-- Squashed baseline.
--
-- This file replaces the V1..V308 migration chain, which had grown to 293
-- files whose only remaining job was to build an empty database up to the
-- schema below. It is generated from a database migrated through that full
-- chain, so it is the same schema the chain produced, object for object.
--
-- Nothing here upgrades an existing database. Any database created before
-- the squash must already be at 308; there is no path forward from an
-- earlier version any more.
--
-- Regenerate after schema changes only if you squash again. Normal changes
-- get a new V309+ migration as usual.

CREATE TABLE pull_requests (
    id                  INTEGER NOT NULL PRIMARY KEY,
    repo                TEXT    NOT NULL,
    number              INTEGER NOT NULL,
    title               TEXT    NOT NULL,
    author              TEXT,
    html_url            TEXT,
    updated_at          TEXT,
    origin              TEXT    NOT NULL,
    labels              TEXT    NOT NULL DEFAULT '[]',
    draft               INTEGER NOT NULL DEFAULT 0,
    synced_at           TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    internal_created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    internal_updated_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
, ci_status TEXT, comment_count INTEGER NOT NULL DEFAULT 0, additions INTEGER NOT NULL DEFAULT 0, deletions INTEGER NOT NULL DEFAULT 0, attention_reason TEXT, created_at TEXT, label_colors TEXT, state VARCHAR, closed_at TEXT, merged_at TEXT, mergeable INTEGER, mergeable_state VARCHAR, head_pushed_at TEXT, reviewer_verdicts TEXT, head_ref TEXT);
CREATE TABLE app_settings (
    key                 TEXT NOT NULL PRIMARY KEY,
    value               TEXT NOT NULL,
    internal_created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    internal_updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE pr_view_state (
    pr_id               INTEGER NOT NULL PRIMARY KEY,
    viewed_at           TEXT,
    snoozed_until       TEXT,
    reviewed_at         TEXT,
    internal_created_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    internal_updated_at TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
, handled_action TEXT, snoozed_at         TEXT, snooze_wake_reason TEXT);
CREATE TABLE watched_repos (
    id            INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    owner         TEXT    NOT NULL,
    repo          TEXT    NOT NULL,
    display_order INTEGER NOT NULL DEFAULT 0,
    added_at      TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP, local_clone_path TEXT, upstream_remote_name TEXT, view_focus TEXT,
    UNIQUE(owner, repo)
);
CREATE TABLE pr_detail (
    pr_id                    INTEGER NOT NULL PRIMARY KEY,
    body                     TEXT,
    labels                   TEXT    NOT NULL DEFAULT '[]',
    draft                    INTEGER NOT NULL DEFAULT 0,
    mergeable                INTEGER,
    mergeable_state          TEXT,
    additions                INTEGER NOT NULL DEFAULT 0,
    deletions                INTEGER NOT NULL DEFAULT 0,
    changed_files            INTEGER NOT NULL DEFAULT 0,
    requested_reviewer_count INTEGER NOT NULL DEFAULT 0,
    head_sha                 TEXT,
    synced_at                TEXT    NOT NULL
, head_ref  TEXT, head_repo TEXT, base_ref  TEXT, base_repo TEXT, requested_reviewers TEXT, merge_queue_state TEXT, state TEXT, merged INTEGER NOT NULL DEFAULT 0, merge_queue_enabled BOOLEAN, base_sha TEXT, merge_commit_sha TEXT);
CREATE TABLE pr_reviews (
    id      INTEGER NOT NULL PRIMARY KEY,
    pr_id   INTEGER NOT NULL,
    login   TEXT    NOT NULL,
    state   TEXT    NOT NULL
, submitted_at TIMESTAMP);
CREATE TABLE pr_files (
    id        INTEGER NOT NULL PRIMARY KEY,
    pr_id     INTEGER NOT NULL,
    filename  TEXT    NOT NULL,
    additions INTEGER NOT NULL DEFAULT 0,
    deletions INTEGER NOT NULL DEFAULT 0,
    status    TEXT
);
CREATE TABLE pr_timeline (
    id        INTEGER NOT NULL PRIMARY KEY,
    pr_id     INTEGER NOT NULL,
    event     TEXT,
    actor     TEXT,
    state     TEXT,
    timestamp TEXT
, body TEXT, before_sha TEXT, after_sha  TEXT, requested_reviewer TEXT, review_id INTEGER, github_id INTEGER, author_association VARCHAR, reactions_plus_one  INTEGER NOT NULL DEFAULT 0, reactions_minus_one INTEGER NOT NULL DEFAULT 0, reactions_laugh     INTEGER NOT NULL DEFAULT 0, reactions_hooray    INTEGER NOT NULL DEFAULT 0, reactions_confused  INTEGER NOT NULL DEFAULT 0, reactions_heart     INTEGER NOT NULL DEFAULT 0, reactions_rocket    INTEGER NOT NULL DEFAULT 0, reactions_eyes      INTEGER NOT NULL DEFAULT 0, label_name TEXT, label_color TEXT, milestone_title TEXT, assignee_login TEXT, cross_ref_number INTEGER, cross_ref_title TEXT, cross_ref_url TEXT, cross_ref_is_pull_request INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pr_check_runs (
    id         INTEGER NOT NULL PRIMARY KEY,
    pr_id      INTEGER NOT NULL,
    status     TEXT,
    conclusion TEXT
, name TEXT, html_url TEXT, output_title TEXT, output_summary TEXT, github_id INTEGER);
CREATE TABLE pr_review_draft (
    id            INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    pr_id         INTEGER NOT NULL,
    summary       TEXT,
    provider_id   TEXT    NOT NULL,
    model         TEXT    NOT NULL,
    head_sha      TEXT,
    status        TEXT    NOT NULL DEFAULT 'COMPLETE',
    created_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
, repo TEXT, pr_number INTEGER, unified_pr_id TEXT);
CREATE INDEX pr_review_draft_pr_id_idx ON pr_review_draft(pr_id);
CREATE TABLE pr_review_comment (
    id           INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    draft_id     INTEGER NOT NULL,
    file_path    TEXT    NOT NULL,
    line_number  INTEGER NOT NULL,
    body         TEXT    NOT NULL,
    severity     TEXT    NOT NULL DEFAULT 'suggestion',
    created_at   TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP, edited_body TEXT, dismissed INTEGER NOT NULL DEFAULT 0, source VARCHAR(16) NOT NULL DEFAULT 'AI', side VARCHAR(8) NOT NULL DEFAULT 'RIGHT', start_line INTEGER, start_side VARCHAR(8),
    FOREIGN KEY (draft_id) REFERENCES pr_review_draft(id) ON DELETE CASCADE
);
CREATE INDEX pr_review_comment_draft_id_idx ON pr_review_comment(draft_id);
CREATE TABLE "credentials" (
    id            INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    type          TEXT    NOT NULL,
    name          TEXT    NOT NULL,
    label         TEXT,
    ciphertext    TEXT    NOT NULL,
    preview       TEXT    NOT NULL,
    notes         TEXT,
    created_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at  TEXT
, instance_name TEXT NOT NULL DEFAULT 'default api', is_default INTEGER NOT NULL DEFAULT 0, config_json TEXT);
CREATE TABLE team (
    id          INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    name        TEXT    NOT NULL UNIQUE,
    -- 2-letter avatar prefix shown on cards / headers (e.g. "TR" for Trino).
    avatar      TEXT    NOT NULL,
    -- One of "purple" | "green" | "orange" — keyed in CSS, not free-form.
    color       TEXT    NOT NULL DEFAULT 'purple',
    created_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
, description TEXT);
CREATE TABLE team_member (
    team_id     INTEGER NOT NULL,
    login       TEXT    NOT NULL,
    added_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (team_id, login),
    FOREIGN KEY (team_id) REFERENCES team(id) ON DELETE CASCADE
);
CREATE INDEX idx_team_member_login ON team_member(login);
CREATE UNIQUE INDEX uq_team_name_nocase ON team(name COLLATE NOCASE);
CREATE UNIQUE INDEX uq_credentials_type_name_instance ON credentials(type, name, instance_name);
CREATE TABLE pr_review_thread_message (
    id              INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    pr_id           INTEGER NOT NULL,
    github_id       INTEGER NOT NULL,
    in_reply_to     INTEGER,
    review_id       INTEGER,
    author          TEXT,
    body            TEXT,
    file_path       TEXT,
    line_number     INTEGER,
    side            TEXT,
    diff_hunk       TEXT,
    commit_id       TEXT,
    created_at      TEXT, reactions_plus_one INTEGER NOT NULL DEFAULT 0, reactions_minus_one INTEGER NOT NULL DEFAULT 0, reactions_laugh INTEGER NOT NULL DEFAULT 0, reactions_hooray INTEGER NOT NULL DEFAULT 0, reactions_confused INTEGER NOT NULL DEFAULT 0, reactions_heart INTEGER NOT NULL DEFAULT 0, reactions_rocket INTEGER NOT NULL DEFAULT 0, reactions_eyes INTEGER NOT NULL DEFAULT 0, outdated INTEGER NOT NULL DEFAULT 0, start_line INTEGER, start_side VARCHAR, author_association VARCHAR, graphql_node_id VARCHAR, resolved BOOLEAN, original_line       INTEGER, original_start_line INTEGER, resolved_by VARCHAR,
    UNIQUE (pr_id, github_id)
);
CREATE INDEX pr_review_thread_message_pr_id_idx ON pr_review_thread_message(pr_id);
CREATE TABLE pr_linked_issue (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    pr_id INTEGER NOT NULL,
    issue_number INTEGER NOT NULL,
    title TEXT NOT NULL,
    state TEXT NOT NULL,
    html_url TEXT NOT NULL
);
CREATE INDEX idx_pr_linked_issue_pr_id ON pr_linked_issue(pr_id);
CREATE UNIQUE INDEX pr_timeline_pr_github_id_uniq
    ON pr_timeline(pr_id, github_id)
    WHERE github_id IS NOT NULL;
CREATE TABLE repo_meta (
    owner               TEXT    NOT NULL,
    repo                TEXT    NOT NULL,
    full_name           TEXT    NOT NULL,
    html_url            TEXT    NOT NULL,
    description         TEXT,
    default_branch      TEXT,
    license             TEXT,
    stargazers_count    INTEGER NOT NULL,
    forks_count         INTEGER NOT NULL,
    watchers_count      INTEGER NOT NULL,
    open_issues_count   INTEGER NOT NULL,
    size_kb             INTEGER NOT NULL,
    -- ISO-8601 instants (TEXT for SQLite parity with the rest of the
    -- schema, where InstantToTextConverter handles round-tripping).
    created_at          TEXT,
    pushed_at           TEXT,
    -- topics: JSON array of strings; languages: JSON object
    -- (language → byte count). Stored as TEXT, decoded by the JPA
    -- converters on read.
    topics              TEXT    NOT NULL DEFAULT '[]',
    languages           TEXT    NOT NULL DEFAULT '{}',
    synced_at           TEXT    NOT NULL, owner_avatar_url TEXT, parent_owner          TEXT, parent_repo           TEXT, parent_default_branch TEXT,
    PRIMARY KEY (owner, repo)
);
CREATE TABLE github_user_profile_cache (
    login       TEXT NOT NULL PRIMARY KEY,
    payload     TEXT NOT NULL,
    fetched_at  TEXT NOT NULL
);
CREATE TABLE github_user_event_cache (
    login       TEXT NOT NULL,
    feed        TEXT NOT NULL,
    payload     TEXT NOT NULL,
    fetched_at  TEXT NOT NULL,
    PRIMARY KEY (login, feed)
);
CREATE TABLE github_user_stats_cache (
    login       TEXT NOT NULL PRIMARY KEY,
    payload     TEXT NOT NULL,
    fetched_at  TEXT NOT NULL
);
CREATE TABLE github_user_orgs_cache (
    login       TEXT NOT NULL PRIMARY KEY,
    payload     TEXT NOT NULL,
    fetched_at  TEXT NOT NULL
);
CREATE TABLE email_messages (
    account_email     TEXT    NOT NULL,
    gmail_message_id  TEXT    NOT NULL,
    gmail_thread_id   TEXT    NOT NULL,
    from_addr         TEXT,
    subject           TEXT,
    snippet           TEXT,
    received_at_ms    INTEGER NOT NULL,
    is_unread         INTEGER NOT NULL DEFAULT 0,
    is_in_inbox       INTEGER NOT NULL DEFAULT 1,
    cached_at_ms      INTEGER NOT NULL,
    PRIMARY KEY (account_email, gmail_message_id)
);
CREATE INDEX idx_email_messages_inbox
    ON email_messages(account_email, is_in_inbox, received_at_ms DESC);
CREATE INDEX idx_email_messages_thread
    ON email_messages(account_email, gmail_thread_id);
CREATE TABLE email_account_sync (
    account_email    TEXT NOT NULL PRIMARY KEY,
    last_history_id  TEXT,
    last_sync_at_ms  INTEGER
);
CREATE TABLE email_muted_senders (
    account_email  TEXT    NOT NULL,
    sender_email   TEXT    NOT NULL,
    muted_at_ms    INTEGER NOT NULL,
    PRIMARY KEY (account_email, sender_email)
);
CREATE INDEX idx_email_muted_senders_account
    ON email_muted_senders(account_email);
CREATE INDEX idx_pr_reviews_login_submitted_at
    ON pr_reviews(login, submitted_at);
CREATE TABLE "threads" (
    id                TEXT    PRIMARY KEY,
    kind              TEXT    NOT NULL,             -- 'CLI_AGENT' | 'LOGIC_LOOP'
    provider          TEXT    NOT NULL,             -- 'claude-code' | 'codex' | 'deepseek-review' | ...
    agent_session_id  TEXT,                         -- cli_agent: CLI's session id for --resume; logic_loop: NULL
    title             TEXT    NOT NULL,             -- first user prompt, truncated for the list view
    status            TEXT    NOT NULL,             -- 'PENDING' | 'RUNNING' | 'AWAITING' | 'IDLE' | 'COMPLETED' | 'ERRORED'
    model             TEXT    NOT NULL,             -- e.g. 'claude-sonnet-4.6'
    cost_usd_milli    INTEGER NOT NULL DEFAULT 0,   -- USD × 1000
    tokens_in         INTEGER NOT NULL DEFAULT 0,
    tokens_out        INTEGER NOT NULL DEFAULT 0,
    created_at_ms     INTEGER NOT NULL,
    updated_at_ms     INTEGER NOT NULL,
    ended_at_ms       INTEGER,
    error_message     TEXT,
    group_id TEXT REFERENCES "thread_groups"(id), workspace_id TEXT REFERENCES workspaces(id), flow TEXT NOT NULL DEFAULT 'build', work_model_json TEXT NULL, parent_review_pass_id TEXT, parallel_slots INTEGER NOT NULL DEFAULT 1, parent_task_id TEXT, planning_repo_root TEXT, planning_base_sha TEXT, pr_ref TEXT, description TEXT, turn_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (turn_version IN ('LEGACY', 'V2')), lifecycle_state TEXT, aggregate_version INTEGER NOT NULL DEFAULT 0
    CHECK (aggregate_version >= 0));
CREATE TABLE "thread_messages" (
    id              TEXT    PRIMARY KEY,
    thread_id         TEXT    NOT NULL REFERENCES "threads"(id) ON DELETE CASCADE,
    seq             INTEGER NOT NULL,             -- monotonically increasing within a task; lets us ORDER BY without timestamps
    role            TEXT    NOT NULL,             -- 'user' | 'assistant' | 'tool' | 'system'
    type            TEXT    NOT NULL,             -- 'text' | 'tool_call' | 'tool_result' | 'thinking' | 'permission_request' | 'error'
    content_json    TEXT    NOT NULL,             -- shape varies by type
    duration_ms     INTEGER,                      -- present for tool_call / tool_result rows
    tokens_in       INTEGER,
    tokens_out      INTEGER,
    cost_usd_milli  INTEGER,
    ts_ms           INTEGER NOT NULL, task_id TEXT REFERENCES tasks(id), stage_id TEXT, scope TEXT,
    UNIQUE(thread_id, seq)
);
CREATE TABLE "thread_groups" (
    id              TEXT    NOT NULL PRIMARY KEY,
    name            TEXT    NOT NULL,
    -- Single-character (or short) display glyph rendered in the
    -- left-rail badge. Free-form so users can paste an emoji.
    glyph           TEXT    NOT NULL DEFAULT '•',
    -- CSS-compatible color string for the glyph background. Free-form
    -- so we don't have to migrate every time we add a swatch.
    color           TEXT    NOT NULL DEFAULT 'slate',
    sort_order      INTEGER NOT NULL DEFAULT 0,
    created_at_ms   INTEGER NOT NULL,
    updated_at_ms   INTEGER NOT NULL
);
CREATE TABLE email_tags (
    id                  TEXT    NOT NULL PRIMARY KEY,
    account_email       TEXT    NOT NULL,
    name                TEXT    NOT NULL,
    subject_contains    TEXT    NOT NULL,
    action              TEXT    NOT NULL CHECK (action IN ('FOCUS', 'ARCHIVE', 'IGNORE')),
    created_at_ms       INTEGER NOT NULL,
    updated_at_ms       INTEGER NOT NULL
);
CREATE INDEX idx_email_tags_account
    ON email_tags(account_email);
CREATE TABLE "thread_group_members" (
    thread_id     TEXT    NOT NULL REFERENCES "threads"(id) ON DELETE CASCADE,
    group_id    TEXT    NOT NULL REFERENCES "thread_groups"(id) ON DELETE CASCADE,
    added_at_ms INTEGER NOT NULL,
    PRIMARY KEY (thread_id, group_id)
);
CREATE TABLE "email_tag_archive_log" (
    account_email       TEXT    NOT NULL,
    gmail_thread_id     TEXT    NOT NULL,
    tag_id              TEXT,
    subject             TEXT,
    from_addr           TEXT,
    snippet             TEXT,
    received_at_ms      INTEGER NOT NULL,
    archived_at_ms      INTEGER NOT NULL,
    PRIMARY KEY (account_email, gmail_thread_id)
);
CREATE INDEX idx_email_tag_archive_log_account_archived
    ON email_tag_archive_log(account_email, archived_at_ms DESC);
CREATE TABLE "thread_turns" (
    id TEXT PRIMARY KEY,
    thread_id TEXT NOT NULL,
    lane TEXT NOT NULL,
    status TEXT NOT NULL,
    input TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL,
    updated_at_ms INTEGER NOT NULL,
    started_at_ms INTEGER,
    finished_at_ms INTEGER,
    error_message TEXT, task_id TEXT REFERENCES tasks(id), initiator_attended INTEGER NOT NULL DEFAULT 1, initiator_source TEXT NOT NULL DEFAULT 'user', stage_id TEXT, scope TEXT, agent_run_id TEXT, affects_task_liveness INTEGER NOT NULL DEFAULT 0, kick_key TEXT,
    FOREIGN KEY (thread_id) REFERENCES "threads"(id) ON DELETE CASCADE
);
CREATE TABLE "thread_turn_events" (
    id TEXT PRIMARY KEY,
    turn_id TEXT NOT NULL,
    thread_id TEXT NOT NULL,
    event TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL,
    message TEXT, task_id TEXT REFERENCES tasks(id), is_summary INTEGER NOT NULL DEFAULT 0, stage_id TEXT,
    FOREIGN KEY (turn_id) REFERENCES "thread_turns"(id) ON DELETE CASCADE,
    FOREIGN KEY (thread_id) REFERENCES "threads"(id) ON DELETE CASCADE
);
CREATE TABLE "thread_checkpoints" (
    id                  TEXT    PRIMARY KEY,
    thread_id             TEXT    NOT NULL REFERENCES "threads"(id) ON DELETE CASCADE,

    -- Per-segment identity. seq=0 is reserved for the Overall
    -- rollup; per-segment checkpoints start at 1.
    seq                 INTEGER NOT NULL,
    is_overall          INTEGER NOT NULL DEFAULT 0,

    -- Inclusive turn coverage. For Overall, last_msg_seq is the
    -- task's max seq at the moment it was generated.
    first_msg_seq       INTEGER NOT NULL,
    last_msg_seq        INTEGER NOT NULL,
    tokens_covered      INTEGER NOT NULL,

    -- Summary content. summary_md is Markdown; bullet_titles is a
    -- JSON array of 1-3 short bullets the UI uses for the rail
    -- preview without parsing the full Markdown.
    summary_md          TEXT    NOT NULL,
    bullet_titles       TEXT    NOT NULL DEFAULT '[]',

    -- Audit / provenance.
    model_used          TEXT    NOT NULL,
    prompt_tokens       INTEGER NOT NULL,
    completion_tokens   INTEGER NOT NULL,
    cost_usd_milli      INTEGER NOT NULL,
    generated_at_ms     INTEGER NOT NULL,

    -- Set on Overall rows when a newer Overall replaces them; the
    -- prior rows stay for history (cheap, gives time-travel via
    --   SELECT ... WHERE is_overall=1 ORDER BY generated_at_ms).
    superseded_at_ms    INTEGER, task_id TEXT REFERENCES tasks(id) ON DELETE CASCADE,

    UNIQUE(thread_id, seq)
);
CREATE INDEX idx_threads_status_updated
    ON threads(status, updated_at_ms DESC);
CREATE INDEX idx_threads_group_id
    ON threads(group_id);
CREATE INDEX idx_thread_messages_thread_seq
    ON thread_messages(thread_id, seq);
CREATE INDEX idx_thread_group_members_group_id
    ON thread_group_members(group_id);
CREATE INDEX idx_thread_group_members_thread_id
    ON thread_group_members(thread_id);
CREATE INDEX idx_thread_turns_status_created_id
    ON thread_turns(status, created_at_ms, id);
CREATE INDEX idx_thread_turns_thread_status_created_id_desc
    ON thread_turns(thread_id, status, created_at_ms DESC, id DESC);
CREATE INDEX idx_thread_turns_thread_created_id_desc
    ON thread_turns(thread_id, created_at_ms DESC, id DESC);
CREATE INDEX idx_thread_turn_events_turn_created
    ON thread_turn_events(turn_id, created_at_ms);
CREATE INDEX idx_thread_turn_events_thread_created_id_desc
    ON thread_turn_events(thread_id, created_at_ms DESC, id DESC);
CREATE INDEX idx_thread_checkpoints_thread_seq
    ON thread_checkpoints(thread_id, is_overall DESC, seq DESC);
CREATE INDEX idx_thread_checkpoints_thread_active
    ON thread_checkpoints(thread_id, superseded_at_ms);
CREATE TABLE tasks (
    id                  TEXT    PRIMARY KEY,
    thread_id           TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    seq                 INTEGER NOT NULL,            -- 1, 2, 3... within the thread
    status              TEXT    NOT NULL,            -- PENDING|RUNNING|AWAITING|IDLE|COMPLETED|ERRORED

    -- Where the agent runs (per-task; absent for the future 0-Task case).
    branch_name         TEXT,                        -- e.g. dev/<task-id>-<slug>
    worktree_path       TEXT,                        -- <repo>/.worktrees/<task-id>
    base_branch         TEXT,                        -- 'main' / 'upstream/master' / the stacked-on branch
    working_dir         TEXT,                        -- repo root the worktree was cut from

    -- Per-execution state (transient — cleared when the agent stops).
    process_pid         INTEGER,                     -- CLI subprocess pid
    log_path            TEXT,                        -- CLI's JSONL log for THIS spawn

    -- GitHub linkage.
    pr_number           INTEGER,
    pr_state            TEXT,
    ci_state            TEXT,
    task_type           TEXT    NOT NULL DEFAULT 'DEVELOP',
    linked_pr_number    INTEGER,
    linked_issue_number INTEGER,

    -- Per-task spend (threads keep their own running rollup).
    cost_usd_milli      INTEGER NOT NULL DEFAULT 0,
    tokens_in           INTEGER NOT NULL DEFAULT 0,
    tokens_out          INTEGER NOT NULL DEFAULT 0,

    -- Inclusive thread_messages.seq range that this task covers, so the
    -- conversation can be sliced per task in the UI.
    created_at_ms       INTEGER NOT NULL,
    ended_at_ms         INTEGER,
    error_message       TEXT, agent_session_id TEXT, name TEXT, role_skill TEXT, work_model_json TEXT NULL, pushed_at_ms BIGINT, phase TEXT NOT NULL DEFAULT 'IMPLEMENTING', agenda_json TEXT, consecutive_auto_pushes INTEGER NOT NULL DEFAULT 0, linked_pr_ref TEXT, opening_prompt TEXT, merge_notification_sent_at_ms INTEGER, ready_gate_sent_at_ms INTEGER, merge_authorized_at_ms INTEGER, merge_queue_retries INTEGER NOT NULL DEFAULT 0, auto_approve INTEGER NOT NULL DEFAULT 0, min_approvals INTEGER NOT NULL DEFAULT 0, pending_completion_summary_turn_id TEXT, auto_merge INTEGER NOT NULL DEFAULT 0, origin TEXT NOT NULL DEFAULT 'user', paused_status TEXT, recovery_phase TEXT, recovery_context_json TEXT, resume_requested_at_ms INTEGER, recovery_request_id TEXT, recovery_requested_kind TEXT, recovery_request_payload_json TEXT, recovery_requested_at_ms INTEGER, legacy_recovery_kind TEXT, legacy_recovery_requested_at_ms INTEGER, current_liveness_turn_id TEXT, workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), epoch INTEGER NOT NULL DEFAULT 1 CHECK (epoch >= 1), aggregate_version INTEGER NOT NULL DEFAULT 0
    CHECK (aggregate_version >= 0), lifecycle_state TEXT, assignment_id TEXT REFERENCES task_assignment(id), policy_revision_id TEXT REFERENCES task_policy_revision(id), creation_receipt_id TEXT
    REFERENCES task_creation_receipt(id) DEFERRABLE INITIALLY DEFERRED,

    UNIQUE (thread_id, seq)
);
CREATE INDEX idx_tasks_thread_seq ON tasks(thread_id, seq);
CREATE INDEX idx_tasks_status     ON tasks(status);
CREATE INDEX idx_tasks_pr_number  ON tasks(pr_number);
CREATE TABLE task_files (
    task_id         TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    path            TEXT    NOT NULL,
    operation       TEXT    NOT NULL,                -- 'read' | 'write' | 'edit' | 'delete'
    count           INTEGER NOT NULL DEFAULT 1,
    lines_added     INTEGER NOT NULL DEFAULT 0,
    lines_removed   INTEGER NOT NULL DEFAULT 0,
    last_touched_ms INTEGER NOT NULL,
    PRIMARY KEY (task_id, path)
);
CREATE TABLE workspaces (
    id              TEXT    PRIMARY KEY,
    name            TEXT    NOT NULL,
    -- WORKSPACE.md content the app maintains in-DB. Loaded into every
    -- thread's system context; size-bounded to ~2k tokens target /
    -- ~4k cap by the service layer. Seeded blank — the distillation
    -- pass populates it over time as threads close.
    memory_md       TEXT    NOT NULL DEFAULT '',
    -- Scratch workspaces accrue no durable memory and never propose
    -- distillation upward. The default workspace is not scratch.
    is_scratch      INTEGER NOT NULL DEFAULT 0,
    created_at_ms   INTEGER NOT NULL,
    updated_at_ms   INTEGER NOT NULL
, work_model_json TEXT NULL, detached_at_ms INTEGER);
CREATE TABLE workspace_repos (
    workspace_id        TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo_full_name      TEXT NOT NULL,
    default_base_branch TEXT,
    added_at_ms         INTEGER NOT NULL, auto_fix_enabled INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (workspace_id, repo_full_name)
);
CREATE INDEX idx_workspace_repos_repo ON workspace_repos(repo_full_name);
CREATE INDEX idx_threads_workspace_id ON threads(workspace_id);
CREATE TABLE worktree_leases (
    -- The worktree directory is the resource being leased; PK is the
    -- path so duplicate acquires are a constraint violation rather
    -- than an application-side race.
    worktree_path   TEXT NOT NULL PRIMARY KEY,
    task_id         TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    -- 'CLI_AGENT' | 'LOGIC_LOOP' — matches the existing thread kinds.
    agent_kind      TEXT NOT NULL,
    -- OS pid for CLI agents; null for LOGIC_LOOP (the loop runs in
    -- the JVM and has no separate process to identify).
    holder_pid      INTEGER,
    acquired_at_ms  INTEGER NOT NULL,
    -- Soft expiry so a crashed holder can be reaped after a timeout.
    -- The reaper sweeps rows whose expires_at_ms < now and whose
    -- holder_pid no longer corresponds to a live process.
    expires_at_ms   INTEGER
, workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), operation_id TEXT, task_epoch INTEGER, fencing_token INTEGER, lease_owner TEXT);
CREATE INDEX idx_worktree_leases_task ON worktree_leases(task_id);
CREATE TABLE notifications (
    id              TEXT NOT NULL PRIMARY KEY,
    -- 'AWAITING_REVIEW' | 'NEEDS_ATTENTION' | 'AUTO_FIX_DONE' | ...
    -- Stored as TEXT so adding kinds later doesn't need a migration.
    kind            TEXT NOT NULL,
    -- Pointer back to the conversation that produced the event.
    thread_id       TEXT REFERENCES threads(id) ON DELETE CASCADE,
    -- Pointer at the work-unit (the one parked). Nullable so a
    -- thread-level notification (e.g. "ship-and-continue succeeded")
    -- can stand without a specific task.
    task_id         TEXT REFERENCES tasks(id) ON DELETE CASCADE,
    -- 'UNREAD' | 'READ' | 'DISMISSED' — the runtime sets UNREAD, the
    -- UI patches to READ on click and DISMISSED on swipe-away.
    status          TEXT NOT NULL DEFAULT 'UNREAD',
    -- Free-form JSON1 blob (title, body, PR number, etc.) so a kind
    -- can carry its own payload without growing the schema.
    payload_json    TEXT NOT NULL DEFAULT '{}',
    created_at_ms   INTEGER NOT NULL,
    read_at_ms      INTEGER
, workspace_id TEXT REFERENCES workspaces(id), public_type TEXT, title TEXT, summary TEXT, item_path TEXT, dedup_key TEXT);
CREATE INDEX idx_notifications_status_created
    ON notifications(status, created_at_ms DESC);
CREATE INDEX idx_notifications_thread
    ON notifications(thread_id, created_at_ms DESC);
CREATE INDEX idx_notifications_task
    ON notifications(task_id, created_at_ms DESC);
CREATE INDEX idx_thread_checkpoints_task ON thread_checkpoints(task_id);
CREATE TABLE workspace_memory_proposals (
    workspace_id        TEXT    PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
    current_md          TEXT    NOT NULL,
    proposed_md         TEXT    NOT NULL,
    summariser_model    TEXT    NOT NULL,
    prompt_tokens       INTEGER NOT NULL DEFAULT 0,
    completion_tokens   INTEGER NOT NULL DEFAULT 0,
    cost_usd_milli      INTEGER NOT NULL DEFAULT 0,
    created_at_ms       INTEGER NOT NULL
);
CREATE TABLE review_passes (
    id              TEXT    PRIMARY KEY,
    thread_id       TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    repo_full_name  TEXT    NOT NULL,
    pr_number       INTEGER NOT NULL,
    -- Commit reviewed so a later run can detect "the PR has been
    -- updated since this review". Null while the kickoff fetch is
    -- still in flight.
    head_sha        TEXT,
    -- KICKOFF | INDEPENDENT | CROSS_REVIEW | CONSENSUS | DEBATE
    -- | TERMINATE | ARBITRATE | PUBLISHED
    phase           TEXT    NOT NULL,
    round           INTEGER NOT NULL DEFAULT 0,
    round_cap       INTEGER NOT NULL DEFAULT 3,
    cost_cap_milli  INTEGER NOT NULL DEFAULT 500,
    cost_usd_milli  INTEGER NOT NULL DEFAULT 0,
    -- approve | request_changes | comment; null until the user confirms
    -- a suggested verdict via the publish gate.
    verdict         TEXT,
    created_at_ms   INTEGER NOT NULL,
    ended_at_ms     INTEGER
, spawned_build_thread_id TEXT, agenda_json TEXT, host_kind TEXT NOT NULL DEFAULT 'THREAD', host_id   TEXT NOT NULL DEFAULT '', kind      TEXT NOT NULL DEFAULT 'FRESH', task_stage_id TEXT, base_repository_id TEXT, head_repository_id TEXT, head_ref TEXT);
CREATE INDEX idx_review_passes_thread     ON review_passes(thread_id);
CREATE INDEX idx_review_passes_repo_pr    ON review_passes(repo_full_name, pr_number);
CREATE TABLE review_participants (
    id              TEXT    PRIMARY KEY,
    review_pass_id  TEXT    NOT NULL REFERENCES review_passes(id) ON DELETE CASCADE,
    -- moderator | reviewer | human
    kind            TEXT    NOT NULL,
    -- FK into the AI credentials store (review-role credential).
    -- Null for the moderator + human participants.
    credential_id   TEXT,
    -- Display label: "GPT-5", "Claude", "You", "Moderator".
    persona_label   TEXT    NOT NULL,
    model           TEXT,
    -- Optional hex colour for the persona bubble (panel UI). Null
    -- when the renderer should pick a default for this position.
    color           TEXT,
    created_at_ms   INTEGER NOT NULL
, budget_milli_usd_cap INTEGER, budget_milli_usd_spent INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_review_participants_pass ON review_participants(review_pass_id);
CREATE TABLE review_messages (
    id              TEXT    PRIMARY KEY,
    review_pass_id  TEXT    NOT NULL REFERENCES review_passes(id) ON DELETE CASCADE,
    participant_id  TEXT    NOT NULL REFERENCES review_participants(id),
    -- Same phase token as review_passes.phase; the message snapshots
    -- which phase produced it so a later read can group them.
    phase           TEXT    NOT NULL,
    round           INTEGER NOT NULL,
    body            TEXT    NOT NULL,
    -- JSON array of participant ids the message targets (@mention).
    mentions        TEXT,
    -- JSON array of review_messages ids the message quotes (#ref).
    refs            TEXT,
    cost_usd_milli  INTEGER NOT NULL DEFAULT 0,
    created_at_ms   INTEGER NOT NULL
, payload_kind TEXT, payload_json TEXT);
CREATE INDEX idx_review_messages_pass     ON review_messages(review_pass_id, created_at_ms);
CREATE TABLE review_findings (
    id                  TEXT    PRIMARY KEY,
    review_pass_id      TEXT    NOT NULL REFERENCES review_passes(id) ON DELETE CASCADE,
    -- File path the finding is anchored to. Null for whole-PR
    -- findings (architectural notes, missing-test summaries).
    path                TEXT,
    -- Line number the finding is anchored to. Null when path is
    -- whole-file or when the finding is whole-PR.
    line                INTEGER,
    -- blocker | major | nit | question
    severity            TEXT    NOT NULL,
    -- agreed | disputed | resolved | arbitrated | dropped | posted
    status              TEXT    NOT NULL,
    body                TEXT    NOT NULL,
    -- How a disputed finding was settled (human pick / consensus
    -- statement). Null until the finding goes from disputed →
    -- resolved/arbitrated.
    resolution          TEXT,
    -- GitHub comment id once the finding is posted to the PR.
    posted_comment_id   TEXT,
    created_at_ms       INTEGER NOT NULL
, debate_status TEXT, debate_rounds INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1
    CHECK (revision > 0));
CREATE INDEX idx_review_findings_pass     ON review_findings(review_pass_id);
CREATE INDEX idx_thread_messages_task_seq      ON thread_messages(task_id, seq);
CREATE INDEX idx_thread_turns_task_id          ON thread_turns(task_id);
CREATE INDEX idx_thread_turn_events_task_id    ON thread_turn_events(task_id);
CREATE TABLE thread_settings (
    thread_id            TEXT    PRIMARY KEY REFERENCES threads(id) ON DELETE CASCADE,

    -- Concurrency cap: the per-thread max number of Tasks that may
    -- be RUNNING simultaneously. NULL = inherit. Hard cap — the
    -- scheduler queues over-cap work via its fair-share lanes.
    max_running_tasks    INTEGER,

    -- Two-tier cost budget. soft = warn-and-continue threshold the
    -- UI surfaces as a banner; hard = pause-and-ask ceiling the
    -- scheduler refuses to cross without an explicit OK. NULL = inherit.
    -- Both are milli-USD to match the rest of the cost columns.
    soft_cost_usd_milli  INTEGER,
    hard_cost_usd_milli  INTEGER,

    -- Thread prompt addendum: free-form text concatenated onto the
    -- workspace memory at every CLI / logic-loop spawn. Guidance,
    -- not security — relaxing a guardrail goes through a different
    -- (future) column with explicit flagging.
    prompt_addendum      TEXT,

    updated_at_ms        INTEGER NOT NULL
);
CREATE UNIQUE INDEX uq_credentials_type_name_default
    ON credentials(type, name)
    WHERE is_default = 1;
CREATE TABLE skill (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    scope TEXT NOT NULL CHECK (scope IN ('global', 'repo', 'thread')),
    repo TEXT,
    thread_id TEXT,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    body TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('library', 'persona', 'rubric')),
    role_tag TEXT,
    enabled INTEGER NOT NULL DEFAULT 1,
    is_default INTEGER NOT NULL DEFAULT 0,
    source TEXT NOT NULL DEFAULT 'authored' CHECK (source IN ('authored', 'ai_drafted')),
    provenance TEXT,
    content_hash TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
, usage TEXT NOT NULL DEFAULT 'build');
CREATE INDEX skill_scope_idx ON skill(scope, repo, enabled);
CREATE INDEX skill_role_idx ON skill(role_tag, enabled);
CREATE TABLE skill_asset (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    skill_id INTEGER NOT NULL REFERENCES skill(id) ON DELETE CASCADE,
    filename TEXT NOT NULL,
    content BLOB NOT NULL
);
CREATE INDEX skill_asset_skill_idx ON skill_asset(skill_id);
CREATE TABLE permission_grant (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('global', 'workspace', 'thread', 'task')),
    scope_id TEXT,
    capability TEXT NOT NULL,
    mode TEXT NOT NULL CHECK (mode IN ('allow', 'deny', 'inherit')),
    params_json TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX permission_grant_scope_idx ON permission_grant(scope_kind, scope_id);
CREATE TABLE concept_user (
    name TEXT NOT NULL PRIMARY KEY,
    kind TEXT NOT NULL,
    definition TEXT NOT NULL,
    aka_json TEXT NOT NULL DEFAULT '[]',
    criteria_json TEXT,
    created_at_ms INTEGER NOT NULL,
    updated_at_ms INTEGER NOT NULL
);
CREATE TABLE memory_item (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    scope_kind      TEXT    NOT NULL CHECK (scope_kind IN ('WORKSPACE', 'THREAD')),
    scope_id        TEXT    NOT NULL,
    kind            TEXT    NOT NULL CHECK (kind IN (
                        'DECISION', 'BLOCKER', 'CONVENTION',
                        'FOCUS_SHIFT', 'OPEN_QUESTION', 'RECURRING_PATTERN')),
    text            TEXT    NOT NULL,
    sources_json    TEXT    NOT NULL DEFAULT '[]',
    confidence      TEXT    NOT NULL CHECK (confidence IN ('HIGH', 'MEDIUM', 'LOW')),
    tags_json       TEXT    NOT NULL DEFAULT '[]',
    superseded_by   INTEGER REFERENCES memory_item(id) ON DELETE SET NULL,
    resolved_at_ms  INTEGER,
    proposed_at_ms  INTEGER NOT NULL,
    applied_at_ms   INTEGER,
    source          TEXT    NOT NULL CHECK (source IN ('DISTILL', 'INLINE', 'USER_TYPED'))
);
CREATE INDEX memory_item_scope_kind_idx
    ON memory_item(scope_kind, scope_id, kind, applied_at_ms);
CREATE INDEX memory_item_pending_idx
    ON memory_item(scope_kind, scope_id, applied_at_ms)
    WHERE applied_at_ms IS NULL;
CREATE INDEX threads_parent_review_pass_id_idx
    ON threads(parent_review_pass_id);
CREATE INDEX idx_tasks_phase ON tasks(phase);
CREATE TABLE task_phase_event (
    id                INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    task_id           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    from_phase        TEXT,                       -- null on the first transition
    to_phase          TEXT    NOT NULL,
    transitioned_at_ms INTEGER NOT NULL,
    reason            TEXT,                        -- 'validation_passed', 'human_approved', …
    actor             TEXT                         -- 'agent' | 'human' | 'webhook' | 'scheduler'
);
CREATE INDEX task_phase_event_task_idx ON task_phase_event(task_id, transitioned_at_ms);
CREATE TABLE validation_pass (
    id            INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    task_id       TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    started_at_ms INTEGER NOT NULL,
    ended_at_ms   INTEGER,                  -- null while in flight
    passed        INTEGER,                  -- null until finished; 0 | 1
    fix_rounds    INTEGER NOT NULL DEFAULT 0,
    failures_json TEXT                       -- JSON array of {source, detail}
, claim_key TEXT, context TEXT, round_id TEXT, code_fingerprint TEXT, through_sequence INTEGER, root_set_digest TEXT, cancel_requested_at_ms INTEGER, cancel_deadline_at_ms INTEGER, cancel_attempts INTEGER NOT NULL DEFAULT 0, superseded_at_ms INTEGER, owner_id TEXT, executor_identity TEXT, lease_until_ms INTEGER, heartbeat_at_ms INTEGER, workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), task_epoch INTEGER, stage_id TEXT REFERENCES stage(id), stage_generation INTEGER, operation_id TEXT, semantic_attempt INTEGER, expected_head_sha TEXT, expected_base_sha TEXT);
CREATE INDEX validation_pass_task_idx ON validation_pass(task_id, started_at_ms);
CREATE INDEX review_pass_pr_phase_idx
    ON review_passes(repo_full_name, pr_number, host_kind, phase);
CREATE INDEX review_pass_host_phase_idx
    ON review_passes(host_kind, host_id, phase);
