    linked_task_id  TEXT    REFERENCES tasks(id) ON DELETE SET NULL
, workspace_id TEXT, priority TEXT NOT NULL DEFAULT 'medium', source TEXT NOT NULL DEFAULT 'manual', status TEXT NOT NULL DEFAULT 'created', created_by TEXT NOT NULL DEFAULT 'user', in_progress_at_ms INTEGER, resolved_at_ms INTEGER, rejected_at_ms INTEGER, rejection_reason TEXT, related_backlog_ids_json TEXT NOT NULL DEFAULT '[]', item_key TEXT, summary TEXT NOT NULL DEFAULT '', detail TEXT, impact_risk TEXT, links_json TEXT NOT NULL DEFAULT '[]', origin TEXT NOT NULL DEFAULT 'user'
    CHECK (origin IN ('user', 'agent', 'issue-monitor', 'quality-scan')));
CREATE INDEX idx_backlog_item_thread ON backlog_item(thread_id, created_at_ms);
CREATE TABLE thread_signal (
    id            TEXT    NOT NULL PRIMARY KEY,
    thread_id     TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    task_id       TEXT    REFERENCES tasks(id) ON DELETE SET NULL,
    source_kind   TEXT    NOT NULL CHECK (source_kind IN ('agent', 'system', 'github')),
    icon_kind     TEXT    NOT NULL CHECK (icon_kind IN ('info', 'success', 'warn', 'alert')),
    title         TEXT    NOT NULL,
    body          TEXT,
    source_url    TEXT,
    created_at_ms INTEGER NOT NULL,
    read_at_ms    INTEGER
);
CREATE INDEX idx_thread_signal_thread ON thread_signal(thread_id, created_at_ms);
CREATE TABLE ci_fixing_log_query_marker (
