    opened_at_ms   INTEGER NOT NULL,
    gated_at_ms    INTEGER,                           -- when drafts became ready
    posted_at_ms   INTEGER                            -- when the user approved the gate
, origin TEXT NOT NULL DEFAULT 'external', brain_verdict TEXT, iteration INTEGER NOT NULL DEFAULT 0, budget INTEGER NOT NULL DEFAULT 3, paused_from TEXT, code_fingerprint TEXT, enqueue_failures INTEGER NOT NULL DEFAULT 0, kick_attempt INTEGER NOT NULL DEFAULT 0, gate_revision INTEGER NOT NULL DEFAULT 0, active_gate_token TEXT, closed_at_ms INTEGER, workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), task_epoch INTEGER, stage_id TEXT REFERENCES stage(id), stage_generation INTEGER, operation_id TEXT, semantic_attempt INTEGER, expected_head_sha TEXT, expected_base_sha TEXT);
CREATE INDEX idx_review_round_task ON "response_round"(task_id, opened_at_ms);
CREATE INDEX idx_review_comment_round ON review_comment(round_id);
