CREATE TABLE repo_metadata_cache (
    repo_full_name  TEXT NOT NULL PRIMARY KEY,
    users_json      TEXT NOT NULL,
    labels_json     TEXT NOT NULL,
    fetched_at      TEXT NOT NULL
);
