    ON pr_review_draft(unified_pr_id);
CREATE TABLE workspace_automation_state (
    workspace_id   TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    kind           TEXT NOT NULL,
    cursor         INTEGER,
    last_run_json  TEXT,
    updated_at_ms  INTEGER NOT NULL,
    PRIMARY KEY (workspace_id, kind)
);
CREATE TABLE issue_origin (
    issue_id BIGINT PRIMARY KEY,
    issue_number INTEGER NOT NULL,
    origin TEXT NOT NULL CHECK (origin IN ('user', 'user-report', 'quality-scan'))
);
CREATE TABLE repo_learning_run (
    id                TEXT    NOT NULL PRIMARY KEY,
    workspace_id      TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo              TEXT    NOT NULL,                -- owner/name
    trigger_kind      TEXT    NOT NULL,               -- clone | manual
    state             TEXT    NOT NULL,               -- queued | indexing | cataloging | useful | caught-up | partial | failed
    snapshot_sha      TEXT,                           -- HEAD the doc index/capsule was built against
    catalog_cursor    TEXT,                           -- JSON: merge-date partitions + per-range page cursors
    counts_json       TEXT    NOT NULL DEFAULT '{}',  -- JSON: docsIndexed, cataloged, analyzed, lessons, ...
    extractor_version INTEGER NOT NULL DEFAULT 1,
    started_at_ms     INTEGER NOT NULL,
    updated_at_ms     INTEGER NOT NULL,
    completed_at_ms   INTEGER,
    last_error        TEXT
);
CREATE INDEX idx_repo_learning_run_state
    ON repo_learning_run(state, updated_at_ms);
CREATE UNIQUE INDEX idx_repo_learning_run_live
    ON repo_learning_run(workspace_id, repo)
    WHERE state IN ('queued', 'indexing', 'cataloging');
CREATE TABLE repo_pr_source (
    workspace_id      TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo              TEXT    NOT NULL,
    pr_number         INTEGER NOT NULL,
    merged_at         TEXT,                            -- GitHub ISO-8601; ISO order drives date partitions
    merge_sha         TEXT,
    metadata_json     TEXT    NOT NULL DEFAULT '{}',   -- title, author, labels, base, counts, changed paths...
    completeness_json TEXT    NOT NULL DEFAULT '{}',   -- overall + per-source completeness markers
    source_digest     TEXT,
    priority_score    REAL,                            -- deterministic ranking is a later phase
    analysis_state    TEXT    NOT NULL DEFAULT 'cataloged', -- cataloged | analyzed
    extractor_version INTEGER NOT NULL DEFAULT 1,
    analyzed_at_ms    INTEGER,
    last_error        TEXT,
    PRIMARY KEY (workspace_id, repo, pr_number)
);
CREATE INDEX idx_repo_pr_source_analysis
    ON repo_pr_source(workspace_id, repo, analysis_state);
CREATE TABLE repo_doc_section (
    workspace_id      TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo              TEXT    NOT NULL,
    path              TEXT    NOT NULL,                -- repo-relative document path
    heading_path      TEXT    NOT NULL,               -- "H1 > H2 > H3" trail; "" for the preamble
    line_start        INTEGER NOT NULL,
    line_end          INTEGER NOT NULL,
    content_digest    TEXT    NOT NULL,
    knowledge_type    TEXT,                            -- readme | contributing | architecture | adr | build | config | brief
    tags_json         TEXT    NOT NULL DEFAULT '[]',
    commit_sha        TEXT,
    indexed_at_ms     INTEGER NOT NULL,
    PRIMARY KEY (workspace_id, repo, path, heading_path)
);
CREATE TABLE repo_project_capsule (
    workspace_id      TEXT    NOT NULL PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
    repo              TEXT    NOT NULL,
    capsule_md        TEXT    NOT NULL,
    source_digest     TEXT    NOT NULL,
    generated_at_ms   INTEGER NOT NULL
);
CREATE TABLE repo_pr_evidence_bundle (
    workspace_id         TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo                 TEXT    NOT NULL,
    pr_number            INTEGER NOT NULL,
    base_sha             TEXT,
    head_sha             TEXT,
    merge_sha            TEXT,
    repo_sha             TEXT,                          -- pinned default-branch/checkout snapshot
    overall_completeness TEXT    NOT NULL,              -- complete | partial:<source> | unavailable
    completeness_json    TEXT    NOT NULL DEFAULT '{}', -- per-source markers
    priority_score       REAL,
    extractor_version    INTEGER NOT NULL DEFAULT 1,
    built_at_ms          INTEGER NOT NULL,
    PRIMARY KEY (workspace_id, repo, pr_number)
);
CREATE TABLE repo_pr_evidence_ref (
    id             INTEGER PRIMARY KEY,
    workspace_id   TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo           TEXT    NOT NULL,
    pr_number      INTEGER NOT NULL,
    ref_kind       TEXT    NOT NULL,   -- review | thread | commit | file | symbol | test | timeline
    github_id      TEXT,               -- PR / thread / comment GitHub id
    url            TEXT,
    commit_sha     TEXT,               -- pinned snapshot; never crosses repo_sha
    file_path      TEXT,
    line_start     INTEGER,
    line_end       INTEGER,
    content_digest TEXT,
    detail_json    TEXT    NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_repo_pr_evidence_ref_pr
    ON repo_pr_evidence_ref(workspace_id, repo, pr_number);
CREATE TABLE repo_pr_evidence_outcome_chain (
    id                  INTEGER PRIMARY KEY,
    workspace_id        TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo                TEXT    NOT NULL,
    pr_number           INTEGER NOT NULL,
    concern_author      TEXT,
    concern_path        TEXT,
    concern_ref         TEXT,               -- stable ref (root comment id)
    addressed_by_commit TEXT,               -- author follow-up commit SHA
    resolved            INTEGER NOT NULL DEFAULT 0,
    merged              INTEGER NOT NULL DEFAULT 0,
    depth               INTEGER NOT NULL DEFAULT 0,
    content_digest      TEXT,
    detail_json         TEXT    NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_repo_pr_evidence_chain_pr
    ON repo_pr_evidence_outcome_chain(workspace_id, repo, pr_number);
CREATE UNIQUE INDEX idx_backlog_item_linked_task
    ON backlog_item(linked_task_id)
    WHERE linked_task_id IS NOT NULL;
CREATE TABLE workspace_relation (
    workspace_id                TEXT PRIMARY KEY
                                REFERENCES workspaces(id) ON DELETE CASCADE,
    upstream_workspace_id       TEXT NOT NULL
                                REFERENCES workspaces(id) ON DELETE CASCADE,
    commits_enabled             INTEGER NOT NULL DEFAULT 1
                                CHECK (commits_enabled IN (0, 1)),
    tags_enabled                INTEGER NOT NULL DEFAULT 1
                                CHECK (tags_enabled IN (0, 1)),
    last_fetched_at_ms          INTEGER,
    auto_fetch_interval_minutes INTEGER NOT NULL DEFAULT 15
                                CHECK (auto_fetch_interval_minutes BETWEEN 1 AND 1440),
    indexed_commit_count        INTEGER NOT NULL DEFAULT 0
                                CHECK (indexed_commit_count >= 0),
    created_at_ms               INTEGER NOT NULL,
    updated_at_ms               INTEGER NOT NULL,
    CHECK (workspace_id <> upstream_workspace_id)
);
CREATE INDEX idx_workspace_relation_upstream
    ON workspace_relation(upstream_workspace_id);
CREATE TABLE upstream_cherry_pick_job (
