CREATE TABLE ci_harness_cycle (
    id                    TEXT    NOT NULL PRIMARY KEY,
    watch_id              TEXT    NOT NULL REFERENCES ci_harness_watch(id) ON DELETE CASCADE,
    ordinal               INTEGER NOT NULL,
    trigger_kind          TEXT    NOT NULL,
    steering_text         TEXT CHECK (steering_text IS NULL OR length(steering_text) <= 4000),
    status                TEXT    NOT NULL,
    phase                 TEXT    NOT NULL,
    head_sha              TEXT,
    run_ref               TEXT,
    cost_milli_usd        INTEGER NOT NULL DEFAULT 0,
    backup_ref            TEXT,
    original_head         TEXT,
    net_neutral_proof_json TEXT,
    run_status_tail       TEXT,
    started_at_ms         INTEGER NOT NULL,
    updated_at_ms         INTEGER NOT NULL,
    finished_at_ms        INTEGER,
    error_message         TEXT,
    UNIQUE(watch_id, ordinal)
);
CREATE UNIQUE INDEX idx_ci_harness_cycle_live
    ON ci_harness_cycle(watch_id)
    WHERE status IN ('queued', 'running');
CREATE INDEX idx_ci_harness_cycle_watch_started
    ON ci_harness_cycle(watch_id, started_at_ms DESC);
CREATE TABLE ci_harness_failure (
    id                    TEXT    NOT NULL PRIMARY KEY,
    cycle_id              TEXT    NOT NULL REFERENCES ci_harness_cycle(id) ON DELETE CASCADE,
    run_id                TEXT,
    check_run_id          INTEGER,
    job_name              TEXT    NOT NULL,
    module                TEXT    NOT NULL,
    test_class            TEXT,
    test_method           TEXT,
    signature             TEXT    NOT NULL,
    log_excerpt           TEXT    NOT NULL,
    bucket                TEXT    NOT NULL,
    rule_id               TEXT,
    status                TEXT    NOT NULL,
    target_subject        TEXT,
    diagnosis_json        TEXT,
    fix_json              TEXT,
    verification_json     TEXT,
    created_at_ms         INTEGER NOT NULL,
    updated_at_ms         INTEGER NOT NULL,
    UNIQUE(cycle_id, job_name, signature)
);
CREATE INDEX idx_ci_harness_failure_cycle
    ON ci_harness_failure(cycle_id, created_at_ms);
CREATE INDEX idx_ci_harness_failure_signature
    ON ci_harness_failure(signature);
CREATE TABLE ci_harness_rule (
    id                    TEXT    NOT NULL PRIMARY KEY,
    workspace_id          TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    owner                 TEXT    NOT NULL,
    repo                  TEXT    NOT NULL,
    matcher_pattern       TEXT    NOT NULL,
    scope                 TEXT,
    bucket                TEXT    NOT NULL,
    binding               TEXT    NOT NULL,
    recipe_json           TEXT,
    status                TEXT    NOT NULL,
    origin                TEXT    NOT NULL,
    priority              INTEGER NOT NULL,
    evidence_json         TEXT    NOT NULL DEFAULT '[]',
    hits                  INTEGER NOT NULL DEFAULT 0,
    created_at_ms         INTEGER NOT NULL,
    updated_at_ms         INTEGER NOT NULL,
    approved_at_ms        INTEGER,
    UNIQUE(workspace_id, owner, repo, matcher_pattern, scope)
);
CREATE INDEX idx_ci_harness_rule_match
    ON ci_harness_rule(workspace_id, owner, repo, status, priority DESC);
CREATE UNIQUE INDEX idx_ci_harness_rule_identity
    ON ci_harness_rule(workspace_id, owner, repo, matcher_pattern, COALESCE(scope, ''));
CREATE TABLE ci_harness_event (
    id                    INTEGER PRIMARY KEY,
    watch_id              TEXT    NOT NULL REFERENCES ci_harness_watch(id) ON DELETE CASCADE,
    cycle_id              TEXT    REFERENCES ci_harness_cycle(id) ON DELETE CASCADE,
    phase                 TEXT    NOT NULL,
    kind                  TEXT    NOT NULL,
    message               TEXT    NOT NULL,
    detail_json           TEXT    NOT NULL DEFAULT '{}',
    created_at_ms         INTEGER NOT NULL
);
CREATE INDEX idx_ci_harness_event_watch
    ON ci_harness_event(watch_id, created_at_ms DESC);
CREATE TABLE ci_harness_log_cache (
    watch_id              TEXT    NOT NULL REFERENCES ci_harness_watch(id) ON DELETE CASCADE,
    head_sha              TEXT    NOT NULL,
    check_run_id          INTEGER NOT NULL,
    log_text              TEXT    NOT NULL,
    fetched_at_ms         INTEGER NOT NULL,
    PRIMARY KEY(watch_id, head_sha, check_run_id)
);
CREATE TABLE knowledge_item (
    id                  TEXT    NOT NULL PRIMARY KEY,
    workspace_id        TEXT    REFERENCES workspaces(id) ON DELETE CASCADE,
    repo_id             TEXT    NOT NULL,               -- owner/name
    subtype             TEXT    NOT NULL,               -- knowledge kind
    title               TEXT,
    statement           TEXT    NOT NULL,               -- one concise, actionable fact
    rationale           TEXT,
    steps_json          TEXT,                           -- investigation-recipe steps
    trigger_json        TEXT    NOT NULL DEFAULT '{}',
    state               TEXT    NOT NULL DEFAULT 'pending',
    counters_json       TEXT    NOT NULL DEFAULT '{}',  -- confirmations, conflictsWith, notes
    audiences_json      TEXT    NOT NULL DEFAULT '[]',  -- plan | dev | review | ci-fix
    confidence          TEXT    NOT NULL DEFAULT 'medium',
    validated_at_commit TEXT,                           -- default-branch SHA currentness ran against
    last_verified_at_ms INTEGER,
    created_by          TEXT    NOT NULL DEFAULT 'user', -- user | docs-bootstrap | distill | pr-learning | review-synthesizer
    statement_digest    TEXT,                           -- normalized-statement dedup key
    created_at_ms       INTEGER NOT NULL DEFAULT 0,
    updated_at_ms       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_knowledge_item_workspace
    ON knowledge_item(workspace_id, state, updated_at_ms DESC);
CREATE INDEX idx_knowledge_item_repo
    ON knowledge_item(repo_id, state);
CREATE INDEX idx_knowledge_item_digest
    ON knowledge_item(workspace_id, repo_id, statement_digest);
CREATE TABLE knowledge_provenance (
    knowledge_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE CASCADE,
    source_kind       TEXT NOT NULL,   -- pr | review | thread | commit | file | symbol | test | timeline | doc | distill-operation | imported | user
    source_ref        TEXT NOT NULL,   -- stable ref, e.g. owner/repo#123 or a GitHub id
    commit_sha        TEXT,
    file_path         TEXT,
    url               TEXT,
    content_digest    TEXT,
    PRIMARY KEY (knowledge_item_id, source_kind, source_ref)
);
CREATE TABLE knowledge_applicability (
    knowledge_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE CASCADE,
    kind              TEXT NOT NULL,   -- module | path | symbol | concept
    value             TEXT NOT NULL,
    PRIMARY KEY (knowledge_item_id, kind, value)
);
CREATE INDEX idx_knowledge_applicability_value
    ON knowledge_applicability(kind, value);
CREATE TABLE session_context_projection (
    workspace_id    TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    audience        TEXT    NOT NULL,               -- plan | dev | review | ci-fix
    query_hint      TEXT,                           -- thread/task text the retrieval used
    item_ids_json   TEXT    NOT NULL DEFAULT '[]',  -- knowledge ids inserted into context
    capsule_chars   INTEGER NOT NULL DEFAULT 0,
    brain_chars     INTEGER NOT NULL DEFAULT 0,
    retrieved_chars INTEGER NOT NULL DEFAULT 0,
    created_at_ms   INTEGER NOT NULL,
    PRIMARY KEY (workspace_id, audience)
);
CREATE TABLE thread_engines (
    thread_id  TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,

    -- One of the four session audiences: plan / dev / review / ci-fix.
    audience   TEXT NOT NULL,

    choice     TEXT NOT NULL, work_model_json TEXT,

    PRIMARY KEY (thread_id, audience)
);
CREATE UNIQUE INDEX validation_pass_claim_idx
    ON validation_pass(claim_key) WHERE claim_key IS NOT NULL;
CREATE UNIQUE INDEX thread_turns_kick_key_idx
    ON thread_turns(kick_key) WHERE kick_key IS NOT NULL;
CREATE TABLE task_status_event (
    id             INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    task_id        TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    from_status    TEXT    NOT NULL,
    to_status      TEXT    NOT NULL,
    actor          TEXT    NOT NULL,
    reason         TEXT,
    occurred_at_ms INTEGER NOT NULL
);
CREATE INDEX task_status_event_task_idx ON task_status_event(task_id, occurred_at_ms);
CREATE TABLE local_review_submission (
    id                    TEXT    NOT NULL PRIMARY KEY,
    timeline_event_id     TEXT    UNIQUE,
    task_id               TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    pr_id                 TEXT    NOT NULL,
    agent_run_id          TEXT,
    submission_seq        INTEGER NOT NULL,
    root_ids_json         TEXT    NOT NULL,
    root_snapshot_json    TEXT    NOT NULL,
    submitted_through_ms  INTEGER NOT NULL,
    addressed_through_ms  INTEGER,
    attempt               INTEGER NOT NULL DEFAULT 0,
    failures              INTEGER NOT NULL DEFAULT 0,
    created_at_ms         INTEGER NOT NULL,
    activated_at_ms       INTEGER,
    completed_at_ms       INTEGER,
    canceled_at_ms        INTEGER,
    cancel_reason         TEXT
);
CREATE UNIQUE INDEX local_review_submission_seq_idx
    ON local_review_submission(task_id, submission_seq);
CREATE TABLE local_review_brain_handoff (
    validation_claim_key TEXT    NOT NULL PRIMARY KEY,
    task_id              TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    through_sequence     INTEGER NOT NULL,
    code_fingerprint     TEXT    NOT NULL,
    created_at_ms        INTEGER NOT NULL,
    consumed_at_ms       INTEGER,
    delivery_failures    INTEGER NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX idx_response_round_one_coordinator
    ON response_round(task_id)
    WHERE status IN ('triaging', 'addressing', 'awaiting_gate', 'paused');
CREATE TABLE task_push_authorization (
    token             TEXT    NOT NULL PRIMARY KEY,
    task_id           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    pr_id             TEXT    NOT NULL,
    run_id            TEXT,
    head_sha          TEXT    NOT NULL,
    code_fingerprint  TEXT    NOT NULL,
    actor              TEXT    NOT NULL,
    basis_kind         TEXT    NOT NULL,
    basis_id           TEXT,
    override_reason    TEXT,
    payload_json       TEXT    NOT NULL,
    payload_digest     TEXT    NOT NULL,
    created_at_ms      INTEGER NOT NULL,
    revoked_at_ms      INTEGER,
    consumed_at_ms     INTEGER,
    outcome            TEXT
, effect_keys_json TEXT NOT NULL
    DEFAULT '["push_branch","ensure_pull_request"]', workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), task_epoch INTEGER, stage_id TEXT REFERENCES stage(id), stage_generation INTEGER, operation_id TEXT, semantic_attempt INTEGER, expected_base_sha TEXT);
CREATE UNIQUE INDEX task_push_authorization_one_active
    ON task_push_authorization(task_id)
    WHERE revoked_at_ms IS NULL AND consumed_at_ms IS NULL;
CREATE TABLE task_push_effect (
    id                 INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    token              TEXT    NOT NULL REFERENCES task_push_authorization(token) ON DELETE CASCADE,
    effect_key         TEXT    NOT NULL,
    status             TEXT    NOT NULL,
    attempts           INTEGER NOT NULL DEFAULT 0,
    attempt_limit      INTEGER NOT NULL,
    first_claimed_at_ms INTEGER,
    last_claimed_at_ms INTEGER,
    claim_owner        TEXT,
    lease_until_ms     INTEGER,
    last_error_class   TEXT,
    last_error         TEXT,
    next_attempt_at_ms INTEGER,
    evidence_json      TEXT,
    completed_at_ms    INTEGER,
    UNIQUE(token, effect_key)
);
CREATE INDEX task_push_effect_recovery
    ON task_push_effect(status, next_attempt_at_ms, lease_until_ms);
CREATE TABLE round_gate_authorization (
    token              TEXT    NOT NULL PRIMARY KEY,
    task_id            TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    round_id           TEXT    NOT NULL REFERENCES response_round(id) ON DELETE CASCADE,
    gate_revision      INTEGER NOT NULL,
    attempt            INTEGER NOT NULL,
    actor              TEXT    NOT NULL,
    code_fingerprint   TEXT    NOT NULL,
    payload_json       TEXT    NOT NULL,
    payload_digest     TEXT    NOT NULL,
    effect_keys_json   TEXT    NOT NULL,
    approved_at_ms     INTEGER NOT NULL,
    revoked_at_ms      INTEGER,
    consumed_at_ms     INTEGER,
    outcome            TEXT
, workflow_version TEXT NOT NULL DEFAULT 'LEGACY'
    CHECK (workflow_version IN ('LEGACY', 'V2')), task_epoch INTEGER, stage_id TEXT REFERENCES stage(id), stage_generation INTEGER, operation_id TEXT, semantic_attempt INTEGER, expected_head_sha TEXT, expected_base_sha TEXT);
CREATE UNIQUE INDEX round_gate_authorization_one_active
    ON round_gate_authorization(round_id)
    WHERE revoked_at_ms IS NULL AND consumed_at_ms IS NULL;
CREATE TABLE round_gate_effect (
    id                  INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    token               TEXT    NOT NULL REFERENCES round_gate_authorization(token) ON DELETE CASCADE,
    effect_key          TEXT    NOT NULL,
    status              TEXT    NOT NULL,
    attempts            INTEGER NOT NULL DEFAULT 0,
    attempt_limit       INTEGER NOT NULL,
    first_claimed_at_ms INTEGER,
    last_claimed_at_ms  INTEGER,
    claim_owner         TEXT,
    lease_until_ms      INTEGER,
    last_error_class    TEXT,
    last_error          TEXT,
    next_attempt_at_ms  INTEGER,
    evidence_json       TEXT,
    completed_at_ms     INTEGER,
    UNIQUE(token, effect_key)
);
CREATE INDEX round_gate_effect_recovery
    ON round_gate_effect(status, next_attempt_at_ms, lease_until_ms);
CREATE TABLE repo_directory_scope_decision (
    workspace_id   TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo           TEXT    NOT NULL,
    scope_path     TEXT    NOT NULL,
    decision_state TEXT    NOT NULL CHECK (decision_state IN ('approved', 'rejected')),
    decided_at_ms  INTEGER NOT NULL,
    PRIMARY KEY (workspace_id, repo, scope_path)
);
CREATE TABLE thread_directory_scope_assignment (
    thread_id      TEXT    NOT NULL PRIMARY KEY REFERENCES threads(id) ON DELETE CASCADE,
    workspace_id   TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    repo           TEXT    NOT NULL,
    scope_path     TEXT    NOT NULL,
    assigned_at_ms INTEGER NOT NULL,
    FOREIGN KEY (workspace_id, repo, scope_path)
        REFERENCES repo_directory_scope_decision(workspace_id, repo, scope_path)
        ON DELETE CASCADE
);
CREATE INDEX idx_thread_directory_scope_workspace
    ON thread_directory_scope_assignment(workspace_id, repo);
CREATE TABLE task_policy_revision (
    id                             TEXT    NOT NULL PRIMARY KEY,
    trunk_id                       TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    revision                       INTEGER NOT NULL CHECK (revision > 0),
    source                         TEXT    NOT NULL,
    auto_approve                   INTEGER NOT NULL DEFAULT 0 CHECK (auto_approve IN (0, 1)),
    auto_merge                     INTEGER NOT NULL DEFAULT 0 CHECK (auto_merge IN (0, 1)),
    min_approvals                  INTEGER NOT NULL DEFAULT 0 CHECK (min_approvals >= 0),
    max_brain_rounds               INTEGER NOT NULL DEFAULT 3 CHECK (max_brain_rounds >= 0),
    max_ci_fix_pushes              INTEGER NOT NULL DEFAULT 3 CHECK (max_ci_fix_pushes >= 0),
    require_remote_branch_cleanup  INTEGER NOT NULL DEFAULT 0
        CHECK (require_remote_branch_cleanup IN (0, 1)),
    permission_policy_ref          TEXT,
    created_by                     TEXT    NOT NULL,
    created_at_ms                  INTEGER NOT NULL, delete_local_branch_on_cleanup INTEGER NOT NULL DEFAULT 1
        CHECK (delete_local_branch_on_cleanup IN (0, 1)),
    UNIQUE (trunk_id, revision),
    CHECK (auto_merge = 0 OR auto_approve = 1)
);
CREATE UNIQUE INDEX idx_tasks_assignment_v2
    ON tasks(assignment_id) WHERE assignment_id IS NOT NULL;
CREATE TABLE stage (
    id               TEXT    NOT NULL PRIMARY KEY,
    task_id          TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    kind             TEXT    NOT NULL CHECK (kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT', 'CLEANUP')),
    generation       INTEGER NOT NULL CHECK (generation > 0),
    version          INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    checkpoint       TEXT    NOT NULL,
    opened_at_ms     INTEGER NOT NULL,
    completed_at_ms  INTEGER,
    end_reason       TEXT CHECK (end_reason IN (
        'NORMAL', 'SUPERSEDED_BY_REPLAN', 'TASK_CANCELED',
        'REMOTE_MERGED', 'REMOTE_CLOSED')),
    open_marker      INTEGER GENERATED ALWAYS AS (
        CASE WHEN completed_at_ms IS NULL THEN 1 ELSE 0 END) STORED, reasoning_effort TEXT
    CHECK (reasoning_effort IS NULL OR reasoning_effort IN (
        'none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max')),
    CHECK ((completed_at_ms IS NULL AND end_reason IS NULL)
        OR (completed_at_ms IS NOT NULL AND end_reason IS NOT NULL)),
    CHECK (kind <> 'PLAN' OR checkpoint IN (
        'DRAFTING', 'SELF_REVIEW', 'AWAITING_APPROVAL', 'COMPLETED')),
    CHECK (kind <> 'LOCAL_DEVELOPMENT' OR checkpoint IN (
        'IMPLEMENTING', 'VALIDATING', 'BRAIN_REVIEW', 'LOCAL_REVIEW',
        'PUBLISHING', 'ADDRESSING_BRAIN_FINDINGS',
        'ADDRESSING_LOCAL_FEEDBACK', 'COMPLETED')),
    CHECK (kind <> 'REMOTE_DEVELOPMENT' OR checkpoint IN (
        'WAITING_CI', 'AWAITING_READY', 'WAITING_REMOTE_REVIEW',
        'ADDRESSING_REMOTE_FEEDBACK', 'READY_TO_MERGE', 'MERGING', 'COMPLETED')),
    CHECK (kind <> 'CLEANUP' OR checkpoint IN (
        'WAITING_QUIESCENCE', 'CLEANING', 'COMPLETED')),
    CHECK (end_reason NOT IN ('NORMAL', 'REMOTE_MERGED', 'REMOTE_CLOSED')
        OR checkpoint = 'COMPLETED'),
    UNIQUE (task_id, kind, generation),
    UNIQUE (id, task_id, generation, open_marker)
);
CREATE UNIQUE INDEX idx_stage_one_unsealed_per_task
    ON stage(task_id) WHERE completed_at_ms IS NULL;
CREATE INDEX idx_stage_task_kind_generation
    ON stage(task_id, kind, generation DESC);
CREATE TABLE task_current_stage (
    task_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES tasks(id) ON DELETE CASCADE,
    stage_id         TEXT    NOT NULL,
    stage_generation INTEGER NOT NULL CHECK (stage_generation > 0),
    open_marker      INTEGER NOT NULL DEFAULT 1 CHECK (open_marker = 1),
    FOREIGN KEY (stage_id, task_id, stage_generation, open_marker)
        REFERENCES stage(id, task_id, generation, open_marker)
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE trunk_transition (
    id               TEXT    NOT NULL PRIMARY KEY,
    trunk_id         TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id       TEXT    NOT NULL,
    from_state       TEXT,
    to_state         TEXT    NOT NULL,
    aggregate_version INTEGER NOT NULL,
    cause            TEXT    NOT NULL,
    actor            TEXT    NOT NULL,
    occurred_at_ms   INTEGER NOT NULL,
    UNIQUE (trunk_id, command_id),
    UNIQUE (trunk_id, aggregate_version)
);
CREATE TABLE task_transition (
    id               TEXT    NOT NULL PRIMARY KEY,
    task_id          TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id       TEXT    NOT NULL,
    epoch            INTEGER NOT NULL,
    from_state       TEXT,
    to_state         TEXT    NOT NULL,
    aggregate_version INTEGER NOT NULL,
    cause            TEXT    NOT NULL,
    actor            TEXT    NOT NULL,
    occurred_at_ms   INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    UNIQUE (task_id, aggregate_version)
);
CREATE TABLE stage_transition (
    id               TEXT    NOT NULL PRIMARY KEY,
    stage_id         TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    command_id       TEXT    NOT NULL,
    generation       INTEGER NOT NULL,
    from_checkpoint  TEXT,
    to_checkpoint    TEXT    NOT NULL,
    stage_version    INTEGER NOT NULL,
    cause            TEXT    NOT NULL,
    actor            TEXT    NOT NULL,
    occurred_at_ms   INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    UNIQUE (stage_id, stage_version)
);
CREATE TABLE task_terminal_intent (
    id               TEXT    NOT NULL PRIMARY KEY,
    task_id          TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    kind             TEXT    NOT NULL CHECK (kind IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    source           TEXT    NOT NULL,
    source_id        TEXT,
    observed_head_sha TEXT,
    evidence_json    TEXT,
    accepted         INTEGER NOT NULL CHECK (accepted IN (0, 1)),
    recorded_at_ms   INTEGER NOT NULL
);
CREATE UNIQUE INDEX idx_task_terminal_intent_accepted
    ON task_terminal_intent(task_id) WHERE accepted = 1;
CREATE TABLE task_blocker (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    stage_id            TEXT    REFERENCES stage(id) ON DELETE CASCADE,
    owner_kind          TEXT    NOT NULL CHECK (owner_kind IN ('TASK', 'STAGE', 'EPISODE', 'OPERATION')),
    owner_id            TEXT    NOT NULL,
    subject_revision    TEXT,
    blocker_type        TEXT    NOT NULL,
    status              TEXT    NOT NULL CHECK (status IN ('OPEN', 'RESOLVED', 'WAIVED')),
    payload_json        TEXT,
    opened_at_ms        INTEGER NOT NULL,
    resolved_at_ms      INTEGER,
    resolution_evidence TEXT,
    CHECK ((status = 'OPEN' AND resolved_at_ms IS NULL)
        OR (status <> 'OPEN' AND resolved_at_ms IS NOT NULL))
);
CREATE INDEX idx_task_blocker_open
    ON task_blocker(task_id, stage_id) WHERE status = 'OPEN';
CREATE TABLE thread_turn (
    id                TEXT    NOT NULL PRIMARY KEY,
    trunk_id          TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    purpose           TEXT    NOT NULL,
    status            TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING',
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    operation_id      TEXT    NOT NULL UNIQUE,
    attempt           INTEGER NOT NULL CHECK (attempt > 0),
    delivery_lane     TEXT    NOT NULL,
    launch_input      TEXT    NOT NULL,
    requested_at_ms   INTEGER NOT NULL,
    started_at_ms     INTEGER,
    finished_at_ms    INTEGER,
    error_message     TEXT
, planning_operation_id TEXT
    REFERENCES planning_base_refresh_operation(id), expected_base_sha TEXT);
CREATE INDEX idx_thread_turn_trunk_status
    ON thread_turn(trunk_id, status, requested_at_ms);
CREATE TABLE task_turn (
    id                         TEXT    NOT NULL PRIMARY KEY,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    purpose                    TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING',
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    operation_id               TEXT    NOT NULL UNIQUE,
    attempt                    INTEGER NOT NULL CHECK (attempt > 0),
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    trigger_stage_id           TEXT    REFERENCES stage(id),
    trigger_stage_generation   INTEGER,
    expected_code_fingerprint  TEXT,
    expected_head_sha          TEXT,
    expected_base_sha          TEXT,
    delivery_lane              TEXT    NOT NULL,
    launch_input               TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    started_at_ms              INTEGER,
    finished_at_ms             INTEGER,
    error_message              TEXT,
    CHECK ((trigger_stage_id IS NULL AND trigger_stage_generation IS NULL)
        OR (trigger_stage_id IS NOT NULL AND trigger_stage_generation IS NOT NULL))
);
CREATE INDEX idx_task_turn_task_status
    ON task_turn(task_id, status, requested_at_ms);
CREATE TABLE stage_turn (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    purpose                    TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING',
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    operation_id               TEXT    NOT NULL UNIQUE,
    attempt                    INTEGER NOT NULL CHECK (attempt > 0),
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    expected_code_fingerprint  TEXT,
    expected_head_sha          TEXT,
    expected_base_sha          TEXT,
    delivery_lane              TEXT    NOT NULL,
    launch_input               TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    started_at_ms              INTEGER,
    finished_at_ms             INTEGER,
    error_message              TEXT
);
CREATE INDEX idx_stage_turn_stage_status
    ON stage_turn(stage_id, status, requested_at_ms);
CREATE TABLE review_assignment_turn (
    id                TEXT    NOT NULL PRIMARY KEY,
    assignment_id     TEXT    NOT NULL REFERENCES review_assignment(id) ON DELETE CASCADE,
    purpose           TEXT    NOT NULL,
    status            TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING',
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    operation_id      TEXT    NOT NULL UNIQUE,
    attempt           INTEGER NOT NULL CHECK (attempt > 0),
    start_commit      TEXT    NOT NULL,
    delivery_lane     TEXT    NOT NULL,
    launch_input      TEXT    NOT NULL,
    requested_at_ms   INTEGER NOT NULL,
    started_at_ms     INTEGER,
    finished_at_ms    INTEGER,
    error_message     TEXT
, subject_key TEXT NOT NULL DEFAULT '', verifier_run_id TEXT REFERENCES agent_run(id), cost_cap_usd_milli INTEGER CHECK (cost_cap_usd_milli > 0));
CREATE INDEX idx_review_assignment_turn_owner_status
    ON review_assignment_turn(assignment_id, status, requested_at_ms);
CREATE TABLE thread_message (
    id TEXT NOT NULL PRIMARY KEY,
    turn_id TEXT NOT NULL REFERENCES thread_turn(id) ON DELETE CASCADE,
    seq INTEGER NOT NULL CHECK (seq > 0),
    role TEXT NOT NULL,
    body TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL,
    UNIQUE (turn_id, seq)
);
CREATE TABLE thread_question (
    id TEXT NOT NULL PRIMARY KEY,
    turn_id TEXT NOT NULL REFERENCES thread_turn(id) ON DELETE CASCADE,
    call_id TEXT NOT NULL,
    prompt TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('OPEN', 'ANSWERED', 'CANCELED')),
    answer TEXT,
    answer_revision INTEGER NOT NULL DEFAULT 0 CHECK (answer_revision >= 0),
    created_at_ms INTEGER NOT NULL,
    answered_at_ms INTEGER, context TEXT, options_json TEXT NOT NULL DEFAULT '[]', allow_free_form INTEGER NOT NULL DEFAULT 1
    CHECK (allow_free_form IN (0, 1)), answer_option_id TEXT, answer_free_form TEXT, answer_actor TEXT, continuation_state TEXT NOT NULL DEFAULT 'WAITING'
    CHECK (continuation_state IN (
        'WAITING', 'READY', 'DISPATCHED', 'SUPERSEDED', 'CANCELED')), successor_turn_id TEXT REFERENCES thread_turn(id), continuation_error TEXT,
    UNIQUE (turn_id, call_id)
);
