CREATE TABLE stage_question (
    id TEXT NOT NULL PRIMARY KEY,
    turn_id TEXT NOT NULL REFERENCES stage_turn(id) ON DELETE CASCADE,
    call_id TEXT NOT NULL,
    prompt TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('OPEN', 'ANSWERED', 'CANCELED')),
    answer TEXT,
    answer_revision INTEGER NOT NULL DEFAULT 0 CHECK (answer_revision >= 0),
    created_at_ms INTEGER NOT NULL,
    answered_at_ms INTEGER, context TEXT, options_json TEXT NOT NULL DEFAULT '[]', allow_free_form INTEGER NOT NULL DEFAULT 1
    CHECK (allow_free_form IN (0, 1)), answer_option_id TEXT, answer_free_form TEXT, answer_actor TEXT, continuation_state TEXT NOT NULL DEFAULT 'WAITING'
    CHECK (continuation_state IN (
        'WAITING', 'READY', 'DISPATCHED', 'SUPERSEDED', 'CANCELED')), successor_turn_id TEXT REFERENCES stage_turn(id), continuation_error TEXT,
