CREATE TABLE permission_request (
    id                    TEXT    NOT NULL PRIMARY KEY,
    call_id               TEXT    NOT NULL UNIQUE,
    turn_kind             TEXT    NOT NULL CHECK (turn_kind IN (
        'THREAD', 'TASK', 'STAGE', 'REVIEW_ASSIGNMENT')),
    turn_id               TEXT    NOT NULL,
    operation_id          TEXT    NOT NULL,
    capability            TEXT    NOT NULL,
    tool_name             TEXT,
    parameters_json       TEXT    NOT NULL,
    policy_snapshot       TEXT    NOT NULL,
    state                 TEXT    NOT NULL CHECK (state IN (
        'OPEN', 'ALLOWED_ONCE', 'ALLOWED_NEXT', 'ALLOWED_TASK',
        'ALLOWED_REPOSITORY', 'DENIED', 'CANCELED', 'EXPIRED')),
    answer                TEXT,
    answer_revision       INTEGER NOT NULL DEFAULT 0 CHECK (answer_revision >= 0),
    requested_at_ms       INTEGER NOT NULL,
    answered_at_ms        INTEGER
, parameters_digest TEXT, grant_scope_kind TEXT
    CHECK (grant_scope_kind IN ('CALL', 'TRUNK', 'TASK', 'REPOSITORY')), grant_scope_id TEXT, granted_uses INTEGER
    CHECK (granted_uses = -1 OR granted_uses > 0), remaining_uses INTEGER
    CHECK (remaining_uses = -1 OR remaining_uses >= 0), consumed_uses INTEGER NOT NULL DEFAULT 0
    CHECK (consumed_uses >= 0), answer_actor TEXT, last_consumed_at_ms INTEGER, continuation_state TEXT NOT NULL DEFAULT 'WAITING'
    CHECK (continuation_state IN (
        'WAITING', 'READY', 'DISPATCHED', 'SUPERSEDED', 'CANCELED')), successor_turn_id TEXT, continuation_error TEXT);
CREATE INDEX idx_permission_request_turn
    ON permission_request(turn_kind, turn_id, requested_at_ms);
CREATE TABLE outbox (
    id                TEXT    NOT NULL PRIMARY KEY,
    dedup_key         TEXT    NOT NULL UNIQUE,
    aggregate_kind    TEXT    NOT NULL,
    aggregate_id      TEXT    NOT NULL,
    topic             TEXT    NOT NULL,
    payload           TEXT    NOT NULL,
    status            TEXT    NOT NULL CHECK (status IN ('PENDING', 'CLAIMED', 'DELIVERED', 'FAILED')),
    attempts          INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    available_at_ms   INTEGER NOT NULL,
    claim_owner       TEXT,
    lease_until_ms    INTEGER,
    created_at_ms     INTEGER NOT NULL,
    delivered_at_ms   INTEGER,
    last_error        TEXT
);
CREATE INDEX idx_outbox_delivery
    ON outbox(status, available_at_ms, created_at_ms);
CREATE TABLE agent_execution (
    id                   TEXT    NOT NULL PRIMARY KEY,
    ticket_id            TEXT    NOT NULL REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    infrastructure_attempt INTEGER NOT NULL CHECK (infrastructure_attempt > 0),
    provider             TEXT,
    provider_session_id  TEXT,
    process_pid          INTEGER,
    log_ref              TEXT,
    status               TEXT    NOT NULL CHECK (status IN (
        'STARTING', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELED', 'UNKNOWN')),
    started_at_ms        INTEGER NOT NULL,
    heartbeat_at_ms      INTEGER,
    finished_at_ms       INTEGER,
    raw_result           TEXT,
    error_class          TEXT,
    error_message        TEXT,
    cost_usd_milli       INTEGER NOT NULL DEFAULT 0,
    tokens_in            INTEGER NOT NULL DEFAULT 0,
    tokens_out           INTEGER NOT NULL DEFAULT 0,
    UNIQUE (ticket_id, infrastructure_attempt)
);
CREATE TABLE agent_execution_log (
    execution_id TEXT NOT NULL REFERENCES agent_execution(id) ON DELETE CASCADE,
    seq INTEGER NOT NULL CHECK (seq >= 0),
    payload TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL,
    PRIMARY KEY (execution_id, seq)
);
CREATE TABLE capacity_lease (
    id               TEXT    NOT NULL PRIMARY KEY,
    ticket_id        TEXT    REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    operation_id     TEXT    NOT NULL,
    workflow_source  TEXT    NOT NULL CHECK (workflow_source IN ('LEGACY', 'V2')),
    lane_mask        INTEGER NOT NULL CHECK (lane_mask BETWEEN 1 AND 511),
    trunk_control    INTEGER NOT NULL CHECK (trunk_control IN (0, 1)),
    exclusive_task   INTEGER NOT NULL CHECK (exclusive_task IN (0, 1)),
    writer_required  INTEGER NOT NULL CHECK (writer_required IN (0, 1)),
    workspace_id     TEXT    REFERENCES workspaces(id),
    trunk_id         TEXT    REFERENCES threads(id) ON DELETE CASCADE,
    task_id          TEXT    REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch       INTEGER,
    holder           TEXT    NOT NULL,
    fencing_token    INTEGER CHECK (fencing_token > 0),
    acquired_at_ms   INTEGER NOT NULL,
    heartbeat_at_ms  INTEGER NOT NULL,
    expires_at_ms    INTEGER NOT NULL,
    released_at_ms   INTEGER,
    release_reason   TEXT,
    CHECK (expires_at_ms > acquired_at_ms),
    CHECK (heartbeat_at_ms >= acquired_at_ms),
    CHECK ((released_at_ms IS NULL AND release_reason IS NULL)
        OR (released_at_ms IS NOT NULL AND release_reason IS NOT NULL)),
    CHECK (trunk_control = 0 OR task_id IS NULL),
    CHECK (exclusive_task = 0 OR task_id IS NOT NULL),
    CHECK (writer_required = 0 OR (exclusive_task = 1 AND fencing_token IS NOT NULL)),
    CHECK ((task_id IS NULL AND task_epoch IS NULL)
        OR (task_id IS NOT NULL AND task_epoch IS NOT NULL))
);
CREATE UNIQUE INDEX idx_capacity_lease_live_operation
    ON capacity_lease(operation_id) WHERE released_at_ms IS NULL;
CREATE UNIQUE INDEX idx_capacity_lease_live_ticket
    ON capacity_lease(ticket_id) WHERE released_at_ms IS NULL AND ticket_id IS NOT NULL;
CREATE UNIQUE INDEX idx_capacity_lease_mutating_task
    ON capacity_lease(task_id)
    WHERE released_at_ms IS NULL AND exclusive_task = 1;
CREATE INDEX idx_capacity_lease_expiry
    ON capacity_lease(released_at_ms, expires_at_ms);
CREATE UNIQUE INDEX idx_capacity_lease_writer_fence
    ON capacity_lease(task_id, fencing_token) WHERE fencing_token IS NOT NULL;
CREATE UNIQUE INDEX idx_validation_pass_v2_operation
    ON validation_pass(operation_id) WHERE operation_id IS NOT NULL;
CREATE UNIQUE INDEX idx_task_push_authorization_v2_operation
    ON task_push_authorization(operation_id) WHERE operation_id IS NOT NULL;
CREATE UNIQUE INDEX idx_response_round_v2_operation
    ON response_round(operation_id) WHERE operation_id IS NOT NULL;
CREATE UNIQUE INDEX idx_round_gate_authorization_v2_operation
    ON round_gate_authorization(operation_id) WHERE operation_id IS NOT NULL;
CREATE UNIQUE INDEX idx_worktree_leases_v2_task
    ON worktree_leases(task_id) WHERE workflow_version = 'V2';
CREATE UNIQUE INDEX idx_worktree_leases_v2_fence
    ON worktree_leases(task_id, fencing_token) WHERE fencing_token IS NOT NULL;
CREATE TABLE dispatch_delivery_claim (
    ticket_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    ticket_version     INTEGER NOT NULL CHECK (ticket_version >= 0),
    claim_owner        TEXT    NOT NULL,
    claimed_at_ms      INTEGER NOT NULL,
    heartbeat_at_ms    INTEGER NOT NULL,
    expires_at_ms      INTEGER NOT NULL,
    CHECK (heartbeat_at_ms >= claimed_at_ms),
    CHECK (expires_at_ms > heartbeat_at_ms)
);
CREATE INDEX idx_dispatch_delivery_claim_expiry
    ON dispatch_delivery_claim(expires_at_ms);
CREATE TABLE task_brain (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL UNIQUE REFERENCES tasks(id) ON DELETE CASCADE,
    provider            TEXT    NOT NULL,
    model               TEXT    NOT NULL,
    role_skill          TEXT,
    engine_snapshot     TEXT    NOT NULL,
    created_at_ms       INTEGER NOT NULL
);
CREATE TABLE provision_task_operation (
    id                       TEXT    NOT NULL PRIMARY KEY,
    task_id                  TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch               INTEGER NOT NULL CHECK (task_epoch > 0),
    assignment_id            TEXT    NOT NULL REFERENCES task_assignment(id),
    operation_id             TEXT    NOT NULL UNIQUE,
    semantic_attempt         INTEGER NOT NULL CHECK (semantic_attempt > 0),
    repository_id            TEXT    NOT NULL,
    expected_base_sha        TEXT,
    expected_remote_head_sha TEXT,
    requested_branch_name    TEXT    NOT NULL,
    requested_worktree_path  TEXT    NOT NULL,
    status                   TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'ACCEPTED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    result_base_sha          TEXT,
    result_head_sha          TEXT,
    result_code_fingerprint  TEXT,
    created_at_ms            INTEGER NOT NULL,
    completed_at_ms          INTEGER,
    error_message            TEXT, base_source TEXT
    CHECK (base_source IN ('PLANNING_SNAPSHOT', 'FRESH_REMOTE_BASE', 'EXISTING_PR_HEAD')), base_repository_id TEXT, base_ref TEXT, result_evidence TEXT,
    CHECK ((status = 'ACCEPTED') = (
        result_base_sha IS NOT NULL AND result_head_sha IS NOT NULL
        AND result_code_fingerprint IS NOT NULL)),
    CHECK ((status IN ('ACCEPTED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_provision_task_semantic_attempt
    ON provision_task_operation(task_id, task_epoch, semantic_attempt);
CREATE TABLE task_code_identity (
    task_id                  TEXT    NOT NULL PRIMARY KEY
        REFERENCES tasks(id) ON DELETE CASCADE,
    provision_operation_id  TEXT    NOT NULL UNIQUE
        REFERENCES provision_task_operation(id),
    repository_id           TEXT    NOT NULL,
    upstream_repository_id  TEXT,
    publish_repository_id   TEXT    NOT NULL,
    branch_name             TEXT    NOT NULL,
    worktree_path           TEXT    NOT NULL,
    base_sha                TEXT    NOT NULL,
    local_head_sha          TEXT    NOT NULL,
    code_fingerprint        TEXT    NOT NULL,
    version                 INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at_ms           INTEGER NOT NULL,
    updated_at_ms           INTEGER NOT NULL,
    UNIQUE (repository_id, worktree_path),
    UNIQUE (publish_repository_id, branch_name)
);
CREATE TABLE plan_stage (
    stage_id             TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage(id) ON DELETE CASCADE,
    task_id              TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    generation           INTEGER NOT NULL CHECK (generation > 0),
    opened_for_epoch     INTEGER NOT NULL CHECK (opened_for_epoch > 0),
    UNIQUE (stage_id, task_id, generation)
);
CREATE TABLE plan_revision (
    id                  TEXT    NOT NULL PRIMARY KEY,
    plan_stage_id       TEXT    NOT NULL REFERENCES plan_stage(stage_id) ON DELETE CASCADE,
    revision            INTEGER NOT NULL CHECK (revision > 0),
    content             TEXT    NOT NULL,
    content_digest      TEXT    NOT NULL,
    source              TEXT    NOT NULL CHECK (source IN (
        'AGENT', 'USER_EDIT', 'BRAIN_REVISION', 'REPLAN_SEED')),
    created_by          TEXT    NOT NULL,
    created_at_ms       INTEGER NOT NULL,
    UNIQUE (plan_stage_id, revision),
    UNIQUE (plan_stage_id, content_digest)
);
CREATE TABLE plan_self_review (
    id                    TEXT    NOT NULL PRIMARY KEY,
    plan_revision_id      TEXT    NOT NULL UNIQUE
        REFERENCES plan_revision(id) ON DELETE CASCADE,
    task_turn_id          TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    task_epoch            INTEGER NOT NULL CHECK (task_epoch > 0),
    reviewed_digest       TEXT    NOT NULL,
    status                TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    verdict               TEXT CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'BLOCKED')),
    concern_summary       TEXT,
    requested_at_ms       INTEGER NOT NULL,
    completed_at_ms       INTEGER,
    error_message         TEXT,
    CHECK ((status = 'SUCCEEDED') = (verdict IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE TABLE plan_followup (
    id                  TEXT    NOT NULL PRIMARY KEY,
    plan_revision_id    TEXT    NOT NULL REFERENCES plan_revision(id) ON DELETE CASCADE,
    kind                TEXT    NOT NULL CHECK (kind IN (
        'CONCERN', 'FOLLOW_UP', 'STEWARDSHIP', 'FAILURE_BLOCKER')),
    description         TEXT    NOT NULL,
    status              TEXT    NOT NULL CHECK (status IN ('OPEN', 'RESOLVED', 'DEFERRED')),
    self_review_id      TEXT    REFERENCES plan_self_review(id),
    task_blocker_id     TEXT    UNIQUE REFERENCES task_blocker(id),
    created_by          TEXT    NOT NULL,
    created_at_ms       INTEGER NOT NULL,
    resolved_at_ms      INTEGER,
    resolution          TEXT,
    UNIQUE (self_review_id),
    CHECK ((kind = 'FAILURE_BLOCKER'
            AND self_review_id IS NOT NULL AND task_blocker_id IS NOT NULL)
        OR (kind <> 'FAILURE_BLOCKER'
            AND self_review_id IS NULL AND task_blocker_id IS NULL)),
    CHECK ((status = 'OPEN' AND resolved_at_ms IS NULL AND resolution IS NULL)
        OR (status <> 'OPEN' AND resolved_at_ms IS NOT NULL AND resolution IS NOT NULL))
);
CREATE TABLE task_quiescence_barrier (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch          INTEGER NOT NULL CHECK (task_epoch > 0),
    reason              TEXT    NOT NULL CHECK (reason IN (
        'REPLAN', 'PAUSE', 'CANCEL', 'CLEANUP')),
    status              TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'SATISFIED', 'FAILED', 'CANCELED')),
    requested_at_ms     INTEGER NOT NULL,
    completed_at_ms     INTEGER,
    evidence            TEXT,
    error_message       TEXT,
    CHECK ((status IN ('SATISFIED', 'FAILED', 'CANCELED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK ((status = 'SATISFIED') = (evidence IS NOT NULL))
);
CREATE UNIQUE INDEX idx_task_quiescence_one_active
    ON task_quiescence_barrier(task_id) WHERE status = 'REQUESTED';
CREATE TABLE task_replan_request (
    id                    TEXT    NOT NULL PRIMARY KEY,
    task_id               TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    source_stage_id       TEXT    NOT NULL REFERENCES stage(id),
    source_generation     INTEGER NOT NULL CHECK (source_generation > 0),
    source_task_epoch     INTEGER NOT NULL CHECK (source_task_epoch > 0),
    target_task_epoch     INTEGER NOT NULL CHECK (target_task_epoch = source_task_epoch + 1),
    quiescence_barrier_id TEXT    NOT NULL UNIQUE
        REFERENCES task_quiescence_barrier(id),
    command_id            TEXT    NOT NULL,
    reason                TEXT    NOT NULL,
    requested_by          TEXT    NOT NULL,
    status                TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'QUIESCING', 'APPLIED', 'FAILED', 'CANCELED')),
    new_plan_stage_id     TEXT    REFERENCES stage(id),
    new_plan_generation   INTEGER,
    requested_at_ms       INTEGER NOT NULL,
    completed_at_ms       INTEGER,
    error_message         TEXT,
    UNIQUE (task_id, command_id),
    CHECK ((new_plan_stage_id IS NULL AND new_plan_generation IS NULL)
        OR (new_plan_stage_id IS NOT NULL AND new_plan_generation IS NOT NULL)),
    CHECK ((status = 'APPLIED') = (new_plan_stage_id IS NOT NULL)),
    CHECK ((status IN ('APPLIED', 'FAILED', 'CANCELED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_task_replan_one_active
    ON task_replan_request(task_id)
    WHERE status IN ('REQUESTED', 'QUIESCING');
CREATE TABLE local_development_stage (
    stage_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage(id) ON DELETE CASCADE,
    task_id           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    generation        INTEGER NOT NULL CHECK (generation > 0),
    opened_for_epoch  INTEGER NOT NULL CHECK (opened_for_epoch > 0),
    UNIQUE (stage_id, task_id, generation)
);
CREATE TABLE dev_report (
    id                         TEXT    NOT NULL PRIMARY KEY,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    summary                    TEXT    NOT NULL,
    decisions_json             TEXT,
    invariants_json            TEXT,
    tricky_spots_json          TEXT,
    test_map_json              TEXT,
    followups_json             TEXT,
    created_at_ms              INTEGER NOT NULL,
    workflow_version           TEXT    NOT NULL DEFAULT 'LEGACY'
        CHECK (workflow_version IN ('LEGACY', 'V2')),
    local_development_stage_id TEXT
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_epoch                 INTEGER CHECK (task_epoch > 0),
    stage_generation           INTEGER CHECK (stage_generation > 0),
    stage_turn_id              TEXT UNIQUE REFERENCES stage_turn(id),
    revision                   INTEGER CHECK (revision > 0),
    code_fingerprint           TEXT,
    head_sha                   TEXT,
    base_sha                   TEXT,
    implemented_intent         TEXT,
    commit_summary             TEXT,
    file_summary               TEXT,
    validation_summary         TEXT,
    known_risks                TEXT,
    unresolved_concerns        TEXT,
    context_refs               TEXT
, source_code_fingerprint TEXT, source_head_sha TEXT, source_base_sha TEXT);
CREATE UNIQUE INDEX idx_dev_report_legacy_task
    ON dev_report(task_id) WHERE workflow_version = 'LEGACY';
CREATE UNIQUE INDEX idx_dev_report_v2_revision
    ON dev_report(local_development_stage_id, revision)
    WHERE workflow_version = 'V2';
CREATE UNIQUE INDEX idx_dev_report_v2_subject
    ON dev_report(local_development_stage_id, code_fingerprint, head_sha, base_sha)
    WHERE workflow_version = 'V2';
CREATE TABLE validation_operation (
    id                         TEXT    NOT NULL PRIMARY KEY,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    operation_id               TEXT    NOT NULL UNIQUE,
    semantic_attempt           INTEGER NOT NULL CHECK (semantic_attempt > 0),
    code_fingerprint           TEXT    NOT NULL,
    expected_head_sha          TEXT    NOT NULL,
    expected_base_sha          TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'COMPLETED', 'FAILED',
        'CANCELED', 'SUPERSEDED')),
    requested_at_ms            INTEGER NOT NULL,
    completed_at_ms            INTEGER,
    error_message              TEXT,
    UNIQUE (local_development_stage_id, code_fingerprint, semantic_attempt),
    CHECK ((status IN ('COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE TABLE validation_evidence (
    id                       TEXT    NOT NULL PRIMARY KEY,
    validation_operation_id TEXT    NOT NULL UNIQUE
        REFERENCES validation_operation(id) ON DELETE CASCADE,
    validation_pass_id       INTEGER NOT NULL UNIQUE REFERENCES validation_pass(id),
    task_id                  TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch               INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id                 TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation         INTEGER NOT NULL CHECK (stage_generation > 0),
    code_fingerprint         TEXT    NOT NULL,
    head_sha                 TEXT    NOT NULL,
    base_sha                 TEXT    NOT NULL,
    passed                   INTEGER NOT NULL CHECK (passed IN (0, 1)),
    failures_digest          TEXT,
    evidence                 TEXT    NOT NULL,
    completed_at_ms          INTEGER NOT NULL,
    CHECK ((passed = 1 AND failures_digest IS NULL)
        OR (passed = 0 AND length(failures_digest) > 0))
);
CREATE TABLE brain_review_episode (
    id                         TEXT    NOT NULL PRIMARY KEY,
    task_brain_id              TEXT    NOT NULL REFERENCES task_brain(id),
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    validation_evidence_id     TEXT    NOT NULL REFERENCES validation_evidence(id),
    task_turn_id               TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    semantic_attempt           INTEGER NOT NULL CHECK (semantic_attempt > 0),
    code_fingerprint           TEXT    NOT NULL,
    expected_head_sha          TEXT    NOT NULL,
    expected_base_sha          TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'REVIEWING', 'SUCCEEDED', 'FAILED', 'CANCELED',
        'SUPERSEDED', 'BUDGET_EXHAUSTED')),
    verdict                    TEXT CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'BLOCKED')),
    unresolved_finding_count   INTEGER NOT NULL DEFAULT 0
        CHECK (unresolved_finding_count >= 0),
    verdict_summary            TEXT,
    requested_at_ms            INTEGER NOT NULL,
    completed_at_ms            INTEGER,
    error_message              TEXT,
    UNIQUE (local_development_stage_id, dev_report_id, semantic_attempt),
    CHECK ((status = 'SUCCEEDED') = (verdict IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'CANCELED',
            'SUPERSEDED', 'BUDGET_EXHAUSTED')) = (completed_at_ms IS NOT NULL)),
    CHECK (verdict <> 'APPROVED' OR unresolved_finding_count = 0),
    CHECK (status <> 'BUDGET_EXHAUSTED' OR verdict IS NULL)
);
CREATE UNIQUE INDEX idx_brain_review_episode_one_active
    ON brain_review_episode(task_id)
    WHERE status IN ('REQUESTED', 'REVIEWING');
CREATE TABLE local_review_thread (
    id                         TEXT    NOT NULL PRIMARY KEY,
    pr_id                      TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    scope                      TEXT    NOT NULL CHECK (scope IN ('PR', 'FILE_LINE')),
    file_path                  TEXT,
    start_line                 INTEGER,
    end_line                   INTEGER,
    source                     TEXT    NOT NULL CHECK (source IN (
        'USER', 'BRAIN', 'ADVISORY_REVIEW', 'BLOCKING_REVIEW',
        'DEVELOPMENT', 'IMPORTED')),
    created_by                 TEXT    NOT NULL,
    created_at_ms              INTEGER NOT NULL,
    CHECK ((scope = 'PR' AND file_path IS NULL
            AND start_line IS NULL AND end_line IS NULL)
        OR (scope = 'FILE_LINE' AND length(file_path) > 0
            AND start_line > 0 AND end_line >= start_line))
);
CREATE TABLE local_review_comment_revision (
    id                         TEXT    NOT NULL PRIMARY KEY,
    thread_id                  TEXT    NOT NULL
        REFERENCES local_review_thread(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    revision                   INTEGER NOT NULL CHECK (revision > 0),
    previous_revision_id       TEXT REFERENCES local_review_comment_revision(id),
    author_kind                TEXT    NOT NULL CHECK (author_kind IN (
        'USER', 'BRAIN', 'ADVISORY_REVIEW', 'BLOCKING_REVIEW',
        'DEVELOPMENT', 'IMPORTED')),
    body                       TEXT    NOT NULL,
    body_digest                TEXT    NOT NULL,
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    state                      TEXT    NOT NULL CHECK (state IN (
        'DRAFT', 'PENDING', 'SUBMITTED', 'ADDRESSED',
        'DISMISSED', 'SUPERSEDED')),
    state_version              INTEGER NOT NULL DEFAULT 0 CHECK (state_version >= 0),
    created_at_ms              INTEGER NOT NULL,
    state_changed_at_ms        INTEGER NOT NULL,
    resolution_reason          TEXT,
    terminal_at_ms             INTEGER,
    UNIQUE (thread_id, revision),
    UNIQUE (thread_id, body_digest, revision),
    CHECK (length(body) > 0 AND length(body_digest) > 0),
    CHECK ((state IN ('ADDRESSED', 'DISMISSED', 'SUPERSEDED'))
        = (terminal_at_ms IS NOT NULL)),
    CHECK (state NOT IN ('DISMISSED', 'SUPERSEDED')
        OR length(resolution_reason) > 0)
);
CREATE TABLE local_feedback_batch (
    id                         TEXT    NOT NULL PRIMARY KEY,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    pr_id                      TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    source_submission_id       TEXT UNIQUE REFERENCES local_review_submission(id),
    sequence                   INTEGER NOT NULL CHECK (sequence > 0),
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'BUILDING', 'FROZEN', 'QUEUED', 'DISPATCHED', 'ADDRESSED',
        'FAILED', 'CANCELED', 'SUPERSEDED')),
    stage_turn_id              TEXT UNIQUE REFERENCES stage_turn(id),
    created_at_ms              INTEGER NOT NULL,
    frozen_at_ms               INTEGER,
    completed_at_ms            INTEGER,
    error_message              TEXT, content_digest TEXT,
    UNIQUE (local_development_stage_id, sequence),
    CHECK ((status = 'BUILDING') = (frozen_at_ms IS NULL)),
    CHECK ((status IN ('ADDRESSED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_local_feedback_batch_one_dispatched
    ON local_feedback_batch(local_development_stage_id)
    WHERE status = 'DISPATCHED';
CREATE TABLE local_feedback_batch_item (
    batch_id              TEXT    NOT NULL
        REFERENCES local_feedback_batch(id) ON DELETE CASCADE,
    position              INTEGER NOT NULL CHECK (position > 0),
    thread_id             TEXT    NOT NULL REFERENCES local_review_thread(id),
    comment_revision_id   TEXT    NOT NULL UNIQUE
        REFERENCES local_review_comment_revision(id),
    body_digest           TEXT    NOT NULL,
    frozen_body           TEXT    NOT NULL,
    frozen_thread_content TEXT    NOT NULL,
    selected_by           TEXT    NOT NULL,
    selected_at_ms        INTEGER NOT NULL,
    PRIMARY KEY (batch_id, position),
    UNIQUE (batch_id, thread_id, comment_revision_id),
    CHECK (length(frozen_body) > 0 AND length(frozen_thread_content) > 0)
);
CREATE TABLE publish_override (
    id                         TEXT    NOT NULL PRIMARY KEY,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    actor_kind                 TEXT    NOT NULL CHECK (actor_kind = 'HUMAN'),
    actor_id                   TEXT    NOT NULL,
    reason                     TEXT    NOT NULL,
    created_at_ms              INTEGER NOT NULL,
    CHECK (length(actor_id) > 0 AND length(reason) > 0)
);
CREATE TABLE publish_override_item (
    override_id            TEXT NOT NULL REFERENCES publish_override(id) ON DELETE CASCADE,
    position               INTEGER NOT NULL CHECK (position > 0),
    kind                   TEXT NOT NULL CHECK (kind IN (
        'VALIDATION_FAILURE', 'LOCAL_FEEDBACK')),
    task_blocker_id        TEXT NOT NULL UNIQUE REFERENCES task_blocker(id),
    validation_evidence_id TEXT UNIQUE REFERENCES validation_evidence(id),
    comment_revision_id    TEXT UNIQUE REFERENCES local_review_comment_revision(id),
    acknowledged_at_ms     INTEGER NOT NULL,
    PRIMARY KEY (override_id, position),
    CHECK ((kind = 'VALIDATION_FAILURE' AND validation_evidence_id IS NOT NULL
            AND comment_revision_id IS NULL)
        OR (kind = 'LOCAL_FEEDBACK' AND validation_evidence_id IS NULL
            AND comment_revision_id IS NOT NULL))
);
CREATE TABLE promotion_manifest (
    id                         TEXT    NOT NULL PRIMARY KEY,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    pr_id                      TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    policy_revision_id         TEXT    NOT NULL REFERENCES task_policy_revision(id),
    revision                   INTEGER NOT NULL CHECK (revision > 0),
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    route                      TEXT    NOT NULL CHECK (route IN ('DIRECT', 'FORK')),
    base_repository_id         TEXT    NOT NULL,
    head_repository_id         TEXT    NOT NULL,
    publish_repository_id      TEXT    NOT NULL,
    branch_name                TEXT    NOT NULL,
    head_ref                   TEXT    NOT NULL,
    base_branch                TEXT    NOT NULL,
    require_clean_worktree             INTEGER NOT NULL CHECK (require_clean_worktree = 1),
    minimum_commits_ahead              INTEGER NOT NULL CHECK (minimum_commits_ahead > 0),
    require_branch_match            INTEGER NOT NULL CHECK (require_branch_match = 1),
    require_base_match              INTEGER NOT NULL CHECK (require_base_match = 1),
    require_publish_permission           INTEGER NOT NULL CHECK (require_publish_permission = 1),
    pr_title                   TEXT    NOT NULL,
    pr_body                    TEXT    NOT NULL,
    pr_content_revision        INTEGER NOT NULL CHECK (pr_content_revision > 0),
    pr_content_digest          TEXT    NOT NULL,
    created_at_ms              INTEGER NOT NULL,
    UNIQUE (local_development_stage_id, revision),
    UNIQUE (local_development_stage_id, code_fingerprint, head_sha,
        pr_content_revision, policy_revision_id),
    CHECK (length(branch_name) > 0 AND length(base_branch) > 0
        AND length(pr_title) > 0 AND length(pr_content_digest) > 0),
    CHECK ((route = 'DIRECT'
            AND base_repository_id = head_repository_id
            AND head_repository_id = publish_repository_id
            AND head_ref = branch_name)
        OR (route = 'FORK'
            AND base_repository_id <> head_repository_id
            AND head_repository_id = publish_repository_id
            AND instr(head_repository_id, '/') > 1
            AND head_ref = substr(
                head_repository_id, 1, instr(head_repository_id, '/') - 1)
                || ':' || branch_name))
);
CREATE TABLE publish_authorization (
    id                         TEXT    NOT NULL PRIMARY KEY,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    manifest_id                TEXT    NOT NULL UNIQUE REFERENCES promotion_manifest(id),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    validation_evidence_id     TEXT    NOT NULL REFERENCES validation_evidence(id),
    brain_review_episode_id    TEXT    NOT NULL REFERENCES brain_review_episode(id),
    pr_id                      TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    policy_revision_id         TEXT    NOT NULL REFERENCES task_policy_revision(id),
    publish_override_id        TEXT REFERENCES publish_override(id),
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    route                      TEXT    NOT NULL CHECK (route IN ('DIRECT', 'FORK')),
    base_repository_id         TEXT    NOT NULL,
    head_repository_id         TEXT    NOT NULL,
    publish_repository_id      TEXT    NOT NULL,
    branch_name                TEXT    NOT NULL,
    head_ref                   TEXT    NOT NULL,
    base_branch                TEXT    NOT NULL,
    pr_content_revision        INTEGER NOT NULL CHECK (pr_content_revision > 0),
    pr_content_digest          TEXT    NOT NULL,
    consent_kind               TEXT    NOT NULL CHECK (consent_kind IN (
        'HUMAN', 'STANDING_TASK')),
    consent_id                 TEXT    NOT NULL,
    actor_id                   TEXT    NOT NULL,
    brain_basis                TEXT    NOT NULL CHECK (brain_basis IN (
        'APPROVED', 'HUMAN_ESCALATION')),
    brain_escalation_reason    TEXT,
    authorized_operation_id    TEXT    NOT NULL UNIQUE,
    authorized_attempt         INTEGER NOT NULL CHECK (authorized_attempt > 0),
    created_at_ms              INTEGER NOT NULL,
    revoked_at_ms              INTEGER,
    consumed_at_ms             INTEGER,
    outcome                    TEXT CHECK (outcome IN ('PUBLISHED', 'CANCELED', 'SUPERSEDED')),
    CHECK (revoked_at_ms IS NULL OR consumed_at_ms IS NULL),
    CHECK ((consumed_at_ms IS NULL) = (outcome IS NULL)),
    CHECK ((brain_basis = 'HUMAN_ESCALATION')
        = (brain_escalation_reason IS NOT NULL))
);
CREATE UNIQUE INDEX idx_publish_authorization_one_active
    ON publish_authorization(task_id)
    WHERE revoked_at_ms IS NULL AND consumed_at_ms IS NULL;
CREATE TABLE publish_operation (
    id                         TEXT    NOT NULL PRIMARY KEY,
    publish_authorization_id   TEXT    NOT NULL UNIQUE
        REFERENCES publish_authorization(id),
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    operation_id               TEXT    NOT NULL UNIQUE,
    semantic_attempt           INTEGER NOT NULL CHECK (semantic_attempt > 0),
    code_fingerprint           TEXT    NOT NULL,
    expected_head_sha          TEXT    NOT NULL,
    expected_base_sha          TEXT    NOT NULL,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'SUCCEEDED', 'FAILED',
        'CANCELED', 'SUPERSEDED', 'INDETERMINATE')),
    remote_repository_id       TEXT,
    remote_pr_number           INTEGER,
    remote_pr_url              TEXT,
    remote_head_ref            TEXT,
    remote_head_sha            TEXT,
    remote_base_sha            TEXT,
    result_evidence            TEXT,
    requested_at_ms            INTEGER NOT NULL,
    completed_at_ms            INTEGER,
    error_message              TEXT,
    CHECK (
        (status IN ('REQUESTED', 'DISPATCHED')
            AND remote_repository_id IS NULL AND remote_pr_number IS NULL
            AND remote_pr_url IS NULL AND remote_head_ref IS NULL
            AND remote_head_sha IS NULL AND remote_base_sha IS NULL
            AND result_evidence IS NULL AND completed_at_ms IS NULL
            AND error_message IS NULL)
        OR (status = 'SUCCEEDED'
            AND remote_repository_id IS NOT NULL AND remote_pr_number > 0
            AND remote_pr_url IS NOT NULL AND remote_head_ref IS NOT NULL
            AND remote_head_sha IS NOT NULL AND remote_base_sha IS NOT NULL
            AND result_evidence IS NOT NULL AND completed_at_ms IS NOT NULL
            AND error_message IS NULL)
        OR (status IN ('FAILED', 'CANCELED', 'SUPERSEDED', 'INDETERMINATE')
            AND remote_repository_id IS NULL AND remote_pr_number IS NULL
            AND remote_pr_url IS NULL AND remote_head_ref IS NULL
            AND remote_head_sha IS NULL AND remote_base_sha IS NULL
            AND result_evidence IS NULL AND completed_at_ms IS NOT NULL
            AND error_message IS NOT NULL))
);
CREATE UNIQUE INDEX idx_publish_operation_one_active
    ON publish_operation(task_id)
    WHERE status IN ('REQUESTED', 'DISPATCHED');
CREATE TABLE publish_effect_step (
    id                    TEXT    NOT NULL PRIMARY KEY,
    publish_operation_id  TEXT    NOT NULL
        REFERENCES publish_operation(id) ON DELETE CASCADE,
    ordinal               INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 6),
    kind                  TEXT    NOT NULL CHECK (kind IN (
        'VERIFY_SUBJECT', 'RECONCILE_BRANCH_BASE', 'PUSH_BRANCH',
        'CREATE_OR_ADOPT_DRAFT_PR', 'FETCH_REMOTE_DETAIL',
        'PROVE_REMOTE_HEAD')),
    idempotency_key       TEXT    NOT NULL UNIQUE,
    status                TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE')),
    attempt_count         INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit         INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode            TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner           TEXT,
    claimed_at_ms         INTEGER,
    lease_until_ms        INTEGER,
    evidence              TEXT,
    last_error            TEXT,
    completed_at_ms       INTEGER,
    UNIQUE (publish_operation_id, ordinal),
    UNIQUE (publish_operation_id, kind),
    CHECK (
        (status = 'REQUESTED'
            AND claim_mode IS NULL AND claim_owner IS NULL
            AND claimed_at_ms IS NULL AND lease_until_ms IS NULL
            AND evidence IS NULL AND last_error IS NULL
            AND completed_at_ms IS NULL)
        OR (status = 'CLAIMED'
            AND claim_mode IS NOT NULL AND claim_owner IS NOT NULL
            AND claimed_at_ms IS NOT NULL AND lease_until_ms IS NOT NULL
            AND evidence IS NULL AND last_error IS NULL
            AND completed_at_ms IS NULL)
        OR (status = 'SUCCEEDED'
            AND claim_mode IS NULL AND claim_owner IS NULL
            AND claimed_at_ms IS NULL AND lease_until_ms IS NULL
            AND evidence IS NOT NULL AND last_error IS NULL
            AND completed_at_ms IS NOT NULL)
        OR (status IN ('FAILED', 'INDETERMINATE')
            AND claim_mode IS NULL AND claim_owner IS NULL
            AND claimed_at_ms IS NULL AND lease_until_ms IS NULL
            AND evidence IS NULL AND last_error IS NOT NULL
            AND completed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_publish_effect_step_one_claimed
    ON publish_effect_step(publish_operation_id)
    WHERE status = 'CLAIMED';
CREATE TABLE remote_pr_binding (
    id                       TEXT    NOT NULL PRIMARY KEY,
    task_id                  TEXT    NOT NULL UNIQUE
        REFERENCES tasks(id) ON DELETE CASCADE,
    pr_id                    TEXT    NOT NULL UNIQUE REFERENCES pr(id) ON DELETE CASCADE,
    publish_operation_id     TEXT    NOT NULL UNIQUE REFERENCES publish_operation(id),
    publish_authorization_id TEXT    NOT NULL UNIQUE REFERENCES publish_authorization(id),
    manifest_id              TEXT    NOT NULL UNIQUE REFERENCES promotion_manifest(id),
    route                    TEXT    NOT NULL CHECK (route IN ('DIRECT', 'FORK')),
    base_repository_id       TEXT    NOT NULL,
    head_repository_id       TEXT    NOT NULL,
    remote_repository_id     TEXT    NOT NULL,
    remote_pr_number         INTEGER NOT NULL CHECK (remote_pr_number > 0),
    remote_pr_url            TEXT    NOT NULL,
    remote_head_ref          TEXT    NOT NULL,
    remote_head_sha          TEXT    NOT NULL,
    remote_base_sha          TEXT    NOT NULL,
    evidence                 TEXT    NOT NULL,
    bound_at_ms              INTEGER NOT NULL,
    UNIQUE (remote_repository_id, remote_pr_number)
);
CREATE UNIQUE INDEX idx_stage_receipt_owner_identity
    ON stage(id, task_id);
CREATE UNIQUE INDEX idx_stage_receipt_full_identity
    ON stage(id, task_id, kind, generation);
CREATE TABLE trunk_command_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    cause                    TEXT    NOT NULL CHECK (cause IN (
        'MARK_IDLE', 'ACTIVATE', 'ARCHIVE')),
    actor                    TEXT    NOT NULL,
    disposition              TEXT    NOT NULL CHECK (disposition = 'APPLIED'),
    expected_version         INTEGER NOT NULL CHECK (expected_version >= 0),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'ACTIVE', 'IDLE', 'ARCHIVED')),
    returned_version         INTEGER NOT NULL CHECK (returned_version >= 0),
    recorded_at_ms           INTEGER NOT NULL,
    UNIQUE (trunk_id, command_id),
    CHECK (returned_version = expected_version + 1)
);
CREATE TABLE task_command_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'REQUEST_PAUSE', 'COMPLETE_PAUSE', 'REQUEST_RESUME', 'COMPLETE_RESUME',
        'REQUEST_ARCHIVE', 'COMPLETE_ARCHIVE', 'REQUEST_CANCEL',
        'ACCEPT_PROVISIONING', 'OPEN_REPLAN_PLAN', 'OPEN_CANCELED_CLEANUP',
        'OPEN_MERGED_CLEANUP', 'OPEN_REMOTE_CLOSED_CLEANUP',
        'ACCEPT_BRAIN_VERDICT', 'ACCEPT_CLEANUP_COMPLETION',
        'OPEN_LOCAL_DEVELOPMENT', 'OPEN_REMOTE_DEVELOPMENT')),
    actor                             TEXT    NOT NULL,
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),

    -- Present only when the command itself carried a structural Task fence.
    expected_task_epoch               INTEGER CHECK (expected_task_epoch > 0),
    expected_task_version             INTEGER CHECK (expected_task_version >= 0),

    -- Optional Task command ResultFence, preserved field-for-field.
    subject_task_epoch                INTEGER CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    brain_verdict                     TEXT CHECK (brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    proof_id                          TEXT,
    next_stage_id                     TEXT,
    next_stage_kind                   TEXT CHECK (next_stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT', 'CLEANUP')),
    next_stage_generation             INTEGER CHECK (next_stage_generation > 0),

    -- Exact returned TaskManager.State. These are a historical replay
    -- snapshot and intentionally are not compared to today's Task row.
    returned_trunk_id                 TEXT    NOT NULL REFERENCES threads(id),
    returned_lifecycle                TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'PROVISIONING', 'ACTIVE', 'PAUSING', 'PAUSED', 'RESUMING',
        'ARCHIVING', 'ARCHIVED', 'CANCELING', 'CLEANING',
        'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    returned_epoch                    INTEGER NOT NULL CHECK (returned_epoch > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_current_stage_id         TEXT,
    returned_pending_task_epoch       INTEGER CHECK (returned_pending_task_epoch > 0),
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    returned_last_brain_verdict       TEXT CHECK (returned_last_brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    returned_last_brain_task_epoch    INTEGER CHECK (returned_last_brain_task_epoch > 0),
    returned_last_brain_stage_id      TEXT,
    returned_last_brain_stage_generation INTEGER,
    returned_last_brain_operation_id  TEXT,
    returned_last_brain_attempt       INTEGER,
    returned_last_brain_code_fingerprint TEXT,
    returned_last_brain_head_sha      TEXT,
    returned_last_brain_base_sha      TEXT,
    returned_terminal_intent          TEXT CHECK (returned_terminal_intent IN (
        'CANCELED', 'COMPLETED', 'REMOTE_CLOSED')),
    recorded_at_ms                    INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    CHECK ((expected_task_epoch IS NULL AND expected_task_version IS NULL)
        OR (expected_task_epoch IS NOT NULL AND expected_task_version IS NOT NULL)),
    CHECK ((expected_task_epoch IS NULL) = (cause = 'ACCEPT_BRAIN_VERDICT')),
    CHECK (cause = 'ACCEPT_BRAIN_VERDICT'
        OR returned_version = expected_task_version + 1),
    CHECK ((subject_operation_id IS NULL
            AND subject_task_epoch IS NULL AND subject_stage_id IS NULL
            AND subject_stage_generation IS NULL AND subject_attempt IS NULL
            AND subject_expected_code_fingerprint IS NULL
            AND subject_expected_head_sha IS NULL
            AND subject_expected_base_sha IS NULL)
        OR (subject_operation_id IS NOT NULL AND length(subject_operation_id) > 0
            AND subject_task_epoch IS NOT NULL AND subject_attempt > 0
            AND ((subject_stage_id IS NULL AND subject_stage_generation = 0)
                OR (subject_stage_id IS NOT NULL
                    AND subject_stage_generation > 0)))),
    CHECK ((next_stage_id IS NULL AND next_stage_kind IS NULL
            AND next_stage_generation IS NULL)
        OR (next_stage_id IS NOT NULL AND next_stage_kind IS NOT NULL
            AND next_stage_generation IS NOT NULL)),
    CHECK ((returned_pending_operation_id IS NULL
            AND returned_pending_task_epoch IS NULL
            AND returned_pending_stage_id IS NULL
            AND returned_pending_stage_generation IS NULL
            AND returned_pending_attempt IS NULL
            AND returned_pending_code_fingerprint IS NULL
            AND returned_pending_head_sha IS NULL
            AND returned_pending_base_sha IS NULL)
        OR (returned_pending_operation_id IS NOT NULL
            AND length(returned_pending_operation_id) > 0
            AND returned_pending_task_epoch IS NOT NULL
            AND returned_pending_attempt > 0
            AND ((returned_pending_stage_id IS NULL
                    AND returned_pending_stage_generation = 0)
                OR (returned_pending_stage_id IS NOT NULL
                    AND returned_pending_stage_generation > 0)))),
    CHECK ((returned_last_brain_operation_id IS NULL
            AND returned_last_brain_verdict IS NULL
            AND returned_last_brain_task_epoch IS NULL
            AND returned_last_brain_stage_id IS NULL
            AND returned_last_brain_stage_generation IS NULL
            AND returned_last_brain_attempt IS NULL
            AND returned_last_brain_code_fingerprint IS NULL
            AND returned_last_brain_head_sha IS NULL
            AND returned_last_brain_base_sha IS NULL)
        OR (returned_last_brain_operation_id IS NOT NULL
            AND length(returned_last_brain_operation_id) > 0
            AND returned_last_brain_verdict IS NOT NULL
            AND returned_last_brain_task_epoch IS NOT NULL
            AND returned_last_brain_attempt > 0
            AND ((returned_last_brain_stage_id IS NULL
                    AND returned_last_brain_stage_generation = 0)
                OR (returned_last_brain_stage_id IS NOT NULL
                    AND returned_last_brain_stage_generation > 0)))),
    CHECK ((cause = 'ACCEPT_BRAIN_VERDICT') = (brain_verdict IS NOT NULL)),
    CHECK ((proof_id IS NOT NULL) = (cause IN (
        'COMPLETE_PAUSE', 'COMPLETE_RESUME', 'COMPLETE_ARCHIVE',
        'ACCEPT_PROVISIONING', 'OPEN_REPLAN_PLAN', 'OPEN_CANCELED_CLEANUP',
        'OPEN_MERGED_CLEANUP', 'OPEN_REMOTE_CLOSED_CLEANUP',
        'OPEN_LOCAL_DEVELOPMENT'))),
    CHECK ((next_stage_id IS NOT NULL) = (cause IN (
        'ACCEPT_PROVISIONING', 'OPEN_REPLAN_PLAN', 'OPEN_CANCELED_CLEANUP',
        'OPEN_MERGED_CLEANUP', 'OPEN_REMOTE_CLOSED_CLEANUP',
        'OPEN_LOCAL_DEVELOPMENT', 'OPEN_REMOTE_DEVELOPMENT'))),
    CHECK ((subject_operation_id IS NOT NULL) = (cause IN (
        'ACCEPT_PROVISIONING', 'ACCEPT_BRAIN_VERDICT',
        'ACCEPT_CLEANUP_COMPLETION', 'OPEN_REMOTE_DEVELOPMENT'))),
    CHECK (cause NOT IN ('ACCEPT_PROVISIONING', 'OPEN_REPLAN_PLAN')
        OR next_stage_kind = 'PLAN'),
    CHECK (cause NOT IN ('OPEN_CANCELED_CLEANUP', 'OPEN_MERGED_CLEANUP',
            'OPEN_REMOTE_CLOSED_CLEANUP')
        OR next_stage_kind = 'CLEANUP'),
    CHECK (cause <> 'OPEN_LOCAL_DEVELOPMENT'
        OR next_stage_kind = 'LOCAL_DEVELOPMENT'),
    CHECK (cause <> 'OPEN_REMOTE_DEVELOPMENT'
        OR next_stage_kind = 'REMOTE_DEVELOPMENT'),
    CHECK (disposition <> 'SUPERSEDED' OR cause = 'ACCEPT_BRAIN_VERDICT'),
    CHECK (disposition <> 'SUPERSEDED' OR subject_operation_id IS NOT NULL),
    CHECK (returned_lifecycle NOT IN (
            'PROVISIONING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
        OR returned_current_stage_id IS NULL),
    CHECK (returned_lifecycle IN (
            'PROVISIONING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
        OR returned_current_stage_id IS NOT NULL),
    CHECK ((returned_lifecycle IN ('CANCELING', 'CLEANING'))
        = (returned_terminal_intent IS NOT NULL)
        OR returned_lifecycle IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    CHECK (returned_lifecycle NOT IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
        OR returned_terminal_intent = returned_lifecycle),
    CHECK (returned_lifecycle NOT IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
        OR returned_pending_operation_id IS NULL),
    FOREIGN KEY (returned_current_stage_id, task_id)
        REFERENCES stage(id, task_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (next_stage_id, task_id, next_stage_kind, next_stage_generation)
        REFERENCES stage(id, task_id, kind, generation)
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE stage_command_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'OPEN_INITIAL_PLAN', 'OPEN_REPLAN_PLAN', 'ACCEPT_DRAFTED',
        'ACCEPT_PLAN_BRAIN_FINDINGS', 'ACCEPT_PLAN_BRAIN_APPROVAL',
        'REVISE_BEFORE_APPROVAL', 'APPROVE_PLAN', 'OPEN_LOCAL_DEVELOPMENT',
        'ACCEPT_IMPLEMENTATION', 'ACCEPT_VALIDATION', 'ACCEPT_BRAIN_APPROVAL',
        'ACCEPT_BRAIN_FINDINGS', 'ACCEPT_BRAIN_FIXES', 'SUBMIT_LOCAL_FEEDBACK',
        'AUTHORIZE_PUBLISH', 'ACCEPT_LOCAL_FEEDBACK_FIXES', 'ACCEPT_PUBLISHED',
        'OPEN_REMOTE_DEVELOPMENT', 'ACCEPT_CI', 'ACCEPT_READY',
        'BEGIN_REMOTE_FEEDBACK', 'ACCEPT_REMOTE_FEEDBACK_PUSH',
        'ACCEPT_READINESS', 'AUTHORIZE_MERGE', 'ACCEPT_REMOTE_MERGED',
        'ACCEPT_REMOTE_CLOSED', 'SEAL_FOR_REPLAN',
        'SEAL_FOR_TASK_CANCELLATION', 'OPEN_CANCELED_CLEANUP',
        'OPEN_TERMINAL_CLEANUP', 'ACCEPT_CLEANUP_QUIESCENCE',
        'ACCEPT_CLEANUP_COMPLETE')),
    actor                             TEXT    NOT NULL,
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),

    -- Structural commands carry these; result commands and Stage creation do
    -- not invent a current version/checkpoint fence.
    expected_task_epoch               INTEGER CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT,

    -- Optional command ResultFence, including operation attempt.
    subject_task_epoch                INTEGER CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT,

    -- Exact returned StageManager.State.
    returned_kind                     TEXT    NOT NULL CHECK (returned_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT', 'CLEANUP')),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_checkpoint               TEXT    NOT NULL,
    returned_end_reason               TEXT CHECK (returned_end_reason IN (
        'NORMAL', 'SUPERSEDED_BY_REPLAN', 'TASK_CANCELED',
        'REMOTE_MERGED', 'REMOTE_CLOSED')),
    returned_pending_task_epoch INTEGER CHECK (returned_pending_task_epoch > 0),
    returned_pending_stage_id   TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id TEXT,
    returned_pending_attempt     INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha    TEXT,
    returned_pending_base_sha    TEXT,
    recorded_at_ms               INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK ((expected_task_epoch IS NULL
            AND expected_stage_generation IS NULL
            AND expected_stage_version IS NULL)
        OR (expected_task_epoch IS NOT NULL
            AND expected_stage_generation IS NOT NULL
            AND expected_stage_version IS NOT NULL)),
    CHECK (source_checkpoint IS NULL OR expected_task_epoch IS NOT NULL),
    CHECK (expected_stage_version IS NULL
        OR returned_version = expected_stage_version + 1),
    CHECK ((subject_operation_id IS NULL
            AND subject_task_epoch IS NULL AND subject_stage_id IS NULL
            AND subject_stage_generation IS NULL AND subject_attempt IS NULL
            AND subject_expected_code_fingerprint IS NULL
            AND subject_expected_head_sha IS NULL
            AND subject_expected_base_sha IS NULL)
        OR (subject_operation_id IS NOT NULL AND length(subject_operation_id) > 0
            AND subject_task_epoch IS NOT NULL AND subject_attempt > 0
            AND ((subject_stage_id IS NULL AND subject_stage_generation = 0)
                OR (subject_stage_id IS NOT NULL
                    AND subject_stage_generation > 0)))),
    CHECK ((returned_pending_operation_id IS NULL
            AND returned_pending_task_epoch IS NULL
            AND returned_pending_stage_id IS NULL
            AND returned_pending_stage_generation IS NULL
            AND returned_pending_attempt IS NULL
            AND returned_pending_code_fingerprint IS NULL
            AND returned_pending_head_sha IS NULL
            AND returned_pending_base_sha IS NULL)
        OR (returned_pending_operation_id IS NOT NULL
            AND length(returned_pending_operation_id) > 0
            AND returned_pending_task_epoch IS NOT NULL
            AND returned_pending_attempt > 0
            AND returned_pending_stage_id = stage_id
            AND returned_pending_stage_generation = returned_generation)),
    CHECK (returned_checkpoint <> 'COMPLETED'
        OR returned_end_reason IS NOT NULL),
    CHECK (returned_checkpoint = 'COMPLETED'
        OR returned_end_reason IS NULL
        OR returned_end_reason IN ('SUPERSEDED_BY_REPLAN', 'TASK_CANCELED')),
    CHECK (returned_end_reason NOT IN ('NORMAL', 'REMOTE_MERGED', 'REMOTE_CLOSED')
        OR returned_checkpoint = 'COMPLETED'),
    CHECK (returned_end_reason NOT IN ('REMOTE_MERGED', 'REMOTE_CLOSED')
        OR returned_kind = 'REMOTE_DEVELOPMENT'),
    CHECK (returned_end_reason IS NULL
        OR returned_pending_operation_id IS NULL),
    CHECK (returned_kind <> 'PLAN' OR returned_checkpoint IN (
        'DRAFTING', 'SELF_REVIEW', 'AWAITING_APPROVAL', 'COMPLETED')),
    CHECK (returned_kind <> 'LOCAL_DEVELOPMENT' OR returned_checkpoint IN (
        'IMPLEMENTING', 'VALIDATING', 'BRAIN_REVIEW', 'LOCAL_REVIEW',
        'PUBLISHING', 'ADDRESSING_BRAIN_FINDINGS',
        'ADDRESSING_LOCAL_FEEDBACK', 'COMPLETED')),
    CHECK (returned_kind <> 'REMOTE_DEVELOPMENT' OR returned_checkpoint IN (
        'WAITING_CI', 'AWAITING_READY', 'WAITING_REMOTE_REVIEW',
        'ADDRESSING_REMOTE_FEEDBACK', 'READY_TO_MERGE', 'MERGING', 'COMPLETED')),
    CHECK (returned_kind <> 'CLEANUP' OR returned_checkpoint IN (
        'WAITING_QUIESCENCE', 'CLEANING', 'COMPLETED')),
    CHECK ((proof_id IS NOT NULL) = (cause IN (
        'OPEN_INITIAL_PLAN', 'OPEN_REPLAN_PLAN', 'REVISE_BEFORE_APPROVAL',
        'APPROVE_PLAN', 'OPEN_LOCAL_DEVELOPMENT', 'SUBMIT_LOCAL_FEEDBACK',
        'AUTHORIZE_PUBLISH', 'BEGIN_REMOTE_FEEDBACK', 'AUTHORIZE_MERGE',
        'ACCEPT_REMOTE_MERGED', 'ACCEPT_REMOTE_CLOSED', 'SEAL_FOR_REPLAN',
        'SEAL_FOR_TASK_CANCELLATION', 'OPEN_CANCELED_CLEANUP',
        'OPEN_TERMINAL_CLEANUP', 'ACCEPT_CLEANUP_QUIESCENCE'))),
    CHECK ((subject_operation_id IS NOT NULL) = (cause IN (
        'OPEN_INITIAL_PLAN', 'ACCEPT_DRAFTED',
        'ACCEPT_PLAN_BRAIN_FINDINGS', 'ACCEPT_PLAN_BRAIN_APPROVAL',
        'ACCEPT_IMPLEMENTATION', 'ACCEPT_VALIDATION', 'ACCEPT_BRAIN_APPROVAL',
        'ACCEPT_BRAIN_FINDINGS', 'ACCEPT_BRAIN_FIXES', 'AUTHORIZE_PUBLISH',
        'ACCEPT_LOCAL_FEEDBACK_FIXES', 'ACCEPT_PUBLISHED',
        'OPEN_REMOTE_DEVELOPMENT', 'ACCEPT_CI', 'ACCEPT_READY',
        'ACCEPT_REMOTE_FEEDBACK_PUSH', 'ACCEPT_READINESS', 'AUTHORIZE_MERGE',
        'ACCEPT_CLEANUP_COMPLETE'))),
    CHECK (cause NOT IN (
        'OPEN_INITIAL_PLAN', 'OPEN_REPLAN_PLAN', 'OPEN_LOCAL_DEVELOPMENT',
        'OPEN_REMOTE_DEVELOPMENT', 'OPEN_CANCELED_CLEANUP',
        'OPEN_TERMINAL_CLEANUP', 'ACCEPT_DRAFTED',
        'ACCEPT_PLAN_BRAIN_FINDINGS', 'ACCEPT_PLAN_BRAIN_APPROVAL',
        'ACCEPT_IMPLEMENTATION', 'ACCEPT_VALIDATION', 'ACCEPT_BRAIN_APPROVAL',
        'ACCEPT_BRAIN_FINDINGS', 'ACCEPT_BRAIN_FIXES',
        'ACCEPT_LOCAL_FEEDBACK_FIXES', 'ACCEPT_PUBLISHED', 'ACCEPT_CI',
        'ACCEPT_READY', 'ACCEPT_REMOTE_FEEDBACK_PUSH', 'ACCEPT_READINESS',
        'ACCEPT_CLEANUP_COMPLETE')
        OR expected_task_epoch IS NULL),
    CHECK (cause IN (
        'OPEN_INITIAL_PLAN', 'OPEN_REPLAN_PLAN', 'OPEN_LOCAL_DEVELOPMENT',
        'OPEN_REMOTE_DEVELOPMENT', 'OPEN_CANCELED_CLEANUP',
        'OPEN_TERMINAL_CLEANUP', 'ACCEPT_DRAFTED',
        'ACCEPT_PLAN_BRAIN_FINDINGS', 'ACCEPT_PLAN_BRAIN_APPROVAL',
        'ACCEPT_IMPLEMENTATION', 'ACCEPT_VALIDATION', 'ACCEPT_BRAIN_APPROVAL',
        'ACCEPT_BRAIN_FINDINGS', 'ACCEPT_BRAIN_FIXES',
        'ACCEPT_LOCAL_FEEDBACK_FIXES', 'ACCEPT_PUBLISHED', 'ACCEPT_CI',
        'ACCEPT_READY', 'ACCEPT_REMOTE_FEEDBACK_PUSH', 'ACCEPT_READINESS',
        'ACCEPT_CLEANUP_COMPLETE')
        OR expected_task_epoch IS NOT NULL),
    CHECK ((source_checkpoint IS NOT NULL) = (cause IN (
        'REVISE_BEFORE_APPROVAL', 'APPROVE_PLAN', 'SUBMIT_LOCAL_FEEDBACK',
        'AUTHORIZE_PUBLISH', 'BEGIN_REMOTE_FEEDBACK', 'AUTHORIZE_MERGE',
        'ACCEPT_CLEANUP_QUIESCENCE'))),
    CHECK (source_checkpoint IS NULL
        OR (cause IN ('REVISE_BEFORE_APPROVAL', 'APPROVE_PLAN')
            AND source_checkpoint = 'AWAITING_APPROVAL')
        OR (cause IN ('SUBMIT_LOCAL_FEEDBACK', 'AUTHORIZE_PUBLISH')
            AND source_checkpoint = 'LOCAL_REVIEW')
        OR (cause = 'BEGIN_REMOTE_FEEDBACK'
            AND source_checkpoint = 'WAITING_REMOTE_REVIEW')
        OR (cause = 'AUTHORIZE_MERGE'
            AND source_checkpoint = 'READY_TO_MERGE')
        OR (cause = 'ACCEPT_CLEANUP_QUIESCENCE'
            AND source_checkpoint = 'WAITING_QUIESCENCE')),
    CHECK (disposition <> 'SUPERSEDED' OR subject_operation_id IS NOT NULL),
    FOREIGN KEY (stage_id, task_id, returned_kind, returned_generation)
        REFERENCES stage(id, task_id, kind, generation)
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE "task_assignment" (
    id                      TEXT    NOT NULL PRIMARY KEY,
    trunk_id                TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    kind                    TEXT    NOT NULL CHECK (kind IN (
        'NEW_FROM_TRUNK', 'EXISTING_OWN_PR', 'REVIEW_FINDINGS',
        'ISSUE', 'AUTOMATION', 'QUALITY_SCAN')),
    source_id               TEXT,
    repository_id           TEXT,
    pr_number               INTEGER,
    remote_head_sha         TEXT,
    planning_base_sha       TEXT,
    plan_seed               TEXT,
    prompt                  TEXT,
    producer                TEXT,
    reason                  TEXT,
    selected_findings_json  TEXT,
    created_by              TEXT    NOT NULL,
    created_at_ms           INTEGER NOT NULL,
    base_repository_id      TEXT,
    head_repository_id      TEXT,
    base_ref                TEXT,
    head_ref                TEXT,
    remote_base_sha         TEXT,
    repository_route        TEXT CHECK (repository_route IN ('DIRECT', 'FORK')),
    creation_authorization_id TEXT UNIQUE
        REFERENCES trunk_task_creation_authorization(id)
        DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX idx_task_assignment_trunk_created
    ON task_assignment(trunk_id, created_at_ms);
CREATE TABLE task_assignment_review_finding (
    assignment_id       TEXT    NOT NULL
        REFERENCES task_assignment(id) ON DELETE CASCADE,
    position            INTEGER NOT NULL CHECK (position > 0),
    source_review_id    TEXT    NOT NULL,
    finding_id          TEXT    NOT NULL,
    finding_revision    INTEGER NOT NULL CHECK (finding_revision > 0),
    content_digest      TEXT    NOT NULL,
    PRIMARY KEY (assignment_id, position),
    UNIQUE (assignment_id, finding_id),
    CHECK (length(source_review_id) > 0 AND length(finding_id) > 0
        AND length(content_digest) > 0)
);
CREATE TABLE task_provision_target (
    task_id                TEXT    NOT NULL PRIMARY KEY
        REFERENCES tasks(id) ON DELETE CASCADE,
    repository_id          TEXT    NOT NULL,
    publish_repository_id  TEXT    NOT NULL,
    branch_name            TEXT    NOT NULL,
    worktree_path          TEXT    NOT NULL UNIQUE,
    created_at_ms          INTEGER NOT NULL,
    UNIQUE (publish_repository_id, branch_name),
    CHECK (length(repository_id) > 0 AND length(publish_repository_id) > 0
        AND length(branch_name) > 0 AND length(worktree_path) > 0)
);
CREATE TABLE task_creation_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    workspace_id             TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    actor                    TEXT    NOT NULL,
    authorization_id         TEXT    NOT NULL UNIQUE
        REFERENCES trunk_task_creation_authorization(id),
    task_id                  TEXT    NOT NULL UNIQUE
        REFERENCES tasks(id) DEFERRABLE INITIALLY DEFERRED,
    task_seq                 INTEGER NOT NULL CHECK (task_seq > 0),
    task_epoch               INTEGER NOT NULL CHECK (task_epoch = 1),
    task_version             INTEGER NOT NULL CHECK (task_version = 0),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle = 'PROVISIONING'),
    assignment_id            TEXT    NOT NULL UNIQUE REFERENCES task_assignment(id),
    policy_revision_id       TEXT    NOT NULL REFERENCES task_policy_revision(id),
    task_brain_id            TEXT    NOT NULL UNIQUE REFERENCES task_brain(id),
    provision_operation_id   TEXT    NOT NULL UNIQUE REFERENCES provision_task_operation(id),
    dispatch_ticket_id       TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    operation_id             TEXT    NOT NULL UNIQUE,
    semantic_attempt         INTEGER NOT NULL CHECK (semantic_attempt = 1),
    requested_branch_name    TEXT    NOT NULL,
    requested_worktree_path  TEXT    NOT NULL,
    recorded_at_ms           INTEGER NOT NULL,
    UNIQUE (trunk_id, command_id),
    CHECK (length(actor) > 0 AND length(operation_id) > 0
        AND length(requested_branch_name) > 0
        AND length(requested_worktree_path) > 0)
);
CREATE UNIQUE INDEX idx_tasks_creation_receipt
    ON tasks(creation_receipt_id) WHERE creation_receipt_id IS NOT NULL;
CREATE TABLE task_pause_evidence (
    barrier_id             TEXT    NOT NULL PRIMARY KEY
        REFERENCES task_quiescence_barrier(id),
    task_id                TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch             INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id               TEXT    NOT NULL REFERENCES stage(id),
    stage_generation       INTEGER NOT NULL CHECK (stage_generation > 0),
    restore_checkpoint     TEXT    NOT NULL,
    code_fingerprint       TEXT    NOT NULL,
    head_sha               TEXT    NOT NULL,
    base_sha               TEXT    NOT NULL,
    barrier_completed_at_ms INTEGER NOT NULL,
    stop_evidence_digest   TEXT    NOT NULL,
    status                 TEXT    NOT NULL CHECK (status = 'SATISFIED'),
    recorded_at_ms         INTEGER NOT NULL CHECK (recorded_at_ms > 0),
    CHECK (length(trim(code_fingerprint)) > 0
        AND length(trim(head_sha)) > 0
        AND length(trim(base_sha)) > 0
        AND length(trim(stop_evidence_digest)) > 0
        AND barrier_completed_at_ms <= recorded_at_ms),
    UNIQUE (barrier_id, task_id, task_epoch)
);
CREATE VIEW task_pause_evidence_digest_v230 AS
SELECT evidence.barrier_id,
       'pause:v1:' || lower(hex(evidence.task_id)) || ':'
           || evidence.task_epoch || ':' || lower(hex(evidence.barrier_id)) || ':'
           || lower(hex(evidence.stage_id)) || ':' || evidence.stage_generation || ':'
           || lower(hex(evidence.restore_checkpoint)) || ':'
           || lower(hex(evidence.code_fingerprint)) || ':'
           || lower(hex(evidence.head_sha)) || ':' || lower(hex(evidence.base_sha)) || ':'
           || evidence.barrier_completed_at_ms || ':' || evidence.recorded_at_ms
           AS content_digest
FROM task_pause_evidence evidence;
CREATE TABLE task_resume_reconciliation (
    id                                  TEXT    NOT NULL PRIMARY KEY,
    task_id                             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                          INTEGER NOT NULL CHECK (task_epoch > 0),
    pause_barrier_id                    TEXT    NOT NULL UNIQUE
        REFERENCES task_pause_evidence(barrier_id),
    stage_id                            TEXT    NOT NULL REFERENCES stage(id),
    stage_generation                    INTEGER NOT NULL CHECK (stage_generation > 0),
    restore_checkpoint                  TEXT    NOT NULL,
    paused_code_fingerprint             TEXT    NOT NULL,
    paused_head_sha                     TEXT    NOT NULL,
    paused_base_sha                     TEXT    NOT NULL,
    active_task_turn_count              INTEGER NOT NULL CHECK (active_task_turn_count = 0),
    active_stage_turn_count             INTEGER NOT NULL CHECK (active_stage_turn_count = 0),
    active_plan_review_count            INTEGER NOT NULL CHECK (active_plan_review_count = 0),
    active_validation_count             INTEGER NOT NULL CHECK (active_validation_count = 0),
    active_brain_episode_count           INTEGER NOT NULL CHECK (active_brain_episode_count = 0),
    active_provision_operation_count     INTEGER NOT NULL CHECK (active_provision_operation_count = 0),
    active_writer_dispatch_count         INTEGER NOT NULL CHECK (active_writer_dispatch_count = 0),
    active_agent_execution_count         INTEGER NOT NULL CHECK (active_agent_execution_count = 0),
    unreconciled_execution_count         INTEGER NOT NULL CHECK (unreconciled_execution_count = 0),
    live_writer_capacity_count           INTEGER NOT NULL CHECK (live_writer_capacity_count = 0),
    live_worktree_lease_count            INTEGER NOT NULL CHECK (live_worktree_lease_count = 0),
    active_publish_operation_count       INTEGER NOT NULL CHECK (active_publish_operation_count = 0),
    unreconciled_publish_operation_count INTEGER NOT NULL CHECK (unreconciled_publish_operation_count = 0),
    active_publish_effect_count          INTEGER NOT NULL CHECK (active_publish_effect_count = 0),
    reconciliation_digest               TEXT    NOT NULL,
    status                              TEXT    NOT NULL CHECK (status = 'SATISFIED'),
    recorded_at_ms                      INTEGER NOT NULL CHECK (recorded_at_ms > 0),
    CHECK (length(trim(paused_code_fingerprint)) > 0
        AND length(trim(paused_head_sha)) > 0
        AND length(trim(paused_base_sha)) > 0
        AND length(trim(reconciliation_digest)) > 0),
    UNIQUE (id, task_id, task_epoch)
);
CREATE VIEW task_resume_evidence_digest_v230 AS
SELECT evidence.id,
       'resume:v1:' || lower(hex(evidence.task_id)) || ':' || evidence.task_epoch || ':'
           || lower(hex(evidence.id)) || ':' || lower(hex(evidence.pause_barrier_id)) || ':'
           || lower(hex(evidence.stage_id)) || ':' || evidence.stage_generation || ':'
           || lower(hex(evidence.restore_checkpoint)) || ':'
           || lower(hex(evidence.paused_code_fingerprint)) || ':'
           || lower(hex(evidence.paused_head_sha)) || ':'
           || lower(hex(evidence.paused_base_sha)) || ':'
           || evidence.active_task_turn_count || ':' || evidence.active_stage_turn_count || ':'
           || evidence.active_plan_review_count || ':' || evidence.active_validation_count || ':'
           || evidence.active_brain_episode_count || ':'
           || evidence.active_provision_operation_count || ':'
           || evidence.active_writer_dispatch_count || ':'
           || evidence.active_agent_execution_count || ':'
           || evidence.unreconciled_execution_count || ':'
           || evidence.live_writer_capacity_count || ':'
           || evidence.live_worktree_lease_count || ':'
           || evidence.active_publish_operation_count || ':'
           || evidence.unreconciled_publish_operation_count || ':'
           || evidence.active_publish_effect_count || ':'
           || evidence.recorded_at_ms AS content_digest
FROM task_resume_reconciliation evidence;
CREATE TABLE task_archive_liveness (
    id                                   TEXT    NOT NULL PRIMARY KEY,
    task_id                              TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                           INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id                             TEXT    NOT NULL REFERENCES stage(id),
    stage_generation                     INTEGER NOT NULL CHECK (stage_generation > 0),
    active_task_turn_count               INTEGER NOT NULL CHECK (active_task_turn_count = 0),
    active_stage_turn_count              INTEGER NOT NULL CHECK (active_stage_turn_count = 0),
    active_review_turn_count             INTEGER NOT NULL CHECK (active_review_turn_count = 0),
    active_plan_review_count             INTEGER NOT NULL CHECK (active_plan_review_count = 0),
    active_validation_count              INTEGER NOT NULL CHECK (active_validation_count = 0),
    active_brain_episode_count            INTEGER NOT NULL CHECK (active_brain_episode_count = 0),
    active_provision_operation_count      INTEGER NOT NULL CHECK (active_provision_operation_count = 0),
    active_dispatch_count                INTEGER NOT NULL CHECK (active_dispatch_count = 0),
    active_agent_execution_count         INTEGER NOT NULL CHECK (active_agent_execution_count = 0),
    unreconciled_execution_count          INTEGER NOT NULL CHECK (unreconciled_execution_count = 0),
    live_capacity_lease_count             INTEGER NOT NULL CHECK (live_capacity_lease_count = 0),
    live_worktree_lease_count             INTEGER NOT NULL CHECK (live_worktree_lease_count = 0),
    active_quiescence_count               INTEGER NOT NULL CHECK (active_quiescence_count = 0),
    active_replan_count                   INTEGER NOT NULL CHECK (active_replan_count = 0),
    active_feedback_batch_count           INTEGER NOT NULL CHECK (active_feedback_batch_count = 0),
    active_publish_operation_count        INTEGER NOT NULL CHECK (active_publish_operation_count = 0),
    unreconciled_publish_operation_count  INTEGER NOT NULL CHECK (unreconciled_publish_operation_count = 0),
    active_publish_effect_count           INTEGER NOT NULL CHECK (active_publish_effect_count = 0),
    active_publish_authorization_count    INTEGER NOT NULL CHECK (active_publish_authorization_count = 0),
    open_permission_count                 INTEGER NOT NULL CHECK (open_permission_count = 0),
    accepted_terminal_intent_count        INTEGER NOT NULL CHECK (accepted_terminal_intent_count = 0),
    open_cleanup_stage_count              INTEGER NOT NULL CHECK (open_cleanup_stage_count = 0),
    liveness_digest                       TEXT    NOT NULL,
    status                                TEXT    NOT NULL CHECK (status = 'SATISFIED'),
    recorded_at_ms                        INTEGER NOT NULL CHECK (recorded_at_ms > 0),
    CHECK (length(trim(liveness_digest)) > 0),
    UNIQUE (id, task_id, task_epoch)
);
CREATE VIEW task_archive_evidence_digest_v230 AS
SELECT evidence.id,
       'archive:v1:' || lower(hex(evidence.task_id)) || ':' || evidence.task_epoch || ':'
           || lower(hex(evidence.id)) || ':' || lower(hex(evidence.stage_id)) || ':'
           || evidence.stage_generation || ':' || evidence.active_task_turn_count || ':'
           || evidence.active_stage_turn_count || ':' || evidence.active_review_turn_count || ':'
           || evidence.active_plan_review_count || ':' || evidence.active_validation_count || ':'
           || evidence.active_brain_episode_count || ':'
           || evidence.active_provision_operation_count || ':'
           || evidence.active_dispatch_count || ':' || evidence.active_agent_execution_count || ':'
           || evidence.unreconciled_execution_count || ':'
           || evidence.live_capacity_lease_count || ':'
           || evidence.live_worktree_lease_count || ':' || evidence.active_quiescence_count || ':'
           || evidence.active_replan_count || ':' || evidence.active_feedback_batch_count || ':'
           || evidence.active_publish_operation_count || ':'
           || evidence.unreconciled_publish_operation_count || ':'
           || evidence.active_publish_effect_count || ':'
           || evidence.active_publish_authorization_count || ':'
           || evidence.open_permission_count || ':'
           || evidence.accepted_terminal_intent_count || ':'
           || evidence.open_cleanup_stage_count || ':' || evidence.recorded_at_ms
           AS content_digest
FROM task_archive_liveness evidence;
CREATE VIEW local_feedback_batch_digest_v230 AS
SELECT batch.id AS batch_id,
       'lfb:v1:' || lower(hex(batch.task_id)) || ':' || batch.task_epoch || ':'
           || lower(hex(batch.local_development_stage_id)) || ':'
           || batch.stage_generation || ':' || lower(hex(batch.source_submission_id)) || ':'
           || lower(hex(batch.code_fingerprint)) || ':' || lower(hex(batch.head_sha)) || ':'
           || lower(hex(batch.base_sha)) || ':'
           || (SELECT group_concat(
                    item.position || ':' || lower(hex(item.thread_id)) || ':'
                    || lower(hex(item.comment_revision_id)) || ':'
                    || lower(hex(item.body_digest)) || ':'
                    || lower(hex(item.frozen_body)) || ':'
                    || lower(hex(item.frozen_thread_content)),
                    '|' ORDER BY item.position)
               FROM local_feedback_batch_item item
               WHERE item.batch_id = batch.id) AS content_digest,
       (SELECT COUNT(*) FROM local_feedback_batch_item item
        WHERE item.batch_id = batch.id) AS item_count,
       (SELECT MIN(item.position) FROM local_feedback_batch_item item
        WHERE item.batch_id = batch.id) AS first_position,
       (SELECT MAX(item.position) FROM local_feedback_batch_item item
        WHERE item.batch_id = batch.id) AS last_position
FROM local_feedback_batch batch;
CREATE UNIQUE INDEX idx_outbox_v2_dispatch_ticket_wake
    ON outbox(aggregate_id)
    WHERE aggregate_kind = 'DISPATCH_TICKET';
CREATE TABLE remote_development_stage (
    stage_id                       TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage(id) ON DELETE CASCADE,
    task_id                        TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    generation                     INTEGER NOT NULL CHECK (generation > 0),
    remote_pr_binding_id           TEXT    NOT NULL UNIQUE
        REFERENCES remote_pr_binding(id),
    accepted_snapshot_id           TEXT    UNIQUE
        REFERENCES remote_pr_snapshot(id) DEFERRABLE INITIALLY DEFERRED,
    accepted_observation_revision  INTEGER NOT NULL DEFAULT 0
        CHECK (accepted_observation_revision >= 0),
    current_head_sha               TEXT    NOT NULL,
    current_base_sha               TEXT    NOT NULL,
    subject_changed_at_ms          INTEGER NOT NULL,
    UNIQUE (stage_id, task_id, generation),
    UNIQUE (stage_id, current_head_sha, current_base_sha),
    CHECK ((accepted_snapshot_id IS NULL AND accepted_observation_revision = 0)
        OR (accepted_snapshot_id IS NOT NULL AND accepted_observation_revision > 0))
);
CREATE TABLE remote_pr_snapshot (
    id                      TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                 TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch              INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation        INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id    TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    observation_revision    INTEGER NOT NULL CHECK (observation_revision > 0),
    observation_key         TEXT    NOT NULL,
    remote_repository_id    TEXT    NOT NULL,
    remote_pr_number        INTEGER NOT NULL CHECK (remote_pr_number > 0),
    head_sha                TEXT    NOT NULL,
    base_sha                TEXT    NOT NULL,
    pr_state                TEXT    NOT NULL CHECK (pr_state IN (
        'DRAFT', 'OPEN', 'MERGED', 'CLOSED')),
    mergeability            TEXT    NOT NULL CHECK (mergeability IN (
        'UNKNOWN', 'MERGEABLE', 'CONFLICTING', 'BLOCKED')),
    merge_queue_state       TEXT    NOT NULL CHECK (merge_queue_state IN (
        'NONE', 'QUEUED', 'DEQUEUED', 'MERGED')),
    effective_approval_count INTEGER NOT NULL DEFAULT 0
        CHECK (effective_approval_count >= 0),
    write_approval_count    INTEGER NOT NULL DEFAULT 0
        CHECK (write_approval_count >= 0),
    changes_requested_count INTEGER NOT NULL DEFAULT 0
        CHECK (changes_requested_count >= 0),
    requested_reviewer_count INTEGER NOT NULL DEFAULT 0
        CHECK (requested_reviewer_count >= 0),
    unresolved_thread_count INTEGER NOT NULL DEFAULT 0
        CHECK (unresolved_thread_count >= 0),
    unresolved_comment_count INTEGER NOT NULL DEFAULT 0
        CHECK (unresolved_comment_count >= 0),
    observed_at_ms          INTEGER NOT NULL,
    raw_evidence            TEXT, merge_queue_capability TEXT NOT NULL
    DEFAULT 'UNKNOWN' CHECK (merge_queue_capability IN (
        'UNKNOWN', 'UNSUPPORTED', 'SUPPORTED')), viewer_login TEXT, viewer_can_merge INTEGER
    CHECK (viewer_can_merge IS NULL OR viewer_can_merge IN (0, 1)), ci_provenance_json TEXT,
    UNIQUE (remote_development_stage_id, observation_revision),
    UNIQUE (remote_pr_binding_id, observation_key),
    UNIQUE (id, remote_development_stage_id, head_sha, base_sha)
);
CREATE TABLE remote_ci_policy_revision (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    remote_pr_binding_id TEXT   NOT NULL REFERENCES remote_pr_binding(id),
    revision            INTEGER NOT NULL CHECK (revision > 0),
    source              TEXT    NOT NULL,
    none_outcome        TEXT    NOT NULL CHECK (none_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    missing_outcome     TEXT    NOT NULL CHECK (missing_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    queued_outcome      TEXT    NOT NULL CHECK (queued_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    pending_outcome     TEXT    NOT NULL CHECK (pending_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    neutral_outcome     TEXT    NOT NULL CHECK (neutral_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    skipped_outcome     TEXT    NOT NULL CHECK (skipped_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    canceled_outcome    TEXT    NOT NULL CHECK (canceled_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    created_by          TEXT    NOT NULL,
    created_at_ms       INTEGER NOT NULL,
    UNIQUE (task_id, revision)
);
CREATE TABLE remote_ci_check_snapshot (
    id                  TEXT    NOT NULL PRIMARY KEY,
    remote_pr_snapshot_id TEXT  NOT NULL REFERENCES remote_pr_snapshot(id) ON DELETE CASCADE,
    check_kind          TEXT    NOT NULL CHECK (check_kind IN (
        'CHECK_RUN', 'STATUS_CONTEXT', 'CHECK_SUITE', 'REQUIRED_MISSING')),
    external_check_id   TEXT    NOT NULL,
    check_name          TEXT    NOT NULL,
    normalized_state    TEXT    NOT NULL CHECK (normalized_state IN (
        'MISSING', 'QUEUED', 'PENDING', 'PASSED', 'FAILED',
        'NEUTRAL', 'SKIPPED', 'CANCELED')),
    provider_status     TEXT,
    provider_conclusion TEXT,
    started_at_ms       INTEGER,
    completed_at_ms     INTEGER,
    observed_at_ms      INTEGER NOT NULL,
    raw_evidence        TEXT,
    UNIQUE (remote_pr_snapshot_id, check_kind, external_check_id),
    CHECK ((normalized_state = 'MISSING') = (check_kind = 'REQUIRED_MISSING')),
    CHECK (completed_at_ms IS NULL OR started_at_ms IS NULL
        OR completed_at_ms >= started_at_ms)
);
CREATE TABLE remote_ci_evaluation (
    id                         TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT  NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    remote_pr_snapshot_id      TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    ci_policy_revision_id      TEXT    NOT NULL REFERENCES remote_ci_policy_revision(id),
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    normalized_status          TEXT    NOT NULL CHECK (normalized_status IN (
        'NONE', 'MISSING', 'QUEUED', 'PENDING', 'PASSED', 'FAILED',
        'NEUTRAL', 'SKIPPED', 'CANCELED')),
    policy_outcome             TEXT    NOT NULL CHECK (policy_outcome IN (
        'ACCEPTED', 'WAITING', 'FAILED')),
    check_count                INTEGER NOT NULL CHECK (check_count >= 0),
    missing_required_count     INTEGER NOT NULL CHECK (missing_required_count >= 0),
    evidence                   TEXT    NOT NULL,
    evaluated_at_ms            INTEGER NOT NULL,
    UNIQUE (remote_pr_snapshot_id, ci_policy_revision_id),
    CHECK ((normalized_status = 'NONE' AND check_count = 0
            AND missing_required_count = 0)
        OR (normalized_status = 'MISSING' AND missing_required_count > 0)
        OR normalized_status NOT IN ('NONE', 'MISSING')),
    CHECK (normalized_status NOT IN (
        'QUEUED', 'PENDING', 'PASSED', 'FAILED', 'NEUTRAL', 'SKIPPED', 'CANCELED')
        OR check_count > 0)
);
CREATE TABLE ci_repair_episode (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    failed_ci_evaluation_id     TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    subject_head_sha            TEXT    NOT NULL,
    subject_base_sha            TEXT    NOT NULL,
    classification              TEXT    NOT NULL CHECK (classification IN (
        'FLAKY', 'INFRASTRUCTURE', 'TASK_DETERMINISTIC',
        'BASE_DETERMINISTIC', 'UNKNOWN')),
    status                      TEXT    NOT NULL CHECK (status IN (
        'OPEN', 'AWAITING_RERUN', 'FIXING', 'VALIDATING', 'AWAITING_PUSH_CI',
        'SUCCEEDED', 'EXHAUSTED', 'STOPPED')),
    rerun_count                 INTEGER NOT NULL DEFAULT 0 CHECK (rerun_count >= 0),
    rerun_limit                 INTEGER NOT NULL CHECK (rerun_limit >= 0),
    fix_attempt_count           INTEGER NOT NULL DEFAULT 0 CHECK (fix_attempt_count >= 0),
    fix_attempt_limit           INTEGER NOT NULL CHECK (fix_attempt_limit >= 0),
    delivery_retry_count        INTEGER NOT NULL DEFAULT 0 CHECK (delivery_retry_count >= 0),
    delivery_retry_limit        INTEGER NOT NULL CHECK (delivery_retry_limit >= 0),
    push_count                  INTEGER NOT NULL DEFAULT 0 CHECK (push_count >= 0),
    push_limit                  INTEGER NOT NULL CHECK (push_limit >= 0),
    last_pushed_head_sha        TEXT,
    last_push_result_evaluation_id TEXT REFERENCES remote_ci_evaluation(id),
    terminal_ci_evaluation_id   TEXT REFERENCES remote_ci_evaluation(id),
    opened_at_ms                INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    stop_reason                 TEXT,
    CHECK (rerun_count <= rerun_limit
        AND fix_attempt_count <= fix_attempt_limit
        AND delivery_retry_count <= delivery_retry_limit
        AND push_count <= push_limit),
    CHECK ((push_count = 0 AND last_pushed_head_sha IS NULL
            AND last_push_result_evaluation_id IS NULL)
        OR (push_count > 0 AND last_pushed_head_sha IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'EXHAUSTED', 'STOPPED'))
            = (completed_at_ms IS NOT NULL)),
    CHECK (classification NOT IN ('FLAKY', 'INFRASTRUCTURE')
        OR (fix_attempt_count = 0 AND fix_attempt_limit = 0
            AND push_count = 0 AND push_limit = 0))
);
CREATE UNIQUE INDEX idx_ci_repair_one_live_subject
    ON ci_repair_episode(remote_development_stage_id, subject_head_sha)
    WHERE status NOT IN ('SUCCEEDED', 'EXHAUSTED', 'STOPPED');
CREATE TABLE branch_sync_episode (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    source_snapshot_id          TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    old_head_sha                TEXT    NOT NULL,
    observed_base_sha           TEXT    NOT NULL,
    target_base_sha             TEXT    NOT NULL,
    policy_source               TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'OPEN', 'REBASING', 'CONFLICT_REPAIR', 'VALIDATING', 'BRAIN_REVIEW',
        'PUSHING', 'AWAITING_HEAD', 'SUCCEEDED', 'FAILED', 'STOPPED')),
    attempt_count               INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit               INTEGER NOT NULL CHECK (attempt_limit > 0),
    result_head_sha             TEXT,
    result_snapshot_id          TEXT REFERENCES remote_pr_snapshot(id),
    opened_at_ms                INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    error_message               TEXT, branch_sync_policy_revision_id TEXT
        REFERENCES task_branch_sync_policy_revision(id),
    CHECK (attempt_count <= attempt_limit),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'STOPPED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED'
        OR (result_head_sha IS NOT NULL AND result_snapshot_id IS NOT NULL))
);
CREATE UNIQUE INDEX idx_branch_sync_one_live_subject
    ON branch_sync_episode(
        remote_development_stage_id, old_head_sha, target_base_sha)
    WHERE status NOT IN ('SUCCEEDED', 'FAILED', 'STOPPED');
CREATE TABLE branch_sync_effect_step (
    id                     TEXT    NOT NULL PRIMARY KEY,
    branch_sync_episode_id TEXT    NOT NULL REFERENCES branch_sync_episode(id) ON DELETE CASCADE,
    ordinal                INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 6),
    kind                   TEXT    NOT NULL CHECK (kind IN (
        'FETCH_COMPARE', 'MECHANICAL_REBASE', 'CONFLICT_REPAIR',
        'VALIDATE', 'BRAIN_REVIEW', 'FORCE_WITH_LEASE_PUSH')),
    idempotency_key        TEXT    NOT NULL UNIQUE,
    status                 TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED',
        'INDETERMINATE', 'SKIPPED')),
    attempt_count          INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit          INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode             TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner            TEXT,
    claimed_at_ms          INTEGER,
    lease_until_ms         INTEGER,
    evidence               TEXT,
    last_error             TEXT,
    completed_at_ms        INTEGER,
    UNIQUE (branch_sync_episode_id, ordinal),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK (status <> 'CLAIMED' OR lease_until_ms > claimed_at_ms),
    CHECK (attempt_count <= attempt_limit),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE', 'SKIPPED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE TABLE branch_sync_push_proof (
    branch_sync_effect_step_id TEXT NOT NULL PRIMARY KEY
        REFERENCES branch_sync_effect_step(id) ON DELETE CASCADE,
    branch_sync_episode_id     TEXT NOT NULL REFERENCES branch_sync_episode(id) ON DELETE CASCADE,
    old_head_sha               TEXT NOT NULL,
    observed_base_sha          TEXT NOT NULL,
    target_base_sha            TEXT NOT NULL,
    force_with_lease_expected_sha TEXT NOT NULL,
    pushed_head_sha            TEXT NOT NULL,
    force_with_lease_used      INTEGER NOT NULL CHECK (force_with_lease_used = 1),
    remote_probe_identity      TEXT NOT NULL,
    evidence                   TEXT NOT NULL,
    recorded_at_ms             INTEGER NOT NULL,
    UNIQUE (branch_sync_episode_id, pushed_head_sha)
);
CREATE TABLE remote_inbox_item (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    remote_pr_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'INLINE_COMMENT', 'TOP_LEVEL_COMMENT', 'REVIEW_BODY',
        'REVIEW_VERDICT', 'REQUESTED_REVIEW', 'THREAD_RESOLVED',
        'THREAD_REOPENED', 'HEAD_CHANGED')),
    external_key                TEXT    NOT NULL,
    external_revision           INTEGER NOT NULL CHECK (external_revision > 0),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    actor_login                 TEXT,
    provenance                  TEXT    NOT NULL CHECK (provenance IN (
        'EXTERNAL', 'OWN_REPLY')),
    ignored                     INTEGER NOT NULL CHECK (ignored IN (0, 1)),
    thread_id                   TEXT,
    comment_id                  TEXT,
    review_id                   TEXT,
    requested_reviewer          TEXT,
    body                        TEXT,
    body_digest                 TEXT,
    verdict                     TEXT CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'COMMENTED', 'DISMISSED')),
    previous_head_sha           TEXT,
    new_head_sha                TEXT,
    observed_at_ms              INTEGER NOT NULL,
    raw_evidence                TEXT,
    UNIQUE (remote_pr_binding_id, external_key, external_revision),
    UNIQUE (id, remote_development_stage_id, head_sha, base_sha),
    CHECK ((provenance = 'OWN_REPLY' AND ignored = 1)
        OR (provenance = 'EXTERNAL' AND ignored = 0)),
    CHECK ((body IS NULL AND body_digest IS NULL)
        OR (body IS NOT NULL AND body_digest IS NOT NULL)),
    CHECK (
        (kind = 'INLINE_COMMENT' AND thread_id IS NOT NULL
            AND comment_id IS NOT NULL AND body IS NOT NULL
            AND review_id IS NULL AND requested_reviewer IS NULL
            AND verdict IS NULL AND previous_head_sha IS NULL
            AND new_head_sha IS NULL)
        OR (kind = 'TOP_LEVEL_COMMENT' AND thread_id IS NULL
            AND comment_id IS NOT NULL AND body IS NOT NULL
            AND review_id IS NULL AND requested_reviewer IS NULL
            AND verdict IS NULL AND previous_head_sha IS NULL
            AND new_head_sha IS NULL)
        OR (kind = 'REVIEW_BODY' AND review_id IS NOT NULL
            AND thread_id IS NULL
            AND body IS NOT NULL AND comment_id IS NULL
            AND requested_reviewer IS NULL AND verdict IS NULL
            AND previous_head_sha IS NULL AND new_head_sha IS NULL)
        OR (kind = 'REVIEW_VERDICT' AND review_id IS NOT NULL
            AND thread_id IS NULL
            AND verdict IS NOT NULL AND comment_id IS NULL
            AND requested_reviewer IS NULL
            AND previous_head_sha IS NULL AND new_head_sha IS NULL)
        OR (kind = 'REQUESTED_REVIEW' AND requested_reviewer IS NOT NULL
            AND thread_id IS NULL AND comment_id IS NULL AND review_id IS NULL
            AND body IS NULL AND verdict IS NULL
            AND previous_head_sha IS NULL AND new_head_sha IS NULL)
        OR (kind IN ('THREAD_RESOLVED', 'THREAD_REOPENED')
            AND thread_id IS NOT NULL AND comment_id IS NULL
            AND review_id IS NULL AND body IS NULL
            AND requested_reviewer IS NULL AND verdict IS NULL
            AND previous_head_sha IS NULL AND new_head_sha IS NULL)
        OR (kind = 'HEAD_CHANGED' AND previous_head_sha IS NOT NULL
            AND new_head_sha IS NOT NULL
            AND previous_head_sha <> new_head_sha
            AND head_sha = new_head_sha AND thread_id IS NULL
            AND comment_id IS NULL AND review_id IS NULL
            AND requested_reviewer IS NULL AND body IS NULL
            AND verdict IS NULL))
);
CREATE TABLE remote_feedback_batch (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    source_snapshot_id          TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    sequence                    INTEGER NOT NULL CHECK (sequence > 0),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'BUILDING', 'FROZEN', 'ADDRESSING', 'AWAITING_APPROVAL',
        'AUTHORIZED', 'APPLYING', 'COMPLETED', 'SUPERSEDED')),
    brain_review_required       INTEGER NOT NULL CHECK (brain_review_required IN (0, 1)),
    item_count                  INTEGER NOT NULL CHECK (item_count > 0),
    content_digest              TEXT,
    result_head_sha             TEXT,
    result_snapshot_id          TEXT REFERENCES remote_pr_snapshot(id),
    created_at_ms               INTEGER NOT NULL,
    frozen_at_ms                INTEGER,
    completed_at_ms             INTEGER,
    CHECK ((status = 'BUILDING' AND content_digest IS NULL
            AND frozen_at_ms IS NULL)
        OR (status <> 'BUILDING' AND content_digest IS NOT NULL
            AND frozen_at_ms IS NOT NULL)),
    CHECK ((status IN ('COMPLETED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK ((result_head_sha IS NULL AND result_snapshot_id IS NULL)
        OR (result_head_sha IS NOT NULL AND result_snapshot_id IS NOT NULL)),
    UNIQUE (remote_development_stage_id, sequence),
    UNIQUE (id, remote_development_stage_id, head_sha, base_sha)
);
CREATE TABLE remote_feedback_batch_item (
    remote_feedback_batch_id TEXT    NOT NULL
        REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    ordinal                 INTEGER NOT NULL CHECK (ordinal > 0),
    remote_inbox_item_id    TEXT    NOT NULL UNIQUE REFERENCES remote_inbox_item(id),
    external_revision       INTEGER NOT NULL CHECK (external_revision > 0),
    kind                    TEXT    NOT NULL,
    frozen_body             TEXT,
    body_digest             TEXT,
    external_target         TEXT,
    selected_by             TEXT    NOT NULL,
    selected_at_ms          INTEGER NOT NULL,
    PRIMARY KEY (remote_feedback_batch_id, ordinal),
    CHECK ((frozen_body IS NULL AND body_digest IS NULL)
        OR (frozen_body IS NOT NULL AND body_digest IS NOT NULL))
);
CREATE TABLE remote_feedback_validation_evidence (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id   TEXT    NOT NULL UNIQUE
        REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    remote_development_stage_id TEXT   NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    repair_stage_turn_id        TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    validation_pass_id          INTEGER NOT NULL UNIQUE REFERENCES validation_pass(id),
    validation_operation_id     TEXT    NOT NULL UNIQUE,
    validation_attempt          INTEGER NOT NULL CHECK (validation_attempt > 0),
    subject_head_sha            TEXT    NOT NULL,
    proposed_head_sha           TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    passed                      INTEGER NOT NULL CHECK (passed IN (0, 1)),
    evidence                    TEXT    NOT NULL,
    completed_at_ms             INTEGER NOT NULL
);
CREATE TABLE remote_feedback_brain_review_evidence (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id   TEXT    NOT NULL UNIQUE
        REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    validation_evidence_id      TEXT    NOT NULL UNIQUE
        REFERENCES remote_feedback_validation_evidence(id),
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    task_turn_id                TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    proposed_head_sha           TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    verdict                     TEXT    NOT NULL CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'BLOCKED')),
    unresolved_finding_count    INTEGER NOT NULL CHECK (unresolved_finding_count >= 0),
    evidence                    TEXT    NOT NULL,
    completed_at_ms             INTEGER NOT NULL,
    CHECK (verdict <> 'APPROVED' OR unresolved_finding_count = 0)
);
CREATE TABLE remote_feedback_authorization (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id   TEXT    NOT NULL UNIQUE
        REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    validation_evidence_id      TEXT    NOT NULL UNIQUE
        REFERENCES remote_feedback_validation_evidence(id),
    brain_review_evidence_id    TEXT    UNIQUE
        REFERENCES remote_feedback_brain_review_evidence(id),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    item_count                  INTEGER NOT NULL CHECK (item_count > 0),
    content_digest              TEXT    NOT NULL,
    effect_count                INTEGER NOT NULL CHECK (effect_count > 0),
    authority_kind              TEXT    NOT NULL CHECK (authority_kind = 'USER_ACTION'),
    authorized_by               TEXT    NOT NULL,
    reason                      TEXT,
    authorized_at_ms            INTEGER NOT NULL,
    UNIQUE (id, remote_feedback_batch_id)
);
CREATE TABLE remote_feedback_effect_step (
    id                           TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_authorization_id TEXT NOT NULL
        REFERENCES remote_feedback_authorization(id) ON DELETE CASCADE,
    remote_feedback_batch_id     TEXT    NOT NULL
        REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    ordinal                      INTEGER NOT NULL CHECK (ordinal > 0),
    kind                         TEXT    NOT NULL CHECK (kind IN (
        'POST_INLINE_REPLY', 'POST_TOP_LEVEL_REPLY', 'SUBMIT_REVIEW',
        'REQUEST_REVIEWER', 'POST_MAINTAINER_NUDGE',
        'RESOLVE_THREAD', 'PUSH_COMMITS')),
    remote_inbox_item_id         TEXT REFERENCES remote_inbox_item(id),
    external_target              TEXT,
    review_action                TEXT CHECK (review_action IN (
        'COMMENT', 'APPROVE', 'REQUEST_CHANGES')),
    payload_digest               TEXT    NOT NULL,
    idempotency_key              TEXT    NOT NULL UNIQUE,
    status                       TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE')),
    attempt_count                INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit                INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode                   TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner                  TEXT,
    claimed_at_ms                INTEGER,
    lease_until_ms               INTEGER,
    external_effect_id           TEXT,
    evidence                     TEXT,
    last_error                   TEXT,
    completed_at_ms              INTEGER,
    UNIQUE (remote_feedback_batch_id, ordinal),
    CHECK ((kind IN ('PUSH_COMMITS', 'SUBMIT_REVIEW', 'REQUEST_REVIEWER',
            'POST_MAINTAINER_NUDGE')
            AND remote_inbox_item_id IS NULL)
        OR (kind NOT IN ('PUSH_COMMITS', 'SUBMIT_REVIEW', 'REQUEST_REVIEWER',
            'POST_MAINTAINER_NUDGE')
            AND remote_inbox_item_id IS NOT NULL)),
    CHECK (kind NOT IN ('REQUEST_REVIEWER', 'POST_MAINTAINER_NUDGE')
        OR external_target IS NOT NULL),
    CHECK ((kind = 'SUBMIT_REVIEW') = (review_action IS NOT NULL)),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK (status <> 'CLAIMED' OR lease_until_ms > claimed_at_ms),
    CHECK (attempt_count <= attempt_limit),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED'
        OR (external_effect_id IS NOT NULL AND evidence IS NOT NULL))
);
CREATE TABLE task_automation_policy (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    revision                    INTEGER NOT NULL CHECK (revision > 0),
    source                      TEXT    NOT NULL,
    auto_approve                INTEGER NOT NULL CHECK (auto_approve IN (0, 1)),
    auto_merge                  INTEGER NOT NULL CHECK (auto_merge IN (0, 1)),
    keep_draft                  INTEGER NOT NULL CHECK (keep_draft IN (0, 1)),
    minimum_write_approvals     INTEGER NOT NULL CHECK (minimum_write_approvals >= 0),
    max_merge_queue_reenqueues  INTEGER NOT NULL CHECK (max_merge_queue_reenqueues >= 0),
    require_low_risk            INTEGER NOT NULL CHECK (require_low_risk IN (0, 1)),
    require_small_effort        INTEGER NOT NULL CHECK (require_small_effort IN (0, 1)),
    stewardship_exception       INTEGER NOT NULL CHECK (stewardship_exception IN (0, 1)),
    created_by                  TEXT    NOT NULL,
    created_at_ms               INTEGER NOT NULL,
    UNIQUE (task_id, revision),
    CHECK (auto_merge = 0 OR auto_approve = 1),
    CHECK (stewardship_exception = 0
        OR (auto_approve = 0 AND auto_merge = 0))
);
CREATE TABLE remote_mark_ready_authorization (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_snapshot_id       TEXT    NOT NULL UNIQUE REFERENCES remote_pr_snapshot(id),
    ci_evaluation_id            TEXT    NOT NULL UNIQUE REFERENCES remote_ci_evaluation(id),
    automation_policy_id        TEXT    NOT NULL REFERENCES task_automation_policy(id),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    authority_kind              TEXT    NOT NULL CHECK (authority_kind IN (
        'MANUAL', 'AUTO_APPROVE_POLICY')),
    actor_id                    TEXT,
    status                      TEXT    NOT NULL CHECK (status IN (
        'ACTIVE', 'CONSUMED', 'REVOKED')),
    authorized_at_ms            INTEGER NOT NULL,
    terminal_at_ms              INTEGER,
    CHECK ((authority_kind = 'MANUAL' AND actor_id IS NOT NULL)
        OR (authority_kind = 'AUTO_APPROVE_POLICY' AND actor_id IS NULL)),
    CHECK ((status = 'ACTIVE') = (terminal_at_ms IS NULL))
);
CREATE TABLE remote_mark_ready_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    mark_ready_authorization_id TEXT    NOT NULL UNIQUE
        REFERENCES remote_mark_ready_authorization(id),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'AWAITING_OBSERVATION', 'SUCCEEDED',
        'FAILED', 'INDETERMINATE', 'CANCELED')),
    attempt_count               INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit               INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode                  TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner                 TEXT,
    claimed_at_ms               INTEGER,
    lease_until_ms              INTEGER,
    result_snapshot_id          TEXT REFERENCES remote_pr_snapshot(id),
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    evidence                    TEXT,
    last_error                  TEXT,
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK (status <> 'CLAIMED' OR lease_until_ms > claimed_at_ms),
    CHECK (attempt_count <= attempt_limit),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE', 'CANCELED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK ((status = 'SUCCEEDED') = (result_snapshot_id IS NOT NULL))
);
CREATE TABLE task_automation_eligibility_evidence (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch          INTEGER NOT NULL CHECK (task_epoch > 0),
    plan_revision_id    TEXT    NOT NULL UNIQUE REFERENCES plan_revision(id),
    risk_level          TEXT    NOT NULL CHECK (risk_level IN (
        'LOW', 'MEDIUM', 'HIGH', 'UNKNOWN')),
    effort              TEXT    NOT NULL CHECK (effort IN (
        'SMALL', 'MEDIUM', 'LARGE', 'UNKNOWN')),
    low_risk_eligible   INTEGER NOT NULL CHECK (low_risk_eligible IN (0, 1)),
    small_effort_eligible INTEGER NOT NULL CHECK (small_effort_eligible IN (0, 1)),
    evidence            TEXT    NOT NULL,
    content_digest      TEXT    NOT NULL,
    recorded_at_ms      INTEGER NOT NULL,
    CHECK (low_risk_eligible = CASE risk_level WHEN 'LOW' THEN 1 ELSE 0 END),
    CHECK (small_effort_eligible = CASE effort WHEN 'SMALL' THEN 1 ELSE 0 END)
);
CREATE TABLE remote_readiness_evidence (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    ci_evaluation_id            TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    automation_policy_id        TEXT    NOT NULL REFERENCES task_automation_policy(id),
    automation_eligibility_evidence_id TEXT
        REFERENCES task_automation_eligibility_evidence(id),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    pr_open                     INTEGER NOT NULL CHECK (pr_open IN (0, 1)),
    non_draft                   INTEGER NOT NULL CHECK (non_draft IN (0, 1)),
    ci_accepted                 INTEGER NOT NULL CHECK (ci_accepted IN (0, 1)),
    write_approval_count        INTEGER NOT NULL CHECK (write_approval_count >= 0),
    required_write_approval_count INTEGER NOT NULL CHECK (required_write_approval_count >= 0),
    changes_requested_count     INTEGER NOT NULL CHECK (changes_requested_count >= 0),
    unresolved_thread_count     INTEGER NOT NULL CHECK (unresolved_thread_count >= 0),
    unresolved_comment_count    INTEGER NOT NULL CHECK (unresolved_comment_count >= 0),
    open_feedback_batch_count   INTEGER NOT NULL CHECK (open_feedback_batch_count >= 0),
    blocking_gate_count         INTEGER NOT NULL CHECK (blocking_gate_count >= 0),
    low_risk_required           INTEGER NOT NULL CHECK (low_risk_required IN (0, 1)),
    small_effort_required       INTEGER NOT NULL CHECK (small_effort_required IN (0, 1)),
    low_risk_eligible           INTEGER NOT NULL CHECK (low_risk_eligible IN (0, 1)),
    small_effort_eligible       INTEGER NOT NULL CHECK (small_effort_eligible IN (0, 1)),
    mergeability                TEXT    NOT NULL CHECK (mergeability IN (
        'UNKNOWN', 'MERGEABLE', 'CONFLICTING', 'BLOCKED')),
    merge_queue_capability      TEXT    NOT NULL CHECK (merge_queue_capability IN (
        'UNKNOWN', 'UNSUPPORTED', 'SUPPORTED')),
    ready                       INTEGER NOT NULL CHECK (ready IN (0, 1)),
    evidence                    TEXT    NOT NULL,
    observed_at_ms              INTEGER NOT NULL,
    UNIQUE (remote_pr_snapshot_id, automation_policy_id),
    UNIQUE (id, remote_development_stage_id, head_sha),
    CHECK (ready = CASE WHEN pr_open = 1 AND non_draft = 1
            AND ci_accepted = 1
            AND write_approval_count >= required_write_approval_count
            AND changes_requested_count = 0
            AND unresolved_thread_count = 0
            AND unresolved_comment_count = 0
            AND open_feedback_batch_count = 0
            AND blocking_gate_count = 0
            AND (low_risk_required = 0 OR low_risk_eligible = 1)
            AND (small_effort_required = 0 OR small_effort_eligible = 1)
            AND mergeability = 'MERGEABLE'
        THEN 1 ELSE 0 END)
);
CREATE TABLE remote_merge_authorization (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    readiness_evidence_id       TEXT    NOT NULL UNIQUE REFERENCES remote_readiness_evidence(id),
    automation_policy_id        TEXT    NOT NULL REFERENCES task_automation_policy(id),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    authority_kind              TEXT    NOT NULL CHECK (authority_kind IN (
        'MANUAL', 'AUTO_MERGE_POLICY')),
    actor_id                    TEXT,
    status                      TEXT    NOT NULL CHECK (status IN (
        'ACTIVE', 'CONSUMED', 'REVOKED')),
    authorized_at_ms            INTEGER NOT NULL,
    terminal_at_ms              INTEGER, merge_method TEXT NOT NULL DEFAULT 'squash'
        CHECK (merge_method IN ('merge', 'squash', 'rebase')),
    CHECK ((authority_kind = 'MANUAL' AND actor_id IS NOT NULL)
        OR (authority_kind = 'AUTO_MERGE_POLICY' AND actor_id IS NULL)),
    CHECK ((status = 'ACTIVE') = (terminal_at_ms IS NULL))
);
CREATE UNIQUE INDEX idx_remote_merge_authorization_live_head
    ON remote_merge_authorization(remote_development_stage_id, head_sha)
    WHERE status = 'ACTIVE';
CREATE TABLE remote_merge_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    merge_authorization_id      TEXT    NOT NULL UNIQUE
        REFERENCES remote_merge_authorization(id),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    mode                        TEXT    NOT NULL CHECK (mode IN (
        'DIRECT', 'MERGE_QUEUE')),
    merge_queue_capability      TEXT    NOT NULL CHECK (merge_queue_capability IN (
        'UNSUPPORTED', 'SUPPORTED')),
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'QUEUE_ENTERED', 'AWAITING_OBSERVATION',
        'SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED')),
    attempt_count               INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit               INTEGER NOT NULL CHECK (attempt_limit > 0),
    queue_bounce_count          INTEGER NOT NULL DEFAULT 0 CHECK (queue_bounce_count >= 0),
    max_queue_reenqueues        INTEGER NOT NULL CHECK (max_queue_reenqueues >= 0),
    terminal_observation_id     TEXT REFERENCES remote_terminal_observation(id)
        DEFERRABLE INITIALLY DEFERRED,
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    block_reason                TEXT CHECK (block_reason IN (
        'QUEUE_REENQUEUE_EXHAUSTED', 'PERMISSION_DENIED',
        'MERGEABILITY_REGRESSED', 'MANUAL_INTERVENTION')),
    last_error                  TEXT, merge_method TEXT NOT NULL DEFAULT 'squash'
        CHECK (merge_method IN ('merge', 'squash', 'rebase')),
    CHECK (attempt_count <= attempt_limit),
    CHECK (queue_bounce_count <= max_queue_reenqueues),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED' OR terminal_observation_id IS NOT NULL),
    CHECK ((status = 'BLOCKED') = (block_reason IS NOT NULL)),
    CHECK (mode = 'MERGE_QUEUE' OR max_queue_reenqueues = 0),
    CHECK ((mode = 'MERGE_QUEUE' AND merge_queue_capability = 'SUPPORTED')
        OR (mode = 'DIRECT' AND merge_queue_capability = 'UNSUPPORTED'))
);
CREATE UNIQUE INDEX idx_remote_merge_operation_one_live_head
    ON remote_merge_operation(remote_development_stage_id, head_sha)
    WHERE status NOT IN ('SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED');
CREATE TABLE remote_merge_effect_attempt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    merge_operation_id       TEXT    NOT NULL
        REFERENCES remote_merge_operation(id) ON DELETE CASCADE,
    ordinal                  INTEGER NOT NULL CHECK (ordinal > 0),
    effect_kind              TEXT    NOT NULL CHECK (effect_kind IN (
        'DIRECT_MERGE', 'ENTER_QUEUE')),
    effect_ordinal           INTEGER CHECK (effect_ordinal > 0),
    readiness_evidence_id    TEXT    NOT NULL REFERENCES remote_readiness_evidence(id),
    idempotency_key          TEXT    NOT NULL,
    attempt_key              TEXT    NOT NULL UNIQUE,
    claim_mode               TEXT    NOT NULL CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    status                   TEXT    NOT NULL CHECK (status IN (
        'CLAIMED', 'AWAITING_OBSERVATION', 'SUCCEEDED', 'FAILED',
        'INDETERMINATE')),
    claim_owner              TEXT    NOT NULL,
    claimed_at_ms            INTEGER NOT NULL,
    lease_until_ms           INTEGER NOT NULL,
    observed_snapshot_id     TEXT REFERENCES remote_pr_snapshot(id),
    external_effect_id       TEXT,
    evidence                 TEXT,
    last_error               TEXT,
    completed_at_ms          INTEGER,
    UNIQUE (merge_operation_id, ordinal),
    CHECK (lease_until_ms > claimed_at_ms),
    CHECK ((effect_kind = 'DIRECT_MERGE') = (effect_ordinal IS NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED'
        OR (observed_snapshot_id IS NOT NULL AND evidence IS NOT NULL)),
    CHECK (status NOT IN ('FAILED', 'INDETERMINATE')
        OR evidence IS NOT NULL)
);
CREATE UNIQUE INDEX idx_remote_merge_effect_execute_once
    ON remote_merge_effect_attempt(idempotency_key)
    WHERE claim_mode = 'EXECUTE';
CREATE TABLE remote_merge_queue_entry (
    id                       TEXT    NOT NULL PRIMARY KEY,
    merge_operation_id       TEXT    NOT NULL REFERENCES remote_merge_operation(id) ON DELETE CASCADE,
    merge_effect_attempt_id  TEXT    NOT NULL UNIQUE
        REFERENCES remote_merge_effect_attempt(id),
    ordinal                  INTEGER NOT NULL CHECK (ordinal > 0),
    queue_entry_id           TEXT    NOT NULL UNIQUE,
    head_sha                 TEXT    NOT NULL,
    status                   TEXT    NOT NULL CHECK (status IN (
        'ENTERED', 'BOUNCED', 'MERGED', 'REMOVED')),
    entered_snapshot_id      TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    readiness_evidence_id    TEXT    NOT NULL REFERENCES remote_readiness_evidence(id),
    observed_snapshot_id     TEXT REFERENCES remote_pr_snapshot(id),
    entered_at_ms            INTEGER NOT NULL,
    observed_at_ms           INTEGER,
    evidence                 TEXT    NOT NULL,
    UNIQUE (merge_operation_id, ordinal),
    CHECK ((status = 'ENTERED' AND observed_snapshot_id IS NULL
            AND observed_at_ms IS NULL)
        OR (status <> 'ENTERED' AND observed_snapshot_id IS NOT NULL
            AND observed_at_ms IS NOT NULL))
);
CREATE TABLE remote_terminal_observation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    remote_pr_snapshot_id       TEXT    NOT NULL UNIQUE REFERENCES remote_pr_snapshot(id),
    task_terminal_intent_id     TEXT    NOT NULL UNIQUE REFERENCES task_terminal_intent(id),
    kind                        TEXT    NOT NULL CHECK (kind IN ('MERGED', 'CLOSED')),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    observed_at_ms              INTEGER NOT NULL,
    evidence                    TEXT    NOT NULL
);
CREATE TABLE task_terminal_acceptance (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_terminal_intent_id     TEXT    NOT NULL UNIQUE
        REFERENCES task_terminal_intent(id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    source_kind                 TEXT    NOT NULL CHECK (source_kind IN (
        'REMOTE_OBSERVATION', 'USER_CANCEL', 'LOCAL_COMPLETION')),
    source_id                   TEXT    NOT NULL,
    remote_terminal_observation_id TEXT UNIQUE
        REFERENCES remote_terminal_observation(id),
    observed_head_sha           TEXT,
    accepted_by                 TEXT    NOT NULL,
    accepted_at_ms              INTEGER NOT NULL,
    evidence                    TEXT    NOT NULL,
    CHECK ((source_kind = 'REMOTE_OBSERVATION'
            AND kind IN ('COMPLETED', 'REMOTE_CLOSED')
            AND remote_terminal_observation_id IS NOT NULL
            AND observed_head_sha IS NOT NULL)
        OR (source_kind = 'USER_CANCEL' AND kind = 'CANCELED'
            AND remote_terminal_observation_id IS NULL
            AND observed_head_sha IS NULL)
        OR (source_kind = 'LOCAL_COMPLETION' AND kind = 'COMPLETED'
            AND remote_terminal_observation_id IS NULL))
);
CREATE TABLE cleanup_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    cleanup_stage_id            TEXT    NOT NULL UNIQUE
        REFERENCES cleanup_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    terminal_acceptance_id      TEXT    NOT NULL UNIQUE
        REFERENCES task_terminal_acceptance(id),
    dispatch_ticket_id          TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'ACTIVE', 'COMPLETED')),
    step_count                  INTEGER NOT NULL CHECK (step_count = 11),
    requested_at_ms             INTEGER NOT NULL,
    started_at_ms               INTEGER,
    completed_at_ms             INTEGER,
    summary_digest              TEXT,
    CHECK ((status = 'REQUESTED') = (started_at_ms IS NULL)),
    CHECK ((status = 'COMPLETED') = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'COMPLETED' OR summary_digest IS NOT NULL)
);
CREATE TABLE cleanup_step (
    id                          TEXT    NOT NULL PRIMARY KEY,
    cleanup_operation_id        TEXT    NOT NULL
        REFERENCES cleanup_operation(id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    cleanup_stage_id            TEXT    NOT NULL REFERENCES cleanup_stage(stage_id),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    ordinal                     INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 11),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'PROVE_NO_NEW_ADMISSIONS', 'RECONCILE_OPEN_WORK',
        'STOP_PROVIDER_SESSIONS', 'RECONCILE_VALIDATION',
        'SEAL_REVIEW_STATE', 'DISMISS_TASK_INTERACTIONS',
        'RELEASE_RUNTIME_LEASES', 'REMOVE_WORKTREE',
        'DELETE_LOCAL_BRANCH', 'DELETE_REMOTE_BRANCH',
        'RECORD_FINAL_EVIDENCE')),
    requirement                 TEXT    NOT NULL CHECK (requirement IN (
        'REQUIRED', 'OPTIONAL', 'NOT_APPLICABLE')),
    idempotency_key             TEXT    NOT NULL UNIQUE,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'SKIPPED', 'WAIVED')),
    attempt_count               INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    execute_attempt_count       INTEGER NOT NULL DEFAULT 0
        CHECK (execute_attempt_count >= 0),
    attempt_limit               INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode                  TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner                 TEXT,
    claimed_at_ms               INTEGER,
    lease_until_ms              INTEGER,
    failure_kind                TEXT CHECK (failure_kind IN (
        'DETERMINATE', 'INDETERMINATE')),
    last_error                  TEXT,
    completed_at_ms             INTEGER,
    UNIQUE (cleanup_operation_id, ordinal),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK (status <> 'CLAIMED' OR lease_until_ms > claimed_at_ms),
    CHECK (execute_attempt_count <= attempt_limit),
    CHECK ((status = 'FAILED') = (failure_kind IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'SKIPPED', 'WAIVED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED' OR requirement IN ('REQUIRED', 'OPTIONAL')),
    CHECK (status <> 'SKIPPED' OR requirement = 'NOT_APPLICABLE'),
    CHECK (status <> 'WAIVED' OR requirement = 'OPTIONAL')
);
CREATE TABLE cleanup_interaction_dismissal_evidence (
    id                              TEXT    NOT NULL PRIMARY KEY,
    cleanup_step_id                 TEXT    NOT NULL UNIQUE
        REFERENCES cleanup_step(id) ON DELETE CASCADE,
    cleanup_operation_id            TEXT    NOT NULL
        REFERENCES cleanup_operation(id) ON DELETE CASCADE,
    task_id                         TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                      INTEGER NOT NULL CHECK (task_epoch > 0),
    dismissed_notification_count    INTEGER NOT NULL
        CHECK (dismissed_notification_count >= 0),
    canceled_permission_count       INTEGER NOT NULL
        CHECK (canceled_permission_count >= 0),
    notification_scope_evidence     TEXT    NOT NULL,
    permission_scope_evidence       TEXT    NOT NULL,
    recorded_at_ms                  INTEGER NOT NULL
);
CREATE TABLE cleanup_step_attempt_result (
    id                          TEXT    NOT NULL PRIMARY KEY,
    cleanup_step_id             TEXT    NOT NULL REFERENCES cleanup_step(id) ON DELETE CASCADE,
    cleanup_operation_id        TEXT    NOT NULL REFERENCES cleanup_operation(id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    ordinal                     INTEGER NOT NULL CHECK (ordinal BETWEEN 1 AND 11),
    attempt                     INTEGER NOT NULL CHECK (attempt > 0),
    claim_mode                  TEXT    NOT NULL CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    outcome                     TEXT    NOT NULL CHECK (outcome IN (
        'SUCCEEDED', 'FAILED', 'INDETERMINATE')),
    external_effect_id          TEXT,
    evidence                    TEXT    NOT NULL,
    evidence_digest             TEXT    NOT NULL,
    error_message               TEXT,
    recorded_at_ms              INTEGER NOT NULL,
    UNIQUE (cleanup_step_id, attempt),
    CHECK (outcome <> 'SUCCEEDED' OR error_message IS NULL),
    CHECK (outcome = 'SUCCEEDED' OR error_message IS NOT NULL),
    CHECK (outcome <> 'SUCCEEDED' OR ordinal NOT IN (8, 9, 10)
        OR external_effect_id IS NOT NULL)
);
CREATE TABLE cleanup_step_skip_evidence (
    id                  TEXT    NOT NULL PRIMARY KEY,
    cleanup_step_id     TEXT    NOT NULL UNIQUE REFERENCES cleanup_step(id) ON DELETE CASCADE,
    reason              TEXT    NOT NULL,
    evidence            TEXT    NOT NULL,
    skipped_by          TEXT    NOT NULL,
    skipped_at_ms       INTEGER NOT NULL
);
CREATE TABLE cleanup_step_waiver (
    id                  TEXT    NOT NULL PRIMARY KEY,
    cleanup_step_id     TEXT    NOT NULL UNIQUE REFERENCES cleanup_step(id) ON DELETE CASCADE,
    actor_id            TEXT    NOT NULL,
    reason              TEXT    NOT NULL,
    evidence            TEXT    NOT NULL,
    waived_at_ms        INTEGER NOT NULL
);
CREATE TABLE task_outcome (
    id                              TEXT    NOT NULL PRIMARY KEY,
    task_id                         TEXT    NOT NULL UNIQUE
        REFERENCES tasks(id) ON DELETE CASCADE,
    trunk_id                        TEXT    NOT NULL REFERENCES threads(id),
    task_epoch                      INTEGER NOT NULL CHECK (task_epoch > 0),
    terminal_acceptance_id          TEXT    NOT NULL UNIQUE
        REFERENCES task_terminal_acceptance(id),
    cleanup_operation_id            TEXT    NOT NULL UNIQUE
        REFERENCES cleanup_operation(id),
    cleanup_stage_id                TEXT    NOT NULL UNIQUE
        REFERENCES cleanup_stage(stage_id),
    terminal_reason                 TEXT    NOT NULL CHECK (terminal_reason IN (
        'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    pr_id                           TEXT REFERENCES pr(id),
    remote_pr_binding_id            TEXT REFERENCES remote_pr_binding(id),
    remote_terminal_observation_id  TEXT REFERENCES remote_terminal_observation(id),
    observed_head_sha               TEXT,
    cleanup_summary_digest          TEXT    NOT NULL,
    summary_state                   TEXT    NOT NULL CHECK (summary_state IN (
        'FALLBACK', 'BRAIN_GENERATED')),
    summary_text                    TEXT    NOT NULL,
    summary_digest                  TEXT    NOT NULL,
    summary_operation_id            TEXT,
    follow_up_proposals_json        TEXT    NOT NULL DEFAULT '[]'
        CHECK (json_valid(follow_up_proposals_json)),
    backlog_items_json              TEXT    NOT NULL DEFAULT '[]'
        CHECK (json_valid(backlog_items_json)),
    recorded_at_ms                  INTEGER NOT NULL,
    summary_updated_at_ms           INTEGER,
    CHECK ((pr_id IS NULL) = (remote_pr_binding_id IS NULL)),
    CHECK ((summary_state = 'FALLBACK'
            AND summary_operation_id IS NULL
            AND summary_updated_at_ms IS NULL
            AND summary_text = 'TaskOutcome:' || task_id || ':'
                || terminal_reason || ':' || cleanup_summary_digest
            AND summary_digest = cleanup_summary_digest
            AND follow_up_proposals_json = '[]'
            AND backlog_items_json = '[]')
        OR (summary_state = 'BRAIN_GENERATED'
            AND summary_operation_id IS NOT NULL
            AND summary_updated_at_ms IS NOT NULL))
);
CREATE TABLE trunk_outcome_inbox (
    id                      TEXT    NOT NULL PRIMARY KEY,
    trunk_id                TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    task_id                 TEXT    NOT NULL UNIQUE REFERENCES tasks(id) ON DELETE CASCADE,
    task_outcome_id         TEXT    NOT NULL UNIQUE REFERENCES task_outcome(id) ON DELETE CASCADE,
    delivery_key            TEXT    NOT NULL UNIQUE,
    fallback_summary_marker TEXT    NOT NULL,
    status                  TEXT    NOT NULL CHECK (status IN ('PENDING', 'DELIVERED')),
    created_at_ms           INTEGER NOT NULL,
    delivered_at_ms         INTEGER,
    delivery_evidence       TEXT, fallback_summary_text TEXT, returned_trunk_version INTEGER, legacy_delivery_evidence TEXT, legacy_delivered_at_ms INTEGER,
    CHECK ((status = 'DELIVERED') =
        (delivered_at_ms IS NOT NULL AND delivery_evidence IS NOT NULL))
);
CREATE TABLE task_outcome_summary_operation (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_outcome_id     TEXT    NOT NULL REFERENCES task_outcome(id) ON DELETE CASCADE,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch          INTEGER NOT NULL CHECK (task_epoch > 0),
    task_turn_id        TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    dispatch_ticket_id  TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    operation_id        TEXT    NOT NULL UNIQUE,
    semantic_attempt    INTEGER NOT NULL CHECK (semantic_attempt > 0),
    status              TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'SUCCEEDED', 'FAILED', 'CANCELED')),
    summary_text        TEXT,
    summary_digest      TEXT,
    error_message       TEXT,
    requested_at_ms     INTEGER NOT NULL,
    completed_at_ms     INTEGER,
    UNIQUE (task_outcome_id, semantic_attempt),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK ((status = 'SUCCEEDED') =
        (summary_text IS NOT NULL AND summary_digest IS NOT NULL)),
    CHECK (status <> 'FAILED' OR error_message IS NOT NULL)
);
CREATE UNIQUE INDEX idx_task_outcome_one_requested_summary
    ON task_outcome_summary_operation(task_outcome_id)
    WHERE status = 'REQUESTED';
CREATE TABLE stage_initial_result_request (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL UNIQUE REFERENCES stage(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    stage_kind                 TEXT    NOT NULL CHECK (stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT', 'CLEANUP')),
    command_id                 TEXT    NOT NULL,
    cause                      TEXT    NOT NULL CHECK (cause IN (
        'REQUEST_PLAN_DRAFT', 'REQUEST_LOCAL_RESULT')),
    actor                      TEXT    NOT NULL,
    expected_task_epoch        INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation  INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version     INTEGER NOT NULL CHECK (expected_stage_version = 0),
    returned_stage_version     INTEGER NOT NULL CHECK (returned_stage_version = 1),
    checkpoint                 TEXT    NOT NULL,
    turn_owner_kind            TEXT    NOT NULL CHECK (turn_owner_kind IN (
        'TASK_TURN', 'STAGE_TURN')),
    turn_id                    TEXT    NOT NULL UNIQUE,
    pending_task_epoch         INTEGER NOT NULL CHECK (pending_task_epoch > 0),
    pending_stage_id           TEXT    NOT NULL,
    pending_stage_generation   INTEGER NOT NULL CHECK (pending_stage_generation > 0),
    pending_operation_id       TEXT    NOT NULL UNIQUE,
    pending_attempt            INTEGER NOT NULL CHECK (pending_attempt > 0),
    pending_code_fingerprint   TEXT,
    pending_head_sha           TEXT,
    pending_base_sha           TEXT,
    requested_at_ms            INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (length(trim(id)) > 0 AND length(trim(command_id)) > 0
        AND length(trim(actor)) > 0 AND length(trim(turn_id)) > 0
        AND length(trim(pending_operation_id)) > 0),
    CHECK (pending_stage_id = stage_id),
    CHECK (pending_stage_generation = expected_stage_generation),
    CHECK (returned_stage_version = expected_stage_version + 1),
    CHECK ((cause = 'REQUEST_PLAN_DRAFT'
            AND stage_kind = 'PLAN' AND checkpoint = 'DRAFTING'
            AND turn_owner_kind = 'TASK_TURN')
        OR (cause = 'REQUEST_LOCAL_RESULT'
            AND stage_kind = 'LOCAL_DEVELOPMENT' AND checkpoint = 'IMPLEMENTING'
            AND turn_owner_kind = 'STAGE_TURN'))
);
CREATE UNIQUE INDEX idx_plan_task_turn_one_active_purpose
    ON task_turn(trigger_stage_id, purpose)
    WHERE purpose IN ('PLAN_DRAFT', 'PLAN_SELF_REVIEW')
      AND status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING');
CREATE TABLE task_provision_plan_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    task_id                  TEXT    NOT NULL UNIQUE REFERENCES tasks(id) ON DELETE CASCADE,
    provision_operation_id   TEXT    NOT NULL UNIQUE,
    evidence_digest          TEXT    NOT NULL,
    plan_stage_id            TEXT    NOT NULL UNIQUE REFERENCES plan_stage(stage_id),
    plan_stage_generation    INTEGER NOT NULL CHECK (plan_stage_generation = 1),
    draft_turn_id            TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    draft_operation_id       TEXT    NOT NULL UNIQUE,
    draft_ticket_id          TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    recorded_at_ms           INTEGER NOT NULL,
    CHECK (length(trim(id)) > 0 AND length(trim(provision_operation_id)) > 0
        AND length(trim(evidence_digest)) > 0)
);
CREATE TABLE task_provision_failure_receipt (
    operation_id       TEXT    NOT NULL PRIMARY KEY,
    task_id            TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch         INTEGER NOT NULL CHECK (task_epoch > 0),
    raw_outcome        TEXT    NOT NULL CHECK (raw_outcome IN (
        'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_digest         TEXT    NOT NULL,
    error_message      TEXT    NOT NULL,
    blocker_id         TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    recorded_at_ms     INTEGER NOT NULL,
    CHECK (length(trim(raw_digest)) > 0 AND length(trim(error_message)) > 0)
);
CREATE TABLE plan_turn_submission (
    task_turn_id       TEXT    NOT NULL PRIMARY KEY REFERENCES task_turn(id),
    operation_id       TEXT    NOT NULL UNIQUE,
    task_id            TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch         INTEGER NOT NULL CHECK (task_epoch > 0),
    plan_stage_id      TEXT    NOT NULL REFERENCES plan_stage(stage_id) ON DELETE CASCADE,
    stage_generation   INTEGER NOT NULL CHECK (stage_generation > 0),
    plan_revision_id   TEXT    NOT NULL UNIQUE REFERENCES plan_revision(id),
    submitted_at_ms    INTEGER NOT NULL
);
CREATE TABLE plan_review_submission (
    task_turn_id       TEXT    NOT NULL PRIMARY KEY REFERENCES task_turn(id),
    operation_id       TEXT    NOT NULL UNIQUE,
    task_id            TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch         INTEGER NOT NULL CHECK (task_epoch > 0),
    plan_stage_id      TEXT    NOT NULL REFERENCES plan_stage(stage_id) ON DELETE CASCADE,
    stage_generation   INTEGER NOT NULL CHECK (stage_generation > 0),
    self_review_id     TEXT    NOT NULL UNIQUE REFERENCES plan_self_review(id),
    plan_revision_id   TEXT    NOT NULL UNIQUE REFERENCES plan_revision(id),
    reviewed_digest    TEXT    NOT NULL,
    verdict            TEXT    NOT NULL CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'BLOCKED')),
    concerns_json      TEXT    NOT NULL CHECK (
        json_valid(concerns_json) AND json_type(concerns_json) = 'array'),
    follow_ups_json    TEXT    NOT NULL CHECK (
        json_valid(follow_ups_json) AND json_type(follow_ups_json) = 'array'),
    stewardship_json   TEXT    NOT NULL CHECK (
        json_valid(stewardship_json) AND json_type(stewardship_json) = 'array'),
    submitted_at_ms    INTEGER NOT NULL,
    CHECK (verdict <> 'APPROVED' OR concerns_json = '[]')
);
CREATE TABLE plan_self_review_attempt (
    self_review_id       TEXT    NOT NULL REFERENCES plan_self_review(id) ON DELETE CASCADE,
    attempt              INTEGER NOT NULL CHECK (attempt IN (1, 2)),
    task_turn_id         TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    operation_id         TEXT    NOT NULL UNIQUE,
    predecessor_turn_id  TEXT    UNIQUE REFERENCES task_turn(id),
    requested_at_ms      INTEGER NOT NULL,
    PRIMARY KEY (self_review_id, attempt),
    CHECK ((attempt = 1 AND predecessor_turn_id IS NULL)
        OR (attempt = 2 AND predecessor_turn_id IS NOT NULL))
);
CREATE TABLE plan_task_turn_delivery_receipt (
    task_turn_id        TEXT    NOT NULL PRIMARY KEY REFERENCES task_turn(id),
    operation_id        TEXT    NOT NULL UNIQUE,
    raw_outcome         TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_evidence_digest TEXT    NOT NULL,
    acceptance          TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    domain_result       TEXT    NOT NULL CHECK (domain_result IN (
        'DRAFT_ACCEPTED', 'REVIEW_APPROVED', 'REVIEW_FINDINGS',
        'REVIEW_RETRY_REQUESTED', 'REVIEW_BLOCKED', 'PROTOCOL_BLOCKED',
        'TURN_FAILED', 'TURN_CANCELED', 'SUPERSEDED')),
    recorded_at_ms      INTEGER NOT NULL
);
CREATE TABLE stage_plan_review_retry_request (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                 TEXT    NOT NULL,
    actor                      TEXT    NOT NULL,
    self_review_id             TEXT    NOT NULL REFERENCES plan_self_review(id),
    predecessor_turn_id        TEXT    NOT NULL REFERENCES task_turn(id),
    replacement_turn_id        TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    expected_stage_version     INTEGER NOT NULL CHECK (expected_stage_version > 0),
    returned_stage_version     INTEGER NOT NULL,
    subject_task_epoch         INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_generation   INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id       TEXT    NOT NULL UNIQUE,
    subject_attempt            INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_code_fingerprint   TEXT    NOT NULL,
    subject_head_sha           TEXT    NOT NULL,
    subject_base_sha           TEXT    NOT NULL,
    pending_task_epoch         INTEGER NOT NULL CHECK (pending_task_epoch > 0),
    pending_stage_generation   INTEGER NOT NULL CHECK (pending_stage_generation > 0),
    pending_operation_id       TEXT    NOT NULL UNIQUE,
    pending_attempt            INTEGER NOT NULL CHECK (pending_attempt > 0),
    pending_code_fingerprint   TEXT    NOT NULL,
    pending_head_sha           TEXT    NOT NULL,
    pending_base_sha           TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (returned_stage_version = expected_stage_version + 1),
    CHECK (pending_task_epoch = subject_task_epoch
        AND pending_stage_generation = subject_stage_generation)
);
CREATE TABLE stage_plan_terminal_result (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                 TEXT    NOT NULL,
    actor                      TEXT    NOT NULL,
    cause                      TEXT    NOT NULL CHECK (cause IN (
        'PLAN_DRAFT_FAILED', 'PLAN_SELF_REVIEW_FAILED',
        'PLAN_SELF_REVIEW_NO_VERDICT', 'PLAN_SELF_REVIEW_BLOCKED')),
    proof_id                   TEXT    NOT NULL,
    checkpoint                 TEXT    NOT NULL CHECK (checkpoint IN (
        'DRAFTING', 'SELF_REVIEW')),
    expected_stage_version     INTEGER NOT NULL CHECK (expected_stage_version > 0),
    returned_stage_version     INTEGER NOT NULL,
    subject_task_epoch         INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_generation   INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id       TEXT    NOT NULL UNIQUE,
    subject_attempt            INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_code_fingerprint   TEXT    NOT NULL,
    subject_head_sha           TEXT    NOT NULL,
    subject_base_sha           TEXT    NOT NULL,
    recorded_at_ms             INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (returned_stage_version = expected_stage_version + 1)
);
CREATE TABLE stage_plan_edit_review_request (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                 TEXT    NOT NULL,
    actor                      TEXT    NOT NULL,
    expected_task_epoch        INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation  INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version     INTEGER NOT NULL CHECK (expected_stage_version > 0),
    returned_stage_version     INTEGER NOT NULL,
    revision_id                TEXT    NOT NULL REFERENCES plan_revision(id),
    pending_task_epoch         INTEGER NOT NULL CHECK (pending_task_epoch > 0),
    pending_stage_id           TEXT    NOT NULL,
    pending_stage_generation   INTEGER NOT NULL CHECK (pending_stage_generation > 0),
    pending_operation_id       TEXT    NOT NULL UNIQUE,
    pending_attempt            INTEGER NOT NULL CHECK (pending_attempt > 0),
    pending_code_fingerprint   TEXT    NOT NULL,
    pending_head_sha           TEXT    NOT NULL,
    pending_base_sha           TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (returned_stage_version = expected_stage_version + 1),
    CHECK (pending_stage_id = stage_id
        AND pending_stage_generation = expected_stage_generation
        AND pending_task_epoch = expected_task_epoch)
);
CREATE TABLE plan_user_edit_receipt (
    request_id                TEXT    NOT NULL PRIMARY KEY,
    task_id                   TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                INTEGER NOT NULL CHECK (task_epoch > 0),
    plan_stage_id             TEXT    NOT NULL REFERENCES plan_stage(stage_id) ON DELETE CASCADE,
    stage_generation          INTEGER NOT NULL CHECK (stage_generation > 0),
    expected_stage_version    INTEGER NOT NULL CHECK (expected_stage_version >= 0),
    actor                     TEXT    NOT NULL,
    previous_revision_id      TEXT    NOT NULL REFERENCES plan_revision(id),
    plan_revision_id          TEXT    NOT NULL UNIQUE REFERENCES plan_revision(id),
    content_digest            TEXT    NOT NULL,
    self_review_id            TEXT    NOT NULL UNIQUE REFERENCES plan_self_review(id),
    review_turn_id            TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    review_operation_id       TEXT    NOT NULL UNIQUE,
    review_ticket_id          TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    review_command_id         TEXT    NOT NULL UNIQUE,
    recorded_at_ms            INTEGER NOT NULL,
    CHECK (length(trim(request_id)) > 0 AND length(trim(actor)) > 0
        AND length(trim(content_digest)) > 0)
);
CREATE TABLE task_replan_plan_receipt (
    replan_request_id      TEXT    NOT NULL PRIMARY KEY
        REFERENCES task_replan_request(id),
    task_id                TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch             INTEGER NOT NULL CHECK (task_epoch > 1),
    plan_stage_id          TEXT    NOT NULL UNIQUE REFERENCES plan_stage(stage_id),
    plan_stage_generation  INTEGER NOT NULL CHECK (plan_stage_generation > 0),
    draft_turn_id          TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    draft_operation_id     TEXT    NOT NULL UNIQUE,
    draft_ticket_id        TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    recorded_at_ms         INTEGER NOT NULL
);
CREATE TABLE local_stage_turn_request (
    id                         TEXT    NOT NULL PRIMARY KEY,
    command_id                 TEXT    NOT NULL UNIQUE,
    stage_turn_id              TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    kind                       TEXT    NOT NULL CHECK (kind IN (
        'IMPLEMENTATION', 'BRAIN_FINDINGS', 'LOCAL_FEEDBACK', 'STEERING')),
    queue_mode                 TEXT    NOT NULL CHECK (queue_mode IN (
        'IMMEDIATE', 'APPEND', 'CANCEL_AND_REPLACE')),
    predecessor_turn_id        TEXT REFERENCES stage_turn(id),
    brain_review_episode_id    TEXT REFERENCES brain_review_episode(id),
    local_feedback_batch_id    TEXT REFERENCES local_feedback_batch(id),
    prompt_digest              TEXT    NOT NULL,
    requested_by               TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    cancellation_requested_at_ms INTEGER,
    CHECK (length(prompt_digest) = 64 AND length(requested_by) > 0),
    CHECK ((queue_mode = 'IMMEDIATE') = (predecessor_turn_id IS NULL)),
    CHECK ((kind = 'BRAIN_FINDINGS') = (brain_review_episode_id IS NOT NULL)),
    CHECK ((kind = 'LOCAL_FEEDBACK') = (local_feedback_batch_id IS NOT NULL))
);
CREATE TABLE local_stage_command_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL
        REFERENCES stage(id) ON DELETE CASCADE,
    task_id                           TEXT    NOT NULL
        REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'REQUEST_LOCAL_RESULT', 'REPLACE_LOCAL_RESULT',
        'CLEAR_LOCAL_RESULT', 'ACCEPT_LOCAL_CODE_RESULT',
        'BEGIN_LOCAL_VALIDATION', 'ACCEPT_BRAIN_BUDGET_EXHAUSTION')),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT,
    subject_task_epoch                INTEGER CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT    NOT NULL CHECK (length(proof_id) > 0),
    returned_kind                     TEXT    NOT NULL
        CHECK (returned_kind = 'LOCAL_DEVELOPMENT'),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_checkpoint               TEXT    NOT NULL CHECK (returned_checkpoint IN (
        'IMPLEMENTING', 'VALIDATING', 'BRAIN_REVIEW', 'LOCAL_REVIEW',
        'PUBLISHING', 'ADDRESSING_BRAIN_FINDINGS',
        'ADDRESSING_LOCAL_FEEDBACK')),
    returned_end_reason               TEXT CHECK (returned_end_reason IS NULL),
    returned_pending_task_epoch       INTEGER CHECK (returned_pending_task_epoch > 0),
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (stage_id, command_id),
    CHECK ((expected_task_epoch IS NULL
            AND expected_stage_generation IS NULL
            AND expected_stage_version IS NULL)
        OR (expected_task_epoch IS NOT NULL
            AND expected_stage_generation IS NOT NULL
            AND expected_stage_version IS NOT NULL)),
    CHECK (source_checkpoint IS NULL OR expected_task_epoch IS NOT NULL),
    CHECK ((expected_task_epoch IS NOT NULL) = (cause IN (
        'REQUEST_LOCAL_RESULT', 'BEGIN_LOCAL_VALIDATION',
        'ACCEPT_BRAIN_BUDGET_EXHAUSTION'))),
    CHECK ((source_checkpoint IS NOT NULL) = (cause IN (
        'REQUEST_LOCAL_RESULT', 'BEGIN_LOCAL_VALIDATION',
        'ACCEPT_BRAIN_BUDGET_EXHAUSTION'))),
    CHECK (expected_stage_version IS NULL
        OR returned_version = expected_stage_version + 1),
    CHECK ((subject_operation_id IS NULL
            AND subject_task_epoch IS NULL AND subject_stage_id IS NULL
            AND subject_stage_generation IS NULL AND subject_attempt IS NULL
            AND subject_expected_code_fingerprint IS NULL
            AND subject_expected_head_sha IS NULL
            AND subject_expected_base_sha IS NULL)
        OR (subject_operation_id IS NOT NULL
            AND length(subject_operation_id) > 0
            AND subject_task_epoch IS NOT NULL
            AND subject_stage_id = stage_id
            AND subject_stage_generation = returned_generation
            AND subject_attempt > 0)),
    CHECK ((subject_operation_id IS NOT NULL) = (cause IN (
        'REQUEST_LOCAL_RESULT', 'REPLACE_LOCAL_RESULT',
        'CLEAR_LOCAL_RESULT', 'ACCEPT_LOCAL_CODE_RESULT'))),
    CHECK ((returned_pending_operation_id IS NULL
            AND returned_pending_task_epoch IS NULL
            AND returned_pending_stage_id IS NULL
            AND returned_pending_stage_generation IS NULL
            AND returned_pending_attempt IS NULL
            AND returned_pending_code_fingerprint IS NULL
            AND returned_pending_head_sha IS NULL
            AND returned_pending_base_sha IS NULL)
        OR (returned_pending_operation_id IS NOT NULL
            AND length(returned_pending_operation_id) > 0
            AND returned_pending_task_epoch IS NOT NULL
            AND returned_pending_stage_id = stage_id
            AND returned_pending_stage_generation = returned_generation
            AND returned_pending_attempt > 0)),
    CHECK (returned_end_reason IS NULL),
    CHECK (disposition <> 'SUPERSEDED' OR subject_operation_id IS NOT NULL),
    FOREIGN KEY (stage_id, task_id, returned_kind, returned_generation)
        REFERENCES stage(id, task_id, kind, generation) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE task_brain_request_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    task_id                           TEXT    NOT NULL
        REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause = 'REQUEST_BRAIN_REVIEW'),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition = 'APPLIED'),
    expected_task_epoch               INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_task_version             INTEGER NOT NULL CHECK (expected_task_version >= 0),
    subject_task_epoch                INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT    NOT NULL,
    subject_stage_generation          INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id              TEXT    NOT NULL CHECK (length(subject_operation_id) > 0),
    subject_attempt                   INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    brain_verdict                     TEXT CHECK (brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    proof_id                          TEXT    NOT NULL CHECK (length(proof_id) > 0),
    next_stage_id                     TEXT,
    next_stage_kind                   TEXT CHECK (next_stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT', 'CLEANUP')),
    next_stage_generation             INTEGER CHECK (next_stage_generation > 0),
    returned_trunk_id                 TEXT    NOT NULL REFERENCES threads(id),
    returned_lifecycle                TEXT    NOT NULL CHECK (returned_lifecycle = 'ACTIVE'),
    returned_epoch                    INTEGER NOT NULL CHECK (returned_epoch > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_current_stage_id         TEXT    NOT NULL,
    returned_pending_task_epoch       INTEGER NOT NULL CHECK (returned_pending_task_epoch > 0),
    returned_pending_stage_id         TEXT    NOT NULL,
    returned_pending_stage_generation INTEGER NOT NULL
        CHECK (returned_pending_stage_generation > 0),
    returned_pending_operation_id     TEXT    NOT NULL
        CHECK (length(returned_pending_operation_id) > 0),
    returned_pending_attempt          INTEGER NOT NULL CHECK (returned_pending_attempt > 0),
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    returned_last_brain_verdict       TEXT CHECK (returned_last_brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    returned_last_brain_task_epoch    INTEGER CHECK (returned_last_brain_task_epoch > 0),
    returned_last_brain_stage_id      TEXT,
    returned_last_brain_stage_generation INTEGER,
    returned_last_brain_operation_id  TEXT,
    returned_last_brain_attempt       INTEGER,
    returned_last_brain_code_fingerprint TEXT,
    returned_last_brain_head_sha      TEXT,
    returned_last_brain_base_sha      TEXT,
    returned_terminal_intent          TEXT CHECK (returned_terminal_intent IN (
        'CANCELED', 'COMPLETED', 'REMOTE_CLOSED')),
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (task_id, command_id),
    CHECK (brain_verdict IS NULL),
    CHECK (next_stage_id IS NULL AND next_stage_kind IS NULL
        AND next_stage_generation IS NULL),
    CHECK (returned_terminal_intent IS NULL),
    CHECK (returned_epoch = expected_task_epoch),
    CHECK (returned_version = expected_task_version + 1),
    CHECK (returned_current_stage_id = subject_stage_id),
    CHECK (returned_pending_task_epoch = subject_task_epoch
        AND returned_pending_stage_id = subject_stage_id
        AND returned_pending_stage_generation = subject_stage_generation
        AND returned_pending_operation_id = subject_operation_id
        AND returned_pending_attempt = subject_attempt
        AND returned_pending_code_fingerprint
            IS subject_expected_code_fingerprint
        AND returned_pending_head_sha IS subject_expected_head_sha
        AND returned_pending_base_sha IS subject_expected_base_sha),
    CHECK ((returned_last_brain_operation_id IS NULL
            AND returned_last_brain_verdict IS NULL
            AND returned_last_brain_task_epoch IS NULL
            AND returned_last_brain_stage_id IS NULL
            AND returned_last_brain_stage_generation IS NULL
            AND returned_last_brain_attempt IS NULL
            AND returned_last_brain_code_fingerprint IS NULL
            AND returned_last_brain_head_sha IS NULL
            AND returned_last_brain_base_sha IS NULL)
        OR (returned_last_brain_operation_id IS NOT NULL
            AND length(returned_last_brain_operation_id) > 0
            AND returned_last_brain_verdict IS NOT NULL
            AND returned_last_brain_task_epoch IS NOT NULL
            AND returned_last_brain_stage_id IS NOT NULL
            AND returned_last_brain_stage_generation > 0
            AND returned_last_brain_attempt > 0)),
    FOREIGN KEY (subject_stage_id, task_id)
        REFERENCES stage(id, task_id) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (returned_current_stage_id, task_id)
        REFERENCES stage(id, task_id) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE local_stage_turn_delivery_receipt (
    stage_turn_id       TEXT    NOT NULL PRIMARY KEY REFERENCES stage_turn(id),
    operation_id        TEXT    NOT NULL UNIQUE,
    raw_outcome         TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest   TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance          TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    dev_report_id       TEXT UNIQUE REFERENCES dev_report(id),
    validation_operation_id TEXT UNIQUE REFERENCES validation_operation(id),
    recorded_at_ms      INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    CHECK ((dev_report_id IS NOT NULL) =
        (acceptance = 'ACCEPTED' AND raw_outcome = 'SUCCEEDED')),
    CHECK ((validation_operation_id IS NOT NULL) = (dev_report_id IS NOT NULL))
);
CREATE TABLE local_validation_delivery_receipt (
    validation_operation_id TEXT    NOT NULL PRIMARY KEY
        REFERENCES validation_operation(id) ON DELETE CASCADE,
    operation_id             TEXT    NOT NULL UNIQUE,
    raw_outcome              TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest        TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance               TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    validation_evidence_id   TEXT UNIQUE REFERENCES validation_evidence(id),
    brain_review_episode_id  TEXT UNIQUE REFERENCES brain_review_episode(id),
    recorded_at_ms           INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    CHECK (brain_review_episode_id IS NULL OR validation_evidence_id IS NOT NULL)
);
CREATE TABLE local_brain_turn_delivery_receipt (
    task_turn_id          TEXT    NOT NULL PRIMARY KEY REFERENCES task_turn(id),
    operation_id          TEXT    NOT NULL UNIQUE,
    raw_outcome           TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest     TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance            TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    brain_review_episode_id TEXT  NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    verdict               TEXT CHECK (verdict IN ('APPROVED', 'CHANGES_REQUESTED')),
    blocker_id            TEXT UNIQUE REFERENCES task_blocker(id),
    next_stage_turn_request_id TEXT UNIQUE REFERENCES local_stage_turn_request(id),
    recorded_at_ms        INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    CHECK ((verdict IS NOT NULL) = (raw_outcome = 'SUCCEEDED'
        AND acceptance = 'ACCEPTED')),
    CHECK (blocker_id IS NULL OR verdict IS NULL),
    CHECK (next_stage_turn_request_id IS NULL
        OR verdict = 'CHANGES_REQUESTED')
);
CREATE TABLE task_brain_budget_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL
        CHECK (cause = 'ACCEPT_BRAIN_BUDGET_EXHAUSTION'),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER,
    expected_task_version             INTEGER,
    subject_task_epoch                INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT    NOT NULL,
    subject_stage_generation          INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id              TEXT    NOT NULL CHECK (length(subject_operation_id) > 0),
    subject_attempt                   INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_expected_code_fingerprint TEXT    NOT NULL,
    subject_expected_head_sha         TEXT    NOT NULL,
    subject_expected_base_sha         TEXT    NOT NULL,
    brain_verdict                     TEXT,
    proof_id                          TEXT    NOT NULL REFERENCES task_blocker(id),
    next_stage_id                     TEXT,
    next_stage_kind                   TEXT,
    next_stage_generation             INTEGER,
    returned_trunk_id                 TEXT    NOT NULL REFERENCES threads(id),
    returned_lifecycle                TEXT    NOT NULL CHECK (returned_lifecycle = 'ACTIVE'),
    returned_epoch                    INTEGER NOT NULL CHECK (returned_epoch > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_current_stage_id         TEXT    NOT NULL,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    returned_last_brain_verdict       TEXT CHECK (returned_last_brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    returned_last_brain_task_epoch    INTEGER,
    returned_last_brain_stage_id      TEXT,
    returned_last_brain_stage_generation INTEGER,
    returned_last_brain_operation_id  TEXT,
    returned_last_brain_attempt       INTEGER,
    returned_last_brain_code_fingerprint TEXT,
    returned_last_brain_head_sha      TEXT,
    returned_last_brain_base_sha      TEXT,
    returned_terminal_intent          TEXT,
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (task_id, command_id),
    CHECK (expected_task_epoch IS NULL AND expected_task_version IS NULL),
    CHECK (brain_verdict IS NULL AND next_stage_id IS NULL
        AND next_stage_kind IS NULL AND next_stage_generation IS NULL),
    CHECK ((returned_pending_operation_id IS NULL
            AND returned_pending_task_epoch IS NULL
            AND returned_pending_stage_id IS NULL
            AND returned_pending_stage_generation IS NULL
            AND returned_pending_attempt IS NULL
            AND returned_pending_code_fingerprint IS NULL
            AND returned_pending_head_sha IS NULL
            AND returned_pending_base_sha IS NULL)
        OR disposition = 'SUPERSEDED')
);
CREATE TABLE cleanup_step_retry_request (
    id                  TEXT    NOT NULL PRIMARY KEY,
    cleanup_step_id     TEXT    NOT NULL REFERENCES cleanup_step(id) ON DELETE CASCADE,
    cleanup_operation_id TEXT   NOT NULL REFERENCES cleanup_operation(id) ON DELETE CASCADE,
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    failed_attempt      INTEGER NOT NULL CHECK (failed_attempt > 0),
    requested_by        TEXT    NOT NULL,
    reason              TEXT    NOT NULL,
    status              TEXT    NOT NULL CHECK (status IN ('PENDING', 'CONSUMED')),
    requested_at_ms     INTEGER NOT NULL,
    consumed_at_ms      INTEGER,
    UNIQUE (cleanup_step_id, failed_attempt),
    CHECK ((status = 'CONSUMED') = (consumed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_cleanup_step_one_pending_retry
    ON cleanup_step_retry_request(cleanup_step_id)
    WHERE status = 'PENDING';
CREATE TABLE publish_delivery_receipt (
    operation_id       TEXT    NOT NULL PRIMARY KEY
        REFERENCES publish_operation(operation_id),
    raw_result_digest  TEXT    NOT NULL,
    outcome            TEXT    NOT NULL CHECK (outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED')),
    acceptance         TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    remote_stage_id    TEXT REFERENCES stage(id),
    delivered_at_ms    INTEGER NOT NULL,
    CHECK ((outcome = 'SUCCEEDED' AND acceptance = 'ACCEPTED')
        = (remote_stage_id IS NOT NULL))
);
CREATE TABLE remote_feedback_stage_turn_request (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id    TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    stage_turn_id               TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    remote_development_stage_id TEXT    NOT NULL REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    predecessor_turn_id         TEXT REFERENCES stage_turn(id),
    prompt_digest               TEXT    NOT NULL CHECK (length(prompt_digest) = 64),
    requested_by                TEXT    NOT NULL CHECK (length(requested_by) > 0),
    requested_at_ms             INTEGER NOT NULL,
    UNIQUE (remote_feedback_batch_id, semantic_attempt)
);
CREATE TABLE remote_feedback_repair_result (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id    TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    repair_stage_turn_id        TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_development_stage_id TEXT    NOT NULL REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    subject_head_sha            TEXT    NOT NULL,
    proposed_head_sha           TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    summary                     TEXT    NOT NULL,
    result_digest               TEXT    NOT NULL CHECK (length(result_digest) = 64),
    completed_at_ms             INTEGER NOT NULL,
    CHECK (length(summary) > 0),
    UNIQUE (remote_feedback_batch_id, repair_stage_turn_id)
);
CREATE TABLE remote_feedback_reply_draft (
    id                       TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    repair_result_id         TEXT    NOT NULL REFERENCES remote_feedback_repair_result(id) ON DELETE CASCADE,
    batch_item_ordinal       INTEGER NOT NULL CHECK (batch_item_ordinal > 0),
    kind                     TEXT    NOT NULL CHECK (kind IN (
        'POST_INLINE_REPLY', 'POST_TOP_LEVEL_REPLY', 'RESOLVE_THREAD')),
    body                     TEXT,
    body_digest              TEXT,
    external_target          TEXT,
    ordinal                  INTEGER NOT NULL CHECK (ordinal > 0),
    CHECK ((kind = 'RESOLVE_THREAD' AND body IS NULL AND body_digest IS NULL)
        OR (kind <> 'RESOLVE_THREAD' AND body IS NOT NULL
            AND body_digest IS NOT NULL AND length(body) > 0)),
    UNIQUE (repair_result_id, ordinal),
    UNIQUE (repair_result_id, batch_item_ordinal, kind),
    FOREIGN KEY (remote_feedback_batch_id, batch_item_ordinal)
        REFERENCES remote_feedback_batch_item(remote_feedback_batch_id, ordinal)
);
CREATE TABLE remote_feedback_validation_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id    TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    repair_result_id            TEXT    NOT NULL UNIQUE REFERENCES remote_feedback_repair_result(id),
    remote_development_stage_id TEXT    NOT NULL REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    code_fingerprint            TEXT    NOT NULL,
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    error_message               TEXT,
    CHECK ((status IN ('COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL))
);
CREATE TABLE remote_feedback_validation_attempt_evidence (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id    TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    repair_result_id            TEXT    NOT NULL UNIQUE REFERENCES remote_feedback_repair_result(id),
    validation_operation_id     TEXT    NOT NULL UNIQUE REFERENCES remote_feedback_validation_operation(id),
    validation_pass_id          INTEGER NOT NULL UNIQUE REFERENCES validation_pass(id),
    remote_development_stage_id TEXT    NOT NULL REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    repair_stage_turn_id        TEXT    NOT NULL REFERENCES stage_turn(id),
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    subject_head_sha            TEXT    NOT NULL,
    proposed_head_sha           TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    passed                      INTEGER NOT NULL CHECK (passed IN (0, 1)),
    failures_json               TEXT    NOT NULL,
    evidence                    TEXT    NOT NULL,
    completed_at_ms             INTEGER NOT NULL,
    UNIQUE (remote_feedback_batch_id, semantic_attempt)
);
CREATE TABLE remote_feedback_brain_episode (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_feedback_batch_id    TEXT    NOT NULL REFERENCES remote_feedback_batch(id) ON DELETE CASCADE,
    validation_attempt_evidence_id TEXT NOT NULL UNIQUE REFERENCES remote_feedback_validation_attempt_evidence(id),
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_development_stage_id TEXT    NOT NULL REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    task_turn_id                TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    code_fingerprint            TEXT    NOT NULL,
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    verdict                     TEXT CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED', 'BLOCKED')),
    unresolved_finding_count    INTEGER CHECK (unresolved_finding_count >= 0),
    evidence                    TEXT,
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    CHECK ((status = 'SUCCEEDED') = (verdict IS NOT NULL
        AND unresolved_finding_count IS NOT NULL AND evidence IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (verdict <> 'APPROVED' OR unresolved_finding_count = 0),
    UNIQUE (remote_feedback_batch_id, semantic_attempt)
);
CREATE TABLE remote_feedback_effect_payload (
    remote_feedback_effect_step_id TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_feedback_effect_step(id) ON DELETE CASCADE,
    payload_kind                   TEXT NOT NULL CHECK (payload_kind IN (
        'TEXT', 'REVIEW', 'REVIEWER', 'NUDGE', 'RESOLUTION', 'PUSH')),
    payload                        TEXT NOT NULL,
    payload_digest                 TEXT NOT NULL,
    created_at_ms                  INTEGER NOT NULL,
    CHECK (length(payload) > 0)
);
CREATE TABLE remote_feedback_effect_dispatch (
    remote_feedback_effect_step_id TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_feedback_effect_step(id) ON DELETE CASCADE,
    dispatch_ticket_id             TEXT NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    operation_id                   TEXT NOT NULL UNIQUE,
    dispatched_at_ms               INTEGER NOT NULL
);
CREATE TABLE remote_mark_ready_dispatch (
    remote_mark_ready_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_mark_ready_operation(id) ON DELETE CASCADE,
    dispatch_ticket_id             TEXT NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    operation_id                   TEXT NOT NULL UNIQUE,
    dispatched_at_ms               INTEGER NOT NULL
);
CREATE TABLE remote_task_brain_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'REQUEST_BRAIN_REVIEW', 'ACCEPT_BRAIN_VERDICT')),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER,
    expected_task_version             INTEGER,
    subject_task_epoch                INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT    NOT NULL,
    subject_stage_generation          INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id              TEXT    NOT NULL CHECK (length(subject_operation_id) > 0),
    subject_attempt                   INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    brain_verdict                     TEXT CHECK (brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    proof_id                          TEXT,
    next_stage_id                     TEXT,
    next_stage_kind                   TEXT,
    next_stage_generation             INTEGER,
    returned_trunk_id                 TEXT    NOT NULL REFERENCES threads(id),
    returned_lifecycle                TEXT    NOT NULL CHECK (returned_lifecycle = 'ACTIVE'),
    returned_epoch                    INTEGER NOT NULL CHECK (returned_epoch > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_current_stage_id         TEXT    NOT NULL,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    returned_last_brain_verdict       TEXT CHECK (returned_last_brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    returned_last_brain_task_epoch    INTEGER,
    returned_last_brain_stage_id      TEXT,
    returned_last_brain_stage_generation INTEGER,
    returned_last_brain_operation_id  TEXT,
    returned_last_brain_attempt       INTEGER,
    returned_last_brain_code_fingerprint TEXT,
    returned_last_brain_head_sha      TEXT,
    returned_last_brain_base_sha      TEXT,
    returned_terminal_intent          TEXT,
    recorded_at_ms                    INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    CHECK (next_stage_id IS NULL AND next_stage_kind IS NULL
        AND next_stage_generation IS NULL),
    CHECK (returned_terminal_intent IS NULL),
    CHECK ((cause = 'REQUEST_BRAIN_REVIEW'
            AND disposition = 'APPLIED'
            AND expected_task_epoch IS NOT NULL
            AND expected_task_version IS NOT NULL
            AND proof_id IS NOT NULL AND brain_verdict IS NULL
            AND returned_pending_operation_id = subject_operation_id)
        OR (cause = 'ACCEPT_BRAIN_VERDICT'
            AND expected_task_epoch IS NULL
            AND expected_task_version IS NULL
            AND proof_id IS NULL AND brain_verdict IS NOT NULL)),
    FOREIGN KEY (subject_stage_id, task_id)
        REFERENCES stage(id, task_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (returned_current_stage_id, task_id)
        REFERENCES stage(id, task_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE remote_runtime_delivery_receipt (
    id                  TEXT    NOT NULL PRIMARY KEY,
    operation_id        TEXT    NOT NULL UNIQUE,
    callback_route      TEXT    NOT NULL CHECK (callback_route IN (
        'REMOTE_FEEDBACK_TURN_RESULT',
        'REMOTE_FEEDBACK_VALIDATION_RESULT',
        'REMOTE_FEEDBACK_BRAIN_RESULT',
        'REMOTE_FEEDBACK_EFFECT_RESULT',
        'REMOTE_MARK_READY_RESULT')),
    raw_result_digest   TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance          TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED', 'REJECTED')),
    evidence            TEXT    NOT NULL,
    recorded_at_ms      INTEGER NOT NULL
);
CREATE TABLE remote_stage_runtime_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'COMPLETE_REMOTE_FEEDBACK_PUSH',
        'COMPLETE_REMOTE_FEEDBACK_NO_PUSH',
        'COMPLETE_REMOTE_MARK_READY',
        'ACCEPT_REMOTE_READINESS')),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER NOT NULL CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT    NOT NULL CHECK (source_checkpoint IN (
        'ADDRESSING_REMOTE_FEEDBACK', 'AWAITING_READY',
        'WAITING_REMOTE_REVIEW')),
    subject_task_epoch                INTEGER,
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT    NOT NULL CHECK (length(proof_id) > 0),
    returned_kind                     TEXT    NOT NULL CHECK (
        returned_kind = 'REMOTE_DEVELOPMENT'),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_checkpoint               TEXT    NOT NULL CHECK (returned_checkpoint IN (
        'WAITING_CI', 'WAITING_REMOTE_REVIEW', 'READY_TO_MERGE')),
    returned_end_reason               TEXT,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    recorded_at_ms                    INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (returned_version = expected_stage_version + 1),
    CHECK (subject_operation_id IS NULL
        AND subject_task_epoch IS NULL AND subject_stage_id IS NULL
        AND subject_stage_generation IS NULL AND subject_attempt IS NULL
        AND subject_expected_code_fingerprint IS NULL
        AND subject_expected_head_sha IS NULL
        AND subject_expected_base_sha IS NULL),
    CHECK (returned_pending_operation_id IS NULL
        AND returned_pending_task_epoch IS NULL
        AND returned_pending_stage_id IS NULL
        AND returned_pending_stage_generation IS NULL
        AND returned_pending_attempt IS NULL
        AND returned_pending_code_fingerprint IS NULL
        AND returned_pending_head_sha IS NULL
        AND returned_pending_base_sha IS NULL),
    CHECK (returned_end_reason IS NULL),
    CHECK ((cause = 'COMPLETE_REMOTE_FEEDBACK_PUSH'
            AND source_checkpoint = 'ADDRESSING_REMOTE_FEEDBACK'
            AND returned_checkpoint = 'WAITING_CI')
        OR (cause = 'COMPLETE_REMOTE_FEEDBACK_NO_PUSH'
            AND source_checkpoint = 'ADDRESSING_REMOTE_FEEDBACK'
            AND returned_checkpoint = 'WAITING_REMOTE_REVIEW')
        OR (cause = 'COMPLETE_REMOTE_MARK_READY'
            AND source_checkpoint = 'AWAITING_READY'
            AND returned_checkpoint = 'WAITING_REMOTE_REVIEW')
        OR (cause = 'ACCEPT_REMOTE_READINESS'
            AND source_checkpoint = 'WAITING_REMOTE_REVIEW'
            AND returned_checkpoint = 'READY_TO_MERGE'))
);
CREATE TABLE remote_ci_required_check (
    ci_policy_revision_id TEXT NOT NULL
        REFERENCES remote_ci_policy_revision(id) ON DELETE CASCADE,
    check_name            TEXT NOT NULL,
    PRIMARY KEY (ci_policy_revision_id, check_name),
    CHECK (length(trim(check_name)) > 0)
);
CREATE TABLE remote_observation_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    ci_policy_revision_id       TEXT    NOT NULL REFERENCES remote_ci_policy_revision(id),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'ACCEPTED', 'SUPERSEDED',
        'FAILED', 'CANCELED')),
    snapshot_id                 TEXT UNIQUE REFERENCES remote_pr_snapshot(id),
    ci_evaluation_id            TEXT UNIQUE REFERENCES remote_ci_evaluation(id),
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    error_message               TEXT,
    UNIQUE (remote_development_stage_id, semantic_attempt),
    CHECK ((status IN ('ACCEPTED', 'SUPERSEDED', 'FAILED', 'CANCELED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status NOT IN ('ACCEPTED', 'SUPERSEDED') OR snapshot_id IS NOT NULL),
    CHECK (ci_evaluation_id IS NULL OR snapshot_id IS NOT NULL)
);
CREATE UNIQUE INDEX idx_remote_observation_one_live_stage
    ON remote_observation_operation(remote_development_stage_id)
    WHERE status IN ('REQUESTED', 'DISPATCHED');
CREATE TABLE remote_observation_delivery_receipt (
    remote_observation_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_observation_operation(id) ON DELETE CASCADE,
    operation_id       TEXT    NOT NULL UNIQUE,
    raw_outcome        TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest  TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance         TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    snapshot_id        TEXT REFERENCES remote_pr_snapshot(id),
    ci_evaluation_id   TEXT REFERENCES remote_ci_evaluation(id),
    recorded_at_ms     INTEGER NOT NULL,
    CHECK ((snapshot_id IS NOT NULL) =
        (raw_outcome = 'SUCCEEDED')),
    CHECK (ci_evaluation_id IS NULL OR snapshot_id IS NOT NULL)
);
CREATE TABLE remote_code_subject (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    stage_turn_id               TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    source_code_fingerprint     TEXT    NOT NULL,
    source_head_sha             TEXT    NOT NULL,
    source_base_sha             TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    created_at_ms               INTEGER NOT NULL
);
CREATE TABLE ci_repair_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    ci_repair_episode_id        TEXT    NOT NULL
        REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'RERUN', 'FIX_STAGE_TURN', 'VALIDATE', 'BRAIN_REVIEW', 'PUSH_HEAD')),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    stage_turn_id               TEXT UNIQUE REFERENCES stage_turn(id),
    task_turn_id                TEXT UNIQUE REFERENCES task_turn(id),
    expected_code_fingerprint   TEXT,
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'SUCCEEDED', 'FAILED',
        'CANCELED', 'SUPERSEDED')),
    result_code_fingerprint     TEXT,
    result_head_sha             TEXT,
    result_evidence             TEXT,
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    error_message               TEXT, base_repair_authorization_id TEXT
    REFERENCES ci_base_repair_authorization_v303(id), lease_expected_sha TEXT,
    UNIQUE (ci_repair_episode_id, kind, semantic_attempt),
    CHECK ((kind = 'FIX_STAGE_TURN') = (stage_turn_id IS NOT NULL)),
    CHECK ((kind = 'BRAIN_REVIEW') = (task_turn_id IS NOT NULL)),
    CHECK (stage_turn_id IS NULL OR task_turn_id IS NULL),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (kind <> 'PUSH_HEAD' OR status <> 'SUCCEEDED'
        OR result_head_sha IS NOT NULL)
);
CREATE UNIQUE INDEX idx_ci_repair_one_live_operation
    ON ci_repair_operation(ci_repair_episode_id)
    WHERE status IN ('REQUESTED', 'DISPATCHED');
CREATE TABLE ci_repair_delivery_receipt (
    ci_repair_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES ci_repair_operation(id) ON DELETE CASCADE,
    operation_id       TEXT    NOT NULL UNIQUE,
    raw_outcome        TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest  TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance         TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    recorded_at_ms     INTEGER NOT NULL
);
CREATE TABLE ci_repair_budget_extension (
    id                   TEXT    NOT NULL PRIMARY KEY,
    ci_repair_episode_id TEXT    NOT NULL REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    command_id           TEXT    NOT NULL UNIQUE,
    kind                 TEXT    NOT NULL CHECK (kind IN (
        'EXTEND', 'PER_PUSH_APPROVAL')),
    rerun_delta          INTEGER NOT NULL DEFAULT 0 CHECK (rerun_delta >= 0),
    fix_delta            INTEGER NOT NULL DEFAULT 0 CHECK (fix_delta >= 0),
    push_delta           INTEGER NOT NULL DEFAULT 0 CHECK (push_delta >= 0),
    approved_by          TEXT    NOT NULL,
    reason               TEXT    NOT NULL,
    created_at_ms        INTEGER NOT NULL,
    consumed_at_ms       INTEGER,
    CHECK (rerun_delta + fix_delta + push_delta > 0),
    CHECK (kind <> 'PER_PUSH_APPROVAL'
        OR (rerun_delta = 0 AND fix_delta = 1 AND push_delta = 1))
);
CREATE TABLE ci_repair_control_command (
    id                   TEXT    NOT NULL PRIMARY KEY,
    ci_repair_episode_id TEXT    NOT NULL REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    command_id           TEXT    NOT NULL UNIQUE,
    kind                 TEXT    NOT NULL CHECK (kind IN (
        'MANUAL_TAKEOVER', 'STOP_AUTOMATION')),
    actor                TEXT    NOT NULL,
    reason               TEXT    NOT NULL,
    created_at_ms        INTEGER NOT NULL,
    consumed_at_ms       INTEGER
);
CREATE TABLE remote_head_evidence_invalidation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    accepted_snapshot_id        TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    old_head_sha                TEXT    NOT NULL,
    new_head_sha                TEXT    NOT NULL,
    old_base_sha                TEXT    NOT NULL,
    new_base_sha                TEXT    NOT NULL,
    evidence_kind               TEXT    NOT NULL CHECK (evidence_kind IN (
        'CI', 'BRAIN', 'REMOTE_REVIEW', 'READINESS', 'MERGE')),
    invalidated_at_ms           INTEGER NOT NULL,
    UNIQUE (accepted_snapshot_id, evidence_kind),
    CHECK (old_head_sha <> new_head_sha OR old_base_sha <> new_base_sha)
);
CREATE TABLE branch_sync_dispatch_operation (
    id                          TEXT    NOT NULL PRIMARY KEY,
    branch_sync_episode_id      TEXT    NOT NULL REFERENCES branch_sync_episode(id) ON DELETE CASCADE,
    branch_sync_effect_step_id  TEXT    NOT NULL UNIQUE
        REFERENCES branch_sync_effect_step(id) ON DELETE CASCADE,
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'FETCH_COMPARE', 'MECHANICAL_REBASE', 'CONFLICT_REPAIR',
        'VALIDATE', 'BRAIN_REVIEW', 'FORCE_WITH_LEASE_PUSH')),
    operation_id                TEXT    NOT NULL UNIQUE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    stage_turn_id               TEXT UNIQUE REFERENCES stage_turn(id),
    task_turn_id                TEXT UNIQUE REFERENCES task_turn(id),
    expected_code_fingerprint   TEXT,
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    target_base_sha             TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'DISPATCHED', 'SUCCEEDED', 'FAILED',
        'INDETERMINATE', 'CANCELED', 'SUPERSEDED')),
    result_code_fingerprint     TEXT,
    result_head_sha             TEXT,
    result_evidence             TEXT,
    requested_at_ms             INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    error_message               TEXT,
    CHECK ((kind = 'CONFLICT_REPAIR') = (stage_turn_id IS NOT NULL)),
    CHECK ((kind = 'BRAIN_REVIEW') = (task_turn_id IS NOT NULL)),
    CHECK (stage_turn_id IS NULL OR task_turn_id IS NULL),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE',
            'CANCELED', 'SUPERSEDED')) = (completed_at_ms IS NOT NULL))
);
CREATE UNIQUE INDEX idx_branch_sync_one_live_dispatch
    ON branch_sync_dispatch_operation(branch_sync_episode_id)
    WHERE status IN ('REQUESTED', 'DISPATCHED');
CREATE TABLE branch_sync_delivery_receipt (
    branch_sync_dispatch_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES branch_sync_dispatch_operation(id) ON DELETE CASCADE,
    operation_id       TEXT    NOT NULL UNIQUE,
    raw_outcome        TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest  TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance         TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    recorded_at_ms     INTEGER NOT NULL
);
CREATE VIEW development_flow_task_route AS
SELECT
    task.id AS task_id,
    task.thread_id AS trunk_id,
    trunk.workspace_id,
    task.workflow_version,
    task.lifecycle_state,
    task.epoch,
    task.aggregate_version,
    current.stage_id,
    current.stage_generation
FROM tasks task
JOIN threads trunk ON trunk.id = task.thread_id
LEFT JOIN task_current_stage current ON current.task_id = task.id;
CREATE TABLE trunk_thread_turn_request_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    actor                    TEXT    NOT NULL,
    expected_trunk_version   INTEGER NOT NULL CHECK (expected_trunk_version >= 0),
    returned_trunk_version   INTEGER NOT NULL CHECK (
        returned_trunk_version = expected_trunk_version + 1),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'ACTIVE', 'IDLE', 'ARCHIVED')),
    turn_id                  TEXT    NOT NULL UNIQUE
        REFERENCES thread_turn(id) ON DELETE CASCADE,
    operation_id             TEXT    NOT NULL UNIQUE,
    dispatch_ticket_id       TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    purpose                  TEXT    NOT NULL,
    delivery_lane            TEXT    NOT NULL CHECK (delivery_lane IN ('CLI', 'API')),
    launch_input_digest      TEXT    NOT NULL CHECK (length(launch_input_digest) = 64),
    user_message_digest      TEXT    NOT NULL CHECK (length(user_message_digest) = 64),
    recorded_at_ms           INTEGER NOT NULL,
    UNIQUE (trunk_id, command_id)
);
CREATE TABLE trunk_thread_turn_result_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    actor                    TEXT    NOT NULL,
    turn_id                  TEXT    NOT NULL UNIQUE
        REFERENCES thread_turn(id) ON DELETE CASCADE,
    operation_id             TEXT    NOT NULL UNIQUE,
    attempt                  INTEGER NOT NULL CHECK (attempt > 0),
    raw_result_digest        TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    raw_outcome              TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    acceptance               TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    terminal_status          TEXT    NOT NULL CHECK (terminal_status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    assistant_message_id     TEXT REFERENCES thread_message(id) ON DELETE RESTRICT,
    returned_trunk_version   INTEGER NOT NULL CHECK (returned_trunk_version > 0),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'ACTIVE', 'IDLE', 'ARCHIVED')),
    recorded_at_ms           INTEGER NOT NULL,
    CHECK (assistant_message_id IS NULL
        OR (acceptance = 'ACCEPTED' AND terminal_status = 'SUCCEEDED')),
    UNIQUE (trunk_id, command_id)
);
CREATE TABLE ci_repair_brain_verdict (
    ci_repair_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES ci_repair_operation(id) ON DELETE CASCADE,
    task_turn_id           TEXT NOT NULL UNIQUE REFERENCES task_turn(id),
    verdict                TEXT NOT NULL CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    finding_count          INTEGER NOT NULL CHECK (finding_count >= 0),
    summary                TEXT NOT NULL CHECK (length(trim(summary)) > 0),
    recorded_at_ms         INTEGER NOT NULL,
    CHECK ((verdict = 'APPROVED') = (finding_count = 0))
);
CREATE TABLE branch_sync_brain_verdict (
    branch_sync_dispatch_operation_id TEXT NOT NULL PRIMARY KEY
        REFERENCES branch_sync_dispatch_operation(id) ON DELETE CASCADE,
    task_turn_id           TEXT NOT NULL UNIQUE REFERENCES task_turn(id),
    verdict                TEXT NOT NULL CHECK (verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    finding_count          INTEGER NOT NULL CHECK (finding_count >= 0),
    summary                TEXT NOT NULL CHECK (length(trim(summary)) > 0),
    recorded_at_ms         INTEGER NOT NULL,
    CHECK ((verdict = 'APPROVED') = (finding_count = 0))
);
CREATE VIEW remote_brain_operation_v248 AS
SELECT episode.id AS proof_id, episode.task_turn_id,
       episode.task_id, episode.task_epoch,
       episode.remote_development_stage_id AS stage_id,
       episode.stage_generation, turn.operation_id, turn.attempt,
       turn.expected_code_fingerprint, turn.expected_head_sha,
       turn.expected_base_sha, episode.status, episode.verdict
FROM remote_feedback_brain_episode episode
JOIN task_turn turn ON turn.id = episode.task_turn_id
UNION ALL
SELECT operation.id, operation.task_turn_id, operation.task_id,
       operation.task_epoch, operation.remote_development_stage_id,
       operation.stage_generation, operation.operation_id,
       operation.semantic_attempt, operation.expected_code_fingerprint,
       operation.expected_head_sha, operation.expected_base_sha,
       operation.status, verdict.verdict
FROM ci_repair_operation operation
LEFT JOIN ci_repair_brain_verdict verdict
  ON verdict.ci_repair_operation_id = operation.id
WHERE operation.kind = 'BRAIN_REVIEW'
UNION ALL
SELECT operation.id, operation.task_turn_id, operation.task_id,
       operation.task_epoch, operation.remote_development_stage_id,
       operation.stage_generation, operation.operation_id,
       operation.semantic_attempt, operation.expected_code_fingerprint,
       operation.expected_head_sha, operation.expected_base_sha,
       operation.status, verdict.verdict
FROM branch_sync_dispatch_operation operation
LEFT JOIN branch_sync_brain_verdict verdict
  ON verdict.branch_sync_dispatch_operation_id = operation.id
WHERE operation.kind = 'BRAIN_REVIEW';
CREATE TABLE task_policy_command_intent (
    id                           TEXT    NOT NULL PRIMARY KEY,
    task_id                      TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                   TEXT    NOT NULL,
    actor                        TEXT    NOT NULL,
    expected_task_epoch          INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_task_version        INTEGER NOT NULL CHECK (expected_task_version >= 0),
    previous_policy_revision_id  TEXT    NOT NULL REFERENCES task_policy_revision(id),
    selected_policy_revision_id  TEXT    NOT NULL UNIQUE REFERENCES task_policy_revision(id),
    recorded_at_ms               INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    CHECK (previous_policy_revision_id <> selected_policy_revision_id)
);
CREATE TABLE task_policy_command_receipt (
    id                           TEXT    NOT NULL PRIMARY KEY,
    intent_id                    TEXT    NOT NULL UNIQUE
        REFERENCES task_policy_command_intent(id),
    task_id                      TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                   TEXT    NOT NULL,
    actor                        TEXT    NOT NULL,
    expected_task_epoch          INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_task_version        INTEGER NOT NULL CHECK (expected_task_version >= 0),
    previous_policy_revision_id  TEXT    NOT NULL REFERENCES task_policy_revision(id),
    selected_policy_revision_id  TEXT    NOT NULL UNIQUE REFERENCES task_policy_revision(id),
    returned_task_version        INTEGER NOT NULL CHECK (returned_task_version > 0),
    recorded_at_ms               INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    CHECK (previous_policy_revision_id <> selected_policy_revision_id),
    CHECK (returned_task_version = expected_task_version + 1)
);
CREATE TABLE remote_observation_stage_receipt (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause IN (
        'ACCEPT_REMOTE_CI',
        'ACCEPT_OBSERVED_READY',
        'ACCEPT_REMOTE_HEAD_CHANGE')),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN (
        'APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER NOT NULL CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT    NOT NULL CHECK (source_checkpoint IN (
        'WAITING_CI', 'AWAITING_READY', 'WAITING_REMOTE_REVIEW',
        'ADDRESSING_REMOTE_FEEDBACK', 'READY_TO_MERGE', 'MERGING')),
    subject_task_epoch                INTEGER,
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT    NOT NULL CHECK (length(proof_id) > 0),
    returned_kind                     TEXT    NOT NULL CHECK (
        returned_kind = 'REMOTE_DEVELOPMENT'),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_checkpoint               TEXT    NOT NULL CHECK (returned_checkpoint IN (
        'WAITING_CI', 'AWAITING_READY', 'WAITING_REMOTE_REVIEW')),
    returned_end_reason               TEXT,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    recorded_at_ms                    INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (returned_version = expected_stage_version + 1),
    CHECK (subject_operation_id IS NULL
        AND subject_task_epoch IS NULL AND subject_stage_id IS NULL
        AND subject_stage_generation IS NULL AND subject_attempt IS NULL
        AND subject_expected_code_fingerprint IS NULL
        AND subject_expected_head_sha IS NULL
        AND subject_expected_base_sha IS NULL),
    CHECK (returned_pending_operation_id IS NULL
        AND returned_pending_task_epoch IS NULL
        AND returned_pending_stage_id IS NULL
        AND returned_pending_stage_generation IS NULL
        AND returned_pending_attempt IS NULL
        AND returned_pending_code_fingerprint IS NULL
        AND returned_pending_head_sha IS NULL
        AND returned_pending_base_sha IS NULL),
    CHECK (returned_end_reason IS NULL),
    CHECK ((cause = 'ACCEPT_REMOTE_CI'
            AND source_checkpoint = 'WAITING_CI'
            AND returned_checkpoint = 'AWAITING_READY')
        OR (cause = 'ACCEPT_OBSERVED_READY'
            AND source_checkpoint = 'AWAITING_READY'
            AND returned_checkpoint = 'WAITING_REMOTE_REVIEW')
        OR (cause = 'ACCEPT_REMOTE_HEAD_CHANGE'
            AND source_checkpoint IN (
                'AWAITING_READY', 'WAITING_REMOTE_REVIEW',
                'ADDRESSING_REMOTE_FEEDBACK', 'READY_TO_MERGE', 'MERGING')
            AND returned_checkpoint = 'WAITING_CI'))
);
CREATE TABLE review_assignment_turn_request_receipt (
    id                  TEXT    NOT NULL PRIMARY KEY,
    turn_id             TEXT    NOT NULL UNIQUE
        REFERENCES review_assignment_turn(id) ON DELETE CASCADE,
    assignment_id       TEXT    NOT NULL REFERENCES review_assignment(id) ON DELETE CASCADE,
    round_id            TEXT    NOT NULL REFERENCES review_round(id) ON DELETE CASCADE,
    operation_id        TEXT    NOT NULL UNIQUE,
    dispatch_ticket_id  TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    attempt             INTEGER NOT NULL CHECK (attempt > 0),
    start_commit        TEXT    NOT NULL,
    recorded_at_ms      INTEGER NOT NULL
);
CREATE TABLE review_assignment_turn_result_receipt (
    id                   TEXT    NOT NULL PRIMARY KEY,
    turn_id              TEXT    NOT NULL UNIQUE
        REFERENCES review_assignment_turn(id) ON DELETE CASCADE,
    assignment_id        TEXT    NOT NULL REFERENCES review_assignment(id) ON DELETE CASCADE,
    round_id             TEXT    NOT NULL REFERENCES review_round(id) ON DELETE CASCADE,
    review_id            TEXT    NOT NULL REFERENCES review_session(id) ON DELETE CASCADE,
    operation_id         TEXT    NOT NULL UNIQUE,
    attempt              INTEGER NOT NULL CHECK (attempt > 0),
    start_commit         TEXT    NOT NULL,
    raw_result_digest    TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    raw_outcome          TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    disposition          TEXT,
    acceptance           TEXT    NOT NULL CHECK (acceptance IN ('ACCEPTED', 'SUPERSEDED')),
    terminal_status      TEXT    NOT NULL CHECK (terminal_status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    final_text           TEXT    NOT NULL,
    input_tokens         INTEGER NOT NULL CHECK (input_tokens >= 0),
    output_tokens        INTEGER NOT NULL CHECK (output_tokens >= 0),
    cost_usd_milli       INTEGER NOT NULL CHECK (cost_usd_milli >= 0),
    provider_session_id  TEXT,
    payload_json         TEXT,
    evidence_json        TEXT,
    error_message        TEXT,
    recorded_at_ms       INTEGER NOT NULL
);
CREATE TABLE cleanup_stage (
    stage_id                     TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage(id) ON DELETE CASCADE,
    task_id                      TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                   INTEGER NOT NULL CHECK (task_epoch > 0),
    generation                   INTEGER NOT NULL CHECK (generation > 0),
    terminal_acceptance_id       TEXT    NOT NULL UNIQUE
        REFERENCES task_terminal_acceptance(id),
    task_terminal_intent_id      TEXT    NOT NULL UNIQUE
        REFERENCES task_terminal_intent(id),
    terminal_reason              TEXT    NOT NULL CHECK (terminal_reason IN (
        'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    task_policy_revision_id      TEXT    NOT NULL REFERENCES task_policy_revision(id),
    remote_pr_binding_id         TEXT REFERENCES remote_pr_binding(id),
    remote_pr_disposition        TEXT    NOT NULL CHECK (remote_pr_disposition IN (
        'PRESERVE_OPEN', 'REMOTE_ALREADY_TERMINAL', 'NO_REMOTE_PR')),
    local_branch_requirement     TEXT    NOT NULL CHECK (local_branch_requirement IN (
        'REQUIRED', 'NOT_APPLICABLE')),
    remote_branch_requirement    TEXT    NOT NULL CHECK (remote_branch_requirement IN (
        'REQUIRED', 'OPTIONAL', 'NOT_APPLICABLE')),
    opened_at_ms                 INTEGER NOT NULL,
    UNIQUE (stage_id, task_id, task_epoch, generation),
    CHECK (terminal_reason <> 'CANCELED'
        OR remote_branch_requirement = 'NOT_APPLICABLE'),
    CHECK ((remote_pr_binding_id IS NULL)
        = (remote_pr_disposition = 'NO_REMOTE_PR'))
);
CREATE VIEW task_control_live_work_v256 AS
SELECT task.id AS task_id,
       (SELECT COUNT(*) FROM task_turn turn
        WHERE turn.task_id = task.id
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_task_turn_count,
       (SELECT COUNT(*) FROM stage_turn turn
        JOIN stage owner ON owner.id = turn.stage_id
        WHERE owner.task_id = task.id
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_stage_turn_count,
       (SELECT COUNT(*)
        FROM review_assignment_turn turn
        JOIN review_assignment assignment ON assignment.id = turn.assignment_id
        JOIN review_round round ON round.id = assignment.round_id
        JOIN review_session session ON session.id = round.session_id
        JOIN pr pull_request ON pull_request.id = session.pr_id
        WHERE pull_request.origin = 'task' AND pull_request.task_id = task.id
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_review_turn_count,
       (SELECT COUNT(*) FROM dispatch_ticket ticket
        WHERE ticket.task_id = task.id
          AND ticket.status IN (
              'REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT', 'RESULT_PENDING',
              'CLAIMED', 'RUNNING', 'DELIVERING'))
           AS active_dispatch_count,
       (SELECT COUNT(*) FROM agent_execution execution
        JOIN dispatch_ticket ticket ON ticket.id = execution.ticket_id
        WHERE ticket.task_id = task.id
          AND execution.status IN ('STARTING', 'RUNNING', 'UNKNOWN'))
           AS active_agent_execution_count
FROM tasks task
WHERE task.workflow_version = 'V2';
CREATE TABLE task_resume_reconciliation_v256 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    source_kind                 TEXT    NOT NULL CHECK (source_kind IN ('PAUSE', 'ARCHIVE')),
    source_id                   TEXT    NOT NULL,
    stage_id                    TEXT    NOT NULL REFERENCES stage(id),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    restore_checkpoint          TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    reconciliation_digest       TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status = 'SATISFIED'),
    recorded_at_ms              INTEGER NOT NULL CHECK (recorded_at_ms > 0),
    UNIQUE (source_kind, source_id),
    CHECK (length(trim(reconciliation_digest)) > 0)
);
CREATE VIEW task_resume_evidence_digest_v256 AS
SELECT evidence.id,
       'resume:v2:' || lower(hex(evidence.task_id)) || ':' || evidence.task_epoch || ':'
           || lower(hex(evidence.id)) || ':' || lower(hex(evidence.source_kind)) || ':'
           || lower(hex(evidence.source_id)) || ':' || lower(hex(evidence.stage_id)) || ':'
           || evidence.stage_generation || ':' || lower(hex(evidence.restore_checkpoint)) || ':'
           || lower(hex(evidence.code_fingerprint)) || ':' || lower(hex(evidence.head_sha)) || ':'
           || lower(hex(evidence.base_sha)) || ':' || evidence.recorded_at_ms
           AS content_digest
FROM task_resume_reconciliation_v256 evidence;
CREATE TABLE task_resume_handoff_v256 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    task_version                INTEGER NOT NULL CHECK (task_version >= 0),
    reconciliation_id           TEXT    NOT NULL UNIQUE,
    stage_id                    TEXT    NOT NULL REFERENCES stage(id),
    stage_kind                  TEXT    NOT NULL CHECK (stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT')),
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    stage_version               INTEGER NOT NULL CHECK (stage_version >= 0),
    restore_checkpoint          TEXT    NOT NULL,
    code_fingerprint            TEXT    NOT NULL,
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    request_digest              TEXT    NOT NULL,
    status                      TEXT    NOT NULL CHECK (status IN ('PENDING', 'ACCEPTED')),
    owner_proof_id              TEXT,
    accepted_by                 TEXT,
    accepted_at_ms              INTEGER,
    created_at_ms               INTEGER NOT NULL CHECK (created_at_ms > 0),
    UNIQUE (task_id, task_version),
    CHECK (length(trim(reconciliation_id)) > 0
        AND length(trim(restore_checkpoint)) > 0
        AND length(trim(code_fingerprint)) > 0
        AND length(trim(head_sha)) > 0
        AND length(trim(base_sha)) > 0
        AND length(trim(request_digest)) > 0),
    CHECK ((status = 'PENDING'
            AND owner_proof_id IS NULL AND accepted_by IS NULL
            AND accepted_at_ms IS NULL)
        OR (status = 'ACCEPTED'
            AND owner_proof_id IS NOT NULL AND length(trim(owner_proof_id)) > 0
            AND accepted_by IS NOT NULL AND length(trim(accepted_by)) > 0
            AND accepted_at_ms IS NOT NULL
            AND accepted_at_ms >= created_at_ms))
);
CREATE VIEW task_resume_handoff_digest_v256 AS
SELECT handoff.id,
       'resume-handoff:v1:' || lower(hex(handoff.id)) || ':'
           || lower(hex(handoff.task_id)) || ':' || handoff.task_epoch || ':'
           || handoff.task_version || ':' || lower(hex(handoff.reconciliation_id)) || ':'
           || lower(hex(handoff.stage_id)) || ':' || lower(hex(handoff.stage_kind)) || ':'
           || handoff.stage_generation || ':' || handoff.stage_version || ':'
           || lower(hex(handoff.restore_checkpoint)) || ':'
           || lower(hex(handoff.code_fingerprint)) || ':'
           || lower(hex(handoff.head_sha)) || ':' || lower(hex(handoff.base_sha)) || ':'
           || handoff.created_at_ms AS content_digest
FROM task_resume_handoff_v256 handoff;
CREATE TABLE stage_steering_request_v257 (
    id                         TEXT    NOT NULL PRIMARY KEY,
    command_id                 TEXT    NOT NULL UNIQUE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_kind                 TEXT    NOT NULL CHECK (stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT')),
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    accepted_stage_version     INTEGER NOT NULL CHECK (accepted_stage_version >= 0),
    accepted_checkpoint        TEXT    NOT NULL,
    mode                       TEXT    NOT NULL CHECK (mode IN (
        'APPEND', 'CANCEL_AND_REPLACE')),
    body                       TEXT    NOT NULL,
    content_digest             TEXT    NOT NULL CHECK (length(content_digest) = 64),
    predecessor_owner_kind     TEXT,
    predecessor_owner_id       TEXT,
    predecessor_purpose        TEXT,
    predecessor_operation_id   TEXT,
    predecessor_ticket_id      TEXT REFERENCES dispatch_ticket(id),
    predecessor_attempt        INTEGER CHECK (predecessor_attempt > 0),
    predecessor_code_fingerprint TEXT,
    predecessor_head_sha       TEXT,
    predecessor_base_sha       TEXT,
    cancel_intent_at_ms        INTEGER,
    status                     TEXT    NOT NULL CHECK (status IN (
        'PENDING', 'ADMITTED', 'SUPERSEDED')),
    successor_owner_kind       TEXT,
    successor_owner_id         TEXT,
    successor_operation_id     TEXT,
    terminal_reason            TEXT,
    requested_by               TEXT    NOT NULL CHECK (length(requested_by) > 0),
    requested_at_ms            INTEGER NOT NULL CHECK (requested_at_ms >= 0),
    admitted_at_ms             INTEGER,
    CHECK ((predecessor_operation_id IS NULL
            AND predecessor_owner_kind IS NULL
            AND predecessor_owner_id IS NULL
            AND predecessor_purpose IS NULL
            AND predecessor_ticket_id IS NULL
            AND predecessor_attempt IS NULL
            AND predecessor_code_fingerprint IS NULL
            AND predecessor_head_sha IS NULL
            AND predecessor_base_sha IS NULL)
        OR (predecessor_operation_id IS NOT NULL
            AND predecessor_owner_kind IS NOT NULL
            AND predecessor_owner_id IS NOT NULL
            AND predecessor_purpose IS NOT NULL
            AND predecessor_ticket_id IS NOT NULL
            AND predecessor_attempt IS NOT NULL)),
    CHECK ((mode = 'CANCEL_AND_REPLACE') = (cancel_intent_at_ms IS NOT NULL)),
    CHECK (mode <> 'CANCEL_AND_REPLACE' OR predecessor_operation_id IS NOT NULL),
    CHECK ((status = 'PENDING'
            AND successor_owner_kind IS NULL
            AND successor_owner_id IS NULL
            AND successor_operation_id IS NULL
            AND admitted_at_ms IS NULL
            AND terminal_reason IS NULL)
        OR (status = 'ADMITTED'
            AND successor_owner_kind IS NOT NULL
            AND successor_owner_id IS NOT NULL
            AND successor_operation_id IS NOT NULL
            AND admitted_at_ms IS NOT NULL
            AND terminal_reason IS NULL)
        OR (status = 'SUPERSEDED'
            AND successor_owner_kind IS NULL
            AND successor_owner_id IS NULL
            AND successor_operation_id IS NULL
            AND admitted_at_ms IS NULL
            AND terminal_reason IS NOT NULL)),
    FOREIGN KEY (stage_id, task_id, stage_kind, stage_generation)
        REFERENCES stage(id, task_id, kind, generation) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX idx_stage_steering_pending_v257
    ON stage_steering_request_v257(status, requested_at_ms, id);
CREATE UNIQUE INDEX idx_stage_steering_cancel_predecessor_v257
    ON stage_steering_request_v257(predecessor_operation_id)
    WHERE status = 'PENDING' AND mode = 'CANCEL_AND_REPLACE';
CREATE TABLE stage_steering_attachment_v257 (
    request_id     TEXT    NOT NULL REFERENCES stage_steering_request_v257(id)
        ON DELETE CASCADE,
    position       INTEGER NOT NULL CHECK (position > 0),
    media_type     TEXT    NOT NULL CHECK (length(media_type) > 0),
    content_ref    TEXT    NOT NULL CHECK (length(content_ref) > 0),
    content_digest TEXT    NOT NULL CHECK (length(content_digest) = 64),
    PRIMARY KEY (request_id, position),
    UNIQUE (request_id, content_ref)
);
CREATE TABLE remote_stage_steering_handoff_v257 (
    request_id              TEXT NOT NULL PRIMARY KEY
        REFERENCES stage_steering_request_v257(id) ON DELETE CASCADE,
    owner_family            TEXT NOT NULL CHECK (owner_family IN (
        'CI_REPAIR', 'BRANCH_REPAIR', 'REMOTE_FEEDBACK')),
    owner_purpose           TEXT NOT NULL,
    predecessor_turn_id     TEXT NOT NULL REFERENCES stage_turn(id),
    predecessor_operation_id TEXT NOT NULL UNIQUE,
    status                  TEXT NOT NULL CHECK (status IN ('PARKED', 'CONSUMED')),
    successor_turn_id       TEXT REFERENCES stage_turn(id),
    consumed_at_ms          INTEGER,
    CHECK ((status = 'PARKED' AND successor_turn_id IS NULL
            AND consumed_at_ms IS NULL)
        OR (status = 'CONSUMED' AND successor_turn_id IS NOT NULL
            AND consumed_at_ms IS NOT NULL))
);
CREATE TABLE remote_repair_steering_turn_v257 (
    request_id              TEXT NOT NULL PRIMARY KEY
        REFERENCES stage_steering_request_v257(id) ON DELETE CASCADE,
    owner_family            TEXT NOT NULL CHECK (owner_family IN (
        'CI_REPAIR', 'BRANCH_REPAIR')),
    ci_repair_episode_id    TEXT REFERENCES ci_repair_episode(id),
    branch_sync_episode_id  TEXT REFERENCES branch_sync_episode(id),
    branch_sync_step_id     TEXT REFERENCES branch_sync_effect_step(id),
    stage_turn_id           TEXT NOT NULL UNIQUE REFERENCES stage_turn(id),
    operation_id            TEXT NOT NULL UNIQUE,
    dispatch_ticket_id      TEXT NOT NULL UNIQUE REFERENCES dispatch_ticket(id)
        DEFERRABLE INITIALLY DEFERRED,
    semantic_attempt        INTEGER NOT NULL CHECK (semantic_attempt > 0),
    status                  TEXT NOT NULL CHECK (status IN (
        'REQUESTED', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    result_code_fingerprint TEXT,
    result_head_sha         TEXT,
    result_summary          TEXT,
    requested_at_ms         INTEGER NOT NULL,
    completed_at_ms         INTEGER,
    error_message           TEXT,
    CHECK ((owner_family = 'CI_REPAIR'
            AND ci_repair_episode_id IS NOT NULL
            AND branch_sync_episode_id IS NULL
            AND branch_sync_step_id IS NULL)
        OR (owner_family = 'BRANCH_REPAIR'
            AND ci_repair_episode_id IS NULL
            AND branch_sync_episode_id IS NOT NULL
            AND branch_sync_step_id IS NOT NULL)),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK (status <> 'SUCCEEDED' OR (
        result_code_fingerprint IS NOT NULL AND result_head_sha IS NOT NULL
        AND result_summary IS NOT NULL))
);
CREATE TABLE remote_repair_steering_delivery_v257 (
    request_id       TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_repair_steering_turn_v257(request_id) ON DELETE CASCADE,
    operation_id     TEXT NOT NULL UNIQUE,
    raw_outcome      TEXT NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest TEXT NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance       TEXT NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    recorded_at_ms   INTEGER NOT NULL
);
CREATE TABLE remote_steering_code_subject_v257 (
    request_id              TEXT NOT NULL PRIMARY KEY
        REFERENCES remote_repair_steering_turn_v257(request_id) ON DELETE CASCADE,
    task_id                 TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch              INTEGER NOT NULL,
    remote_stage_id         TEXT NOT NULL REFERENCES remote_development_stage(stage_id),
    stage_generation        INTEGER NOT NULL,
    stage_turn_id           TEXT NOT NULL UNIQUE REFERENCES stage_turn(id),
    source_code_fingerprint TEXT NOT NULL,
    source_head_sha         TEXT NOT NULL,
    source_base_sha         TEXT NOT NULL,
    code_fingerprint        TEXT NOT NULL,
    head_sha                TEXT NOT NULL,
    base_sha                TEXT NOT NULL,
    recorded_at_ms          INTEGER NOT NULL
);
CREATE TABLE stage_steering_transition_receipt_v257 (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause = 'ADMIT_LOCAL_STEERING'),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition IN ('APPLIED', 'SUPERSEDED')),
    expected_task_epoch               INTEGER CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT,
    subject_task_epoch                INTEGER CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT    NOT NULL CHECK (length(proof_id) > 0),
    returned_kind                     TEXT    NOT NULL CHECK (returned_kind = 'LOCAL_DEVELOPMENT'),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version >= 0),
    returned_checkpoint               TEXT    NOT NULL CHECK (returned_checkpoint = 'ADDRESSING_LOCAL_FEEDBACK'),
    returned_end_reason               TEXT,
    returned_pending_task_epoch       INTEGER CHECK (returned_pending_task_epoch > 0),
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (stage_id, command_id),
    CHECK (expected_task_epoch IS NOT NULL
        AND expected_stage_generation IS NOT NULL
        AND expected_stage_version IS NOT NULL
        AND source_checkpoint = 'LOCAL_REVIEW'),
    CHECK (subject_operation_id IS NOT NULL
        AND subject_task_epoch = expected_task_epoch
        AND subject_stage_id = stage_id
        AND subject_stage_generation = returned_generation
        AND subject_attempt > 0),
    CHECK (returned_pending_operation_id = subject_operation_id
        AND returned_pending_task_epoch = subject_task_epoch
        AND returned_pending_stage_id = subject_stage_id
        AND returned_pending_stage_generation = subject_stage_generation
        AND returned_pending_attempt = subject_attempt),
    CHECK (returned_end_reason IS NULL),
    FOREIGN KEY (stage_id, task_id, returned_kind, returned_generation)
        REFERENCES stage(id, task_id, kind, generation) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE stage_resume_rearm_intent_v257 (
    handoff_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES task_resume_handoff_v256(id) ON DELETE CASCADE,
    owner_proof_id      TEXT    NOT NULL UNIQUE,
    accepted_by         TEXT    NOT NULL CHECK (length(accepted_by) > 0),
    task_id             TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch          INTEGER NOT NULL CHECK (task_epoch > 0),
    task_version        INTEGER NOT NULL CHECK (task_version > 0),
    stage_id            TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_kind          TEXT    NOT NULL CHECK (stage_kind IN (
        'PLAN', 'LOCAL_DEVELOPMENT', 'REMOTE_DEVELOPMENT')),
    stage_generation    INTEGER NOT NULL CHECK (stage_generation > 0),
    stage_version       INTEGER NOT NULL CHECK (stage_version >= 0),
    restore_checkpoint  TEXT    NOT NULL,
    reconciliation_id   TEXT    NOT NULL,
    code_fingerprint    TEXT    NOT NULL CHECK (length(code_fingerprint) > 0),
    head_sha            TEXT    NOT NULL CHECK (length(head_sha) > 0),
    base_sha            TEXT    NOT NULL CHECK (length(base_sha) > 0),
    status              TEXT    NOT NULL CHECK (status IN ('PENDING', 'MATERIALIZED')),
    accepted_at_ms      INTEGER NOT NULL CHECK (accepted_at_ms >= 0),
    materialized_at_ms  INTEGER,
    diagnostic_code     TEXT,
    diagnostic_detail   TEXT,
    diagnosed_at_ms     INTEGER,
    CHECK ((status = 'PENDING') = (materialized_at_ms IS NULL)),
    CHECK ((diagnostic_code IS NULL AND diagnostic_detail IS NULL
            AND diagnosed_at_ms IS NULL)
        OR (status = 'PENDING' AND diagnostic_code IS NOT NULL
            AND diagnostic_detail IS NOT NULL AND diagnosed_at_ms IS NOT NULL)),
    FOREIGN KEY (stage_id, task_id, stage_kind, stage_generation)
        REFERENCES stage(id, task_id, kind, generation) ON DELETE CASCADE
        DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE stage_resume_rearm_successor_v257 (
    handoff_id             TEXT NOT NULL PRIMARY KEY
        REFERENCES stage_resume_rearm_intent_v257(handoff_id) ON DELETE CASCADE,
    command_id             TEXT NOT NULL UNIQUE,
    owner_kind             TEXT NOT NULL CHECK (owner_kind IN (
        'TASK_TURN', 'STAGE_TURN', 'REMOTE_OBSERVATION')),
    owner_id               TEXT NOT NULL UNIQUE,
    operation_id           TEXT UNIQUE,
    dispatch_ticket_id     TEXT UNIQUE,
    purpose                TEXT NOT NULL,
    semantic_attempt       INTEGER CHECK (semantic_attempt > 0),
    status                 TEXT NOT NULL CHECK (status IN ('PREPARED', 'ARMED')),
    returned_stage_version INTEGER CHECK (returned_stage_version >= 0),
    created_at_ms          INTEGER NOT NULL CHECK (created_at_ms >= 0),
    armed_at_ms            INTEGER,
    CHECK (operation_id IS NOT NULL AND dispatch_ticket_id IS NOT NULL
        AND semantic_attempt IS NOT NULL),
    CHECK ((status = 'PREPARED' AND armed_at_ms IS NULL
            AND returned_stage_version IS NULL)
        OR (status = 'ARMED' AND armed_at_ms IS NOT NULL)),
    CHECK (returned_stage_version IS NULL
        OR owner_kind IN ('TASK_TURN', 'STAGE_TURN'))
);
CREATE TABLE review_build_selection (
    thread_id          TEXT    PRIMARY KEY
        REFERENCES threads(id) ON DELETE RESTRICT,
    review_pass_id     TEXT    NOT NULL UNIQUE
        REFERENCES review_passes(id) ON DELETE RESTRICT,
    repo_full_name     TEXT    NOT NULL,
    pr_number          INTEGER NOT NULL CHECK (pr_number > 0),
    reviewed_head_sha  TEXT    NOT NULL,
    workspace_id       TEXT    NOT NULL REFERENCES workspaces(id),
    opening_title      TEXT    NOT NULL,
    selection_policy   TEXT    NOT NULL CHECK (selection_policy IN (
        'ALL_ELIGIBLE', 'EXPLICIT')),
    spawn_mode         TEXT    NOT NULL CHECK (spawn_mode IN (
        'author_is_reviewer', 'suggested_change')),
    base_repository_id TEXT    NOT NULL,
    head_repository_id TEXT    NOT NULL,
    base_ref           TEXT    NOT NULL,
    head_ref           TEXT    NOT NULL,
    selection_digest  TEXT    NOT NULL,
    frozen_at_ms       INTEGER NOT NULL CHECK (frozen_at_ms >= 0),
    CHECK (length(trim(repo_full_name)) > 0
        AND length(trim(reviewed_head_sha)) > 0
        AND length(trim(workspace_id)) > 0
        AND length(trim(opening_title)) > 0
        AND length(trim(base_repository_id)) > 0
        AND length(trim(head_repository_id)) > 0
        AND length(trim(base_ref)) > 0
        AND length(trim(head_ref)) > 0
        AND length(trim(selection_digest)) > 0)
);
CREATE TABLE review_build_selection_item (
    thread_id          TEXT    NOT NULL
        REFERENCES review_build_selection(thread_id) ON DELETE RESTRICT,
    position           INTEGER NOT NULL CHECK (position > 0),
    review_pass_id     TEXT    NOT NULL,
    finding_id         TEXT    NOT NULL
        REFERENCES review_findings(id) ON DELETE RESTRICT,
    finding_revision   INTEGER NOT NULL CHECK (finding_revision > 0),
    content_json       TEXT    NOT NULL,
    content_digest     TEXT    NOT NULL,
    PRIMARY KEY (thread_id, position),
    UNIQUE (thread_id, finding_id),
    CHECK (length(trim(review_pass_id)) > 0
        AND length(trim(finding_id)) > 0
        AND length(trim(content_json)) > 0
        AND length(trim(content_digest)) > 0)
);
CREATE TABLE review_build_outcome_receipt (
    task_outcome_id     TEXT    PRIMARY KEY
        REFERENCES task_outcome(id) ON DELETE RESTRICT,
    task_id             TEXT    NOT NULL UNIQUE REFERENCES tasks(id),
    thread_id           TEXT    NOT NULL
        REFERENCES review_build_selection(thread_id) ON DELETE RESTRICT,
    review_pass_id      TEXT    NOT NULL REFERENCES review_passes(id),
    terminal_reason     TEXT    NOT NULL CHECK (terminal_reason IN (
        'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')),
    disposition         TEXT    NOT NULL CHECK (disposition IN (
        'RESOLVED', 'IGNORED_TERMINAL', 'STALE_SELECTION')),
    selection_digest    TEXT    NOT NULL,
    resolved_count      INTEGER NOT NULL CHECK (resolved_count >= 0),
    detail              TEXT    NOT NULL,
    recorded_at_ms      INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    CHECK (length(trim(review_pass_id)) > 0
        AND length(trim(selection_digest)) > 0
        AND length(trim(detail)) > 0
        AND ((disposition = 'RESOLVED' AND terminal_reason = 'COMPLETED')
          OR (disposition = 'IGNORED_TERMINAL'
                AND terminal_reason <> 'COMPLETED')
          OR disposition = 'STALE_SELECTION'))
);
CREATE UNIQUE INDEX task_active_pr_idx
    ON tasks(lower(linked_pr_ref))
    WHERE linked_pr_ref IS NOT NULL
      AND ((workflow_version = 'V2'
              AND lifecycle_state NOT IN ('CANCELED', 'COMPLETED', 'REMOTE_CLOSED'))
        OR (workflow_version = 'LEGACY' AND phase <> 'COMPLETED'));
CREATE TABLE local_review_agent_request (
    id                         TEXT    NOT NULL PRIMARY KEY,
    review_id                  TEXT    NOT NULL
        REFERENCES review_session(id) ON DELETE CASCADE,
    review_round_id            TEXT    NOT NULL UNIQUE
        REFERENCES review_round(id) ON DELETE CASCADE,
    pr_id                      TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER NOT NULL CHECK (task_epoch > 0),
    local_development_stage_id TEXT    NOT NULL
        REFERENCES local_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation           INTEGER NOT NULL CHECK (stage_generation > 0),
    dev_report_id              TEXT    NOT NULL REFERENCES dev_report(id),
    code_fingerprint           TEXT    NOT NULL,
    head_sha                   TEXT    NOT NULL,
    base_sha                   TEXT    NOT NULL,
    mode                       TEXT    NOT NULL CHECK (mode IN ('ADVISORY', 'BLOCKING')),
    task_blocker_id            TEXT    UNIQUE REFERENCES task_blocker(id),
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'IMPORTED', 'CANCELED', 'STALE')),
    requested_by               TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    completed_at_ms            INTEGER,
    completion_evidence        TEXT,
    CHECK (length(requested_by) > 0),
    CHECK ((mode = 'BLOCKING') = (task_blocker_id IS NOT NULL)),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL))
);
CREATE INDEX idx_local_review_agent_request_task_status
    ON local_review_agent_request(task_id, status, requested_at_ms);
CREATE INDEX idx_local_review_agent_request_review_status
    ON local_review_agent_request(review_id, status, requested_at_ms);
CREATE TABLE local_review_imported_finding (
    request_id          TEXT    NOT NULL
        REFERENCES local_review_agent_request(id) ON DELETE CASCADE,
    finding_id          TEXT    NOT NULL UNIQUE REFERENCES finding(id),
    thread_id           TEXT    NOT NULL UNIQUE REFERENCES local_review_thread(id),
    comment_revision_id TEXT    NOT NULL UNIQUE
        REFERENCES local_review_comment_revision(id),
    imported_by         TEXT    NOT NULL,
    imported_at_ms      INTEGER NOT NULL,
    PRIMARY KEY (request_id, finding_id),
    CHECK (length(imported_by) > 0)
);
CREATE TABLE planning_base_refresh_operation (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    workspace_id             TEXT    NOT NULL,
    command_id               TEXT    NOT NULL,
    actor                    TEXT    NOT NULL,
    operation_id             TEXT    NOT NULL UNIQUE,
    dispatch_ticket_id       TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) DEFERRABLE INITIALLY DEFERRED,
    launch_command_id        TEXT    NOT NULL UNIQUE,
    reserved_thread_turn_id  TEXT    NOT NULL UNIQUE,
    semantic_attempt         INTEGER NOT NULL CHECK (semantic_attempt > 0),
    repository_root          TEXT    NOT NULL,
    previous_base_sha        TEXT,
    launch_intent            TEXT    NOT NULL CHECK (json_valid(launch_intent)),
    launch_intent_digest     TEXT    NOT NULL CHECK (length(launch_intent_digest) = 64),
    status                   TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    raw_outcome              TEXT CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest        TEXT,
    result_worktree_path     TEXT,
    result_base_ref          TEXT,
    result_base_sha          TEXT,
    error_message            TEXT,
    requested_at_ms          INTEGER NOT NULL,
    completed_at_ms          INTEGER,
    launch_disposition       TEXT    NOT NULL DEFAULT 'PENDING' CHECK (
        launch_disposition IN ('PENDING', 'LAUNCHED', 'SUPPRESSED')),
    launch_disposition_reason TEXT,
    launched_thread_turn_id  TEXT UNIQUE REFERENCES thread_turn(id),
    launched_at_ms           INTEGER,
    UNIQUE (trunk_id, command_id),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK ((status = 'SUCCEEDED') =
        (result_worktree_path IS NOT NULL
          AND result_base_ref IS NOT NULL
          AND result_base_sha IS NOT NULL)),
    CHECK ((launch_disposition = 'PENDING'
            AND launch_disposition_reason IS NULL
            AND launched_thread_turn_id IS NULL AND launched_at_ms IS NULL)
        OR (launch_disposition = 'LAUNCHED'
            AND launch_disposition_reason IS NULL
            AND status = 'SUCCEEDED'
            AND launched_thread_turn_id = reserved_thread_turn_id
            AND launched_at_ms IS NOT NULL)
        OR (launch_disposition = 'SUPPRESSED'
            AND launch_disposition_reason IS NOT NULL
            AND launched_thread_turn_id IS NULL AND launched_at_ms IS NOT NULL))
);
CREATE INDEX idx_planning_base_refresh_ready
    ON planning_base_refresh_operation(status, completed_at_ms, id);
CREATE TABLE trunk_planning_base_request_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    planning_operation_id    TEXT    NOT NULL UNIQUE
        REFERENCES planning_base_refresh_operation(id) ON DELETE CASCADE,
    expected_trunk_version   INTEGER NOT NULL CHECK (expected_trunk_version >= 0),
    returned_trunk_version   INTEGER NOT NULL CHECK (
        returned_trunk_version = expected_trunk_version + 1),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'ACTIVE', 'IDLE', 'ARCHIVED')),
    recorded_at_ms           INTEGER NOT NULL,
    UNIQUE (trunk_id, command_id)
);
CREATE TABLE trunk_planning_base_result_receipt (
    id                       TEXT    NOT NULL PRIMARY KEY,
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL UNIQUE,
    planning_operation_id    TEXT    NOT NULL UNIQUE
        REFERENCES planning_base_refresh_operation(id) ON DELETE CASCADE,
    operation_id             TEXT    NOT NULL UNIQUE,
    raw_outcome              TEXT    NOT NULL,
    raw_result_digest        TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance               TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    returned_trunk_version   INTEGER NOT NULL CHECK (returned_trunk_version > 0),
    returned_lifecycle       TEXT    NOT NULL CHECK (returned_lifecycle IN (
        'ACTIVE', 'IDLE', 'ARCHIVED')),
    recorded_at_ms           INTEGER NOT NULL
);
CREATE UNIQUE INDEX idx_review_assignment_turn_logical_attempt
    ON review_assignment_turn(assignment_id, purpose, subject_key, attempt);
CREATE TABLE review_round_followup_v262 (
    round_id                 TEXT    NOT NULL PRIMARY KEY
        REFERENCES review_round(id) ON DELETE CASCADE,
    start_commit             TEXT    NOT NULL,
    phase                    TEXT    NOT NULL CHECK (phase IN (
        'PRIMARY', 'SELF_REFUTATION', 'VERIFYING',
        'FINALIZING', 'COMPLETED', 'BLOCKED', 'CANCELED')),
    verifier_assignment_id   TEXT REFERENCES review_assignment(id),
    verifier_run_id          TEXT REFERENCES agent_run(id),
    version                  INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at_ms            INTEGER NOT NULL,
    updated_at_ms            INTEGER NOT NULL,
    CHECK ((verifier_assignment_id IS NULL) = (verifier_run_id IS NULL))
);
CREATE INDEX idx_thread_question_open
    ON thread_question(state, created_at_ms, id);
CREATE INDEX idx_task_question_open
    ON task_question(state, created_at_ms, id);
CREATE INDEX idx_stage_question_open
    ON stage_question(state, created_at_ms, id);
CREATE INDEX idx_review_assignment_question_open
    ON review_assignment_question(state, created_at_ms, id);
CREATE TABLE typed_question_answer_attempt (
    id                  TEXT    NOT NULL PRIMARY KEY,
    owner_kind          TEXT    NOT NULL CHECK (owner_kind IN (
        'THREAD_TURN', 'TASK_TURN', 'STAGE_TURN',
        'REVIEW_ASSIGNMENT_TURN')),
    question_id         TEXT    NOT NULL,
    expected_revision   INTEGER NOT NULL CHECK (expected_revision >= 0),
    answer_option_id    TEXT,
    answer_free_form    TEXT,
    actor               TEXT    NOT NULL,
    outcome             TEXT    NOT NULL CHECK (outcome IN (
        'ACCEPTED', 'ALREADY_TERMINAL', 'REVISION_CONFLICT',
        'OWNER_TERMINAL')),
    attempted_at_ms     INTEGER NOT NULL,
    CHECK (answer_option_id IS NOT NULL OR answer_free_form IS NOT NULL)
);
CREATE INDEX idx_typed_question_answer_attempt_question
    ON typed_question_answer_attempt(owner_kind, question_id,
        attempted_at_ms, id);
CREATE TABLE typed_user_wait_result (
    operation_id       TEXT    NOT NULL PRIMARY KEY,
    owner_kind         TEXT    NOT NULL CHECK (owner_kind IN (
        'THREAD_TURN', 'TASK_TURN', 'STAGE_TURN',
        'REVIEW_ASSIGNMENT_TURN')),
    turn_id            TEXT    NOT NULL,
    wait_kind          TEXT    NOT NULL CHECK (wait_kind IN (
        'QUESTION', 'PERMISSION')),
    wait_id            TEXT    NOT NULL,
    payload_digest     TEXT    NOT NULL,
    result_evidence    TEXT    NOT NULL,
    accepted_at_ms     INTEGER NOT NULL,
    UNIQUE (owner_kind, turn_id, wait_kind, wait_id)
);
CREATE INDEX idx_permission_request_active_grant
    ON permission_request(
        grant_scope_kind, grant_scope_id, tool_name, state, remaining_uses,
        requested_at_ms);
CREATE TABLE permission_answer_attempt (
    id                  TEXT    NOT NULL PRIMARY KEY,
    permission_id       TEXT    NOT NULL REFERENCES permission_request(id) ON DELETE CASCADE,
    expected_revision   INTEGER NOT NULL CHECK (expected_revision >= 0),
    proposed_state      TEXT    NOT NULL CHECK (proposed_state IN (
        'ALLOWED_ONCE', 'ALLOWED_NEXT', 'ALLOWED_TASK',
        'ALLOWED_REPOSITORY', 'DENIED', 'CANCELED', 'EXPIRED')),
    actor               TEXT    NOT NULL,
    answer              TEXT    NOT NULL,
    outcome             TEXT    NOT NULL CHECK (outcome IN (
        'ACCEPTED', 'ALREADY_TERMINAL', 'REVISION_CONFLICT')),
    attempted_at_ms     INTEGER NOT NULL
);
CREATE INDEX idx_permission_answer_attempt_request
    ON permission_answer_attempt(permission_id, attempted_at_ms, id);
CREATE TABLE stage_resume_passive_wait_v263 (
    handoff_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage_resume_rearm_intent_v257(handoff_id) ON DELETE CASCADE,
    wait_kind           TEXT    NOT NULL CHECK (wait_kind IN (
        'PLAN_APPROVAL', 'LOCAL_REVIEW')),
    stage_id            TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation    INTEGER NOT NULL CHECK (stage_generation > 0),
    checkpoint          TEXT    NOT NULL CHECK (checkpoint IN (
        'AWAITING_APPROVAL', 'LOCAL_REVIEW')),
    recorded_at_ms      INTEGER NOT NULL
);
CREATE TABLE task_branch_sync_policy_revision (
    id                TEXT    NOT NULL PRIMARY KEY,
    task_id           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    revision          INTEGER NOT NULL CHECK (revision > 0),
    enabled           INTEGER NOT NULL CHECK (enabled IN (0, 1)),
    schedule          TEXT    NOT NULL
        CHECK (length(trim(schedule)) BETWEEN 1 AND 64),
    source            TEXT    NOT NULL CHECK (source IN (
        'FIRST_PUSH_DEFAULT', 'USER_CONFIGURED')),
    attempt_limit     INTEGER NOT NULL CHECK (attempt_limit BETWEEN 1 AND 10),
    command_id        TEXT    NOT NULL,
    actor             TEXT    NOT NULL,
    created_at_ms     INTEGER NOT NULL,
    UNIQUE (task_id, revision),
    UNIQUE (task_id, command_id)
);
CREATE TABLE permission_grant_consumption (
    id                  TEXT    NOT NULL PRIMARY KEY,
    permission_id       TEXT    NOT NULL REFERENCES permission_request(id) ON DELETE CASCADE,
    turn_kind           TEXT    NOT NULL CHECK (turn_kind IN (
        'THREAD', 'TASK', 'STAGE', 'REVIEW_ASSIGNMENT')),
    turn_id             TEXT    NOT NULL,
    operation_id        TEXT    NOT NULL,
    call_id             TEXT    NOT NULL,
    parameters_digest   TEXT    NOT NULL,
    remaining_after     INTEGER NOT NULL CHECK (remaining_after = -1 OR remaining_after >= 0),
    consumed_at_ms      INTEGER NOT NULL,
    UNIQUE (permission_id, turn_kind, turn_id, operation_id,
        call_id, parameters_digest)
);
CREATE INDEX idx_permission_grant_consumption_request
    ON permission_grant_consumption(permission_id, consumed_at_ms, id);
CREATE TABLE plan_turn_user_wait_continuation_v265 (
    wait_kind                    TEXT    NOT NULL CHECK (wait_kind IN (
        'QUESTION', 'PERMISSION')),
    wait_id                      TEXT    NOT NULL,
    command_id                   TEXT    NOT NULL UNIQUE,
    task_id                      TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                   INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id                     TEXT    NOT NULL REFERENCES plan_stage(stage_id) ON DELETE CASCADE,
    stage_generation             INTEGER NOT NULL CHECK (stage_generation > 0),
    predecessor_turn_id          TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    predecessor_operation_id     TEXT    NOT NULL UNIQUE,
    successor_turn_id            TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    successor_operation_id       TEXT    NOT NULL UNIQUE,
    expected_stage_version       INTEGER NOT NULL CHECK (expected_stage_version >= 0),
    returned_stage_version       INTEGER NOT NULL,
    checkpoint                   TEXT    NOT NULL CHECK (checkpoint IN (
        'DRAFTING', 'SELF_REVIEW')),
    admitted_at_ms               INTEGER NOT NULL,
    PRIMARY KEY (wait_kind, wait_id),
    CHECK (returned_stage_version = expected_stage_version + 1)
);
CREATE TABLE plan_self_review_user_wait_attempt_v265 (
    self_review_id              TEXT    NOT NULL REFERENCES plan_self_review(id) ON DELETE CASCADE,
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 1),
    task_turn_id                TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    operation_id                TEXT    NOT NULL UNIQUE,
    predecessor_turn_id         TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    wait_kind                   TEXT    NOT NULL,
    wait_id                     TEXT    NOT NULL,
    requested_at_ms             INTEGER NOT NULL,
    PRIMARY KEY (self_review_id, semantic_attempt),
    UNIQUE (wait_kind, wait_id)
);
CREATE TABLE stage_turn_user_wait_continuation_v265 (
    request_id                   TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage_steering_request_v257(id) ON DELETE CASCADE,
    wait_kind                    TEXT    NOT NULL CHECK (wait_kind IN (
        'QUESTION', 'PERMISSION')),
    wait_id                      TEXT    NOT NULL,
    predecessor_turn_id          TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    predecessor_operation_id     TEXT    NOT NULL UNIQUE,
    successor_turn_id            TEXT    UNIQUE REFERENCES stage_turn(id),
    successor_operation_id       TEXT    UNIQUE,
    admitted_at_ms               INTEGER,
    UNIQUE (wait_kind, wait_id),
    CHECK ((successor_turn_id IS NULL) = (successor_operation_id IS NULL)),
    CHECK ((successor_turn_id IS NULL) = (admitted_at_ms IS NULL))
);
CREATE TABLE review_turn_user_wait_continuation_v265 (
    wait_kind                    TEXT    NOT NULL CHECK (wait_kind IN (
        'QUESTION', 'PERMISSION')),
    wait_id                      TEXT    NOT NULL,
    predecessor_turn_id          TEXT    NOT NULL UNIQUE REFERENCES review_assignment_turn(id),
    predecessor_operation_id     TEXT    NOT NULL UNIQUE,
    successor_turn_id            TEXT    NOT NULL UNIQUE REFERENCES review_assignment_turn(id),
    successor_operation_id       TEXT    NOT NULL UNIQUE,
    admitted_at_ms               INTEGER NOT NULL,
    PRIMARY KEY (wait_kind, wait_id)
);
CREATE TABLE task_brain_conversation_result_v266 (
    task_turn_id         TEXT    NOT NULL PRIMARY KEY REFERENCES task_turn(id),
    operation_id         TEXT    NOT NULL UNIQUE,
    raw_outcome          TEXT    NOT NULL CHECK (raw_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    raw_result_digest    TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance           TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED')),
    terminal_status      TEXT    NOT NULL CHECK (terminal_status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    assistant_message_id TEXT    UNIQUE REFERENCES task_message(id),
    evidence             TEXT    NOT NULL,
    recorded_at_ms       INTEGER NOT NULL,
    CHECK ((terminal_status = 'SUCCEEDED') =
        (assistant_message_id IS NOT NULL)),
    CHECK ((acceptance = 'SUPERSEDED') =
        (terminal_status = 'SUPERSEDED'))
);
CREATE TABLE task_turn_user_wait_continuation_v266 (
    wait_kind                    TEXT    NOT NULL CHECK (wait_kind IN (
        'QUESTION', 'PERMISSION')),
    wait_id                      TEXT    NOT NULL,
    source_turn_id               TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    source_operation_id          TEXT    NOT NULL UNIQUE,
    logical_turn_id              TEXT    NOT NULL REFERENCES task_turn(id),
    logical_operation_id         TEXT    NOT NULL,
    successor_turn_id            TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    successor_operation_id       TEXT    NOT NULL UNIQUE,
    purpose                      TEXT    NOT NULL CHECK (purpose IN (
        'TASK_BRAIN_CONVERSATION', 'DEVELOPMENT_BRAIN_REVIEW',
        'REMOTE_FEEDBACK_BRAIN_REVIEW')),
    task_id                      TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                   INTEGER NOT NULL CHECK (task_epoch > 0),
    trigger_stage_id             TEXT    REFERENCES stage(id),
    trigger_stage_generation     INTEGER,
    expected_code_fingerprint    TEXT,
    expected_head_sha            TEXT,
    expected_base_sha            TEXT,
    requested_at_ms              INTEGER NOT NULL,
    PRIMARY KEY (wait_kind, wait_id),
    CHECK ((trigger_stage_id IS NULL) =
        (trigger_stage_generation IS NULL))
);
CREATE TABLE remote_policy_stage_receipt_v268 (
    id                                TEXT    NOT NULL PRIMARY KEY,
    stage_id                          TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (
        cause = 'RECONSIDER_REMOTE_READINESS_POLICY'),
    actor                             TEXT    NOT NULL CHECK (length(actor) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition = 'APPLIED'),
    expected_task_epoch               INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation         INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version            INTEGER NOT NULL CHECK (expected_stage_version >= 0),
    source_checkpoint                 TEXT    NOT NULL CHECK (
        source_checkpoint = 'READY_TO_MERGE'),
    subject_task_epoch                INTEGER,
    subject_stage_id                  TEXT,
    subject_stage_generation          INTEGER,
    subject_operation_id              TEXT,
    subject_attempt                   INTEGER,
    subject_expected_code_fingerprint TEXT,
    subject_expected_head_sha         TEXT,
    subject_expected_base_sha         TEXT,
    proof_id                          TEXT    NOT NULL
        REFERENCES remote_readiness_evidence(id),
    returned_kind                     TEXT    NOT NULL CHECK (
        returned_kind = 'REMOTE_DEVELOPMENT'),
    returned_generation               INTEGER NOT NULL CHECK (returned_generation > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version > 0),
    returned_checkpoint               TEXT    NOT NULL CHECK (
        returned_checkpoint = 'WAITING_REMOTE_REVIEW'),
    returned_end_reason               TEXT,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (stage_id, command_id),
    CHECK (returned_version = expected_stage_version + 1),
    CHECK (subject_task_epoch IS NULL
        AND subject_stage_id IS NULL
        AND subject_stage_generation IS NULL
        AND subject_operation_id IS NULL
        AND subject_attempt IS NULL
        AND subject_expected_code_fingerprint IS NULL
        AND subject_expected_head_sha IS NULL
        AND subject_expected_base_sha IS NULL),
    CHECK (returned_end_reason IS NULL
        AND returned_pending_task_epoch IS NULL
        AND returned_pending_stage_id IS NULL
        AND returned_pending_stage_generation IS NULL
        AND returned_pending_operation_id IS NULL
        AND returned_pending_attempt IS NULL
        AND returned_pending_code_fingerprint IS NULL
        AND returned_pending_head_sha IS NULL
        AND returned_pending_base_sha IS NULL)
);
CREATE VIEW v2_trunk_purge_state_v269 AS
SELECT trunk.id AS trunk_id,
       trunk.lifecycle_state,
       trunk.aggregate_version,
       (SELECT COUNT(*)
        FROM tasks task
        WHERE task.thread_id = trunk.id
          AND task.workflow_version = 'V2'
          AND task.lifecycle_state NOT IN (
              'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
           AS nonterminal_task_count,
       (SELECT COUNT(*)
        FROM tasks task
        WHERE task.thread_id = trunk.id
          AND task.workflow_version = 'V2'
          AND NOT EXISTS (
              SELECT 1
              FROM task_outcome outcome
              JOIN cleanup_operation operation
                ON operation.id = outcome.cleanup_operation_id
              JOIN cleanup_stage cleanup
                ON cleanup.stage_id = outcome.cleanup_stage_id
              JOIN stage owner ON owner.id = cleanup.stage_id
              JOIN dispatch_ticket ticket
                ON ticket.id = operation.dispatch_ticket_id
              WHERE outcome.task_id = task.id
                AND outcome.trunk_id = trunk.id
                AND outcome.task_epoch = task.epoch
                AND outcome.terminal_reason = task.lifecycle_state
                AND operation.task_id = task.id
                AND operation.task_epoch = task.epoch
                AND operation.cleanup_stage_id = cleanup.stage_id
                AND operation.status = 'COMPLETED'
                AND cleanup.task_id = task.id
                AND cleanup.task_epoch = task.epoch
                AND cleanup.terminal_reason = outcome.terminal_reason
                AND owner.task_id = task.id
                AND owner.kind = 'CLEANUP'
                AND owner.generation = cleanup.generation
                AND owner.checkpoint = 'COMPLETED'
                AND owner.completed_at_ms IS NOT NULL
                AND ticket.trunk_id = trunk.id
                AND ticket.task_id = task.id
                AND ticket.task_epoch = task.epoch
                AND ticket.status = 'SUCCEEDED'
                AND ticket.delivery_acceptance = 'ACCEPTED'))
           AS incomplete_cleanup_count,
       ((SELECT COUNT(*)
         FROM thread_question question
         JOIN thread_turn turn ON turn.id = question.turn_id
         WHERE turn.trunk_id = trunk.id
           AND (question.state = 'OPEN'
             OR question.continuation_state = 'READY'))
        + (SELECT COUNT(*)
           FROM task_question question
           JOIN task_turn turn ON turn.id = question.turn_id
           JOIN tasks task ON task.id = turn.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND (question.state = 'OPEN'
               OR question.continuation_state = 'READY'))
        + (SELECT COUNT(*)
           FROM stage_question question
           JOIN stage_turn turn ON turn.id = question.turn_id
           JOIN stage owner ON owner.id = turn.stage_id
           JOIN tasks task ON task.id = owner.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND (question.state = 'OPEN'
               OR question.continuation_state = 'READY'))
        + (SELECT COUNT(*)
           FROM review_assignment_question question
           JOIN review_assignment_turn turn ON turn.id = question.turn_id
           JOIN review_assignment assignment
             ON assignment.id = turn.assignment_id
           JOIN review_round round ON round.id = assignment.round_id
           JOIN review_session session ON session.id = round.session_id
           WHERE (session.owner_thread_id = trunk.id
               OR EXISTS (
                   SELECT 1 FROM tasks task
                   WHERE task.id = session.owner_task_id
                     AND task.thread_id = trunk.id
                     AND task.workflow_version = 'V2'))
             AND (question.state = 'OPEN'
               OR question.continuation_state = 'READY'))
        + (SELECT COUNT(*)
           FROM permission_request permission
           WHERE (permission.state = 'OPEN'
               OR permission.continuation_state = 'READY')
             AND ((permission.turn_kind = 'THREAD' AND EXISTS (
                      SELECT 1 FROM thread_turn turn
                      WHERE turn.id = permission.turn_id
                        AND turn.trunk_id = trunk.id))
               OR (permission.turn_kind = 'TASK' AND EXISTS (
                      SELECT 1
                      FROM task_turn turn
                      JOIN tasks task ON task.id = turn.task_id
                      WHERE turn.id = permission.turn_id
                        AND task.thread_id = trunk.id
                        AND task.workflow_version = 'V2'))
               OR (permission.turn_kind = 'STAGE' AND EXISTS (
                      SELECT 1
                      FROM stage_turn turn
                      JOIN stage owner ON owner.id = turn.stage_id
                      JOIN tasks task ON task.id = owner.task_id
                      WHERE turn.id = permission.turn_id
                        AND task.thread_id = trunk.id
                        AND task.workflow_version = 'V2'))
               OR (permission.turn_kind = 'REVIEW_ASSIGNMENT' AND EXISTS (
                      SELECT 1
                      FROM review_assignment_turn turn
                      JOIN review_assignment assignment
                        ON assignment.id = turn.assignment_id
                      JOIN review_round round
                        ON round.id = assignment.round_id
                      JOIN review_session session
                        ON session.id = round.session_id
                      WHERE turn.id = permission.turn_id
                        AND (session.owner_thread_id = trunk.id
                          OR EXISTS (
                              SELECT 1 FROM tasks task
                              WHERE task.id = session.owner_task_id
                                AND task.thread_id = trunk.id
                                AND task.workflow_version = 'V2')))))))
           AS open_wait_count,
       ((SELECT COUNT(*) FROM thread_turn turn
         WHERE turn.trunk_id = trunk.id
           AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
        + (SELECT COUNT(*)
           FROM task_turn turn
           JOIN tasks task ON task.id = turn.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
        + (SELECT COUNT(*)
           FROM stage_turn turn
           JOIN stage owner ON owner.id = turn.stage_id
           JOIN tasks task ON task.id = owner.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
        + (SELECT COUNT(*)
           FROM review_assignment_turn turn
           JOIN review_assignment assignment
             ON assignment.id = turn.assignment_id
           JOIN review_round round ON round.id = assignment.round_id
           JOIN review_session session ON session.id = round.session_id
           WHERE turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')
             AND (session.owner_thread_id = trunk.id
               OR EXISTS (
                   SELECT 1 FROM tasks task
                   WHERE task.id = session.owner_task_id
                     AND task.thread_id = trunk.id
                     AND task.workflow_version = 'V2'))))
           AS live_turn_count,
       (SELECT COUNT(*) FROM dispatch_ticket ticket
        WHERE ticket.trunk_id = trunk.id
          AND ticket.status IN (
              'REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT', 'RESULT_PENDING',
              'CLAIMED', 'RUNNING', 'DELIVERING'))
           AS live_ticket_count,
       (SELECT COUNT(*)
        FROM agent_execution execution
        JOIN dispatch_ticket ticket ON ticket.id = execution.ticket_id
        WHERE ticket.trunk_id = trunk.id
          AND execution.status IN ('STARTING', 'RUNNING', 'UNKNOWN'))
           AS live_execution_count,
       ((SELECT COUNT(*)
         FROM planning_base_refresh_operation operation
         WHERE operation.trunk_id = trunk.id
           AND (operation.status = 'REQUESTED'
             OR (operation.status = 'SUCCEEDED'
               AND operation.launch_disposition = 'PENDING')))
        + (SELECT COALESCE(SUM(
                live.active_plan_review_count
              + live.active_validation_count
              + live.active_brain_episode_count
              + live.active_provision_operation_count
              + live.active_quiescence_count
              + live.active_replan_count
              + live.active_feedback_batch_count
              + live.active_publish_operation_count
              + live.unreconciled_publish_operation_count
              + live.active_publish_effect_count
              + live.active_publish_authorization_count), 0)
           FROM task_live_work_counts_v230 live
           JOIN tasks task ON task.id = live.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2')
        + (SELECT COUNT(*) FROM stage_steering_request_v257 request
           JOIN tasks task ON task.id = request.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND request.status = 'PENDING')
        + (SELECT COUNT(*) FROM local_review_agent_request request
           JOIN tasks task ON task.id = request.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND request.status = 'REQUESTED')
        + (SELECT COUNT(*) FROM remote_observation_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status IN ('REQUESTED', 'DISPATCHED'))
        + (SELECT COUNT(*) FROM ci_repair_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status IN ('REQUESTED', 'DISPATCHED'))
        + (SELECT COUNT(*) FROM branch_sync_dispatch_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status IN (
                 'REQUESTED', 'DISPATCHED', 'INDETERMINATE'))
        + (SELECT COUNT(*)
           FROM remote_feedback_validation_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status IN ('REQUESTED', 'DISPATCHED'))
        + (SELECT COUNT(*) FROM remote_feedback_brain_episode episode
           JOIN tasks task ON task.id = episode.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND episode.status = 'REQUESTED')
        + (SELECT COUNT(*) FROM remote_feedback_batch batch
           JOIN tasks task ON task.id = batch.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND batch.status NOT IN ('COMPLETED', 'SUPERSEDED'))
        + (SELECT COUNT(*) FROM ci_repair_episode episode
           JOIN tasks task ON task.id = episode.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND episode.status NOT IN ('SUCCEEDED', 'EXHAUSTED', 'STOPPED'))
        + (SELECT COUNT(*) FROM branch_sync_episode episode
           JOIN tasks task ON task.id = episode.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND episode.status NOT IN ('SUCCEEDED', 'FAILED', 'STOPPED'))
        + (SELECT COUNT(*) FROM remote_mark_ready_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status IN (
                 'REQUESTED', 'CLAIMED', 'AWAITING_OBSERVATION',
                 'INDETERMINATE'))
        + (SELECT COUNT(*) FROM remote_merge_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status NOT IN (
                 'SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED'))
        + (SELECT COUNT(*) FROM remote_mark_ready_authorization authorization
           JOIN tasks task ON task.id = authorization.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND authorization.status = 'ACTIVE')
        + (SELECT COUNT(*) FROM remote_merge_authorization authorization
           JOIN tasks task ON task.id = authorization.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND authorization.status = 'ACTIVE')
        + (SELECT COUNT(*) FROM cleanup_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status <> 'COMPLETED')
        + (SELECT COUNT(*) FROM cleanup_step_retry_request request
           JOIN tasks task ON task.id = request.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND request.status = 'PENDING')
        + (SELECT COUNT(*) FROM task_outcome_summary_operation operation
           JOIN tasks task ON task.id = operation.task_id
           WHERE task.thread_id = trunk.id
             AND task.workflow_version = 'V2'
             AND operation.status = 'REQUESTED')
        + (SELECT COUNT(*) FROM trunk_outcome_inbox inbox
           WHERE inbox.trunk_id = trunk.id AND inbox.status = 'PENDING')
        + (SELECT COUNT(*)
           FROM outbox event
           JOIN dispatch_ticket ticket ON ticket.id = event.aggregate_id
           WHERE event.aggregate_kind = 'DISPATCH_TICKET'
             AND event.status IN ('PENDING', 'CLAIMED')
             AND ticket.trunk_id = trunk.id))
           AS live_operation_count,
       (SELECT COUNT(*)
        FROM stage owner
        JOIN tasks task ON task.id = owner.task_id
        WHERE task.thread_id = trunk.id
          AND task.workflow_version = 'V2'
          AND owner.completed_at_ms IS NULL)
           AS incomplete_stage_count,
       ((SELECT COUNT(*) FROM capacity_lease lease
         WHERE lease.workflow_source = 'V2'
           AND lease.trunk_id = trunk.id
           AND lease.released_at_ms IS NULL)
        + (SELECT COUNT(*)
           FROM worktree_leases lease
           JOIN tasks task ON task.id = lease.task_id
           WHERE lease.workflow_version = 'V2'
             AND task.thread_id = trunk.id
             AND task.workflow_version = 'V2'))
           AS live_lease_count
FROM threads trunk
WHERE trunk.turn_version = 'V2';
CREATE TABLE v2_trunk_purge_authorization_v269 (
    trunk_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES threads(id) DEFERRABLE INITIALLY DEFERRED,
    archived_version  INTEGER NOT NULL CHECK (archived_version >= 0),
    authorized_at_ms  INTEGER NOT NULL CHECK (authorized_at_ms > 0)
);
CREATE TABLE v2_user_remote_action_v270 (
    id                    TEXT    NOT NULL PRIMARY KEY,
    operation_id          TEXT    NOT NULL UNIQUE,
    task_id               TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id            TEXT    NOT NULL,
    task_epoch            INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_stage_id       TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation      INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id  TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    pr_id                 TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    kind                  TEXT    NOT NULL CHECK (kind IN (
        'DEQUEUE', 'DELETE_REMOTE_BRANCH',
        'POST_TOP_LEVEL_COMMENT', 'SUBMIT_REVIEW')),
    remote_repository_id  TEXT    NOT NULL,
    head_repository_id    TEXT    NOT NULL,
    remote_pr_number      INTEGER NOT NULL CHECK (remote_pr_number > 0),
    branch_name           TEXT    NOT NULL,
    expected_head_sha     TEXT    NOT NULL,
    expected_base_sha     TEXT    NOT NULL,
    payload_json          TEXT    NOT NULL,
    payload_digest        TEXT    NOT NULL CHECK (length(payload_digest) = 64),
    handled_action        TEXT CHECK (handled_action IN (
        'APPROVED', 'CHANGES_REQUESTED', 'COMMENTED')),
    semantic_attempt      INTEGER NOT NULL DEFAULT 1 CHECK (semantic_attempt = 1),
    status                TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE',
        'CANCELED', 'ABANDONED')),
    attempt_count         INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit         INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode            TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner           TEXT,
    claimed_at_ms         INTEGER,
    lease_until_ms        INTEGER,
    external_effect_id    TEXT,
    evidence              TEXT,
    last_error            TEXT,
    recovery_baseline_json TEXT,
    authorized_by         TEXT    NOT NULL,
    authorized_at_ms      INTEGER NOT NULL,
    completed_at_ms       INTEGER,
    finalized_at_ms       INTEGER, semantic_action TEXT, worktree_path TEXT, expected_code_fingerprint TEXT,
    CHECK (length(trim(remote_repository_id)) > 0
        AND length(trim(head_repository_id)) > 0
        AND length(trim(branch_name)) > 0
        AND length(trim(expected_head_sha)) > 0
        AND length(trim(expected_base_sha)) > 0
        AND length(trim(payload_json)) > 0
        AND length(trim(command_id)) > 0
        AND length(trim(authorized_by)) > 0),
    CHECK ((kind IN ('POST_TOP_LEVEL_COMMENT', 'SUBMIT_REVIEW'))
        OR handled_action IS NULL),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK ((status = 'SUCCEEDED') = (external_effect_id IS NOT NULL
        AND evidence IS NOT NULL AND completed_at_ms IS NOT NULL)),
    CHECK (status NOT IN ('CANCELED', 'ABANDONED')
        OR completed_at_ms IS NOT NULL),
    CHECK ((status IN ('SUCCEEDED', 'CANCELED', 'ABANDONED'))
        OR finalized_at_ms IS NULL),
    CHECK (finalized_at_ms IS NULL OR completed_at_ms IS NOT NULL),
    CHECK (attempt_count <= attempt_limit),
    UNIQUE (id, task_id, task_epoch, remote_stage_id, stage_generation,
        expected_head_sha, expected_base_sha),
    UNIQUE (task_id, command_id)
);
CREATE INDEX idx_v2_user_remote_action_live_v270
    ON v2_user_remote_action_v270(task_id, kind, payload_digest, status);
CREATE INDEX idx_v2_user_remote_action_finalize_v270
    ON v2_user_remote_action_v270(status, finalized_at_ms);
CREATE TABLE v2_user_remote_action_draft_v270 (
    action_id       TEXT    NOT NULL
        REFERENCES v2_user_remote_action_v270(id) ON DELETE CASCADE,
    position        INTEGER NOT NULL CHECK (position > 0),
    comment_id      TEXT    NOT NULL REFERENCES pr_comment(id),
    scope           TEXT    NOT NULL CHECK (scope IN ('pr', 'file-line')),
    file_path       TEXT,
    line_number     INTEGER,
    side            TEXT,
    start_line      INTEGER,
    start_side      TEXT,
    body            TEXT    NOT NULL,
    finding_id      TEXT,
    PRIMARY KEY (action_id, position),
    UNIQUE (action_id, comment_id),
    CHECK ((scope = 'pr' AND file_path IS NULL AND line_number IS NULL)
        OR (scope = 'file-line' AND file_path IS NOT NULL
            AND line_number IS NOT NULL AND side IS NOT NULL))
);
CREATE TABLE v2_user_remote_action_dispatch_v270 (
    action_id          TEXT    NOT NULL PRIMARY KEY
        REFERENCES v2_user_remote_action_v270(id) ON DELETE CASCADE,
    dispatch_ticket_id TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    operation_id       TEXT    NOT NULL UNIQUE,
    dispatched_at_ms   INTEGER NOT NULL
);
CREATE TABLE remote_readiness_notification_marker_v271 (
    stage_id              TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage(id) ON DELETE CASCADE,
    workspace_id          TEXT    NOT NULL
        REFERENCES workspaces(id) ON DELETE CASCADE,
    trunk_id              TEXT    NOT NULL
        REFERENCES threads(id) ON DELETE CASCADE,
    task_id               TEXT    NOT NULL
        REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch            INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_generation      INTEGER NOT NULL CHECK (stage_generation > 0),
    ready_stage_version   INTEGER NOT NULL CHECK (ready_stage_version >= 0),
    readiness_evidence_id TEXT    NOT NULL
        REFERENCES remote_readiness_evidence(id) ON DELETE CASCADE,
    head_sha              TEXT    NOT NULL CHECK (length(trim(head_sha)) > 0),
    state                 TEXT    NOT NULL CHECK (state IN (
        'DELIVERED', 'REGRESSED')),
    delivered_at_ms       INTEGER NOT NULL CHECK (delivered_at_ms >= 0),
    regressed_at_ms       INTEGER CHECK (regressed_at_ms >= 0),
    updated_at_ms         INTEGER NOT NULL CHECK (updated_at_ms >= 0),
    CHECK ((state = 'DELIVERED' AND regressed_at_ms IS NULL)
        OR (state = 'REGRESSED' AND regressed_at_ms IS NOT NULL))
);
CREATE INDEX idx_remote_readiness_notification_marker_state_v271
    ON remote_readiness_notification_marker_v271(state, updated_at_ms);
CREATE TABLE stage_resume_async_successor_v272 (
    handoff_id             TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage_resume_rearm_intent_v257(handoff_id) ON DELETE CASCADE,
    command_id             TEXT    NOT NULL UNIQUE,
    owner_kind             TEXT    NOT NULL CHECK (owner_kind IN (
        'PLAN_SELF_REVIEW', 'LOCAL_VALIDATION',
        'DEVELOPMENT_BRAIN_REVIEW', 'PUBLISH_RECOVERY',
        'MERGE_RECOVERY')),
    owner_id               TEXT    NOT NULL,
    operation_id           TEXT    NOT NULL,
    dispatch_ticket_id     TEXT    NOT NULL,
    dispatch_attempt       INTEGER NOT NULL CHECK (dispatch_attempt > 0),
    domain_attempt         INTEGER NOT NULL CHECK (domain_attempt > 0),
    status                 TEXT    NOT NULL CHECK (status IN ('PREPARED', 'ARMED')),
    returned_stage_version INTEGER CHECK (returned_stage_version >= 0),
    created_at_ms          INTEGER NOT NULL CHECK (created_at_ms >= 0),
    armed_at_ms            INTEGER,
    CHECK ((status = 'PREPARED' AND armed_at_ms IS NULL
            AND returned_stage_version IS NULL)
        OR (status = 'ARMED' AND armed_at_ms IS NOT NULL)),
    CHECK (returned_stage_version IS NULL
        OR owner_kind <> 'DEVELOPMENT_BRAIN_REVIEW')
);
CREATE INDEX idx_stage_resume_async_successor_operation_v272
    ON stage_resume_async_successor_v272(operation_id, status);
CREATE TABLE stage_resume_budget_lineage_v272 (
    handoff_id           TEXT    NOT NULL PRIMARY KEY
        REFERENCES stage_resume_async_successor_v272(handoff_id) ON DELETE CASCADE,
    owner_kind           TEXT    NOT NULL CHECK (owner_kind IN (
        'LOCAL_VALIDATION', 'DEVELOPMENT_BRAIN_REVIEW')),
    predecessor_owner_id TEXT    NOT NULL,
    successor_owner_id   TEXT    NOT NULL,
    execution_attempt    INTEGER NOT NULL CHECK (execution_attempt > 1),
    budget_attempt       INTEGER NOT NULL CHECK (budget_attempt > 0),
    consumes_budget      INTEGER NOT NULL CHECK (consumes_budget = 0),
    recorded_at_ms       INTEGER NOT NULL
);
CREATE TABLE plan_self_review_resume_attempt_v272 (
    self_review_id      TEXT    NOT NULL
        REFERENCES plan_self_review(id) ON DELETE CASCADE,
    semantic_attempt    INTEGER NOT NULL CHECK (semantic_attempt > 1),
    task_turn_id        TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    operation_id        TEXT    NOT NULL UNIQUE,
    predecessor_turn_id TEXT    NOT NULL REFERENCES task_turn(id),
    handoff_id          TEXT    NOT NULL UNIQUE
        REFERENCES stage_resume_rearm_intent_v257(handoff_id) ON DELETE CASCADE,
    requested_at_ms     INTEGER NOT NULL,
    PRIMARY KEY (self_review_id, semantic_attempt)
);
CREATE TABLE plan_self_review_failure_execution_v272 (
    self_review_id         TEXT    NOT NULL,
    infrastructure_attempt INTEGER NOT NULL CHECK (infrastructure_attempt = 2),
    execution_attempt      INTEGER NOT NULL CHECK (execution_attempt > 1),
    requested_at_ms        INTEGER NOT NULL,
    PRIMARY KEY (self_review_id, infrastructure_attempt),
    UNIQUE (self_review_id, execution_attempt),
    FOREIGN KEY (self_review_id, infrastructure_attempt)
        REFERENCES plan_self_review_attempt(self_review_id, attempt)
        ON DELETE CASCADE
);
CREATE VIEW plan_self_review_all_attempt_v265 AS
SELECT attempt.self_review_id,
       CASE WHEN attempt.attempt = 1 THEN 1 ELSE execution.execution_attempt END
           AS semantic_attempt,
       attempt.task_turn_id, attempt.operation_id, attempt.predecessor_turn_id
FROM plan_self_review_attempt attempt
LEFT JOIN plan_self_review_failure_execution_v272 execution
  ON execution.self_review_id = attempt.self_review_id
 AND execution.infrastructure_attempt = attempt.attempt
UNION ALL
SELECT self_review_id, semantic_attempt, task_turn_id,
       operation_id, predecessor_turn_id
FROM plan_self_review_user_wait_attempt_v265
UNION ALL
SELECT self_review_id, semantic_attempt, task_turn_id,
       operation_id, predecessor_turn_id
FROM plan_self_review_resume_attempt_v272;
CREATE VIEW task_live_work_counts_v230 AS
SELECT task.id AS task_id,
       task.epoch AS task_epoch,
       (SELECT COUNT(*) FROM task_turn turn
        WHERE turn.task_id = task.id AND turn.task_epoch = task.epoch
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_task_turn_count,
       (SELECT COUNT(*) FROM stage_turn turn
        JOIN stage owner ON owner.id = turn.stage_id
        WHERE owner.task_id = task.id AND turn.task_epoch = task.epoch
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_stage_turn_count,
       (SELECT COUNT(*)
        FROM review_assignment_turn turn
        JOIN review_assignment assignment ON assignment.id = turn.assignment_id
        JOIN review_round round ON round.id = assignment.round_id
        JOIN review_session session ON session.id = round.session_id
        JOIN pr pull_request ON pull_request.id = session.pr_id
        WHERE pull_request.origin = 'task' AND pull_request.task_id = task.id
          AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
           AS active_review_turn_count,
       (SELECT COUNT(*) FROM plan_self_review review
        JOIN plan_revision revision ON revision.id = review.plan_revision_id
        JOIN plan_stage owner ON owner.stage_id = revision.plan_stage_id
        WHERE owner.task_id = task.id AND review.task_epoch = task.epoch
          AND review.status = 'REQUESTED'
          AND EXISTS (
              SELECT 1
              FROM plan_self_review_all_attempt_v265 attempt
              JOIN task_turn turn ON turn.id = attempt.task_turn_id
              WHERE attempt.self_review_id = review.id
                AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')))
           AS active_plan_review_count,
       (SELECT COUNT(*) FROM validation_operation operation
        WHERE operation.task_id = task.id AND operation.task_epoch = task.epoch
          AND operation.status IN ('REQUESTED', 'DISPATCHED'))
           AS active_validation_count,
       (SELECT COUNT(*) FROM brain_review_episode episode
        WHERE episode.task_id = task.id AND episode.task_epoch = task.epoch
          AND episode.status IN ('REQUESTED', 'REVIEWING'))
           AS active_brain_episode_count,
       (SELECT COUNT(*) FROM provision_task_operation operation
        WHERE operation.task_id = task.id AND operation.task_epoch = task.epoch
          AND operation.status IN ('REQUESTED', 'DISPATCHED'))
           AS active_provision_operation_count,
       (SELECT COUNT(*) FROM dispatch_ticket ticket
        WHERE ticket.task_id = task.id AND ticket.task_epoch = task.epoch
          AND ticket.status IN (
              'REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT', 'RESULT_PENDING',
              'CLAIMED', 'RUNNING', 'DELIVERING'))
           AS active_dispatch_count,
       (SELECT COUNT(*) FROM dispatch_ticket ticket
        WHERE ticket.task_id = task.id AND ticket.task_epoch = task.epoch
          AND ticket.writer_required = 1
          AND ticket.status IN (
              'REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT', 'RESULT_PENDING',
              'CLAIMED', 'RUNNING', 'DELIVERING'))
           AS active_writer_dispatch_count,
       (SELECT COUNT(*) FROM agent_execution execution
        JOIN dispatch_ticket ticket ON ticket.id = execution.ticket_id
        WHERE ticket.task_id = task.id AND ticket.task_epoch = task.epoch
          AND execution.status IN ('STARTING', 'RUNNING'))
           AS active_agent_execution_count,
       (SELECT COUNT(*) FROM agent_execution execution
        JOIN dispatch_ticket ticket ON ticket.id = execution.ticket_id
        WHERE ticket.task_id = task.id AND ticket.task_epoch = task.epoch
          AND execution.status = 'UNKNOWN') AS unreconciled_execution_count,
       (SELECT COUNT(*) FROM task_quiescence_barrier barrier
        WHERE barrier.task_id = task.id AND barrier.task_epoch = task.epoch
          AND barrier.status = 'REQUESTED') AS active_quiescence_count,
       (SELECT COUNT(*) FROM task_replan_request request
        WHERE request.task_id = task.id
          AND request.source_task_epoch = task.epoch
          AND request.status IN ('REQUESTED', 'QUIESCING'))
           AS active_replan_count,
       (SELECT COUNT(*) FROM local_feedback_batch batch
        WHERE batch.task_id = task.id AND batch.task_epoch = task.epoch
          AND batch.status IN ('BUILDING', 'FROZEN', 'QUEUED', 'DISPATCHED'))
           AS active_feedback_batch_count,
       (SELECT COUNT(*) FROM publish_operation operation
        WHERE operation.task_id = task.id AND operation.task_epoch = task.epoch
          AND operation.status IN ('REQUESTED', 'DISPATCHED'))
           AS active_publish_operation_count,
       (SELECT COUNT(*) FROM publish_operation operation
        WHERE operation.task_id = task.id AND operation.task_epoch = task.epoch
          AND operation.status = 'INDETERMINATE')
           AS unreconciled_publish_operation_count,
       (SELECT COUNT(*) FROM publish_effect_step step
        JOIN publish_operation operation ON operation.id = step.publish_operation_id
        WHERE operation.task_id = task.id AND operation.task_epoch = task.epoch
          AND step.status IN ('CLAIMED', 'INDETERMINATE'))
           AS active_publish_effect_count,
       (SELECT COUNT(*) FROM publish_authorization authorization
        WHERE authorization.task_id = task.id
          AND authorization.task_epoch = task.epoch
          AND authorization.revoked_at_ms IS NULL
          AND authorization.consumed_at_ms IS NULL)
           AS active_publish_authorization_count,
       (SELECT COUNT(*) FROM permission_request permission
        WHERE permission.state = 'OPEN'
          AND ((permission.turn_kind = 'TASK' AND EXISTS (
                    SELECT 1 FROM task_turn turn
                    WHERE turn.id = permission.turn_id
                      AND turn.task_id = task.id
                      AND turn.task_epoch = task.epoch))
            OR (permission.turn_kind = 'STAGE' AND EXISTS (
                    SELECT 1 FROM stage_turn turn
                    JOIN stage owner ON owner.id = turn.stage_id
                    WHERE turn.id = permission.turn_id
                      AND owner.task_id = task.id
                      AND turn.task_epoch = task.epoch))))
           AS open_permission_count,
       (SELECT COUNT(*) FROM task_terminal_intent intent
        WHERE intent.task_id = task.id AND intent.accepted = 1)
           AS accepted_terminal_intent_count,
       (SELECT COUNT(*) FROM stage cleanup
        WHERE cleanup.task_id = task.id AND cleanup.kind = 'CLEANUP'
          AND cleanup.completed_at_ms IS NULL) AS open_cleanup_stage_count
FROM tasks task
WHERE task.workflow_version = 'V2';
CREATE TABLE remote_readiness_assistance_v273 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    command_id                  TEXT    NOT NULL,
    operation_id                TEXT    NOT NULL UNIQUE,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_stage_id             TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    remote_pr_binding_id        TEXT    NOT NULL REFERENCES remote_pr_binding(id),
    remote_pr_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    readiness_evidence_id       TEXT    NOT NULL REFERENCES remote_readiness_evidence(id),
    automation_policy_id        TEXT    NOT NULL REFERENCES task_automation_policy(id),
    kind                        TEXT    NOT NULL CHECK (kind IN (
        'REQUEST_REVIEWER', 'POST_MAINTAINER_NUDGE')),
    external_target             TEXT    NOT NULL,
    payload                     TEXT    NOT NULL,
    payload_digest              TEXT    NOT NULL CHECK (length(payload_digest) = 64),
    idempotency_key             TEXT    NOT NULL UNIQUE,
    remote_repository_id        TEXT    NOT NULL,
    head_repository_id          TEXT    NOT NULL,
    remote_pr_number            INTEGER NOT NULL CHECK (remote_pr_number > 0),
    expected_head_sha           TEXT    NOT NULL,
    expected_base_sha           TEXT    NOT NULL,
    semantic_attempt            INTEGER NOT NULL DEFAULT 1 CHECK (semantic_attempt = 1),
    status                      TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE',
        'ABANDONED')),
    attempt_count               INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit               INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode                  TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner                 TEXT,
    claimed_at_ms               INTEGER,
    lease_until_ms              INTEGER,
    external_effect_id          TEXT,
    evidence                    TEXT,
    last_error                  TEXT,
    authorized_by               TEXT    NOT NULL,
    authorized_at_ms            INTEGER NOT NULL,
    completed_at_ms             INTEGER,
    UNIQUE (task_id, command_id),
    UNIQUE (id, task_id, task_epoch, remote_stage_id, stage_generation,
        expected_head_sha, expected_base_sha),
    CHECK (length(trim(command_id)) > 0
        AND length(trim(external_target)) > 0
        AND length(trim(payload)) > 0
        AND length(trim(remote_repository_id)) > 0
        AND length(trim(head_repository_id)) > 0
        AND length(trim(expected_head_sha)) > 0
        AND length(trim(expected_base_sha)) > 0
        AND length(trim(authorized_by)) > 0),
    CHECK ((kind = 'REQUEST_REVIEWER' AND lower(external_target) = lower(payload))
        OR (kind = 'POST_MAINTAINER_NUDGE'
            AND external_target = 'MAINTAINER')),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK (status <> 'CLAIMED' OR lease_until_ms > claimed_at_ms),
    CHECK (attempt_count <= attempt_limit),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE', 'ABANDONED'))
        = (completed_at_ms IS NOT NULL)),
    CHECK (status <> 'SUCCEEDED'
        OR (external_effect_id IS NOT NULL AND evidence IS NOT NULL))
);
CREATE INDEX idx_remote_readiness_assistance_subject_v273
    ON remote_readiness_assistance_v273(
        task_id, remote_stage_id, remote_pr_snapshot_id,
        automation_policy_id, status);
CREATE TABLE remote_readiness_assistance_dispatch_v273 (
    assistance_id      TEXT    NOT NULL PRIMARY KEY
        REFERENCES remote_readiness_assistance_v273(id) ON DELETE CASCADE,
    dispatch_ticket_id TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    operation_id       TEXT    NOT NULL UNIQUE,
    dispatched_at_ms   INTEGER NOT NULL
);
CREATE TABLE remote_readiness_assistance_receipt_v273 (
    operation_id      TEXT    NOT NULL PRIMARY KEY,
    raw_result_digest TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    acceptance        TEXT    NOT NULL CHECK (acceptance IN (
        'ACCEPTED', 'SUPERSEDED', 'REJECTED')),
    evidence          TEXT    NOT NULL,
    recorded_at_ms    INTEGER NOT NULL
);
CREATE TABLE manual_pr_validation_operation (
    id                        TEXT    NOT NULL PRIMARY KEY,
    command_id                TEXT    NOT NULL,
    pr_id                     TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    task_id                   TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                INTEGER NOT NULL CHECK (task_epoch > 0),
    worktree_path             TEXT    NOT NULL,
    code_fingerprint          TEXT    NOT NULL,
    expected_head_sha         TEXT    NOT NULL,
    expected_base_sha         TEXT    NOT NULL,
    status                    TEXT    NOT NULL
        CHECK (status IN ('REQUESTED', 'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    result_json               TEXT,
    error_message             TEXT,
    requested_at_ms           INTEGER NOT NULL,
    completed_at_ms           INTEGER,
    UNIQUE (task_id, command_id),
    CHECK (length(command_id) > 0 AND length(worktree_path) > 0),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK ((status = 'REQUESTED') = (result_json IS NULL))
);
CREATE TABLE plan_approval (
    id                  TEXT    NOT NULL PRIMARY KEY,
    plan_revision_id    TEXT    NOT NULL UNIQUE
        REFERENCES plan_revision(id) ON DELETE CASCADE,
    self_review_id      TEXT    NOT NULL UNIQUE REFERENCES plan_self_review(id),
    approval_kind       TEXT    NOT NULL CHECK (approval_kind IN (
        'HUMAN', 'POLICY', 'AUTOMATION')),
    policy_revision_id  TEXT    NOT NULL REFERENCES task_policy_revision(id),
    actor               TEXT    NOT NULL,
    approved_at_ms      INTEGER NOT NULL,
    CHECK (approval_kind <> 'AUTOMATION'
        OR (actor LIKE 'automation/%' AND length(actor) > 11))
);
CREATE INDEX idx_v2_user_remote_action_semantic_v282
    ON v2_user_remote_action_v270(
        task_id, semantic_action, payload_digest, status);
CREATE TABLE remote_worktree_subject (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    revision                    INTEGER NOT NULL CHECK (revision > 0),
    source_kind                 TEXT    NOT NULL CHECK (source_kind IN (
        'CI_STAGE_TURN', 'BRANCH_EFFECT', 'BRANCH_STAGE_TURN',
        'USER_CI_TRIGGER')),
    source_operation_id         TEXT    NOT NULL UNIQUE,
    code_fingerprint            TEXT    NOT NULL,
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    recorded_at_ms              INTEGER NOT NULL,
    UNIQUE (task_id, task_epoch, revision)
);
CREATE TABLE "trunk_task_creation_authorization" (
    id                         TEXT    NOT NULL PRIMARY KEY,
    trunk_id                   TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    workspace_id               TEXT    NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    command_id                 TEXT    NOT NULL,
    actor                      TEXT    NOT NULL,
    disposition                TEXT    NOT NULL CHECK (disposition = 'AUTHORIZED'),
    expected_trunk_version     INTEGER NOT NULL CHECK (expected_trunk_version >= 0),
    returned_trunk_version     INTEGER NOT NULL CHECK (returned_trunk_version > 0),
    returned_lifecycle         TEXT    NOT NULL CHECK (returned_lifecycle IN ('ACTIVE', 'IDLE')),
    assignment_id              TEXT    NOT NULL UNIQUE
        REFERENCES task_assignment(id) DEFERRABLE INITIALLY DEFERRED,
    policy_revision_id         TEXT    NOT NULL REFERENCES task_policy_revision(id),
    provenance                 TEXT    NOT NULL CHECK (provenance IN (
        'AGENT_HANDOFF', 'DIRECT_USER', 'ISSUE_MONITOR', 'AUTOMATION',
        'QUALITY_SCAN', 'REVIEW_SESSION')),
    repository_id              TEXT    NOT NULL,
    upstream_repository_id     TEXT,
    publish_repository_id      TEXT    NOT NULL,
    base_source                TEXT    NOT NULL CHECK (base_source IN (
        'PLANNING_SNAPSHOT', 'FRESH_REMOTE_BASE', 'EXISTING_PR_HEAD')),
    base_repository_id         TEXT    NOT NULL,
    base_ref                   TEXT,
    planning_base_sha          TEXT,
    assignment_base_sha        TEXT,
    assignment_head_sha        TEXT,
    engine_snapshot            TEXT    NOT NULL,
    work_model_snapshot        TEXT    NOT NULL,
    recorded_at_ms             INTEGER NOT NULL,
    task_name                  TEXT,
    task_type                  TEXT,
    linked_issue_number        INTEGER,
    opening_prompt             TEXT,
    task_origin                TEXT,
    UNIQUE (trunk_id, command_id),
    CHECK (returned_trunk_version = expected_trunk_version + 1),
    CHECK (length(actor) > 0 AND length(base_repository_id) > 0
        AND length(engine_snapshot) > 0 AND length(work_model_snapshot) > 0),
    CHECK ((base_source = 'PLANNING_SNAPSHOT'
            AND length(base_ref) > 0 AND planning_base_sha IS NOT NULL
            AND assignment_base_sha IS NULL AND assignment_head_sha IS NULL)
        OR (base_source = 'FRESH_REMOTE_BASE'
            AND length(base_ref) > 0 AND planning_base_sha IS NULL
            AND assignment_base_sha IS NULL AND assignment_head_sha IS NULL)
        OR (base_source = 'EXISTING_PR_HEAD'
            AND planning_base_sha IS NULL
            AND ((base_ref IS NULL AND assignment_base_sha IS NULL
                    AND assignment_head_sha IS NULL)
              OR (length(base_ref) > 0 AND assignment_base_sha IS NOT NULL
                    AND assignment_head_sha IS NOT NULL))))
);
CREATE TABLE "task_creation_context" (
    task_id                   TEXT    NOT NULL PRIMARY KEY
        REFERENCES tasks(id) ON DELETE CASCADE,
    assignment_id             TEXT    NOT NULL REFERENCES task_assignment(id),
    policy_revision_id        TEXT    NOT NULL REFERENCES task_policy_revision(id),
    authorization_id          TEXT UNIQUE
        REFERENCES trunk_task_creation_authorization(id),
    provenance                TEXT    NOT NULL CHECK (provenance IN (
        'AGENT_HANDOFF', 'DIRECT_USER', 'ISSUE_MONITOR', 'AUTOMATION',
        'QUALITY_SCAN', 'REVIEW_SESSION')),
    repository_id             TEXT    NOT NULL,
    upstream_repository_id    TEXT,
    publish_repository_id     TEXT    NOT NULL,
    base_source               TEXT CHECK (base_source IN (
        'PLANNING_SNAPSHOT', 'FRESH_REMOTE_BASE', 'EXISTING_PR_HEAD')),
    base_repository_id        TEXT,
    base_ref                  TEXT,
    planning_base_sha         TEXT,
    assignment_base_sha       TEXT,
    assignment_head_sha       TEXT,
    engine_snapshot           TEXT    NOT NULL,
    work_model_snapshot       TEXT    NOT NULL,
    created_at_ms             INTEGER NOT NULL,
    task_name                 TEXT,
    task_type                 TEXT,
    linked_issue_number       INTEGER,
    opening_prompt            TEXT,
    task_origin               TEXT,
    CHECK (base_source IS NULL OR (length(base_repository_id) > 0
        AND ((base_source = 'PLANNING_SNAPSHOT'
                AND length(base_ref) > 0 AND planning_base_sha IS NOT NULL
                AND assignment_base_sha IS NULL
                AND assignment_head_sha IS NULL)
            OR (base_source = 'FRESH_REMOTE_BASE'
                AND length(base_ref) > 0 AND planning_base_sha IS NULL
                AND assignment_base_sha IS NULL
                AND assignment_head_sha IS NULL)
            OR (base_source = 'EXISTING_PR_HEAD'
                AND planning_base_sha IS NULL
                AND ((base_ref IS NULL AND assignment_base_sha IS NULL
                        AND assignment_head_sha IS NULL)
                  OR (length(base_ref) > 0 AND assignment_base_sha IS NOT NULL
                        AND assignment_head_sha IS NOT NULL))))))
);
CREATE TABLE v2_quality_issue_publish_v285 (
    id                       TEXT    NOT NULL PRIMARY KEY,
    operation_id             TEXT    NOT NULL UNIQUE,
    notification_id          TEXT    NOT NULL UNIQUE
        REFERENCES notifications(id) ON DELETE CASCADE,
    task_id                  TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch               INTEGER NOT NULL CHECK (task_epoch > 0),
    workspace_id             TEXT    NOT NULL REFERENCES workspaces(id),
    trunk_id                 TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    repo_owner               TEXT    NOT NULL,
    repo_name                TEXT    NOT NULL,
    issue_title              TEXT    NOT NULL,
    issue_body               TEXT    NOT NULL,
    idempotency_marker       TEXT    NOT NULL UNIQUE,
    payload_digest           TEXT    NOT NULL CHECK (length(payload_digest) = 64),
    status                   TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'EXECUTING', 'SUCCEEDED', 'INDETERMINATE',
        'FAILED', 'CANCELED', 'DELIVERED')),
    external_issue_id        INTEGER,
    external_issue_number    INTEGER,
    external_issue_url       TEXT,
    result_json              TEXT,
    last_error               TEXT,
    authorized_at_ms         INTEGER NOT NULL,
    effect_started_at_ms     INTEGER,
    effect_completed_at_ms   INTEGER,
    delivered_at_ms          INTEGER,
    CHECK (length(trim(repo_owner)) > 0
        AND length(trim(repo_name)) > 0
        AND length(trim(issue_title)) > 0
        AND length(trim(issue_body)) > 0
        AND length(trim(idempotency_marker)) > 0),
    CHECK ((status IN ('SUCCEEDED', 'DELIVERED')) =
        (external_issue_id IS NOT NULL
          AND external_issue_number IS NOT NULL
          AND external_issue_number > 0
          AND external_issue_url IS NOT NULL)),
    CHECK (status <> 'EXECUTING' OR effect_started_at_ms IS NOT NULL),
    CHECK (status NOT IN ('SUCCEEDED', 'INDETERMINATE', 'FAILED', 'DELIVERED')
        OR effect_completed_at_ms IS NOT NULL),
    CHECK (status <> 'DELIVERED' OR delivered_at_ms IS NOT NULL),
    CHECK (delivered_at_ms IS NULL OR result_json IS NOT NULL),
    CHECK (delivered_at_ms IS NULL
        OR status IN ('DELIVERED', 'FAILED', 'CANCELED')),
    UNIQUE (id, task_id, task_epoch)
);
CREATE INDEX idx_v2_quality_issue_publish_status_v285
    ON v2_quality_issue_publish_v285(status, authorized_at_ms);
CREATE TABLE v2_quality_issue_publish_dispatch_v285 (
