        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    operation_id        TEXT NOT NULL UNIQUE,
    dispatched_at_ms    INTEGER NOT NULL CHECK (dispatched_at_ms >= 0)
);
CREATE TABLE external_pr_action_v289 (
    id                    TEXT    NOT NULL PRIMARY KEY,
    operation_id          TEXT    NOT NULL UNIQUE,
    thread_id             TEXT    NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    workspace_id          TEXT    NOT NULL REFERENCES workspaces(id),
    command_id            TEXT    NOT NULL,
    pr_id                 TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    review_id             TEXT    REFERENCES review_session(id) ON DELETE RESTRICT,
    kind                  TEXT    NOT NULL CHECK (kind IN (
        'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
        'SUBMIT_REVIEW')),
    semantic_action       TEXT    NOT NULL CHECK (semantic_action IN (
        'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
        'SUBMIT_REVIEW', 'RERUN_FAILED_CHECKS', 'SET_DRAFT_STATE',
        'UPDATE_TITLE', 'UPDATE_BODY', 'CLOSE_PULL_REQUEST',
        'COMMENT_AND_CLOSE', 'REPLY_REVIEW_THREAD', 'EDIT_ISSUE_COMMENT',
        'EDIT_REVIEW_COMMENT', 'DELETE_ISSUE_COMMENT',
        'DELETE_REVIEW_COMMENT', 'ADD_REVIEWER', 'REMOVE_REVIEWER',
        'SET_ASSIGNEE', 'SET_LABEL', 'CREATE_INLINE_COMMENT',
        'REACT_PULL_REQUEST', 'REACT_REVIEW_COMMENT',
        'REACT_ISSUE_COMMENT', 'SET_THREAD_RESOLUTION', 'MERGE',
        'ENABLE_AUTO_MERGE', 'DISABLE_AUTO_MERGE')),
    remote_repository_id  TEXT    NOT NULL,
    head_repository_id    TEXT    NOT NULL,
    remote_pr_number      INTEGER NOT NULL CHECK (remote_pr_number > 0),
    branch_name           TEXT    NOT NULL,
    expected_head_sha     TEXT    NOT NULL,
    expected_base_sha     TEXT    NOT NULL,
    payload_json          TEXT    NOT NULL CHECK (json_valid(payload_json)),
    payload_digest        TEXT    NOT NULL CHECK (length(payload_digest) = 64),
    handled_action        TEXT CHECK (handled_action IN (
        'APPROVED', 'CHANGES_REQUESTED', 'COMMENTED')),
    semantic_attempt      INTEGER NOT NULL DEFAULT 1 CHECK (semantic_attempt = 1),
    status                TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE',
        'CANCELED', 'ABANDONED')),
    attempt_count         INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    attempt_limit         INTEGER NOT NULL CHECK (attempt_limit > 0),
    claim_mode            TEXT CHECK (claim_mode IN ('EXECUTE', 'PROBE')),
    claim_owner           TEXT,
    claimed_at_ms         INTEGER,
    lease_until_ms        INTEGER,
    external_effect_id    TEXT,
    evidence              TEXT,
    last_error            TEXT,
    recovery_baseline_json TEXT,
    authorized_at_ms      INTEGER NOT NULL CHECK (authorized_at_ms >= 0),
    completed_at_ms       INTEGER,
    finalized_at_ms       INTEGER,
    CHECK (length(trim(command_id)) > 0
        AND length(trim(remote_repository_id)) > 0
        AND length(trim(head_repository_id)) > 0
        AND length(trim(branch_name)) > 0
        AND length(trim(expected_head_sha)) > 0
        AND length(trim(expected_base_sha)) > 0),
    CHECK ((semantic_action IN (
            'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
            'SUBMIT_REVIEW') AND kind = semantic_action)
        OR (semantic_action NOT IN (
            'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
            'SUBMIT_REVIEW') AND kind = 'DEQUEUE')),
    CHECK ((status = 'CLAIMED') = (claim_mode IS NOT NULL
        AND claim_owner IS NOT NULL AND claimed_at_ms IS NOT NULL
        AND lease_until_ms IS NOT NULL)),
    CHECK ((status = 'SUCCEEDED') = (external_effect_id IS NOT NULL
        AND evidence IS NOT NULL AND completed_at_ms IS NOT NULL)),
    CHECK (status NOT IN ('CANCELED', 'ABANDONED')
        OR completed_at_ms IS NOT NULL),
    CHECK ((status IN ('SUCCEEDED', 'CANCELED', 'ABANDONED'))
        OR finalized_at_ms IS NULL),
    CHECK (finalized_at_ms IS NULL OR completed_at_ms IS NOT NULL),
    CHECK (attempt_count <= attempt_limit),
    UNIQUE (thread_id, command_id)
);
CREATE INDEX idx_external_pr_action_pr_v289
    ON external_pr_action_v289(pr_id, authorized_at_ms DESC);
CREATE INDEX idx_external_pr_action_finalize_v289
    ON external_pr_action_v289(status, finalized_at_ms);
CREATE TABLE external_pr_action_draft_v289 (
    action_id       TEXT    NOT NULL
        REFERENCES external_pr_action_v289(id) ON DELETE CASCADE,
    position        INTEGER NOT NULL CHECK (position > 0),
    comment_id      TEXT    NOT NULL REFERENCES pr_comment(id),
    scope           TEXT    NOT NULL CHECK (scope IN ('pr', 'file-line')),
    file_path       TEXT,
    line_number     INTEGER,
    side            TEXT,
    start_line      INTEGER,
    start_side      TEXT,
    body            TEXT    NOT NULL,
    finding_id      TEXT,
    PRIMARY KEY (action_id, position),
    UNIQUE (action_id, comment_id),
    CHECK ((scope = 'pr' AND file_path IS NULL AND line_number IS NULL)
        OR (scope = 'file-line' AND file_path IS NOT NULL
            AND line_number IS NOT NULL AND side IS NOT NULL))
);
CREATE TABLE external_pr_action_dispatch_v289 (
    action_id          TEXT NOT NULL PRIMARY KEY
        REFERENCES external_pr_action_v289(id) ON DELETE CASCADE,
    dispatch_ticket_id TEXT NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) ON DELETE CASCADE,
    operation_id       TEXT NOT NULL UNIQUE,
    dispatched_at_ms   INTEGER NOT NULL CHECK (dispatched_at_ms >= 0)
);
CREATE TABLE review_round_snapshot_v291 (
    round_id           TEXT    NOT NULL PRIMARY KEY
        REFERENCES review_round(id) ON DELETE CASCADE,
    repository         TEXT,
    remote_pr_number   INTEGER,
    base_branch        TEXT    NOT NULL,
    pr_title           TEXT    NOT NULL,
    pr_description     TEXT    NOT NULL,
    base_commit        TEXT    NOT NULL,
    head_commit        TEXT    NOT NULL,
    diff               TEXT    NOT NULL,
    files_json         TEXT    NOT NULL CHECK (json_valid(files_json)),
    file_contents_json TEXT    NOT NULL
        CHECK (json_valid(file_contents_json)
            AND json_type(file_contents_json) = 'object'),
    local_root         TEXT,
    repository_root    TEXT,
    capabilities_json  TEXT    NOT NULL CHECK (json_valid(capabilities_json)),
    created_at_ms      INTEGER NOT NULL,
    CHECK (length(trim(base_commit)) > 0
        AND length(trim(head_commit)) > 0),
    CHECK (length(trim(base_branch)) > 0),
    CHECK ((repository IS NULL) = (remote_pr_number IS NULL)),
    CHECK (repository IS NULL OR length(trim(repository)) > 0),
    CHECK (remote_pr_number IS NULL OR remote_pr_number > 0),
    CHECK (local_root IS NULL OR length(trim(local_root)) > 0),
    CHECK (repository_root IS NULL OR length(trim(repository_root)) > 0)
);
CREATE TABLE "dispatch_ticket" (
    id                         TEXT    NOT NULL PRIMARY KEY,
    version                    INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    operation_id               TEXT    NOT NULL UNIQUE,
    operation_kind             TEXT    NOT NULL,
    async_family               TEXT    NOT NULL CHECK (async_family IN (
        'AGENT_TURN', 'VALIDATION', 'LOCAL_GIT', 'GITHUB_EFFECT',
        'REMOTE_OBSERVATION', 'MERGE', 'CLEANUP')),
    owner_kind                 TEXT    NOT NULL CHECK (owner_kind IN (
        'TRUNK', 'TASK', 'STAGE', 'THREAD_TURN', 'TASK_TURN',
        'STAGE_TURN', 'REVIEW_ASSIGNMENT_TURN', 'REVIEW_SESSION')),
    owner_id                   TEXT    NOT NULL,
    callback_route             TEXT    NOT NULL,
    -- CLI=1, API=2, VALIDATION=4, REVIEW=8, LOCAL_GIT=16, GITHUB=32,
    -- REMOTE_OBSERVATION=64, MERGE=128, CLEANUP=256. A bitmask keeps the
    -- required non-empty lane set atomic with the ticket row.
    lane_mask                  INTEGER NOT NULL CHECK (lane_mask BETWEEN 1 AND 511),
    trunk_control              INTEGER NOT NULL DEFAULT 0 CHECK (trunk_control IN (0, 1)),
    exclusive_task             INTEGER NOT NULL DEFAULT 0 CHECK (exclusive_task IN (0, 1)),
    writer_required            INTEGER NOT NULL DEFAULT 0 CHECK (writer_required IN (0, 1)),
    workspace_id               TEXT    REFERENCES workspaces(id),
    trunk_id                   TEXT    REFERENCES threads(id) ON DELETE CASCADE,
    task_id                    TEXT    REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                 INTEGER,
    stage_id                   TEXT    REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation           INTEGER,
    attempt                    INTEGER NOT NULL CHECK (attempt > 0),
    expected_code_fingerprint  TEXT,
    expected_head_sha          TEXT,
    expected_base_sha          TEXT,
    status                     TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT', 'RESULT_PENDING',
        'CLAIMED', 'RUNNING', 'DELIVERING', 'SUCCEEDED', 'FAILED', 'CANCELED')),
    claim_purpose              TEXT CHECK (claim_purpose IN ('EXECUTE', 'RECONCILE', 'DELIVER')),
    claim_owner                TEXT,
    capacity_lease_id          TEXT,
    claim_expires_at_ms        INTEGER,
    next_attempt_at_ms         INTEGER,
    cancel_requested_at_ms     INTEGER,
    infrastructure_attempts    INTEGER NOT NULL DEFAULT 0 CHECK (infrastructure_attempts >= 0),
    started_at_ms              INTEGER,
    pending_result_outcome     TEXT CHECK (pending_result_outcome IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'INDETERMINATE')),
    pending_result_payload     TEXT,
    pending_result_evidence    TEXT,
    pending_result_error       TEXT,
    delivery_acceptance        TEXT CHECK (delivery_acceptance IN (
        'ACCEPTED', 'SUPERSEDED', 'REJECTED')),
    delivery_evidence          TEXT,
    created_at_ms              INTEGER NOT NULL,
    completed_at_ms            INTEGER,
    last_error                 TEXT, pending_result_task_epoch INTEGER, pending_result_stage_id TEXT, pending_result_stage_generation INTEGER, pending_result_operation_id TEXT, pending_result_attempt INTEGER, pending_result_expected_code_fingerprint TEXT, pending_result_expected_head_sha TEXT, pending_result_expected_base_sha TEXT,
    CHECK ((stage_id IS NULL AND stage_generation IS NULL)
        OR (stage_id IS NOT NULL AND stage_generation IS NOT NULL)),
    CHECK ((task_id IS NULL AND task_epoch IS NULL)
        OR (task_id IS NOT NULL AND task_epoch IS NOT NULL)),
    CHECK (trunk_control = 0 OR task_id IS NULL),
    CHECK (exclusive_task = 0 OR task_id IS NOT NULL),
    CHECK (writer_required = 0 OR exclusive_task = 1),
    CHECK ((status IN ('CLAIMED', 'RUNNING', 'DELIVERING'))
        = (claim_purpose IS NOT NULL AND claim_owner IS NOT NULL
            AND capacity_lease_id IS NOT NULL AND claim_expires_at_ms IS NOT NULL)),
    CHECK ((status IN ('RESULT_PENDING', 'DELIVERING')
            OR (status = 'CLAIMED' AND claim_purpose = 'DELIVER'))
        = (pending_result_outcome IS NOT NULL)),
    CHECK ((status IN ('SUCCEEDED', 'FAILED', 'CANCELED'))
        = (completed_at_ms IS NOT NULL AND delivery_acceptance IS NOT NULL))
);
CREATE TRIGGER agent_run_insert_retired_v290
BEFORE INSERT ON agent_run
WHEN NOT (
    NEW.task_id IS NULL
    AND NEW.kind = 'review_compatibility_header'
    AND NEW.source = 'v2_review_assignment_turn_fk'
    AND NEW.parent_stage_id IS NULL
    AND NEW.review_round_id IS NOT NULL
    AND length(trim(NEW.review_round_id)) > 0
    AND NEW.stage_id IS NULL
    AND NEW.status = 'succeeded'
    AND NEW.iterations = 0
    AND (NEW.budget IS NULL OR NEW.budget >= 0)
    AND NEW.headline IS NULL
    AND NEW.metrics_json IS NULL
    AND NEW.finished_at_ms = NEW.started_at_ms
    AND NEW.workspace_id IS NULL
    AND NEW.thread_id IS NULL
    AND NEW.provider IS NULL
    AND NEW.model IS NULL
    AND NEW.cost_usd_milli = 0
    AND NEW.tokens_in = 0
    AND NEW.tokens_out = 0
    AND NEW.step_cursor = 0
    AND NEW.launch_input IS NULL
    AND NEW.pause_reason IS NULL
    AND NEW.outcome = 'completed'
)
BEGIN SELECT RAISE(ABORT,
    'AgentRun creation is retired; only an inert review compatibility header is allowed'); END;
CREATE TRIGGER agent_run_update_retired_v290
BEFORE UPDATE ON agent_run
BEGIN SELECT RAISE(ABORT, 'AgentRun rows are immutable after V2 cutover'); END;
CREATE TRIGGER backlog_item_origin_immutable
BEFORE UPDATE OF origin ON backlog_item
WHEN NEW.origin <> OLD.origin
BEGIN
    SELECT RAISE(ABORT, 'backlog item origin is immutable');
END;
CREATE TRIGGER brain_review_episode_identity_immutable
BEFORE UPDATE OF task_brain_id, task_id, task_epoch,
        local_development_stage_id, stage_generation, dev_report_id,
        validation_evidence_id, task_turn_id, semantic_attempt,
        code_fingerprint, expected_head_sha, expected_base_sha, requested_at_ms
ON brain_review_episode
WHEN NEW.task_brain_id IS NOT OLD.task_brain_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.dev_report_id IS NOT OLD.dev_report_id
  OR NEW.validation_evidence_id IS NOT OLD.validation_evidence_id
  OR NEW.task_turn_id IS NOT OLD.task_turn_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'BrainReviewEpisode fence is immutable'); END;
CREATE TRIGGER brain_review_episode_owner_insert
BEFORE INSERT ON brain_review_episode
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'BrainReviewEpisode must start REQUESTED')
        WHEN NOT EXISTS (
            SELECT 1
            FROM task_brain b
            JOIN tasks t ON t.id = b.task_id
            JOIN local_development_stage l ON l.task_id = t.id
            JOIN stage s ON s.id = l.stage_id
            JOIN task_current_stage c ON c.stage_id = l.stage_id
            JOIN dev_report r ON r.id = NEW.dev_report_id
            JOIN validation_evidence v ON v.id = NEW.validation_evidence_id
            JOIN task_turn tt ON tt.id = NEW.task_turn_id
            WHERE b.id = NEW.task_brain_id
              AND b.task_id = NEW.task_id
              AND t.workflow_version = 'V2'
              AND t.lifecycle_state = 'ACTIVE'
              AND t.epoch = NEW.task_epoch
              AND l.stage_id = NEW.local_development_stage_id
              AND l.generation = NEW.stage_generation
              AND l.opened_for_epoch = NEW.task_epoch
              AND s.completed_at_ms IS NULL
              AND c.task_id = NEW.task_id
              AND c.stage_generation = NEW.stage_generation
              AND r.local_development_stage_id = l.stage_id
              AND r.task_id = NEW.task_id
              AND r.task_epoch = NEW.task_epoch
              AND r.stage_generation = NEW.stage_generation
              AND r.code_fingerprint = NEW.code_fingerprint
              AND r.head_sha = NEW.expected_head_sha
              AND r.base_sha = NEW.expected_base_sha
              AND v.validation_operation_id IN (
                  SELECT o.id FROM validation_operation o
                  WHERE o.dev_report_id = r.id AND o.status = 'COMPLETED')
              AND v.passed = 1
              AND v.code_fingerprint = NEW.code_fingerprint
              AND v.head_sha = NEW.expected_head_sha
              AND v.base_sha = NEW.expected_base_sha
              AND tt.task_id = NEW.task_id
              AND tt.task_epoch = NEW.task_epoch
              AND tt.trigger_stage_id = l.stage_id
              AND tt.trigger_stage_generation = l.generation
              AND tt.expected_code_fingerprint = NEW.code_fingerprint
              AND tt.expected_head_sha = NEW.expected_head_sha
              AND tt.expected_base_sha = NEW.expected_base_sha
              AND tt.purpose = 'DEVELOPMENT_BRAIN_REVIEW'
              AND tt.status IN ('REQUESTED', 'QUEUED'))
            THEN RAISE(ABORT, 'BrainReviewEpisode requires exact green validation and TaskTurn')
    END;
END;
CREATE TRIGGER brain_review_episode_result_fence
BEFORE UPDATE OF status ON brain_review_episode
WHEN NEW.status = 'SUCCEEDED'
  AND NOT EXISTS (
      SELECT 1
      FROM task_turn tt
      JOIN tasks t ON t.id = NEW.task_id
      JOIN stage s ON s.id = NEW.local_development_stage_id
      JOIN task_current_stage c ON c.stage_id = s.id
      WHERE tt.id = NEW.task_turn_id
        AND tt.task_id = NEW.task_id
        AND tt.task_epoch = NEW.task_epoch
        AND tt.status = 'SUCCEEDED'
        AND tt.expected_code_fingerprint = NEW.code_fingerprint
        AND tt.expected_head_sha = NEW.expected_head_sha
        AND tt.expected_base_sha = NEW.expected_base_sha
        AND t.epoch = NEW.task_epoch
        AND t.lifecycle_state = 'ACTIVE'
        AND s.task_id = NEW.task_id
        AND s.generation = NEW.stage_generation
        AND s.completed_at_ms IS NULL
        AND c.task_id = NEW.task_id
        AND c.stage_generation = NEW.stage_generation
        AND NOT EXISTS (
            SELECT 1 FROM dev_report newer
            JOIN dev_report current ON current.id = NEW.dev_report_id
            WHERE newer.local_development_stage_id = current.local_development_stage_id
              AND newer.revision > current.revision))
BEGIN SELECT RAISE(ABORT, 'BrainReviewEpisode result is stale'); END;
CREATE TRIGGER brain_review_episode_terminal_immutable
BEFORE UPDATE ON brain_review_episode
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED',
    'SUPERSEDED', 'BUDGET_EXHAUSTED')
BEGIN SELECT RAISE(ABORT, 'terminal BrainReviewEpisode is immutable'); END;
CREATE TRIGGER brain_review_episode_transition
BEFORE UPDATE OF status ON brain_review_episode
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'REVIEWING', 'SUCCEEDED', 'FAILED', 'CANCELED',
        'SUPERSEDED', 'BUDGET_EXHAUSTED'))
    OR (OLD.status = 'REVIEWING' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED',
        'SUPERSEDED', 'BUDGET_EXHAUSTED')))
BEGIN SELECT RAISE(ABORT, 'illegal BrainReviewEpisode transition'); END;
CREATE TRIGGER branch_sync_brain_verdict_immutable
BEFORE UPDATE ON branch_sync_brain_verdict
BEGIN SELECT RAISE(ABORT, 'Branch Brain verdict is immutable'); END;
CREATE TRIGGER branch_sync_brain_verdict_insert
BEFORE INSERT ON branch_sync_brain_verdict
WHEN NOT EXISTS (
    SELECT 1 FROM branch_sync_dispatch_operation operation
    WHERE operation.id = NEW.branch_sync_dispatch_operation_id
      AND operation.kind = 'BRAIN_REVIEW'
      AND operation.task_turn_id = NEW.task_turn_id
      AND operation.status = 'SUCCEEDED')
BEGIN SELECT RAISE(ABORT, 'Branch Brain verdict lacks its successful exact TaskTurn'); END;
CREATE TRIGGER branch_sync_delivery_receipt_immutable
BEFORE UPDATE ON branch_sync_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Branch sync delivery receipt is immutable'); END;
CREATE TRIGGER branch_sync_delivery_receipt_insert
BEFORE INSERT ON branch_sync_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM branch_sync_dispatch_operation operation
    JOIN dispatch_ticket ticket ON ticket.operation_id = operation.operation_id
    WHERE operation.id = NEW.branch_sync_dispatch_operation_id
      AND operation.operation_id = NEW.operation_id
      AND operation.status IN (
          'SUCCEEDED', 'FAILED', 'INDETERMINATE', 'CANCELED', 'SUPERSEDED')
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = NEW.raw_outcome)
BEGIN SELECT RAISE(ABORT, 'Branch sync delivery receipt is not exact'); END;
CREATE TRIGGER branch_sync_dispatch_operation_dispatched
BEFORE UPDATE OF status ON branch_sync_dispatch_operation
WHEN NEW.status = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1 FROM dispatch_ticket ticket
    WHERE ticket.operation_id = NEW.operation_id
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Branch sync dispatch lacks its DispatchTicket'); END;
CREATE TRIGGER branch_sync_dispatch_operation_identity_immutable
BEFORE UPDATE OF id, branch_sync_episode_id, branch_sync_effect_step_id,
        remote_development_stage_id, task_id, task_epoch, stage_generation,
        kind, operation_id, semantic_attempt, stage_turn_id, task_turn_id,
        expected_code_fingerprint, expected_head_sha, expected_base_sha,
        target_base_sha, requested_at_ms ON branch_sync_dispatch_operation
BEGIN SELECT RAISE(ABORT, 'Branch sync dispatch identity is immutable'); END;
CREATE TRIGGER branch_sync_dispatch_operation_insert
BEFORE INSERT ON branch_sync_dispatch_operation
WHEN NOT EXISTS (
    SELECT 1
    FROM branch_sync_episode episode
    JOIN branch_sync_effect_step step
      ON step.branch_sync_episode_id = episode.id
    JOIN remote_development_stage remote
      ON remote.stage_id = episode.remote_development_stage_id
    JOIN tasks task ON task.id = episode.task_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE episode.id = NEW.branch_sync_episode_id
      AND step.id = NEW.branch_sync_effect_step_id
      AND step.kind = NEW.kind
      AND step.status = 'REQUESTED'
      AND episode.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND episode.task_id = NEW.task_id
      AND episode.task_epoch = NEW.task_epoch
      AND episode.stage_generation = NEW.stage_generation
      AND episode.target_base_sha = NEW.target_base_sha
      AND episode.status NOT IN ('SUCCEEDED', 'FAILED', 'STOPPED')
      AND remote.current_head_sha = episode.old_head_sha
      AND remote.current_base_sha = episode.observed_base_sha
      AND NEW.expected_head_sha = code.head_sha
      AND NEW.expected_base_sha = code.base_sha
      AND (NEW.expected_code_fingerprint IS NULL
          OR NEW.expected_code_fingerprint = code.code_fingerprint)
      AND task.epoch = NEW.task_epoch
      AND task.lifecycle_state = 'ACTIVE'
      AND NEW.status = 'REQUESTED'
      AND (NEW.kind <> 'CONFLICT_REPAIR' OR EXISTS (
          SELECT 1 FROM stage_turn turn
          WHERE turn.id = NEW.stage_turn_id
            AND turn.operation_id = NEW.operation_id
            AND turn.stage_id = NEW.remote_development_stage_id
            AND turn.stage_generation = NEW.stage_generation
            AND turn.task_epoch = NEW.task_epoch
            AND turn.attempt = NEW.semantic_attempt
            AND turn.expected_code_fingerprint =
                NEW.expected_code_fingerprint
            AND turn.expected_head_sha = NEW.expected_head_sha
            AND turn.expected_base_sha = NEW.expected_base_sha
            AND turn.purpose = 'BRANCH_CONFLICT_REPAIR'
            AND turn.status = 'QUEUED'))
      AND (NEW.kind <> 'BRAIN_REVIEW' OR EXISTS (
          SELECT 1 FROM task_turn turn
          WHERE turn.id = NEW.task_turn_id
            AND turn.operation_id = NEW.operation_id
            AND turn.task_id = NEW.task_id
            AND turn.task_epoch = NEW.task_epoch
            AND turn.trigger_stage_id = NEW.remote_development_stage_id
            AND turn.trigger_stage_generation = NEW.stage_generation
            AND turn.attempt = NEW.semantic_attempt
            AND turn.expected_code_fingerprint =
                NEW.expected_code_fingerprint
            AND turn.expected_head_sha = NEW.expected_head_sha
            AND turn.expected_base_sha = NEW.expected_base_sha
            AND turn.purpose = 'BRANCH_SYNC_BRAIN_REVIEW'
            AND turn.status = 'REQUESTED')))
BEGIN SELECT RAISE(ABORT, 'Branch sync dispatch requires its exact worktree subject'); END;
CREATE TRIGGER branch_sync_dispatch_operation_status
BEFORE UPDATE OF status ON branch_sync_dispatch_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'SUCCEEDED', 'FAILED', 'INDETERMINATE',
        'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'INDETERMINATE',
        'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'Branch sync dispatch status transition is invalid'); END;
CREATE TRIGGER branch_sync_effect_step_claim
BEFORE UPDATE OF status ON branch_sync_effect_step
WHEN NEW.status = 'CLAIMED'
  AND (NEW.attempt_count <> OLD.attempt_count + 1
    OR (OLD.status = 'INDETERMINATE' AND NEW.claim_mode <> 'PROBE')
    OR (OLD.status <> 'INDETERMINATE' AND NEW.claim_mode <> 'EXECUTE')
    OR EXISTS (
        SELECT 1 FROM branch_sync_effect_step previous
        WHERE previous.branch_sync_episode_id = NEW.branch_sync_episode_id
          AND previous.ordinal < NEW.ordinal
          AND previous.status NOT IN ('SUCCEEDED', 'SKIPPED')))
BEGIN SELECT RAISE(ABORT, 'Branch sync effect claim is unordered or unsafe'); END;
CREATE TRIGGER branch_sync_effect_step_identity_immutable
BEFORE UPDATE OF branch_sync_episode_id, ordinal, kind, idempotency_key,
        attempt_limit ON branch_sync_effect_step
WHEN NEW.branch_sync_episode_id IS NOT OLD.branch_sync_episode_id
  OR NEW.ordinal IS NOT OLD.ordinal
  OR NEW.kind IS NOT OLD.kind
  OR NEW.idempotency_key IS NOT OLD.idempotency_key
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
BEGIN SELECT RAISE(ABORT, 'Branch sync effect identity is immutable'); END;
CREATE TRIGGER branch_sync_effect_step_insert
BEFORE INSERT ON branch_sync_effect_step
WHEN NEW.kind <> CASE NEW.ordinal
        WHEN 1 THEN 'FETCH_COMPARE'
        WHEN 2 THEN 'MECHANICAL_REBASE'
        WHEN 3 THEN 'CONFLICT_REPAIR'
        WHEN 4 THEN 'VALIDATE'
        WHEN 5 THEN 'BRAIN_REVIEW'
        WHEN 6 THEN 'FORCE_WITH_LEASE_PUSH'
    END
BEGIN SELECT RAISE(ABORT, 'Branch sync effect ordinal and kind do not match'); END;
CREATE TRIGGER branch_sync_episode_attempt_monotonic
BEFORE UPDATE OF attempt_count ON branch_sync_episode
WHEN NEW.attempt_count < OLD.attempt_count
  OR NEW.attempt_count > OLD.attempt_count + 1
BEGIN SELECT RAISE(ABORT, 'Branch sync attempt must advance by at most one'); END;
CREATE TRIGGER branch_sync_episode_identity_immutable
BEFORE UPDATE OF remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_binding_id, source_snapshot_id,
        old_head_sha, observed_base_sha, target_base_sha, policy_source,
        attempt_limit, opened_at_ms, branch_sync_policy_revision_id
        ON branch_sync_episode
WHEN NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.remote_pr_binding_id IS NOT OLD.remote_pr_binding_id
  OR NEW.source_snapshot_id IS NOT OLD.source_snapshot_id
  OR NEW.old_head_sha IS NOT OLD.old_head_sha
  OR NEW.observed_base_sha IS NOT OLD.observed_base_sha
  OR NEW.target_base_sha IS NOT OLD.target_base_sha
  OR NEW.policy_source IS NOT OLD.policy_source
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
  OR NEW.opened_at_ms IS NOT OLD.opened_at_ms
  OR NEW.branch_sync_policy_revision_id IS NOT OLD.branch_sync_policy_revision_id
BEGIN SELECT RAISE(ABORT, 'Branch sync subject is immutable'); END;
CREATE TRIGGER branch_sync_episode_insert
BEFORE INSERT ON branch_sync_episode
WHEN NOT EXISTS (
    SELECT 1 FROM remote_development_stage remote
    JOIN tasks task ON task.id = remote.task_id
    JOIN remote_pr_snapshot snapshot
      ON snapshot.remote_development_stage_id = remote.stage_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND remote.current_head_sha = NEW.old_head_sha
      AND remote.current_base_sha = NEW.observed_base_sha
      AND task.epoch = NEW.task_epoch
      AND snapshot.id = NEW.source_snapshot_id
      AND snapshot.head_sha = NEW.old_head_sha
      AND snapshot.base_sha = NEW.observed_base_sha)
BEGIN SELECT RAISE(ABORT, 'Branch sync requires the current exact remote subject'); END;
CREATE TRIGGER branch_sync_episode_policy_v264
BEFORE INSERT ON branch_sync_episode
WHEN NEW.branch_sync_policy_revision_id IS NULL
  OR NOT EXISTS (
      SELECT 1 FROM task_branch_sync_policy_revision policy
      WHERE policy.id = NEW.branch_sync_policy_revision_id
        AND policy.task_id = NEW.task_id
        AND policy.enabled = 1
        AND policy.source = NEW.policy_source
        AND policy.attempt_limit = NEW.attempt_limit
        AND policy.revision = (
            SELECT MAX(current.revision)
            FROM task_branch_sync_policy_revision current
            WHERE current.task_id = NEW.task_id))
BEGIN SELECT RAISE(ABORT, 'Branch sync requires the exact enabled Task policy'); END;
CREATE TRIGGER branch_sync_episode_success
BEFORE UPDATE OF status ON branch_sync_episode
WHEN NEW.status = 'SUCCEEDED'
  AND ((SELECT COUNT(*) FROM branch_sync_effect_step step
        WHERE step.branch_sync_episode_id = NEW.id) <> 6
    OR EXISTS (
        SELECT 1 FROM branch_sync_effect_step step
        WHERE step.branch_sync_episode_id = NEW.id
          AND step.status NOT IN ('SUCCEEDED', 'SKIPPED'))
    OR NOT EXISTS (
        SELECT 1 FROM branch_sync_push_proof proof
        WHERE proof.branch_sync_episode_id = NEW.id
          AND proof.pushed_head_sha = NEW.result_head_sha)
    OR NOT EXISTS (
        SELECT 1 FROM remote_pr_snapshot snapshot
        JOIN remote_development_stage remote
          ON remote.stage_id = snapshot.remote_development_stage_id
        WHERE snapshot.id = NEW.result_snapshot_id
          AND snapshot.remote_development_stage_id =
                NEW.remote_development_stage_id
          AND snapshot.task_id = NEW.task_id
          AND snapshot.stage_generation = NEW.stage_generation
          AND snapshot.remote_pr_binding_id = NEW.remote_pr_binding_id
          AND snapshot.head_sha = NEW.result_head_sha
          AND snapshot.base_sha = NEW.target_base_sha
          AND remote.accepted_snapshot_id = snapshot.id
          AND remote.current_head_sha = NEW.result_head_sha
          AND remote.current_base_sha = NEW.target_base_sha))
BEGIN SELECT RAISE(ABORT, 'Branch sync success lacks complete ordered effect proof'); END;
CREATE TRIGGER branch_sync_episode_terminal_immutable
BEFORE UPDATE ON branch_sync_episode
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'STOPPED')
BEGIN SELECT RAISE(ABORT, 'Terminal branch sync episode is immutable'); END;
CREATE TRIGGER branch_sync_push_proof_immutable
BEFORE UPDATE ON branch_sync_push_proof
BEGIN SELECT RAISE(ABORT, 'Branch sync push proof is immutable'); END;
CREATE TRIGGER branch_sync_push_proof_insert
BEFORE INSERT ON branch_sync_push_proof
WHEN NOT EXISTS (
    SELECT 1 FROM branch_sync_effect_step step
    JOIN branch_sync_episode episode
      ON episode.id = step.branch_sync_episode_id
    WHERE step.id = NEW.branch_sync_effect_step_id
      AND step.branch_sync_episode_id = NEW.branch_sync_episode_id
      AND step.kind = 'FORCE_WITH_LEASE_PUSH'
      AND step.status = 'CLAIMED'
      AND episode.old_head_sha = NEW.old_head_sha
      AND episode.observed_base_sha = NEW.observed_base_sha
      AND episode.target_base_sha = NEW.target_base_sha
      AND NEW.force_with_lease_expected_sha = NEW.old_head_sha
      AND NEW.pushed_head_sha <> NEW.old_head_sha)
BEGIN SELECT RAISE(ABORT, 'Branch sync push proof is not exact force-with-lease evidence'); END;
CREATE TRIGGER branch_sync_push_success
BEFORE UPDATE OF status ON branch_sync_effect_step
WHEN NEW.status = 'SUCCEEDED' AND NEW.kind = 'FORCE_WITH_LEASE_PUSH'
  AND NOT EXISTS (
      SELECT 1 FROM branch_sync_push_proof proof
      WHERE proof.branch_sync_effect_step_id = NEW.id
        AND proof.branch_sync_episode_id = NEW.branch_sync_episode_id)
BEGIN SELECT RAISE(ABORT, 'Branch sync push success lacks force-with-lease proof'); END;
CREATE TRIGGER capacity_lease_identity_immutable
BEFORE UPDATE OF ticket_id, operation_id, workflow_source, trunk_control,
        lane_mask, exclusive_task, writer_required, workspace_id, trunk_id, task_id,
        task_epoch, holder, fencing_token, acquired_at_ms ON capacity_lease
WHEN NEW.ticket_id IS NOT OLD.ticket_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.workflow_source IS NOT OLD.workflow_source
  OR NEW.lane_mask IS NOT OLD.lane_mask
  OR NEW.trunk_control IS NOT OLD.trunk_control
  OR NEW.exclusive_task IS NOT OLD.exclusive_task
  OR NEW.writer_required IS NOT OLD.writer_required
  OR NEW.workspace_id IS NOT OLD.workspace_id
  OR NEW.trunk_id IS NOT OLD.trunk_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.holder IS NOT OLD.holder
  OR NEW.fencing_token IS NOT OLD.fencing_token
  OR NEW.acquired_at_ms IS NOT OLD.acquired_at_ms
BEGIN SELECT RAISE(ABORT, 'capacity lease identity is immutable'); END;
CREATE TRIGGER capacity_lease_replan_admission_fence
BEFORE INSERT ON capacity_lease
WHEN NEW.workflow_source = 'V2'
  AND EXISTS (
      SELECT 1 FROM task_replan_request r
      WHERE r.task_id = NEW.task_id
        AND r.source_task_epoch = NEW.task_epoch
        AND r.status IN ('REQUESTED', 'QUIESCING'))
BEGIN SELECT RAISE(ABORT, 'replan quiescence blocks new exact-epoch admission'); END;
CREATE TRIGGER capacity_lease_route_insert
BEFORE INSERT ON capacity_lease
BEGIN
    SELECT CASE
        WHEN NEW.workflow_source = 'V2' AND NEW.ticket_id IS NULL
            THEN RAISE(ABORT, 'V2 capacity lease requires DispatchTicket')
        WHEN NEW.workflow_source = 'V2' AND NOT EXISTS (
            SELECT 1 FROM dispatch_ticket d
            WHERE d.id = NEW.ticket_id
              AND d.operation_id = NEW.operation_id
              AND d.lane_mask = NEW.lane_mask
              AND d.workspace_id IS NEW.workspace_id
              AND d.trunk_id IS NEW.trunk_id
              AND d.task_id IS NEW.task_id
              AND d.task_epoch IS NEW.task_epoch
              AND d.trunk_control = NEW.trunk_control
              AND d.exclusive_task = NEW.exclusive_task
              AND d.writer_required = NEW.writer_required)
            THEN RAISE(ABORT, 'V2 capacity lease does not match DispatchTicket')
        WHEN NEW.task_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM tasks t JOIN threads h ON h.id = t.thread_id
            WHERE t.id = NEW.task_id
              AND t.workflow_version = NEW.workflow_source
              AND t.epoch = NEW.task_epoch
              AND t.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'capacity lease does not match Task route and epoch')
        WHEN NEW.task_id IS NULL AND NEW.trunk_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM threads h
            WHERE h.id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'capacity lease does not match Trunk route')
    END;
END;
CREATE TRIGGER ci_repair_brain_verdict_immutable
BEFORE UPDATE ON ci_repair_brain_verdict
BEGIN SELECT RAISE(ABORT, 'CI Brain verdict is immutable'); END;
CREATE TRIGGER ci_repair_brain_verdict_insert
BEFORE INSERT ON ci_repair_brain_verdict
WHEN NOT EXISTS (
    SELECT 1 FROM ci_repair_operation operation
    WHERE operation.id = NEW.ci_repair_operation_id
      AND operation.kind = 'BRAIN_REVIEW'
      AND operation.task_turn_id = NEW.task_turn_id
      AND operation.status = 'SUCCEEDED')
BEGIN SELECT RAISE(ABORT, 'CI Brain verdict lacks its successful exact TaskTurn'); END;
CREATE TRIGGER ci_repair_budget_extension_immutable
BEFORE UPDATE OF id, ci_repair_episode_id, command_id, kind, rerun_delta,
        fix_delta, push_delta, approved_by, reason, created_at_ms
        ON ci_repair_budget_extension
BEGIN SELECT RAISE(ABORT, 'CI repair budget authorization is immutable'); END;
CREATE TRIGGER ci_repair_control_command_immutable
BEFORE UPDATE OF id, ci_repair_episode_id, command_id, kind, actor, reason,
        created_at_ms ON ci_repair_control_command
BEGIN SELECT RAISE(ABORT, 'CI repair control command is immutable'); END;
CREATE TRIGGER ci_repair_delivery_receipt_immutable
BEFORE UPDATE ON ci_repair_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'CI repair delivery receipt is immutable'); END;
CREATE TRIGGER ci_repair_delivery_receipt_insert
BEFORE INSERT ON ci_repair_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_repair_operation operation
    JOIN dispatch_ticket ticket ON ticket.operation_id = operation.operation_id
    WHERE operation.id = NEW.ci_repair_operation_id
      AND operation.operation_id = NEW.operation_id
      AND operation.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = NEW.raw_outcome)
BEGIN SELECT RAISE(ABORT, 'CI repair delivery receipt is not exact'); END;
CREATE TRIGGER ci_repair_episode_budget_update
BEFORE UPDATE OF rerun_limit, fix_attempt_limit, push_limit
        ON ci_repair_episode
WHEN NEW.rerun_limit <> OLD.rerun_limit
  OR NEW.fix_attempt_limit <> OLD.fix_attempt_limit
  OR NEW.push_limit <> OLD.push_limit
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM ci_repair_budget_extension extension
        WHERE extension.ci_repair_episode_id = NEW.id
          AND extension.consumed_at_ms IS NULL
          AND NEW.rerun_limit = OLD.rerun_limit + extension.rerun_delta
          AND NEW.fix_attempt_limit = OLD.fix_attempt_limit + extension.fix_delta
          AND NEW.push_limit = OLD.push_limit + extension.push_delta)
    THEN RAISE(ABORT, 'CI repair budget change lacks exact authorization') END;
END;
CREATE TRIGGER ci_repair_episode_counter_update
BEFORE UPDATE OF rerun_count, fix_attempt_count, delivery_retry_count, push_count
        ON ci_repair_episode
WHEN NEW.rerun_count NOT BETWEEN OLD.rerun_count AND OLD.rerun_count + 1
  OR NEW.fix_attempt_count NOT BETWEEN OLD.fix_attempt_count AND OLD.fix_attempt_count + 1
  OR NEW.delivery_retry_count NOT BETWEEN OLD.delivery_retry_count AND OLD.delivery_retry_count + 1
  OR NEW.push_count NOT BETWEEN OLD.push_count AND OLD.push_count + 1
BEGIN SELECT RAISE(ABORT, 'CI repair counters advance independently by at most one'); END;
CREATE TRIGGER ci_repair_episode_exhaustion
BEFORE UPDATE OF status ON ci_repair_episode
WHEN NEW.status = 'EXHAUSTED'
  AND (
    (NEW.classification IN ('FLAKY', 'INFRASTRUCTURE')
        AND NEW.rerun_count < NEW.rerun_limit)
    OR (NEW.classification NOT IN ('FLAKY', 'INFRASTRUCTURE')
        AND NEW.fix_attempt_count < NEW.fix_attempt_limit
        AND NEW.push_count < NEW.push_limit)
    OR (NEW.last_pushed_head_sha IS NOT NULL
        AND (NEW.last_push_result_evaluation_id IS NULL
            OR NOT EXISTS (
                SELECT 1 FROM remote_ci_evaluation evaluation
                WHERE evaluation.id = NEW.last_push_result_evaluation_id
                  AND evaluation.head_sha = NEW.last_pushed_head_sha
                  AND evaluation.policy_outcome = 'FAILED'))))
BEGIN SELECT RAISE(ABORT, 'CI repair cannot exhaust before its final result and budget'); END;
CREATE TRIGGER ci_repair_episode_identity_immutable
BEFORE UPDATE OF remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_binding_id, failed_ci_evaluation_id,
        subject_head_sha, subject_base_sha, classification, opened_at_ms
        ON ci_repair_episode
BEGIN SELECT RAISE(ABORT, 'CI repair subject identity is immutable'); END;
CREATE TRIGGER ci_repair_episode_insert
BEFORE INSERT ON ci_repair_episode
WHEN NOT EXISTS (
    SELECT 1 FROM remote_development_stage remote
    JOIN tasks task ON task.id = remote.task_id
    JOIN remote_ci_evaluation evaluation
      ON evaluation.remote_development_stage_id = remote.stage_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND remote.current_head_sha = NEW.subject_head_sha
      AND remote.current_base_sha = NEW.subject_base_sha
      AND task.epoch = NEW.task_epoch
      AND evaluation.id = NEW.failed_ci_evaluation_id
      AND evaluation.head_sha = NEW.subject_head_sha
      AND evaluation.base_sha = NEW.subject_base_sha
      AND evaluation.policy_outcome = 'FAILED')
BEGIN SELECT RAISE(ABORT, 'CI repair requires the current failed exact-head evidence'); END;
CREATE TRIGGER ci_repair_episode_push_result
BEFORE UPDATE OF last_pushed_head_sha, last_push_result_evaluation_id
        ON ci_repair_episode
WHEN NEW.last_push_result_evaluation_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM remote_ci_evaluation evaluation
      WHERE evaluation.id = NEW.last_push_result_evaluation_id
        AND evaluation.remote_development_stage_id =
            NEW.remote_development_stage_id
        AND evaluation.task_id = NEW.task_id
        AND evaluation.task_epoch = NEW.task_epoch
        AND evaluation.head_sha = NEW.last_pushed_head_sha)
BEGIN SELECT RAISE(ABORT, 'CI repair push result does not match the pushed head'); END;
CREATE TRIGGER ci_repair_episode_push_subject
BEFORE UPDATE OF push_count, last_pushed_head_sha ON ci_repair_episode
WHEN (NEW.push_count = OLD.push_count + 1
        AND (NEW.last_pushed_head_sha IS NULL
            OR NEW.last_pushed_head_sha IS OLD.last_pushed_head_sha
            OR NEW.last_pushed_head_sha IS NEW.subject_head_sha
            OR NEW.last_push_result_evaluation_id IS NOT NULL))
  OR (NEW.push_count = OLD.push_count
        AND NEW.last_pushed_head_sha IS NOT OLD.last_pushed_head_sha)
BEGIN SELECT RAISE(ABORT, 'Each CI repair push must record exactly one new unresolved head'); END;
CREATE TRIGGER ci_repair_episode_terminal_immutable
BEFORE UPDATE ON ci_repair_episode
WHEN OLD.status IN ('SUCCEEDED', 'STOPPED')
  OR (OLD.status = 'EXHAUSTED' AND NOT (
      (NEW.status = 'OPEN'
        AND NEW.completed_at_ms IS NULL
        AND NEW.terminal_ci_evaluation_id IS NULL
        AND EXISTS (
            SELECT 1 FROM ci_repair_budget_extension extension
            WHERE extension.ci_repair_episode_id = OLD.id
              AND extension.consumed_at_ms IS NULL))
      OR (NEW.status = 'STOPPED'
        AND EXISTS (
            SELECT 1 FROM ci_repair_control_command command
            WHERE command.ci_repair_episode_id = OLD.id
              AND command.consumed_at_ms IS NULL))))
BEGIN SELECT RAISE(ABORT, 'Terminal CI repair episode is immutable'); END;
CREATE TRIGGER ci_repair_episode_terminal_result
BEFORE UPDATE OF status ON ci_repair_episode
WHEN NEW.status IN ('SUCCEEDED', 'EXHAUSTED')
  AND NOT EXISTS (
      SELECT 1 FROM remote_ci_evaluation evaluation
      JOIN remote_development_stage remote
        ON remote.stage_id = evaluation.remote_development_stage_id
      WHERE evaluation.id = NEW.terminal_ci_evaluation_id
        AND evaluation.remote_development_stage_id =
            NEW.remote_development_stage_id
        AND evaluation.task_id = NEW.task_id
        AND evaluation.task_epoch = NEW.task_epoch
        AND evaluation.stage_generation = NEW.stage_generation
        AND evaluation.head_sha = COALESCE(
            NEW.last_pushed_head_sha, NEW.subject_head_sha)
        AND evaluation.base_sha = NEW.subject_base_sha
        AND evaluation.policy_outcome = CASE NEW.status
            WHEN 'SUCCEEDED' THEN 'ACCEPTED' ELSE 'FAILED' END
        AND remote.accepted_snapshot_id = evaluation.remote_pr_snapshot_id
        AND remote.current_head_sha = evaluation.head_sha
        AND remote.current_base_sha = evaluation.base_sha
        AND (NEW.last_pushed_head_sha IS NULL
            OR NEW.last_push_result_evaluation_id = evaluation.id))
BEGIN SELECT RAISE(ABORT, 'CI repair terminal state lacks accepted exact-head CI result'); END;
CREATE TRIGGER ci_repair_operation_dispatched
BEFORE UPDATE OF status ON ci_repair_operation
WHEN NEW.status = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1 FROM dispatch_ticket ticket
    WHERE ticket.operation_id = NEW.operation_id
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'CI repair Operation lacks its DispatchTicket'); END;
CREATE TRIGGER ci_repair_operation_identity_immutable
BEFORE UPDATE OF id, ci_repair_episode_id, remote_development_stage_id,
        task_id, task_epoch, stage_generation, kind, operation_id,
        semantic_attempt, stage_turn_id, task_turn_id,
        expected_code_fingerprint, expected_head_sha, expected_base_sha,
        requested_at_ms ON ci_repair_operation
BEGIN SELECT RAISE(ABORT, 'CI repair Operation identity is immutable'); END;
CREATE TRIGGER ci_repair_operation_insert
BEFORE INSERT ON ci_repair_operation
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_repair_episode episode
    JOIN remote_development_stage remote
      ON remote.stage_id = episode.remote_development_stage_id
    JOIN tasks task ON task.id = episode.task_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE episode.id = NEW.ci_repair_episode_id
      AND episode.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND episode.task_id = NEW.task_id
      AND episode.task_epoch = NEW.task_epoch
      AND episode.stage_generation = NEW.stage_generation
      AND episode.status NOT IN ('SUCCEEDED', 'EXHAUSTED', 'STOPPED')
      AND remote.current_head_sha =
          COALESCE(episode.last_pushed_head_sha, episode.subject_head_sha)
      AND remote.current_base_sha = episode.subject_base_sha
      AND task.epoch = NEW.task_epoch
      AND task.lifecycle_state = 'ACTIVE'
      AND NEW.status = 'REQUESTED'
      AND ((NEW.kind = 'RERUN'
            AND NEW.expected_code_fingerprint IS NULL
            AND NEW.expected_head_sha = remote.current_head_sha
            AND NEW.expected_base_sha = remote.current_base_sha)
        OR (NEW.kind <> 'RERUN'
            AND NEW.expected_code_fingerprint = code.code_fingerprint
            AND NEW.expected_head_sha = code.head_sha
            AND NEW.expected_base_sha = code.base_sha))
      AND (NEW.kind <> 'FIX_STAGE_TURN' OR EXISTS (
          SELECT 1 FROM stage_turn turn
          WHERE turn.id = NEW.stage_turn_id
            AND turn.operation_id = NEW.operation_id
            AND turn.stage_id = NEW.remote_development_stage_id
            AND turn.stage_generation = NEW.stage_generation
            AND turn.task_epoch = NEW.task_epoch
            AND turn.attempt = NEW.semantic_attempt
            AND turn.expected_code_fingerprint =
                NEW.expected_code_fingerprint
            AND turn.expected_head_sha = NEW.expected_head_sha
            AND turn.expected_base_sha = NEW.expected_base_sha
            AND turn.purpose = 'REMOTE_CI_REPAIR'
            AND turn.status = 'QUEUED'))
      AND (NEW.kind <> 'BRAIN_REVIEW' OR EXISTS (
          SELECT 1 FROM task_turn turn
          WHERE turn.id = NEW.task_turn_id
            AND turn.operation_id = NEW.operation_id
            AND turn.task_id = NEW.task_id
            AND turn.task_epoch = NEW.task_epoch
            AND turn.trigger_stage_id = NEW.remote_development_stage_id
            AND turn.trigger_stage_generation = NEW.stage_generation
            AND turn.attempt = NEW.semantic_attempt
            AND turn.expected_code_fingerprint =
                NEW.expected_code_fingerprint
            AND turn.expected_head_sha = NEW.expected_head_sha
            AND turn.expected_base_sha = NEW.expected_base_sha
            AND turn.purpose = 'REMOTE_CI_BRAIN_REVIEW'
            AND turn.status = 'REQUESTED')))
BEGIN SELECT RAISE(ABORT, 'CI repair Operation requires its live exact subjects'); END;
CREATE TRIGGER ci_repair_operation_status
BEFORE UPDATE OF status ON ci_repair_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'CI repair Operation status transition is invalid'); END;
CREATE TRIGGER cleanup_dispatch_admission
BEFORE INSERT ON dispatch_ticket
WHEN NEW.task_id IS NOT NULL
  AND EXISTS (
      SELECT 1 FROM tasks task
      WHERE task.id = NEW.task_id
        AND task.workflow_version = 'V2'
        AND task.lifecycle_state IN (
            'CLEANING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
  AND NOT (
      EXISTS (
          SELECT 1 FROM tasks task
          JOIN task_current_stage current ON current.task_id = task.id
          JOIN stage owner ON owner.id = current.stage_id
          JOIN cleanup_stage cleanup ON cleanup.stage_id = owner.id
          WHERE task.id = NEW.task_id
            AND task.lifecycle_state = 'CLEANING'
            AND task.epoch = NEW.task_epoch
            AND owner.kind = 'CLEANUP'
            AND owner.checkpoint = 'WAITING_QUIESCENCE'
            AND owner.id = NEW.stage_id
            AND owner.generation = NEW.stage_generation
            AND NEW.operation_kind = 'RUN_CLEANUP_OPERATION'
            AND NEW.async_family = 'CLEANUP'
            AND NEW.owner_kind = 'STAGE'
            AND NEW.owner_id = owner.id
            AND NEW.callback_route = 'CLEANUP_OPERATION_RESULT'
            AND NEW.lane_mask = 256
            AND NEW.exclusive_task = 1
            AND NEW.writer_required = 1
            AND NOT EXISTS (
                SELECT 1 FROM dispatch_ticket existing
                WHERE existing.task_id = NEW.task_id
                  AND existing.task_epoch = NEW.task_epoch
                  AND existing.async_family = 'CLEANUP'))
      OR EXISTS (
          SELECT 1 FROM tasks task
          JOIN task_outcome outcome ON outcome.task_id = task.id
          JOIN task_turn turn ON turn.task_id = task.id
          WHERE task.id = NEW.task_id
            AND task.lifecycle_state IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
            AND task.epoch = NEW.task_epoch
            AND outcome.summary_state = 'FALLBACK'
            AND turn.id = NEW.owner_id
            AND turn.purpose = 'TASK_COMPLETION_SUMMARY'
            AND turn.operation_id = NEW.operation_id
            AND turn.attempt = NEW.attempt
            AND NEW.operation_kind = 'GENERATE_TASK_OUTCOME_SUMMARY'
            AND NEW.async_family = 'AGENT_TURN'
            AND NEW.owner_kind = 'TASK_TURN'
            AND NEW.callback_route = 'TASK_OUTCOME_SUMMARY_RESULT'
            AND NEW.lane_mask = 2
            AND NEW.trunk_control = 0
            AND NEW.exclusive_task = 0
            AND NEW.writer_required = 0
            AND NEW.stage_id IS NULL
            AND NEW.stage_generation IS NULL)
      OR EXISTS (
          SELECT 1 FROM tasks task
          JOIN task_outcome outcome ON outcome.task_id = task.id
          JOIN task_turn turn ON turn.id = NEW.owner_id
          WHERE task.id = NEW.task_id
            AND task.lifecycle_state IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
            AND task.epoch = NEW.task_epoch
            AND outcome.task_epoch = NEW.task_epoch
            AND turn.task_id = task.id
            AND turn.purpose = 'TASK_BRAIN_CONVERSATION'
            AND turn.operation_id = NEW.operation_id
            AND turn.attempt = NEW.attempt
            AND NEW.operation_kind = 'EXECUTE_TASK_TURN'
            AND NEW.async_family = 'AGENT_TURN'
            AND NEW.owner_kind = 'TASK_TURN'
            AND NEW.callback_route = 'TASK_TURN_RESULT'
            AND NEW.lane_mask IN (9, 10)
            AND NEW.trunk_control = 0
            AND NEW.exclusive_task = 0
            AND NEW.writer_required = 0
            AND NEW.stage_id IS NULL
            AND NEW.stage_generation IS NULL))
BEGIN SELECT RAISE(ABORT, 'Task admits no unrelated dispatch during or after Cleanup'); END;
CREATE TRIGGER cleanup_interaction_dismissal_evidence_immutable
BEFORE UPDATE ON cleanup_interaction_dismissal_evidence
BEGIN SELECT RAISE(ABORT, 'Cleanup interaction evidence is immutable'); END;
CREATE TRIGGER cleanup_interaction_dismissal_evidence_insert
BEFORE INSERT ON cleanup_interaction_dismissal_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM cleanup_step step
    JOIN cleanup_operation operation ON operation.id = step.cleanup_operation_id
    WHERE step.id = NEW.cleanup_step_id
      AND step.cleanup_operation_id = NEW.cleanup_operation_id
      AND step.task_id = NEW.task_id
      AND step.task_epoch = NEW.task_epoch
      AND step.ordinal = 6
      AND step.kind = 'DISMISS_TASK_INTERACTIONS'
      AND step.status = 'CLAIMED'
      AND operation.status = 'ACTIVE'
      AND NEW.dismissed_notification_count = (
          SELECT COUNT(*) FROM notifications notification
          WHERE notification.task_id = NEW.task_id
            AND notification.status = 'DISMISSED'
            AND notification.read_at_ms IS NOT NULL
            AND notification.read_at_ms <= NEW.recorded_at_ms)
      AND NEW.canceled_permission_count = (
          SELECT COUNT(*) FROM permission_request permission
          WHERE permission.state = 'CANCELED'
            AND permission.answered_at_ms IS NOT NULL
            AND permission.answered_at_ms <= NEW.recorded_at_ms
            AND ((permission.turn_kind = 'TASK' AND EXISTS (
                    SELECT 1 FROM task_turn turn
                    WHERE turn.id = permission.turn_id
                      AND turn.task_id = NEW.task_id))
              OR (permission.turn_kind = 'STAGE' AND EXISTS (
                    SELECT 1 FROM stage_turn turn
                    JOIN stage owner ON owner.id = turn.stage_id
                    WHERE turn.id = permission.turn_id
                      AND owner.task_id = NEW.task_id))))
      AND NOT EXISTS (
          SELECT 1 FROM notifications notification
          WHERE notification.task_id = NEW.task_id
            AND notification.status = 'UNREAD')
      AND NOT EXISTS (
          SELECT 1 FROM permission_request permission
          WHERE permission.state = 'OPEN'
            AND ((permission.turn_kind = 'TASK' AND EXISTS (
                    SELECT 1 FROM task_turn turn
                    WHERE turn.id = permission.turn_id
                      AND turn.task_id = NEW.task_id))
              OR (permission.turn_kind = 'STAGE' AND EXISTS (
                    SELECT 1 FROM stage_turn turn
                    JOIN stage owner ON owner.id = turn.stage_id
                    WHERE turn.id = permission.turn_id
                      AND owner.task_id = NEW.task_id)))))
BEGIN SELECT RAISE(ABORT, 'Cleanup interaction evidence is incomplete'); END;
CREATE TRIGGER cleanup_operation_active
BEFORE UPDATE OF status ON cleanup_operation
WHEN NEW.status = 'ACTIVE'
  AND (OLD.status <> 'REQUESTED'
    OR NEW.started_at_ms IS NULL OR NEW.completed_at_ms IS NOT NULL
    OR NEW.summary_digest IS NOT NULL
    OR (SELECT COUNT(*) FROM cleanup_step step
        WHERE step.cleanup_operation_id = NEW.id) <> NEW.step_count
    OR EXISTS (
        SELECT 1 FROM cleanup_step step
        WHERE step.cleanup_operation_id = NEW.id
          AND step.status <> 'REQUESTED')
    OR NOT EXISTS (
        SELECT 1 FROM dispatch_ticket ticket
        JOIN cleanup_stage cleanup ON cleanup.stage_id = NEW.cleanup_stage_id
        JOIN stage owner ON owner.id = cleanup.stage_id
        JOIN tasks task ON task.id = cleanup.task_id
        WHERE ticket.id = NEW.dispatch_ticket_id
          AND ticket.operation_id = NEW.operation_id
          AND ticket.status IN ('CLAIMED', 'RUNNING')
          AND ticket.claim_purpose = 'EXECUTE'
          AND ticket.task_id = NEW.task_id
          AND ticket.task_epoch = NEW.task_epoch
          AND ticket.stage_id = NEW.cleanup_stage_id
          AND ticket.stage_generation = NEW.stage_generation
          AND owner.checkpoint = 'WAITING_QUIESCENCE'
          AND owner.completed_at_ms IS NULL
          AND task.lifecycle_state = 'CLEANING'
          AND task.epoch = NEW.task_epoch))
BEGIN SELECT RAISE(ABORT, 'CleanupOperation cannot activate without its claimed dispatch and full ledger'); END;
CREATE TRIGGER cleanup_operation_complete
BEFORE UPDATE OF status ON cleanup_operation
WHEN NEW.status = 'COMPLETED'
  AND (OLD.status <> 'ACTIVE'
    OR NEW.summary_digest IS NULL OR NEW.completed_at_ms IS NULL
    OR (SELECT COUNT(*) FROM cleanup_step step
        WHERE step.cleanup_operation_id = NEW.id) <> NEW.step_count
    OR EXISTS (
        SELECT 1 FROM cleanup_step step
        WHERE step.cleanup_operation_id = NEW.id
          AND NOT ((step.requirement = 'REQUIRED' AND step.status = 'SUCCEEDED')
            OR (step.requirement = 'OPTIONAL'
                AND step.status IN ('SUCCEEDED', 'WAIVED'))
            OR (step.requirement = 'NOT_APPLICABLE'
                AND step.status = 'SKIPPED')))
    OR EXISTS (
        SELECT 1 FROM task_blocker blocker
        WHERE blocker.task_id = NEW.task_id
          AND blocker.stage_id = NEW.cleanup_stage_id
          AND blocker.owner_kind = 'OPERATION'
          AND blocker.owner_id = NEW.id
          AND blocker.status = 'OPEN')
    OR NOT EXISTS (
        SELECT 1 FROM cleanup_step final_step
        WHERE final_step.cleanup_operation_id = NEW.id
          AND final_step.ordinal = 11
          AND final_step.kind = 'RECORD_FINAL_EVIDENCE'
          AND final_step.status = 'SUCCEEDED'
          AND EXISTS (
              SELECT 1 FROM cleanup_step_attempt_result result
              WHERE result.cleanup_step_id = final_step.id
                AND result.attempt = final_step.attempt_count
                AND result.outcome = 'SUCCEEDED'
                AND result.evidence_digest = NEW.summary_digest))
    OR NOT EXISTS (
        SELECT 1 FROM dispatch_ticket ticket
        WHERE ticket.id = NEW.dispatch_ticket_id
          AND ticket.operation_id = NEW.operation_id
          AND ticket.status = 'RESULT_PENDING'
          AND ticket.pending_result_outcome = 'SUCCEEDED'
          AND ticket.pending_result_payload = NEW.summary_digest
          AND ticket.pending_result_evidence IS NOT NULL
          AND ticket.pending_result_task_epoch = NEW.task_epoch
          AND ticket.pending_result_stage_id = NEW.cleanup_stage_id
          AND ticket.pending_result_stage_generation = NEW.stage_generation
          AND ticket.pending_result_operation_id = NEW.operation_id
          AND ticket.pending_result_attempt = NEW.semantic_attempt))
BEGIN SELECT RAISE(ABORT, 'CleanupOperation completion lacks exact settled evidence'); END;
CREATE TRIGGER cleanup_operation_identity_immutable
BEFORE UPDATE OF cleanup_stage_id, task_id, task_epoch, stage_generation,
        terminal_acceptance_id, dispatch_ticket_id, operation_id,
        semantic_attempt, step_count,
        requested_at_ms ON cleanup_operation
WHEN NEW.cleanup_stage_id IS NOT OLD.cleanup_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.terminal_acceptance_id IS NOT OLD.terminal_acceptance_id
  OR NEW.dispatch_ticket_id IS NOT OLD.dispatch_ticket_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.step_count IS NOT OLD.step_count
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'CleanupOperation identity is immutable'); END;
CREATE TRIGGER cleanup_operation_insert
BEFORE INSERT ON cleanup_operation
WHEN NEW.status <> 'REQUESTED'
  OR NOT EXISTS (
    SELECT 1 FROM cleanup_stage cleanup
    JOIN stage owner ON owner.id = cleanup.stage_id
    JOIN tasks task ON task.id = cleanup.task_id
    JOIN task_current_stage current ON current.stage_id = owner.id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    JOIN outbox wake ON wake.aggregate_id = ticket.id
    WHERE cleanup.stage_id = NEW.cleanup_stage_id
      AND cleanup.task_id = NEW.task_id
      AND cleanup.task_epoch = NEW.task_epoch
      AND cleanup.generation = NEW.stage_generation
      AND cleanup.terminal_acceptance_id = NEW.terminal_acceptance_id
      AND owner.checkpoint = 'WAITING_QUIESCENCE'
      AND owner.completed_at_ms IS NULL
      AND current.task_id = NEW.task_id
      AND current.stage_generation = NEW.stage_generation
      AND task.lifecycle_state = 'CLEANING'
      AND task.epoch = NEW.task_epoch
      AND ticket.operation_id = NEW.operation_id
      AND ticket.operation_kind = 'RUN_CLEANUP_OPERATION'
      AND ticket.async_family = 'CLEANUP'
      AND ticket.owner_kind = 'STAGE'
      AND ticket.owner_id = NEW.cleanup_stage_id
      AND ticket.callback_route = 'CLEANUP_OPERATION_RESULT'
      AND ticket.lane_mask = 256
      AND ticket.exclusive_task = 1
      AND ticket.writer_required = 1
      AND ticket.workspace_id = (
          SELECT trunk.workspace_id FROM threads trunk
          WHERE trunk.id = task.thread_id)
      AND ticket.trunk_id = task.thread_id
      AND ticket.task_id = NEW.task_id
      AND ticket.task_epoch = NEW.task_epoch
      AND ticket.stage_id = NEW.cleanup_stage_id
      AND ticket.stage_generation = NEW.stage_generation
      AND ticket.attempt = NEW.semantic_attempt
      AND ticket.status = 'REQUESTED'
      AND wake.id = 'V2_DISPATCH_TICKET_REQUESTED:' || ticket.id
      AND wake.dedup_key = wake.id
      AND wake.aggregate_kind = 'DISPATCH_TICKET'
      AND wake.topic = 'V2_DISPATCH_TICKET_REQUESTED'
      AND wake.payload = ticket.id
      AND wake.status = 'PENDING'
      AND wake.attempts = 0
      AND wake.available_at_ms = ticket.created_at_ms
      AND wake.created_at_ms = ticket.created_at_ms
      AND wake.claim_owner IS NULL AND wake.lease_until_ms IS NULL
      AND wake.delivered_at_ms IS NULL AND wake.last_error IS NULL)
BEGIN SELECT RAISE(ABORT, 'CleanupOperation lacks its exact current Cleanup Stage'); END;
CREATE TRIGGER cleanup_operation_result_fields
BEFORE UPDATE OF started_at_ms, completed_at_ms, summary_digest
        ON cleanup_operation
WHEN NEW.status IS OLD.status
  AND (NEW.started_at_ms IS NOT OLD.started_at_ms
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms
    OR NEW.summary_digest IS NOT OLD.summary_digest)
BEGIN SELECT RAISE(ABORT, 'CleanupOperation result fields change only with status'); END;
CREATE TRIGGER cleanup_operation_terminal_immutable
BEFORE UPDATE ON cleanup_operation
WHEN OLD.status = 'COMPLETED'
BEGIN SELECT RAISE(ABORT, 'Terminal CleanupOperation is immutable'); END;
CREATE TRIGGER cleanup_operation_transition
BEFORE UPDATE OF status ON cleanup_operation
WHEN NEW.status IS NOT OLD.status
  AND NOT ((OLD.status = 'REQUESTED' AND NEW.status = 'ACTIVE')
        OR (OLD.status = 'ACTIVE' AND NEW.status = 'COMPLETED'))
BEGIN SELECT RAISE(ABORT, 'CleanupOperation transition is invalid'); END;
CREATE TRIGGER cleanup_stage_checkpoint_update
BEFORE UPDATE OF checkpoint, completed_at_ms, end_reason ON stage
WHEN OLD.kind = 'CLEANUP'
  AND NOT ((OLD.checkpoint = 'WAITING_QUIESCENCE'
            AND NEW.checkpoint = 'CLEANING'
            AND NEW.completed_at_ms IS NULL AND NEW.end_reason IS NULL
            AND EXISTS (
                SELECT 1 FROM cleanup_operation operation
                WHERE operation.cleanup_stage_id = OLD.id
                  AND operation.status = 'ACTIVE')
            AND EXISTS (
                SELECT 1 FROM stage_transition transition
                WHERE transition.stage_id = OLD.id
                  AND transition.generation = OLD.generation
                  AND transition.from_checkpoint = OLD.checkpoint
                  AND transition.to_checkpoint = NEW.checkpoint
                  AND transition.stage_version = NEW.version
                  AND transition.cause = 'ACCEPT_CLEANUP_QUIESCENCE'))
        OR (OLD.checkpoint = 'CLEANING'
            AND NEW.checkpoint = 'COMPLETED'
            AND NEW.completed_at_ms IS NOT NULL
            AND NEW.end_reason = 'NORMAL'
            AND EXISTS (
                SELECT 1 FROM cleanup_operation operation
                WHERE operation.cleanup_stage_id = OLD.id
                  AND operation.status = 'COMPLETED')
            AND EXISTS (
                SELECT 1 FROM stage_transition transition
                WHERE transition.stage_id = OLD.id
                  AND transition.generation = OLD.generation
                  AND transition.from_checkpoint = OLD.checkpoint
                  AND transition.to_checkpoint = NEW.checkpoint
                  AND transition.stage_version = NEW.version
                  AND transition.cause = 'ACCEPT_CLEANUP_COMPLETE')))
BEGIN SELECT RAISE(ABORT, 'Cleanup Stage checkpoint lacks its exact operation transition'); END;
CREATE TRIGGER cleanup_stage_immutable
BEFORE UPDATE ON cleanup_stage
BEGIN SELECT RAISE(ABORT, 'Cleanup Stage identity is immutable'); END;
CREATE TRIGGER cleanup_stage_insert
BEFORE INSERT ON cleanup_stage
WHEN NOT EXISTS (
    SELECT 1 FROM stage owner
    JOIN tasks task ON task.id = owner.task_id
    JOIN task_current_stage current ON current.stage_id = owner.id
    JOIN task_terminal_acceptance acceptance
      ON acceptance.id = NEW.terminal_acceptance_id
    JOIN task_terminal_intent intent ON intent.id = acceptance.task_terminal_intent_id
    JOIN task_policy_revision policy ON policy.id = NEW.task_policy_revision_id
    WHERE owner.id = NEW.stage_id
      AND owner.task_id = NEW.task_id
      AND owner.kind = 'CLEANUP'
      AND owner.generation = NEW.generation
      AND owner.checkpoint = 'WAITING_QUIESCENCE'
      AND owner.completed_at_ms IS NULL
      AND current.task_id = NEW.task_id
      AND current.stage_generation = NEW.generation
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'CLEANING'
      AND task.epoch = NEW.task_epoch
      AND task.policy_revision_id = policy.id
      AND acceptance.task_id = NEW.task_id
      AND acceptance.task_epoch = NEW.task_epoch
      AND acceptance.kind = NEW.terminal_reason
      AND intent.id = NEW.task_terminal_intent_id
      AND policy.trunk_id = task.thread_id
      AND (NEW.remote_pr_binding_id IS NULL OR EXISTS (
          SELECT 1 FROM remote_pr_binding binding
          WHERE binding.id = NEW.remote_pr_binding_id
            AND binding.task_id = NEW.task_id))
      AND NEW.remote_pr_disposition = CASE
          WHEN NEW.remote_pr_binding_id IS NULL THEN 'NO_REMOTE_PR'
          WHEN NEW.terminal_reason = 'CANCELED' THEN 'PRESERVE_OPEN'
          ELSE 'REMOTE_ALREADY_TERMINAL' END
      AND NEW.local_branch_requirement = CASE
          WHEN policy.delete_local_branch_on_cleanup = 1 THEN 'REQUIRED'
          ELSE 'NOT_APPLICABLE' END
      AND NEW.remote_branch_requirement = CASE
          WHEN NEW.remote_pr_binding_id IS NULL OR NEW.terminal_reason = 'CANCELED'
              THEN 'NOT_APPLICABLE'
          WHEN policy.require_remote_branch_cleanup = 1 THEN 'REQUIRED'
          ELSE 'OPTIONAL' END)
BEGIN SELECT RAISE(ABORT, 'Cleanup Stage lacks current accepted terminal ownership'); END;
CREATE TRIGGER cleanup_stage_turn_admission
BEFORE INSERT ON stage_turn
WHEN EXISTS (
    SELECT 1 FROM stage owner
    JOIN tasks task ON task.id = owner.task_id
    WHERE owner.id = NEW.stage_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state IN (
          'CLEANING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
BEGIN SELECT RAISE(ABORT, 'Task admits no StageTurns during or after Cleanup'); END;
CREATE TRIGGER cleanup_step_attempt
BEFORE UPDATE OF attempt_count, execute_attempt_count ON cleanup_step
WHEN NEW.status <> 'CLAIMED'
  OR NEW.attempt_count <> OLD.attempt_count + 1
  OR NEW.execute_attempt_count <> OLD.execute_attempt_count
        + CASE NEW.claim_mode WHEN 'EXECUTE' THEN 1 ELSE 0 END
  OR OLD.status NOT IN ('REQUESTED', 'CLAIMED', 'FAILED')
  OR (OLD.status = 'CLAIMED'
      AND (NEW.claim_mode <> 'PROBE'
        OR NEW.claimed_at_ms < OLD.lease_until_ms))
  OR (OLD.status = 'FAILED' AND OLD.failure_kind = 'INDETERMINATE'
      AND NEW.claim_mode <> 'PROBE')
  OR ((OLD.status = 'REQUESTED'
        OR (OLD.status = 'FAILED' AND OLD.failure_kind = 'DETERMINATE'))
      AND NEW.claim_mode <> 'EXECUTE')
  OR (NEW.claim_mode = 'EXECUTE'
      AND OLD.execute_attempt_count >= OLD.attempt_limit)
  OR NEW.claim_owner IS NULL OR NEW.claimed_at_ms IS NULL
  OR NEW.lease_until_ms IS NULL OR NEW.lease_until_ms <= NEW.claimed_at_ms
  OR NEW.failure_kind IS NOT NULL OR NEW.last_error IS NOT NULL
  OR NEW.completed_at_ms IS NOT NULL
  OR EXISTS (
      SELECT 1 FROM cleanup_step previous
      WHERE previous.cleanup_operation_id = NEW.cleanup_operation_id
        AND previous.ordinal < NEW.ordinal
        AND NOT ((previous.requirement = 'REQUIRED'
                  AND previous.status = 'SUCCEEDED')
          OR (previous.requirement = 'OPTIONAL'
                  AND previous.status IN ('SUCCEEDED', 'WAIVED'))
          OR (previous.requirement = 'NOT_APPLICABLE'
                  AND previous.status = 'SKIPPED')))
  OR NOT EXISTS (
      SELECT 1 FROM cleanup_operation operation
      JOIN stage owner ON owner.id = operation.cleanup_stage_id
      JOIN tasks task ON task.id = operation.task_id
      WHERE operation.id = NEW.cleanup_operation_id
        AND operation.status = 'ACTIVE'
        AND owner.checkpoint = 'CLEANING'
        AND owner.completed_at_ms IS NULL
        AND task.lifecycle_state = 'CLEANING'
        AND task.epoch = NEW.task_epoch)
BEGIN SELECT RAISE(ABORT, 'CleanupStep attempt must be an exact claim'); END;
CREATE TRIGGER cleanup_step_attempt_result_immutable
BEFORE UPDATE ON cleanup_step_attempt_result
BEGIN SELECT RAISE(ABORT, 'Cleanup step attempt result is immutable'); END;
CREATE TRIGGER cleanup_step_attempt_result_insert
BEFORE INSERT ON cleanup_step_attempt_result
WHEN NOT EXISTS (
    SELECT 1 FROM cleanup_step step
    JOIN cleanup_operation operation ON operation.id = step.cleanup_operation_id
    JOIN cleanup_stage cleanup ON cleanup.stage_id = step.cleanup_stage_id
    JOIN tasks task ON task.id = step.task_id
    WHERE step.id = NEW.cleanup_step_id
      AND step.cleanup_operation_id = NEW.cleanup_operation_id
      AND step.task_id = NEW.task_id
      AND step.task_epoch = NEW.task_epoch
      AND step.ordinal = NEW.ordinal
      AND step.status = 'CLAIMED'
      AND step.attempt_count = NEW.attempt
      AND step.claim_mode = NEW.claim_mode
      AND operation.status = 'ACTIVE'
      AND task.lifecycle_state = 'CLEANING'
      AND task.epoch = NEW.task_epoch
      AND ((step.ordinal = 1
            AND task.lifecycle_state = 'CLEANING'
            AND cleanup.stage_id = step.cleanup_stage_id)
        OR step.ordinal <> 1)
      AND (step.ordinal <> 2 OR (
          NOT EXISTS (
              SELECT 1 FROM task_turn turn
              WHERE turn.task_id = NEW.task_id
                AND turn.task_epoch = NEW.task_epoch
                AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
          AND NOT EXISTS (
              SELECT 1 FROM stage_turn turn
              JOIN stage owner ON owner.id = turn.stage_id
              WHERE owner.task_id = NEW.task_id
                AND turn.task_epoch = NEW.task_epoch
                AND turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING'))
          AND NOT EXISTS (
              SELECT 1 FROM dispatch_ticket ticket
              WHERE ticket.task_id = NEW.task_id
                AND ticket.task_epoch = NEW.task_epoch
                AND ticket.async_family <> 'CLEANUP'
                AND ticket.status IN ('REQUESTED', 'RETRY_WAIT', 'RECONCILE_WAIT',
                    'RESULT_PENDING', 'CLAIMED', 'RUNNING', 'DELIVERING'))
          AND NOT EXISTS (
              SELECT 1 FROM ci_repair_episode episode
              WHERE episode.task_id = NEW.task_id
                AND episode.task_epoch = NEW.task_epoch
                AND episode.status NOT IN ('SUCCEEDED', 'EXHAUSTED', 'STOPPED'))
          AND NOT EXISTS (
              SELECT 1 FROM branch_sync_episode episode
              WHERE episode.task_id = NEW.task_id
                AND episode.task_epoch = NEW.task_epoch
                AND episode.status NOT IN ('SUCCEEDED', 'FAILED', 'STOPPED'))
          AND NOT EXISTS (
              SELECT 1 FROM remote_mark_ready_operation remote_operation
              WHERE remote_operation.task_id = NEW.task_id
                AND remote_operation.task_epoch = NEW.task_epoch
                AND remote_operation.status NOT IN ('SUCCEEDED', 'CANCELED'))
          AND NOT EXISTS (
              SELECT 1 FROM remote_merge_operation merge_operation
              WHERE merge_operation.task_id = NEW.task_id
                AND merge_operation.task_epoch = NEW.task_epoch
                AND merge_operation.status NOT IN (
                    'SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED'))))
      AND (step.ordinal <> 3 OR NOT EXISTS (
          SELECT 1 FROM agent_execution execution
          JOIN dispatch_ticket ticket ON ticket.id = execution.ticket_id
          WHERE ticket.task_id = NEW.task_id
            AND execution.status IN ('STARTING', 'RUNNING', 'UNKNOWN')))
      AND (step.ordinal <> 4 OR (
          NOT EXISTS (
              SELECT 1 FROM validation_operation validation
              WHERE validation.task_id = NEW.task_id
                AND validation.status IN ('REQUESTED', 'DISPATCHED'))
          AND NOT EXISTS (
              SELECT 1 FROM validation_pass validation
              WHERE validation.task_id = NEW.task_id
                AND validation.ended_at_ms IS NULL)))
      AND (step.ordinal <> 5 OR (
          NOT EXISTS (
              SELECT 1 FROM local_feedback_batch batch
              WHERE batch.task_id = NEW.task_id
                AND batch.status IN ('BUILDING', 'FROZEN', 'QUEUED', 'DISPATCHED'))
          AND NOT EXISTS (
              SELECT 1 FROM remote_feedback_batch batch
              WHERE batch.task_id = NEW.task_id
                AND batch.status NOT IN ('COMPLETED', 'SUPERSEDED'))
          AND NOT EXISTS (
              SELECT 1 FROM remote_mark_ready_authorization authorization
              WHERE authorization.task_id = NEW.task_id
                AND authorization.status = 'ACTIVE')
          AND NOT EXISTS (
              SELECT 1 FROM remote_merge_authorization authorization
              WHERE authorization.task_id = NEW.task_id
                AND authorization.status = 'ACTIVE')))
      AND (step.ordinal <> 6 OR NOT EXISTS (
          SELECT 1 FROM permission_request permission
          WHERE permission.state = 'OPEN'
            AND ((permission.turn_kind = 'TASK' AND EXISTS (
                    SELECT 1 FROM task_turn turn
                    WHERE turn.id = permission.turn_id
                      AND turn.task_id = NEW.task_id))
              OR (permission.turn_kind = 'STAGE' AND EXISTS (
                    SELECT 1 FROM stage_turn turn
                    JOIN stage owner ON owner.id = turn.stage_id
                    WHERE turn.id = permission.turn_id
                      AND owner.task_id = NEW.task_id)))))
      AND (step.ordinal <> 6 OR EXISTS (
          SELECT 1 FROM cleanup_interaction_dismissal_evidence interaction
          WHERE interaction.cleanup_step_id = step.id
            AND interaction.cleanup_operation_id = operation.id
            AND interaction.task_id = NEW.task_id
            AND interaction.task_epoch = NEW.task_epoch
            AND interaction.recorded_at_ms <= NEW.recorded_at_ms))
      AND (step.ordinal <> 7 OR (
          NOT EXISTS (
              SELECT 1 FROM capacity_lease lease
              JOIN dispatch_ticket ticket ON ticket.id = lease.ticket_id
              WHERE lease.workflow_source = 'V2'
                AND lease.task_id = NEW.task_id
                AND lease.task_epoch = NEW.task_epoch
                AND ticket.async_family <> 'CLEANUP'
                AND lease.released_at_ms IS NULL
                AND lease.expires_at_ms > NEW.recorded_at_ms)
          AND NOT EXISTS (
              SELECT 1 FROM worktree_leases lease
              WHERE lease.workflow_version = 'V2'
                AND lease.task_id = NEW.task_id
                AND lease.task_epoch = NEW.task_epoch
                AND lease.expires_at_ms > NEW.recorded_at_ms))))
BEGIN SELECT RAISE(ABORT, 'Cleanup result lacks exact claimed or reconciled evidence'); END;
CREATE TRIGGER cleanup_step_claim
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status = 'CLAIMED'
  AND (NEW.attempt_count <> OLD.attempt_count + 1
    OR NEW.execute_attempt_count <> OLD.execute_attempt_count
        + CASE NEW.claim_mode WHEN 'EXECUTE' THEN 1 ELSE 0 END
    OR (NEW.claim_mode = 'EXECUTE'
        AND OLD.execute_attempt_count >= OLD.attempt_limit)
    OR OLD.status NOT IN ('REQUESTED', 'CLAIMED', 'FAILED')
    OR (OLD.status = 'CLAIMED'
        AND (NEW.claim_mode <> 'PROBE'
          OR NEW.claimed_at_ms < OLD.lease_until_ms))
    OR (OLD.status = 'FAILED' AND OLD.failure_kind = 'INDETERMINATE'
        AND NEW.claim_mode <> 'PROBE')
    OR ((OLD.status = 'REQUESTED'
          OR (OLD.status = 'FAILED' AND OLD.failure_kind = 'DETERMINATE'))
        AND NEW.claim_mode <> 'EXECUTE')
    OR NEW.failure_kind IS NOT NULL OR NEW.last_error IS NOT NULL
    OR NEW.completed_at_ms IS NOT NULL
    OR EXISTS (
        SELECT 1 FROM cleanup_step previous
        WHERE previous.cleanup_operation_id = NEW.cleanup_operation_id
          AND previous.ordinal < NEW.ordinal
          AND NOT ((previous.requirement = 'REQUIRED'
                    AND previous.status = 'SUCCEEDED')
            OR (previous.requirement = 'OPTIONAL'
                    AND previous.status IN ('SUCCEEDED', 'WAIVED'))
            OR (previous.requirement = 'NOT_APPLICABLE'
                    AND previous.status = 'SKIPPED')))
    OR NOT EXISTS (
        SELECT 1 FROM cleanup_operation operation
        JOIN stage owner ON owner.id = operation.cleanup_stage_id
        JOIN tasks task ON task.id = operation.task_id
        WHERE operation.id = NEW.cleanup_operation_id
          AND operation.status = 'ACTIVE'
          AND owner.checkpoint = 'CLEANING'
          AND owner.completed_at_ms IS NULL
          AND task.lifecycle_state = 'CLEANING'
          AND task.epoch = NEW.task_epoch))
BEGIN SELECT RAISE(ABORT, 'CleanupStep claim is stale, unordered, or unsafe'); END;
CREATE TRIGGER cleanup_step_claim_fields
BEFORE UPDATE OF claim_mode, claim_owner, claimed_at_ms, lease_until_ms
        ON cleanup_step
WHEN NOT ((NEW.status = 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count + 1)
        OR (OLD.status = 'CLAIMED' AND NEW.status <> 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count
            AND NEW.claim_mode IS NULL AND NEW.claim_owner IS NULL
            AND NEW.claimed_at_ms IS NULL AND NEW.lease_until_ms IS NULL))
BEGIN SELECT RAISE(ABORT, 'CleanupStep claim fields change only with an attempt boundary'); END;
CREATE TRIGGER cleanup_step_determinate_retry_consumed
AFTER UPDATE OF status ON cleanup_step
WHEN OLD.status = 'FAILED' AND OLD.failure_kind = 'DETERMINATE'
  AND NEW.status = 'CLAIMED'
BEGIN
    UPDATE cleanup_step_retry_request
       SET status = 'CONSUMED', consumed_at_ms = NEW.claimed_at_ms
     WHERE cleanup_step_id = NEW.id
       AND cleanup_operation_id = NEW.cleanup_operation_id
       AND task_id = NEW.task_id
       AND failed_attempt = OLD.attempt_count
       AND status = 'PENDING';
END;
CREATE TRIGGER cleanup_step_determinate_retry_requires_request
BEFORE UPDATE OF status ON cleanup_step
WHEN OLD.status = 'FAILED' AND OLD.failure_kind = 'DETERMINATE'
  AND NEW.status = 'CLAIMED'
  AND NOT EXISTS (
      SELECT 1 FROM cleanup_step_retry_request retry
      WHERE retry.cleanup_step_id = OLD.id
        AND retry.cleanup_operation_id = OLD.cleanup_operation_id
        AND retry.task_id = OLD.task_id
        AND retry.failed_attempt = OLD.attempt_count
        AND retry.status = 'PENDING')
BEGIN SELECT RAISE(ABORT, 'Determinate Cleanup retry lacks owner authorization'); END;
CREATE TRIGGER cleanup_step_failure
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status = 'FAILED'
  AND (NOT EXISTS (
      SELECT 1 FROM cleanup_step_attempt_result result
      WHERE result.cleanup_step_id = NEW.id
        AND result.attempt = NEW.attempt_count
        AND result.claim_mode = OLD.claim_mode
        AND ((result.outcome = 'FAILED' AND NEW.failure_kind = 'DETERMINATE')
          OR (result.outcome = 'INDETERMINATE'
                AND NEW.failure_kind = 'INDETERMINATE')))
    OR NOT EXISTS (
      SELECT 1 FROM task_blocker blocker
      WHERE blocker.task_id = NEW.task_id
        AND blocker.stage_id = NEW.cleanup_stage_id
        AND blocker.owner_kind = 'OPERATION'
        AND blocker.owner_id = NEW.cleanup_operation_id
        AND blocker.subject_revision = CAST(NEW.ordinal AS TEXT)
        AND blocker.status = 'OPEN'))
BEGIN SELECT RAISE(ABORT, 'CleanupStep failure lacks exact result and blocker'); END;
CREATE TRIGGER cleanup_step_identity_immutable
BEFORE UPDATE OF cleanup_operation_id, task_id, task_epoch, cleanup_stage_id,
        stage_generation, ordinal, kind, requirement, idempotency_key,
        attempt_limit ON cleanup_step
WHEN NEW.cleanup_operation_id IS NOT OLD.cleanup_operation_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.cleanup_stage_id IS NOT OLD.cleanup_stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.ordinal IS NOT OLD.ordinal
  OR NEW.kind IS NOT OLD.kind
  OR NEW.requirement IS NOT OLD.requirement
  OR NEW.idempotency_key IS NOT OLD.idempotency_key
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
BEGIN SELECT RAISE(ABORT, 'CleanupStep identity is immutable'); END;
CREATE TRIGGER cleanup_step_insert
BEFORE INSERT ON cleanup_step
WHEN NEW.status <> 'REQUESTED' OR NEW.attempt_count <> 0
  OR NEW.execute_attempt_count <> 0
  OR NOT EXISTS (
    SELECT 1 FROM cleanup_operation operation
    JOIN cleanup_stage cleanup ON cleanup.stage_id = operation.cleanup_stage_id
    WHERE operation.id = NEW.cleanup_operation_id
      AND operation.status = 'REQUESTED'
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.cleanup_stage_id = NEW.cleanup_stage_id
      AND operation.stage_generation = NEW.stage_generation
      AND NEW.ordinal = COALESCE((
          SELECT MAX(step.ordinal) + 1 FROM cleanup_step step
          WHERE step.cleanup_operation_id = operation.id), 1)
      AND NEW.kind = CASE NEW.ordinal
          WHEN 1 THEN 'PROVE_NO_NEW_ADMISSIONS'
          WHEN 2 THEN 'RECONCILE_OPEN_WORK'
          WHEN 3 THEN 'STOP_PROVIDER_SESSIONS'
          WHEN 4 THEN 'RECONCILE_VALIDATION'
          WHEN 5 THEN 'SEAL_REVIEW_STATE'
          WHEN 6 THEN 'DISMISS_TASK_INTERACTIONS'
          WHEN 7 THEN 'RELEASE_RUNTIME_LEASES'
          WHEN 8 THEN 'REMOVE_WORKTREE'
          WHEN 9 THEN 'DELETE_LOCAL_BRANCH'
          WHEN 10 THEN 'DELETE_REMOTE_BRANCH'
          WHEN 11 THEN 'RECORD_FINAL_EVIDENCE' END
      AND NEW.requirement = CASE NEW.ordinal
          WHEN 9 THEN cleanup.local_branch_requirement
          WHEN 10 THEN cleanup.remote_branch_requirement ELSE 'REQUIRED' END)
BEGIN SELECT RAISE(ABORT, 'CleanupStep kind, order, or requirement is invalid'); END;
CREATE TRIGGER cleanup_step_result_fields
BEFORE UPDATE OF failure_kind, last_error, completed_at_ms ON cleanup_step
WHEN (NEW.failure_kind IS NOT OLD.failure_kind
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
  AND NEW.status IS OLD.status
  AND NOT (NEW.status = 'CLAIMED'
    AND NEW.attempt_count = OLD.attempt_count + 1
    AND NEW.failure_kind IS NULL AND NEW.last_error IS NULL
    AND NEW.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'CleanupStep result changes only at a result or claim boundary'); END;
CREATE TRIGGER cleanup_step_retry_request_delete
BEFORE DELETE ON cleanup_step_retry_request
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'Cleanup retry evidence cannot be deleted'); END;
CREATE TRIGGER cleanup_step_retry_request_insert
BEFORE INSERT ON cleanup_step_retry_request
WHEN NEW.status <> 'PENDING' OR NEW.consumed_at_ms IS NOT NULL
  OR NOT EXISTS (
      SELECT 1 FROM cleanup_step step
      JOIN cleanup_operation operation ON operation.id = step.cleanup_operation_id
      JOIN task_blocker blocker
        ON blocker.owner_id = operation.id
       AND blocker.subject_revision = CAST(step.ordinal AS TEXT)
      WHERE step.id = NEW.cleanup_step_id
        AND step.cleanup_operation_id = NEW.cleanup_operation_id
        AND step.task_id = NEW.task_id
        AND step.status = 'FAILED'
        AND step.failure_kind = 'DETERMINATE'
        AND step.attempt_count = NEW.failed_attempt
        AND step.execute_attempt_count < step.attempt_limit
        AND operation.status = 'ACTIVE'
        AND blocker.task_id = step.task_id
        AND blocker.stage_id = step.cleanup_stage_id
        AND blocker.owner_kind = 'OPERATION'
        AND blocker.status = 'OPEN')
BEGIN SELECT RAISE(ABORT, 'Cleanup retry lacks an exact retryable failure'); END;
CREATE TRIGGER cleanup_step_retry_request_update
BEFORE UPDATE ON cleanup_step_retry_request
WHEN NOT (OLD.status = 'PENDING' AND NEW.status = 'CONSUMED'
      AND NEW.id = OLD.id
      AND NEW.cleanup_step_id = OLD.cleanup_step_id
      AND NEW.cleanup_operation_id = OLD.cleanup_operation_id
      AND NEW.task_id = OLD.task_id
      AND NEW.failed_attempt = OLD.failed_attempt
      AND NEW.requested_by = OLD.requested_by
      AND NEW.reason = OLD.reason
      AND NEW.requested_at_ms = OLD.requested_at_ms
      AND NEW.consumed_at_ms >= OLD.requested_at_ms)
BEGIN SELECT RAISE(ABORT, 'Cleanup retry transition is invalid'); END;
CREATE TRIGGER cleanup_step_skip
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status = 'SKIPPED'
  AND NOT EXISTS (
      SELECT 1 FROM cleanup_step_skip_evidence evidence
      WHERE evidence.cleanup_step_id = NEW.id)
BEGIN SELECT RAISE(ABORT, 'CleanupStep skip lacks explicit inapplicability evidence'); END;
CREATE TRIGGER cleanup_step_skip_evidence_immutable
BEFORE UPDATE ON cleanup_step_skip_evidence
BEGIN SELECT RAISE(ABORT, 'Cleanup skip evidence is immutable'); END;
CREATE TRIGGER cleanup_step_skip_evidence_insert
BEFORE INSERT ON cleanup_step_skip_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM cleanup_step step
    WHERE step.id = NEW.cleanup_step_id
      AND step.requirement = 'NOT_APPLICABLE'
      AND step.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Cleanup skip requires an inapplicable requested step'); END;
CREATE TRIGGER cleanup_step_success
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status = 'SUCCEEDED'
  AND NOT EXISTS (
      SELECT 1 FROM cleanup_step_attempt_result result
      WHERE result.cleanup_step_id = NEW.id
        AND result.cleanup_operation_id = NEW.cleanup_operation_id
        AND result.task_id = NEW.task_id
        AND result.task_epoch = NEW.task_epoch
        AND result.ordinal = NEW.ordinal
        AND result.attempt = NEW.attempt_count
        AND result.claim_mode = OLD.claim_mode
        AND result.outcome = 'SUCCEEDED')
BEGIN SELECT RAISE(ABORT, 'CleanupStep success lacks exact attempt evidence'); END;
CREATE TRIGGER cleanup_step_terminal_immutable
BEFORE UPDATE ON cleanup_step
WHEN OLD.status IN ('SUCCEEDED', 'SKIPPED', 'WAIVED')
BEGIN SELECT RAISE(ABORT, 'Settled CleanupStep is immutable'); END;
CREATE TRIGGER cleanup_step_transition
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED') AND NEW.status = 'CLAIMED')
    OR (OLD.status = 'CLAIMED' AND NEW.status IN ('SUCCEEDED', 'FAILED'))
    OR (OLD.status = 'REQUESTED' AND NEW.status = 'SKIPPED')
    OR (OLD.status = 'FAILED' AND NEW.status = 'WAIVED'))
BEGIN SELECT RAISE(ABORT, 'CleanupStep transition is invalid'); END;
CREATE TRIGGER cleanup_step_waive
BEFORE UPDATE OF status ON cleanup_step
WHEN NEW.status = 'WAIVED'
  AND NOT EXISTS (
      SELECT 1 FROM cleanup_step_waiver waiver
      WHERE waiver.cleanup_step_id = NEW.id)
BEGIN SELECT RAISE(ABORT, 'CleanupStep waiver lacks explicit user evidence'); END;
CREATE TRIGGER cleanup_step_waiver_excludes_retry
BEFORE INSERT ON cleanup_step_waiver
WHEN EXISTS (
    SELECT 1 FROM cleanup_step_retry_request retry
    WHERE retry.cleanup_step_id = NEW.cleanup_step_id
      AND retry.status = 'PENDING')
BEGIN SELECT RAISE(ABORT, 'Cleanup waiver conflicts with a pending retry'); END;
CREATE TRIGGER cleanup_step_waiver_immutable
BEFORE UPDATE ON cleanup_step_waiver
BEGIN SELECT RAISE(ABORT, 'Cleanup waiver is immutable'); END;
CREATE TRIGGER cleanup_step_waiver_insert
BEFORE INSERT ON cleanup_step_waiver
WHEN NOT EXISTS (
    SELECT 1 FROM cleanup_step step
    JOIN task_blocker blocker
      ON blocker.owner_id = step.cleanup_operation_id
    WHERE step.id = NEW.cleanup_step_id
      AND step.requirement = 'OPTIONAL'
      AND step.status = 'FAILED'
      AND blocker.task_id = step.task_id
      AND blocker.stage_id = step.cleanup_stage_id
      AND blocker.owner_kind = 'OPERATION'
      AND blocker.subject_revision = CAST(step.ordinal AS TEXT)
      AND blocker.status = 'OPEN')
BEGIN SELECT RAISE(ABORT, 'Cleanup waiver requires an explicit optional failure blocker'); END;
CREATE TRIGGER cleanup_task_turn_admission
BEFORE INSERT ON task_turn
WHEN EXISTS (
    SELECT 1 FROM tasks task
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state IN (
          'CLEANING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
  AND NOT EXISTS (
    SELECT 1 FROM tasks task
    JOIN task_outcome outcome ON outcome.task_id = task.id
    WHERE task.id = NEW.task_id
      AND task.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
      AND task.epoch = NEW.task_epoch
      AND ((outcome.summary_state = 'FALLBACK'
            AND NEW.purpose = 'TASK_COMPLETION_SUMMARY'
            AND NEW.status = 'REQUESTED'
            AND NEW.trigger_stage_id IS NULL
            AND NEW.trigger_stage_generation IS NULL
            AND NOT EXISTS (
                SELECT 1 FROM task_outcome_summary_operation summary
                WHERE summary.task_outcome_id = outcome.id
                  AND summary.status IN ('REQUESTED', 'SUCCEEDED'))
            AND NOT EXISTS (
                SELECT 1 FROM task_turn existing
                WHERE existing.task_id = NEW.task_id
                  AND existing.purpose = 'TASK_COMPLETION_SUMMARY'
                  AND existing.status IN (
                    'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')))
        OR (NEW.purpose = 'TASK_BRAIN_CONVERSATION'
            AND NEW.status = 'REQUESTED'
            AND NEW.trigger_stage_id IS NULL
            AND NEW.trigger_stage_generation IS NULL)))
BEGIN SELECT RAISE(ABORT, 'Task admits no regular Turns during or after Cleanup'); END;
CREATE TRIGGER dev_report_immutable
BEFORE UPDATE ON dev_report
WHEN OLD.workflow_version = 'V2'
BEGIN SELECT RAISE(ABORT, 'V2 DevReport is immutable'); END;
CREATE TRIGGER dev_report_owner_insert
BEFORE INSERT ON dev_report
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            WHERE task.id = NEW.task_id
              AND task.workflow_version = NEW.workflow_version)
            THEN RAISE(ABORT, 'DevReport workflow version must match its Task')
        WHEN NEW.workflow_version = 'LEGACY' AND (
            NEW.local_development_stage_id IS NOT NULL
            OR NEW.task_epoch IS NOT NULL OR NEW.stage_generation IS NOT NULL
            OR NEW.stage_turn_id IS NOT NULL OR NEW.revision IS NOT NULL
            OR NEW.code_fingerprint IS NOT NULL OR NEW.head_sha IS NOT NULL
            OR NEW.base_sha IS NOT NULL OR NEW.implemented_intent IS NOT NULL
            OR NEW.commit_summary IS NOT NULL OR NEW.file_summary IS NOT NULL
            OR NEW.validation_summary IS NOT NULL OR NEW.known_risks IS NOT NULL
            OR NEW.unresolved_concerns IS NOT NULL OR NEW.context_refs IS NOT NULL
            OR NEW.source_code_fingerprint IS NOT NULL
            OR NEW.source_head_sha IS NOT NULL OR NEW.source_base_sha IS NOT NULL)
            THEN RAISE(ABORT, 'LEGACY DevReport cannot carry a V2 fence')
        WHEN NEW.workflow_version = 'V2' AND (
            NEW.local_development_stage_id IS NULL OR NEW.task_epoch IS NULL
            OR NEW.stage_generation IS NULL OR NEW.stage_turn_id IS NULL
            OR NEW.revision IS NULL OR NEW.code_fingerprint IS NULL
            OR NEW.head_sha IS NULL OR NEW.base_sha IS NULL
            OR NEW.source_code_fingerprint IS NULL
            OR NEW.source_head_sha IS NULL OR NEW.source_base_sha IS NULL
            OR NEW.implemented_intent IS NULL OR NEW.commit_summary IS NULL
            OR NEW.file_summary IS NULL OR NEW.validation_summary IS NULL
            OR NEW.known_risks IS NULL OR NEW.unresolved_concerns IS NULL
            OR NEW.context_refs IS NULL)
            THEN RAISE(ABORT, 'V2 DevReport requires its complete typed fence')
        WHEN NEW.workflow_version = 'V2' AND (
            length(NEW.code_fingerprint) = 0 OR length(NEW.head_sha) = 0
            OR length(NEW.base_sha) = 0
            OR length(NEW.source_code_fingerprint) = 0
            OR length(NEW.source_head_sha) = 0
            OR length(NEW.source_base_sha) = 0
            OR length(NEW.implemented_intent) = 0)
            THEN RAISE(ABORT, 'V2 DevReport subject must not be blank')
        WHEN NEW.workflow_version = 'V2' AND NEW.revision <> COALESCE((
            SELECT MAX(report.revision) + 1 FROM dev_report report
            WHERE report.workflow_version = 'V2'
              AND report.local_development_stage_id
                    = NEW.local_development_stage_id), 1)
            THEN RAISE(ABORT, 'DevReport revision must be the next exact revision')
        WHEN NEW.workflow_version = 'V2' AND NOT EXISTS (
            SELECT 1
            FROM local_development_stage local
            JOIN stage owner ON owner.id = local.stage_id
            JOIN tasks task ON task.id = local.task_id
            JOIN task_current_stage current ON current.stage_id = local.stage_id
            JOIN stage_turn turn ON turn.id = NEW.stage_turn_id
            WHERE local.stage_id = NEW.local_development_stage_id
              AND local.task_id = NEW.task_id
              AND local.generation = NEW.stage_generation
              AND local.opened_for_epoch = NEW.task_epoch
              AND owner.completed_at_ms IS NULL
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.task_epoch
              AND current.task_id = NEW.task_id
              AND current.stage_generation = NEW.stage_generation
              AND turn.stage_id = local.stage_id
              AND turn.stage_generation = local.generation
              AND turn.task_epoch = NEW.task_epoch
              AND turn.expected_code_fingerprint
                    = NEW.source_code_fingerprint
              AND turn.expected_head_sha = NEW.source_head_sha
              AND turn.expected_base_sha = NEW.source_base_sha
              AND turn.status = 'SUCCEEDED')
            THEN RAISE(ABORT, 'DevReport requires its exact successful StageTurn')
    END;
END;
CREATE TRIGGER dev_report_route_immutable
BEFORE UPDATE OF workflow_version, task_id, local_development_stage_id,
        task_epoch, stage_generation, stage_turn_id, revision,
        code_fingerprint, head_sha, base_sha, source_code_fingerprint,
        source_head_sha, source_base_sha ON dev_report
WHEN NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.stage_turn_id IS NOT OLD.stage_turn_id
  OR NEW.revision IS NOT OLD.revision
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.source_code_fingerprint IS NOT OLD.source_code_fingerprint
  OR NEW.source_head_sha IS NOT OLD.source_head_sha
  OR NEW.source_base_sha IS NOT OLD.source_base_sha
BEGIN SELECT RAISE(ABORT, 'DevReport route and subject are immutable'); END;
CREATE TRIGGER dispatch_delivery_claim_heartbeat_shape
BEFORE UPDATE OF heartbeat_at_ms, expires_at_ms ON dispatch_delivery_claim
WHEN NEW.heartbeat_at_ms < OLD.heartbeat_at_ms
  OR NEW.expires_at_ms < OLD.expires_at_ms
  OR NEW.expires_at_ms <= NEW.heartbeat_at_ms
BEGIN
    SELECT RAISE(ABORT, 'delivery claim heartbeat must advance with a future expiry');
END;
CREATE TRIGGER dispatch_delivery_claim_identity_immutable
BEFORE UPDATE OF ticket_id, ticket_version, claim_owner, claimed_at_ms
ON dispatch_delivery_claim
WHEN NEW.ticket_id IS NOT OLD.ticket_id
  OR NEW.ticket_version IS NOT OLD.ticket_version
  OR NEW.claim_owner IS NOT OLD.claim_owner
  OR NEW.claimed_at_ms IS NOT OLD.claimed_at_ms
BEGIN
    SELECT RAISE(ABORT, 'delivery claim identity is immutable');
END;
CREATE TRIGGER dispatch_delivery_claim_insert_fence
BEFORE INSERT ON dispatch_delivery_claim
WHEN NOT EXISTS (
    SELECT 1
    FROM dispatch_ticket d
    WHERE d.id = NEW.ticket_id
      AND d.version = NEW.ticket_version
      AND d.status = 'RESULT_PENDING'
      AND d.pending_result_outcome IS NOT NULL
      AND d.claim_owner IS NULL
      AND d.capacity_lease_id IS NULL)
BEGIN
    SELECT RAISE(ABORT, 'delivery claim requires the exact result-pending ticket version');
END;
CREATE TRIGGER dispatch_ticket_branch_sync_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind IN (
        'FETCH_COMPARE_REMOTE_BRANCH', 'REBASE_REMOTE_BRANCH',
        'VALIDATE_REMOTE_BRANCH_SYNC', 'FORCE_WITH_LEASE_REMOTE_BRANCH')
  OR NEW.callback_route IN (
        'BRANCH_SYNC_FETCH_RESULT', 'BRANCH_SYNC_REBASE_RESULT',
        'BRANCH_SYNC_CONFLICT_RESULT', 'BRANCH_SYNC_VALIDATION_RESULT',
        'BRANCH_SYNC_BRAIN_RESULT', 'BRANCH_SYNC_PUSH_RESULT')
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM branch_sync_dispatch_operation operation
        WHERE operation.operation_id = NEW.operation_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.remote_development_stage_id = NEW.stage_id
          AND operation.stage_generation = NEW.stage_generation
          AND operation.semantic_attempt = NEW.attempt
          AND operation.expected_code_fingerprint IS NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND NEW.callback_route = CASE operation.kind
              WHEN 'FETCH_COMPARE' THEN 'BRANCH_SYNC_FETCH_RESULT'
              WHEN 'MECHANICAL_REBASE' THEN 'BRANCH_SYNC_REBASE_RESULT'
              WHEN 'CONFLICT_REPAIR' THEN 'BRANCH_SYNC_CONFLICT_RESULT'
              WHEN 'VALIDATE' THEN 'BRANCH_SYNC_VALIDATION_RESULT'
              WHEN 'BRAIN_REVIEW' THEN 'BRANCH_SYNC_BRAIN_RESULT'
              WHEN 'FORCE_WITH_LEASE_PUSH' THEN 'BRANCH_SYNC_PUSH_RESULT' END
          AND NEW.operation_kind = CASE operation.kind
              WHEN 'FETCH_COMPARE' THEN 'FETCH_COMPARE_REMOTE_BRANCH'
              WHEN 'MECHANICAL_REBASE' THEN 'REBASE_REMOTE_BRANCH'
              WHEN 'CONFLICT_REPAIR' THEN 'EXECUTE_STAGE_TURN'
              WHEN 'VALIDATE' THEN 'VALIDATE_REMOTE_BRANCH_SYNC'
              WHEN 'BRAIN_REVIEW' THEN 'EXECUTE_TASK_TURN'
              WHEN 'FORCE_WITH_LEASE_PUSH' THEN 'FORCE_WITH_LEASE_REMOTE_BRANCH' END
          AND NEW.async_family = CASE operation.kind
              WHEN 'CONFLICT_REPAIR' THEN 'AGENT_TURN'
              WHEN 'BRAIN_REVIEW' THEN 'AGENT_TURN'
              WHEN 'VALIDATE' THEN 'VALIDATION'
              ELSE 'LOCAL_GIT' END
          AND NEW.owner_kind = CASE operation.kind
              WHEN 'CONFLICT_REPAIR' THEN 'STAGE_TURN'
              WHEN 'BRAIN_REVIEW' THEN 'TASK_TURN'
              ELSE 'STAGE' END
          AND NEW.owner_id = COALESCE(
              operation.stage_turn_id, operation.task_turn_id,
              operation.remote_development_stage_id)
          AND NEW.lane_mask = CASE operation.kind
              WHEN 'FETCH_COMPARE' THEN 16
              WHEN 'MECHANICAL_REBASE' THEN 16
              WHEN 'CONFLICT_REPAIR' THEN NEW.lane_mask
              WHEN 'VALIDATE' THEN 4
              WHEN 'BRAIN_REVIEW' THEN NEW.lane_mask
              WHEN 'FORCE_WITH_LEASE_PUSH' THEN 16 END
          AND (operation.kind NOT IN ('CONFLICT_REPAIR', 'BRAIN_REVIEW')
              OR NEW.lane_mask IN (1, 2))
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = CASE operation.kind
              WHEN 'VALIDATE' THEN 0
              WHEN 'BRAIN_REVIEW' THEN 0 ELSE 1 END
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Branch sync DispatchTicket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_capacity_claim_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.status IN ('CLAIMED', 'RUNNING', 'DELIVERING')
  AND NOT EXISTS (
      SELECT 1 FROM capacity_lease c
      WHERE c.id = NEW.capacity_lease_id
        AND c.ticket_id = NEW.id
        AND c.operation_id = NEW.operation_id
        AND c.workflow_source = 'V2'
        AND c.lane_mask = NEW.lane_mask
        AND c.holder = NEW.claim_owner
        AND c.released_at_ms IS NULL
        AND NEW.claim_expires_at_ms <= c.expires_at_ms)
BEGIN SELECT RAISE(ABORT, 'DispatchTicket claim requires its exact live CapacityLease'); END;
CREATE TRIGGER dispatch_ticket_capacity_claim_update
BEFORE UPDATE ON dispatch_ticket
WHEN NEW.status IN ('CLAIMED', 'RUNNING', 'DELIVERING')
  AND NOT EXISTS (
      SELECT 1 FROM capacity_lease c
      WHERE c.id = NEW.capacity_lease_id
        AND c.ticket_id = NEW.id
        AND c.operation_id = NEW.operation_id
        AND c.workflow_source = 'V2'
        AND c.lane_mask = NEW.lane_mask
        AND c.workspace_id IS NEW.workspace_id
        AND c.trunk_id IS NEW.trunk_id
        AND c.task_id IS NEW.task_id
        AND c.task_epoch IS NEW.task_epoch
        AND c.holder = NEW.claim_owner
        AND c.released_at_ms IS NULL
        AND NEW.claim_expires_at_ms <= c.expires_at_ms)
BEGIN SELECT RAISE(ABORT, 'DispatchTicket claim requires its exact live CapacityLease'); END;
CREATE TRIGGER dispatch_ticket_delivery_claim_guard
BEFORE UPDATE ON dispatch_ticket
WHEN OLD.status = 'RESULT_PENDING'
  AND EXISTS (
      SELECT 1 FROM dispatch_delivery_claim c WHERE c.ticket_id = OLD.id)
BEGIN
    SELECT RAISE(ABORT, 'release the exact delivery claim before changing its ticket');
END;
CREATE TRIGGER dispatch_ticket_external_pr_action_v289
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'APPLY_V2_EXTERNAL_PR_ACTION'
  OR NEW.callback_route = 'V2_EXTERNAL_PR_ACTION_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM external_pr_action_v289 action
        WHERE action.operation_id = NEW.operation_id
          AND action.thread_id = NEW.owner_id
          AND action.thread_id = NEW.trunk_id
          AND action.workspace_id = NEW.workspace_id
          AND action.semantic_attempt = NEW.attempt
          AND action.expected_head_sha = NEW.expected_head_sha
          AND action.expected_base_sha = NEW.expected_base_sha
          AND action.status = 'REQUESTED'
          AND NEW.operation_kind = 'APPLY_V2_EXTERNAL_PR_ACTION'
          AND NEW.async_family = 'GITHUB_EFFECT'
          AND NEW.owner_kind = 'TRUNK'
          AND NEW.callback_route = 'V2_EXTERNAL_PR_ACTION_RESULT'
          AND NEW.lane_mask = 32
          AND NEW.trunk_control = 1
          AND NEW.exclusive_task = 0
          AND NEW.writer_required = 0
          AND NEW.task_id IS NULL AND NEW.task_epoch IS NULL
          AND NEW.stage_id IS NULL AND NEW.stage_generation IS NULL
          AND NEW.expected_code_fingerprint IS NULL
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'external PR action ticket differs from authorization') END;
END;
CREATE TRIGGER dispatch_ticket_identity_immutable
BEFORE UPDATE OF operation_id, operation_kind, owner_kind, owner_id,
        callback_route, async_family, lane_mask, trunk_control, exclusive_task,
        writer_required, workspace_id,
        trunk_id, task_id, task_epoch, stage_id, stage_generation, attempt,
        expected_code_fingerprint, expected_head_sha, expected_base_sha,
        created_at_ms ON dispatch_ticket
WHEN NEW.operation_id IS NOT OLD.operation_id
  OR NEW.operation_kind IS NOT OLD.operation_kind
  OR NEW.owner_kind IS NOT OLD.owner_kind
  OR NEW.owner_id IS NOT OLD.owner_id
  OR NEW.callback_route IS NOT OLD.callback_route
  OR NEW.async_family IS NOT OLD.async_family
  OR NEW.lane_mask IS NOT OLD.lane_mask
  OR NEW.trunk_control IS NOT OLD.trunk_control
  OR NEW.exclusive_task IS NOT OLD.exclusive_task
  OR NEW.writer_required IS NOT OLD.writer_required
  OR NEW.workspace_id IS NOT OLD.workspace_id
  OR NEW.trunk_id IS NOT OLD.trunk_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.attempt IS NOT OLD.attempt
  OR NEW.expected_code_fingerprint IS NOT OLD.expected_code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'DispatchTicket identity is immutable'); END;
CREATE TRIGGER dispatch_ticket_local_stage_turn_insert
BEFORE INSERT ON dispatch_ticket
WHEN (NEW.callback_route = 'STAGE_TURN_RESULT'
      OR NEW.operation_kind = 'EXECUTE_STAGE_TURN')
  AND (EXISTS (
          SELECT 1
          FROM stage_turn turn
          JOIN stage owner ON owner.id = turn.stage_id
          WHERE turn.operation_id = NEW.operation_id
            AND owner.kind = 'LOCAL_DEVELOPMENT')
    OR EXISTS (
          SELECT 1 FROM stage owner
          WHERE owner.id = NEW.stage_id
            AND owner.kind = 'LOCAL_DEVELOPMENT'))
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM local_stage_turn_request request
        JOIN stage_turn turn ON turn.id = request.stage_turn_id
        WHERE request.stage_turn_id = NEW.owner_id
          AND turn.operation_id = NEW.operation_id
          AND turn.attempt = NEW.attempt
          AND turn.task_epoch = NEW.task_epoch
          AND turn.stage_id = NEW.stage_id
          AND turn.stage_generation = NEW.stage_generation
          AND turn.expected_code_fingerprint = NEW.expected_code_fingerprint
          AND turn.expected_head_sha = NEW.expected_head_sha
          AND turn.expected_base_sha = NEW.expected_base_sha
          AND NEW.operation_kind = 'EXECUTE_STAGE_TURN'
          AND NEW.async_family = 'AGENT_TURN'
          AND NEW.owner_kind = 'STAGE_TURN'
          AND NEW.callback_route = 'STAGE_TURN_RESULT'
          AND NEW.lane_mask IN (1, 2)
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1 AND NEW.writer_required = 1
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Local StageTurn ticket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_local_validation_insert
BEFORE INSERT ON dispatch_ticket
WHEN (NEW.callback_route = 'STAGE_VALIDATION_RESULT'
      OR NEW.operation_kind = 'VALIDATE_LOCAL_DEVELOPMENT')
  AND (EXISTS (
          SELECT 1
          FROM validation_operation operation
          JOIN stage owner
            ON owner.id = operation.local_development_stage_id
          WHERE operation.operation_id = NEW.operation_id
            AND owner.kind = 'LOCAL_DEVELOPMENT')
    OR EXISTS (
          SELECT 1 FROM stage owner
          WHERE owner.id = NEW.stage_id
            AND owner.kind = 'LOCAL_DEVELOPMENT'))
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM validation_operation operation
        WHERE operation.operation_id = NEW.operation_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.local_development_stage_id = NEW.stage_id
          AND operation.stage_generation = NEW.stage_generation
          AND operation.semantic_attempt = NEW.attempt
          AND operation.code_fingerprint = NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND NEW.operation_kind = 'VALIDATE_LOCAL_DEVELOPMENT'
          AND NEW.async_family = 'VALIDATION'
          AND NEW.owner_kind = 'STAGE'
          AND NEW.owner_id = NEW.stage_id
          AND NEW.callback_route = 'STAGE_VALIDATION_RESULT'
          AND NEW.lane_mask = 4
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 0
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Local Validation ticket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_manual_pr_validation_v279
BEFORE INSERT ON dispatch_ticket
WHEN NEW.callback_route = 'MANUAL_PR_VALIDATION_RESULT'
  OR NEW.operation_kind = 'VALIDATE_PR_MANUALLY'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM manual_pr_validation_operation operation
        WHERE operation.id = NEW.operation_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.code_fingerprint = NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND operation.status = 'REQUESTED'
          AND NEW.operation_kind = 'VALIDATE_PR_MANUALLY'
          AND NEW.async_family = 'VALIDATION'
          AND NEW.owner_kind = 'TASK'
          AND NEW.owner_id = NEW.task_id
          AND NEW.callback_route = 'MANUAL_PR_VALIDATION_RESULT'
          AND NEW.lane_mask = 4
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 0
          AND NEW.stage_id IS NULL
          AND NEW.stage_generation IS NULL
          AND NEW.attempt = 1
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Manual PR validation DispatchTicket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_owner_insert
BEFORE INSERT ON dispatch_ticket
BEGIN
    SELECT CASE
        WHEN NEW.task_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM tasks t
            JOIN threads h ON h.id = t.thread_id
            WHERE t.id = NEW.task_id
              AND t.workflow_version = 'V2'
              AND t.epoch = NEW.task_epoch
              AND t.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'DispatchTicket Task scope is invalid')
        WHEN NEW.stage_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM stage s
            WHERE s.id = NEW.stage_id
              AND s.task_id = NEW.task_id
              AND s.generation = NEW.stage_generation)
            THEN RAISE(ABORT, 'DispatchTicket Stage scope is invalid')
        WHEN NEW.owner_kind = 'TRUNK' AND NOT EXISTS (
            SELECT 1 FROM threads x
            WHERE x.id = NEW.owner_id
              AND x.id = NEW.trunk_id
              AND x.workspace_id IS NEW.workspace_id
              AND x.turn_version = 'V2'
              AND NEW.task_id IS NULL AND NEW.stage_id IS NULL)
            THEN RAISE(ABORT, 'DispatchTicket Trunk owner is invalid')
        WHEN NEW.owner_kind = 'TASK' AND NOT EXISTS (
            SELECT 1 FROM tasks x JOIN threads h ON h.id = x.thread_id
            WHERE x.id = NEW.owner_id AND x.workflow_version = 'V2'
              AND x.id = NEW.task_id AND x.epoch = NEW.task_epoch
              AND x.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'DispatchTicket Task owner fence is invalid')
        WHEN NEW.owner_kind = 'STAGE' AND NOT EXISTS (
            SELECT 1
            FROM stage s
            JOIN tasks t ON t.id = s.task_id
            JOIN threads h ON h.id = t.thread_id
            WHERE s.id = NEW.owner_id
              AND s.id = NEW.stage_id
              AND s.generation = NEW.stage_generation
              AND t.id = NEW.task_id
              AND t.epoch = NEW.task_epoch
              AND t.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'DispatchTicket Stage owner fence is invalid')
        WHEN NEW.owner_kind = 'THREAD_TURN' AND NOT EXISTS (
            SELECT 1 FROM thread_turn x JOIN threads h ON h.id = x.trunk_id
            WHERE x.id = NEW.owner_id AND x.operation_id = NEW.operation_id
              AND x.trunk_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id
              AND NEW.task_id IS NULL AND NEW.stage_id IS NULL)
            THEN RAISE(ABORT, 'DispatchTicket ThreadTurn owner is invalid')
        WHEN NEW.owner_kind = 'TASK_TURN' AND NOT EXISTS (
            SELECT 1
            FROM task_turn x
            JOIN tasks t ON t.id = x.task_id
            JOIN threads h ON h.id = t.thread_id
            WHERE x.id = NEW.owner_id AND x.operation_id = NEW.operation_id
              AND x.task_id = NEW.task_id AND x.task_epoch = NEW.task_epoch
              AND t.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id
              AND (NEW.stage_id IS NULL OR EXISTS (
                  SELECT 1 FROM stage s
                  WHERE s.id = NEW.stage_id
                    AND s.task_id = NEW.task_id
                    AND s.generation = NEW.stage_generation)))
            THEN RAISE(ABORT, 'DispatchTicket TaskTurn owner fence is invalid')
        WHEN NEW.owner_kind = 'STAGE_TURN' AND NOT EXISTS (
            SELECT 1
            FROM stage_turn x
            JOIN stage s ON s.id = x.stage_id
            JOIN tasks t ON t.id = s.task_id
            JOIN threads h ON h.id = t.thread_id
            WHERE x.id = NEW.owner_id AND x.operation_id = NEW.operation_id
              AND x.task_epoch = NEW.task_epoch
              AND x.stage_id = NEW.stage_id
              AND x.stage_generation = NEW.stage_generation
              AND s.task_id = NEW.task_id
              AND t.thread_id = NEW.trunk_id
              AND h.workspace_id IS NEW.workspace_id)
            THEN RAISE(ABORT, 'DispatchTicket StageTurn owner fence is invalid')
        WHEN NEW.owner_kind = 'REVIEW_ASSIGNMENT_TURN' AND NOT EXISTS (
            SELECT 1
            FROM review_assignment_turn turn
            JOIN review_assignment assignment ON assignment.id = turn.assignment_id
            JOIN review_round round ON round.id = assignment.round_id
            JOIN review_session session ON session.id = round.session_id
            LEFT JOIN tasks task ON task.id = session.owner_task_id
            WHERE turn.id = NEW.owner_id
              AND turn.operation_id = NEW.operation_id
              AND NEW.workspace_id IS session.workspace_id
              AND NEW.trunk_id IS session.owner_thread_id
              AND NEW.task_id IS session.owner_task_id
              AND NEW.task_epoch IS CASE
                  WHEN session.owner_task_id IS NULL THEN NULL ELSE task.epoch END
              AND NEW.stage_id IS NULL
              AND (session.owner_task_id IS NULL
                OR task.workflow_version = 'V2'))
            THEN RAISE(ABORT, 'DispatchTicket review Turn owner is invalid')
    END;
END;
CREATE TRIGGER dispatch_ticket_pending_fence_immutable
BEFORE UPDATE OF pending_result_outcome, pending_result_payload,
        pending_result_evidence, pending_result_error,
        pending_result_task_epoch, pending_result_stage_id,
        pending_result_stage_generation, pending_result_operation_id,
        pending_result_attempt, pending_result_expected_code_fingerprint,
        pending_result_expected_head_sha, pending_result_expected_base_sha
ON dispatch_ticket
WHEN OLD.pending_result_outcome IS NOT NULL
  AND NEW.pending_result_outcome IS NOT NULL
  AND (NEW.pending_result_outcome IS NOT OLD.pending_result_outcome
    OR NEW.pending_result_payload IS NOT OLD.pending_result_payload
    OR NEW.pending_result_evidence IS NOT OLD.pending_result_evidence
    OR NEW.pending_result_error IS NOT OLD.pending_result_error
    OR NEW.pending_result_task_epoch IS NOT OLD.pending_result_task_epoch
    OR NEW.pending_result_stage_id IS NOT OLD.pending_result_stage_id
    OR NEW.pending_result_stage_generation IS NOT OLD.pending_result_stage_generation
    OR NEW.pending_result_operation_id IS NOT OLD.pending_result_operation_id
    OR NEW.pending_result_attempt IS NOT OLD.pending_result_attempt
    OR NEW.pending_result_expected_code_fingerprint
        IS NOT OLD.pending_result_expected_code_fingerprint
    OR NEW.pending_result_expected_head_sha IS NOT OLD.pending_result_expected_head_sha
    OR NEW.pending_result_expected_base_sha IS NOT OLD.pending_result_expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'pending DispatchResult is immutable'); END;
CREATE TRIGGER dispatch_ticket_pending_fence_insert
BEFORE INSERT ON dispatch_ticket
WHEN (NEW.pending_result_outcome IS NULL AND (
        NEW.pending_result_task_epoch IS NOT NULL
        OR NEW.pending_result_stage_id IS NOT NULL
        OR NEW.pending_result_stage_generation IS NOT NULL
        OR NEW.pending_result_operation_id IS NOT NULL
        OR NEW.pending_result_attempt IS NOT NULL
        OR NEW.pending_result_expected_code_fingerprint IS NOT NULL
        OR NEW.pending_result_expected_head_sha IS NOT NULL
        OR NEW.pending_result_expected_base_sha IS NOT NULL))
  OR (NEW.pending_result_outcome IS NOT NULL AND (
        NEW.pending_result_operation_id IS NULL
        OR length(NEW.pending_result_operation_id) = 0
        OR NEW.pending_result_attempt IS NULL
        OR NEW.pending_result_attempt <= 0
        OR NEW.pending_result_task_epoch IS NOT NULL
            AND NEW.pending_result_task_epoch <= 0
        OR (NEW.pending_result_stage_id IS NULL)
            <> (NEW.pending_result_stage_generation IS NULL)
        OR NEW.pending_result_stage_generation IS NOT NULL
            AND NEW.pending_result_stage_generation <= 0))
BEGIN SELECT RAISE(ABORT, 'pending DispatchResult requires its complete raw fence'); END;
CREATE TRIGGER dispatch_ticket_pending_fence_update
BEFORE UPDATE ON dispatch_ticket
WHEN (NEW.pending_result_outcome IS NULL AND (
        NEW.pending_result_task_epoch IS NOT NULL
        OR NEW.pending_result_stage_id IS NOT NULL
        OR NEW.pending_result_stage_generation IS NOT NULL
        OR NEW.pending_result_operation_id IS NOT NULL
        OR NEW.pending_result_attempt IS NOT NULL
        OR NEW.pending_result_expected_code_fingerprint IS NOT NULL
        OR NEW.pending_result_expected_head_sha IS NOT NULL
        OR NEW.pending_result_expected_base_sha IS NOT NULL))
  OR (NEW.pending_result_outcome IS NOT NULL AND (
        NEW.pending_result_operation_id IS NULL
        OR length(NEW.pending_result_operation_id) = 0
        OR NEW.pending_result_attempt IS NULL
        OR NEW.pending_result_attempt <= 0
        OR NEW.pending_result_task_epoch IS NOT NULL
            AND NEW.pending_result_task_epoch <= 0
        OR (NEW.pending_result_stage_id IS NULL)
            <> (NEW.pending_result_stage_generation IS NULL)
        OR NEW.pending_result_stage_generation IS NOT NULL
            AND NEW.pending_result_stage_generation <= 0))
BEGIN SELECT RAISE(ABORT, 'pending DispatchResult requires its complete raw fence'); END;
CREATE TRIGGER dispatch_ticket_pending_result_terminal_clear
BEFORE UPDATE ON dispatch_ticket
WHEN OLD.pending_result_outcome IS NOT NULL
  AND NEW.pending_result_outcome IS NULL
  AND NOT (
      (OLD.pending_result_outcome = 'SUCCEEDED' AND NEW.status = 'SUCCEEDED')
      OR (OLD.pending_result_outcome IN ('FAILED', 'INDETERMINATE')
          AND NEW.status = 'FAILED')
      OR (OLD.pending_result_outcome = 'CANCELED' AND NEW.status = 'CANCELED'))
BEGIN SELECT RAISE(ABORT, 'terminal status must match the pending DispatchResult'); END;
CREATE TRIGGER dispatch_ticket_readiness_assistance_v273
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'APPLY_READINESS_ASSISTANCE'
   OR NEW.callback_route = 'READINESS_ASSISTANCE_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM remote_readiness_assistance_v273 assistance
        JOIN tasks task ON task.id = assistance.task_id
        JOIN threads trunk ON trunk.id = task.thread_id
        WHERE assistance.operation_id = NEW.operation_id
          AND assistance.status = 'REQUESTED'
          AND NEW.operation_kind = 'APPLY_READINESS_ASSISTANCE'
          AND NEW.async_family = 'GITHUB_EFFECT'
          AND NEW.owner_kind = 'STAGE'
          AND NEW.owner_id = assistance.remote_stage_id
          AND NEW.callback_route = 'READINESS_ASSISTANCE_RESULT'
          AND NEW.lane_mask = 32
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 0
          AND NEW.workspace_id = trunk.workspace_id
          AND NEW.trunk_id = task.thread_id
          AND NEW.task_id = assistance.task_id
          AND NEW.task_epoch = assistance.task_epoch
          AND NEW.stage_id = assistance.remote_stage_id
          AND NEW.stage_generation = assistance.stage_generation
          AND NEW.attempt = assistance.semantic_attempt
          AND NEW.expected_code_fingerprint IS NULL
          AND NEW.expected_head_sha = assistance.expected_head_sha
          AND NEW.expected_base_sha = assistance.expected_base_sha
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT,
        'Readiness assistance ticket is stale or unowned') END;
END;
CREATE TRIGGER dispatch_ticket_remote_feedback_brain_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'EXECUTE_TASK_TURN'
  AND EXISTS (
      SELECT 1 FROM task_turn turn
      WHERE turn.id = NEW.owner_id
        AND turn.purpose = 'REMOTE_FEEDBACK_BRAIN_REVIEW')
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM task_turn turn
        LEFT JOIN task_turn_user_wait_continuation_v266 continuation
          ON continuation.successor_turn_id = turn.id
        JOIN remote_feedback_brain_episode episode
          ON episode.task_turn_id = COALESCE(
              continuation.logical_turn_id, turn.id)
        WHERE turn.id = NEW.owner_id
          AND turn.operation_id = NEW.operation_id
          AND turn.attempt = NEW.attempt
          AND turn.task_id = NEW.task_id
          AND turn.task_epoch = NEW.task_epoch
          AND turn.trigger_stage_id = NEW.stage_id
          AND turn.trigger_stage_generation = NEW.stage_generation
          AND turn.expected_code_fingerprint =
              NEW.expected_code_fingerprint
          AND turn.expected_head_sha = NEW.expected_head_sha
          AND turn.expected_base_sha = NEW.expected_base_sha
          AND NEW.async_family = 'AGENT_TURN'
          AND NEW.owner_kind = 'TASK_TURN'
          AND NEW.callback_route = 'REMOTE_FEEDBACK_BRAIN_RESULT'
          AND NEW.lane_mask IN (1, 2)
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 0
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Remote feedback Brain ticket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_remote_feedback_effect_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'APPLY_REMOTE_FEEDBACK_EFFECT'
   OR NEW.callback_route = 'REMOTE_FEEDBACK_EFFECT_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM remote_feedback_effect_step step
        JOIN remote_feedback_authorization authorization
          ON authorization.id = step.remote_feedback_authorization_id
        JOIN remote_feedback_batch batch ON batch.id = step.remote_feedback_batch_id
        WHERE NEW.operation_id = step.id || ':attempt:' || (step.attempt_count + 1)
          AND step.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
          AND batch.status IN ('AUTHORIZED', 'APPLYING')
          AND NEW.owner_kind = 'STAGE'
          AND NEW.owner_id = batch.remote_development_stage_id
          AND NEW.task_id = batch.task_id
          AND NEW.task_epoch = batch.task_epoch
          AND NEW.stage_id = batch.remote_development_stage_id
          AND NEW.stage_generation = batch.stage_generation
          AND NEW.attempt = step.attempt_count + 1
          AND NEW.expected_head_sha = authorization.head_sha
          AND NEW.expected_base_sha = authorization.base_sha
          AND NEW.async_family = CASE WHEN step.kind = 'PUSH_COMMITS'
              THEN 'LOCAL_GIT' ELSE 'GITHUB_EFFECT' END
          AND NEW.lane_mask = CASE WHEN step.kind = 'PUSH_COMMITS' THEN 16 ELSE 32 END
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = CASE WHEN step.kind = 'PUSH_COMMITS' THEN 1 ELSE 0 END
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'Remote feedback effect ticket is not exact') END;
END;
