CREATE TRIGGER dispatch_ticket_state_shape_insert
BEFORE INSERT ON dispatch_ticket
BEGIN
    SELECT CASE WHEN
        (NEW.status IN ('CLAIMED', 'RUNNING', 'DELIVERING') AND (
            NEW.claim_purpose IS NULL OR NEW.claim_owner IS NULL
            OR NEW.capacity_lease_id IS NULL OR NEW.claim_expires_at_ms IS NULL))
        OR (NEW.status NOT IN ('CLAIMED', 'RUNNING', 'DELIVERING') AND (
            NEW.claim_purpose IS NOT NULL OR NEW.claim_owner IS NOT NULL
            OR NEW.capacity_lease_id IS NOT NULL OR NEW.claim_expires_at_ms IS NOT NULL))
        OR ((NEW.status IN ('RESULT_PENDING', 'DELIVERING')
                OR (NEW.status = 'CLAIMED' AND NEW.claim_purpose = 'DELIVER'))
            AND NEW.pending_result_outcome IS NULL)
        OR (NEW.status NOT IN ('RESULT_PENDING', 'DELIVERING')
            AND NOT (NEW.status = 'CLAIMED' AND NEW.claim_purpose = 'DELIVER')
            AND NEW.pending_result_outcome IS NOT NULL)
        OR (NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED') AND (
            NEW.completed_at_ms IS NULL OR NEW.delivery_acceptance IS NULL))
        OR (NEW.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED') AND (
            NEW.completed_at_ms IS NOT NULL OR NEW.delivery_acceptance IS NOT NULL))
    THEN RAISE(ABORT, 'DispatchTicket state evidence is incomplete') END;
END;
CREATE TRIGGER dispatch_ticket_state_shape_update
BEFORE UPDATE ON dispatch_ticket
BEGIN
    SELECT CASE WHEN
        (NEW.status IN ('CLAIMED', 'RUNNING', 'DELIVERING') AND (
            NEW.claim_purpose IS NULL OR NEW.claim_owner IS NULL
            OR NEW.capacity_lease_id IS NULL OR NEW.claim_expires_at_ms IS NULL))
        OR (NEW.status NOT IN ('CLAIMED', 'RUNNING', 'DELIVERING') AND (
            NEW.claim_purpose IS NOT NULL OR NEW.claim_owner IS NOT NULL
            OR NEW.capacity_lease_id IS NOT NULL OR NEW.claim_expires_at_ms IS NOT NULL))
        OR ((NEW.status IN ('RESULT_PENDING', 'DELIVERING')
                OR (NEW.status = 'CLAIMED' AND NEW.claim_purpose = 'DELIVER'))
            AND NEW.pending_result_outcome IS NULL)
        OR (NEW.status NOT IN ('RESULT_PENDING', 'DELIVERING')
            AND NOT (NEW.status = 'CLAIMED' AND NEW.claim_purpose = 'DELIVER')
            AND NEW.pending_result_outcome IS NOT NULL)
        OR (NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED') AND (
            NEW.completed_at_ms IS NULL OR NEW.delivery_acceptance IS NULL))
        OR (NEW.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED') AND (
            NEW.completed_at_ms IS NOT NULL OR NEW.delivery_acceptance IS NOT NULL))
    THEN RAISE(ABORT, 'DispatchTicket state evidence is incomplete') END;
END;
CREATE TRIGGER dispatch_ticket_task_review_snapshot_v286
BEFORE INSERT ON dispatch_ticket
WHEN NEW.callback_route = 'TASK_REVIEW_SNAPSHOT_RESULT'
  OR NEW.operation_kind = 'CAPTURE_TASK_REVIEW_SNAPSHOT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM task_review_snapshot_operation_v286 operation
        WHERE operation.id = NEW.operation_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.code_fingerprint = NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND operation.status = 'REQUESTED'
          AND NEW.operation_kind = 'CAPTURE_TASK_REVIEW_SNAPSHOT'
          AND NEW.async_family = 'LOCAL_GIT'
          AND NEW.owner_kind = 'TASK'
          AND NEW.owner_id = NEW.task_id
          AND NEW.callback_route = 'TASK_REVIEW_SNAPSHOT_RESULT'
          AND NEW.lane_mask = 16
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 1
          AND NEW.stage_id IS NULL
          AND NEW.stage_generation IS NULL
          AND NEW.attempt = 1
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT,
        'Task review snapshot DispatchTicket is not exact') END;
END;
CREATE TRIGGER dispatch_ticket_terminal_immutable
BEFORE UPDATE ON dispatch_ticket
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED')
 AND NOT (
    OLD.status = 'CANCELED' AND NEW.status = 'REQUESTED'
    AND NEW.version = OLD.version + 1
    AND NEW.cancel_requested_at_ms IS NULL
    AND NEW.pending_result_outcome IS NULL
    AND NEW.delivery_acceptance IS NULL
    AND NEW.completed_at_ms IS NULL
    AND EXISTS (
        SELECT 1
        FROM stage_resume_async_successor_v272 resume
        JOIN stage_resume_rearm_intent_v257 intent
          ON intent.handoff_id = resume.handoff_id
        WHERE resume.status = 'PREPARED'
          AND resume.dispatch_ticket_id = OLD.id
          AND resume.operation_id = OLD.operation_id
          AND resume.dispatch_attempt = OLD.attempt
          AND intent.status = 'PENDING'
          AND intent.task_id = OLD.task_id
          AND intent.task_epoch = OLD.task_epoch
          AND intent.stage_id = OLD.stage_id
          AND intent.stage_generation = OLD.stage_generation
          AND ((resume.owner_kind = 'PUBLISH_RECOVERY'
                AND OLD.operation_kind = 'PUBLISH_LOCAL_DEVELOPMENT'
                AND OLD.async_family = 'GITHUB_EFFECT'
                AND OLD.callback_route = 'STAGE_PUBLISH_RESULT')
            OR (resume.owner_kind = 'MERGE_RECOVERY'
                AND OLD.operation_kind = 'MERGE_REMOTE_PULL_REQUEST'
                AND OLD.async_family = 'MERGE'
                AND OLD.callback_route = 'REMOTE_MERGE_RESULT'))))
BEGIN SELECT RAISE(ABORT, 'terminal DispatchTicket is immutable'); END;
CREATE TRIGGER dispatch_ticket_v2_quality_issue_publish_v285
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'PUBLISH_V2_QUALITY_ISSUE'
   OR NEW.callback_route = 'V2_QUALITY_ISSUE_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM v2_quality_issue_publish_v285 publish
        WHERE publish.operation_id = NEW.operation_id
          AND publish.status = 'REQUESTED'
          AND NEW.operation_kind = 'PUBLISH_V2_QUALITY_ISSUE'
          AND NEW.async_family = 'GITHUB_EFFECT'
          AND NEW.owner_kind = 'TASK'
          AND NEW.owner_id = publish.task_id
          AND NEW.callback_route = 'V2_QUALITY_ISSUE_RESULT'
          AND NEW.lane_mask = 32
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 0
          AND NEW.workspace_id = publish.workspace_id
          AND NEW.trunk_id = publish.trunk_id
          AND NEW.task_id = publish.task_id
          AND NEW.task_epoch = publish.task_epoch
          AND NEW.stage_id IS NULL
          AND NEW.stage_generation IS NULL
          AND NEW.attempt = 1
          AND NEW.expected_code_fingerprint IS NULL
          AND NEW.expected_head_sha IS NULL
          AND NEW.expected_base_sha IS NULL
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT,
        'quality issue publish ticket is stale or unowned') END;
END;
CREATE TRIGGER dispatch_ticket_v2_user_remote_action_v270
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'APPLY_V2_USER_REMOTE_ACTION'
   OR NEW.callback_route = 'V2_USER_REMOTE_ACTION_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM v2_user_remote_action_v270 action
        JOIN tasks task ON task.id = action.task_id
        JOIN threads trunk ON trunk.id = task.thread_id
        WHERE action.operation_id = NEW.operation_id
          AND action.status = 'REQUESTED'
          AND NEW.operation_kind = 'APPLY_V2_USER_REMOTE_ACTION'
          AND NEW.async_family = 'GITHUB_EFFECT'
          AND NEW.owner_kind = 'TASK'
          AND NEW.owner_id = action.task_id
          AND NEW.callback_route = 'V2_USER_REMOTE_ACTION_RESULT'
          AND NEW.lane_mask = CASE action.semantic_action
              WHEN 'TRIGGER_CI_EMPTY_COMMIT' THEN 48 ELSE 32 END
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = CASE action.semantic_action
              WHEN 'TRIGGER_CI_EMPTY_COMMIT' THEN 1 ELSE 0 END
          AND NEW.workspace_id = trunk.workspace_id
          AND NEW.trunk_id = task.thread_id
          AND NEW.task_id = action.task_id
          AND NEW.task_epoch = action.task_epoch
          AND NEW.stage_id = action.remote_stage_id
          AND NEW.stage_generation = action.stage_generation
          AND NEW.attempt = action.semantic_attempt
          AND NEW.expected_code_fingerprint
              IS action.expected_code_fingerprint
          AND NEW.expected_head_sha = action.expected_head_sha
          AND NEW.expected_base_sha = action.expected_base_sha
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'V2 user remote action ticket is stale or unowned') END;
END;
CREATE TRIGGER dispatch_ticket_version_monotonic
BEFORE UPDATE ON dispatch_ticket
WHEN NEW.version <> OLD.version + 1
BEGIN SELECT RAISE(ABORT, 'DispatchTicket version must advance'); END;
CREATE TRIGGER external_pr_action_baseline_v289
BEFORE UPDATE OF recovery_baseline_json ON external_pr_action_v289
WHEN OLD.recovery_baseline_json IS NOT NULL
  OR NEW.recovery_baseline_json IS NULL
  OR OLD.status <> 'CLAIMED'
  OR NEW.status <> OLD.status
BEGIN SELECT RAISE(ABORT,
    'external PR action recovery baseline is immutable'); END;
CREATE TRIGGER external_pr_action_delete_v289
BEFORE DELETE ON external_pr_action_v289
WHEN NOT EXISTS (
    SELECT 1 FROM v2_trunk_purge_authorization_v269 authorization
    WHERE authorization.trunk_id = OLD.thread_id)
BEGIN SELECT RAISE(ABORT, 'external PR action cannot be deleted'); END;
CREATE TRIGGER external_pr_action_dispatch_delete_v289
BEFORE DELETE ON external_pr_action_dispatch_v289
WHEN NOT EXISTS (
    SELECT 1 FROM external_pr_action_v289 action
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = action.thread_id
    WHERE action.id = OLD.action_id)
BEGIN SELECT RAISE(ABORT, 'external PR action dispatch cannot be deleted'); END;
CREATE TRIGGER external_pr_action_dispatch_insert_v289
BEFORE INSERT ON external_pr_action_dispatch_v289
WHEN NOT EXISTS (
    SELECT 1 FROM external_pr_action_v289 action
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    WHERE action.id = NEW.action_id
      AND action.operation_id = NEW.operation_id
      AND ticket.operation_id = NEW.operation_id
      AND ticket.owner_kind = 'TRUNK'
      AND ticket.owner_id = action.thread_id
      AND ticket.trunk_id = action.thread_id
      AND ticket.operation_kind = 'APPLY_V2_EXTERNAL_PR_ACTION'
      AND ticket.callback_route = 'V2_EXTERNAL_PR_ACTION_RESULT'
      AND ticket.expected_head_sha = action.expected_head_sha
      AND ticket.expected_base_sha = action.expected_base_sha
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'external PR action dispatch is invalid'); END;
CREATE TRIGGER external_pr_action_dispatch_update_v289
BEFORE UPDATE ON external_pr_action_dispatch_v289
BEGIN SELECT RAISE(ABORT, 'external PR action dispatch is immutable'); END;
CREATE TRIGGER external_pr_action_draft_delete_v289
BEFORE DELETE ON external_pr_action_draft_v289
WHEN NOT EXISTS (
    SELECT 1 FROM external_pr_action_v289 action
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = action.thread_id
    WHERE action.id = OLD.action_id)
BEGIN SELECT RAISE(ABORT, 'external PR action draft cannot be deleted'); END;
CREATE TRIGGER external_pr_action_draft_insert_v289
BEFORE INSERT ON external_pr_action_draft_v289
WHEN NOT EXISTS (
    SELECT 1
    FROM external_pr_action_v289 action
    JOIN pr_comment comment ON comment.id = NEW.comment_id
    WHERE action.id = NEW.action_id
      AND action.semantic_action = 'SUBMIT_REVIEW'
      AND comment.pr_id = action.pr_id
      AND comment.origin = 'local'
      AND comment.parent_comment_id IS NULL
      AND comment.published_at_ms IS NULL
      AND comment.stripped_on_push_at_ms IS NULL
      AND comment.resolved_at_ms IS NULL
      AND comment.dismissed_at_ms IS NULL
      AND comment.scope = NEW.scope
      AND comment.file_path IS NEW.file_path
      AND comment.line_number IS NEW.line_number
      AND COALESCE(comment.side,
            CASE WHEN comment.scope = 'file-line' THEN 'RIGHT' END) IS NEW.side
      AND comment.start_line IS NEW.start_line
      AND comment.start_side IS NEW.start_side
      AND comment.body = NEW.body
      AND comment.finding_id IS NEW.finding_id)
  OR EXISTS (
    SELECT 1 FROM external_pr_action_draft_v289 reserved
    JOIN external_pr_action_v289 action ON action.id = reserved.action_id
    WHERE reserved.comment_id = NEW.comment_id
      AND (action.status NOT IN ('SUCCEEDED', 'CANCELED', 'ABANDONED')
        OR action.finalized_at_ms IS NULL))
BEGIN SELECT RAISE(ABORT, 'external review draft changed before authorization'); END;
CREATE TRIGGER external_pr_action_draft_update_v289
BEFORE UPDATE ON external_pr_action_draft_v289
BEGIN SELECT RAISE(ABORT, 'external PR action draft is immutable'); END;
CREATE TRIGGER external_pr_action_finalize_v289
BEFORE UPDATE OF finalized_at_ms ON external_pr_action_v289
WHEN NEW.finalized_at_ms IS NOT NULL AND (
    OLD.finalized_at_ms IS NOT NULL
    OR NEW.status NOT IN ('SUCCEEDED', 'CANCELED', 'ABANDONED')
    OR NOT EXISTS (
        SELECT 1 FROM external_pr_action_dispatch_v289 link
        JOIN dispatch_ticket ticket ON ticket.id = link.dispatch_ticket_id
        WHERE link.action_id = NEW.id
          AND ticket.delivery_acceptance = 'ACCEPTED'
          AND ticket.status IN ('SUCCEEDED', 'FAILED', 'CANCELED')))
BEGIN SELECT RAISE(ABORT,
    'external PR action finalization requires accepted delivery'); END;
CREATE TRIGGER external_pr_action_identity_v289
BEFORE UPDATE OF id, operation_id, thread_id, workspace_id, command_id,
    pr_id, review_id, kind, semantic_action, remote_repository_id,
    head_repository_id, remote_pr_number, branch_name, expected_head_sha,
    expected_base_sha, payload_json, payload_digest, handled_action,
    semantic_attempt, attempt_limit, authorized_at_ms
ON external_pr_action_v289
BEGIN SELECT RAISE(ABORT, 'external PR action identity is immutable'); END;
CREATE TRIGGER external_pr_action_insert_v289
BEFORE INSERT ON external_pr_action_v289
WHEN NOT EXISTS (
    SELECT 1
    FROM pr local_pr
    JOIN workspace_repos binding
      ON lower(binding.repo_full_name) = lower(local_pr.repo)
    JOIN threads trunk
      ON trunk.workspace_id = binding.workspace_id
     AND trunk.pr_ref = lower(local_pr.repo) || '#' || local_pr.remote_pr_number
    JOIN pull_requests cached
      ON lower(cached.repo) = lower(local_pr.repo)
     AND cached.number = local_pr.remote_pr_number
    JOIN pr_detail detail ON detail.pr_id = cached.id
    WHERE local_pr.id = NEW.pr_id
      AND local_pr.task_id IS NULL
      AND local_pr.origin = 'external'
      AND local_pr.repo = NEW.remote_repository_id COLLATE NOCASE
      AND local_pr.remote_pr_number = NEW.remote_pr_number
      AND trunk.id = NEW.thread_id
      AND trunk.workspace_id = NEW.workspace_id
      AND trunk.flow = 'review'
      AND trunk.turn_version = 'V2'
      AND trunk.lifecycle_state IN ('ACTIVE', 'IDLE')
      AND NOT EXISTS (SELECT 1 FROM tasks task WHERE task.thread_id = trunk.id)
      AND detail.base_repo = NEW.remote_repository_id COLLATE NOCASE
      AND detail.head_repo = NEW.head_repository_id COLLATE NOCASE
      AND detail.head_ref = NEW.branch_name
      AND detail.head_sha = NEW.expected_head_sha
      AND detail.base_sha = NEW.expected_base_sha
      AND trim(detail.head_sha) <> '' AND trim(detail.base_sha) <> '')
  OR (NEW.review_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM review_session review
    WHERE review.id = NEW.review_id
      AND review.pr_id = NEW.pr_id
      AND review.workspace_id = NEW.workspace_id
      AND review.owner_thread_id = NEW.thread_id
      AND review.base_commit = NEW.expected_base_sha
      AND review.reviewed_head_commit = NEW.expected_head_sha))
BEGIN SELECT RAISE(ABORT,
    'external PR action lacks its exact cached V2 REVIEW Trunk subject'); END;
CREATE TRIGGER external_pr_action_transition_v289
BEFORE UPDATE OF status ON external_pr_action_v289
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status IN ('CLAIMED', 'CANCELED', 'ABANDONED'))
    OR (OLD.status = 'CLAIMED' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'INDETERMINATE', 'CANCELED', 'ABANDONED')))
BEGIN SELECT RAISE(ABORT, 'external PR action transition is invalid'); END;
CREATE TRIGGER issue_origin_immutable
BEFORE UPDATE OF origin ON issue_origin
WHEN NEW.origin <> OLD.origin
BEGIN
    SELECT RAISE(ABORT, 'issue origin is immutable');
END;
CREATE TRIGGER legacy_task_creation_retired
BEFORE INSERT ON tasks
WHEN NEW.workflow_version <> 'V2'
BEGIN
    SELECT RAISE(ABORT, 'LEGACY Task creation is retired');
END;
CREATE TRIGGER local_brain_turn_delivery_receipt_immutable
BEFORE UPDATE ON local_brain_turn_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Local Brain delivery receipt is immutable'); END;
CREATE TRIGGER local_brain_turn_delivery_receipt_insert
BEFORE INSERT ON local_brain_turn_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM task_turn delivered
    LEFT JOIN task_turn_user_wait_continuation_v266 continuation
      ON continuation.successor_turn_id = delivered.id
    JOIN brain_review_episode episode
      ON episode.task_turn_id = COALESCE(
          continuation.logical_turn_id, delivered.id)
    WHERE episode.id = NEW.brain_review_episode_id
      AND delivered.id = NEW.task_turn_id
      AND delivered.operation_id = NEW.operation_id
      AND delivered.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
      AND episode.status IN ('SUCCEEDED', 'FAILED', 'CANCELED',
          'SUPERSEDED', 'BUDGET_EXHAUSTED')
      AND episode.verdict IS NEW.verdict
      AND (NEW.blocker_id IS NULL OR EXISTS (
          SELECT 1 FROM task_blocker blocker
          WHERE blocker.id = NEW.blocker_id
            AND blocker.task_id = episode.task_id
            AND blocker.blocker_type = 'BRAIN_BUDGET_EXHAUSTED'))
      AND (NEW.next_stage_turn_request_id IS NULL OR EXISTS (
          SELECT 1 FROM local_stage_turn_request request
          WHERE request.id = NEW.next_stage_turn_request_id
            AND request.brain_review_episode_id = episode.id)))
BEGIN SELECT RAISE(ABORT, 'Local Brain delivery receipt is not exact'); END;
CREATE TRIGGER local_development_stage_immutable
BEFORE UPDATE ON local_development_stage
BEGIN SELECT RAISE(ABORT, 'Local Development Stage identity is immutable'); END;
CREATE TRIGGER local_development_stage_owner_insert
BEFORE INSERT ON local_development_stage
WHEN NOT EXISTS (
    SELECT 1
    FROM stage s
    JOIN tasks t ON t.id = s.task_id
    JOIN task_current_stage c ON c.stage_id = s.id
    WHERE s.id = NEW.stage_id
      AND s.task_id = NEW.task_id
      AND s.kind = 'LOCAL_DEVELOPMENT'
      AND s.generation = NEW.generation
      AND s.completed_at_ms IS NULL
      AND t.workflow_version = 'V2'
      AND t.lifecycle_state = 'ACTIVE'
      AND t.epoch = NEW.opened_for_epoch
      AND c.task_id = NEW.task_id
      AND c.stage_generation = NEW.generation)
BEGIN
    SELECT RAISE(ABORT, 'Local Development subtype must match its exact open V2 Stage');
END;
CREATE TRIGGER local_feedback_batch_address_proof
BEFORE UPDATE OF status ON local_feedback_batch
WHEN NEW.status = 'ADDRESSED'
  AND (NOT EXISTS (
      SELECT 1 FROM stage_turn st
      WHERE st.id = NEW.stage_turn_id AND st.status = 'SUCCEEDED')
    OR EXISTS (
      SELECT 1
      FROM local_feedback_batch_item item
      JOIN local_review_comment_revision revision
        ON revision.id = item.comment_revision_id
      WHERE item.batch_id = NEW.id
        AND revision.state NOT IN ('ADDRESSED', 'DISMISSED')))
BEGIN SELECT RAISE(ABORT, 'addressed LocalFeedbackBatch lacks exact Turn/revision proof'); END;
CREATE TRIGGER local_feedback_batch_dispatch
BEFORE UPDATE OF status ON local_feedback_batch
WHEN NEW.status = 'DISPATCHED'
  AND (NEW.stage_turn_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM stage_turn st
      JOIN tasks t ON t.id = NEW.task_id
      JOIN task_current_stage c ON c.task_id = t.id
      WHERE st.id = NEW.stage_turn_id
        AND st.stage_id = NEW.local_development_stage_id
        AND st.stage_generation = NEW.stage_generation
        AND st.task_epoch = NEW.task_epoch
        AND st.status IN ('REQUESTED', 'QUEUED')
        AND t.epoch = NEW.task_epoch AND t.lifecycle_state = 'ACTIVE'
        AND c.stage_id = NEW.local_development_stage_id
        AND c.stage_generation = NEW.stage_generation))
BEGIN SELECT RAISE(ABORT, 'dispatched LocalFeedbackBatch requires its exact live StageTurn'); END;
CREATE TRIGGER local_feedback_batch_freeze
BEFORE UPDATE OF status ON local_feedback_batch
WHEN NEW.status = 'FROZEN'
  AND (NEW.frozen_at_ms IS NULL
    OR NOT EXISTS (
        SELECT 1 FROM local_feedback_batch_item item WHERE item.batch_id = NEW.id)
    OR EXISTS (
        SELECT 1
        FROM local_feedback_batch_item item
        JOIN local_review_comment_revision revision
          ON revision.id = item.comment_revision_id
        WHERE item.batch_id = NEW.id
          AND (revision.state <> 'SUBMITTED'
            OR revision.code_fingerprint <> NEW.code_fingerprint
            OR revision.head_sha <> NEW.head_sha
            OR revision.base_sha <> NEW.base_sha)))
BEGIN SELECT RAISE(ABORT, 'frozen LocalFeedbackBatch requires exact submitted revisions'); END;
CREATE TRIGGER local_feedback_batch_identity_immutable
BEFORE UPDATE OF local_development_stage_id, task_id, task_epoch,
        stage_generation, pr_id, dev_report_id, source_submission_id, sequence,
        code_fingerprint, head_sha, base_sha, created_at_ms ON local_feedback_batch
WHEN NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.pr_id IS NOT OLD.pr_id OR NEW.dev_report_id IS NOT OLD.dev_report_id
  OR NEW.source_submission_id IS NOT OLD.source_submission_id
  OR NEW.sequence IS NOT OLD.sequence
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.head_sha IS NOT OLD.head_sha OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch subject is immutable'); END;
CREATE TRIGGER local_feedback_batch_insert
BEFORE INSERT ON local_feedback_batch
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'BUILDING'
            THEN RAISE(ABORT, 'LocalFeedbackBatch must start BUILDING')
        WHEN NEW.sequence <> COALESCE((
            SELECT MAX(b.sequence) + 1 FROM local_feedback_batch b
            WHERE b.local_development_stage_id = NEW.local_development_stage_id), 1)
            THEN RAISE(ABORT, 'LocalFeedbackBatch sequence must be exact')
        WHEN NOT EXISTS (
            SELECT 1
            FROM local_development_stage l
            JOIN stage s ON s.id = l.stage_id
            JOIN tasks t ON t.id = l.task_id
            JOIN task_current_stage c ON c.stage_id = l.stage_id
            JOIN pr p ON p.id = NEW.pr_id
            JOIN dev_report r ON r.id = NEW.dev_report_id
            WHERE l.stage_id = NEW.local_development_stage_id
              AND l.task_id = NEW.task_id
              AND l.opened_for_epoch = NEW.task_epoch
              AND l.generation = NEW.stage_generation
              AND s.completed_at_ms IS NULL
              AND t.lifecycle_state = 'ACTIVE' AND t.epoch = NEW.task_epoch
              AND c.task_id = NEW.task_id
              AND c.stage_generation = NEW.stage_generation
              AND p.task_id = NEW.task_id AND p.origin = 'task'
              AND r.workflow_version = 'V2'
              AND r.local_development_stage_id = l.stage_id
              AND r.task_id = NEW.task_id AND r.task_epoch = NEW.task_epoch
              AND r.stage_generation = NEW.stage_generation
              AND r.code_fingerprint = NEW.code_fingerprint
              AND r.head_sha = NEW.head_sha AND r.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = r.local_development_stage_id
                    AND newer.revision > r.revision))
            THEN RAISE(ABORT, 'LocalFeedbackBatch does not match the current local subject')
        WHEN NEW.source_submission_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM local_review_submission legacy
            WHERE legacy.id = NEW.source_submission_id
              AND legacy.task_id = NEW.task_id
              AND legacy.pr_id = NEW.pr_id)
            THEN RAISE(ABORT, 'LocalFeedbackBatch legacy source does not match')
    END;
END;
CREATE TRIGGER local_feedback_batch_item_delete_guard
BEFORE DELETE ON local_feedback_batch_item
WHEN EXISTS (
    SELECT 1 FROM local_feedback_batch batch
    WHERE batch.id = OLD.batch_id AND batch.status <> 'BUILDING')
  AND NOT EXISTS (
    SELECT 1
    FROM local_feedback_batch batch
    JOIN tasks task ON task.id = batch.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE batch.id = OLD.batch_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'frozen LocalFeedbackBatch items cannot be deleted'); END;
CREATE TRIGGER local_feedback_batch_item_immutable
BEFORE UPDATE ON local_feedback_batch_item
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch item is immutable'); END;
CREATE TRIGGER local_feedback_batch_item_insert
BEFORE INSERT ON local_feedback_batch_item
WHEN NOT EXISTS (
    SELECT 1
    FROM local_feedback_batch batch
    JOIN local_review_comment_revision revision
      ON revision.id = NEW.comment_revision_id
    WHERE batch.id = NEW.batch_id
      AND batch.status = 'BUILDING'
      AND revision.thread_id = NEW.thread_id
      AND revision.task_id = batch.task_id
      AND revision.local_development_stage_id = batch.local_development_stage_id
      AND revision.task_epoch = batch.task_epoch
      AND revision.stage_generation = batch.stage_generation
      AND revision.dev_report_id = batch.dev_report_id
      AND revision.code_fingerprint = batch.code_fingerprint
      AND revision.head_sha = batch.head_sha
      AND revision.base_sha = batch.base_sha
      AND revision.body_digest = NEW.body_digest
      AND revision.body = NEW.frozen_body)
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch item is not an exact comment snapshot'); END;
CREATE TRIGGER local_feedback_batch_state_fields
BEFORE UPDATE OF frozen_at_ms, completed_at_ms, error_message
ON local_feedback_batch
WHEN NEW.status IS OLD.status
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch state fields require a transition'); END;
CREATE TRIGGER local_feedback_batch_terminal_immutable
BEFORE UPDATE ON local_feedback_batch
WHEN OLD.status IN ('ADDRESSED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal LocalFeedbackBatch is immutable'); END;
CREATE TRIGGER local_feedback_batch_transition
BEFORE UPDATE OF status ON local_feedback_batch
WHEN NOT (
    (OLD.status = 'BUILDING' AND NEW.status IN ('FROZEN', 'CANCELED'))
    OR (OLD.status = 'FROZEN' AND NEW.status IN (
        'QUEUED', 'DISPATCHED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'QUEUED' AND NEW.status IN (
        'DISPATCHED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'ADDRESSED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'illegal LocalFeedbackBatch transition'); END;
CREATE TRIGGER local_feedback_batch_turn_bind
BEFORE UPDATE OF stage_turn_id ON local_feedback_batch
WHEN OLD.stage_turn_id IS NOT NULL
  OR NEW.stage_turn_id IS NULL
  OR OLD.status NOT IN ('FROZEN', 'QUEUED')
  OR NOT EXISTS (
      SELECT 1 FROM stage_turn st
      WHERE st.id = NEW.stage_turn_id
        AND st.stage_id = NEW.local_development_stage_id
        AND st.stage_generation = NEW.stage_generation
        AND st.task_epoch = NEW.task_epoch
        AND st.purpose = 'ADDRESS_LOCAL_FEEDBACK'
        AND st.status IN ('REQUESTED', 'QUEUED')
        AND st.expected_code_fingerprint = NEW.code_fingerprint
        AND st.expected_head_sha = NEW.head_sha
        AND st.expected_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch requires one exact StageTurn'); END;
CREATE TRIGGER local_feedback_batch_v230_digest_update
BEFORE UPDATE OF content_digest ON local_feedback_batch
WHEN NOT (
    OLD.status = 'BUILDING' AND NEW.status = 'FROZEN'
    AND OLD.content_digest IS NULL AND NEW.content_digest IS NOT NULL
    AND length(trim(NEW.content_digest)) > 0
    AND EXISTS (
        SELECT 1 FROM local_feedback_batch_digest_v230 digest
        WHERE digest.batch_id = NEW.id AND digest.item_count > 0
          AND digest.first_position = 1
          AND digest.last_position = digest.item_count
          AND digest.content_digest = NEW.content_digest))
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch digest must freeze exact ordered items'); END;
CREATE TRIGGER local_feedback_batch_v230_freeze
BEFORE UPDATE OF status ON local_feedback_batch
WHEN NEW.status = 'FROZEN'
  AND NOT EXISTS (
      SELECT 1 FROM local_feedback_batch_digest_v230 digest
      WHERE digest.batch_id = NEW.id AND digest.item_count > 0
        AND digest.first_position = 1
        AND digest.last_position = digest.item_count
        AND digest.content_digest = NEW.content_digest)
BEGIN SELECT RAISE(ABORT, 'frozen LocalFeedbackBatch lacks canonical content digest'); END;
CREATE TRIGGER local_feedback_batch_v230_insert_digest
BEFORE INSERT ON local_feedback_batch
WHEN NEW.content_digest IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'LocalFeedbackBatch digest is assigned only at freeze'); END;
CREATE TRIGGER local_initial_implementation_receipt_immutable
BEFORE UPDATE ON local_initial_implementation_receipt
BEGIN SELECT RAISE(ABORT, 'initial Local implementation receipt is immutable'); END;
CREATE TRIGGER local_initial_implementation_receipt_insert
BEFORE INSERT ON local_initial_implementation_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM local_development_stage local
    JOIN plan_approval approval ON approval.id = NEW.plan_approval_id
    JOIN plan_revision revision ON revision.id = approval.plan_revision_id
    JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
    JOIN local_stage_turn_request request
      ON request.id = NEW.stage_turn_request_id
    JOIN stage_turn turn ON turn.id = request.stage_turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.ticket_id
    JOIN stage_initial_result_request initial
      ON initial.stage_id = local.stage_id
    WHERE local.stage_id = NEW.local_development_stage_id
      AND local.task_id = NEW.task_id
      AND plan.task_id = NEW.task_id
      AND request.local_development_stage_id = local.stage_id
      AND request.task_id = NEW.task_id
      AND request.kind = 'IMPLEMENTATION'
      AND request.queue_mode = 'IMMEDIATE'
      AND request.stage_turn_id = NEW.stage_turn_id
      AND turn.operation_id = NEW.operation_id
      AND ticket.operation_id = NEW.operation_id
      AND ticket.owner_kind = 'STAGE_TURN'
      AND ticket.owner_id = NEW.stage_turn_id
      AND ticket.callback_route = 'STAGE_TURN_RESULT'
      AND initial.turn_owner_kind = 'STAGE_TURN'
      AND initial.turn_id = NEW.stage_turn_id
      AND initial.pending_operation_id = NEW.operation_id)
BEGIN SELECT RAISE(ABORT, 'initial Local implementation receipt is not exact'); END;
CREATE TRIGGER local_review_agent_request_identity_immutable
BEFORE UPDATE OF id, review_id, review_round_id, pr_id, task_id, task_epoch,
        local_development_stage_id, stage_generation, dev_report_id,
        code_fingerprint, head_sha, base_sha, mode, task_blocker_id,
        requested_by, requested_at_ms
ON local_review_agent_request
BEGIN SELECT RAISE(ABORT, 'Local AgentReview request subject is immutable'); END;
CREATE TRIGGER local_review_agent_request_insert
BEFORE INSERT ON local_review_agent_request
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'Local AgentReview request must start REQUESTED')
        WHEN NOT EXISTS (
            SELECT 1
            FROM review_session review
            JOIN review_round requested_round
              ON requested_round.id = NEW.review_round_id
            JOIN pr pull_request ON pull_request.id = review.pr_id
            JOIN tasks task ON task.id = NEW.task_id
            JOIN task_current_stage current ON current.task_id = task.id
            JOIN stage owner ON owner.id = current.stage_id
            JOIN local_development_stage local ON local.stage_id = owner.id
            JOIN dev_report report ON report.id = NEW.dev_report_id
            JOIN task_current_code_subject_v230 code ON code.task_id = task.id
            WHERE review.id = NEW.review_id
              AND review.pr_id = NEW.pr_id
              AND review.owner_task_id = NEW.task_id
              AND review.status = 'ACTIVE'
              AND review.reviewed_head_commit = NEW.head_sha
              AND requested_round.session_id = review.id
              AND requested_round.start_commit = NEW.head_sha
              AND requested_round.status IN ('QUEUED', 'RUNNING')
              AND pull_request.id = NEW.pr_id
              AND pull_request.task_id = NEW.task_id
              AND pull_request.origin = 'task'
              AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.task_epoch
              AND current.stage_id = NEW.local_development_stage_id
              AND current.stage_generation = NEW.stage_generation
              AND owner.kind = 'LOCAL_DEVELOPMENT'
              AND owner.generation = NEW.stage_generation
              AND owner.checkpoint = 'LOCAL_REVIEW'
              AND owner.completed_at_ms IS NULL
              AND local.task_id = NEW.task_id
              AND local.generation = NEW.stage_generation
              AND local.opened_for_epoch = NEW.task_epoch
              AND report.workflow_version = 'V2'
              AND report.task_id = NEW.task_id
              AND report.local_development_stage_id = NEW.local_development_stage_id
              AND report.task_epoch = NEW.task_epoch
              AND report.stage_generation = NEW.stage_generation
              AND report.code_fingerprint = NEW.code_fingerprint
              AND report.head_sha = NEW.head_sha
              AND report.base_sha = NEW.base_sha
              AND code.code_fingerprint = NEW.code_fingerprint
              AND code.head_sha = NEW.head_sha
              AND code.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision)
              AND EXISTS (
                  SELECT 1 FROM brain_review_episode brain
                  WHERE brain.task_id = NEW.task_id
                    AND brain.local_development_stage_id = NEW.local_development_stage_id
                    AND brain.task_epoch = NEW.task_epoch
                    AND brain.stage_generation = NEW.stage_generation
                    AND brain.dev_report_id = NEW.dev_report_id
                    AND brain.code_fingerprint = NEW.code_fingerprint
                    AND brain.expected_head_sha = NEW.head_sha
                    AND brain.expected_base_sha = NEW.base_sha
                    AND ((brain.status = 'SUCCEEDED'
                          AND brain.verdict = 'APPROVED'
                          AND brain.unresolved_finding_count = 0)
                      OR brain.status = 'BUDGET_EXHAUSTED')))
            THEN RAISE(ABORT, 'Local AgentReview request subject is stale')
        WHEN NEW.mode = 'BLOCKING' AND NOT EXISTS (
            SELECT 1 FROM task_blocker blocker
            WHERE blocker.id = NEW.task_blocker_id
              AND blocker.task_id = NEW.task_id
              AND blocker.stage_id = NEW.local_development_stage_id
              AND blocker.owner_kind = 'STAGE'
              AND blocker.owner_id = NEW.local_development_stage_id
              AND blocker.subject_revision = NEW.id
              AND blocker.blocker_type = 'LOCAL_AGENT_REVIEW_BLOCKING'
              AND blocker.status = 'OPEN')
            THEN RAISE(ABORT, 'blocking Local AgentReview lacks its exact blocker')
    END;
END;
CREATE TRIGGER local_review_agent_request_state_fields
BEFORE UPDATE OF completed_at_ms, completion_evidence
ON local_review_agent_request
WHEN NEW.status IS OLD.status
BEGIN SELECT RAISE(ABORT, 'Local AgentReview completion requires a transition'); END;
CREATE TRIGGER local_review_agent_request_terminal_immutable
BEFORE UPDATE ON local_review_agent_request
WHEN OLD.status IN ('IMPORTED', 'CANCELED', 'STALE')
BEGIN SELECT RAISE(ABORT, 'terminal Local AgentReview request is immutable'); END;
CREATE TRIGGER local_review_agent_request_transition
BEFORE UPDATE OF status ON local_review_agent_request
WHEN OLD.status <> 'REQUESTED'
  OR NEW.status NOT IN ('IMPORTED', 'CANCELED', 'STALE')
  OR NEW.completed_at_ms IS NULL
  OR NEW.completed_at_ms < OLD.requested_at_ms
  OR NEW.completion_evidence IS NULL
  OR length(trim(NEW.completion_evidence)) = 0
BEGIN SELECT RAISE(ABORT, 'illegal Local AgentReview request transition'); END;
CREATE TRIGGER local_review_comment_address_fence
BEFORE UPDATE OF state ON local_review_comment_revision
WHEN NEW.state = 'ADDRESSED'
  AND NOT EXISTS (
      SELECT 1
      FROM local_feedback_batch_item item
      JOIN local_feedback_batch batch ON batch.id = item.batch_id
      JOIN stage_turn st ON st.id = batch.stage_turn_id
      WHERE item.comment_revision_id = NEW.id
        AND batch.status = 'DISPATCHED'
        AND st.status = 'SUCCEEDED'
        AND st.expected_code_fingerprint = NEW.code_fingerprint
        AND st.expected_head_sha = NEW.head_sha
        AND st.expected_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'only the exact successful feedback Turn may address a revision'); END;
CREATE TRIGGER local_review_comment_content_immutable
BEFORE UPDATE OF thread_id, task_id, local_development_stage_id, task_epoch,
        stage_generation, dev_report_id, revision, previous_revision_id,
        author_kind, body, body_digest, code_fingerprint, head_sha, base_sha,
        created_at_ms ON local_review_comment_revision
WHEN NEW.thread_id IS NOT OLD.thread_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.dev_report_id IS NOT OLD.dev_report_id
  OR NEW.revision IS NOT OLD.revision
  OR NEW.previous_revision_id IS NOT OLD.previous_revision_id
  OR NEW.author_kind IS NOT OLD.author_kind
  OR NEW.body IS NOT OLD.body OR NEW.body_digest IS NOT OLD.body_digest
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.head_sha IS NOT OLD.head_sha OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'CommentRevision content and subject are immutable'); END;
CREATE TRIGGER local_review_comment_revision_insert
BEFORE INSERT ON local_review_comment_revision
BEGIN
    SELECT CASE
        WHEN NEW.revision <> COALESCE((
            SELECT MAX(r.revision) + 1
            FROM local_review_comment_revision r
            WHERE r.thread_id = NEW.thread_id), 1)
            THEN RAISE(ABORT, 'CommentRevision must be the next exact thread revision')
        WHEN (NEW.revision = 1) <> (NEW.previous_revision_id IS NULL)
            THEN RAISE(ABORT, 'CommentRevision predecessor shape is invalid')
        WHEN NEW.previous_revision_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM local_review_comment_revision previous
            WHERE previous.id = NEW.previous_revision_id
              AND previous.thread_id = NEW.thread_id
              AND previous.revision = NEW.revision - 1)
            THEN RAISE(ABORT, 'CommentRevision predecessor is not exact')
        WHEN NOT EXISTS (
            SELECT 1
            FROM local_review_thread thread
            JOIN dev_report report ON report.id = NEW.dev_report_id
            WHERE thread.id = NEW.thread_id
              AND thread.task_id = NEW.task_id
              AND thread.local_development_stage_id = NEW.local_development_stage_id
              AND thread.task_epoch = NEW.task_epoch
              AND thread.stage_generation = NEW.stage_generation
              AND report.workflow_version = 'V2'
              AND report.task_id = NEW.task_id
              AND report.local_development_stage_id = NEW.local_development_stage_id
              AND report.task_epoch = NEW.task_epoch
              AND report.stage_generation = NEW.stage_generation
              AND report.code_fingerprint = NEW.code_fingerprint
              AND report.head_sha = NEW.head_sha
              AND report.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision))
            THEN RAISE(ABORT, 'CommentRevision does not match the latest DevReport subject')
    END;
END;
CREATE TRIGGER local_review_comment_state_fields
BEFORE UPDATE OF state_version, state_changed_at_ms,
        resolution_reason, terminal_at_ms ON local_review_comment_revision
WHEN NEW.state IS OLD.state
BEGIN SELECT RAISE(ABORT, 'CommentRevision state fields require a state transition'); END;
CREATE TRIGGER local_review_comment_state_transition
BEFORE UPDATE OF state ON local_review_comment_revision
WHEN NEW.state_version <> OLD.state_version + 1
  OR NEW.state_changed_at_ms < OLD.state_changed_at_ms
  OR NOT (
      (OLD.state = 'DRAFT' AND NEW.state IN (
          'PENDING', 'SUBMITTED', 'DISMISSED', 'SUPERSEDED'))
      OR (OLD.state = 'PENDING' AND NEW.state IN (
          'SUBMITTED', 'DISMISSED', 'SUPERSEDED'))
      OR (OLD.state = 'SUBMITTED' AND NEW.state IN ('ADDRESSED', 'DISMISSED')))
BEGIN SELECT RAISE(ABORT, 'illegal CommentRevision state transition'); END;
CREATE TRIGGER local_review_comment_terminal_immutable
BEFORE UPDATE ON local_review_comment_revision
WHEN OLD.state IN ('ADDRESSED', 'DISMISSED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal CommentRevision is immutable'); END;
CREATE TRIGGER local_review_imported_finding_delete_guard
BEFORE DELETE ON local_review_imported_finding
WHEN EXISTS (
    SELECT 1 FROM local_review_agent_request request
    WHERE request.id = OLD.request_id)
  AND NOT EXISTS (
    SELECT 1
    FROM local_review_agent_request request
    JOIN tasks task ON task.id = request.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE request.id = OLD.request_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'imported Local review finding cannot be deleted'); END;
CREATE TRIGGER local_review_imported_finding_immutable
BEFORE UPDATE ON local_review_imported_finding
BEGIN SELECT RAISE(ABORT, 'imported Local review finding is immutable'); END;
CREATE TRIGGER local_review_imported_finding_insert
BEFORE INSERT ON local_review_imported_finding
WHEN NOT EXISTS (
    SELECT 1
    FROM local_review_agent_request request
    JOIN review_round requested_round
      ON requested_round.id = request.review_round_id
    JOIN finding finding ON finding.id = NEW.finding_id
    JOIN review_round round ON round.id = finding.round_id
    JOIN local_review_thread thread ON thread.id = NEW.thread_id
    JOIN local_review_comment_revision revision
      ON revision.id = NEW.comment_revision_id
    WHERE request.id = NEW.request_id
      AND request.status = 'REQUESTED'
      AND requested_round.session_id = request.review_id
      AND requested_round.status LIKE 'COMPLETED%'
      AND requested_round.end_commit = request.head_sha
      AND finding.session_id = request.review_id
      AND finding.round_id = request.review_round_id
      AND lower(finding.lifecycle_status) <> 'dropped'
      AND finding.last_checked_commit = request.head_sha
      AND round.session_id = request.review_id
      AND round.status LIKE 'COMPLETED%'
      AND round.end_commit = request.head_sha
      AND thread.pr_id = request.pr_id
      AND thread.task_id = request.task_id
      AND thread.local_development_stage_id
            = request.local_development_stage_id
      AND thread.task_epoch = request.task_epoch
      AND thread.stage_generation = request.stage_generation
      AND thread.source = CASE request.mode
          WHEN 'BLOCKING' THEN 'BLOCKING_REVIEW'
          ELSE 'ADVISORY_REVIEW' END
      AND revision.thread_id = thread.id
      AND revision.task_id = request.task_id
      AND revision.local_development_stage_id
            = request.local_development_stage_id
      AND revision.task_epoch = request.task_epoch
      AND revision.stage_generation = request.stage_generation
      AND revision.dev_report_id = request.dev_report_id
      AND revision.code_fingerprint = request.code_fingerprint
      AND revision.head_sha = request.head_sha
      AND revision.base_sha = request.base_sha
      AND revision.author_kind = thread.source
      AND revision.state = 'PENDING')
BEGIN SELECT RAISE(ABORT, 'imported finding does not match its exact completed review'); END;
CREATE TRIGGER local_review_thread_immutable
BEFORE UPDATE ON local_review_thread
BEGIN SELECT RAISE(ABORT, 'LocalReviewThread is immutable'); END;
CREATE TRIGGER local_review_thread_owner_insert
BEFORE INSERT ON local_review_thread
WHEN NOT EXISTS (
    SELECT 1
    FROM pr p
    JOIN tasks t ON t.id = p.task_id
    JOIN local_development_stage l ON l.task_id = t.id
    JOIN stage s ON s.id = l.stage_id
    WHERE p.id = NEW.pr_id
      AND p.origin = 'task'
      AND p.task_id = NEW.task_id
      AND t.workflow_version = 'V2'
      AND t.lifecycle_state = 'ACTIVE'
      AND t.epoch = NEW.task_epoch
      AND l.stage_id = NEW.local_development_stage_id
      AND l.generation = NEW.stage_generation
      AND l.opened_for_epoch = NEW.task_epoch
      AND s.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'LocalReviewThread requires its exact private local PR subject'); END;
CREATE TRIGGER local_stage_command_receipt_immutable
BEFORE UPDATE ON local_stage_command_receipt
BEGIN SELECT RAISE(ABORT, 'Local Stage command receipt is immutable'); END;
CREATE TRIGGER local_stage_command_receipt_insert
BEFORE INSERT ON local_stage_command_receipt
BEGIN
    SELECT CASE
        WHEN NEW.cause NOT IN ('REQUEST_LOCAL_RESULT', 'REPLACE_LOCAL_RESULT',
                'CLEAR_LOCAL_RESULT', 'ACCEPT_LOCAL_CODE_RESULT',
                'BEGIN_LOCAL_VALIDATION',
                'ACCEPT_BRAIN_BUDGET_EXHAUSTION')
          OR NEW.returned_kind <> 'LOCAL_DEVELOPMENT'
          OR NEW.actor IS NULL OR length(NEW.actor) = 0
          OR NEW.proof_id IS NULL OR length(NEW.proof_id) = 0
          OR NEW.disposition NOT IN ('APPLIED', 'SUPERSEDED')
          OR NOT EXISTS (
              SELECT 1 FROM stage owner JOIN tasks task ON task.id = owner.task_id
              WHERE owner.id = NEW.stage_id AND owner.task_id = NEW.task_id
                AND owner.kind = 'LOCAL_DEVELOPMENT'
                AND owner.generation = NEW.returned_generation
                AND task.workflow_version = 'V2')
          OR EXISTS (SELECT 1 FROM stage_command_receipt shared
                     WHERE shared.stage_id = NEW.stage_id
                       AND shared.command_id = NEW.command_id)
          OR (NEW.disposition = 'APPLIED' AND NOT EXISTS (
              SELECT 1 FROM stage_transition transition
              WHERE transition.stage_id = NEW.stage_id
                AND transition.command_id = NEW.command_id
                AND transition.generation = NEW.returned_generation
                AND transition.to_checkpoint = NEW.returned_checkpoint
                AND transition.stage_version = NEW.returned_version
                AND transition.cause = NEW.cause
                AND transition.actor = NEW.actor))
            THEN RAISE(ABORT, 'Local Stage receipt owner or transition is invalid')
        WHEN NEW.cause IN ('REQUEST_LOCAL_RESULT', 'BEGIN_LOCAL_VALIDATION',
                'ACCEPT_BRAIN_BUDGET_EXHAUSTION') AND (
            NEW.expected_task_epoch IS NULL
            OR NEW.expected_stage_generation IS NULL
            OR NEW.expected_stage_version IS NULL
            OR NEW.returned_version <> NEW.expected_stage_version + 1)
            THEN RAISE(ABORT, 'Local structural receipt fence is incomplete')
        WHEN NEW.cause IN ('REPLACE_LOCAL_RESULT', 'CLEAR_LOCAL_RESULT',
                'ACCEPT_LOCAL_CODE_RESULT') AND (
            NEW.expected_task_epoch IS NOT NULL
            OR NEW.expected_stage_generation IS NOT NULL
            OR NEW.expected_stage_version IS NOT NULL
            OR NEW.source_checkpoint IS NOT NULL)
            THEN RAISE(ABORT, 'Local result receipt invented a structural fence')
        WHEN NEW.cause IN ('REQUEST_LOCAL_RESULT', 'REPLACE_LOCAL_RESULT',
                'CLEAR_LOCAL_RESULT', 'ACCEPT_LOCAL_CODE_RESULT') AND (
            NEW.subject_operation_id IS NULL
            OR NEW.subject_task_epoch IS NULL
            OR NEW.subject_stage_id <> NEW.stage_id
            OR NEW.subject_stage_generation <> NEW.returned_generation
            OR NEW.subject_attempt IS NULL OR NEW.subject_attempt < 1)
            THEN RAISE(ABORT, 'Local result receipt lacks its complete subject')
        WHEN NEW.cause IN ('BEGIN_LOCAL_VALIDATION',
                'ACCEPT_BRAIN_BUDGET_EXHAUSTION')
          AND NEW.subject_operation_id IS NOT NULL
            THEN RAISE(ABORT, 'Local structural proof cannot carry a result subject')
        WHEN NEW.cause = 'REQUEST_LOCAL_RESULT' AND (
            NEW.source_checkpoint <> NEW.returned_checkpoint
            OR NEW.returned_pending_operation_id <> NEW.subject_operation_id
            OR NEW.returned_pending_task_epoch <> NEW.subject_task_epoch
            OR NEW.returned_pending_stage_id <> NEW.subject_stage_id
            OR NEW.returned_pending_stage_generation
                <> NEW.subject_stage_generation
            OR NEW.returned_pending_attempt <> NEW.subject_attempt
            OR NEW.returned_pending_code_fingerprint
                IS NOT NEW.subject_expected_code_fingerprint
            OR NEW.returned_pending_head_sha
                IS NOT NEW.subject_expected_head_sha
            OR NEW.returned_pending_base_sha
                IS NOT NEW.subject_expected_base_sha
            OR NOT EXISTS (
                SELECT 1 FROM dispatch_ticket ticket
                WHERE ticket.operation_id = NEW.subject_operation_id
                  AND ticket.task_id = NEW.task_id
                  AND ticket.task_epoch = NEW.subject_task_epoch
                  AND ticket.stage_id = NEW.stage_id
                  AND ticket.stage_generation = NEW.subject_stage_generation
                  AND ticket.attempt = NEW.subject_attempt
                  AND ticket.expected_code_fingerprint
                        IS NEW.subject_expected_code_fingerprint
                  AND ticket.expected_head_sha IS NEW.subject_expected_head_sha
                  AND ticket.expected_base_sha IS NEW.subject_expected_base_sha
                  AND ticket.status = 'REQUESTED'
                  AND ((ticket.callback_route = 'STAGE_TURN_RESULT'
                        AND EXISTS (SELECT 1 FROM local_stage_turn_request request
                            JOIN stage_turn turn ON turn.id = request.stage_turn_id
                            WHERE request.id = NEW.proof_id
                              AND turn.operation_id = ticket.operation_id))
                    OR (ticket.callback_route = 'STAGE_VALIDATION_RESULT'
                        AND EXISTS (SELECT 1 FROM validation_operation operation
                            WHERE operation.id = NEW.proof_id
                              AND operation.operation_id = ticket.operation_id)))))
            THEN RAISE(ABORT, 'Local requested result lacks its exact durable work')
        WHEN NEW.cause = 'REPLACE_LOCAL_RESULT' AND NOT EXISTS (
                SELECT 1
                FROM local_stage_turn_request replacement
                JOIN stage_turn next ON next.id = replacement.stage_turn_id
                JOIN local_stage_turn_request previous
                  ON previous.stage_turn_id = replacement.predecessor_turn_id
                JOIN stage_turn old ON old.id = previous.stage_turn_id
                WHERE replacement.id = NEW.proof_id
                  AND old.operation_id = NEW.subject_operation_id
                  AND replacement.task_id = NEW.task_id
                  AND replacement.local_development_stage_id = NEW.stage_id
                  AND replacement.task_epoch = NEW.subject_task_epoch
                  AND replacement.stage_generation = NEW.subject_stage_generation
                  AND next.operation_id <> old.operation_id
                  AND (old.status IN (
                          'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
                    OR previous.cancellation_requested_at_ms IS NOT NULL))
            THEN RAISE(ABORT, 'Local replacement result lacks its exact queue edge')
        WHEN NEW.cause = 'REPLACE_LOCAL_RESULT'
          AND NEW.disposition = 'APPLIED' AND (
            NEW.returned_pending_operation_id IS NULL
            OR NOT EXISTS (
                SELECT 1
                FROM local_stage_turn_request replacement
                JOIN stage_turn next ON next.id = replacement.stage_turn_id
                JOIN dispatch_ticket ticket ON ticket.operation_id = next.operation_id
                WHERE replacement.id = NEW.proof_id
                  AND next.operation_id = NEW.returned_pending_operation_id
                  AND next.attempt = NEW.returned_pending_attempt
                  AND next.expected_code_fingerprint
                        IS NEW.returned_pending_code_fingerprint
                  AND next.expected_head_sha IS NEW.returned_pending_head_sha
                  AND next.expected_base_sha IS NEW.returned_pending_base_sha
                  AND ticket.status = 'REQUESTED'))
            THEN RAISE(ABORT, 'Applied Local replacement did not arm its exact successor')
        WHEN NEW.cause = 'REPLACE_LOCAL_RESULT'
          AND NEW.disposition = 'SUPERSEDED'
          AND NEW.returned_pending_operation_id IS NEW.subject_operation_id
            THEN RAISE(ABORT, 'Superseded Local replacement preserved its stale subject')
        WHEN NEW.cause = 'CLEAR_LOCAL_RESULT' AND NOT EXISTS (
                SELECT 1
                FROM local_stage_turn_request request
                JOIN stage_turn turn ON turn.id = request.stage_turn_id
                JOIN dispatch_ticket ticket
                  ON ticket.operation_id = turn.operation_id
                WHERE request.id = NEW.proof_id
                  AND request.task_id = NEW.task_id
                  AND request.local_development_stage_id = NEW.stage_id
                  AND request.task_epoch = NEW.subject_task_epoch
                  AND request.stage_generation = NEW.subject_stage_generation
                  AND turn.operation_id = NEW.subject_operation_id
                  AND turn.attempt = NEW.subject_attempt
                  AND turn.expected_code_fingerprint
                        IS NEW.subject_expected_code_fingerprint
                  AND turn.expected_head_sha IS NEW.subject_expected_head_sha
                  AND turn.expected_base_sha IS NEW.subject_expected_base_sha
                  AND ticket.task_id = NEW.task_id
                  AND ticket.task_epoch = NEW.subject_task_epoch
                  AND ticket.stage_id = NEW.stage_id
                  AND ticket.stage_generation = NEW.subject_stage_generation
                  AND ticket.attempt = NEW.subject_attempt
                  AND ticket.status IN ('RESULT_PENDING', 'FAILED', 'CANCELED'))
            THEN RAISE(ABORT, 'Local clear result lacks terminal delivery evidence')
        WHEN NEW.cause = 'CLEAR_LOCAL_RESULT'
          AND NEW.disposition = 'APPLIED'
          AND NEW.returned_pending_operation_id IS NOT NULL
            THEN RAISE(ABORT, 'Applied Local clear retained a pending result')
        WHEN NEW.cause = 'CLEAR_LOCAL_RESULT'
          AND NEW.disposition = 'SUPERSEDED'
          AND NEW.returned_pending_operation_id IS NEW.subject_operation_id
            THEN RAISE(ABORT, 'Superseded Local clear preserved its stale subject')
        WHEN NEW.cause = 'ACCEPT_LOCAL_CODE_RESULT' AND (
            NEW.returned_pending_operation_id IS NOT NULL
            OR NOT EXISTS (
                SELECT 1
                FROM dev_report report
                JOIN stage_turn turn ON turn.id = report.stage_turn_id
                WHERE report.id = NEW.proof_id
                  AND report.workflow_version = 'V2'
                  AND report.task_id = NEW.task_id
                  AND report.local_development_stage_id = NEW.stage_id
                  AND report.task_epoch = NEW.subject_task_epoch
                  AND report.stage_generation = NEW.subject_stage_generation
                  AND turn.operation_id = NEW.subject_operation_id
                  AND turn.attempt = NEW.subject_attempt
                  AND report.source_code_fingerprint
                        IS NEW.subject_expected_code_fingerprint
                  AND report.source_head_sha IS NEW.subject_expected_head_sha
                  AND report.source_base_sha IS NEW.subject_expected_base_sha
                  AND NOT EXISTS (
                      SELECT 1 FROM dev_report newer
                      WHERE newer.workflow_version = 'V2'
                        AND newer.local_development_stage_id
                            = report.local_development_stage_id
                        AND newer.revision > report.revision)
                  AND EXISTS (
                      SELECT 1 FROM stage_transition transition
                      WHERE transition.stage_id = NEW.stage_id
                        AND transition.command_id = NEW.command_id
                        AND ((transition.from_checkpoint = 'IMPLEMENTING'
                              AND transition.to_checkpoint = 'VALIDATING')
                          OR (transition.from_checkpoint IN (
                                  'ADDRESSING_BRAIN_FINDINGS',
                                  'ADDRESSING_LOCAL_FEEDBACK')
                              AND transition.to_checkpoint = 'IMPLEMENTING')))))
            THEN RAISE(ABORT, 'Local code result lacks its changed-subject DevReport')
        WHEN NEW.cause = 'BEGIN_LOCAL_VALIDATION' AND (
            NEW.source_checkpoint <> 'IMPLEMENTING'
            OR NEW.returned_checkpoint <> 'VALIDATING'
            OR NEW.returned_pending_operation_id IS NOT NULL
            OR NOT EXISTS (
                SELECT 1 FROM dev_report report
                WHERE report.id = NEW.proof_id
                  AND report.task_id = NEW.task_id
                  AND report.local_development_stage_id = NEW.stage_id
                  AND report.stage_generation = NEW.returned_generation
                  AND NOT EXISTS (SELECT 1 FROM dev_report newer
                      WHERE newer.workflow_version = 'V2'
                        AND newer.local_development_stage_id
                            = report.local_development_stage_id
                        AND newer.revision > report.revision)))
            THEN RAISE(ABORT, 'Local validation transition lacks latest DevReport')
        WHEN NEW.cause = 'ACCEPT_BRAIN_BUDGET_EXHAUSTION' AND (
            NEW.source_checkpoint <> 'BRAIN_REVIEW'
            OR NEW.returned_checkpoint <> 'LOCAL_REVIEW'
            OR NEW.returned_pending_operation_id IS NOT NULL
            OR NOT EXISTS (
                SELECT 1 FROM task_blocker blocker
                WHERE blocker.id = NEW.proof_id
                  AND blocker.task_id = NEW.task_id
                  AND blocker.stage_id = NEW.stage_id
                  AND blocker.owner_kind = 'STAGE'
                  AND blocker.owner_id = NEW.stage_id
                  AND blocker.blocker_type = 'BRAIN_BUDGET_EXHAUSTED'
                  AND blocker.status = 'OPEN'))
            THEN RAISE(ABORT, 'Brain exhaustion transition lacks its exact blocker')
    END;
END;
CREATE TRIGGER local_stage_turn_delivery_receipt_immutable
BEFORE UPDATE ON local_stage_turn_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Local StageTurn delivery receipt is immutable'); END;
CREATE TRIGGER local_stage_turn_delivery_receipt_insert
BEFORE INSERT ON local_stage_turn_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_turn turn
    JOIN local_stage_turn_request request ON request.stage_turn_id = turn.id
    WHERE turn.id = NEW.stage_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
      AND (NEW.dev_report_id IS NULL OR EXISTS (
          SELECT 1 FROM dev_report report
          WHERE report.id = NEW.dev_report_id
            AND report.stage_turn_id = turn.id))
      AND (NEW.validation_operation_id IS NULL OR EXISTS (
          SELECT 1 FROM validation_operation operation
          WHERE operation.id = NEW.validation_operation_id
            AND operation.dev_report_id = NEW.dev_report_id)))
BEGIN SELECT RAISE(ABORT, 'Local StageTurn delivery receipt is not exact'); END;
CREATE TRIGGER local_stage_turn_request_cancel
BEFORE UPDATE OF cancellation_requested_at_ms ON local_stage_turn_request
WHEN OLD.cancellation_requested_at_ms IS NOT NULL
  OR NEW.cancellation_requested_at_ms IS NULL
  OR NEW.cancellation_requested_at_ms < OLD.requested_at_ms
  OR NOT EXISTS (
      SELECT 1 FROM local_stage_turn_request replacement
      WHERE replacement.predecessor_turn_id = OLD.stage_turn_id
        AND replacement.queue_mode = 'CANCEL_AND_REPLACE')
BEGIN SELECT RAISE(ABORT, 'Local StageTurn cancellation lacks its exact replacement'); END;
CREATE TRIGGER local_stage_turn_request_identity_immutable
BEFORE UPDATE OF id, command_id, stage_turn_id, task_id,
        local_development_stage_id, task_epoch, stage_generation, kind,
        queue_mode, predecessor_turn_id, brain_review_episode_id,
        local_feedback_batch_id, prompt_digest, requested_by, requested_at_ms
ON local_stage_turn_request
BEGIN SELECT RAISE(ABORT, 'Local StageTurn request identity is immutable'); END;
CREATE TRIGGER local_stage_turn_request_insert
BEFORE INSERT ON local_stage_turn_request
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM stage_turn turn
            JOIN stage owner ON owner.id = turn.stage_id
            JOIN tasks task ON task.id = owner.task_id
            JOIN task_current_stage current ON current.task_id = task.id
            JOIN task_current_code_subject_v230 code ON code.task_id = task.id
            WHERE turn.id = NEW.stage_turn_id
              AND turn.stage_id = NEW.local_development_stage_id
              AND turn.stage_generation = NEW.stage_generation
              AND turn.task_epoch = NEW.task_epoch AND turn.status = 'QUEUED'
              AND turn.expected_code_fingerprint = code.code_fingerprint
              AND turn.expected_head_sha = code.head_sha
              AND turn.expected_base_sha = code.base_sha
              AND task.id = NEW.task_id AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE' AND task.epoch = NEW.task_epoch
              AND current.stage_id = owner.id
              AND current.stage_generation = owner.generation
              AND owner.kind = 'LOCAL_DEVELOPMENT'
              AND owner.generation = NEW.stage_generation
              AND owner.completed_at_ms IS NULL
              AND ((NEW.kind = 'IMPLEMENTATION'
                    AND turn.purpose = 'IMPLEMENT_LOCAL_PLAN')
                OR (NEW.kind = 'BRAIN_FINDINGS'
                    AND turn.purpose = 'ADDRESS_BRAIN_FINDINGS')
                OR (NEW.kind = 'LOCAL_FEEDBACK'
                    AND turn.purpose = 'ADDRESS_LOCAL_FEEDBACK')
                OR (NEW.kind = 'STEERING' AND turn.purpose = 'USER_STEERING')))
            THEN RAISE(ABORT, 'Local StageTurn request owner or subject is stale')
        WHEN NEW.predecessor_turn_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM local_stage_turn_request previous
            JOIN stage_turn turn ON turn.id = previous.stage_turn_id
            WHERE previous.stage_turn_id = NEW.predecessor_turn_id
              AND previous.task_id = NEW.task_id
              AND previous.local_development_stage_id = NEW.local_development_stage_id
              AND previous.task_epoch = NEW.task_epoch
              AND previous.stage_generation = NEW.stage_generation
              AND (turn.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')
                OR (turn.status = 'SUCCEEDED' AND EXISTS (
                    SELECT 1 FROM typed_user_wait_result result
                    WHERE result.operation_id = turn.operation_id
                      AND result.owner_kind = 'STAGE_TURN'
                      AND result.turn_id = turn.id))))
            THEN RAISE(ABORT, 'Local StageTurn predecessor is not exact')
        WHEN NEW.brain_review_episode_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM brain_review_episode episode
            WHERE episode.id = NEW.brain_review_episode_id
              AND episode.task_id = NEW.task_id
              AND episode.local_development_stage_id = NEW.local_development_stage_id
              AND episode.task_epoch = NEW.task_epoch
              AND episode.stage_generation = NEW.stage_generation
              AND episode.status = 'SUCCEEDED'
              AND episode.verdict = 'CHANGES_REQUESTED')
            THEN RAISE(ABORT, 'Brain-finding Turn lacks its exact verdict')
        WHEN NEW.local_feedback_batch_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM local_feedback_batch batch
            WHERE batch.id = NEW.local_feedback_batch_id
              AND batch.task_id = NEW.task_id
              AND batch.local_development_stage_id = NEW.local_development_stage_id
              AND batch.task_epoch = NEW.task_epoch
              AND batch.stage_generation = NEW.stage_generation
              AND batch.status IN ('FROZEN', 'QUEUED', 'DISPATCHED'))
            THEN RAISE(ABORT, 'Local-feedback Turn lacks its exact batch')
    END;
END;
CREATE TRIGGER local_validation_delivery_receipt_immutable
BEFORE UPDATE ON local_validation_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Local Validation delivery receipt is immutable'); END;
CREATE TRIGGER local_validation_delivery_receipt_insert
BEFORE INSERT ON local_validation_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM validation_operation operation
    WHERE operation.id = NEW.validation_operation_id
      AND operation.operation_id = NEW.operation_id
      AND operation.status IN ('COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')
      AND (NEW.validation_evidence_id IS NULL OR EXISTS (
          SELECT 1 FROM validation_evidence evidence
          WHERE evidence.id = NEW.validation_evidence_id
            AND evidence.validation_operation_id = operation.id))
      AND (NEW.brain_review_episode_id IS NULL OR EXISTS (
          SELECT 1 FROM brain_review_episode episode
          WHERE episode.id = NEW.brain_review_episode_id
            AND episode.validation_evidence_id = NEW.validation_evidence_id)))
BEGIN SELECT RAISE(ABORT, 'Local Validation delivery receipt is not exact'); END;
CREATE TRIGGER manual_pr_validation_operation_identity_immutable
BEFORE UPDATE OF id, command_id, pr_id, task_id, task_epoch, worktree_path,
    code_fingerprint, expected_head_sha, expected_base_sha, requested_at_ms
ON manual_pr_validation_operation
BEGIN
    SELECT RAISE(ABORT, 'Manual PR validation identity is immutable');
END;
CREATE TRIGGER manual_pr_validation_operation_insert
BEFORE INSERT ON manual_pr_validation_operation
WHEN NOT EXISTS (
    SELECT 1
    FROM pr
    JOIN tasks task ON task.id = pr.task_id
    JOIN task_code_identity identity ON identity.task_id = task.id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE pr.id = NEW.pr_id
      AND task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND identity.worktree_path = NEW.worktree_path
      AND code.code_fingerprint = NEW.code_fingerprint
      AND code.head_sha = NEW.expected_head_sha
      AND code.base_sha = NEW.expected_base_sha
      AND NEW.status = 'REQUESTED')
BEGIN
    SELECT RAISE(ABORT, 'Manual PR validation requires an exact active V2 Task subject');
END;
CREATE TRIGGER manual_pr_validation_operation_terminal_immutable
BEFORE UPDATE ON manual_pr_validation_operation
WHEN OLD.status <> 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT, 'Terminal Manual PR validation is immutable');
END;
CREATE TRIGGER manual_pr_validation_operation_transition
BEFORE UPDATE OF status ON manual_pr_validation_operation
WHEN OLD.status <> 'REQUESTED' OR NEW.status = 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT, 'Manual PR validation has one terminal transition');
END;
CREATE TRIGGER manual_pr_validation_result_projection
AFTER UPDATE OF status ON manual_pr_validation_operation
WHEN NEW.status = 'COMPLETED'
  AND json_type(NEW.result_json, '$.testRun') = 'object'
BEGIN
    INSERT INTO pr_check(
        id, pr_id, kind, name, status, duration_ms,
        started_at_ms, finished_at_ms, run_id)
    VALUES (
        'manual-pr-validation-check:' || NEW.id,
        NEW.pr_id,
        'local',
        json_extract(NEW.result_json, '$.testRun.ecosystem') || ' test',
        CASE json_extract(NEW.result_json, '$.testRun.passed')
            WHEN 1 THEN 'passed' ELSE 'failed' END,
        json_extract(NEW.result_json, '$.testRun.durationMs'),
        json_extract(NEW.result_json, '$.testRun.startedAtMs'),
        json_extract(NEW.result_json, '$.testRun.completedAtMs'),
        NEW.id);

    INSERT INTO pr_timeline_event(
        id, pr_id, event_type, actor, is_local_only,
        stripped_on_push_at_ms, created_at_ms, payload_json, remote_event_id)
    VALUES (
        'manual-pr-validation-event:' || NEW.id,
        NEW.pr_id,
        'ci',
        'claude-code',
        1,
        NULL,
        json_extract(NEW.result_json, '$.testRun.completedAtMs'),
        json_object(
            'kind', 'local',
            'name', json_extract(
                NEW.result_json, '$.testRun.ecosystem') || ' test',
            'status', CASE json_extract(
                NEW.result_json, '$.testRun.passed')
                WHEN 1 THEN 'passed' ELSE 'failed' END,
            'durationMs', json_extract(
                NEW.result_json, '$.testRun.durationMs')),
        NULL);
END;
CREATE TRIGGER outbox_identity_immutable
BEFORE UPDATE OF dedup_key, aggregate_kind, aggregate_id, topic, payload, created_at_ms ON outbox
WHEN NEW.dedup_key IS NOT OLD.dedup_key
  OR NEW.aggregate_kind IS NOT OLD.aggregate_kind
  OR NEW.aggregate_id IS NOT OLD.aggregate_id
  OR NEW.topic IS NOT OLD.topic
  OR NEW.payload IS NOT OLD.payload
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'outbox identity is immutable'); END;
CREATE TRIGGER outbox_v2_dispatch_ticket_wake_insert
BEFORE INSERT ON outbox
WHEN NEW.aggregate_kind = 'DISPATCH_TICKET'
  OR NEW.topic = 'V2_DISPATCH_TICKET_REQUESTED'
  OR NEW.id GLOB 'V2_DISPATCH_TICKET_REQUESTED:*'
  OR NEW.dedup_key GLOB 'V2_DISPATCH_TICKET_REQUESTED:*'
BEGIN
    SELECT CASE WHEN
        NEW.id <> 'V2_DISPATCH_TICKET_REQUESTED:' || NEW.aggregate_id
        OR NEW.dedup_key <> NEW.id
        OR NEW.aggregate_kind <> 'DISPATCH_TICKET'
        OR NEW.topic <> 'V2_DISPATCH_TICKET_REQUESTED'
        OR NEW.payload <> NEW.aggregate_id
        OR length(NEW.aggregate_id) = 0
        OR NEW.status <> 'PENDING'
        OR NEW.attempts <> 0
        OR NEW.available_at_ms <> NEW.created_at_ms
        OR NEW.claim_owner IS NOT NULL
        OR NEW.lease_until_ms IS NOT NULL
        OR NEW.delivered_at_ms IS NOT NULL
        OR NEW.last_error IS NOT NULL
        OR NOT EXISTS (
            SELECT 1 FROM dispatch_ticket ticket
            WHERE ticket.id = NEW.aggregate_id
              AND ticket.status = 'REQUESTED'
              AND ticket.created_at_ms = NEW.created_at_ms)
    THEN RAISE(ABORT, 'V2 DispatchTicket wake is not exact') END;
END;
CREATE TRIGGER outbox_v2_dispatch_ticket_wake_update
BEFORE UPDATE ON outbox
WHEN OLD.aggregate_kind = 'DISPATCH_TICKET'
BEGIN
    SELECT CASE WHEN
        NEW.id <> OLD.id
        OR NEW.dedup_key <> OLD.dedup_key
        OR NEW.aggregate_kind <> OLD.aggregate_kind
        OR NEW.aggregate_id <> OLD.aggregate_id
        OR NEW.topic <> OLD.topic
        OR NEW.payload <> OLD.payload
        OR NEW.created_at_ms <> OLD.created_at_ms
        OR NEW.id <> 'V2_DISPATCH_TICKET_REQUESTED:' || NEW.aggregate_id
        OR NEW.dedup_key <> NEW.id
        OR NEW.topic <> 'V2_DISPATCH_TICKET_REQUESTED'
        OR NEW.payload <> NEW.aggregate_id
        OR NOT (
        (OLD.status = 'PENDING'
         AND NEW.status = 'CLAIMED'
         AND NEW.attempts = OLD.attempts + 1
         AND NEW.available_at_ms >= OLD.available_at_ms
         AND NEW.claim_owner IS NOT NULL
         AND length(NEW.claim_owner) > 0
         AND NEW.lease_until_ms > NEW.available_at_ms
         AND NEW.delivered_at_ms IS NULL
         AND NEW.last_error IS NULL)
        OR
        (OLD.status = 'CLAIMED'
         AND NEW.status = 'CLAIMED'
         AND NEW.attempts = OLD.attempts + 1
         AND NEW.available_at_ms >= OLD.lease_until_ms
         AND NEW.claim_owner IS NOT NULL
         AND length(NEW.claim_owner) > 0
         AND NEW.lease_until_ms > NEW.available_at_ms
         AND NEW.delivered_at_ms IS NULL
         AND NEW.last_error IS NULL)
        OR
        (OLD.status = 'CLAIMED'
         AND NEW.status = 'DELIVERED'
         AND NEW.attempts = OLD.attempts
         AND NEW.available_at_ms = OLD.available_at_ms
         AND NEW.claim_owner IS NULL
         AND NEW.lease_until_ms IS NULL
         AND NEW.delivered_at_ms >= OLD.available_at_ms
         AND NEW.last_error IS NULL)
        )
    THEN RAISE(ABORT, 'V2 DispatchTicket wake state evidence is invalid') END;
END;
CREATE TRIGGER permission_grant_consumption_immutable
BEFORE UPDATE ON permission_grant_consumption
BEGIN SELECT RAISE(ABORT, 'permission consumption evidence is immutable'); END;
CREATE TRIGGER permission_request_answer_transition
BEFORE UPDATE OF
    state, answer, answer_revision, answered_at_ms, answer_actor,
    grant_scope_kind, grant_scope_id, granted_uses, remaining_uses
ON permission_request
WHEN NEW.state IS NOT OLD.state
BEGIN
    SELECT CASE WHEN OLD.state <> 'OPEN'
        OR NEW.state = 'OPEN'
        OR NEW.answer IS NULL OR length(trim(NEW.answer)) = 0
        OR NEW.answer_actor IS NULL OR length(trim(NEW.answer_actor)) = 0
        OR NEW.answer_revision <> OLD.answer_revision + 1
        OR NEW.answered_at_ms IS NULL
        OR NEW.answered_at_ms < OLD.requested_at_ms
        OR NEW.state IN ('ALLOWED_ONCE', 'ALLOWED_NEXT', 'ALLOWED_TASK',
                'ALLOWED_REPOSITORY', 'DENIED')
            AND NEW.continuation_state <> 'READY'
        OR NEW.state IN ('CANCELED', 'EXPIRED')
            AND NEW.continuation_state <> 'CANCELED'
    THEN RAISE(ABORT, 'permission answer transition is invalid') END;

    SELECT CASE WHEN NEW.state IN ('DENIED', 'CANCELED', 'EXPIRED')
        AND (NEW.grant_scope_kind IS NOT NULL
             OR NEW.grant_scope_id IS NOT NULL
             OR NEW.granted_uses IS NOT NULL
             OR NEW.remaining_uses IS NOT NULL)
    THEN RAISE(ABORT, 'denied permission cannot create a grant') END;

    SELECT CASE WHEN NEW.state = 'ALLOWED_ONCE'
        AND (NEW.grant_scope_kind <> 'CALL'
             OR NEW.parameters_digest IS NULL
             OR NEW.grant_scope_id <> NEW.parameters_digest
             OR NEW.granted_uses <> 1 OR NEW.remaining_uses <> 1)
    THEN RAISE(ABORT, 'one-time permission grant is invalid') END;

    SELECT CASE WHEN NEW.state = 'ALLOWED_NEXT'
        AND (NEW.grant_scope_kind NOT IN ('TRUNK', 'TASK', 'REPOSITORY')
             OR NEW.grant_scope_id IS NULL
             OR length(trim(NEW.grant_scope_id)) = 0
             OR NEW.granted_uses IS NULL OR NEW.granted_uses <= 0
             OR NEW.remaining_uses <> NEW.granted_uses)
    THEN RAISE(ABORT, 'finite permission grant is invalid') END;

    SELECT CASE WHEN NEW.state = 'ALLOWED_TASK'
        AND (NEW.grant_scope_kind <> 'TASK'
             OR NEW.grant_scope_id IS NULL
             OR length(trim(NEW.grant_scope_id)) = 0
             OR NEW.granted_uses <> -1 OR NEW.remaining_uses <> -1)
    THEN RAISE(ABORT, 'Task permission grant is invalid') END;

    SELECT CASE WHEN NEW.state = 'ALLOWED_REPOSITORY'
        AND (NEW.grant_scope_kind <> 'REPOSITORY'
             OR NEW.grant_scope_id IS NULL
             OR length(trim(NEW.grant_scope_id)) = 0
             OR NEW.granted_uses <> -1 OR NEW.remaining_uses <> -1)
    THEN RAISE(ABORT, 'repository permission grant is invalid') END;
END;
CREATE TRIGGER permission_request_continuation_scope
BEFORE UPDATE OF continuation_state, successor_turn_id ON permission_request
WHEN NEW.continuation_state = 'DISPATCHED' AND NOT (
    (OLD.turn_kind = 'THREAD' AND EXISTS (
        SELECT 1
        FROM thread_turn source
        JOIN thread_turn successor ON successor.id = NEW.successor_turn_id
        WHERE source.id = OLD.turn_id
          AND successor.id <> source.id
          AND successor.trunk_id = source.trunk_id))
    OR (OLD.turn_kind = 'TASK' AND EXISTS (
        SELECT 1
        FROM task_turn source
        JOIN task_turn successor ON successor.id = NEW.successor_turn_id
        WHERE source.id = OLD.turn_id
          AND successor.id <> source.id
          AND successor.task_id = source.task_id
          AND successor.task_epoch = source.task_epoch
          AND successor.trigger_stage_id IS source.trigger_stage_id
          AND successor.trigger_stage_generation IS source.trigger_stage_generation
          AND successor.expected_code_fingerprint IS source.expected_code_fingerprint
          AND successor.expected_head_sha IS source.expected_head_sha
          AND successor.expected_base_sha IS source.expected_base_sha))
    OR (OLD.turn_kind = 'STAGE' AND EXISTS (
        SELECT 1
        FROM stage_turn source
        JOIN stage_turn successor ON successor.id = NEW.successor_turn_id
        WHERE source.id = OLD.turn_id
          AND successor.id <> source.id
          AND successor.stage_id = source.stage_id
          AND successor.stage_generation = source.stage_generation
          AND successor.task_epoch = source.task_epoch
          AND successor.expected_code_fingerprint IS source.expected_code_fingerprint
          AND successor.expected_head_sha IS source.expected_head_sha
          AND successor.expected_base_sha IS source.expected_base_sha))
    OR (OLD.turn_kind = 'REVIEW_ASSIGNMENT' AND EXISTS (
        SELECT 1
        FROM review_assignment_turn source
        JOIN review_assignment_turn successor
          ON successor.id = NEW.successor_turn_id
        WHERE source.id = OLD.turn_id
          AND successor.id <> source.id
          AND successor.assignment_id = source.assignment_id
          AND successor.start_commit = source.start_commit)))
BEGIN SELECT RAISE(ABORT, 'permission successor fence is stale'); END;
CREATE TRIGGER permission_request_continuation_transition
BEFORE UPDATE OF continuation_state, successor_turn_id, continuation_error
ON permission_request
BEGIN
    SELECT CASE WHEN OLD.continuation_state = 'WAITING'
            AND NEW.continuation_state NOT IN ('WAITING', 'READY', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state = 'READY'
            AND NEW.continuation_state NOT IN ('READY', 'DISPATCHED', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state IN ('DISPATCHED', 'CANCELED', 'SUPERSEDED')
            AND (NEW.continuation_state IS NOT OLD.continuation_state
                OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
                OR NEW.continuation_error IS NOT OLD.continuation_error)
        OR NEW.continuation_state = 'DISPATCHED'
            AND (NEW.successor_turn_id IS NULL
                OR length(trim(NEW.successor_turn_id)) = 0)
    THEN RAISE(ABORT, 'permission continuation transition is invalid') END;
END;
CREATE TRIGGER permission_request_grant_consume
BEFORE UPDATE OF remaining_uses, consumed_uses, last_consumed_at_ms
ON permission_request
WHEN NEW.state IS OLD.state
  AND (NEW.remaining_uses IS NOT OLD.remaining_uses
       OR NEW.consumed_uses IS NOT OLD.consumed_uses
       OR NEW.last_consumed_at_ms IS NOT OLD.last_consumed_at_ms)
BEGIN
    SELECT CASE WHEN OLD.state NOT IN (
            'ALLOWED_ONCE', 'ALLOWED_NEXT',
            'ALLOWED_TASK', 'ALLOWED_REPOSITORY')
        OR OLD.remaining_uses IS NULL OR OLD.remaining_uses = 0
        OR NEW.consumed_uses <> OLD.consumed_uses + 1
        OR NEW.last_consumed_at_ms IS NULL
        OR (OLD.last_consumed_at_ms IS NOT NULL
            AND NEW.last_consumed_at_ms < OLD.last_consumed_at_ms)
        OR NOT (
            (OLD.remaining_uses = -1 AND NEW.remaining_uses = -1)
            OR (OLD.remaining_uses > 0
                AND NEW.remaining_uses = OLD.remaining_uses - 1))
    THEN RAISE(ABORT, 'permission grant consumption is invalid') END;
END;
CREATE TRIGGER permission_request_grant_identity_immutable
BEFORE UPDATE OF
    parameters_digest, grant_scope_kind, grant_scope_id, granted_uses
ON permission_request
WHEN OLD.state <> 'OPEN'
  AND (NEW.parameters_digest IS NOT OLD.parameters_digest
       OR NEW.grant_scope_kind IS NOT OLD.grant_scope_kind
       OR NEW.grant_scope_id IS NOT OLD.grant_scope_id
       OR NEW.granted_uses IS NOT OLD.granted_uses)
BEGIN SELECT RAISE(ABORT, 'permission grant identity is immutable'); END;
CREATE TRIGGER permission_request_id_immutable_v265
BEFORE UPDATE OF id ON permission_request
WHEN NEW.id IS NOT OLD.id
BEGIN SELECT RAISE(ABORT, 'permission request id is immutable'); END;
CREATE TRIGGER permission_request_identity_immutable
BEFORE UPDATE OF call_id, turn_kind, turn_id, operation_id, capability,
        tool_name, parameters_json, policy_snapshot, requested_at_ms ON permission_request
WHEN NEW.call_id IS NOT OLD.call_id
  OR NEW.turn_kind IS NOT OLD.turn_kind
  OR NEW.turn_id IS NOT OLD.turn_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.capability IS NOT OLD.capability
  OR NEW.tool_name IS NOT OLD.tool_name
  OR NEW.parameters_json IS NOT OLD.parameters_json
  OR NEW.policy_snapshot IS NOT OLD.policy_snapshot
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'permission request identity is immutable'); END;
CREATE TRIGGER permission_request_open_invariant
BEFORE UPDATE ON permission_request
WHEN OLD.state = 'OPEN' AND NEW.state = 'OPEN'
 AND (NEW.answer IS NOT OLD.answer
   OR NEW.answer_revision IS NOT OLD.answer_revision
   OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
   OR NEW.grant_scope_kind IS NOT OLD.grant_scope_kind
   OR NEW.grant_scope_id IS NOT OLD.grant_scope_id
   OR NEW.granted_uses IS NOT OLD.granted_uses
   OR NEW.remaining_uses IS NOT OLD.remaining_uses
   OR NEW.consumed_uses IS NOT OLD.consumed_uses
   OR NEW.answer_actor IS NOT OLD.answer_actor
   OR NEW.last_consumed_at_ms IS NOT OLD.last_consumed_at_ms
   OR NEW.continuation_state IS NOT OLD.continuation_state
   OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
   OR NEW.continuation_error IS NOT OLD.continuation_error)
BEGIN SELECT RAISE(ABORT, 'open permission request is immutable'); END;
CREATE TRIGGER permission_request_owner_insert
BEFORE INSERT ON permission_request
BEGIN
    SELECT CASE WHEN
        (EXISTS (SELECT 1 FROM thread_turn x WHERE x.id = NEW.turn_id)
        + EXISTS (SELECT 1 FROM task_turn x WHERE x.id = NEW.turn_id)
        + EXISTS (SELECT 1 FROM stage_turn x WHERE x.id = NEW.turn_id)
        + EXISTS (SELECT 1 FROM review_assignment_turn x WHERE x.id = NEW.turn_id)) <> 1
    THEN RAISE(ABORT, 'permission Turn id must resolve exactly once') END;
    SELECT CASE WHEN
        (NEW.turn_kind = 'THREAD' AND NOT EXISTS (
            SELECT 1 FROM thread_turn x
            WHERE x.id = NEW.turn_id AND x.operation_id = NEW.operation_id))
        OR (NEW.turn_kind = 'TASK' AND NOT EXISTS (
            SELECT 1 FROM task_turn x
            WHERE x.id = NEW.turn_id AND x.operation_id = NEW.operation_id))
        OR (NEW.turn_kind = 'STAGE' AND NOT EXISTS (
            SELECT 1 FROM stage_turn x
            WHERE x.id = NEW.turn_id AND x.operation_id = NEW.operation_id))
        OR (NEW.turn_kind = 'REVIEW_ASSIGNMENT' AND NOT EXISTS (
            SELECT 1 FROM review_assignment_turn x
            WHERE x.id = NEW.turn_id AND x.operation_id = NEW.operation_id))
    THEN RAISE(ABORT, 'permission Operation does not match typed Turn') END;
END;
CREATE TRIGGER permission_request_parameters_digest_immutable
BEFORE UPDATE OF parameters_digest ON permission_request
WHEN NEW.parameters_digest IS NOT OLD.parameters_digest
BEGIN SELECT RAISE(ABORT, 'permission parameter digest is immutable'); END;
CREATE TRIGGER permission_request_terminal_state_immutable
BEFORE UPDATE OF state, answer, answer_revision, answered_at_ms, answer_actor
ON permission_request
WHEN OLD.state <> 'OPEN'
  AND (NEW.state IS NOT OLD.state
       OR NEW.answer IS NOT OLD.answer
       OR NEW.answer_revision IS NOT OLD.answer_revision
       OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
       OR NEW.answer_actor IS NOT OLD.answer_actor)
BEGIN SELECT RAISE(ABORT, 'terminal permission answer is immutable'); END;
CREATE TRIGGER plan_approval_fence_insert
BEFORE INSERT ON plan_approval
WHEN NOT EXISTS (
    SELECT 1
    FROM plan_self_review sr
    JOIN plan_revision r ON r.id = sr.plan_revision_id
    JOIN plan_stage p ON p.stage_id = r.plan_stage_id
    JOIN stage s ON s.id = p.stage_id
    JOIN tasks t ON t.id = p.task_id
    JOIN task_current_stage c ON c.stage_id = s.id
    JOIN task_policy_revision policy ON policy.id = NEW.policy_revision_id
    WHERE sr.id = NEW.self_review_id
      AND sr.plan_revision_id = NEW.plan_revision_id
      AND sr.status = 'SUCCEEDED'
      AND sr.verdict = 'APPROVED'
      AND t.policy_revision_id = NEW.policy_revision_id
      AND (NEW.approval_kind <> 'POLICY' OR (
          policy.auto_approve = 1
          AND NOT EXISTS (
              SELECT 1
              FROM plan_followup f
              JOIN plan_revision fr ON fr.id = f.plan_revision_id
              JOIN plan_stage fp ON fp.stage_id = fr.plan_stage_id
              WHERE fp.task_id = t.id
                AND f.kind = 'STEWARDSHIP'
                AND f.status <> 'RESOLVED')))
      AND t.epoch = p.opened_for_epoch
      AND c.task_id = t.id
      AND c.stage_generation = p.generation
      AND s.completed_at_ms IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = r.plan_stage_id
            AND newer.revision > r.revision))
BEGIN SELECT RAISE(ABORT, 'Plan approval requires exact approved self-review evidence'); END;
CREATE TRIGGER plan_approval_immutable
BEFORE UPDATE ON plan_approval
BEGIN SELECT RAISE(ABORT, 'Plan approval is immutable'); END;
CREATE TRIGGER plan_followup_identity_immutable
BEFORE UPDATE OF id, plan_revision_id, kind, description, self_review_id,
        task_blocker_id, created_by, created_at_ms
ON plan_followup
WHEN NEW.id IS NOT OLD.id
  OR NEW.plan_revision_id IS NOT OLD.plan_revision_id
  OR NEW.kind IS NOT OLD.kind
  OR NEW.description IS NOT OLD.description
  OR NEW.self_review_id IS NOT OLD.self_review_id
  OR NEW.task_blocker_id IS NOT OLD.task_blocker_id
  OR NEW.created_by IS NOT OLD.created_by
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'Plan follow-up identity is immutable'); END;
CREATE TRIGGER plan_followup_insert_fence
BEFORE INSERT ON plan_followup
WHEN NEW.status <> 'OPEN'
  OR NOT EXISTS (
      SELECT 1
      FROM plan_revision r
      JOIN plan_stage p ON p.stage_id = r.plan_stage_id
      JOIN stage s ON s.id = p.stage_id
      JOIN task_current_stage c ON c.stage_id = p.stage_id
      WHERE r.id = NEW.plan_revision_id
        AND c.task_id = p.task_id
        AND c.stage_generation = p.generation
        AND s.completed_at_ms IS NULL
        AND NOT EXISTS (
            SELECT 1 FROM plan_revision newer
            WHERE newer.plan_stage_id = r.plan_stage_id
              AND newer.revision > r.revision)
        AND (NEW.kind IN ('FOLLOW_UP', 'FAILURE_BLOCKER') OR NOT EXISTS (
            SELECT 1 FROM plan_self_review frozen
            WHERE frozen.plan_revision_id = r.id
              AND frozen.status = 'SUCCEEDED'))
        AND (NEW.kind <> 'FAILURE_BLOCKER' OR EXISTS (
            SELECT 1
            FROM plan_self_review sr
            JOIN task_blocker b ON b.id = NEW.task_blocker_id
            WHERE sr.id = NEW.self_review_id
              AND sr.plan_revision_id = r.id
              AND (sr.status = 'FAILED'
                OR (sr.status = 'SUCCEEDED' AND sr.verdict = 'BLOCKED'))
              AND b.task_id = p.task_id
              AND b.stage_id = p.stage_id
              AND b.owner_kind = 'STAGE'
              AND b.owner_id = p.stage_id
              AND b.subject_revision = r.content_digest
              AND b.blocker_type = 'PLAN_REVIEW_FAILURE'
              AND b.status = 'OPEN')))
BEGIN SELECT RAISE(ABORT, 'Plan follow-up must match current reviewed evidence'); END;
CREATE TRIGGER plan_followup_transition
BEFORE UPDATE OF status ON plan_followup
WHEN NOT (
    (OLD.status = 'OPEN' AND NEW.status IN ('RESOLVED', 'DEFERRED'))
    OR (OLD.status = 'DEFERRED' AND NEW.status = 'RESOLVED'))
BEGIN SELECT RAISE(ABORT, 'illegal Plan follow-up transition'); END;
CREATE TRIGGER plan_review_submission_immutable
BEFORE UPDATE ON plan_review_submission
BEGIN SELECT RAISE(ABORT, 'Plan review submission is immutable'); END;
CREATE TRIGGER plan_review_submission_insert
BEFORE INSERT ON plan_review_submission
WHEN NOT EXISTS (
    SELECT 1
    FROM plan_self_review review
    JOIN plan_self_review_all_attempt_v265 attempt
      ON attempt.self_review_id = review.id
    JOIN plan_revision revision ON revision.id = review.plan_revision_id
    JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
    JOIN stage s ON s.id = plan.stage_id
    JOIN tasks task ON task.id = plan.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN task_turn turn ON turn.id = attempt.task_turn_id
    JOIN dispatch_ticket ticket ON ticket.operation_id = turn.operation_id
    WHERE review.id = NEW.self_review_id
      AND review.plan_revision_id = NEW.plan_revision_id
      AND review.reviewed_digest = NEW.reviewed_digest
      AND review.status = 'REQUESTED'
      AND turn.id = NEW.task_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.purpose = 'PLAN_SELF_REVIEW'
      AND turn.status = 'RUNNING'
      AND turn.task_id = NEW.task_id AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id = NEW.plan_stage_id
      AND turn.trigger_stage_generation = NEW.stage_generation
      AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
      AND ticket.status = 'RUNNING'
      AND plan.generation = NEW.stage_generation
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND current.stage_id = s.id AND current.stage_generation = s.generation
      AND s.checkpoint = 'SELF_REVIEW' AND s.completed_at_ms IS NULL
      AND attempt.semantic_attempt = (
          SELECT MAX(latest.semantic_attempt)
          FROM plan_self_review_all_attempt_v265 latest
          WHERE latest.self_review_id = review.id)
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = revision.plan_stage_id
            AND newer.revision > revision.revision))
BEGIN SELECT RAISE(ABORT, 'Plan review submission is not exact'); END;
CREATE TRIGGER plan_revision_immutable
BEFORE UPDATE ON plan_revision
BEGIN SELECT RAISE(ABORT, 'Plan revision is immutable'); END;
CREATE TRIGGER plan_revision_sequence
BEFORE INSERT ON plan_revision
BEGIN
    SELECT CASE
        WHEN NEW.revision <> COALESCE((
            SELECT MAX(r.revision) + 1 FROM plan_revision r
            WHERE r.plan_stage_id = NEW.plan_stage_id), 1)
            THEN RAISE(ABORT, 'Plan revision must be the next exact revision')
        WHEN NOT EXISTS (
            SELECT 1
            FROM plan_stage p
            JOIN stage s ON s.id = p.stage_id
            JOIN task_current_stage c ON c.stage_id = s.id
            WHERE p.stage_id = NEW.plan_stage_id
              AND c.task_id = p.task_id
              AND c.stage_generation = p.generation
              AND s.completed_at_ms IS NULL)
            THEN RAISE(ABORT, 'Plan revision requires the current open Plan Stage')
    END;
END;
CREATE TRIGGER plan_self_review_attempt_immutable
BEFORE UPDATE ON plan_self_review_attempt
BEGIN SELECT RAISE(ABORT, 'Plan self-review attempt is immutable'); END;
CREATE TRIGGER plan_self_review_attempt_insert
BEFORE INSERT ON plan_self_review_attempt
WHEN NOT EXISTS (
    SELECT 1
    FROM plan_self_review review
    JOIN plan_revision revision ON revision.id = review.plan_revision_id
    JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
    JOIN task_turn turn ON turn.id = NEW.task_turn_id
    WHERE review.id = NEW.self_review_id
      AND review.status = 'REQUESTED'
      AND turn.operation_id = NEW.operation_id
      AND turn.task_id = plan.task_id
      AND turn.task_epoch = review.task_epoch
      AND turn.trigger_stage_id = plan.stage_id
      AND turn.trigger_stage_generation = plan.generation
      AND turn.purpose = 'PLAN_SELF_REVIEW'
      AND turn.status = 'REQUESTED'
      AND ((NEW.attempt = 1 AND turn.id = review.task_turn_id)
        OR (NEW.attempt = 2
          AND NOT EXISTS (
              SELECT 1 FROM plan_self_review_attempt consumed
              WHERE consumed.self_review_id = review.id
                AND consumed.attempt = 2)
          AND EXISTS (
              SELECT 1 FROM plan_self_review_attempt first
              WHERE first.self_review_id = review.id AND first.attempt = 1)
          AND EXISTS (
              SELECT 1
              FROM plan_self_review_all_attempt_v265 predecessor
              JOIN task_turn failed ON failed.id = predecessor.task_turn_id
              WHERE predecessor.self_review_id = review.id
                AND predecessor.task_turn_id = NEW.predecessor_turn_id
                AND predecessor.semantic_attempt = (
                    SELECT MAX(latest.semantic_attempt)
                    FROM plan_self_review_all_attempt_v265 latest
                    WHERE latest.self_review_id = review.id)
                AND failed.status = 'FAILED'
                AND failed.finished_at_ms IS NOT NULL))))
BEGIN SELECT RAISE(ABORT, 'Plan self-review attempt is not exact'); END;
CREATE TRIGGER plan_self_review_failure_execution_immutable_v272
BEFORE UPDATE ON plan_self_review_failure_execution_v272
BEGIN SELECT RAISE(ABORT, 'Plan self-review failure execution is immutable'); END;
CREATE TRIGGER plan_self_review_failure_execution_insert_v272
AFTER INSERT ON plan_self_review_attempt
WHEN NEW.attempt = 2
BEGIN
    INSERT INTO plan_self_review_failure_execution_v272(
        self_review_id, infrastructure_attempt, execution_attempt,
        requested_at_ms)
    SELECT NEW.self_review_id, 2,
           1 + MAX(execution_attempt), NEW.requested_at_ms
    FROM (
        SELECT 1 AS execution_attempt
        UNION ALL
        SELECT semantic_attempt
        FROM plan_self_review_user_wait_attempt_v265
        WHERE self_review_id = NEW.self_review_id
        UNION ALL
        SELECT semantic_attempt
        FROM plan_self_review_resume_attempt_v272
        WHERE self_review_id = NEW.self_review_id);
END;
CREATE TRIGGER plan_self_review_identity_immutable
BEFORE UPDATE OF plan_revision_id, task_turn_id, task_epoch,
        reviewed_digest, requested_at_ms ON plan_self_review
WHEN NEW.plan_revision_id IS NOT OLD.plan_revision_id
  OR NEW.task_turn_id IS NOT OLD.task_turn_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.reviewed_digest IS NOT OLD.reviewed_digest
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'Plan self-review fence is immutable'); END;
CREATE TRIGGER plan_self_review_owner_insert
BEFORE INSERT ON plan_self_review
WHEN NEW.status <> 'REQUESTED'
  OR NOT EXISTS (
    SELECT 1
    FROM plan_revision r
    JOIN plan_stage p ON p.stage_id = r.plan_stage_id
    JOIN stage s ON s.id = p.stage_id
    JOIN tasks t ON t.id = p.task_id
    JOIN task_current_stage c ON c.stage_id = p.stage_id
    JOIN task_turn tt ON tt.id = NEW.task_turn_id
    WHERE r.id = NEW.plan_revision_id
      AND r.content_digest = NEW.reviewed_digest
      AND t.workflow_version = 'V2'
      AND t.lifecycle_state = 'ACTIVE'
      AND t.epoch = NEW.task_epoch
      AND c.task_id = p.task_id
      AND c.stage_generation = p.generation
      AND s.completed_at_ms IS NULL
      AND p.task_id = tt.task_id
      AND p.opened_for_epoch = NEW.task_epoch
      AND tt.task_epoch = NEW.task_epoch
      AND tt.purpose = 'PLAN_SELF_REVIEW'
      AND tt.status IN ('REQUESTED', 'QUEUED')
      AND tt.trigger_stage_id = p.stage_id
      AND tt.trigger_stage_generation = p.generation
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = r.plan_stage_id
            AND newer.revision > r.revision))
BEGIN SELECT RAISE(ABORT, 'Plan self-review must use its exact TaskTurn and revision fence'); END;
CREATE TRIGGER plan_self_review_result_fence
BEFORE UPDATE ON plan_self_review
WHEN NEW.status = 'SUCCEEDED'
  AND NOT EXISTS (
      SELECT 1
      FROM plan_revision revision
      JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
      JOIN stage s ON s.id = plan.stage_id
      JOIN task_current_stage current ON current.stage_id = s.id
      JOIN tasks task ON task.id = plan.task_id
      JOIN plan_self_review_all_attempt_v265 attempt
        ON attempt.self_review_id = NEW.id
      JOIN task_turn turn ON turn.id = attempt.task_turn_id
      WHERE revision.id = NEW.plan_revision_id
        AND revision.content_digest = NEW.reviewed_digest
        AND current.task_id = plan.task_id
        AND current.stage_generation = plan.generation
        AND task.workflow_version = 'V2'
        AND task.lifecycle_state = 'ACTIVE'
        AND task.epoch = NEW.task_epoch
        AND plan.opened_for_epoch = NEW.task_epoch
        AND turn.status = 'SUCCEEDED'
        AND turn.purpose = 'PLAN_SELF_REVIEW'
        AND turn.task_epoch = NEW.task_epoch
        AND turn.trigger_stage_id = plan.stage_id
        AND turn.trigger_stage_generation = plan.generation
        AND attempt.semantic_attempt = (
            SELECT MAX(latest.semantic_attempt)
            FROM plan_self_review_all_attempt_v265 latest
            WHERE latest.self_review_id = NEW.id)
        AND s.completed_at_ms IS NULL
        AND NOT EXISTS (
            SELECT 1 FROM plan_revision newer
            WHERE newer.plan_stage_id = revision.plan_stage_id
              AND newer.revision > revision.revision))
BEGIN SELECT RAISE(ABORT, 'Plan self-review result is stale'); END;
CREATE TRIGGER plan_self_review_resume_attempt_exact_v272
BEFORE INSERT ON plan_self_review_resume_attempt_v272
WHEN NOT EXISTS (
    SELECT 1
    FROM plan_self_review review
    JOIN task_turn predecessor ON predecessor.id = NEW.predecessor_turn_id
    JOIN task_turn successor ON successor.id = NEW.task_turn_id
    JOIN stage_resume_async_successor_v272 resume
      ON resume.handoff_id = NEW.handoff_id
    JOIN stage_resume_rearm_intent_v257 intent
      ON intent.handoff_id = resume.handoff_id
    WHERE review.id = NEW.self_review_id AND review.status = 'REQUESTED'
      AND predecessor.purpose = 'PLAN_SELF_REVIEW'
      AND predecessor.status IN ('CANCELED', 'SUPERSEDED')
      AND successor.purpose = 'PLAN_SELF_REVIEW'
      AND successor.status = 'REQUESTED'
      AND successor.operation_id = NEW.operation_id
      AND successor.task_id = predecessor.task_id
      AND successor.task_epoch = predecessor.task_epoch
      AND successor.trigger_stage_id = predecessor.trigger_stage_id
      AND successor.trigger_stage_generation = predecessor.trigger_stage_generation
      AND successor.expected_code_fingerprint IS predecessor.expected_code_fingerprint
      AND successor.expected_head_sha IS predecessor.expected_head_sha
      AND successor.expected_base_sha IS predecessor.expected_base_sha
      AND resume.status = 'PREPARED'
      AND resume.owner_kind = 'PLAN_SELF_REVIEW'
      AND resume.owner_id = successor.id
      AND resume.operation_id = successor.operation_id
      AND intent.status = 'PENDING'
      AND intent.task_id = successor.task_id
      AND intent.stage_id = successor.trigger_stage_id
      AND intent.stage_generation = successor.trigger_stage_generation
      AND intent.restore_checkpoint = 'SELF_REVIEW'
      AND NEW.semantic_attempt = 1 + (
          SELECT MAX(attempt.semantic_attempt)
          FROM plan_self_review_all_attempt_v265 attempt
          WHERE attempt.self_review_id = review.id))
BEGIN SELECT RAISE(ABORT, 'Plan self-review resume attempt is not exact'); END;
CREATE TRIGGER plan_self_review_resume_attempt_immutable_v272
BEFORE UPDATE ON plan_self_review_resume_attempt_v272
BEGIN SELECT RAISE(ABORT, 'Plan self-review resume attempt is immutable'); END;
CREATE TRIGGER plan_self_review_terminal_immutable
BEFORE UPDATE ON plan_self_review
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal Plan self-review is immutable'); END;
CREATE TRIGGER plan_self_review_transition
BEFORE UPDATE OF status ON plan_self_review
WHEN OLD.status <> 'REQUESTED'
  OR NEW.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'illegal Plan self-review transition'); END;
CREATE TRIGGER plan_self_review_user_wait_attempt_exact_v265
BEFORE INSERT ON plan_self_review_user_wait_attempt_v265
WHEN NOT EXISTS (
    SELECT 1
    FROM plan_self_review review
    JOIN task_turn predecessor ON predecessor.id = NEW.predecessor_turn_id
    JOIN task_turn successor ON successor.id = NEW.task_turn_id
    JOIN typed_user_wait_result result
      ON result.operation_id = predecessor.operation_id
    WHERE review.id = NEW.self_review_id AND review.status = 'REQUESTED'
      AND predecessor.purpose = 'PLAN_SELF_REVIEW'
      AND predecessor.status = 'SUCCEEDED'
      AND successor.purpose = 'PLAN_SELF_REVIEW'
      AND successor.status = 'REQUESTED'
      AND successor.operation_id = NEW.operation_id
      AND successor.task_id = predecessor.task_id
      AND successor.task_epoch = predecessor.task_epoch
      AND successor.trigger_stage_id = predecessor.trigger_stage_id
      AND successor.trigger_stage_generation = predecessor.trigger_stage_generation
      AND successor.expected_code_fingerprint IS predecessor.expected_code_fingerprint
      AND successor.expected_head_sha IS predecessor.expected_head_sha
      AND successor.expected_base_sha IS predecessor.expected_base_sha
      AND result.owner_kind = 'TASK_TURN'
      AND result.turn_id = predecessor.id
      AND result.wait_kind = NEW.wait_kind AND result.wait_id = NEW.wait_id
      AND NEW.semantic_attempt = 1 + (
          SELECT MAX(attempt.semantic_attempt)
          FROM plan_self_review_all_attempt_v265 attempt
          WHERE attempt.self_review_id = review.id))
BEGIN SELECT RAISE(ABORT, 'Plan self-review user-wait attempt is not exact'); END;
CREATE TRIGGER plan_self_review_user_wait_attempt_immutable_v265
BEFORE UPDATE ON plan_self_review_user_wait_attempt_v265
BEGIN SELECT RAISE(ABORT, 'Plan self-review user-wait attempt is immutable'); END;
CREATE TRIGGER plan_stage_identity_immutable
BEFORE UPDATE ON plan_stage
BEGIN SELECT RAISE(ABORT, 'Plan Stage identity is immutable'); END;
CREATE TRIGGER plan_stage_owner_insert
BEFORE INSERT ON plan_stage
WHEN NOT EXISTS (
    SELECT 1
    FROM stage s
    JOIN tasks t ON t.id = s.task_id
    WHERE s.id = NEW.stage_id
      AND s.task_id = NEW.task_id
      AND s.kind = 'PLAN'
      AND s.generation = NEW.generation
      AND t.workflow_version = 'V2'
      AND t.epoch = NEW.opened_for_epoch
      AND t.lifecycle_state = 'ACTIVE'
      AND s.completed_at_ms IS NULL
      AND EXISTS (
          SELECT 1 FROM task_current_stage c
          WHERE c.task_id = t.id
            AND c.stage_id = s.id
            AND c.stage_generation = s.generation))
BEGIN SELECT RAISE(ABORT, 'Plan subtype must match its exact V2 Stage and epoch'); END;
CREATE TRIGGER plan_task_turn_delivery_receipt_immutable
BEFORE UPDATE ON plan_task_turn_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Plan TaskTurn delivery receipt is immutable'); END;
CREATE TRIGGER plan_task_turn_delivery_receipt_insert
BEFORE INSERT ON plan_task_turn_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1 FROM task_turn turn
    WHERE turn.id = NEW.task_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.purpose IN ('PLAN_DRAFT', 'PLAN_SELF_REVIEW')
      AND turn.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
      AND ((NEW.acceptance = 'SUPERSEDED'
            AND turn.status = 'SUPERSEDED' AND NEW.domain_result = 'SUPERSEDED')
        OR (NEW.raw_outcome = 'SUCCEEDED' AND turn.status = 'SUCCEEDED'
            AND NEW.domain_result IN ('DRAFT_ACCEPTED', 'REVIEW_APPROVED',
                'REVIEW_FINDINGS', 'REVIEW_BLOCKED'))
        OR (NEW.raw_outcome = 'SUCCEEDED' AND turn.status = 'FAILED'
            AND NEW.domain_result = 'PROTOCOL_BLOCKED')
        OR (NEW.raw_outcome IN ('FAILED', 'INDETERMINATE')
            AND turn.status = 'FAILED' AND NEW.domain_result IN (
                'TURN_FAILED', 'REVIEW_RETRY_REQUESTED', 'REVIEW_BLOCKED'))
        OR (NEW.raw_outcome = 'CANCELED' AND turn.status = 'CANCELED'
            AND NEW.domain_result = 'TURN_CANCELED')))
BEGIN SELECT RAISE(ABORT, 'Plan TaskTurn delivery receipt is not exact'); END;
CREATE TRIGGER plan_task_turn_insert
BEFORE INSERT ON task_turn
WHEN NEW.purpose IN ('PLAN_DRAFT', 'PLAN_SELF_REVIEW')
BEGIN
    SELECT CASE WHEN
        NEW.status <> 'REQUESTED'
        OR (NEW.attempt <> 1 AND NOT EXISTS (
            SELECT 1
            FROM stage_resume_rearm_successor_v257 successor
            JOIN stage_resume_rearm_intent_v257 intent
              ON intent.handoff_id = successor.handoff_id
            WHERE successor.status = 'PREPARED'
              AND successor.owner_kind = 'TASK_TURN'
              AND successor.owner_id = NEW.id
              AND successor.operation_id = NEW.operation_id
              AND successor.semantic_attempt = NEW.attempt
              AND successor.purpose = NEW.purpose
              AND intent.status = 'PENDING'
              AND intent.task_id = NEW.task_id
              AND intent.task_epoch = NEW.task_epoch
              AND intent.stage_id = NEW.trigger_stage_id
              AND intent.stage_generation = NEW.trigger_stage_generation))
        OR NEW.trigger_stage_id IS NULL
        OR NEW.expected_code_fingerprint IS NULL
        OR NEW.expected_head_sha IS NULL
        OR NEW.expected_base_sha IS NULL
        OR NEW.delivery_lane NOT IN ('CLI', 'API')
        OR NOT json_valid(NEW.launch_input)
        OR json_extract(NEW.launch_input, '$.schemaVersion') <> 1
        OR json_extract(NEW.launch_input, '$.transport') <> NEW.delivery_lane
        OR json_extract(NEW.launch_input, '$.toolEndpoint.ownerKind') <> 'TASK_TURN'
        OR json_extract(NEW.launch_input, '$.toolEndpoint.ownerId') <> NEW.id
        OR json_extract(NEW.launch_input, '$.toolEndpoint.operationId') <> NEW.operation_id
        OR json_extract(NEW.launch_input, '$.toolEndpoint.profile') <> 'TASK_BRAIN_READ_ONLY'
        OR json_extract(NEW.launch_input, '$.toolEndpoint.approvalPromptTool')
            <> 'mcp__bytequay__approval_prompt'
        OR json_extract(NEW.launch_input, '$.toolEndpoint.url') NOT LIKE
            '%/api/v2/task-turns/' || NEW.id || '/operations/' || NEW.operation_id || '/mcp'
        OR length(trim(json_extract(NEW.launch_input, '$.prompt'))) = 0
        OR NOT EXISTS (
            SELECT 1
            FROM tasks task
            JOIN task_current_stage current ON current.task_id = task.id
            JOIN stage s ON s.id = current.stage_id
            JOIN plan_stage plan ON plan.stage_id = s.id
            JOIN task_code_identity code ON code.task_id = task.id
            JOIN task_brain brain ON brain.task_id = task.id
            WHERE task.id = NEW.task_id
              AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.task_epoch
              AND current.stage_id = NEW.trigger_stage_id
              AND current.stage_generation = NEW.trigger_stage_generation
              AND s.kind = 'PLAN' AND s.completed_at_ms IS NULL
              AND s.checkpoint IN ('DRAFTING', 'SELF_REVIEW')
              AND plan.task_id = task.id
              AND plan.generation = s.generation
              AND plan.opened_for_epoch = task.epoch
              AND code.code_fingerprint = NEW.expected_code_fingerprint
              AND code.local_head_sha = NEW.expected_head_sha
              AND code.base_sha = NEW.expected_base_sha
              AND code.worktree_path = json_extract(NEW.launch_input, '$.workingDirectory')
              AND brain.provider = json_extract(NEW.launch_input, '$.provider')
              AND brain.model = json_extract(NEW.launch_input, '$.model'))
    THEN RAISE(ABORT, 'Plan TaskTurn does not match its frozen owner') END;
END;
CREATE TRIGGER plan_turn_submission_immutable
BEFORE UPDATE ON plan_turn_submission
BEGIN SELECT RAISE(ABORT, 'Plan submission is immutable'); END;
CREATE TRIGGER plan_turn_submission_insert
BEFORE INSERT ON plan_turn_submission
WHEN NOT EXISTS (
    SELECT 1
    FROM task_turn turn
    JOIN dispatch_ticket ticket ON ticket.operation_id = turn.operation_id
    JOIN plan_revision revision ON revision.id = NEW.plan_revision_id
    JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
    JOIN stage s ON s.id = plan.stage_id
    JOIN tasks task ON task.id = turn.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    WHERE turn.id = NEW.task_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.purpose = 'PLAN_DRAFT'
      AND turn.status = 'RUNNING'
      AND turn.task_id = NEW.task_id
      AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id = NEW.plan_stage_id
      AND turn.trigger_stage_generation = NEW.stage_generation
      AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
      AND ticket.status = 'RUNNING'
      AND revision.plan_stage_id = NEW.plan_stage_id
      AND revision.created_by = turn.id
      AND plan.task_id = task.id AND plan.generation = NEW.stage_generation
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND current.stage_id = s.id AND current.stage_generation = s.generation
      AND s.checkpoint = 'DRAFTING' AND s.completed_at_ms IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = revision.plan_stage_id
            AND newer.revision > revision.revision))
BEGIN SELECT RAISE(ABORT, 'Plan submission does not match its running TaskTurn'); END;
CREATE TRIGGER plan_turn_user_wait_continuation_exact_v265
BEFORE INSERT ON plan_turn_user_wait_continuation_v265
WHEN NOT EXISTS (
    SELECT 1
    FROM task_turn predecessor
    JOIN task_turn successor ON successor.id = NEW.successor_turn_id
    JOIN typed_user_wait_result result
      ON result.operation_id = predecessor.operation_id
    JOIN stage owner ON owner.id = predecessor.trigger_stage_id
    JOIN tasks task ON task.id = predecessor.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    WHERE predecessor.id = NEW.predecessor_turn_id
      AND predecessor.operation_id = NEW.predecessor_operation_id
      AND predecessor.status = 'SUCCEEDED'
      AND result.owner_kind = 'TASK_TURN'
      AND result.turn_id = predecessor.id
      AND result.wait_kind = NEW.wait_kind AND result.wait_id = NEW.wait_id
      AND successor.id <> predecessor.id
      AND successor.operation_id = NEW.successor_operation_id
      AND successor.task_id = predecessor.task_id
      AND successor.task_epoch = predecessor.task_epoch
      AND successor.trigger_stage_id = predecessor.trigger_stage_id
      AND successor.trigger_stage_generation = predecessor.trigger_stage_generation
      AND successor.purpose = predecessor.purpose
      AND successor.expected_code_fingerprint IS predecessor.expected_code_fingerprint
      AND successor.expected_head_sha IS predecessor.expected_head_sha
      AND successor.expected_base_sha IS predecessor.expected_base_sha
      AND successor.status = 'REQUESTED'
      AND task.id = NEW.task_id AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE' AND task.epoch = NEW.task_epoch
      AND owner.id = NEW.stage_id
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.returned_stage_version
      AND owner.checkpoint = NEW.checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND current.stage_id = owner.id
      AND current.stage_generation = owner.generation
      AND ((NEW.wait_kind = 'QUESTION' AND EXISTS (
            SELECT 1 FROM task_question question
            WHERE question.id = NEW.wait_id
              AND question.turn_id = predecessor.id
              AND question.state = 'ANSWERED'
              AND question.continuation_state = 'READY'))
        OR (NEW.wait_kind = 'PERMISSION' AND EXISTS (
            SELECT 1 FROM permission_request permission
            WHERE permission.id = NEW.wait_id
              AND permission.turn_kind = 'TASK'
              AND permission.turn_id = predecessor.id
              AND permission.operation_id = predecessor.operation_id
              AND permission.state <> 'OPEN'
              AND permission.continuation_state = 'READY'))))
BEGIN SELECT RAISE(ABORT, 'Plan user-wait continuation is not exact'); END;
CREATE TRIGGER plan_turn_user_wait_continuation_immutable_v265
BEFORE UPDATE ON plan_turn_user_wait_continuation_v265
BEGIN SELECT RAISE(ABORT, 'Plan user-wait continuation is immutable'); END;
CREATE TRIGGER plan_user_edit_receipt_immutable
BEFORE UPDATE ON plan_user_edit_receipt
BEGIN SELECT RAISE(ABORT, 'Plan user edit receipt is immutable'); END;
CREATE TRIGGER plan_user_edit_receipt_insert
BEFORE INSERT ON plan_user_edit_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage s ON s.id = current.stage_id
    JOIN plan_stage plan ON plan.stage_id = s.id
    JOIN plan_revision revision ON revision.id = NEW.plan_revision_id
    JOIN plan_revision previous ON previous.id = NEW.previous_revision_id
    JOIN plan_self_review review ON review.id = NEW.self_review_id
    JOIN task_turn turn ON turn.id = NEW.review_turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.review_ticket_id
    JOIN stage_plan_edit_review_request request
      ON request.command_id = NEW.review_command_id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.plan_stage_id
      AND current.stage_generation = NEW.stage_generation
      AND s.kind = 'PLAN' AND s.generation = NEW.stage_generation
      AND s.checkpoint = 'SELF_REVIEW'
      AND s.version = NEW.expected_stage_version + 2
      AND s.completed_at_ms IS NULL
      AND plan.task_id = task.id AND plan.generation = s.generation
      AND revision.plan_stage_id = plan.stage_id
      AND revision.revision = previous.revision + 1
      AND revision.source = 'USER_EDIT'
      AND revision.created_by = NEW.actor
      AND revision.content_digest = NEW.content_digest
      AND previous.plan_stage_id = revision.plan_stage_id
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = revision.plan_stage_id
            AND newer.revision > revision.revision)
      AND review.plan_revision_id = revision.id
      AND review.task_turn_id = turn.id
      AND review.task_epoch = NEW.task_epoch
      AND review.reviewed_digest = revision.content_digest
      AND review.status = 'REQUESTED'
      AND turn.operation_id = NEW.review_operation_id
      AND turn.task_id = task.id AND turn.task_epoch = task.epoch
      AND turn.trigger_stage_id = s.id
      AND turn.trigger_stage_generation = s.generation
      AND turn.purpose = 'PLAN_SELF_REVIEW'
      AND turn.status = 'REQUESTED'
      AND ticket.operation_id = turn.operation_id
      AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.status = 'REQUESTED'
      AND request.stage_id = s.id AND request.task_id = task.id
      AND request.expected_task_epoch = task.epoch
      AND request.expected_stage_generation = s.generation
      AND request.expected_stage_version = NEW.expected_stage_version + 1
      AND request.returned_stage_version = s.version
      AND request.revision_id = revision.id
      AND request.pending_operation_id = turn.operation_id)
BEGIN SELECT RAISE(ABORT, 'Plan user edit receipt is not exact'); END;
CREATE TRIGGER planning_base_dispatch_shape_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'REFRESH_PLANNING_BASE'
  OR NEW.callback_route = 'PLANNING_BASE_REFRESH_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM planning_base_refresh_operation operation
        WHERE operation.dispatch_ticket_id = NEW.id
          AND operation.operation_id = NEW.operation_id
          AND operation.trunk_id = NEW.owner_id
          AND operation.workspace_id = NEW.workspace_id
          AND operation.semantic_attempt = NEW.attempt
          AND operation.previous_base_sha IS NEW.expected_base_sha)
      OR NEW.async_family <> 'LOCAL_GIT'
      OR NEW.owner_kind <> 'TRUNK'
      OR NEW.callback_route <> 'PLANNING_BASE_REFRESH_RESULT'
      OR NEW.lane_mask <> 16
      OR NEW.trunk_control <> 1
      OR NEW.exclusive_task <> 0
      OR NEW.writer_required <> 0
      OR NEW.task_id IS NOT NULL OR NEW.task_epoch IS NOT NULL
      OR NEW.stage_id IS NOT NULL OR NEW.stage_generation IS NOT NULL
    THEN RAISE(ABORT, 'Planning-base refresh ticket is not exact') END;
END;
CREATE TRIGGER planning_base_dispatch_shape_update
BEFORE UPDATE OF operation_kind, async_family, owner_kind, owner_id,
        callback_route, lane_mask, trunk_control, exclusive_task,
        writer_required, workspace_id, trunk_id, task_id, task_epoch,
        stage_id, stage_generation, expected_base_sha ON dispatch_ticket
WHEN NEW.operation_kind = 'REFRESH_PLANNING_BASE'
  OR NEW.callback_route = 'PLANNING_BASE_REFRESH_RESULT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM planning_base_refresh_operation operation
        WHERE operation.dispatch_ticket_id = NEW.id
          AND operation.operation_id = NEW.operation_id
          AND operation.trunk_id = NEW.owner_id
          AND operation.workspace_id = NEW.workspace_id
          AND operation.semantic_attempt = NEW.attempt
          AND operation.previous_base_sha IS NEW.expected_base_sha)
      OR NEW.async_family <> 'LOCAL_GIT'
      OR NEW.owner_kind <> 'TRUNK'
      OR NEW.callback_route <> 'PLANNING_BASE_REFRESH_RESULT'
      OR NEW.lane_mask <> 16
      OR NEW.trunk_control <> 1
      OR NEW.exclusive_task <> 0
      OR NEW.writer_required <> 0
      OR NEW.task_id IS NOT NULL OR NEW.task_epoch IS NOT NULL
      OR NEW.stage_id IS NOT NULL OR NEW.stage_generation IS NOT NULL
    THEN RAISE(ABORT, 'Planning-base refresh ticket is not exact') END;
END;
CREATE TRIGGER planning_base_refresh_delete_immutable
BEFORE DELETE ON planning_base_refresh_operation
WHEN NOT EXISTS (
    SELECT 1 FROM v2_trunk_purge_authorization_v269 authorization
    WHERE authorization.trunk_id = OLD.trunk_id)
BEGIN SELECT RAISE(ABORT, 'Planning-base Operation cannot be deleted'); END;
CREATE TRIGGER planning_base_refresh_identity_immutable
BEFORE UPDATE OF trunk_id, workspace_id, command_id, actor, operation_id,
        dispatch_ticket_id, launch_command_id, reserved_thread_turn_id,
        semantic_attempt,
        repository_root, previous_base_sha, launch_intent,
        launch_intent_digest, requested_at_ms
        ON planning_base_refresh_operation
WHEN NEW.trunk_id IS NOT OLD.trunk_id
  OR NEW.workspace_id IS NOT OLD.workspace_id
  OR NEW.command_id IS NOT OLD.command_id
  OR NEW.actor IS NOT OLD.actor
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.dispatch_ticket_id IS NOT OLD.dispatch_ticket_id
  OR NEW.launch_command_id IS NOT OLD.launch_command_id
  OR NEW.reserved_thread_turn_id IS NOT OLD.reserved_thread_turn_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.repository_root IS NOT OLD.repository_root
  OR NEW.previous_base_sha IS NOT OLD.previous_base_sha
  OR NEW.launch_intent IS NOT OLD.launch_intent
  OR NEW.launch_intent_digest IS NOT OLD.launch_intent_digest
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'Planning-base Operation identity is immutable'); END;
CREATE TRIGGER planning_base_refresh_terminal_immutable
BEFORE UPDATE ON planning_base_refresh_operation
WHEN OLD.status <> 'REQUESTED'
  AND NOT (OLD.status = 'SUCCEEDED'
      AND OLD.launch_disposition = 'PENDING'
      AND NEW.launch_disposition IN ('LAUNCHED', 'SUPPRESSED')
      AND NEW.launched_at_ms IS NOT NULL
      AND NEW.status = OLD.status
      AND NEW.raw_outcome = OLD.raw_outcome
      AND NEW.raw_result_digest = OLD.raw_result_digest
      AND NEW.result_worktree_path = OLD.result_worktree_path
      AND NEW.result_base_ref = OLD.result_base_ref
      AND NEW.result_base_sha = OLD.result_base_sha
      AND NEW.error_message IS OLD.error_message
      AND NEW.completed_at_ms = OLD.completed_at_ms
      AND ((NEW.launch_disposition = 'LAUNCHED'
              AND NEW.launch_disposition_reason IS NULL
              AND NEW.launched_thread_turn_id = OLD.reserved_thread_turn_id)
          OR (NEW.launch_disposition = 'SUPPRESSED'
              AND NEW.launch_disposition_reason IS NOT NULL
              AND NEW.launched_thread_turn_id IS NULL)))
BEGIN SELECT RAISE(ABORT, 'Terminal Planning-base Operation is immutable'); END;
CREATE TRIGGER planning_base_refresh_transition
BEFORE UPDATE OF status ON planning_base_refresh_operation
WHEN NEW.status IS NOT OLD.status
  AND NOT (OLD.status = 'REQUESTED'
      AND NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
BEGIN SELECT RAISE(ABORT, 'Planning-base Operation transition is invalid'); END;
CREATE TRIGGER promotion_manifest_immutable
BEFORE UPDATE ON promotion_manifest
BEGIN SELECT RAISE(ABORT, 'PromotionManifest is immutable'); END;
CREATE TRIGGER promotion_manifest_insert
BEFORE INSERT ON promotion_manifest
BEGIN
    SELECT CASE
        WHEN NEW.revision <> COALESCE((
            SELECT MAX(manifest.revision) + 1 FROM promotion_manifest manifest
            WHERE manifest.local_development_stage_id = NEW.local_development_stage_id), 1)
            THEN RAISE(ABORT, 'PromotionManifest revision must be exact')
        WHEN NOT EXISTS (
            SELECT 1
            FROM local_development_stage l
            JOIN stage s ON s.id = l.stage_id
            JOIN tasks t ON t.id = l.task_id
            JOIN task_current_stage current ON current.stage_id = l.stage_id
            JOIN dev_report report ON report.id = NEW.dev_report_id
            JOIN pr p ON p.id = NEW.pr_id
            JOIN task_policy_revision policy ON policy.id = NEW.policy_revision_id
            JOIN task_creation_context context ON context.task_id = t.id
            JOIN task_code_identity code ON code.task_id = t.id
            WHERE l.stage_id = NEW.local_development_stage_id
              AND l.task_id = NEW.task_id
              AND l.opened_for_epoch = NEW.task_epoch
              AND l.generation = NEW.stage_generation
              AND s.completed_at_ms IS NULL
              AND t.workflow_version = 'V2'
              AND t.lifecycle_state = 'ACTIVE' AND t.epoch = NEW.task_epoch
              AND current.task_id = NEW.task_id
              AND current.stage_generation = NEW.stage_generation
              AND report.workflow_version = 'V2'
              AND report.local_development_stage_id = l.stage_id
              AND report.task_id = NEW.task_id
              AND report.task_epoch = NEW.task_epoch
              AND report.stage_generation = NEW.stage_generation
              AND report.code_fingerprint = NEW.code_fingerprint
              AND report.head_sha = NEW.head_sha
              AND report.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision)
              AND p.task_id = NEW.task_id AND p.origin = 'task'
              AND p.branch_name = NEW.branch_name
              AND p.base_branch = NEW.base_branch
              AND p.title = NEW.pr_title AND p.description = NEW.pr_body
              AND policy.id = t.policy_revision_id
              AND policy.trunk_id = t.thread_id
              AND code.branch_name = NEW.branch_name
              AND NEW.publish_repository_id = context.publish_repository_id
              AND NEW.head_repository_id = context.publish_repository_id
              AND ((context.upstream_repository_id IS NULL
                    AND NEW.route = 'DIRECT'
                    AND NEW.base_repository_id = context.repository_id
                    AND context.repository_id = context.publish_repository_id)
                OR (context.upstream_repository_id IS NOT NULL
                    AND NEW.route = 'FORK'
                    AND NEW.base_repository_id = context.upstream_repository_id)))
            THEN RAISE(ABORT, 'PromotionManifest does not prove the exact local publish subject')
    END;
END;
CREATE TRIGGER protect_resolved_backlog_link
BEFORE UPDATE ON backlog_item
WHEN OLD.linked_task_id IS NOT NULL
    AND (
        (
            NEW.linked_task_id IS NOT OLD.linked_task_id
            AND NOT (
                NEW.linked_task_id IS NULL
                AND NOT EXISTS (
                    SELECT 1 FROM tasks WHERE id = OLD.linked_task_id
                )
            )
        )
        OR NEW.resolved_at_ms IS NULL
        OR NEW.status NOT IN ('resolved', 'shipped', 'closed')
    )
BEGIN
    SELECT RAISE(ABORT, 'resolved_backlog_link_is_immutable');
END;
CREATE TRIGGER provision_task_operation_dispatch_fence
BEFORE UPDATE OF status ON provision_task_operation
WHEN NEW.status = 'DISPATCHED'
  AND NOT EXISTS (
      SELECT 1 FROM dispatch_ticket ticket
      WHERE ticket.operation_id = NEW.operation_id
        AND ticket.operation_kind = 'PROVISION_TASK'
        AND ticket.async_family = 'LOCAL_GIT'
        AND ticket.owner_kind = 'TASK' AND ticket.owner_id = NEW.task_id
        AND ticket.task_id = NEW.task_id AND ticket.task_epoch = NEW.task_epoch
        AND ticket.stage_id IS NULL AND ticket.stage_generation IS NULL
        AND ticket.attempt = NEW.semantic_attempt
        AND ticket.expected_code_fingerprint IS NULL
        AND ticket.expected_base_sha IS NEW.expected_base_sha
        AND ticket.expected_head_sha IS NEW.expected_remote_head_sha
        AND ticket.exclusive_task = 1 AND ticket.writer_required = 1
        AND ticket.lane_mask = CASE
              WHEN NEW.base_source = 'EXISTING_PR_HEAD'
                AND NEW.expected_base_sha IS NULL
                AND NEW.expected_remote_head_sha IS NULL THEN 48
              ELSE 16 END
        AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT,
    'dispatched provisioning requires exact dispatcher capacity'); END;
CREATE TRIGGER provision_task_operation_identity_immutable
BEFORE UPDATE OF task_id, task_epoch, assignment_id, operation_id,
        semantic_attempt, repository_id, expected_base_sha,
        expected_remote_head_sha, requested_branch_name,
        requested_worktree_path, created_at_ms ON provision_task_operation
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.assignment_id IS NOT OLD.assignment_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.repository_id IS NOT OLD.repository_id
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.expected_remote_head_sha IS NOT OLD.expected_remote_head_sha
  OR NEW.requested_branch_name IS NOT OLD.requested_branch_name
  OR NEW.requested_worktree_path IS NOT OLD.requested_worktree_path
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'provision operation fence is immutable'); END;
CREATE TRIGGER provision_task_operation_owner_insert
BEFORE INSERT ON provision_task_operation
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'ProvisionTaskOperation must start REQUESTED')
        WHEN NEW.base_source IS NULL OR NEW.base_repository_id IS NULL
          OR (NEW.base_source <> 'EXISTING_PR_HEAD' AND NEW.base_ref IS NULL)
            THEN RAISE(ABORT, 'ProvisionTaskOperation source must be typed')
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            JOIN task_creation_context context ON context.task_id = task.id
            WHERE task.id = NEW.task_id
              AND task.workflow_version = 'V2'
              AND task.epoch = NEW.task_epoch
              AND task.lifecycle_state = 'PROVISIONING'
              AND task.assignment_id = NEW.assignment_id
              AND context.assignment_id = NEW.assignment_id
              AND context.repository_id = NEW.repository_id
              AND context.base_source = NEW.base_source
              AND context.base_repository_id = NEW.base_repository_id
              AND context.base_ref IS NEW.base_ref
              AND NEW.expected_base_sha IS CASE context.base_source
                    WHEN 'PLANNING_SNAPSHOT' THEN context.planning_base_sha
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_base_sha
                    ELSE NULL END
              AND NEW.expected_remote_head_sha IS CASE context.base_source
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_head_sha
                    ELSE NULL END)
            THEN RAISE(ABORT, 'ProvisionTaskOperation does not match frozen creation source')
    END;
END;
CREATE TRIGGER provision_task_operation_result_fields_guard
BEFORE UPDATE OF result_base_sha, result_head_sha, result_code_fingerprint,
        result_evidence ON provision_task_operation
WHEN OLD.status <> 'DISPATCHED' OR NEW.status <> 'ACCEPTED'
BEGIN SELECT RAISE(ABORT, 'ProvisionTaskOperation result requires acceptance'); END;
CREATE TRIGGER provision_task_operation_result_update_fence
BEFORE UPDATE ON provision_task_operation
WHEN NEW.status = 'ACCEPTED'
  AND (NEW.result_evidence IS NULL OR length(trim(NEW.result_evidence)) = 0
    OR NEW.result_code_fingerprint IS NULL
    OR length(trim(NEW.result_code_fingerprint)) = 0
    OR (NEW.base_source = 'PLANNING_SNAPSHOT'
        AND (NEW.expected_base_sha IS NULL
          OR NEW.expected_remote_head_sha IS NOT NULL
          OR NEW.result_base_sha IS NOT NEW.expected_base_sha
          OR NEW.result_head_sha IS NOT NEW.expected_base_sha))
    OR (NEW.base_source = 'FRESH_REMOTE_BASE'
        AND (NEW.expected_base_sha IS NOT NULL
          OR NEW.expected_remote_head_sha IS NOT NULL
          OR length(trim(NEW.result_base_sha)) = 0
          OR NEW.result_head_sha IS NOT NEW.result_base_sha))
    OR (NEW.base_source = 'EXISTING_PR_HEAD' AND NOT (
        (NEW.expected_base_sha IS NOT NULL
          AND NEW.expected_remote_head_sha IS NOT NULL
          AND NEW.result_base_sha IS NEW.expected_base_sha
          AND NEW.result_head_sha IS NEW.expected_remote_head_sha)
        OR (NEW.expected_base_sha IS NULL
          AND NEW.expected_remote_head_sha IS NULL
          AND length(trim(NEW.result_base_sha)) > 0
          AND length(trim(NEW.result_head_sha)) > 0
          AND json_valid(NEW.result_evidence) = 1
          AND json_extract(NEW.result_evidence, '$.schema') = 'PROVISION_TASK_V2'
          AND json_extract(NEW.result_evidence, '$.baseSource') = 'EXISTING_PR_HEAD'
          AND json_extract(NEW.result_evidence, '$.baseSha') = NEW.result_base_sha
          AND json_extract(NEW.result_evidence, '$.headSha') = NEW.result_head_sha
          AND json_extract(NEW.result_evidence, '$.pullRequest.baseSha')
                = NEW.result_base_sha
          AND json_extract(NEW.result_evidence, '$.pullRequest.headSha')
                = NEW.result_head_sha
          AND EXISTS (
              SELECT 1 FROM task_assignment assignment
              JOIN task_creation_context context
                ON context.assignment_id = assignment.id
              WHERE assignment.id = NEW.assignment_id
                AND context.task_id = NEW.task_id
                AND assignment.kind IN ('EXISTING_OWN_PR', 'REVIEW_FINDINGS')
                AND assignment.pr_number
                    = json_extract(NEW.result_evidence, '$.pullRequest.number')
                AND lower(assignment.base_repository_id) = lower(json_extract(
                    NEW.result_evidence, '$.pullRequest.baseRepositoryId'))
                AND lower(assignment.head_repository_id) = lower(json_extract(
                    NEW.result_evidence, '$.pullRequest.headRepositoryId'))
                AND lower(context.base_repository_id) = lower(json_extract(
                    NEW.result_evidence, '$.pullRequest.baseRepositoryId'))
                AND lower(context.publish_repository_id) = lower(json_extract(
                    NEW.result_evidence, '$.pullRequest.headRepositoryId'))
                AND (assignment.kind = 'EXISTING_OWN_PR' OR EXISTS (
                    SELECT 1 FROM review_build_selection selection
                    WHERE selection.thread_id = (
                            SELECT thread_id FROM tasks WHERE id = NEW.task_id)
                      AND selection.review_pass_id = assignment.source_id
                      AND selection.pr_number = assignment.pr_number
                      AND selection.reviewed_head_sha = NEW.result_head_sha
                      AND lower(selection.base_repository_id) = lower(json_extract(
                          NEW.result_evidence, '$.pullRequest.baseRepositoryId'))
                      AND lower(selection.head_repository_id) = lower(json_extract(
                          NEW.result_evidence, '$.pullRequest.headRepositoryId'))
                      AND selection.base_ref = json_extract(
                          NEW.result_evidence, '$.pullRequest.baseRef')
                      AND selection.head_ref = json_extract(
                          NEW.result_evidence, '$.pullRequest.headRef')
                      AND (SELECT COUNT(*)
                           FROM task_assignment_review_finding assigned
                           WHERE assigned.assignment_id = assignment.id)
                          = (SELECT COUNT(*)
                             FROM review_build_selection_item frozen
                             WHERE frozen.thread_id = selection.thread_id)
                      AND NOT EXISTS (
                          SELECT 1 FROM review_build_selection_item frozen
                          LEFT JOIN task_assignment_review_finding assigned
                            ON assigned.assignment_id = assignment.id
                           AND assigned.source_review_id = frozen.review_pass_id
                           AND assigned.finding_id = frozen.finding_id
                           AND assigned.finding_revision = frozen.finding_revision
                           AND assigned.content_digest = frozen.content_digest
                          JOIN review_findings current
                            ON current.id = frozen.finding_id
                          WHERE frozen.thread_id = selection.thread_id
                            AND (assigned.finding_id IS NULL
                              OR current.review_pass_id <> frozen.review_pass_id
                              OR current.revision <> frozen.finding_revision
                              OR current.status <> 'agreed'))))))))
    OR NOT EXISTS (
        SELECT 1 FROM tasks task
        WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
          AND task.epoch = NEW.task_epoch
          AND task.lifecycle_state = 'PROVISIONING'
          AND task.assignment_id = NEW.assignment_id)
    OR NOT EXISTS (
        SELECT 1 FROM dispatch_ticket ticket
        WHERE ticket.operation_id = NEW.operation_id
          AND ticket.operation_kind = 'PROVISION_TASK'
          AND ticket.async_family = 'LOCAL_GIT'
          AND ticket.owner_kind = 'TASK' AND ticket.owner_id = NEW.task_id
          AND ticket.task_id = NEW.task_id AND ticket.task_epoch = NEW.task_epoch
          AND ticket.stage_id IS NULL AND ticket.stage_generation IS NULL
          AND ticket.attempt = NEW.semantic_attempt
          AND ticket.expected_code_fingerprint IS NULL
          AND ticket.expected_base_sha IS NEW.expected_base_sha
          AND ticket.expected_head_sha IS NEW.expected_remote_head_sha
          AND ticket.lane_mask = CASE
              WHEN NEW.base_source = 'EXISTING_PR_HEAD'
                AND NEW.expected_base_sha IS NULL
                AND NEW.expected_remote_head_sha IS NULL THEN 48
              ELSE 16 END
          AND ticket.status = 'RESULT_PENDING'
          AND ticket.pending_result_outcome = 'SUCCEEDED'
          AND ticket.pending_result_task_epoch = NEW.task_epoch
          AND ticket.pending_result_stage_id IS NULL
          AND ticket.pending_result_stage_generation IS NULL
          AND ticket.pending_result_operation_id = NEW.operation_id
          AND ticket.pending_result_attempt = NEW.semantic_attempt
          AND ticket.pending_result_expected_code_fingerprint IS NULL
          AND ticket.pending_result_expected_base_sha IS NEW.expected_base_sha
          AND ticket.pending_result_expected_head_sha IS NEW.expected_remote_head_sha
          AND ticket.pending_result_evidence = NEW.result_evidence))
BEGIN SELECT RAISE(ABORT,
    'accepted provisioning result lacks exact source/evidence'); END;
CREATE TRIGGER provision_task_operation_terminal_immutable
BEFORE UPDATE ON provision_task_operation
WHEN OLD.status IN ('ACCEPTED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal provisioning operation is immutable'); END;
CREATE TRIGGER provision_task_operation_transition
BEFORE UPDATE OF status ON provision_task_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'ACCEPTED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'illegal provisioning operation transition'); END;
CREATE TRIGGER provision_task_operation_v229_identity_immutable
BEFORE UPDATE OF base_source, base_repository_id, base_ref
ON provision_task_operation
WHEN NEW.base_source IS NOT OLD.base_source
  OR NEW.base_repository_id IS NOT OLD.base_repository_id
  OR NEW.base_ref IS NOT OLD.base_ref
BEGIN SELECT RAISE(ABORT, 'ProvisionTaskOperation source is immutable'); END;
CREATE TRIGGER publish_authorization_consumption_proof
BEFORE UPDATE OF consumed_at_ms, outcome ON publish_authorization
WHEN NEW.consumed_at_ms IS NOT NULL
  AND NOT (
      (NEW.outcome = 'PUBLISHED' AND EXISTS (
          SELECT 1 FROM remote_pr_binding binding
          WHERE binding.publish_authorization_id = NEW.id
            AND binding.task_id = NEW.task_id
            AND binding.pr_id = NEW.pr_id
            AND binding.remote_head_sha = NEW.head_sha
            AND binding.remote_base_sha = NEW.base_sha))
      OR (NEW.outcome IN ('CANCELED', 'SUPERSEDED') AND EXISTS (
          SELECT 1 FROM publish_operation operation
          WHERE operation.publish_authorization_id = NEW.id
            AND operation.local_development_stage_id = NEW.local_development_stage_id
            AND operation.task_id = NEW.task_id
            AND operation.task_epoch = NEW.task_epoch
            AND operation.stage_generation = NEW.stage_generation
            AND operation.code_fingerprint = NEW.code_fingerprint
            AND operation.expected_head_sha = NEW.head_sha
            AND operation.expected_base_sha = NEW.base_sha
            AND operation.status = NEW.outcome
            AND operation.completed_at_ms IS NOT NULL)))
BEGIN SELECT RAISE(ABORT, 'consumed PublishAuthorization lacks exact terminal proof'); END;
CREATE TRIGGER publish_authorization_identity_immutable
BEFORE UPDATE OF local_development_stage_id, task_id, task_epoch,
        stage_generation, manifest_id, dev_report_id, validation_evidence_id,
        brain_review_episode_id, pr_id, policy_revision_id, publish_override_id,
        code_fingerprint, head_sha, base_sha, route, base_repository_id,
        head_repository_id, publish_repository_id, branch_name, head_ref,
        base_branch, pr_content_revision, pr_content_digest, consent_kind,
        consent_id, actor_id, brain_basis, brain_escalation_reason,
        authorized_operation_id, authorized_attempt, created_at_ms
ON publish_authorization
WHEN NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.manifest_id IS NOT OLD.manifest_id
  OR NEW.dev_report_id IS NOT OLD.dev_report_id
  OR NEW.validation_evidence_id IS NOT OLD.validation_evidence_id
  OR NEW.brain_review_episode_id IS NOT OLD.brain_review_episode_id
  OR NEW.pr_id IS NOT OLD.pr_id
  OR NEW.policy_revision_id IS NOT OLD.policy_revision_id
  OR NEW.publish_override_id IS NOT OLD.publish_override_id
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.head_sha IS NOT OLD.head_sha OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.route IS NOT OLD.route
  OR NEW.base_repository_id IS NOT OLD.base_repository_id
  OR NEW.head_repository_id IS NOT OLD.head_repository_id
  OR NEW.publish_repository_id IS NOT OLD.publish_repository_id
  OR NEW.branch_name IS NOT OLD.branch_name OR NEW.head_ref IS NOT OLD.head_ref
  OR NEW.base_branch IS NOT OLD.base_branch
  OR NEW.pr_content_revision IS NOT OLD.pr_content_revision
  OR NEW.pr_content_digest IS NOT OLD.pr_content_digest
  OR NEW.consent_kind IS NOT OLD.consent_kind
  OR NEW.consent_id IS NOT OLD.consent_id OR NEW.actor_id IS NOT OLD.actor_id
  OR NEW.brain_basis IS NOT OLD.brain_basis
  OR NEW.brain_escalation_reason IS NOT OLD.brain_escalation_reason
  OR NEW.authorized_operation_id IS NOT OLD.authorized_operation_id
  OR NEW.authorized_attempt IS NOT OLD.authorized_attempt
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'PublishAuthorization proof is immutable'); END;
CREATE TRIGGER publish_authorization_insert
BEFORE INSERT ON publish_authorization
BEGIN
    SELECT CASE
        WHEN NEW.revoked_at_ms IS NOT NULL OR NEW.consumed_at_ms IS NOT NULL
            THEN RAISE(ABORT, 'PublishAuthorization must start active')
        WHEN NOT EXISTS (
            SELECT 1
            FROM promotion_manifest manifest
            JOIN local_development_stage l
              ON l.stage_id = manifest.local_development_stage_id
            JOIN stage s ON s.id = l.stage_id
            JOIN tasks t ON t.id = l.task_id
            JOIN task_current_stage current ON current.stage_id = l.stage_id
            JOIN dev_report report ON report.id = NEW.dev_report_id
            JOIN pr p ON p.id = NEW.pr_id
            JOIN task_policy_revision policy ON policy.id = NEW.policy_revision_id
            WHERE manifest.id = NEW.manifest_id
              AND manifest.local_development_stage_id = NEW.local_development_stage_id
              AND manifest.task_id = NEW.task_id
              AND manifest.task_epoch = NEW.task_epoch
              AND manifest.stage_generation = NEW.stage_generation
              AND manifest.dev_report_id = NEW.dev_report_id
              AND manifest.pr_id = NEW.pr_id
              AND manifest.policy_revision_id = NEW.policy_revision_id
              AND manifest.code_fingerprint = NEW.code_fingerprint
              AND manifest.head_sha = NEW.head_sha
              AND manifest.base_sha = NEW.base_sha
              AND manifest.route = NEW.route
              AND manifest.base_repository_id = NEW.base_repository_id
              AND manifest.head_repository_id = NEW.head_repository_id
              AND manifest.publish_repository_id = NEW.publish_repository_id
              AND manifest.branch_name = NEW.branch_name
              AND manifest.head_ref = NEW.head_ref
              AND manifest.base_branch = NEW.base_branch
              AND manifest.pr_content_revision = NEW.pr_content_revision
              AND manifest.pr_content_digest = NEW.pr_content_digest
              AND manifest.require_clean_worktree = 1 AND manifest.minimum_commits_ahead > 0
              AND manifest.require_branch_match = 1 AND manifest.require_base_match = 1
              AND manifest.require_publish_permission = 1
              AND l.opened_for_epoch = NEW.task_epoch
              AND l.generation = NEW.stage_generation
              AND s.completed_at_ms IS NULL
              AND t.workflow_version = 'V2'
              AND t.lifecycle_state = 'ACTIVE' AND t.epoch = NEW.task_epoch
              AND current.task_id = NEW.task_id
              AND current.stage_generation = NEW.stage_generation
              AND report.workflow_version = 'V2'
              AND report.local_development_stage_id = l.stage_id
              AND report.task_id = NEW.task_id
              AND report.task_epoch = NEW.task_epoch
              AND report.stage_generation = NEW.stage_generation
              AND report.code_fingerprint = NEW.code_fingerprint
              AND report.head_sha = NEW.head_sha AND report.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision)
              AND p.task_id = NEW.task_id AND p.origin = 'task'
              AND policy.id = t.policy_revision_id)
            THEN RAISE(ABORT, 'PublishAuthorization does not match its current manifest')
        WHEN NOT EXISTS (
            SELECT 1
            FROM validation_evidence evidence
            JOIN validation_operation operation
              ON operation.id = evidence.validation_operation_id
            WHERE evidence.id = NEW.validation_evidence_id
              AND operation.dev_report_id = NEW.dev_report_id
              AND operation.status = 'COMPLETED'
              AND evidence.task_id = NEW.task_id
              AND evidence.task_epoch = NEW.task_epoch
              AND evidence.stage_id = NEW.local_development_stage_id
              AND evidence.stage_generation = NEW.stage_generation
              AND evidence.code_fingerprint = NEW.code_fingerprint
              AND evidence.head_sha = NEW.head_sha
              AND evidence.base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM validation_operation newer
                  WHERE newer.dev_report_id = operation.dev_report_id
                    AND newer.semantic_attempt > operation.semantic_attempt)
              AND (evidence.passed = 1 OR EXISTS (
                  SELECT 1 FROM publish_override_item item
                  WHERE item.override_id = NEW.publish_override_id
                    AND item.kind = 'VALIDATION_FAILURE'
                    AND item.validation_evidence_id = evidence.id)))
            THEN RAISE(ABORT, 'PublishAuthorization lacks exact current validation evidence')
        WHEN NOT EXISTS (
            SELECT 1 FROM brain_review_episode brain
            WHERE brain.id = NEW.brain_review_episode_id
              AND brain.task_id = NEW.task_id
              AND brain.task_epoch = NEW.task_epoch
              AND brain.local_development_stage_id = NEW.local_development_stage_id
              AND brain.stage_generation = NEW.stage_generation
              AND brain.dev_report_id = NEW.dev_report_id
              AND brain.code_fingerprint = NEW.code_fingerprint
              AND brain.expected_head_sha = NEW.head_sha
              AND brain.expected_base_sha = NEW.base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM brain_review_episode newer
                  WHERE newer.dev_report_id = brain.dev_report_id
                    AND newer.semantic_attempt > brain.semantic_attempt)
              AND ((NEW.brain_basis = 'APPROVED'
                    AND brain.status = 'SUCCEEDED'
                    AND brain.verdict = 'APPROVED'
                    AND brain.unresolved_finding_count = 0)
                OR (NEW.brain_basis = 'HUMAN_ESCALATION'
                    AND NEW.consent_kind = 'HUMAN'
                    AND brain.status = 'BUDGET_EXHAUSTED')))
            THEN RAISE(ABORT, 'PublishAuthorization lacks exact Brain evidence')
        WHEN NEW.publish_override_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM publish_override override
            WHERE override.id = NEW.publish_override_id
              AND override.local_development_stage_id = NEW.local_development_stage_id
              AND override.task_id = NEW.task_id
              AND override.task_epoch = NEW.task_epoch
              AND override.stage_generation = NEW.stage_generation
              AND override.dev_report_id = NEW.dev_report_id
              AND override.code_fingerprint = NEW.code_fingerprint
              AND override.head_sha = NEW.head_sha
              AND override.base_sha = NEW.base_sha
              AND EXISTS (
                  SELECT 1 FROM publish_override_item item
                  WHERE item.override_id = override.id))
            THEN RAISE(ABORT, 'PublishAuthorization override is empty or stale')
        WHEN EXISTS (
            SELECT 1 FROM local_review_comment_revision revision
            WHERE revision.task_id = NEW.task_id
              AND revision.local_development_stage_id = NEW.local_development_stage_id
              AND revision.task_epoch = NEW.task_epoch
              AND revision.stage_generation = NEW.stage_generation
              AND revision.dev_report_id = NEW.dev_report_id
              AND revision.code_fingerprint = NEW.code_fingerprint
              AND revision.head_sha = NEW.head_sha
              AND revision.base_sha = NEW.base_sha
              AND revision.state IN ('DRAFT', 'PENDING', 'SUBMITTED')
              AND NOT EXISTS (
                  SELECT 1 FROM publish_override_item item
                  WHERE item.override_id = NEW.publish_override_id
                    AND item.kind = 'LOCAL_FEEDBACK'
                    AND item.comment_revision_id = revision.id))
            THEN RAISE(ABORT, 'PublishAuthorization has unacknowledged local feedback')
        WHEN NEW.consent_kind = 'STANDING_TASK' AND NOT EXISTS (
            SELECT 1 FROM task_policy_revision policy
            WHERE policy.id = NEW.policy_revision_id
              AND policy.auto_approve = 1
              AND NEW.consent_id = policy.id
              AND NEW.publish_override_id IS NULL
              AND NEW.brain_basis = 'APPROVED')
            THEN RAISE(ABORT, 'standing publish consent is not enabled by exact Task policy')
    END;
END;
CREATE TRIGGER publish_authorization_state_transition
BEFORE UPDATE OF revoked_at_ms, consumed_at_ms, outcome ON publish_authorization
WHEN NOT (
    (OLD.revoked_at_ms IS NULL AND OLD.consumed_at_ms IS NULL
      AND ((NEW.revoked_at_ms IS NOT NULL AND NEW.consumed_at_ms IS NULL
              AND NEW.outcome IS NULL)
        OR (NEW.revoked_at_ms IS NULL AND NEW.consumed_at_ms IS NOT NULL
              AND NEW.outcome IS NOT NULL)))
    OR (OLD.revoked_at_ms IS NULL AND OLD.consumed_at_ms IS NOT NULL
      AND OLD.outcome = 'CANCELED'
      AND NEW.revoked_at_ms IS NULL AND NEW.consumed_at_ms IS NULL
      AND NEW.outcome IS NULL
      AND EXISTS (
          SELECT 1
          FROM publish_operation operation
          JOIN stage_resume_async_successor_v272 resume
            ON resume.owner_id = operation.id
           AND resume.operation_id = operation.operation_id
          JOIN stage_resume_rearm_intent_v257 intent
            ON intent.handoff_id = resume.handoff_id
          WHERE operation.publish_authorization_id = OLD.id
            AND operation.status = 'CANCELED'
            AND resume.status = 'PREPARED'
            AND resume.owner_kind = 'PUBLISH_RECOVERY'
            AND intent.status = 'PENDING'
            AND intent.task_id = operation.task_id
            AND intent.stage_id = operation.local_development_stage_id)))
BEGIN SELECT RAISE(ABORT, 'illegal PublishAuthorization state transition'); END;
CREATE TRIGGER publish_delivery_receipt_immutable
BEFORE UPDATE ON publish_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Publish delivery receipt is immutable'); END;
CREATE TRIGGER publish_delivery_receipt_insert
BEFORE INSERT ON publish_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM publish_operation operation
    JOIN dispatch_ticket ticket ON ticket.operation_id = operation.operation_id
    WHERE operation.operation_id = NEW.operation_id
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = NEW.outcome
      AND ticket.pending_result_operation_id = operation.operation_id
      AND ticket.pending_result_task_epoch = operation.task_epoch
      AND ticket.pending_result_stage_id = operation.local_development_stage_id
      AND ticket.pending_result_stage_generation = operation.stage_generation
      AND ticket.pending_result_attempt = operation.semantic_attempt
      AND ticket.pending_result_expected_code_fingerprint = operation.code_fingerprint
      AND ticket.pending_result_expected_head_sha = operation.expected_head_sha
      AND ticket.pending_result_expected_base_sha = operation.expected_base_sha
      AND ((NEW.outcome = 'SUCCEEDED'
              AND operation.status = 'SUCCEEDED'
              AND EXISTS (
                  SELECT 1 FROM remote_pr_binding binding
                  WHERE binding.publish_operation_id = operation.id)
              AND ((NEW.acceptance = 'SUPERSEDED'
                      AND NEW.remote_stage_id IS NULL)
                  OR (NEW.acceptance = 'ACCEPTED'
                      AND EXISTS (
                          SELECT 1
                          FROM remote_development_stage remote
                          JOIN task_current_stage current
                            ON current.task_id = remote.task_id
                          WHERE remote.stage_id = NEW.remote_stage_id
                            AND remote.task_id = operation.task_id
                            AND current.stage_id = remote.stage_id
                            AND current.stage_generation = remote.generation))))
          OR (NEW.outcome = 'FAILED'
              AND operation.status = 'FAILED'
              AND NEW.remote_stage_id IS NULL)
          OR (NEW.outcome = 'CANCELED'
              AND operation.status = 'CANCELED'
              AND NEW.remote_stage_id IS NULL)))
BEGIN SELECT RAISE(ABORT,
    'Publish delivery receipt lacks exact operation, raw result, or owner proof'); END;
CREATE TRIGGER publish_effect_step_claim
BEFORE UPDATE OF status ON publish_effect_step
WHEN NEW.status = 'CLAIMED'
  AND (OLD.status NOT IN ('REQUESTED', 'CLAIMED', 'FAILED', 'INDETERMINATE')
    OR NEW.attempt_count <> OLD.attempt_count + 1
    OR (NEW.attempt_count > NEW.attempt_limit
        AND NEW.claim_mode <> 'PROBE')
    OR NEW.claim_owner IS NULL OR length(NEW.claim_owner) = 0
    OR NEW.claimed_at_ms IS NULL OR NEW.lease_until_ms <= NEW.claimed_at_ms
    OR NEW.evidence IS NOT NULL OR NEW.last_error IS NOT NULL
    OR NEW.completed_at_ms IS NOT NULL
    OR (OLD.status = 'CLAIMED'
        AND (NEW.claim_mode <> 'PROBE'
          OR OLD.lease_until_ms IS NULL
          OR NEW.claimed_at_ms < OLD.lease_until_ms))
    OR (OLD.status = 'INDETERMINATE' AND NEW.claim_mode <> 'PROBE')
    OR (OLD.status IN ('REQUESTED', 'FAILED')
        AND NEW.claim_mode <> 'EXECUTE')
    OR EXISTS (
        SELECT 1 FROM publish_effect_step prior
        WHERE prior.publish_operation_id = NEW.publish_operation_id
          AND prior.ordinal < NEW.ordinal
          AND prior.status <> 'SUCCEEDED')
    OR NOT EXISTS (
        SELECT 1 FROM publish_operation operation
        WHERE operation.id = NEW.publish_operation_id
          AND operation.status = 'DISPATCHED'))
BEGIN SELECT RAISE(ABORT, 'Publish effect step claim is not ordered or recoverable'); END;
CREATE TRIGGER publish_effect_step_fields_guard
BEFORE UPDATE OF attempt_count, claim_mode, claim_owner, claimed_at_ms,
        lease_until_ms, evidence, last_error, completed_at_ms
ON publish_effect_step
WHEN NEW.status IS OLD.status
  AND NOT (OLD.status = 'CLAIMED'
    AND NEW.status = 'CLAIMED'
    AND NEW.attempt_count = OLD.attempt_count + 1
    AND NEW.claim_mode = 'PROBE'
    AND NEW.claimed_at_ms >= OLD.lease_until_ms
    AND NEW.lease_until_ms > NEW.claimed_at_ms
    AND NEW.claim_owner IS NOT NULL AND length(NEW.claim_owner) > 0
    AND NEW.evidence IS NULL AND NEW.last_error IS NULL
    AND NEW.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'Publish effect mutable fields require an attempt boundary'); END;
CREATE TRIGGER publish_effect_step_identity_immutable
BEFORE UPDATE OF publish_operation_id, ordinal, kind, idempotency_key,
        attempt_limit ON publish_effect_step
WHEN NEW.publish_operation_id IS NOT OLD.publish_operation_id
  OR NEW.ordinal IS NOT OLD.ordinal OR NEW.kind IS NOT OLD.kind
  OR NEW.idempotency_key IS NOT OLD.idempotency_key
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
BEGIN SELECT RAISE(ABORT, 'Publish effect step identity is immutable'); END;
CREATE TRIGGER publish_effect_step_insert
BEFORE INSERT ON publish_effect_step
WHEN NEW.status <> 'REQUESTED'
  OR NEW.attempt_count <> 0
  OR NOT EXISTS (
      SELECT 1 FROM publish_operation operation
      WHERE operation.id = NEW.publish_operation_id
        AND operation.status = 'REQUESTED')
  OR NOT ((NEW.ordinal = 1 AND NEW.kind = 'VERIFY_SUBJECT')
      OR (NEW.ordinal = 2 AND NEW.kind = 'RECONCILE_BRANCH_BASE')
      OR (NEW.ordinal = 3 AND NEW.kind = 'PUSH_BRANCH')
      OR (NEW.ordinal = 4 AND NEW.kind = 'CREATE_OR_ADOPT_DRAFT_PR')
      OR (NEW.ordinal = 5 AND NEW.kind = 'FETCH_REMOTE_DETAIL')
      OR (NEW.ordinal = 6 AND NEW.kind = 'PROVE_REMOTE_HEAD'))
BEGIN SELECT RAISE(ABORT, 'Publish effect step identity/order is invalid'); END;
CREATE TRIGGER publish_effect_step_result
BEFORE UPDATE OF status ON publish_effect_step
WHEN NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE')
  AND (OLD.status <> 'CLAIMED'
    OR NEW.attempt_count <> OLD.attempt_count
    OR NEW.claim_mode IS NOT NULL OR NEW.claim_owner IS NOT NULL
    OR NEW.claimed_at_ms IS NOT NULL OR NEW.lease_until_ms IS NOT NULL)
BEGIN SELECT RAISE(ABORT, 'Publish effect result requires its exact committed claim'); END;
CREATE TRIGGER publish_effect_step_succeeded_immutable
BEFORE UPDATE ON publish_effect_step
WHEN OLD.status = 'SUCCEEDED'
BEGIN SELECT RAISE(ABORT, 'successful Publish effect step is immutable'); END;
CREATE TRIGGER publish_effect_step_transition
BEFORE UPDATE OF status ON publish_effect_step
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status = 'CLAIMED')
    OR (OLD.status = 'CLAIMED'
        AND NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE')))
BEGIN SELECT RAISE(ABORT, 'illegal Publish effect step transition'); END;
CREATE TRIGGER publish_operation_dispatch
BEFORE UPDATE OF status ON publish_operation
WHEN NEW.status = 'DISPATCHED'
  AND (NOT EXISTS (
      SELECT 1 FROM dispatch_ticket ticket
      WHERE ticket.operation_id = NEW.operation_id
        AND ticket.operation_kind = 'PUBLISH_LOCAL_DEVELOPMENT'
        AND ticket.async_family = 'GITHUB_EFFECT'
        AND ticket.owner_kind = 'STAGE'
        AND ticket.owner_id = NEW.local_development_stage_id
        AND ticket.callback_route = 'STAGE_PUBLISH_RESULT'
        AND ticket.task_id = NEW.task_id
        AND ticket.task_epoch = NEW.task_epoch
        AND ticket.stage_id = NEW.local_development_stage_id
        AND ticket.stage_generation = NEW.stage_generation
        AND ticket.attempt = NEW.semantic_attempt
        AND ticket.expected_code_fingerprint = NEW.code_fingerprint
        AND ticket.expected_head_sha = NEW.expected_head_sha
        AND ticket.expected_base_sha = NEW.expected_base_sha
        AND ticket.trunk_control = 0
        AND ticket.exclusive_task = 1
        AND ticket.writer_required = 1
        AND ticket.lane_mask = 48
        AND ticket.status = 'REQUESTED')
    OR (SELECT COUNT(*) FROM publish_effect_step step
        WHERE step.publish_operation_id = NEW.id) <> 6)
BEGIN SELECT RAISE(ABORT,
    'dispatched PublishOperation requires exact route, lanes, and six steps'); END;
CREATE TRIGGER publish_operation_identity_immutable
BEFORE UPDATE OF publish_authorization_id, local_development_stage_id,
        task_id, task_epoch, stage_generation, operation_id, semantic_attempt,
        code_fingerprint, expected_head_sha, expected_base_sha, requested_at_ms
ON publish_operation
WHEN NEW.publish_authorization_id IS NOT OLD.publish_authorization_id
  OR NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'PublishOperation fence is immutable'); END;
CREATE TRIGGER publish_operation_insert
BEFORE INSERT ON publish_operation
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'PublishOperation must start REQUESTED')
        WHEN NOT EXISTS (
            SELECT 1
            FROM publish_authorization authorization
            JOIN promotion_manifest manifest ON manifest.id = authorization.manifest_id
            JOIN local_development_stage l
              ON l.stage_id = authorization.local_development_stage_id
            JOIN stage s ON s.id = l.stage_id
            JOIN tasks t ON t.id = l.task_id
            JOIN task_current_stage current ON current.stage_id = l.stage_id
            JOIN dev_report report ON report.id = authorization.dev_report_id
            JOIN validation_evidence validation
              ON validation.id = authorization.validation_evidence_id
            JOIN validation_operation validation_operation
              ON validation_operation.id = validation.validation_operation_id
            JOIN brain_review_episode brain
              ON brain.id = authorization.brain_review_episode_id
            WHERE authorization.id = NEW.publish_authorization_id
              AND authorization.revoked_at_ms IS NULL
              AND authorization.consumed_at_ms IS NULL
              AND authorization.local_development_stage_id = NEW.local_development_stage_id
              AND authorization.task_id = NEW.task_id
              AND authorization.task_epoch = NEW.task_epoch
              AND authorization.stage_generation = NEW.stage_generation
              AND authorization.code_fingerprint = NEW.code_fingerprint
              AND authorization.head_sha = NEW.expected_head_sha
              AND authorization.base_sha = NEW.expected_base_sha
              AND authorization.authorized_operation_id = NEW.operation_id
              AND authorization.authorized_attempt = NEW.semantic_attempt
              AND manifest.local_development_stage_id = NEW.local_development_stage_id
              AND manifest.task_id = NEW.task_id
              AND manifest.task_epoch = NEW.task_epoch
              AND manifest.stage_generation = NEW.stage_generation
              AND manifest.code_fingerprint = NEW.code_fingerprint
              AND manifest.head_sha = NEW.expected_head_sha
              AND manifest.base_sha = NEW.expected_base_sha
              AND l.opened_for_epoch = NEW.task_epoch
              AND l.generation = NEW.stage_generation
              AND s.completed_at_ms IS NULL
              AND t.lifecycle_state = 'ACTIVE' AND t.epoch = NEW.task_epoch
              AND current.task_id = NEW.task_id
              AND current.stage_generation = NEW.stage_generation
              AND report.workflow_version = 'V2'
              AND report.local_development_stage_id = l.stage_id
              AND report.code_fingerprint = NEW.code_fingerprint
              AND report.head_sha = NEW.expected_head_sha
              AND report.base_sha = NEW.expected_base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision)
              AND validation_operation.dev_report_id = report.id
              AND validation_operation.status = 'COMPLETED'
              AND NOT EXISTS (
                  SELECT 1 FROM validation_operation newer
                  WHERE newer.dev_report_id = report.id
                    AND newer.semantic_attempt > validation_operation.semantic_attempt)
              AND brain.dev_report_id = report.id
              AND NOT EXISTS (
                  SELECT 1 FROM brain_review_episode newer
                  WHERE newer.dev_report_id = report.id
                    AND newer.semantic_attempt > brain.semantic_attempt))
            THEN RAISE(ABORT, 'PublishOperation authorization is stale or not exact')
    END;
END;
CREATE TRIGGER publish_operation_success
BEFORE UPDATE OF status ON publish_operation
WHEN NEW.status = 'SUCCEEDED'
  AND (NEW.remote_head_sha <> NEW.expected_head_sha
    OR NEW.remote_base_sha <> NEW.expected_base_sha
    OR EXISTS (
        SELECT 1 FROM publish_effect_step step
        WHERE step.publish_operation_id = NEW.id
          AND step.status <> 'SUCCEEDED')
    OR (SELECT COUNT(*) FROM publish_effect_step step
        WHERE step.publish_operation_id = NEW.id) <> 6
    OR NOT EXISTS (
        SELECT 1 FROM dispatch_ticket ticket
        WHERE ticket.operation_id = NEW.operation_id
          AND ticket.status = 'RESULT_PENDING'
          AND ticket.pending_result_outcome = 'SUCCEEDED'
          AND ticket.pending_result_task_epoch = NEW.task_epoch
          AND ticket.pending_result_stage_id = NEW.local_development_stage_id
          AND ticket.pending_result_stage_generation = NEW.stage_generation
          AND ticket.pending_result_operation_id = NEW.operation_id
          AND ticket.pending_result_attempt = NEW.semantic_attempt
          AND ticket.pending_result_expected_code_fingerprint = NEW.code_fingerprint
          AND ticket.pending_result_expected_head_sha = NEW.expected_head_sha
          AND ticket.pending_result_expected_base_sha = NEW.expected_base_sha
          AND ticket.pending_result_evidence IS NOT NULL))
BEGIN SELECT RAISE(ABORT, 'successful PublishOperation lacks exact effect/raw-result proof'); END;
CREATE TRIGGER publish_operation_terminal_immutable
BEFORE UPDATE ON publish_operation
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED',
    'SUPERSEDED', 'INDETERMINATE')
 AND NOT (OLD.status = 'CANCELED' AND NEW.status = 'DISPATCHED'
    AND EXISTS (
        SELECT 1 FROM stage_resume_async_successor_v272 resume
        JOIN stage_resume_rearm_intent_v257 intent
          ON intent.handoff_id = resume.handoff_id
        WHERE resume.status = 'PREPARED'
          AND resume.owner_kind = 'PUBLISH_RECOVERY'
          AND resume.owner_id = OLD.id
          AND resume.operation_id = OLD.operation_id
          AND intent.status = 'PENDING'))
BEGIN SELECT RAISE(ABORT, 'terminal PublishOperation is immutable'); END;
CREATE TRIGGER publish_operation_transition
BEFORE UPDATE OF status ON publish_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED', 'INDETERMINATE'))
    OR (OLD.status = 'CANCELED' AND NEW.status = 'DISPATCHED'
        AND NEW.completed_at_ms IS NULL AND NEW.error_message IS NULL
        AND EXISTS (
            SELECT 1
            FROM stage_resume_async_successor_v272 resume
            JOIN stage_resume_rearm_intent_v257 intent
              ON intent.handoff_id = resume.handoff_id
            JOIN dispatch_ticket ticket ON ticket.id = resume.dispatch_ticket_id
            JOIN publish_authorization authorization
              ON authorization.id = NEW.publish_authorization_id
            WHERE resume.status = 'PREPARED'
              AND resume.owner_kind = 'PUBLISH_RECOVERY'
              AND resume.owner_id = NEW.id
              AND resume.operation_id = NEW.operation_id
              AND intent.status = 'PENDING'
              AND ticket.operation_id = NEW.operation_id
              AND ticket.status = 'REQUESTED'
              AND authorization.revoked_at_ms IS NULL
              AND authorization.consumed_at_ms IS NULL)))
BEGIN SELECT RAISE(ABORT, 'illegal PublishOperation transition'); END;
CREATE TRIGGER publish_override_immutable
BEFORE UPDATE ON publish_override
BEGIN SELECT RAISE(ABORT, 'PublishOverride is immutable'); END;
CREATE TRIGGER publish_override_insert
BEFORE INSERT ON publish_override
WHEN NOT EXISTS (
    SELECT 1
    FROM local_development_stage l
    JOIN stage s ON s.id = l.stage_id
    JOIN tasks t ON t.id = l.task_id
    JOIN task_current_stage c ON c.stage_id = l.stage_id
    JOIN dev_report report ON report.id = NEW.dev_report_id
    WHERE l.stage_id = NEW.local_development_stage_id
      AND l.task_id = NEW.task_id
      AND l.opened_for_epoch = NEW.task_epoch
      AND l.generation = NEW.stage_generation
      AND s.completed_at_ms IS NULL
      AND t.epoch = NEW.task_epoch AND t.lifecycle_state = 'ACTIVE'
      AND c.task_id = NEW.task_id AND c.stage_generation = NEW.stage_generation
      AND report.workflow_version = 'V2'
      AND report.local_development_stage_id = l.stage_id
      AND report.task_id = NEW.task_id AND report.task_epoch = NEW.task_epoch
      AND report.stage_generation = NEW.stage_generation
      AND report.code_fingerprint = NEW.code_fingerprint
      AND report.head_sha = NEW.head_sha AND report.base_sha = NEW.base_sha
      AND NOT EXISTS (
          SELECT 1 FROM dev_report newer
          WHERE newer.workflow_version = 'V2'
            AND newer.local_development_stage_id = report.local_development_stage_id
            AND newer.revision > report.revision))
BEGIN SELECT RAISE(ABORT, 'PublishOverride requires the exact current local subject'); END;
CREATE TRIGGER publish_override_item_delete_guard
BEFORE DELETE ON publish_override_item
WHEN EXISTS (
    SELECT 1 FROM publish_authorization authorization
    WHERE authorization.publish_override_id = OLD.override_id)
  AND NOT EXISTS (
    SELECT 1
    FROM publish_override override
    JOIN tasks task ON task.id = override.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE override.id = OLD.override_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'used PublishOverride items cannot be deleted'); END;
CREATE TRIGGER publish_override_item_immutable
BEFORE UPDATE ON publish_override_item
BEGIN SELECT RAISE(ABORT, 'PublishOverride item is immutable'); END;
CREATE TRIGGER publish_override_item_insert
BEFORE INSERT ON publish_override_item
BEGIN
    SELECT CASE
        WHEN EXISTS (
            SELECT 1 FROM publish_authorization authorization
            WHERE authorization.publish_override_id = NEW.override_id)
            THEN RAISE(ABORT, 'used PublishOverride items are frozen')
        WHEN NEW.kind = 'VALIDATION_FAILURE' AND NOT EXISTS (
            SELECT 1
            FROM publish_override override
            JOIN validation_evidence evidence
              ON evidence.id = NEW.validation_evidence_id
            JOIN task_blocker blocker ON blocker.id = NEW.task_blocker_id
            WHERE override.id = NEW.override_id
              AND evidence.task_id = override.task_id
              AND evidence.task_epoch = override.task_epoch
              AND evidence.stage_id = override.local_development_stage_id
              AND evidence.stage_generation = override.stage_generation
              AND evidence.code_fingerprint = override.code_fingerprint
              AND evidence.head_sha = override.head_sha
              AND evidence.base_sha = override.base_sha
              AND evidence.passed = 0
              AND blocker.task_id = override.task_id
              AND blocker.stage_id = override.local_development_stage_id
              AND blocker.owner_kind = 'STAGE'
              AND blocker.owner_id = override.local_development_stage_id
              AND blocker.blocker_type = 'LOCAL_VALIDATION_FAILED'
              AND blocker.subject_revision = evidence.id
              AND blocker.status = 'OPEN')
            THEN RAISE(ABORT, 'validation override item does not name its exact open blocker')
        WHEN NEW.kind = 'LOCAL_FEEDBACK' AND NOT EXISTS (
            SELECT 1
            FROM publish_override override
            JOIN local_review_comment_revision revision
              ON revision.id = NEW.comment_revision_id
            JOIN task_blocker blocker ON blocker.id = NEW.task_blocker_id
            WHERE override.id = NEW.override_id
              AND revision.task_id = override.task_id
              AND revision.local_development_stage_id = override.local_development_stage_id
              AND revision.task_epoch = override.task_epoch
              AND revision.stage_generation = override.stage_generation
              AND revision.dev_report_id = override.dev_report_id
              AND revision.code_fingerprint = override.code_fingerprint
              AND revision.head_sha = override.head_sha
              AND revision.base_sha = override.base_sha
              AND revision.state IN ('DRAFT', 'PENDING', 'SUBMITTED')
              AND blocker.task_id = override.task_id
              AND blocker.stage_id = override.local_development_stage_id
              AND blocker.owner_kind = 'STAGE'
              AND blocker.owner_id = override.local_development_stage_id
              AND blocker.blocker_type = 'LOCAL_FEEDBACK_OPEN'
              AND blocker.subject_revision = revision.id
              AND blocker.status = 'OPEN')
            THEN RAISE(ABORT, 'feedback override item does not name its exact open blocker')
    END;
END;
CREATE TRIGGER remote_ci_check_snapshot_immutable
BEFORE UPDATE ON remote_ci_check_snapshot
BEGIN SELECT RAISE(ABORT, 'CI check snapshot is immutable'); END;
CREATE TRIGGER remote_ci_check_snapshot_insert
BEFORE INSERT ON remote_ci_check_snapshot
WHEN NOT EXISTS (
    SELECT 1 FROM remote_pr_snapshot snapshot
    WHERE snapshot.id = NEW.remote_pr_snapshot_id
      AND NEW.observed_at_ms >= snapshot.observed_at_ms)
BEGIN SELECT RAISE(ABORT, 'CI check does not belong to its remote snapshot'); END;
CREATE TRIGGER remote_ci_evaluation_immutable
BEFORE UPDATE ON remote_ci_evaluation
BEGIN SELECT RAISE(ABORT, 'CI evaluation is immutable'); END;
CREATE TRIGGER remote_ci_evaluation_insert
BEFORE INSERT ON remote_ci_evaluation
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM remote_pr_snapshot snapshot
            JOIN remote_development_stage remote
              ON remote.stage_id = snapshot.remote_development_stage_id
            JOIN tasks task ON task.id = remote.task_id
            WHERE snapshot.id = NEW.remote_pr_snapshot_id
              AND snapshot.remote_development_stage_id =
                    NEW.remote_development_stage_id
              AND snapshot.task_id = NEW.task_id
              AND snapshot.stage_generation = NEW.stage_generation
              AND snapshot.head_sha = NEW.head_sha
              AND snapshot.base_sha = NEW.base_sha
              AND task.epoch = NEW.task_epoch)
            THEN RAISE(ABORT, 'CI evaluation subject fence is invalid')
        WHEN NOT EXISTS (
            SELECT 1 FROM remote_ci_policy_revision policy
            WHERE policy.id = NEW.ci_policy_revision_id
              AND policy.task_id = NEW.task_id
              AND policy.remote_pr_binding_id = (
                  SELECT snapshot.remote_pr_binding_id
                  FROM remote_pr_snapshot snapshot
                  WHERE snapshot.id = NEW.remote_pr_snapshot_id)
              AND NEW.policy_outcome = CASE NEW.normalized_status
                  WHEN 'NONE' THEN policy.none_outcome
                  WHEN 'MISSING' THEN policy.missing_outcome
                  WHEN 'QUEUED' THEN policy.queued_outcome
                  WHEN 'PENDING' THEN policy.pending_outcome
                  WHEN 'NEUTRAL' THEN policy.neutral_outcome
                  WHEN 'SKIPPED' THEN policy.skipped_outcome
                  WHEN 'CANCELED' THEN policy.canceled_outcome
                  WHEN 'PASSED' THEN 'ACCEPTED'
                  WHEN 'FAILED' THEN 'FAILED'
              END)
            THEN RAISE(ABORT, 'CI evaluation does not match explicit policy')
        WHEN NEW.check_count <> (
            SELECT COUNT(*) FROM remote_ci_check_snapshot check_snapshot
            WHERE check_snapshot.remote_pr_snapshot_id =
                NEW.remote_pr_snapshot_id)
            THEN RAISE(ABORT, 'CI evaluation check count is not exact')
        WHEN NEW.missing_required_count <> (
            SELECT COUNT(*) FROM remote_ci_check_snapshot check_snapshot
            WHERE check_snapshot.remote_pr_snapshot_id =
                    NEW.remote_pr_snapshot_id
              AND check_snapshot.normalized_state = 'MISSING')
            THEN RAISE(ABORT, 'CI evaluation missing-check count is not exact')
        WHEN NEW.normalized_status = 'PASSED' AND EXISTS (
            SELECT 1 FROM remote_ci_check_snapshot check_snapshot
            WHERE check_snapshot.remote_pr_snapshot_id =
                    NEW.remote_pr_snapshot_id
              AND check_snapshot.normalized_state <> 'PASSED')
            THEN RAISE(ABORT, 'Green CI evaluation contains a non-passing check')
        WHEN NEW.normalized_status NOT IN ('NONE', 'PASSED')
          AND NOT EXISTS (
            SELECT 1 FROM remote_ci_check_snapshot check_snapshot
            WHERE check_snapshot.remote_pr_snapshot_id =
                    NEW.remote_pr_snapshot_id
              AND check_snapshot.normalized_state = NEW.normalized_status)
            THEN RAISE(ABORT, 'CI aggregate status lacks constituent check evidence')
    END;
END;
CREATE TRIGGER remote_ci_policy_revision_immutable
BEFORE UPDATE ON remote_ci_policy_revision
BEGIN SELECT RAISE(ABORT, 'CI policy revision is immutable'); END;
CREATE TRIGGER remote_ci_policy_revision_insert
BEFORE INSERT ON remote_ci_policy_revision
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM remote_pr_binding binding
            JOIN tasks task ON task.id = binding.task_id
            WHERE binding.id = NEW.remote_pr_binding_id
              AND binding.task_id = NEW.task_id
              AND task.workflow_version = 'V2')
            THEN RAISE(ABORT, 'CI policy requires exact V2 remote binding')
        WHEN NEW.revision <> COALESCE((
            SELECT MAX(policy.revision) + 1
            FROM remote_ci_policy_revision policy
            WHERE policy.task_id = NEW.task_id), 1)
            THEN RAISE(ABORT, 'CI policy revision must be next')
    END;
END;
CREATE TRIGGER remote_ci_required_check_immutable
BEFORE UPDATE ON remote_ci_required_check
BEGIN SELECT RAISE(ABORT, 'Remote CI required check is immutable'); END;
CREATE TRIGGER remote_code_subject_immutable
BEFORE UPDATE ON remote_code_subject
BEGIN SELECT RAISE(ABORT, 'Remote code subject is immutable'); END;
CREATE TRIGGER remote_code_subject_insert
BEFORE INSERT ON remote_code_subject
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_development_stage remote
    JOIN stage_turn turn ON turn.id = NEW.stage_turn_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND turn.stage_id = remote.stage_id
      AND turn.stage_generation = remote.generation
      AND turn.task_epoch = NEW.task_epoch
      AND turn.expected_code_fingerprint = NEW.source_code_fingerprint
      AND turn.expected_head_sha = NEW.source_head_sha
      AND turn.expected_base_sha = NEW.source_base_sha
      AND turn.status = 'SUCCEEDED')
BEGIN SELECT RAISE(ABORT, 'Remote code subject lacks its exact successful StageTurn'); END;
CREATE TRIGGER remote_development_stage_accept_snapshot
BEFORE UPDATE OF accepted_snapshot_id, accepted_observation_revision,
        current_head_sha, current_base_sha, subject_changed_at_ms
        ON remote_development_stage
WHEN NEW.accepted_snapshot_id IS NOT OLD.accepted_snapshot_id
  OR NEW.accepted_observation_revision IS NOT OLD.accepted_observation_revision
  OR NEW.current_head_sha IS NOT OLD.current_head_sha
  OR NEW.current_base_sha IS NOT OLD.current_base_sha
  OR NEW.subject_changed_at_ms IS NOT OLD.subject_changed_at_ms
BEGIN
    SELECT CASE
        WHEN NEW.accepted_observation_revision <= OLD.accepted_observation_revision
            THEN RAISE(ABORT, 'Accepted remote observation must advance')
        WHEN NEW.subject_changed_at_ms < OLD.subject_changed_at_ms
            THEN RAISE(ABORT, 'Remote subject time cannot move backward')
        WHEN NOT EXISTS (
            SELECT 1 FROM remote_pr_snapshot snapshot
            WHERE snapshot.id = NEW.accepted_snapshot_id
              AND snapshot.remote_development_stage_id = NEW.stage_id
              AND snapshot.task_id = NEW.task_id
              AND snapshot.stage_generation = NEW.generation
              AND snapshot.remote_pr_binding_id = NEW.remote_pr_binding_id
              AND snapshot.observation_revision =
                    NEW.accepted_observation_revision
              AND snapshot.head_sha = NEW.current_head_sha
              AND snapshot.base_sha = NEW.current_base_sha
              AND snapshot.observed_at_ms = NEW.subject_changed_at_ms)
            THEN RAISE(ABORT, 'Accepted remote subject lacks exact snapshot proof')
    END;
END;
CREATE TRIGGER remote_development_stage_identity_immutable
BEFORE UPDATE OF stage_id, task_id, generation, remote_pr_binding_id
        ON remote_development_stage
WHEN NEW.stage_id IS NOT OLD.stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.generation IS NOT OLD.generation
  OR NEW.remote_pr_binding_id IS NOT OLD.remote_pr_binding_id
BEGIN SELECT RAISE(ABORT, 'Remote Development owner identity is immutable'); END;
CREATE TRIGGER remote_development_stage_insert
BEFORE INSERT ON remote_development_stage
WHEN NOT EXISTS (
    SELECT 1
    FROM stage owner
    JOIN tasks task ON task.id = owner.task_id
    JOIN remote_pr_binding binding ON binding.task_id = task.id
    WHERE owner.id = NEW.stage_id
      AND owner.task_id = NEW.task_id
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = NEW.generation
      AND owner.completed_at_ms IS NULL
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state IN ('ACTIVE', 'PAUSING', 'PAUSED', 'RESUMING')
      AND binding.id = NEW.remote_pr_binding_id
      AND binding.remote_head_sha = NEW.current_head_sha
      AND binding.remote_base_sha = NEW.current_base_sha)
BEGIN SELECT RAISE(ABORT, 'Remote Development owner does not match exact V2 PR binding'); END;
CREATE TRIGGER remote_feedback_authorization_immutable
BEFORE UPDATE ON remote_feedback_authorization
BEGIN SELECT RAISE(ABORT, 'Remote feedback authorization is immutable'); END;
CREATE TRIGGER remote_feedback_authorization_insert
BEFORE INSERT ON remote_feedback_authorization
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_batch batch
    JOIN remote_feedback_validation_evidence validation
      ON validation.remote_feedback_batch_id = batch.id
    JOIN remote_development_stage remote
      ON remote.stage_id = batch.remote_development_stage_id
    JOIN tasks task ON task.id = batch.task_id
    WHERE batch.id = NEW.remote_feedback_batch_id
      AND batch.remote_development_stage_id =
            NEW.remote_development_stage_id
      AND batch.task_id = NEW.task_id
      AND batch.task_epoch = NEW.task_epoch
      AND batch.stage_generation = NEW.stage_generation
      AND batch.head_sha = NEW.head_sha
      AND batch.base_sha = NEW.base_sha
      AND batch.item_count = NEW.item_count
      AND batch.content_digest = NEW.content_digest
      AND batch.status = 'AWAITING_APPROVAL'
      AND validation.id = NEW.validation_evidence_id
      AND validation.passed = 1
      AND validation.task_id = NEW.task_id
      AND validation.task_epoch = NEW.task_epoch
      AND validation.remote_development_stage_id = NEW.remote_development_stage_id
      AND validation.stage_generation = NEW.stage_generation
      AND validation.subject_head_sha = NEW.head_sha
      AND validation.base_sha = NEW.base_sha
      AND ((batch.brain_review_required = 0
            AND NEW.brain_review_evidence_id IS NULL)
        OR EXISTS (
            SELECT 1 FROM remote_feedback_brain_review_evidence brain
            WHERE brain.id = NEW.brain_review_evidence_id
              AND brain.remote_feedback_batch_id = batch.id
              AND brain.validation_evidence_id = validation.id
              AND brain.verdict = 'APPROVED'))
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch)
BEGIN SELECT RAISE(ABORT, 'Remote feedback authorization is stale or incomplete'); END;
CREATE TRIGGER remote_feedback_batch_authorized
BEFORE UPDATE OF status ON remote_feedback_batch
WHEN NEW.status = 'AUTHORIZED'
  AND (NOT EXISTS (
        SELECT 1 FROM remote_feedback_authorization authorization
        WHERE authorization.remote_feedback_batch_id = NEW.id
          AND authorization.item_count = NEW.item_count
          AND authorization.content_digest = NEW.content_digest
          AND authorization.effect_count = (
              SELECT COUNT(*) FROM remote_feedback_effect_step step
              WHERE step.remote_feedback_batch_id = NEW.id))
    OR EXISTS (
        SELECT 1 FROM remote_feedback_effect_step step
        WHERE step.remote_feedback_batch_id = NEW.id
          AND step.status <> 'REQUESTED')
    OR (SELECT COUNT(*) FROM remote_feedback_effect_step step
        WHERE step.remote_feedback_batch_id = NEW.id
          AND step.kind = 'PUSH_COMMITS') > 1
    OR EXISTS (
        SELECT 1 FROM remote_feedback_effect_step step
        WHERE step.remote_feedback_batch_id = NEW.id
          AND step.kind = 'PUSH_COMMITS'
          AND step.ordinal <> (
              SELECT authorization.effect_count
              FROM remote_feedback_authorization authorization
              WHERE authorization.remote_feedback_batch_id = NEW.id)))
BEGIN SELECT RAISE(ABORT, 'Authorized remote batch lacks its complete immutable effect set'); END;
CREATE TRIGGER remote_feedback_batch_complete
BEFORE UPDATE OF status ON remote_feedback_batch
WHEN NEW.status = 'COMPLETED'
  AND (OLD.status <> 'APPLYING'
    OR EXISTS (
        SELECT 1 FROM remote_feedback_effect_step step
        WHERE step.remote_feedback_batch_id = NEW.id
          AND step.status <> 'SUCCEEDED')
    OR (EXISTS (
            SELECT 1 FROM remote_feedback_effect_step step
            WHERE step.remote_feedback_batch_id = NEW.id
              AND step.kind = 'PUSH_COMMITS')
        AND (NEW.result_head_sha IS NULL
          OR NEW.result_head_sha = NEW.head_sha
          OR NOT EXISTS (
              SELECT 1 FROM remote_feedback_effect_step push
              JOIN remote_pr_snapshot snapshot
                ON snapshot.id = NEW.result_snapshot_id
              JOIN remote_development_stage remote
                ON remote.stage_id = snapshot.remote_development_stage_id
              WHERE push.remote_feedback_batch_id = NEW.id
                AND push.kind = 'PUSH_COMMITS'
                AND push.status = 'SUCCEEDED'
                AND push.external_effect_id = NEW.result_head_sha
                AND snapshot.remote_development_stage_id =
                    NEW.remote_development_stage_id
                AND snapshot.task_id = NEW.task_id
                AND snapshot.stage_generation = NEW.stage_generation
                AND snapshot.remote_pr_binding_id = NEW.remote_pr_binding_id
                AND snapshot.head_sha = NEW.result_head_sha
                AND snapshot.base_sha = NEW.base_sha
                AND remote.accepted_snapshot_id = snapshot.id
                AND remote.current_head_sha = NEW.result_head_sha
                AND remote.current_base_sha = NEW.base_sha)))
    OR (NOT EXISTS (
            SELECT 1 FROM remote_feedback_effect_step step
            WHERE step.remote_feedback_batch_id = NEW.id
              AND step.kind = 'PUSH_COMMITS')
        AND (NEW.result_head_sha IS NOT NULL OR NEW.result_snapshot_id IS NOT NULL)))
BEGIN SELECT RAISE(ABORT, 'Remote feedback batch cannot complete with partial effects'); END;
CREATE TRIGGER remote_feedback_batch_freeze
BEFORE UPDATE OF status ON remote_feedback_batch
WHEN NEW.status = 'FROZEN'
  AND (OLD.status <> 'BUILDING'
    OR NEW.content_digest IS NULL OR NEW.frozen_at_ms IS NULL
    OR NEW.item_count <> (
        SELECT COUNT(*) FROM remote_feedback_batch_item item
        WHERE item.remote_feedback_batch_id = NEW.id))
BEGIN SELECT RAISE(ABORT, 'Frozen remote feedback batch lacks its exact item set'); END;
CREATE TRIGGER remote_feedback_batch_freeze_identity
BEFORE UPDATE OF content_digest, frozen_at_ms ON remote_feedback_batch
WHEN OLD.status <> 'BUILDING' OR NEW.status <> 'FROZEN'
BEGIN SELECT RAISE(ABORT, 'Remote feedback batch freeze identity is immutable'); END;
CREATE TRIGGER remote_feedback_batch_identity_immutable
BEFORE UPDATE OF remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_binding_id, source_snapshot_id, sequence,
        head_sha, base_sha, brain_review_required, item_count, created_at_ms
        ON remote_feedback_batch
WHEN NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.remote_pr_binding_id IS NOT OLD.remote_pr_binding_id
  OR NEW.source_snapshot_id IS NOT OLD.source_snapshot_id
  OR NEW.sequence IS NOT OLD.sequence
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.brain_review_required IS NOT OLD.brain_review_required
  OR NEW.item_count IS NOT OLD.item_count
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'Remote feedback batch identity is immutable'); END;
CREATE TRIGGER remote_feedback_batch_insert
BEFORE INSERT ON remote_feedback_batch
BEGIN
    SELECT CASE
        WHEN NEW.sequence <> COALESCE((
            SELECT MAX(batch.sequence) + 1 FROM remote_feedback_batch batch
            WHERE batch.remote_development_stage_id =
                NEW.remote_development_stage_id), 1)
            THEN RAISE(ABORT, 'Remote feedback batch sequence must be next')
        WHEN NOT EXISTS (
            SELECT 1 FROM remote_development_stage remote
            JOIN tasks task ON task.id = remote.task_id
            JOIN remote_pr_snapshot snapshot
              ON snapshot.remote_development_stage_id = remote.stage_id
            WHERE remote.stage_id = NEW.remote_development_stage_id
              AND remote.task_id = NEW.task_id
              AND remote.generation = NEW.stage_generation
              AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
              AND remote.current_head_sha = NEW.head_sha
              AND remote.current_base_sha = NEW.base_sha
              AND remote.accepted_snapshot_id = snapshot.id
              AND task.epoch = NEW.task_epoch
              AND snapshot.id = NEW.source_snapshot_id
              AND snapshot.head_sha = NEW.head_sha
              AND snapshot.base_sha = NEW.base_sha)
            THEN RAISE(ABORT, 'Remote feedback batch is not for the current head')
    END;
END;
CREATE TRIGGER remote_feedback_batch_item_immutable
BEFORE UPDATE ON remote_feedback_batch_item
BEGIN SELECT RAISE(ABORT, 'Remote feedback batch item is immutable'); END;
CREATE TRIGGER remote_feedback_batch_item_insert
BEFORE INSERT ON remote_feedback_batch_item
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_batch batch
    JOIN remote_inbox_item item ON item.id = NEW.remote_inbox_item_id
    WHERE batch.id = NEW.remote_feedback_batch_id
      AND batch.status = 'BUILDING'
      AND item.remote_development_stage_id =
            batch.remote_development_stage_id
      AND item.task_id = batch.task_id
      AND item.task_epoch = batch.task_epoch
      AND item.stage_generation = batch.stage_generation
      AND item.remote_pr_binding_id = batch.remote_pr_binding_id
      AND item.head_sha = batch.head_sha
      AND item.base_sha = batch.base_sha
      AND item.external_revision = NEW.external_revision
      AND item.kind = NEW.kind
      AND item.kind NOT IN ('HEAD_CHANGED', 'THREAD_RESOLVED')
      AND item.ignored = 0
      AND item.body IS NEW.frozen_body
      AND item.body_digest IS NEW.body_digest)
BEGIN SELECT RAISE(ABORT, 'Remote feedback item is stale, ignored, or outside its batch'); END;
CREATE TRIGGER remote_feedback_batch_result_fence
BEFORE UPDATE OF result_head_sha, result_snapshot_id ON remote_feedback_batch
WHEN NEW.status <> 'COMPLETED'
BEGIN SELECT RAISE(ABORT, 'Remote feedback result may only be recorded at completion'); END;
CREATE TRIGGER remote_feedback_batch_terminal_immutable
BEFORE UPDATE ON remote_feedback_batch
WHEN OLD.status IN ('COMPLETED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'Terminal remote feedback batch is immutable'); END;
CREATE TRIGGER remote_feedback_batch_transition
BEFORE UPDATE OF status ON remote_feedback_batch
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status = 'BUILDING' AND NEW.status = 'FROZEN')
    OR (OLD.status = 'FROZEN'
        AND NEW.status IN ('ADDRESSING', 'AWAITING_APPROVAL', 'SUPERSEDED'))
    OR (OLD.status = 'ADDRESSING'
        AND NEW.status IN ('AWAITING_APPROVAL', 'SUPERSEDED'))
    OR (OLD.status = 'AWAITING_APPROVAL'
        AND NEW.status IN ('AUTHORIZED', 'SUPERSEDED'))
    OR (OLD.status = 'AUTHORIZED'
        AND NEW.status IN ('APPLYING', 'SUPERSEDED'))
    OR (OLD.status = 'APPLYING'
        AND NEW.status IN ('COMPLETED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'Remote feedback batch transition is invalid'); END;
CREATE TRIGGER remote_feedback_brain_episode_identity_immutable
BEFORE UPDATE OF remote_feedback_batch_id, validation_attempt_evidence_id, task_id,
        task_epoch, remote_development_stage_id, stage_generation,
        task_turn_id, semantic_attempt, code_fingerprint, expected_head_sha,
        expected_base_sha, requested_at_ms ON remote_feedback_brain_episode
BEGIN SELECT RAISE(ABORT, 'Remote feedback Brain episode identity is immutable'); END;
CREATE TRIGGER remote_feedback_brain_episode_insert
BEFORE INSERT ON remote_feedback_brain_episode
WHEN NEW.status <> 'REQUESTED' OR NOT EXISTS (
    SELECT 1 FROM remote_feedback_validation_attempt_evidence validation
    JOIN remote_feedback_batch batch
      ON batch.id = validation.remote_feedback_batch_id
    JOIN task_turn turn ON turn.id = NEW.task_turn_id
    WHERE validation.id = NEW.validation_attempt_evidence_id
      AND validation.passed = 1
      AND validation.remote_feedback_batch_id = NEW.remote_feedback_batch_id
      AND validation.task_id = NEW.task_id
      AND validation.task_epoch = NEW.task_epoch
      AND validation.remote_development_stage_id = NEW.remote_development_stage_id
      AND validation.stage_generation = NEW.stage_generation
      AND validation.semantic_attempt = NEW.semantic_attempt
      AND validation.code_fingerprint = NEW.code_fingerprint
      AND validation.proposed_head_sha = NEW.expected_head_sha
      AND validation.base_sha = NEW.expected_base_sha
      AND batch.status = 'ADDRESSING'
      AND turn.task_id = NEW.task_id
      AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id = NEW.remote_development_stage_id
      AND turn.trigger_stage_generation = NEW.stage_generation
      AND turn.purpose = 'REMOTE_FEEDBACK_BRAIN_REVIEW'
      AND turn.attempt = NEW.semantic_attempt
      AND turn.expected_code_fingerprint = NEW.code_fingerprint
      AND turn.expected_head_sha = NEW.expected_head_sha
      AND turn.expected_base_sha = NEW.expected_base_sha
      AND turn.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Remote feedback Brain episode lacks green exact-head validation'); END;
CREATE TRIGGER remote_feedback_brain_episode_terminal_immutable
BEFORE UPDATE ON remote_feedback_brain_episode
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'Terminal remote feedback Brain episode is immutable'); END;
CREATE TRIGGER remote_feedback_brain_episode_transition
BEFORE UPDATE OF status ON remote_feedback_brain_episode
WHEN OLD.status <> 'REQUESTED'
  OR NEW.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'Remote feedback Brain transition is invalid'); END;
CREATE TRIGGER remote_feedback_brain_review_evidence_immutable
BEFORE UPDATE ON remote_feedback_brain_review_evidence
BEGIN SELECT RAISE(ABORT, 'Remote feedback Brain review evidence is immutable'); END;
CREATE TRIGGER remote_feedback_brain_review_evidence_insert
BEFORE INSERT ON remote_feedback_brain_review_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_validation_evidence validation
    JOIN remote_feedback_batch batch
      ON batch.id = validation.remote_feedback_batch_id
    JOIN task_turn turn ON turn.id = NEW.task_turn_id
    WHERE validation.id = NEW.validation_evidence_id
      AND validation.remote_feedback_batch_id = NEW.remote_feedback_batch_id
      AND validation.passed = 1
      AND validation.task_id = NEW.task_id
      AND validation.task_epoch = NEW.task_epoch
      AND validation.remote_development_stage_id = NEW.remote_development_stage_id
      AND validation.stage_generation = NEW.stage_generation
      AND validation.proposed_head_sha = NEW.proposed_head_sha
      AND validation.base_sha = NEW.base_sha
      AND validation.code_fingerprint = NEW.code_fingerprint
      AND batch.status IN ('ADDRESSING', 'AWAITING_APPROVAL')
      AND turn.task_id = NEW.task_id
      AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id = NEW.remote_development_stage_id
      AND turn.trigger_stage_generation = NEW.stage_generation
      AND turn.purpose = 'REMOTE_FEEDBACK_BRAIN_REVIEW'
      AND turn.status = 'SUCCEEDED'
      AND turn.expected_code_fingerprint = NEW.code_fingerprint
      AND turn.expected_head_sha = NEW.proposed_head_sha
      AND turn.expected_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Remote feedback Brain evidence lacks exact green validation and TaskTurn'); END;
CREATE TRIGGER remote_feedback_effect_dispatch_immutable
BEFORE UPDATE ON remote_feedback_effect_dispatch
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect dispatch is immutable'); END;
CREATE TRIGGER remote_feedback_effect_dispatch_insert
BEFORE INSERT ON remote_feedback_effect_dispatch
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_effect_step step
    JOIN remote_feedback_authorization authorization
      ON authorization.id = step.remote_feedback_authorization_id
    JOIN remote_feedback_batch batch ON batch.id = step.remote_feedback_batch_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    JOIN remote_feedback_effect_payload payload
      ON payload.remote_feedback_effect_step_id = step.id
    WHERE step.id = NEW.remote_feedback_effect_step_id
      AND step.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
      AND batch.status IN ('AUTHORIZED', 'APPLYING')
      AND NOT EXISTS (
          SELECT 1 FROM remote_feedback_effect_step previous
          WHERE previous.remote_feedback_batch_id = step.remote_feedback_batch_id
            AND previous.ordinal < step.ordinal
            AND previous.status <> 'SUCCEEDED')
      AND ticket.operation_id = NEW.operation_id
      AND ticket.operation_kind = 'APPLY_REMOTE_FEEDBACK_EFFECT'
      AND ticket.async_family = CASE WHEN step.kind = 'PUSH_COMMITS'
          THEN 'LOCAL_GIT' ELSE 'GITHUB_EFFECT' END
      AND ticket.owner_kind = 'STAGE'
      AND ticket.owner_id = batch.remote_development_stage_id
      AND ticket.callback_route = 'REMOTE_FEEDBACK_EFFECT_RESULT'
      AND ticket.task_id = batch.task_id
      AND ticket.task_epoch = batch.task_epoch
      AND ticket.stage_id = batch.remote_development_stage_id
      AND ticket.stage_generation = batch.stage_generation
      AND ticket.attempt = step.attempt_count + 1
      AND ticket.expected_head_sha = authorization.head_sha
      AND ticket.expected_base_sha = authorization.base_sha
      AND ticket.lane_mask = CASE WHEN step.kind = 'PUSH_COMMITS' THEN 16 ELSE 32 END
      AND ticket.trunk_control = 0
      AND ticket.exclusive_task = 1
      AND ticket.writer_required = CASE WHEN step.kind = 'PUSH_COMMITS' THEN 1 ELSE 0 END
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect dispatch is unordered or stale'); END;
CREATE TRIGGER remote_feedback_effect_payload_immutable
BEFORE UPDATE ON remote_feedback_effect_payload
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect payload is immutable'); END;
CREATE TRIGGER remote_feedback_effect_payload_insert
BEFORE INSERT ON remote_feedback_effect_payload
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_effect_step step
    JOIN remote_feedback_batch batch ON batch.id = step.remote_feedback_batch_id
    WHERE step.id = NEW.remote_feedback_effect_step_id
      AND step.status = 'REQUESTED'
      AND step.payload_digest = NEW.payload_digest
      AND batch.status = 'AWAITING_APPROVAL'
      AND NEW.payload_kind = CASE
          WHEN step.kind IN ('POST_INLINE_REPLY', 'POST_TOP_LEVEL_REPLY') THEN 'TEXT'
          WHEN step.kind = 'SUBMIT_REVIEW' THEN 'REVIEW'
          WHEN step.kind = 'REQUEST_REVIEWER' THEN 'REVIEWER'
          WHEN step.kind = 'POST_MAINTAINER_NUDGE' THEN 'NUDGE'
          WHEN step.kind = 'RESOLVE_THREAD' THEN 'RESOLUTION'
          WHEN step.kind = 'PUSH_COMMITS' THEN 'PUSH'
      END)
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect payload is not authorized'); END;
CREATE TRIGGER remote_feedback_effect_step_attempt
BEFORE UPDATE OF attempt_count ON remote_feedback_effect_step
WHEN NEW.status <> 'CLAIMED'
  OR NEW.attempt_count <> OLD.attempt_count + 1
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect attempt must be an exact claim'); END;
CREATE TRIGGER remote_feedback_effect_step_claim
BEFORE UPDATE OF status ON remote_feedback_effect_step
WHEN NEW.status = 'CLAIMED'
  AND (NEW.attempt_count <> OLD.attempt_count + 1
    OR OLD.status NOT IN ('REQUESTED', 'CLAIMED', 'FAILED', 'INDETERMINATE')
    OR (OLD.status = 'CLAIMED'
        AND (NEW.claim_mode <> 'PROBE'
          OR NEW.claimed_at_ms < OLD.lease_until_ms))
    OR (OLD.status = 'INDETERMINATE' AND NEW.claim_mode <> 'PROBE')
    OR (OLD.status NOT IN ('CLAIMED', 'INDETERMINATE')
        AND NEW.claim_mode <> 'EXECUTE')
    OR NEW.external_effect_id IS NOT NULL OR NEW.evidence IS NOT NULL
    OR NEW.last_error IS NOT NULL OR NEW.completed_at_ms IS NOT NULL
    OR NOT EXISTS (
        SELECT 1 FROM remote_feedback_authorization authorization
        JOIN remote_feedback_batch batch
          ON batch.id = authorization.remote_feedback_batch_id
        JOIN remote_development_stage remote
          ON remote.stage_id = batch.remote_development_stage_id
        JOIN tasks task ON task.id = batch.task_id
        WHERE authorization.id = NEW.remote_feedback_authorization_id
          AND authorization.remote_feedback_batch_id = NEW.remote_feedback_batch_id
          AND batch.status IN ('AUTHORIZED', 'APPLYING')
          AND remote.current_head_sha = authorization.head_sha
          AND remote.current_base_sha = authorization.base_sha
          AND task.epoch = authorization.task_epoch)
    OR EXISTS (
        SELECT 1 FROM remote_feedback_effect_step previous
        WHERE previous.remote_feedback_batch_id = NEW.remote_feedback_batch_id
          AND previous.ordinal < NEW.ordinal
          AND previous.status <> 'SUCCEEDED'))
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect claim is unordered or unsafe'); END;
CREATE TRIGGER remote_feedback_effect_step_claim_fields
BEFORE UPDATE OF claim_mode, claim_owner, claimed_at_ms, lease_until_ms
        ON remote_feedback_effect_step
WHEN NOT ((NEW.status = 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count + 1)
        OR (OLD.status = 'CLAIMED' AND NEW.status <> 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count
            AND NEW.claim_mode IS NULL AND NEW.claim_owner IS NULL
            AND NEW.claimed_at_ms IS NULL AND NEW.lease_until_ms IS NULL))
BEGIN SELECT RAISE(ABORT, 'Remote feedback claim fields change only with an attempt boundary'); END;
CREATE TRIGGER remote_feedback_effect_step_identity_immutable
BEFORE UPDATE OF remote_feedback_authorization_id, remote_feedback_batch_id,
        ordinal, kind, remote_inbox_item_id, external_target, payload_digest,
        review_action, idempotency_key, attempt_limit ON remote_feedback_effect_step
WHEN NEW.remote_feedback_authorization_id IS NOT OLD.remote_feedback_authorization_id
  OR NEW.remote_feedback_batch_id IS NOT OLD.remote_feedback_batch_id
  OR NEW.ordinal IS NOT OLD.ordinal
  OR NEW.kind IS NOT OLD.kind
  OR NEW.remote_inbox_item_id IS NOT OLD.remote_inbox_item_id
  OR NEW.external_target IS NOT OLD.external_target
  OR NEW.review_action IS NOT OLD.review_action
  OR NEW.payload_digest IS NOT OLD.payload_digest
  OR NEW.idempotency_key IS NOT OLD.idempotency_key
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect identity is immutable'); END;
CREATE TRIGGER remote_feedback_effect_step_insert
BEFORE INSERT ON remote_feedback_effect_step
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_authorization authorization
    JOIN remote_feedback_batch batch
      ON batch.id = authorization.remote_feedback_batch_id
    WHERE authorization.id = NEW.remote_feedback_authorization_id
      AND authorization.remote_feedback_batch_id =
            NEW.remote_feedback_batch_id
      AND NEW.status = 'REQUESTED'
      AND NEW.attempt_count = 0
      AND NEW.ordinal <= authorization.effect_count
      AND batch.status = 'AWAITING_APPROVAL'
      AND (NEW.kind IN ('PUSH_COMMITS', 'SUBMIT_REVIEW', 'REQUEST_REVIEWER',
            'POST_MAINTAINER_NUDGE')
        OR EXISTS (
          SELECT 1 FROM remote_feedback_batch_item batch_item
          JOIN remote_inbox_item inbox
            ON inbox.id = batch_item.remote_inbox_item_id
          WHERE batch_item.remote_feedback_batch_id = batch.id
            AND batch_item.remote_inbox_item_id = NEW.remote_inbox_item_id
            AND ((NEW.kind = 'POST_INLINE_REPLY'
                    AND inbox.kind = 'INLINE_COMMENT')
              OR (NEW.kind = 'POST_TOP_LEVEL_REPLY'
                    AND inbox.kind IN ('TOP_LEVEL_COMMENT', 'REVIEW_BODY',
                        'REVIEW_VERDICT'))
              OR (NEW.kind = 'RESOLVE_THREAD'
                    AND inbox.kind IN ('INLINE_COMMENT', 'THREAD_REOPENED'))))))
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect is outside its authorization'); END;
CREATE TRIGGER remote_feedback_effect_step_result_fields
BEFORE UPDATE OF external_effect_id, evidence, last_error, completed_at_ms
        ON remote_feedback_effect_step
WHEN (NEW.external_effect_id IS NOT OLD.external_effect_id
    OR NEW.evidence IS NOT OLD.evidence
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
  AND NEW.status IS OLD.status
  AND NOT (NEW.status = 'CLAIMED'
    AND NEW.attempt_count = OLD.attempt_count + 1
    AND NEW.external_effect_id IS NULL AND NEW.evidence IS NULL
    AND NEW.last_error IS NULL AND NEW.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'Remote feedback result changes only at a result or claim boundary'); END;
CREATE TRIGGER remote_feedback_effect_step_terminal_immutable
BEFORE UPDATE ON remote_feedback_effect_step
WHEN OLD.status = 'SUCCEEDED'
BEGIN SELECT RAISE(ABORT, 'Succeeded remote feedback effect is immutable'); END;
CREATE TRIGGER remote_feedback_effect_step_transition
BEFORE UPDATE OF status ON remote_feedback_effect_step
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status = 'CLAIMED')
    OR (OLD.status = 'CLAIMED'
        AND NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE')))
BEGIN SELECT RAISE(ABORT, 'Remote feedback effect transition is invalid'); END;
CREATE TRIGGER remote_feedback_repair_result_immutable
BEFORE UPDATE ON remote_feedback_repair_result
BEGIN SELECT RAISE(ABORT, 'Remote feedback repair result is immutable'); END;
CREATE TRIGGER remote_feedback_repair_result_insert
BEFORE INSERT ON remote_feedback_repair_result
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_batch batch
    JOIN remote_feedback_stage_turn_request request
      ON request.remote_feedback_batch_id = batch.id
    JOIN stage_turn turn ON turn.id = request.stage_turn_id
    JOIN remote_development_stage remote
      ON remote.stage_id = batch.remote_development_stage_id
    JOIN tasks task ON task.id = batch.task_id
    WHERE batch.id = NEW.remote_feedback_batch_id
      AND batch.status = 'ADDRESSING'
      AND request.stage_turn_id = NEW.repair_stage_turn_id
      AND request.semantic_attempt = (
          SELECT MAX(latest.semantic_attempt)
          FROM remote_feedback_stage_turn_request latest
          WHERE latest.remote_feedback_batch_id = batch.id)
      AND turn.status = 'SUCCEEDED'
      AND batch.task_id = NEW.task_id
      AND batch.task_epoch = NEW.task_epoch
      AND batch.remote_development_stage_id = NEW.remote_development_stage_id
      AND batch.stage_generation = NEW.stage_generation
      AND batch.head_sha = NEW.subject_head_sha
      AND batch.base_sha = NEW.base_sha
      AND remote.current_head_sha = NEW.subject_head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND turn.expected_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Remote feedback repair result is stale or unowned'); END;
CREATE TRIGGER remote_feedback_reply_draft_immutable
BEFORE UPDATE ON remote_feedback_reply_draft
BEGIN SELECT RAISE(ABORT, 'Remote feedback reply draft is immutable'); END;
CREATE TRIGGER remote_feedback_reply_draft_insert
BEFORE INSERT ON remote_feedback_reply_draft
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_repair_result repair
    JOIN remote_feedback_batch_item item
      ON item.remote_feedback_batch_id = repair.remote_feedback_batch_id
    JOIN remote_inbox_item inbox ON inbox.id = item.remote_inbox_item_id
    WHERE repair.id = NEW.repair_result_id
      AND repair.remote_feedback_batch_id = NEW.remote_feedback_batch_id
      AND item.ordinal = NEW.batch_item_ordinal
      AND (NEW.external_target IS NULL OR NEW.external_target = item.external_target)
      AND ((NEW.kind = 'POST_INLINE_REPLY' AND inbox.kind = 'INLINE_COMMENT')
        OR (NEW.kind = 'POST_TOP_LEVEL_REPLY' AND inbox.kind IN (
            'TOP_LEVEL_COMMENT', 'REVIEW_BODY', 'REVIEW_VERDICT'))
        OR (NEW.kind = 'RESOLVE_THREAD' AND inbox.kind IN (
            'INLINE_COMMENT', 'THREAD_REOPENED'))))
BEGIN SELECT RAISE(ABORT, 'Remote feedback reply draft is outside its frozen batch'); END;
CREATE TRIGGER remote_feedback_stage_turn_request_immutable
BEFORE UPDATE ON remote_feedback_stage_turn_request
BEGIN SELECT RAISE(ABORT, 'Remote feedback StageTurn request is immutable'); END;
CREATE TRIGGER remote_feedback_stage_turn_request_insert
BEFORE INSERT ON remote_feedback_stage_turn_request
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_feedback_batch batch
    JOIN remote_development_stage remote
      ON remote.stage_id = batch.remote_development_stage_id
    JOIN tasks task ON task.id = batch.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = remote.stage_id
    JOIN stage_turn turn ON turn.id = NEW.stage_turn_id
    WHERE batch.id = NEW.remote_feedback_batch_id
      AND batch.status IN ('FROZEN', 'ADDRESSING')
      AND batch.task_id = NEW.task_id
      AND batch.task_epoch = NEW.task_epoch
      AND batch.stage_generation = NEW.stage_generation
      AND batch.remote_development_stage_id = NEW.remote_development_stage_id
      AND remote.current_head_sha = batch.head_sha
      AND remote.current_base_sha = batch.base_sha
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE' AND task.epoch = NEW.task_epoch
      AND current.stage_id = remote.stage_id
      AND current.stage_generation = remote.generation
      AND owner.checkpoint = 'ADDRESSING_REMOTE_FEEDBACK'
      AND owner.completed_at_ms IS NULL
      AND turn.stage_id = remote.stage_id
      AND turn.stage_generation = remote.generation
      AND turn.task_epoch = NEW.task_epoch
      AND turn.purpose = 'ADDRESS_REMOTE_FEEDBACK'
      AND turn.attempt = NEW.semantic_attempt
      AND turn.expected_base_sha = batch.base_sha
      AND turn.status = 'QUEUED'
      AND ((NEW.semantic_attempt = 1 AND NEW.predecessor_turn_id IS NULL
            AND turn.expected_head_sha = batch.head_sha)
        OR (NEW.semantic_attempt > 1 AND EXISTS (
            SELECT 1 FROM remote_feedback_stage_turn_request previous
            JOIN stage_turn previous_turn
              ON previous_turn.id = previous.stage_turn_id
            JOIN remote_feedback_repair_result previous_repair
              ON previous_repair.repair_stage_turn_id = previous.stage_turn_id
            WHERE previous.remote_feedback_batch_id = batch.id
              AND previous.semantic_attempt = NEW.semantic_attempt - 1
              AND previous.stage_turn_id = NEW.predecessor_turn_id
              AND turn.expected_head_sha = previous_repair.proposed_head_sha
              AND turn.expected_code_fingerprint = previous_repair.code_fingerprint
              AND previous_turn.status IN (
                  'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
        OR (NEW.semantic_attempt > 1 AND EXISTS (
            SELECT 1 FROM remote_feedback_stage_turn_request previous
            JOIN stage_turn previous_turn
              ON previous_turn.id = previous.stage_turn_id
            JOIN stage_steering_request_v257 steering
              ON steering.predecessor_owner_id = previous.stage_turn_id
             AND steering.predecessor_operation_id = previous_turn.operation_id
            JOIN remote_stage_steering_handoff_v257 handoff
              ON handoff.request_id = steering.id
            WHERE previous.remote_feedback_batch_id = batch.id
              AND previous.semantic_attempt = NEW.semantic_attempt - 1
              AND previous.stage_turn_id = NEW.predecessor_turn_id
              AND steering.status = 'PENDING'
              AND steering.stage_id = NEW.remote_development_stage_id
              AND steering.stage_generation = NEW.stage_generation
              AND steering.predecessor_purpose = 'ADDRESS_REMOTE_FEEDBACK'
              AND handoff.owner_family = 'REMOTE_FEEDBACK'
              AND handoff.status = 'PARKED'
              AND NOT EXISTS (
                  SELECT 1 FROM stage_turn_user_wait_continuation_v265 wait
                  WHERE wait.request_id = steering.id)
              AND previous_turn.status IN (
                  'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
              AND turn.expected_head_sha = previous_turn.expected_head_sha
              AND turn.expected_code_fingerprint =
                  previous_turn.expected_code_fingerprint))
        OR (NEW.semantic_attempt > 1 AND EXISTS (
            SELECT 1 FROM remote_feedback_stage_turn_request previous
            JOIN stage_turn previous_turn
              ON previous_turn.id = previous.stage_turn_id
            JOIN stage_steering_request_v257 steering
              ON steering.predecessor_owner_id = previous.stage_turn_id
             AND steering.predecessor_operation_id = previous_turn.operation_id
            JOIN remote_stage_steering_handoff_v257 handoff
              ON handoff.request_id = steering.id
            JOIN stage_turn_user_wait_continuation_v265 continuation
              ON continuation.request_id = steering.id
             AND continuation.predecessor_turn_id = previous_turn.id
             AND continuation.predecessor_operation_id = previous_turn.operation_id
            JOIN typed_user_wait_result result
              ON result.operation_id = previous_turn.operation_id
             AND result.owner_kind = 'STAGE_TURN'
             AND result.turn_id = previous_turn.id
             AND result.wait_kind = continuation.wait_kind
             AND result.wait_id = continuation.wait_id
            WHERE previous.remote_feedback_batch_id = batch.id
              AND previous.task_id = NEW.task_id
              AND previous.task_epoch = NEW.task_epoch
              AND previous.remote_development_stage_id =
                  NEW.remote_development_stage_id
              AND previous.stage_generation = NEW.stage_generation
              AND previous.semantic_attempt = NEW.semantic_attempt - 1
              AND previous.stage_turn_id = NEW.predecessor_turn_id
              AND previous_turn.stage_id = NEW.remote_development_stage_id
              AND previous_turn.stage_generation = NEW.stage_generation
              AND previous_turn.task_epoch = NEW.task_epoch
              AND previous_turn.attempt = previous.semantic_attempt
              AND previous_turn.purpose = 'ADDRESS_REMOTE_FEEDBACK'
              AND previous_turn.status = 'SUCCEEDED'
              AND steering.status = 'PENDING'
              AND steering.mode = 'CANCEL_AND_REPLACE'
              AND steering.task_id = NEW.task_id
              AND steering.task_epoch = NEW.task_epoch
              AND steering.stage_id = NEW.remote_development_stage_id
              AND steering.stage_generation = NEW.stage_generation
              AND steering.predecessor_owner_kind = 'STAGE_TURN'
              AND steering.predecessor_owner_id = previous_turn.id
              AND steering.predecessor_operation_id = previous_turn.operation_id
              AND steering.predecessor_purpose = 'ADDRESS_REMOTE_FEEDBACK'
              AND handoff.owner_family = 'REMOTE_FEEDBACK'
              AND handoff.owner_purpose = 'ADDRESS_REMOTE_FEEDBACK'
              AND handoff.predecessor_turn_id = previous_turn.id
              AND handoff.predecessor_operation_id = previous_turn.operation_id
              AND handoff.status = 'PARKED'
              AND continuation.successor_turn_id IS NULL
              AND turn.attempt = previous_turn.attempt + 1
              AND turn.expected_code_fingerprint IS
                  previous_turn.expected_code_fingerprint
              AND turn.expected_head_sha IS previous_turn.expected_head_sha
              AND turn.expected_base_sha IS previous_turn.expected_base_sha
              AND ((continuation.wait_kind = 'QUESTION' AND EXISTS (
                    SELECT 1 FROM stage_question question
                    WHERE question.id = continuation.wait_id
                      AND question.turn_id = previous_turn.id
                      AND question.state = 'ANSWERED'
                      AND question.continuation_state = 'READY'))
                OR (continuation.wait_kind = 'PERMISSION' AND EXISTS (
                    SELECT 1 FROM permission_request permission
                    WHERE permission.id = continuation.wait_id
                      AND permission.turn_kind = 'STAGE'
                      AND permission.turn_id = previous_turn.id
                      AND permission.operation_id = previous_turn.operation_id
                      AND permission.state <> 'OPEN'
                      AND permission.continuation_state = 'READY')))))
        OR (NEW.semantic_attempt > 1 AND EXISTS (
            SELECT 1 FROM remote_feedback_stage_turn_request previous
            JOIN stage_turn previous_turn
              ON previous_turn.id = previous.stage_turn_id
            JOIN stage_resume_rearm_successor_v257 successor
              ON successor.owner_id = NEW.stage_turn_id
             AND successor.operation_id = turn.operation_id
             AND successor.semantic_attempt = NEW.semantic_attempt
            JOIN stage_resume_rearm_intent_v257 intent
              ON intent.handoff_id = successor.handoff_id
            WHERE previous.remote_feedback_batch_id = batch.id
              AND previous.semantic_attempt = NEW.semantic_attempt - 1
              AND previous.stage_turn_id = NEW.predecessor_turn_id
              AND previous_turn.status = 'CANCELED'
              AND successor.status = 'PREPARED'
              AND successor.owner_kind = 'STAGE_TURN'
              AND successor.purpose = 'ADDRESS_REMOTE_FEEDBACK'
              AND intent.status = 'PENDING'
              AND intent.task_id = NEW.task_id
              AND intent.stage_id = NEW.remote_development_stage_id
              AND intent.stage_generation = NEW.stage_generation
              AND intent.restore_checkpoint = 'ADDRESSING_REMOTE_FEEDBACK'
              AND turn.expected_head_sha = previous_turn.expected_head_sha
              AND turn.expected_code_fingerprint =
                  previous_turn.expected_code_fingerprint))))
BEGIN SELECT RAISE(ABORT, 'Remote feedback StageTurn lacks its exact batch and owner'); END;
CREATE TRIGGER remote_feedback_validation_attempt_evidence_immutable
BEFORE UPDATE ON remote_feedback_validation_attempt_evidence
BEGIN SELECT RAISE(ABORT, 'Remote validation attempt evidence is immutable'); END;
CREATE TRIGGER remote_feedback_validation_attempt_evidence_insert
BEFORE INSERT ON remote_feedback_validation_attempt_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_validation_operation operation
    JOIN remote_feedback_repair_result repair ON repair.id = operation.repair_result_id
    JOIN remote_feedback_stage_turn_request request
      ON request.stage_turn_id = repair.repair_stage_turn_id
    JOIN validation_pass validation ON validation.id = NEW.validation_pass_id
    JOIN remote_feedback_batch batch ON batch.id = operation.remote_feedback_batch_id
    WHERE operation.id = NEW.validation_operation_id
      AND operation.status = 'DISPATCHED'
      AND operation.remote_feedback_batch_id = NEW.remote_feedback_batch_id
      AND operation.repair_result_id = NEW.repair_result_id
      AND operation.remote_development_stage_id = NEW.remote_development_stage_id
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.stage_generation = NEW.stage_generation
      AND operation.semantic_attempt = NEW.semantic_attempt
      AND operation.code_fingerprint = NEW.code_fingerprint
      AND operation.expected_head_sha = NEW.proposed_head_sha
      AND operation.expected_base_sha = NEW.base_sha
      AND repair.repair_stage_turn_id = NEW.repair_stage_turn_id
      AND repair.subject_head_sha = NEW.subject_head_sha
      AND request.semantic_attempt = NEW.semantic_attempt
      AND batch.status = 'ADDRESSING'
      AND validation.task_id = NEW.task_id
      AND validation.workflow_version = 'V2'
      AND validation.task_epoch = NEW.task_epoch
      AND validation.stage_id = NEW.remote_development_stage_id
      AND validation.stage_generation = NEW.stage_generation
      AND validation.operation_id = operation.operation_id
      AND validation.semantic_attempt = NEW.semantic_attempt
      AND validation.code_fingerprint = NEW.code_fingerprint
      AND validation.expected_head_sha = NEW.proposed_head_sha
      AND validation.expected_base_sha = NEW.base_sha
      AND validation.passed = NEW.passed
      AND validation.ended_at_ms = NEW.completed_at_ms)
BEGIN SELECT RAISE(ABORT, 'Remote validation attempt evidence is stale or unowned'); END;
CREATE TRIGGER remote_feedback_validation_evidence_immutable
BEFORE UPDATE ON remote_feedback_validation_evidence
BEGIN SELECT RAISE(ABORT, 'Remote feedback validation evidence is immutable'); END;
CREATE TRIGGER remote_feedback_validation_evidence_insert
BEFORE INSERT ON remote_feedback_validation_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM remote_feedback_batch batch
    JOIN remote_development_stage remote
      ON remote.stage_id = batch.remote_development_stage_id
    JOIN tasks task ON task.id = batch.task_id
    JOIN remote_feedback_repair_result repair
      ON repair.remote_feedback_batch_id = batch.id
    JOIN stage_turn turn ON turn.id = repair.repair_stage_turn_id
    JOIN validation_pass validation ON validation.id = NEW.validation_pass_id
    WHERE batch.id = NEW.remote_feedback_batch_id
      AND batch.status IN ('ADDRESSING', 'AWAITING_APPROVAL')
      AND batch.remote_development_stage_id = NEW.remote_development_stage_id
      AND batch.task_id = NEW.task_id
      AND batch.task_epoch = NEW.task_epoch
      AND batch.stage_generation = NEW.stage_generation
      AND batch.head_sha = NEW.subject_head_sha
      AND batch.base_sha = NEW.base_sha
      AND remote.current_head_sha = NEW.subject_head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND repair.repair_stage_turn_id = NEW.repair_stage_turn_id
      AND repair.subject_head_sha = NEW.subject_head_sha
      AND repair.proposed_head_sha = NEW.proposed_head_sha
      AND repair.base_sha = NEW.base_sha
      AND repair.code_fingerprint = NEW.code_fingerprint
      AND turn.stage_id = NEW.remote_development_stage_id
      AND turn.stage_generation = NEW.stage_generation
      AND turn.task_epoch = NEW.task_epoch
      AND turn.purpose = 'ADDRESS_REMOTE_FEEDBACK'
      AND turn.status = 'SUCCEEDED'
      AND turn.expected_base_sha = NEW.base_sha
      AND validation.task_id = NEW.task_id
      AND validation.workflow_version = 'V2'
      AND validation.task_epoch = NEW.task_epoch
      AND validation.stage_id = NEW.remote_development_stage_id
      AND validation.stage_generation = NEW.stage_generation
      AND validation.operation_id = NEW.validation_operation_id
      AND validation.semantic_attempt = NEW.validation_attempt
      AND validation.code_fingerprint = NEW.code_fingerprint
      AND validation.expected_head_sha = NEW.proposed_head_sha
      AND validation.expected_base_sha = NEW.base_sha
      AND validation.ended_at_ms = NEW.completed_at_ms
      AND validation.passed = NEW.passed)
BEGIN SELECT RAISE(ABORT, 'Remote feedback validation lacks exact repair evidence'); END;
CREATE TRIGGER remote_feedback_validation_operation_identity_immutable
BEFORE UPDATE OF remote_feedback_batch_id, repair_result_id,
        remote_development_stage_id, task_id, task_epoch, stage_generation,
        operation_id, semantic_attempt, code_fingerprint, expected_head_sha,
        expected_base_sha, requested_at_ms ON remote_feedback_validation_operation
BEGIN SELECT RAISE(ABORT, 'Remote feedback validation identity is immutable'); END;
CREATE TRIGGER remote_feedback_validation_operation_insert
BEFORE INSERT ON remote_feedback_validation_operation
WHEN NEW.status <> 'REQUESTED' OR NOT EXISTS (
    SELECT 1 FROM remote_feedback_repair_result repair
    JOIN remote_feedback_batch batch ON batch.id = repair.remote_feedback_batch_id
    JOIN remote_development_stage remote
      ON remote.stage_id = batch.remote_development_stage_id
    JOIN tasks task ON task.id = batch.task_id
    WHERE repair.id = NEW.repair_result_id
      AND batch.id = NEW.remote_feedback_batch_id
      AND batch.status = 'ADDRESSING'
      AND batch.remote_development_stage_id = NEW.remote_development_stage_id
      AND batch.task_id = NEW.task_id
      AND batch.task_epoch = NEW.task_epoch
      AND batch.stage_generation = NEW.stage_generation
      AND repair.code_fingerprint = NEW.code_fingerprint
      AND repair.proposed_head_sha = NEW.expected_head_sha
      AND repair.base_sha = NEW.expected_base_sha
      AND remote.current_head_sha = repair.subject_head_sha
      AND remote.current_base_sha = repair.base_sha
      AND task.epoch = NEW.task_epoch)
BEGIN SELECT RAISE(ABORT, 'Remote feedback validation operation is stale or unowned'); END;
CREATE TRIGGER remote_feedback_validation_operation_terminal_immutable
BEFORE UPDATE ON remote_feedback_validation_operation
WHEN OLD.status IN ('COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'Terminal remote feedback validation is immutable'); END;
CREATE TRIGGER remote_feedback_validation_operation_transition
BEFORE UPDATE OF status ON remote_feedback_validation_operation
WHEN NOT ((OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'Remote feedback validation transition is invalid'); END;
CREATE TRIGGER remote_head_evidence_invalidation_immutable
BEFORE UPDATE ON remote_head_evidence_invalidation
BEGIN SELECT RAISE(ABORT, 'Remote head invalidation evidence is immutable'); END;
CREATE TRIGGER remote_inbox_item_immutable
BEFORE UPDATE ON remote_inbox_item
BEGIN SELECT RAISE(ABORT, 'Remote inbox item is immutable'); END;
CREATE TRIGGER remote_inbox_item_insert
BEFORE INSERT ON remote_inbox_item
WHEN NOT EXISTS (
    SELECT 1 FROM remote_pr_snapshot snapshot
    JOIN remote_development_stage remote
      ON remote.stage_id = snapshot.remote_development_stage_id
    JOIN tasks task ON task.id = remote.task_id
    WHERE snapshot.id = NEW.remote_pr_snapshot_id
      AND snapshot.remote_development_stage_id =
            NEW.remote_development_stage_id
      AND snapshot.task_id = NEW.task_id
      AND snapshot.stage_generation = NEW.stage_generation
      AND snapshot.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND snapshot.head_sha = NEW.head_sha
      AND snapshot.base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch)
BEGIN SELECT RAISE(ABORT, 'Remote inbox item subject fence is invalid'); END;
CREATE TRIGGER remote_mark_ready_authorization_identity_immutable
BEFORE UPDATE OF remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_snapshot_id, ci_evaluation_id,
        automation_policy_id, head_sha, base_sha, authority_kind, actor_id,
        authorized_at_ms ON remote_mark_ready_authorization
WHEN NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.remote_pr_snapshot_id IS NOT OLD.remote_pr_snapshot_id
  OR NEW.ci_evaluation_id IS NOT OLD.ci_evaluation_id
  OR NEW.automation_policy_id IS NOT OLD.automation_policy_id
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.authority_kind IS NOT OLD.authority_kind
  OR NEW.actor_id IS NOT OLD.actor_id
  OR NEW.authorized_at_ms IS NOT OLD.authorized_at_ms
BEGIN SELECT RAISE(ABORT, 'Mark-ready authorization identity is immutable'); END;
CREATE TRIGGER remote_mark_ready_authorization_insert
BEFORE INSERT ON remote_mark_ready_authorization
WHEN NEW.status <> 'ACTIVE'
  OR NOT EXISTS (
    SELECT 1 FROM remote_development_stage remote
    JOIN tasks task ON task.id = remote.task_id
    JOIN remote_pr_snapshot snapshot ON snapshot.id = NEW.remote_pr_snapshot_id
    JOIN remote_ci_evaluation ci ON ci.id = NEW.ci_evaluation_id
    JOIN task_automation_policy policy ON policy.id = NEW.automation_policy_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND remote.accepted_snapshot_id = snapshot.id
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND snapshot.remote_development_stage_id = remote.stage_id
      AND snapshot.task_id = NEW.task_id
      AND snapshot.stage_generation = NEW.stage_generation
      AND snapshot.head_sha = NEW.head_sha
      AND snapshot.base_sha = NEW.base_sha
      AND snapshot.pr_state = 'DRAFT'
      AND ci.remote_pr_snapshot_id = snapshot.id
      AND ci.head_sha = NEW.head_sha
      AND ci.base_sha = NEW.base_sha
      AND ci.policy_outcome = 'ACCEPTED'
      AND policy.task_id = NEW.task_id
      AND policy.revision = (
          SELECT MAX(current_policy.revision)
          FROM task_automation_policy current_policy
          WHERE current_policy.task_id = NEW.task_id)
      AND (NEW.authority_kind = 'MANUAL'
        OR (policy.keep_draft = 0
            AND policy.stewardship_exception = 0)))
BEGIN SELECT RAISE(ABORT, 'Mark-ready authorization lacks current Draft and green exact-head proof'); END;
CREATE TRIGGER remote_mark_ready_authorization_terminal_immutable
BEFORE UPDATE ON remote_mark_ready_authorization
WHEN OLD.status IN ('CONSUMED', 'REVOKED')
BEGIN SELECT RAISE(ABORT, 'Terminal mark-ready authorization is immutable'); END;
CREATE TRIGGER remote_mark_ready_authorization_transition
BEFORE UPDATE OF status ON remote_mark_ready_authorization
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status <> 'ACTIVE'
    OR NEW.status NOT IN ('CONSUMED', 'REVOKED')
    OR (NEW.status = 'CONSUMED' AND NOT EXISTS (
        SELECT 1 FROM remote_mark_ready_operation operation
        WHERE operation.mark_ready_authorization_id = NEW.id)))
BEGIN SELECT RAISE(ABORT, 'Mark-ready authorization transition is invalid'); END;
CREATE TRIGGER remote_mark_ready_dispatch_immutable
BEFORE UPDATE ON remote_mark_ready_dispatch
BEGIN SELECT RAISE(ABORT, 'Mark-ready dispatch is immutable'); END;
CREATE TRIGGER remote_mark_ready_dispatch_insert
BEFORE INSERT ON remote_mark_ready_dispatch
WHEN NOT EXISTS (
    SELECT 1 FROM remote_mark_ready_operation operation
    JOIN remote_mark_ready_authorization authorization
      ON authorization.id = operation.mark_ready_authorization_id
    JOIN remote_development_stage remote
      ON remote.stage_id = operation.remote_development_stage_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    WHERE operation.id = NEW.remote_mark_ready_operation_id
      AND operation.operation_id = NEW.operation_id
      AND operation.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
      AND authorization.status = 'CONSUMED'
      AND remote.current_head_sha = operation.head_sha
      AND remote.current_base_sha = operation.base_sha
      AND ticket.operation_id = NEW.operation_id
      AND ticket.operation_kind = 'MARK_REMOTE_PR_READY'
      AND ticket.async_family = 'GITHUB_EFFECT'
      AND ticket.owner_kind = 'STAGE'
      AND ticket.owner_id = operation.remote_development_stage_id
      AND ticket.callback_route = 'REMOTE_MARK_READY_RESULT'
      AND ticket.task_id = operation.task_id
      AND ticket.task_epoch = operation.task_epoch
      AND ticket.stage_id = operation.remote_development_stage_id
      AND ticket.stage_generation = operation.stage_generation
      AND ticket.attempt = operation.semantic_attempt
      AND ticket.expected_head_sha = operation.head_sha
      AND ticket.expected_base_sha = operation.base_sha
      AND ticket.lane_mask = 32
      AND ticket.trunk_control = 0
      AND ticket.exclusive_task = 1
      AND ticket.writer_required = 0
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Mark-ready dispatch lacks consumed exact-head authority'); END;
CREATE TRIGGER remote_mark_ready_operation_attempt
BEFORE UPDATE OF attempt_count ON remote_mark_ready_operation
WHEN NEW.status <> 'CLAIMED' OR NEW.attempt_count <> OLD.attempt_count + 1
BEGIN SELECT RAISE(ABORT, 'Mark-ready attempt must be an exact claim'); END;
CREATE TRIGGER remote_mark_ready_operation_claim
BEFORE UPDATE OF status ON remote_mark_ready_operation
WHEN NEW.status = 'CLAIMED'
  AND (NEW.attempt_count <> OLD.attempt_count + 1
    OR OLD.status NOT IN ('REQUESTED', 'CLAIMED', 'FAILED', 'INDETERMINATE')
    OR (OLD.status = 'CLAIMED'
        AND (NEW.claim_mode <> 'PROBE'
          OR NEW.claimed_at_ms < OLD.lease_until_ms))
    OR (OLD.status = 'INDETERMINATE' AND NEW.claim_mode <> 'PROBE')
    OR (OLD.status NOT IN ('CLAIMED', 'INDETERMINATE')
        AND NEW.claim_mode <> 'EXECUTE')
    OR NEW.result_snapshot_id IS NOT NULL OR NEW.evidence IS NOT NULL
    OR NEW.last_error IS NOT NULL OR NEW.completed_at_ms IS NOT NULL
    OR NOT EXISTS (
        SELECT 1 FROM remote_mark_ready_authorization authorization
        JOIN remote_development_stage remote
          ON remote.stage_id = authorization.remote_development_stage_id
        WHERE authorization.id = NEW.mark_ready_authorization_id
          AND authorization.status = 'CONSUMED'
          AND remote.accepted_snapshot_id = authorization.remote_pr_snapshot_id
          AND remote.current_head_sha = NEW.head_sha
          AND remote.current_base_sha = NEW.base_sha))
BEGIN SELECT RAISE(ABORT, 'Mark-ready claim is stale or lacks consumed consent'); END;
CREATE TRIGGER remote_mark_ready_operation_claim_fields
BEFORE UPDATE OF claim_mode, claim_owner, claimed_at_ms, lease_until_ms
        ON remote_mark_ready_operation
WHEN NOT ((NEW.status = 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count + 1)
        OR (OLD.status = 'CLAIMED' AND NEW.status <> 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count
            AND NEW.claim_mode IS NULL AND NEW.claim_owner IS NULL
            AND NEW.claimed_at_ms IS NULL AND NEW.lease_until_ms IS NULL))
BEGIN SELECT RAISE(ABORT, 'Mark-ready claim fields change only with an attempt boundary'); END;
CREATE TRIGGER remote_mark_ready_operation_identity_immutable
BEFORE UPDATE OF mark_ready_authorization_id, remote_development_stage_id,
        task_id, task_epoch, stage_generation, operation_id, semantic_attempt,
        head_sha, base_sha, attempt_limit, requested_at_ms
        ON remote_mark_ready_operation
WHEN NEW.mark_ready_authorization_id IS NOT OLD.mark_ready_authorization_id
  OR NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'Mark-ready operation subject is immutable'); END;
CREATE TRIGGER remote_mark_ready_operation_insert
BEFORE INSERT ON remote_mark_ready_operation
WHEN NEW.status <> 'REQUESTED' OR NEW.attempt_count <> 0
  OR NOT EXISTS (
    SELECT 1 FROM remote_mark_ready_authorization authorization
    JOIN remote_development_stage remote
      ON remote.stage_id = authorization.remote_development_stage_id
    WHERE authorization.id = NEW.mark_ready_authorization_id
      AND authorization.status = 'ACTIVE'
      AND authorization.remote_development_stage_id = NEW.remote_development_stage_id
      AND authorization.task_id = NEW.task_id
      AND authorization.task_epoch = NEW.task_epoch
      AND authorization.stage_generation = NEW.stage_generation
      AND authorization.head_sha = NEW.head_sha
      AND authorization.base_sha = NEW.base_sha
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Mark-ready operation lacks active exact-head authorization'); END;
CREATE TRIGGER remote_mark_ready_operation_result_fields
BEFORE UPDATE OF result_snapshot_id, evidence, last_error, completed_at_ms
        ON remote_mark_ready_operation
WHEN (NEW.result_snapshot_id IS NOT OLD.result_snapshot_id
    OR NEW.evidence IS NOT OLD.evidence
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
  AND NEW.status IS OLD.status
  AND NOT (NEW.status = 'CLAIMED'
    AND NEW.attempt_count = OLD.attempt_count + 1
    AND NEW.result_snapshot_id IS NULL AND NEW.evidence IS NULL
    AND NEW.last_error IS NULL AND NEW.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'Mark-ready result changes only at a result or claim boundary'); END;
CREATE TRIGGER remote_mark_ready_operation_success
BEFORE UPDATE OF status ON remote_mark_ready_operation
WHEN NEW.status = 'SUCCEEDED'
  AND NOT EXISTS (
      SELECT 1 FROM remote_pr_snapshot snapshot
      JOIN remote_development_stage remote
        ON remote.stage_id = snapshot.remote_development_stage_id
      WHERE snapshot.id = NEW.result_snapshot_id
        AND snapshot.remote_development_stage_id = NEW.remote_development_stage_id
        AND snapshot.task_id = NEW.task_id
        AND snapshot.stage_generation = NEW.stage_generation
        AND snapshot.head_sha = NEW.head_sha
        AND snapshot.base_sha = NEW.base_sha
        AND snapshot.pr_state = 'OPEN'
        AND remote.accepted_snapshot_id = snapshot.id
        AND remote.current_head_sha = NEW.head_sha
        AND remote.current_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Mark-ready success requires accepted non-Draft remote truth'); END;
CREATE TRIGGER remote_mark_ready_operation_terminal_immutable
BEFORE UPDATE ON remote_mark_ready_operation
WHEN OLD.status IN ('SUCCEEDED', 'CANCELED')
BEGIN SELECT RAISE(ABORT, 'Terminal mark-ready operation is immutable'); END;
CREATE TRIGGER remote_mark_ready_operation_transition
BEFORE UPDATE OF status ON remote_mark_ready_operation
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status = 'CLAIMED')
    OR (OLD.status = 'CLAIMED'
        AND NEW.status IN ('AWAITING_OBSERVATION', 'FAILED',
            'INDETERMINATE', 'CANCELED'))
    OR (OLD.status = 'AWAITING_OBSERVATION'
        AND NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE', 'CANCELED')))
BEGIN SELECT RAISE(ABORT, 'Mark-ready operation transition is invalid'); END;
CREATE TRIGGER remote_merge_authorization_identity_immutable
BEFORE UPDATE OF remote_development_stage_id, task_id, task_epoch,
        stage_generation, readiness_evidence_id, automation_policy_id,
        head_sha, base_sha, authority_kind, actor_id, authorized_at_ms
        ON remote_merge_authorization
WHEN NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.readiness_evidence_id IS NOT OLD.readiness_evidence_id
  OR NEW.automation_policy_id IS NOT OLD.automation_policy_id
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.authority_kind IS NOT OLD.authority_kind
  OR NEW.actor_id IS NOT OLD.actor_id
  OR NEW.authorized_at_ms IS NOT OLD.authorized_at_ms
BEGIN SELECT RAISE(ABORT, 'Merge authorization identity is immutable'); END;
CREATE TRIGGER remote_merge_authorization_insert
BEFORE INSERT ON remote_merge_authorization
WHEN NOT EXISTS (
    SELECT 1 FROM remote_readiness_evidence readiness
    JOIN remote_development_stage remote
      ON remote.stage_id = readiness.remote_development_stage_id
    JOIN task_automation_policy policy
      ON policy.id = readiness.automation_policy_id
    JOIN tasks task ON task.id = readiness.task_id
    WHERE readiness.id = NEW.readiness_evidence_id
      AND readiness.ready = 1
      AND readiness.remote_development_stage_id =
            NEW.remote_development_stage_id
      AND readiness.task_id = NEW.task_id
      AND readiness.task_epoch = NEW.task_epoch
      AND readiness.stage_generation = NEW.stage_generation
      AND readiness.automation_policy_id = NEW.automation_policy_id
      AND policy.revision = (
          SELECT MAX(current_policy.revision)
          FROM task_automation_policy current_policy
          WHERE current_policy.task_id = NEW.task_id)
      AND readiness.head_sha = NEW.head_sha
      AND readiness.base_sha = NEW.base_sha
      AND remote.accepted_snapshot_id = readiness.remote_pr_snapshot_id
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND (NEW.authority_kind = 'MANUAL'
        OR (policy.auto_merge = 1 AND policy.auto_approve = 1
            AND policy.stewardship_exception = 0)))
BEGIN SELECT RAISE(ABORT, 'Merge authorization lacks fresh exact-head readiness'); END;
CREATE TRIGGER remote_merge_authorization_method_immutable_v274
BEFORE UPDATE OF merge_method ON remote_merge_authorization
WHEN NEW.merge_method IS NOT OLD.merge_method
BEGIN SELECT RAISE(ABORT, 'Merge authorization method is immutable'); END;
CREATE TRIGGER remote_merge_authorization_terminal_immutable
BEFORE UPDATE ON remote_merge_authorization
WHEN OLD.status IN ('CONSUMED', 'REVOKED')
BEGIN SELECT RAISE(ABORT, 'Terminal merge authorization is immutable'); END;
CREATE TRIGGER remote_merge_authorization_transition
BEFORE UPDATE OF status ON remote_merge_authorization
WHEN NEW.status IS NOT OLD.status
  AND (OLD.status <> 'ACTIVE'
    OR NEW.status NOT IN ('CONSUMED', 'REVOKED')
    OR (NEW.status = 'CONSUMED' AND NOT EXISTS (
        SELECT 1 FROM remote_merge_operation operation
        WHERE operation.merge_authorization_id = NEW.id)))
BEGIN SELECT RAISE(ABORT, 'Merge authorization transition is invalid'); END;
CREATE TRIGGER remote_merge_effect_attempt_execute
BEFORE INSERT ON remote_merge_effect_attempt
WHEN NEW.claim_mode = 'EXECUTE'
  AND NOT EXISTS (
      SELECT 1 FROM remote_merge_operation operation
      JOIN remote_merge_authorization authorization
        ON authorization.id = operation.merge_authorization_id
      JOIN remote_readiness_evidence readiness
        ON readiness.id = NEW.readiness_evidence_id
      JOIN remote_pr_snapshot snapshot
        ON snapshot.id = readiness.remote_pr_snapshot_id
      JOIN remote_development_stage remote
        ON remote.stage_id = operation.remote_development_stage_id
      WHERE operation.id = NEW.merge_operation_id
        AND readiness.remote_development_stage_id = operation.remote_development_stage_id
        AND readiness.task_id = operation.task_id
        AND readiness.task_epoch = operation.task_epoch
        AND readiness.stage_generation = operation.stage_generation
        AND readiness.automation_policy_id = authorization.automation_policy_id
        AND readiness.head_sha = operation.head_sha
        AND readiness.base_sha = operation.base_sha
        AND readiness.merge_queue_capability = operation.merge_queue_capability
        AND readiness.ready = 1
        AND snapshot.head_sha = operation.head_sha
        AND snapshot.base_sha = operation.base_sha
        AND remote.accepted_snapshot_id = snapshot.id
        AND remote.current_head_sha = operation.head_sha
        AND remote.current_base_sha = operation.base_sha
        AND ((operation.mode = 'DIRECT'
              AND operation.status = 'REQUESTED'
              AND NEW.effect_kind = 'DIRECT_MERGE'
              AND NEW.effect_ordinal IS NULL
              AND NEW.readiness_evidence_id = authorization.readiness_evidence_id
              AND NEW.idempotency_key = operation.operation_id || ':direct')
          OR (operation.mode = 'MERGE_QUEUE'
              AND NEW.effect_kind = 'ENTER_QUEUE'
              AND NEW.idempotency_key = operation.operation_id || ':queue:' || NEW.effect_ordinal
              AND ((operation.status = 'REQUESTED'
                    AND NEW.effect_ordinal = 1
                    AND snapshot.merge_queue_state IN ('NONE', 'DEQUEUED')
                    AND NEW.readiness_evidence_id = authorization.readiness_evidence_id)
                OR (operation.status = 'AWAITING_OBSERVATION'
                    AND NEW.effect_ordinal = operation.queue_bounce_count + 1
                    AND NEW.effect_ordinal > 1
                    AND NEW.effect_ordinal <= operation.max_queue_reenqueues + 1
                    AND snapshot.merge_queue_state = 'DEQUEUED'
                    AND EXISTS (
                        SELECT 1 FROM remote_merge_queue_entry previous
                        WHERE previous.merge_operation_id = operation.id
                          AND previous.ordinal = NEW.effect_ordinal - 1
                          AND previous.status = 'BOUNCED'
                          AND previous.observed_snapshot_id = snapshot.id))))))
BEGIN SELECT RAISE(ABORT, 'Merge execution claim lacks fresh pre-effect readiness'); END;
CREATE TRIGGER remote_merge_effect_attempt_execute_owner
BEFORE INSERT ON remote_merge_effect_attempt
WHEN NEW.claim_mode = 'EXECUTE'
 AND NOT EXISTS (
      SELECT 1
      FROM remote_merge_operation operation
      JOIN remote_merge_authorization authorization
        ON authorization.id = operation.merge_authorization_id
      JOIN task_automation_policy policy
        ON policy.id = authorization.automation_policy_id
      JOIN tasks task ON task.id = operation.task_id
      JOIN task_current_stage current ON current.task_id = task.id
      JOIN stage owner ON owner.id = current.stage_id
      JOIN stage_command_receipt receipt
        ON receipt.stage_id = owner.id
       AND receipt.returned_version = owner.version
       AND receipt.disposition = 'APPLIED'
      WHERE operation.id = NEW.merge_operation_id
        AND policy.task_id = operation.task_id
        AND policy.revision = (
            SELECT MAX(current_policy.revision)
            FROM task_automation_policy current_policy
            WHERE current_policy.task_id = operation.task_id)
        AND task.workflow_version = 'V2'
        AND task.lifecycle_state = 'ACTIVE'
        AND task.epoch = operation.task_epoch
        AND current.stage_id = operation.remote_development_stage_id
        AND current.stage_generation = operation.stage_generation
        AND owner.task_id = operation.task_id
        AND owner.kind = 'REMOTE_DEVELOPMENT'
        AND owner.generation = operation.stage_generation
        AND owner.checkpoint = 'MERGING'
        AND owner.completed_at_ms IS NULL
        AND owner.end_reason IS NULL
        AND receipt.cause = 'AUTHORIZE_MERGE'
        AND receipt.returned_kind = 'REMOTE_DEVELOPMENT'
        AND receipt.returned_generation = operation.stage_generation
        AND receipt.returned_checkpoint = 'MERGING'
        AND receipt.returned_end_reason IS NULL
        AND receipt.returned_pending_task_epoch = operation.task_epoch
        AND receipt.returned_pending_stage_id = operation.remote_development_stage_id
        AND receipt.returned_pending_stage_generation = operation.stage_generation
        AND receipt.returned_pending_operation_id = operation.operation_id
        AND receipt.returned_pending_attempt = operation.semantic_attempt
        AND receipt.returned_pending_code_fingerprint IS NULL
        AND receipt.returned_pending_head_sha = operation.head_sha
        AND receipt.returned_pending_base_sha = operation.base_sha)
 AND NOT EXISTS (
      SELECT 1
      FROM remote_merge_operation operation
      JOIN remote_merge_authorization authorization
        ON authorization.id = operation.merge_authorization_id
      JOIN task_automation_policy policy
        ON policy.id = authorization.automation_policy_id
      JOIN tasks task ON task.id = operation.task_id
      JOIN task_current_stage current ON current.task_id = task.id
      JOIN stage owner ON owner.id = current.stage_id
      JOIN stage_resume_async_successor_v272 resume
        ON resume.owner_id = operation.id
       AND resume.operation_id = operation.operation_id
      JOIN stage_resume_rearm_intent_v257 intent
        ON intent.handoff_id = resume.handoff_id
      WHERE operation.id = NEW.merge_operation_id
        AND authorization.status = 'CONSUMED'
        AND policy.task_id = operation.task_id
        AND policy.revision = (
            SELECT MAX(current_policy.revision)
            FROM task_automation_policy current_policy
            WHERE current_policy.task_id = operation.task_id)
        AND task.workflow_version = 'V2'
        AND task.lifecycle_state = 'ACTIVE'
        AND task.epoch = operation.task_epoch
        AND current.stage_id = operation.remote_development_stage_id
        AND current.stage_generation = operation.stage_generation
        AND owner.task_id = operation.task_id
        AND owner.kind = 'REMOTE_DEVELOPMENT'
        AND owner.generation = operation.stage_generation
        AND owner.checkpoint = 'MERGING'
        AND owner.completed_at_ms IS NULL
        AND owner.end_reason IS NULL
        AND resume.status = 'ARMED'
        AND resume.owner_kind = 'MERGE_RECOVERY'
        AND resume.domain_attempt = operation.semantic_attempt
        AND resume.returned_stage_version = owner.version
        AND intent.status = 'MATERIALIZED'
        AND intent.task_id = operation.task_id
        AND intent.task_epoch = operation.task_epoch
        AND intent.stage_id = operation.remote_development_stage_id
        AND intent.stage_generation = operation.stage_generation
        AND intent.restore_checkpoint = 'MERGING'
        AND intent.head_sha = operation.head_sha
        AND intent.base_sha = operation.base_sha)
BEGIN SELECT RAISE(ABORT,
    'Merge execution claim lacks current Task and Stage authority'); END;
CREATE TRIGGER remote_merge_effect_attempt_identity_immutable
BEFORE UPDATE OF merge_operation_id, ordinal, effect_kind, effect_ordinal,
        readiness_evidence_id, idempotency_key, attempt_key, claim_mode,
        claim_owner, claimed_at_ms, lease_until_ms
        ON remote_merge_effect_attempt
WHEN NEW.merge_operation_id IS NOT OLD.merge_operation_id
  OR NEW.ordinal IS NOT OLD.ordinal
  OR NEW.effect_kind IS NOT OLD.effect_kind
  OR NEW.effect_ordinal IS NOT OLD.effect_ordinal
  OR NEW.readiness_evidence_id IS NOT OLD.readiness_evidence_id
  OR NEW.idempotency_key IS NOT OLD.idempotency_key
  OR NEW.attempt_key IS NOT OLD.attempt_key
  OR NEW.claim_mode IS NOT OLD.claim_mode
  OR NEW.claim_owner IS NOT OLD.claim_owner
  OR NEW.claimed_at_ms IS NOT OLD.claimed_at_ms
  OR NEW.lease_until_ms IS NOT OLD.lease_until_ms
BEGIN SELECT RAISE(ABORT, 'Merge effect attempt claim is immutable'); END;
CREATE TRIGGER remote_merge_effect_attempt_insert
BEFORE INSERT ON remote_merge_effect_attempt
WHEN NEW.status <> 'CLAIMED'
  OR NEW.attempt_key <> NEW.idempotency_key || ':attempt:' || NEW.ordinal
  OR NEW.observed_snapshot_id IS NOT NULL OR NEW.external_effect_id IS NOT NULL
  OR NEW.evidence IS NOT NULL OR NEW.last_error IS NOT NULL
  OR NEW.completed_at_ms IS NOT NULL
  OR NOT EXISTS (
      SELECT 1 FROM remote_merge_operation operation
      JOIN remote_merge_authorization authorization
        ON authorization.id = operation.merge_authorization_id
      JOIN remote_development_stage remote
        ON remote.stage_id = operation.remote_development_stage_id
      JOIN tasks task ON task.id = operation.task_id
      WHERE operation.id = NEW.merge_operation_id
        AND authorization.status = 'CONSUMED'
        AND operation.status IN ('REQUESTED', 'CLAIMED', 'AWAITING_OBSERVATION')
        AND NEW.ordinal = operation.attempt_count + 1
        AND NEW.ordinal <= operation.attempt_limit
        AND remote.current_head_sha = operation.head_sha
        AND remote.current_base_sha = operation.base_sha
        AND task.epoch = operation.task_epoch)
BEGIN SELECT RAISE(ABORT, 'Merge effect attempt lacks a current consumed operation claim'); END;
CREATE TRIGGER remote_merge_effect_attempt_probe
BEFORE INSERT ON remote_merge_effect_attempt
WHEN NEW.claim_mode = 'PROBE'
  AND NOT EXISTS (
      SELECT 1 FROM remote_merge_effect_attempt previous
      JOIN remote_merge_operation operation
        ON operation.id = previous.merge_operation_id
      WHERE previous.merge_operation_id = NEW.merge_operation_id
        AND previous.ordinal = NEW.ordinal - 1
        AND previous.effect_kind = NEW.effect_kind
        AND previous.effect_ordinal IS NEW.effect_ordinal
        AND previous.readiness_evidence_id = NEW.readiness_evidence_id
        AND previous.idempotency_key = NEW.idempotency_key
        AND operation.status IN ('CLAIMED', 'AWAITING_OBSERVATION')
        AND (previous.status = 'INDETERMINATE'
          OR (previous.status IN ('CLAIMED', 'AWAITING_OBSERVATION')
              AND NEW.claimed_at_ms >= previous.lease_until_ms)))
BEGIN SELECT RAISE(ABORT, 'Merge recovery must probe the expired or indeterminate effect'); END;
CREATE TRIGGER remote_merge_effect_attempt_result_fields
BEFORE UPDATE OF observed_snapshot_id, external_effect_id, evidence,
        last_error, completed_at_ms ON remote_merge_effect_attempt
WHEN NEW.status IS OLD.status
  AND (NEW.observed_snapshot_id IS NOT OLD.observed_snapshot_id
    OR NEW.external_effect_id IS NOT OLD.external_effect_id
    OR NEW.evidence IS NOT OLD.evidence
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
BEGIN SELECT RAISE(ABORT, 'Merge effect result changes only with its status transition'); END;
CREATE TRIGGER remote_merge_effect_attempt_success
BEFORE UPDATE OF status ON remote_merge_effect_attempt
WHEN NEW.status = 'SUCCEEDED'
  AND NOT EXISTS (
      SELECT 1 FROM remote_pr_snapshot snapshot
      JOIN remote_merge_operation operation
        ON operation.id = NEW.merge_operation_id
      JOIN remote_development_stage remote
        ON remote.stage_id = operation.remote_development_stage_id
      WHERE snapshot.id = NEW.observed_snapshot_id
        AND snapshot.remote_development_stage_id = operation.remote_development_stage_id
        AND snapshot.task_id = operation.task_id
        AND snapshot.stage_generation = operation.stage_generation
        AND snapshot.head_sha = operation.head_sha
        AND snapshot.base_sha = operation.base_sha
        AND remote.accepted_snapshot_id = snapshot.id
        AND remote.current_head_sha = operation.head_sha
        AND remote.current_base_sha = operation.base_sha
        AND ((NEW.effect_kind = 'DIRECT_MERGE' AND snapshot.pr_state = 'MERGED')
          OR (NEW.effect_kind = 'ENTER_QUEUE'
              AND snapshot.pr_state = 'OPEN'
              AND snapshot.merge_queue_state = 'QUEUED')))
BEGIN SELECT RAISE(ABORT, 'Merge effect completion lacks exact observed remote truth'); END;
CREATE TRIGGER remote_merge_effect_attempt_terminal_immutable
BEFORE UPDATE ON remote_merge_effect_attempt
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE')
 AND NOT (OLD.status = 'FAILED' AND NEW.status = 'INDETERMINATE'
    AND OLD.last_error = 'merge dispatch cancellation requested'
    AND EXISTS (
        SELECT 1
        FROM remote_merge_operation operation
        JOIN stage_resume_async_successor_v272 resume
          ON resume.owner_id = operation.id
         AND resume.operation_id = operation.operation_id
        JOIN stage_resume_rearm_intent_v257 intent
          ON intent.handoff_id = resume.handoff_id
        WHERE operation.id = OLD.merge_operation_id
          AND operation.status = 'CANCELED'
          AND resume.status = 'PREPARED'
          AND resume.owner_kind = 'MERGE_RECOVERY'
          AND intent.status = 'PENDING'))
BEGIN SELECT RAISE(ABORT, 'Terminal merge effect attempt is immutable'); END;
CREATE TRIGGER remote_merge_effect_attempt_transition
BEFORE UPDATE OF status ON remote_merge_effect_attempt
WHEN NEW.status IS NOT OLD.status
  AND NOT ((OLD.status = 'CLAIMED'
              AND NEW.status IN ('AWAITING_OBSERVATION', 'SUCCEEDED',
                  'FAILED', 'INDETERMINATE'))
        OR (OLD.status = 'AWAITING_OBSERVATION'
              AND NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE'))
        OR (OLD.status = 'FAILED' AND NEW.status = 'INDETERMINATE'
              AND OLD.last_error = 'merge dispatch cancellation requested'
              AND EXISTS (
                  SELECT 1
                  FROM remote_merge_operation operation
                  JOIN stage_resume_async_successor_v272 resume
                    ON resume.owner_id = operation.id
                   AND resume.operation_id = operation.operation_id
                  JOIN stage_resume_rearm_intent_v257 intent
                    ON intent.handoff_id = resume.handoff_id
                  WHERE operation.id = OLD.merge_operation_id
                    AND operation.status = 'CANCELED'
                    AND resume.status = 'PREPARED'
                    AND resume.owner_kind = 'MERGE_RECOVERY'
                    AND intent.status = 'PENDING')))
BEGIN SELECT RAISE(ABORT, 'Merge effect attempt transition is invalid'); END;
CREATE TRIGGER remote_merge_operation_attempt
BEFORE UPDATE OF attempt_count ON remote_merge_operation
WHEN NEW.status <> 'CLAIMED'
  OR NEW.attempt_count <> OLD.attempt_count + 1
BEGIN SELECT RAISE(ABORT, 'Merge operation attempt must be an exact committed claim'); END;
CREATE TRIGGER remote_merge_operation_blocked
BEFORE UPDATE OF status ON remote_merge_operation
WHEN NEW.status = 'BLOCKED'
  AND (NOT EXISTS (
        SELECT 1 FROM task_blocker blocker
        WHERE blocker.task_id = NEW.task_id
          AND blocker.stage_id = NEW.remote_development_stage_id
          AND blocker.owner_kind = 'OPERATION'
          AND blocker.owner_id = NEW.id
          AND blocker.subject_revision = NEW.head_sha
          AND blocker.status = 'OPEN')
    OR (NEW.block_reason = 'QUEUE_REENQUEUE_EXHAUSTED'
        AND NOT EXISTS (
            SELECT 1 FROM remote_merge_queue_entry entry
            WHERE entry.merge_operation_id = NEW.id
              AND entry.ordinal = NEW.max_queue_reenqueues + 1
              AND entry.status = 'BOUNCED')))
BEGIN SELECT RAISE(ABORT, 'Blocked merge operation lacks its exact durable blocker'); END;
CREATE TRIGGER remote_merge_operation_bounce_monotonic
BEFORE UPDATE OF queue_bounce_count ON remote_merge_operation
WHEN NEW.queue_bounce_count < OLD.queue_bounce_count
  OR NEW.queue_bounce_count > OLD.queue_bounce_count + 1
  OR (NEW.queue_bounce_count = OLD.queue_bounce_count + 1
    AND (NEW.mode <> 'MERGE_QUEUE' OR NOT EXISTS (
        SELECT 1 FROM remote_merge_queue_entry entry
        WHERE entry.merge_operation_id = NEW.id
          AND entry.ordinal = NEW.queue_bounce_count
          AND entry.status = 'BOUNCED')))
BEGIN SELECT RAISE(ABORT, 'Merge queue bounce count must advance by at most one'); END;
CREATE TRIGGER remote_merge_operation_claim
BEFORE UPDATE OF status ON remote_merge_operation
WHEN NEW.status = 'CLAIMED'
  AND (NEW.attempt_count <> OLD.attempt_count + 1
    OR NOT EXISTS (
      SELECT 1 FROM remote_merge_effect_attempt attempt
      WHERE attempt.merge_operation_id = NEW.id
        AND attempt.ordinal = NEW.attempt_count
        AND attempt.status = 'CLAIMED'
        AND attempt.ordinal = (
            SELECT MAX(latest.ordinal)
            FROM remote_merge_effect_attempt latest
            WHERE latest.merge_operation_id = NEW.id))
    OR NOT EXISTS (
      SELECT 1 FROM remote_merge_authorization authorization
      JOIN remote_development_stage remote
        ON remote.stage_id = authorization.remote_development_stage_id
      JOIN tasks task ON task.id = authorization.task_id
      WHERE authorization.id = NEW.merge_authorization_id
        AND authorization.status = 'CONSUMED'
        AND authorization.head_sha = NEW.head_sha
        AND authorization.base_sha = NEW.base_sha
        AND remote.current_head_sha = NEW.head_sha
        AND remote.current_base_sha = NEW.base_sha
        AND task.epoch = NEW.task_epoch))
BEGIN SELECT RAISE(ABORT, 'Merge operation claim is stale or lacks consumed consent'); END;
CREATE TRIGGER remote_merge_operation_identity_immutable
BEFORE UPDATE OF merge_authorization_id, remote_development_stage_id,
        task_id, task_epoch, stage_generation, operation_id, semantic_attempt,
        head_sha, base_sha, mode, merge_queue_capability,
        attempt_limit, max_queue_reenqueues, requested_at_ms
        ON remote_merge_operation
WHEN NEW.merge_authorization_id IS NOT OLD.merge_authorization_id
  OR NEW.remote_development_stage_id IS NOT OLD.remote_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.base_sha IS NOT OLD.base_sha
  OR NEW.mode IS NOT OLD.mode
  OR NEW.merge_queue_capability IS NOT OLD.merge_queue_capability
  OR NEW.attempt_limit IS NOT OLD.attempt_limit
  OR NEW.max_queue_reenqueues IS NOT OLD.max_queue_reenqueues
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'Merge operation subject is immutable'); END;
CREATE TRIGGER remote_merge_operation_insert
BEFORE INSERT ON remote_merge_operation
WHEN NOT EXISTS (
    SELECT 1 FROM remote_merge_authorization authorization
    JOIN remote_development_stage remote
      ON remote.stage_id = authorization.remote_development_stage_id
    JOIN task_automation_policy policy
      ON policy.id = authorization.automation_policy_id
    JOIN remote_readiness_evidence readiness
      ON readiness.id = authorization.readiness_evidence_id
    WHERE authorization.id = NEW.merge_authorization_id
      AND NEW.status = 'REQUESTED'
      AND NEW.attempt_count = 0
      AND NEW.queue_bounce_count = 0
      AND NEW.terminal_observation_id IS NULL
      AND authorization.status = 'ACTIVE'
      AND authorization.remote_development_stage_id =
            NEW.remote_development_stage_id
      AND authorization.task_id = NEW.task_id
      AND authorization.task_epoch = NEW.task_epoch
      AND authorization.stage_generation = NEW.stage_generation
      AND authorization.head_sha = NEW.head_sha
      AND authorization.base_sha = NEW.base_sha
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND remote.accepted_snapshot_id = readiness.remote_pr_snapshot_id
      AND readiness.merge_queue_capability = NEW.merge_queue_capability
      AND NEW.max_queue_reenqueues = CASE WHEN NEW.mode = 'MERGE_QUEUE'
          THEN policy.max_merge_queue_reenqueues ELSE 0 END)
BEGIN SELECT RAISE(ABORT, 'Merge operation lacks active exact-head authorization'); END;
CREATE TRIGGER remote_merge_operation_method_immutable_v274
BEFORE UPDATE OF merge_method ON remote_merge_operation
WHEN NEW.merge_method IS NOT OLD.merge_method
BEGIN SELECT RAISE(ABORT, 'Merge operation method is immutable'); END;
CREATE TRIGGER remote_merge_operation_method_insert_v274
BEFORE INSERT ON remote_merge_operation
WHEN NOT EXISTS (
    SELECT 1 FROM remote_merge_authorization authorization
    WHERE authorization.id = NEW.merge_authorization_id
      AND authorization.merge_method = NEW.merge_method)
BEGIN SELECT RAISE(ABORT, 'Merge operation method differs from authorization'); END;
CREATE TRIGGER remote_merge_operation_queue_entered
BEFORE UPDATE OF status ON remote_merge_operation
WHEN NEW.status = 'QUEUE_ENTERED'
  AND (NEW.mode <> 'MERGE_QUEUE' OR NOT EXISTS (
      SELECT 1 FROM remote_merge_queue_entry entry
      JOIN remote_merge_effect_attempt attempt
        ON attempt.id = entry.merge_effect_attempt_id
      WHERE entry.merge_operation_id = NEW.id
        AND entry.ordinal = NEW.queue_bounce_count + 1
        AND entry.status = 'ENTERED'
        AND attempt.merge_operation_id = NEW.id
        AND attempt.ordinal = NEW.attempt_count
        AND attempt.status = 'SUCCEEDED'))
BEGIN SELECT RAISE(ABORT, 'Merge queue operation lacks its current entered fact'); END;
CREATE TRIGGER remote_merge_operation_success
BEFORE UPDATE OF status ON remote_merge_operation
WHEN NEW.status = 'SUCCEEDED'
  AND (NOT EXISTS (
      SELECT 1 FROM remote_terminal_observation terminal
      WHERE terminal.id = NEW.terminal_observation_id
        AND terminal.remote_development_stage_id =
            NEW.remote_development_stage_id
        AND terminal.task_id = NEW.task_id
        AND terminal.task_epoch = NEW.task_epoch
        AND terminal.stage_generation = NEW.stage_generation
        AND terminal.kind = 'MERGED'
        AND terminal.head_sha = NEW.head_sha)
    OR (NEW.mode = 'DIRECT' AND NOT EXISTS (
        SELECT 1 FROM remote_merge_effect_attempt attempt
        JOIN remote_terminal_observation terminal
          ON terminal.id = NEW.terminal_observation_id
        WHERE attempt.merge_operation_id = NEW.id
          AND attempt.ordinal = NEW.attempt_count
          AND attempt.effect_kind = 'DIRECT_MERGE'
          AND attempt.status = 'SUCCEEDED'
          AND attempt.observed_snapshot_id = terminal.remote_pr_snapshot_id))
    OR (NEW.mode = 'MERGE_QUEUE' AND NOT EXISTS (
        SELECT 1 FROM remote_merge_queue_entry entry
        JOIN remote_terminal_observation terminal
          ON terminal.id = NEW.terminal_observation_id
        WHERE entry.merge_operation_id = NEW.id
          AND entry.status = 'MERGED'
          AND entry.observed_snapshot_id = terminal.remote_pr_snapshot_id)))
BEGIN SELECT RAISE(ABORT, 'Merge completion requires observed merged truth'); END;
CREATE TRIGGER remote_merge_operation_terminal_immutable
BEFORE UPDATE ON remote_merge_operation
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'BLOCKED', 'CANCELED')
 AND NOT (OLD.status = 'CANCELED'
    AND NEW.status IN ('REQUESTED', 'AWAITING_OBSERVATION')
    AND EXISTS (
        SELECT 1 FROM stage_resume_async_successor_v272 resume
        JOIN stage_resume_rearm_intent_v257 intent
          ON intent.handoff_id = resume.handoff_id
        WHERE resume.status = 'PREPARED'
          AND resume.owner_kind = 'MERGE_RECOVERY'
          AND resume.owner_id = OLD.id
          AND resume.operation_id = OLD.operation_id
          AND intent.status = 'PENDING'))
BEGIN SELECT RAISE(ABORT, 'Terminal merge operation is immutable'); END;
CREATE TRIGGER remote_merge_operation_transition
BEFORE UPDATE OF status ON remote_merge_operation
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN ('CLAIMED', 'CANCELED'))
    OR (OLD.status = 'CLAIMED'
        AND NEW.status IN ('QUEUE_ENTERED', 'AWAITING_OBSERVATION',
            'FAILED', 'BLOCKED', 'CANCELED'))
    OR (OLD.status = 'QUEUE_ENTERED'
        AND NEW.status IN ('AWAITING_OBSERVATION', 'BLOCKED', 'CANCELED'))
    OR (OLD.status = 'AWAITING_OBSERVATION'
        AND NEW.status IN ('CLAIMED', 'QUEUE_ENTERED', 'SUCCEEDED',
            'FAILED', 'BLOCKED', 'CANCELED'))
    OR (OLD.status = 'CANCELED'
        AND NEW.status IN ('REQUESTED', 'AWAITING_OBSERVATION')
        AND NEW.completed_at_ms IS NULL AND NEW.block_reason IS NULL
        AND EXISTS (
            SELECT 1
            FROM stage_resume_async_successor_v272 resume
            JOIN stage_resume_rearm_intent_v257 intent
              ON intent.handoff_id = resume.handoff_id
            JOIN dispatch_ticket ticket ON ticket.id = resume.dispatch_ticket_id
            WHERE resume.status = 'PREPARED'
              AND resume.owner_kind = 'MERGE_RECOVERY'
              AND resume.owner_id = NEW.id
              AND resume.operation_id = NEW.operation_id
              AND intent.status = 'PENDING'
              AND ticket.operation_id = NEW.operation_id
              AND ticket.status = 'REQUESTED')))
BEGIN SELECT RAISE(ABORT, 'Merge operation transition is invalid'); END;
CREATE TRIGGER remote_merge_queue_entry_identity_immutable
BEFORE UPDATE OF merge_operation_id, merge_effect_attempt_id, ordinal,
        queue_entry_id, head_sha,
        entered_snapshot_id, readiness_evidence_id, entered_at_ms
        ON remote_merge_queue_entry
WHEN NEW.merge_operation_id IS NOT OLD.merge_operation_id
  OR NEW.merge_effect_attempt_id IS NOT OLD.merge_effect_attempt_id
  OR NEW.ordinal IS NOT OLD.ordinal
  OR NEW.queue_entry_id IS NOT OLD.queue_entry_id
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.entered_snapshot_id IS NOT OLD.entered_snapshot_id
  OR NEW.readiness_evidence_id IS NOT OLD.readiness_evidence_id
  OR NEW.entered_at_ms IS NOT OLD.entered_at_ms
BEGIN SELECT RAISE(ABORT, 'Merge queue entry identity is immutable'); END;
CREATE TRIGGER remote_merge_queue_entry_insert
BEFORE INSERT ON remote_merge_queue_entry
WHEN NOT EXISTS (
    SELECT 1 FROM remote_merge_operation operation
    JOIN remote_merge_authorization authorization
      ON authorization.id = operation.merge_authorization_id
    JOIN remote_merge_effect_attempt attempt
      ON attempt.id = NEW.merge_effect_attempt_id
    JOIN remote_pr_snapshot snapshot ON snapshot.id = NEW.entered_snapshot_id
    JOIN remote_readiness_evidence readiness
      ON readiness.id = NEW.readiness_evidence_id
    JOIN remote_development_stage remote
      ON remote.stage_id = operation.remote_development_stage_id
    WHERE operation.id = NEW.merge_operation_id
      AND operation.mode = 'MERGE_QUEUE'
      AND operation.status IN ('CLAIMED', 'AWAITING_OBSERVATION')
      AND operation.merge_queue_capability = 'SUPPORTED'
      AND NEW.status = 'ENTERED'
      AND operation.head_sha = NEW.head_sha
      AND attempt.merge_operation_id = operation.id
      AND attempt.ordinal = operation.attempt_count
      AND attempt.effect_kind = 'ENTER_QUEUE'
      AND attempt.effect_ordinal = NEW.ordinal
      AND attempt.readiness_evidence_id = NEW.readiness_evidence_id
      AND attempt.status IN ('CLAIMED', 'AWAITING_OBSERVATION')
      AND snapshot.remote_development_stage_id =
            operation.remote_development_stage_id
      AND snapshot.head_sha = NEW.head_sha
      AND snapshot.base_sha = operation.base_sha
      AND snapshot.pr_state = 'OPEN'
      AND snapshot.merge_queue_state = 'QUEUED'
      AND snapshot.merge_queue_capability = 'SUPPORTED'
      AND readiness.remote_development_stage_id = operation.remote_development_stage_id
      AND readiness.task_id = operation.task_id
      AND readiness.task_epoch = operation.task_epoch
      AND readiness.stage_generation = operation.stage_generation
      AND readiness.automation_policy_id = authorization.automation_policy_id
      AND readiness.head_sha = NEW.head_sha
      AND readiness.base_sha = operation.base_sha
      AND readiness.merge_queue_capability = 'SUPPORTED'
      AND readiness.ready = 1
      AND remote.accepted_snapshot_id = snapshot.id
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = operation.base_sha
      AND NEW.ordinal = COALESCE((
          SELECT MAX(entry.ordinal) + 1 FROM remote_merge_queue_entry entry
          WHERE entry.merge_operation_id = operation.id), 1)
      AND NEW.ordinal <= operation.max_queue_reenqueues + 1
      AND operation.queue_bounce_count = NEW.ordinal - 1
      AND (NEW.ordinal = 1 OR EXISTS (
          SELECT 1 FROM remote_merge_queue_entry previous
          WHERE previous.merge_operation_id = operation.id
            AND previous.ordinal = NEW.ordinal - 1
            AND previous.status = 'BOUNCED')))
BEGIN SELECT RAISE(ABORT, 'Merge queue entry exceeds consent or lacks bounce proof'); END;
CREATE TRIGGER remote_merge_queue_entry_observation
BEFORE UPDATE OF status, observed_snapshot_id, observed_at_ms
        ON remote_merge_queue_entry
WHEN NEW.status <> 'ENTERED'
  AND (OLD.status <> 'ENTERED'
    OR NEW.status NOT IN ('BOUNCED', 'MERGED', 'REMOVED')
    OR NOT EXISTS (
      SELECT 1 FROM remote_pr_snapshot snapshot
      JOIN remote_merge_operation operation
        ON operation.id = NEW.merge_operation_id
      JOIN remote_development_stage remote
        ON remote.stage_id = operation.remote_development_stage_id
      WHERE snapshot.id = NEW.observed_snapshot_id
        AND snapshot.remote_development_stage_id =
            operation.remote_development_stage_id
        AND snapshot.head_sha = NEW.head_sha
        AND snapshot.base_sha = operation.base_sha
        AND remote.accepted_snapshot_id = snapshot.id
        AND remote.current_head_sha = NEW.head_sha
        AND remote.current_base_sha = operation.base_sha
        AND NEW.observed_at_ms = snapshot.observed_at_ms
        AND ((NEW.status = 'BOUNCED'
                AND snapshot.pr_state = 'OPEN'
                AND snapshot.merge_queue_state = 'DEQUEUED')
          OR (NEW.status = 'MERGED'
                AND snapshot.pr_state = 'MERGED'
                AND snapshot.merge_queue_state IN ('NONE', 'MERGED'))
          OR (NEW.status = 'REMOVED'
                AND snapshot.pr_state = 'OPEN'
                AND snapshot.merge_queue_state = 'NONE'))))
BEGIN SELECT RAISE(ABORT, 'Merge queue outcome lacks exact observed remote truth'); END;
CREATE TRIGGER remote_merge_queue_entry_terminal_immutable
BEFORE UPDATE ON remote_merge_queue_entry
WHEN OLD.status IN ('BOUNCED', 'MERGED', 'REMOVED')
BEGIN SELECT RAISE(ABORT, 'Terminal merge queue entry is immutable'); END;
CREATE TRIGGER remote_observation_delivery_receipt_immutable
BEFORE UPDATE ON remote_observation_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Remote observation delivery receipt is immutable'); END;
CREATE TRIGGER remote_observation_delivery_receipt_insert
BEFORE INSERT ON remote_observation_delivery_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_observation_operation operation
    JOIN dispatch_ticket ticket ON ticket.operation_id = operation.operation_id
    WHERE operation.id = NEW.remote_observation_operation_id
      AND operation.operation_id = NEW.operation_id
      AND operation.status IN ('ACCEPTED', 'SUPERSEDED', 'FAILED', 'CANCELED')
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = NEW.raw_outcome
      AND (NEW.snapshot_id IS NULL OR operation.snapshot_id = NEW.snapshot_id)
      AND (NEW.ci_evaluation_id IS NULL
          OR operation.ci_evaluation_id = NEW.ci_evaluation_id))
BEGIN SELECT RAISE(ABORT, 'Remote observation delivery receipt is not exact'); END;
CREATE TRIGGER remote_observation_operation_dispatched
BEFORE UPDATE OF status ON remote_observation_operation
WHEN NEW.status = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1 FROM dispatch_ticket ticket
    WHERE ticket.operation_id = NEW.operation_id
      AND ticket.operation_kind = 'OBSERVE_REMOTE_PR'
      AND ticket.async_family = 'REMOTE_OBSERVATION'
      AND ticket.owner_kind = 'STAGE'
      AND ticket.owner_id = NEW.remote_development_stage_id
      AND ticket.callback_route = 'REMOTE_OBSERVATION_RESULT'
      AND ticket.task_id = NEW.task_id
      AND ticket.task_epoch = NEW.task_epoch
      AND ticket.stage_id = NEW.remote_development_stage_id
      AND ticket.stage_generation = NEW.stage_generation
      AND ticket.attempt = NEW.semantic_attempt
      AND ticket.expected_head_sha = NEW.expected_head_sha
      AND ticket.expected_base_sha = NEW.expected_base_sha
      AND ticket.lane_mask = 64
      AND ticket.trunk_control = 0
      AND ticket.exclusive_task = 0
      AND ticket.writer_required = 0
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Remote observation lacks its exact DispatchTicket'); END;
CREATE TRIGGER remote_observation_operation_identity_immutable
BEFORE UPDATE OF id, remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_binding_id, ci_policy_revision_id,
        operation_id, semantic_attempt, expected_head_sha, expected_base_sha,
        requested_at_ms ON remote_observation_operation
BEGIN SELECT RAISE(ABORT, 'Remote observation operation identity is immutable'); END;
CREATE TRIGGER remote_observation_operation_insert
BEFORE INSERT ON remote_observation_operation
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_development_stage remote
    JOIN stage owner ON owner.id = remote.stage_id
    JOIN tasks task ON task.id = remote.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN remote_ci_policy_revision policy
      ON policy.id = NEW.ci_policy_revision_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND remote.current_head_sha = NEW.expected_head_sha
      AND remote.current_base_sha = NEW.expected_base_sha
      AND owner.completed_at_ms IS NULL
      AND current.stage_id = remote.stage_id
      AND current.stage_generation = remote.generation
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND policy.task_id = NEW.task_id
      AND policy.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND NEW.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Remote observation requires the current exact subject'); END;
CREATE TRIGGER remote_observation_operation_status
BEFORE UPDATE OF status ON remote_observation_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'ACCEPTED', 'SUPERSEDED', 'FAILED', 'CANCELED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'ACCEPTED', 'SUPERSEDED', 'FAILED', 'CANCELED')))
BEGIN SELECT RAISE(ABORT, 'Remote observation status transition is invalid'); END;
CREATE TRIGGER remote_observation_stage_receipt_delete
BEFORE DELETE ON remote_observation_stage_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN
    SELECT RAISE(ABORT, 'Remote observation Stage receipt cannot be deleted');
END;
CREATE TRIGGER remote_observation_stage_receipt_immutable
BEFORE UPDATE ON remote_observation_stage_receipt
BEGIN
    SELECT RAISE(ABORT, 'Remote observation Stage receipt is immutable');
END;
CREATE TRIGGER remote_observation_stage_receipt_insert
BEFORE INSERT ON remote_observation_stage_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM stage owner
    JOIN tasks task ON task.id = owner.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN remote_development_stage remote ON remote.stage_id = owner.id
    WHERE owner.id = NEW.stage_id
      AND owner.task_id = NEW.task_id
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = NEW.returned_generation
      AND owner.version = NEW.returned_version
      AND owner.checkpoint = NEW.returned_checkpoint
      AND owner.completed_at_ms IS NULL
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.expected_task_epoch
      AND current.stage_id = owner.id
      AND current.stage_generation = owner.generation
      AND NEW.expected_stage_generation = owner.generation
      AND NEW.returned_generation = owner.generation
      AND (
        (NEW.cause = 'ACCEPT_REMOTE_CI' AND EXISTS (
            SELECT 1 FROM remote_ci_evaluation ci
            WHERE ci.id = NEW.proof_id
              AND ci.task_id = NEW.task_id
              AND ci.task_epoch = NEW.expected_task_epoch
              AND ci.remote_development_stage_id = owner.id
              AND ci.stage_generation = owner.generation
              AND ci.policy_outcome = 'ACCEPTED'
              AND ci.remote_pr_snapshot_id = remote.accepted_snapshot_id
              AND ci.head_sha = remote.current_head_sha
              AND ci.base_sha = remote.current_base_sha))
        OR (NEW.cause = 'ACCEPT_OBSERVED_READY' AND EXISTS (
            SELECT 1 FROM remote_pr_snapshot snapshot
            JOIN remote_ci_evaluation ci
              ON ci.remote_pr_snapshot_id = snapshot.id
             AND ci.policy_outcome = 'ACCEPTED'
            WHERE snapshot.id = NEW.proof_id
              AND snapshot.task_id = NEW.task_id
              AND snapshot.task_epoch = NEW.expected_task_epoch
              AND snapshot.remote_development_stage_id = owner.id
              AND snapshot.stage_generation = owner.generation
              AND snapshot.pr_state = 'OPEN'
              AND remote.accepted_snapshot_id = snapshot.id
              AND remote.current_head_sha = snapshot.head_sha
              AND remote.current_base_sha = snapshot.base_sha))
        OR (NEW.cause = 'ACCEPT_REMOTE_HEAD_CHANGE' AND EXISTS (
            SELECT 1 FROM remote_pr_snapshot snapshot
            JOIN remote_head_evidence_invalidation invalidation
              ON invalidation.remote_development_stage_id = owner.id
             AND invalidation.accepted_snapshot_id = snapshot.id
            WHERE snapshot.id = NEW.proof_id
              AND snapshot.task_id = NEW.task_id
              AND snapshot.task_epoch = NEW.expected_task_epoch
              AND snapshot.remote_development_stage_id = owner.id
              AND snapshot.stage_generation = owner.generation
              AND remote.accepted_snapshot_id = snapshot.id
              AND remote.current_head_sha = snapshot.head_sha
              AND remote.current_base_sha = snapshot.base_sha)))
      AND (NEW.disposition = 'SUPERSEDED' OR EXISTS (
          SELECT 1 FROM stage_transition transition
          WHERE transition.stage_id = NEW.stage_id
            AND transition.command_id = NEW.command_id
            AND transition.generation = NEW.returned_generation
            AND transition.stage_version = NEW.returned_version
            AND transition.cause = NEW.cause
            AND transition.actor = NEW.actor
            AND transition.from_checkpoint = NEW.source_checkpoint
            AND transition.to_checkpoint = NEW.returned_checkpoint))
)
BEGIN
    SELECT RAISE(ABORT,
        'Remote observation Stage receipt lacks exact current owner proof');
END;
CREATE TRIGGER remote_policy_stage_receipt_v268_immutable
BEFORE UPDATE ON remote_policy_stage_receipt_v268
BEGIN SELECT RAISE(ABORT, 'Remote policy readiness receipt is immutable'); END;
CREATE TRIGGER remote_policy_stage_receipt_v268_insert
BEFORE INSERT ON remote_policy_stage_receipt_v268
WHEN NOT EXISTS (
    SELECT 1
    FROM stage owner
    JOIN tasks task ON task.id = owner.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN remote_development_stage remote ON remote.stage_id = owner.id
    JOIN remote_readiness_evidence readiness ON readiness.id = NEW.proof_id
    JOIN task_automation_policy policy
      ON policy.id = readiness.automation_policy_id
    JOIN stage_transition transition
      ON transition.stage_id = owner.id
     AND transition.command_id = NEW.command_id
    WHERE owner.id = NEW.stage_id
      AND owner.task_id = NEW.task_id
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = NEW.returned_generation
      AND owner.version = NEW.returned_version
      AND owner.checkpoint = 'WAITING_REMOTE_REVIEW'
      AND owner.completed_at_ms IS NULL
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.expected_task_epoch
      AND current.stage_id = owner.id
      AND current.stage_generation = owner.generation
      AND NEW.expected_stage_generation = owner.generation
      AND remote.generation = owner.generation
      AND remote.accepted_snapshot_id = readiness.remote_pr_snapshot_id
      AND remote.current_head_sha = readiness.head_sha
      AND remote.current_base_sha = readiness.base_sha
      AND readiness.task_id = task.id
      AND readiness.task_epoch = task.epoch
      AND readiness.stage_generation = owner.generation
      AND readiness.ready = 0
      AND policy.task_id = task.id
      AND policy.revision = (
          SELECT MAX(current_policy.revision)
          FROM task_automation_policy current_policy
          WHERE current_policy.task_id = task.id)
      AND transition.generation = owner.generation
      AND transition.from_checkpoint = 'READY_TO_MERGE'
      AND transition.to_checkpoint = 'WAITING_REMOTE_REVIEW'
      AND transition.stage_version = owner.version
      AND transition.cause = NEW.cause
      AND transition.actor = NEW.actor)
BEGIN SELECT RAISE(ABORT,
    'Remote policy readiness receipt lacks exact current-policy evidence'); END;
CREATE TRIGGER remote_pr_binding_immutable
BEFORE UPDATE ON remote_pr_binding
BEGIN SELECT RAISE(ABORT, 'RemotePrBinding is immutable'); END;
CREATE TRIGGER remote_pr_binding_insert
BEFORE INSERT ON remote_pr_binding
WHEN NOT EXISTS (
    SELECT 1
    FROM publish_operation operation
    JOIN publish_authorization authorization
      ON authorization.id = operation.publish_authorization_id
    JOIN promotion_manifest manifest ON manifest.id = authorization.manifest_id
    JOIN pr p ON p.id = authorization.pr_id
    WHERE operation.id = NEW.publish_operation_id
      AND operation.status = 'SUCCEEDED'
      AND operation.publish_authorization_id = NEW.publish_authorization_id
      AND authorization.manifest_id = NEW.manifest_id
      AND authorization.task_id = NEW.task_id
      AND authorization.pr_id = NEW.pr_id
      AND authorization.route = NEW.route
      AND authorization.base_repository_id = NEW.base_repository_id
      AND authorization.head_repository_id = NEW.head_repository_id
      AND authorization.head_ref = NEW.remote_head_ref
      AND authorization.head_sha = NEW.remote_head_sha
      AND authorization.base_sha = NEW.remote_base_sha
      AND manifest.task_id = NEW.task_id AND manifest.pr_id = NEW.pr_id
      AND manifest.route = NEW.route
      AND manifest.base_repository_id = NEW.base_repository_id
      AND manifest.head_repository_id = NEW.head_repository_id
      AND p.task_id = NEW.task_id AND p.origin = 'task'
      AND operation.remote_repository_id = NEW.remote_repository_id
      AND operation.remote_repository_id = NEW.base_repository_id
      AND operation.remote_pr_number = NEW.remote_pr_number
      AND operation.remote_pr_url = NEW.remote_pr_url
      AND operation.remote_head_ref = NEW.remote_head_ref
      AND operation.remote_head_sha = NEW.remote_head_sha
      AND operation.remote_base_sha = NEW.remote_base_sha)
BEGIN SELECT RAISE(ABORT, 'RemotePrBinding does not match exact successful publish proof'); END;
CREATE TRIGGER remote_pr_snapshot_immutable
BEFORE UPDATE ON remote_pr_snapshot
BEGIN SELECT RAISE(ABORT, 'Remote PR snapshot is immutable'); END;
CREATE TRIGGER remote_pr_snapshot_insert
BEFORE INSERT ON remote_pr_snapshot
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM remote_development_stage remote
            JOIN tasks task ON task.id = remote.task_id
            JOIN remote_pr_binding binding ON binding.id = remote.remote_pr_binding_id
            WHERE remote.stage_id = NEW.remote_development_stage_id
              AND remote.task_id = NEW.task_id
              AND remote.generation = NEW.stage_generation
              AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
              AND task.epoch = NEW.task_epoch
              AND binding.remote_repository_id = NEW.remote_repository_id
              AND binding.remote_pr_number = NEW.remote_pr_number)
            THEN RAISE(ABORT, 'Remote snapshot owner and binding fence is invalid')
        WHEN NEW.observation_revision <> COALESCE((
            SELECT MAX(snapshot.observation_revision) + 1
            FROM remote_pr_snapshot snapshot
            WHERE snapshot.remote_development_stage_id =
                NEW.remote_development_stage_id), 1)
            THEN RAISE(ABORT, 'Remote snapshot observation revision must be next')
        WHEN NEW.pr_state = 'MERGED' AND NEW.merge_queue_state NOT IN ('NONE', 'MERGED')
            THEN RAISE(ABORT, 'Merged snapshot has invalid queue state')
    END;
END;
CREATE TRIGGER remote_readiness_assistance_attempt_v273
BEFORE UPDATE OF attempt_count ON remote_readiness_assistance_v273
WHEN NOT (NEW.status = 'CLAIMED'
    AND ((OLD.status = 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count
            AND NEW.claim_mode = 'PROBE'
            AND NEW.claimed_at_ms >= OLD.lease_until_ms)
        OR (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
            AND NEW.attempt_count = OLD.attempt_count + 1)))
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance attempt must be an exact claim'); END;
CREATE TRIGGER remote_readiness_assistance_claim_fields_v273
BEFORE UPDATE OF claim_mode, claim_owner, claimed_at_ms, lease_until_ms
        ON remote_readiness_assistance_v273
WHEN NOT ((NEW.status = 'CLAIMED'
            AND ((OLD.status = 'CLAIMED'
                    AND NEW.attempt_count = OLD.attempt_count
                    AND NEW.claim_mode = 'PROBE'
                    AND NEW.claimed_at_ms >= OLD.lease_until_ms)
                OR (OLD.status IN (
                        'REQUESTED', 'FAILED', 'INDETERMINATE')
                    AND NEW.attempt_count = OLD.attempt_count + 1)))
        OR (OLD.status = 'CLAIMED' AND NEW.status <> 'CLAIMED'
            AND NEW.attempt_count = OLD.attempt_count
            AND NEW.claim_mode IS NULL AND NEW.claim_owner IS NULL
            AND NEW.claimed_at_ms IS NULL AND NEW.lease_until_ms IS NULL))
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance claim fields change only with an attempt'); END;
CREATE TRIGGER remote_readiness_assistance_claim_v273
BEFORE UPDATE OF status ON remote_readiness_assistance_v273
WHEN NEW.status = 'CLAIMED'
  AND (NOT ((OLD.status = 'CLAIMED'
                AND NEW.attempt_count = OLD.attempt_count
                AND NEW.claim_mode = 'PROBE'
                AND NEW.claimed_at_ms >= OLD.lease_until_ms)
            OR (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
                AND NEW.attempt_count = OLD.attempt_count + 1))
    OR NEW.attempt_count > OLD.attempt_limit
    OR OLD.status NOT IN (
        'REQUESTED', 'CLAIMED', 'FAILED', 'INDETERMINATE')
    OR (OLD.status = 'INDETERMINATE' AND NEW.claim_mode <> 'PROBE')
    OR (OLD.status NOT IN ('CLAIMED', 'INDETERMINATE')
        AND NEW.claim_mode <> 'EXECUTE')
    OR NEW.external_effect_id IS NOT NULL OR NEW.evidence IS NOT NULL
    OR NEW.last_error IS NOT NULL OR NEW.completed_at_ms IS NOT NULL
    OR NOT EXISTS (
        SELECT 1
        FROM tasks task
        JOIN task_current_stage current ON current.task_id = task.id
        JOIN stage owner ON owner.id = current.stage_id
        JOIN remote_development_stage remote ON remote.stage_id = owner.id
        JOIN remote_pr_binding binding
          ON binding.id = remote.remote_pr_binding_id
        JOIN remote_pr_snapshot snapshot
          ON snapshot.id = remote.accepted_snapshot_id
        JOIN remote_readiness_evidence readiness
          ON readiness.id = NEW.readiness_evidence_id
        JOIN task_automation_policy policy
          ON policy.id = NEW.automation_policy_id
        WHERE task.id = NEW.task_id
          AND task.workflow_version = 'V2'
          AND task.lifecycle_state = 'ACTIVE'
          AND task.epoch = NEW.task_epoch
          AND current.stage_id = NEW.remote_stage_id
          AND current.stage_generation = NEW.stage_generation
          AND owner.id = NEW.remote_stage_id
          AND owner.task_id = task.id
          AND owner.kind = 'REMOTE_DEVELOPMENT'
          AND owner.generation = NEW.stage_generation
          AND owner.checkpoint = 'READY_TO_MERGE'
          AND owner.completed_at_ms IS NULL
          AND remote.task_id = task.id
          AND remote.generation = owner.generation
          AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
          AND remote.accepted_snapshot_id = NEW.remote_pr_snapshot_id
          AND remote.current_head_sha = NEW.expected_head_sha
          AND remote.current_base_sha = NEW.expected_base_sha
          AND binding.task_id = task.id
          AND binding.remote_repository_id = NEW.remote_repository_id
          AND binding.head_repository_id = NEW.head_repository_id
          AND binding.remote_pr_number = NEW.remote_pr_number
          AND snapshot.task_id = task.id
          AND snapshot.task_epoch = task.epoch
          AND snapshot.remote_development_stage_id = owner.id
          AND snapshot.stage_generation = owner.generation
          AND snapshot.remote_pr_binding_id = binding.id
          AND snapshot.head_sha = NEW.expected_head_sha
          AND snapshot.base_sha = NEW.expected_base_sha
          AND snapshot.pr_state = 'OPEN'
          AND snapshot.viewer_login = NEW.authorized_by
          AND snapshot.viewer_can_merge = 0
          AND readiness.remote_development_stage_id = owner.id
          AND readiness.remote_pr_snapshot_id = snapshot.id
          AND readiness.task_id = task.id
          AND readiness.task_epoch = task.epoch
          AND readiness.stage_generation = owner.generation
          AND readiness.automation_policy_id = policy.id
          AND readiness.head_sha = NEW.expected_head_sha
          AND readiness.base_sha = NEW.expected_base_sha
          AND readiness.ready = 1
          AND policy.task_id = task.id
          AND policy.revision = (
              SELECT MAX(latest.revision)
              FROM task_automation_policy latest
              WHERE latest.task_id = task.id)))
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance claim is stale or no longer allowed'); END;
CREATE TRIGGER remote_readiness_assistance_delete_v273
BEFORE DELETE ON remote_readiness_assistance_v273
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id)
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance evidence cannot be deleted before purge'); END;
CREATE TRIGGER remote_readiness_assistance_dispatch_immutable_v273
BEFORE UPDATE ON remote_readiness_assistance_dispatch_v273
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance dispatch is immutable'); END;
CREATE TRIGGER remote_readiness_assistance_dispatch_insert_v273
BEFORE INSERT ON remote_readiness_assistance_dispatch_v273
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_readiness_assistance_v273 assistance
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    WHERE assistance.id = NEW.assistance_id
      AND assistance.operation_id = NEW.operation_id
      AND assistance.status = 'REQUESTED'
      AND ticket.operation_id = assistance.operation_id
      AND ticket.operation_kind = 'APPLY_READINESS_ASSISTANCE'
      AND ticket.callback_route = 'READINESS_ASSISTANCE_RESULT'
      AND ticket.owner_kind = 'STAGE'
      AND ticket.owner_id = assistance.remote_stage_id
      AND ticket.task_id = assistance.task_id
      AND ticket.task_epoch = assistance.task_epoch
      AND ticket.stage_id = assistance.remote_stage_id
      AND ticket.stage_generation = assistance.stage_generation
      AND ticket.expected_head_sha = assistance.expected_head_sha
      AND ticket.expected_base_sha = assistance.expected_base_sha
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance dispatch differs from its authorization'); END;
CREATE TRIGGER remote_readiness_assistance_exhaustion_v273
BEFORE UPDATE OF status ON remote_readiness_assistance_v273
WHEN OLD.status = 'CLAIMED'
  AND OLD.attempt_count >= OLD.attempt_limit
  AND NEW.status IN ('FAILED', 'INDETERMINATE')
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance exhaustion must become terminal'); END;
CREATE TRIGGER remote_readiness_assistance_identity_v273
BEFORE UPDATE OF id, command_id, operation_id, task_id, task_epoch,
        remote_stage_id, stage_generation, remote_pr_binding_id,
        remote_pr_snapshot_id, readiness_evidence_id, automation_policy_id,
        kind, external_target, payload, payload_digest, idempotency_key,
        remote_repository_id, head_repository_id, remote_pr_number,
        expected_head_sha, expected_base_sha, semantic_attempt, attempt_limit,
        authorized_by, authorized_at_ms ON remote_readiness_assistance_v273
BEGIN SELECT RAISE(ABORT, 'Readiness assistance identity is immutable'); END;
CREATE TRIGGER remote_readiness_assistance_insert_v273
BEFORE INSERT ON remote_readiness_assistance_v273
WHEN NEW.status <> 'REQUESTED' OR NEW.attempt_count <> 0 OR NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN threads trunk ON trunk.id = task.thread_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN remote_development_stage remote ON remote.stage_id = owner.id
    JOIN remote_pr_binding binding ON binding.id = remote.remote_pr_binding_id
    JOIN remote_pr_snapshot snapshot ON snapshot.id = remote.accepted_snapshot_id
    JOIN remote_readiness_evidence readiness
      ON readiness.id = NEW.readiness_evidence_id
    JOIN task_automation_policy policy ON policy.id = NEW.automation_policy_id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.remote_stage_id
      AND current.stage_generation = NEW.stage_generation
      AND owner.id = NEW.remote_stage_id
      AND owner.task_id = task.id
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = NEW.stage_generation
      AND owner.checkpoint = 'READY_TO_MERGE'
      AND owner.completed_at_ms IS NULL
      AND remote.task_id = task.id
      AND remote.generation = NEW.stage_generation
      AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND remote.accepted_snapshot_id = NEW.remote_pr_snapshot_id
      AND remote.current_head_sha = NEW.expected_head_sha
      AND remote.current_base_sha = NEW.expected_base_sha
      AND binding.task_id = task.id
      AND binding.remote_repository_id = NEW.remote_repository_id
      AND binding.head_repository_id = NEW.head_repository_id
      AND binding.remote_pr_number = NEW.remote_pr_number
      AND snapshot.task_id = task.id
      AND snapshot.task_epoch = task.epoch
      AND snapshot.remote_development_stage_id = owner.id
      AND snapshot.stage_generation = owner.generation
      AND snapshot.remote_pr_binding_id = binding.id
      AND snapshot.head_sha = NEW.expected_head_sha
      AND snapshot.base_sha = NEW.expected_base_sha
      AND snapshot.pr_state = 'OPEN'
      AND snapshot.viewer_login = NEW.authorized_by
      AND snapshot.viewer_can_merge = 0
      AND readiness.remote_development_stage_id = owner.id
      AND readiness.task_id = task.id
      AND readiness.task_epoch = task.epoch
      AND readiness.stage_generation = owner.generation
      AND readiness.remote_pr_snapshot_id = snapshot.id
      AND readiness.automation_policy_id = policy.id
      AND readiness.head_sha = NEW.expected_head_sha
      AND readiness.base_sha = NEW.expected_base_sha
      AND readiness.ready = 1
      AND policy.task_id = task.id
      AND policy.revision = (
          SELECT MAX(latest.revision)
          FROM task_automation_policy latest
          WHERE latest.task_id = task.id)
      AND NOT EXISTS (
          SELECT 1
          FROM remote_readiness_assistance_v273 prior
          WHERE prior.task_id = task.id
            AND prior.task_epoch = task.epoch
            AND prior.remote_stage_id = owner.id
            AND prior.stage_generation = owner.generation
            AND prior.remote_pr_snapshot_id = snapshot.id
            AND prior.automation_policy_id = policy.id
            AND prior.status IN (
                'REQUESTED', 'CLAIMED', 'SUCCEEDED', 'FAILED',
                'INDETERMINATE')))
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance lacks exact current manually approved authority'); END;
CREATE TRIGGER remote_readiness_assistance_receipt_immutable_v273
BEFORE UPDATE ON remote_readiness_assistance_receipt_v273
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance receipt is immutable'); END;
CREATE TRIGGER remote_readiness_assistance_receipt_insert_v273
BEFORE INSERT ON remote_readiness_assistance_receipt_v273
WHEN NOT EXISTS (
    SELECT 1
    FROM remote_readiness_assistance_v273 assistance
    JOIN remote_readiness_assistance_dispatch_v273 dispatch
      ON dispatch.assistance_id = assistance.id
    WHERE assistance.operation_id = NEW.operation_id
      AND dispatch.operation_id = assistance.operation_id)
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance receipt lacks its exact operation'); END;
CREATE TRIGGER remote_readiness_assistance_result_fields_v273
BEFORE UPDATE OF external_effect_id, evidence, last_error, completed_at_ms
        ON remote_readiness_assistance_v273
WHEN (NEW.external_effect_id IS NOT OLD.external_effect_id
    OR NEW.evidence IS NOT OLD.evidence
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
  AND NEW.status IS OLD.status
  AND NOT (NEW.status = 'CLAIMED'
    AND NEW.attempt_count = OLD.attempt_count + 1
    AND NEW.external_effect_id IS NULL AND NEW.evidence IS NULL
    AND NEW.last_error IS NULL AND NEW.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT,
    'Readiness assistance result changes only at a result boundary'); END;
CREATE TRIGGER remote_readiness_assistance_succeeded_immutable_v273
BEFORE UPDATE ON remote_readiness_assistance_v273
WHEN OLD.status IN ('SUCCEEDED', 'ABANDONED')
BEGIN SELECT RAISE(ABORT, 'Terminal readiness assistance is immutable'); END;
CREATE TRIGGER remote_readiness_assistance_transition_v273
BEFORE UPDATE OF status ON remote_readiness_assistance_v273
WHEN NEW.status IS NOT OLD.status
  AND NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status = 'CLAIMED')
    OR (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status = 'ABANDONED')
    OR (OLD.status = 'CLAIMED'
        AND NEW.status IN (
            'SUCCEEDED', 'FAILED', 'INDETERMINATE', 'ABANDONED')))
BEGIN SELECT RAISE(ABORT, 'Readiness assistance transition is invalid'); END;
CREATE TRIGGER remote_readiness_evidence_immutable
BEFORE UPDATE ON remote_readiness_evidence
BEGIN SELECT RAISE(ABORT, 'Readiness evidence is immutable'); END;
CREATE TRIGGER remote_readiness_evidence_insert
BEFORE INSERT ON remote_readiness_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM remote_development_stage remote
    JOIN tasks task ON task.id = remote.task_id
    JOIN remote_pr_snapshot snapshot ON snapshot.id = NEW.remote_pr_snapshot_id
    JOIN remote_ci_evaluation ci ON ci.id = NEW.ci_evaluation_id
    JOIN task_automation_policy policy ON policy.id = NEW.automation_policy_id
    WHERE remote.stage_id = NEW.remote_development_stage_id
      AND remote.task_id = NEW.task_id
      AND remote.generation = NEW.stage_generation
      AND remote.accepted_snapshot_id = NEW.remote_pr_snapshot_id
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND snapshot.remote_development_stage_id = remote.stage_id
      AND snapshot.task_id = NEW.task_id
      AND snapshot.head_sha = NEW.head_sha
      AND snapshot.base_sha = NEW.base_sha
      AND NEW.pr_open = CASE WHEN snapshot.pr_state = 'OPEN' THEN 1 ELSE 0 END
      AND NEW.non_draft = CASE WHEN snapshot.pr_state = 'OPEN' THEN 1 ELSE 0 END
      AND NEW.write_approval_count = snapshot.write_approval_count
      AND NEW.changes_requested_count = snapshot.changes_requested_count
      AND NEW.unresolved_thread_count = snapshot.unresolved_thread_count
      AND NEW.unresolved_comment_count = snapshot.unresolved_comment_count
      AND NEW.mergeability = snapshot.mergeability
      AND NEW.merge_queue_capability = snapshot.merge_queue_capability
      AND NEW.observed_at_ms = snapshot.observed_at_ms
      AND ci.remote_pr_snapshot_id = snapshot.id
      AND ci.head_sha = NEW.head_sha
      AND ci.base_sha = NEW.base_sha
      AND NEW.ci_accepted = CASE WHEN ci.policy_outcome = 'ACCEPTED' THEN 1 ELSE 0 END
      AND policy.task_id = NEW.task_id
      AND policy.revision = (
          SELECT MAX(current_policy.revision)
          FROM task_automation_policy current_policy
          WHERE current_policy.task_id = NEW.task_id)
      AND NEW.required_write_approval_count = policy.minimum_write_approvals
      AND NEW.low_risk_required = policy.require_low_risk
      AND NEW.small_effort_required = policy.require_small_effort
      AND ((policy.require_low_risk = 0 AND policy.require_small_effort = 0
                AND NEW.automation_eligibility_evidence_id IS NULL
                AND NEW.low_risk_eligible = 0
                AND NEW.small_effort_eligible = 0)
        OR EXISTS (
            SELECT 1 FROM task_automation_eligibility_evidence eligibility
            WHERE eligibility.id = NEW.automation_eligibility_evidence_id
              AND eligibility.task_id = NEW.task_id
              AND eligibility.task_epoch = NEW.task_epoch
              AND NEW.low_risk_eligible = eligibility.low_risk_eligible
              AND NEW.small_effort_eligible = eligibility.small_effort_eligible))
      AND NEW.open_feedback_batch_count = (
          SELECT COUNT(*) FROM remote_feedback_batch batch
          WHERE batch.remote_development_stage_id = remote.stage_id
            AND batch.head_sha = NEW.head_sha
            AND batch.status NOT IN ('COMPLETED', 'SUPERSEDED'))
      AND NEW.blocking_gate_count = (
          SELECT COUNT(*) FROM task_blocker blocker
          WHERE blocker.task_id = NEW.task_id
            AND (blocker.stage_id IS NULL OR blocker.stage_id = remote.stage_id)
            AND blocker.status = 'OPEN'))
BEGIN SELECT RAISE(ABORT, 'Readiness evidence does not match current exact-head truth'); END;
CREATE TRIGGER remote_repair_steering_delivery_immutable_v257
BEFORE UPDATE ON remote_repair_steering_delivery_v257
BEGIN SELECT RAISE(ABORT, 'Remote repair steering delivery is immutable'); END;
CREATE TRIGGER remote_repair_steering_turn_identity_v257
BEFORE UPDATE OF request_id, owner_family, ci_repair_episode_id,
        branch_sync_episode_id, branch_sync_step_id, stage_turn_id,
        operation_id, dispatch_ticket_id, semantic_attempt, requested_at_ms
ON remote_repair_steering_turn_v257
BEGIN SELECT RAISE(ABORT, 'Remote repair steering identity is immutable'); END;
CREATE TRIGGER remote_repair_steering_turn_insert_v257
BEFORE INSERT ON remote_repair_steering_turn_v257
WHEN NEW.status <> 'REQUESTED' OR NOT EXISTS (
    SELECT 1
    FROM remote_stage_steering_handoff_v257 handoff
    JOIN stage_steering_request_v257 request
      ON request.id = handoff.request_id
    JOIN stage_turn turn ON turn.id = NEW.stage_turn_id
    JOIN dispatch_ticket predecessor
      ON predecessor.id = request.predecessor_ticket_id
    JOIN tasks task ON task.id = request.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE handoff.request_id = NEW.request_id
      AND handoff.status = 'PARKED'
      AND handoff.owner_family = NEW.owner_family
      AND request.status = 'PENDING'
      AND request.stage_kind = 'REMOTE_DEVELOPMENT'
      AND request.predecessor_owner_kind = 'STAGE_TURN'
      AND predecessor.status IN ('SUCCEEDED', 'FAILED', 'CANCELED')
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = request.task_epoch
      AND current.stage_id = request.stage_id
      AND current.stage_generation = request.stage_generation
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = request.stage_generation
      AND owner.completed_at_ms IS NULL
      AND turn.stage_id = request.stage_id
      AND turn.stage_generation = request.stage_generation
      AND turn.task_epoch = request.task_epoch
      AND turn.operation_id = NEW.operation_id
      AND turn.attempt = NEW.semantic_attempt
      AND turn.purpose = request.predecessor_purpose
      AND turn.status = 'QUEUED'
      AND turn.expected_code_fingerprint = code.code_fingerprint
      AND turn.expected_head_sha = code.head_sha
      AND turn.expected_base_sha = code.base_sha
      AND ((NEW.owner_family = 'CI_REPAIR' AND EXISTS (
          SELECT 1 FROM ci_repair_operation operation
          JOIN ci_repair_episode episode
            ON episode.id = operation.ci_repair_episode_id
          WHERE operation.operation_id = request.predecessor_operation_id
            AND operation.stage_turn_id = request.predecessor_owner_id
            AND operation.status IN (
                'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
            AND episode.id = NEW.ci_repair_episode_id
            AND episode.status = 'FIXING'))
        OR (NEW.owner_family = 'BRANCH_REPAIR' AND EXISTS (
          SELECT 1 FROM branch_sync_dispatch_operation operation
          JOIN branch_sync_episode episode
            ON episode.id = operation.branch_sync_episode_id
          JOIN branch_sync_effect_step step
            ON step.id = operation.branch_sync_effect_step_id
          WHERE operation.operation_id = request.predecessor_operation_id
            AND operation.stage_turn_id = request.predecessor_owner_id
            AND operation.status IN (
                'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
            AND episode.id = NEW.branch_sync_episode_id
            AND step.id = NEW.branch_sync_step_id
            AND step.status = 'CLAIMED'
            AND step.claim_owner = request.predecessor_operation_id))))
BEGIN SELECT RAISE(ABORT, 'Remote repair steering successor is not exact'); END;
CREATE TRIGGER remote_repair_steering_turn_terminal_v257
BEFORE UPDATE ON remote_repair_steering_turn_v257
WHEN OLD.status <> 'REQUESTED'
BEGIN SELECT RAISE(ABORT, 'terminal Remote repair steering is immutable'); END;
CREATE TRIGGER remote_repair_steering_turn_transition_v257
BEFORE UPDATE OF status ON remote_repair_steering_turn_v257
WHEN OLD.status <> 'REQUESTED' OR NEW.status NOT IN (
        'SUCCEEDED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'illegal Remote repair steering transition'); END;
CREATE TRIGGER remote_runtime_delivery_receipt_immutable
BEFORE UPDATE ON remote_runtime_delivery_receipt
BEGIN SELECT RAISE(ABORT, 'Remote runtime delivery receipt is immutable'); END;
CREATE TRIGGER remote_stage_runtime_receipt_immutable
BEFORE UPDATE ON remote_stage_runtime_receipt
BEGIN SELECT RAISE(ABORT, 'Remote Stage runtime receipt is immutable'); END;
CREATE TRIGGER remote_stage_runtime_receipt_insert
BEFORE INSERT ON remote_stage_runtime_receipt
WHEN NOT EXISTS (
    SELECT 1 FROM stage owner
    JOIN remote_development_stage remote ON remote.stage_id = owner.id
    WHERE owner.id = NEW.stage_id AND owner.task_id = NEW.task_id
      AND owner.kind = 'REMOTE_DEVELOPMENT'
      AND owner.generation = NEW.returned_generation
      AND remote.stage_id = owner.id
      AND (
        (NEW.cause IN ('COMPLETE_REMOTE_FEEDBACK_PUSH',
                'COMPLETE_REMOTE_FEEDBACK_NO_PUSH') AND EXISTS (
            SELECT 1 FROM remote_feedback_batch batch
            WHERE batch.id = NEW.proof_id
              AND batch.remote_development_stage_id = owner.id
              AND batch.task_id = NEW.task_id
              AND batch.task_epoch = NEW.expected_task_epoch
              AND batch.stage_generation = NEW.expected_stage_generation
              AND batch.status = 'COMPLETED'
              AND ((NEW.cause = 'COMPLETE_REMOTE_FEEDBACK_PUSH'
                    AND batch.result_head_sha IS NOT NULL
                    AND remote.current_head_sha = batch.result_head_sha)
                OR (NEW.cause = 'COMPLETE_REMOTE_FEEDBACK_NO_PUSH'
                    AND batch.result_head_sha IS NULL
                    AND remote.current_head_sha = batch.head_sha))))
        OR (NEW.cause = 'COMPLETE_REMOTE_MARK_READY' AND EXISTS (
            SELECT 1 FROM remote_mark_ready_operation operation
            WHERE operation.id = NEW.proof_id
              AND operation.remote_development_stage_id = owner.id
              AND operation.task_id = NEW.task_id
              AND operation.task_epoch = NEW.expected_task_epoch
              AND operation.stage_generation = NEW.expected_stage_generation
              AND operation.status = 'SUCCEEDED'
              AND operation.result_snapshot_id = remote.accepted_snapshot_id
              AND operation.head_sha = remote.current_head_sha
              AND operation.base_sha = remote.current_base_sha))
        OR (NEW.cause = 'ACCEPT_REMOTE_READINESS' AND EXISTS (
            SELECT 1 FROM remote_readiness_evidence readiness
            WHERE readiness.id = NEW.proof_id
              AND readiness.remote_development_stage_id = owner.id
              AND readiness.task_id = NEW.task_id
              AND readiness.task_epoch = NEW.expected_task_epoch
              AND readiness.stage_generation = NEW.expected_stage_generation
              AND readiness.ready = 1
              AND readiness.remote_pr_snapshot_id = remote.accepted_snapshot_id
              AND readiness.head_sha = remote.current_head_sha
              AND readiness.base_sha = remote.current_base_sha)))
      AND (NEW.disposition = 'SUPERSEDED' OR EXISTS (
          SELECT 1 FROM stage_transition transition
          WHERE transition.stage_id = NEW.stage_id
            AND transition.command_id = NEW.command_id
            AND transition.generation = NEW.returned_generation
            AND transition.stage_version = NEW.returned_version
            AND transition.cause = NEW.cause
            AND transition.actor = NEW.actor
            AND transition.from_checkpoint = NEW.source_checkpoint
            AND transition.to_checkpoint = NEW.returned_checkpoint))
)
BEGIN SELECT RAISE(ABORT, 'Remote feedback completion receipt lacks exact owner proof'); END;
CREATE TRIGGER remote_stage_steering_handoff_identity_v257
BEFORE UPDATE OF request_id, owner_family, owner_purpose,
        predecessor_turn_id, predecessor_operation_id
ON remote_stage_steering_handoff_v257
BEGIN SELECT RAISE(ABORT, 'Remote steering handoff identity is immutable'); END;
CREATE TRIGGER remote_stage_steering_handoff_insert_v257
BEFORE INSERT ON remote_stage_steering_handoff_v257
WHEN NEW.status <> 'PARKED' OR NOT EXISTS (
    SELECT 1
    FROM stage_steering_request_v257 request
    JOIN stage_turn turn ON turn.id = request.predecessor_owner_id
    WHERE request.id = NEW.request_id AND request.status = 'PENDING'
      AND request.stage_kind = 'REMOTE_DEVELOPMENT'
      AND request.predecessor_owner_kind = 'STAGE_TURN'
      AND request.predecessor_owner_id = NEW.predecessor_turn_id
      AND request.predecessor_operation_id = NEW.predecessor_operation_id
      AND request.predecessor_purpose = NEW.owner_purpose
      AND turn.operation_id = NEW.predecessor_operation_id
      AND NEW.owner_family = CASE NEW.owner_purpose
          WHEN 'REMOTE_CI_REPAIR' THEN 'CI_REPAIR'
          WHEN 'BRANCH_CONFLICT_REPAIR' THEN 'BRANCH_REPAIR'
          WHEN 'ADDRESS_REMOTE_FEEDBACK' THEN 'REMOTE_FEEDBACK'
          ELSE NULL END)
BEGIN SELECT RAISE(ABORT, 'Remote steering handoff owner is not exact'); END;
CREATE TRIGGER remote_stage_steering_handoff_terminal_v257
BEFORE UPDATE ON remote_stage_steering_handoff_v257
WHEN OLD.status = 'CONSUMED'
BEGIN SELECT RAISE(ABORT, 'consumed Remote steering handoff is immutable'); END;
CREATE TRIGGER remote_stage_steering_handoff_transition_v257
BEFORE UPDATE OF status ON remote_stage_steering_handoff_v257
WHEN OLD.status <> 'PARKED' OR NEW.status <> 'CONSUMED'
BEGIN SELECT RAISE(ABORT, 'illegal Remote steering handoff transition'); END;
CREATE TRIGGER remote_steering_code_subject_immutable_v257
BEFORE UPDATE ON remote_steering_code_subject_v257
BEGIN SELECT RAISE(ABORT, 'Remote steering code subject is immutable'); END;
CREATE TRIGGER remote_steering_code_subject_insert_v257
BEFORE INSERT ON remote_steering_code_subject_v257
WHEN NOT EXISTS (
    SELECT 1 FROM remote_repair_steering_turn_v257 operation
    JOIN stage_steering_request_v257 request ON request.id = operation.request_id
    JOIN stage_turn turn ON turn.id = operation.stage_turn_id
    WHERE operation.request_id = NEW.request_id
      AND operation.status = 'SUCCEEDED'
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND operation.result_head_sha = NEW.head_sha
      AND request.task_id = NEW.task_id AND request.task_epoch = NEW.task_epoch
      AND request.stage_id = NEW.remote_stage_id
      AND request.stage_generation = NEW.stage_generation
      AND turn.id = NEW.stage_turn_id AND turn.status = 'SUCCEEDED'
      AND turn.expected_code_fingerprint = NEW.source_code_fingerprint
      AND turn.expected_head_sha = NEW.source_head_sha
      AND turn.expected_base_sha = NEW.source_base_sha
      AND NEW.base_sha = NEW.source_base_sha)
BEGIN SELECT RAISE(ABORT, 'Remote steering code subject lacks exact result'); END;
CREATE TRIGGER remote_task_brain_receipt_immutable
BEFORE UPDATE ON remote_task_brain_receipt
BEGIN SELECT RAISE(ABORT, 'Remote Task Brain receipt is immutable'); END;
CREATE TRIGGER remote_task_brain_receipt_insert
BEFORE INSERT ON remote_task_brain_receipt
BEGIN
    SELECT CASE
        WHEN EXISTS (SELECT 1 FROM task_command_receipt shared
                     WHERE shared.task_id = NEW.task_id
                       AND shared.command_id = NEW.command_id)
          OR EXISTS (SELECT 1 FROM task_brain_request_receipt local
                     WHERE local.task_id = NEW.task_id
                       AND local.command_id = NEW.command_id)
            THEN RAISE(ABORT, 'Remote Task Brain command id is already used')
        WHEN NEW.cause = 'REQUEST_BRAIN_REVIEW' AND NOT EXISTS (
            SELECT 1 FROM remote_brain_operation_v248 operation
            JOIN task_transition transition
              ON transition.task_id = operation.task_id
             AND transition.command_id = NEW.command_id
            WHERE operation.proof_id = NEW.proof_id
              AND operation.status IN ('REQUESTED', 'DISPATCHED')
              AND operation.task_id = NEW.task_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.stage_id = NEW.subject_stage_id
              AND operation.stage_generation =
                  NEW.subject_stage_generation
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.attempt = NEW.subject_attempt
              AND operation.expected_code_fingerprint IS
                  NEW.subject_expected_code_fingerprint
              AND operation.expected_head_sha IS
                  NEW.subject_expected_head_sha
              AND operation.expected_base_sha IS
                  NEW.subject_expected_base_sha
              AND NEW.returned_epoch = NEW.expected_task_epoch
              AND NEW.returned_version = NEW.expected_task_version + 1
              AND NEW.returned_current_stage_id = NEW.subject_stage_id
              AND NEW.returned_pending_task_epoch = NEW.subject_task_epoch
              AND NEW.returned_pending_stage_id = NEW.subject_stage_id
              AND NEW.returned_pending_stage_generation =
                  NEW.subject_stage_generation
              AND NEW.returned_pending_operation_id =
                  NEW.subject_operation_id
              AND NEW.returned_pending_attempt = NEW.subject_attempt
              AND NEW.returned_pending_code_fingerprint IS
                  NEW.subject_expected_code_fingerprint
              AND NEW.returned_pending_head_sha IS
                  NEW.subject_expected_head_sha
              AND NEW.returned_pending_base_sha IS
                  NEW.subject_expected_base_sha
              AND transition.aggregate_version = NEW.returned_version
              AND transition.cause = NEW.cause
              AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'Remote Task Brain request receipt is not exact')
        WHEN NEW.cause = 'ACCEPT_BRAIN_VERDICT'
          AND NEW.disposition = 'APPLIED' AND NOT EXISTS (
            SELECT 1 FROM remote_brain_operation_v248 operation
            JOIN task_transition transition
              ON transition.task_id = operation.task_id
             AND transition.command_id = NEW.command_id
            WHERE operation.task_id = NEW.task_id
              AND operation.status = 'SUCCEEDED'
              AND operation.verdict = NEW.brain_verdict
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.attempt = NEW.subject_attempt
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.stage_id = NEW.subject_stage_id
              AND operation.stage_generation =
                  NEW.subject_stage_generation
              AND operation.expected_code_fingerprint IS
                  NEW.subject_expected_code_fingerprint
              AND operation.expected_head_sha IS
                  NEW.subject_expected_head_sha
              AND operation.expected_base_sha IS
                  NEW.subject_expected_base_sha
              AND NEW.returned_pending_operation_id IS NULL
              AND NEW.returned_last_brain_verdict = NEW.brain_verdict
              AND NEW.returned_last_brain_operation_id =
                  NEW.subject_operation_id
              AND transition.aggregate_version = NEW.returned_version
              AND transition.cause = NEW.cause
              AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'Remote Task Brain verdict receipt is not exact')
    END;
END;
CREATE TRIGGER remote_terminal_observation_immutable
BEFORE UPDATE ON remote_terminal_observation
BEGIN SELECT RAISE(ABORT, 'Remote terminal observation is immutable'); END;
CREATE TRIGGER remote_terminal_observation_insert
BEFORE INSERT ON remote_terminal_observation
WHEN NOT EXISTS (
    SELECT 1 FROM remote_pr_snapshot snapshot
    JOIN remote_development_stage remote
      ON remote.stage_id = snapshot.remote_development_stage_id
    JOIN tasks task ON task.id = remote.task_id
    JOIN task_terminal_intent intent ON intent.id = NEW.task_terminal_intent_id
    WHERE snapshot.id = NEW.remote_pr_snapshot_id
      AND snapshot.remote_development_stage_id =
            NEW.remote_development_stage_id
      AND snapshot.task_id = NEW.task_id
      AND snapshot.stage_generation = NEW.stage_generation
      AND snapshot.remote_pr_binding_id = NEW.remote_pr_binding_id
      AND snapshot.head_sha = NEW.head_sha
      AND snapshot.base_sha = NEW.base_sha
      AND snapshot.pr_state = NEW.kind
      AND NEW.observed_at_ms = snapshot.observed_at_ms
      AND remote.accepted_snapshot_id = snapshot.id
      AND remote.current_head_sha = NEW.head_sha
      AND remote.current_base_sha = NEW.base_sha
      AND task.epoch = NEW.task_epoch
      AND intent.task_id = NEW.task_id
      AND intent.accepted = 1
      AND intent.source = 'REMOTE_OBSERVATION'
      AND intent.source_id = snapshot.id
      AND intent.observed_head_sha = NEW.head_sha
      AND intent.kind = CASE NEW.kind
          WHEN 'MERGED' THEN 'COMPLETED' ELSE 'REMOTE_CLOSED' END)
BEGIN SELECT RAISE(ABORT, 'Remote terminal fact lacks exact observed Task intent'); END;
CREATE TRIGGER remote_worktree_subject_immutable
BEFORE UPDATE ON remote_worktree_subject
BEGIN SELECT RAISE(ABORT, 'Worktree subject is immutable'); END;
CREATE TRIGGER remote_worktree_subject_insert
BEFORE INSERT ON remote_worktree_subject
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_repair_operation operation
    JOIN ci_repair_episode episode
      ON episode.id = operation.ci_repair_episode_id
    WHERE NEW.source_kind = 'CI_STAGE_TURN'
      AND operation.operation_id = NEW.source_operation_id
      AND operation.kind = 'FIX_STAGE_TURN'
      AND operation.status = 'SUCCEEDED'
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND operation.stage_generation = NEW.stage_generation
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND operation.result_head_sha = NEW.head_sha
      AND operation.expected_base_sha = NEW.base_sha
    UNION ALL
    SELECT 1
    FROM branch_sync_dispatch_operation operation
    JOIN branch_sync_effect_step step
      ON step.id = operation.branch_sync_effect_step_id
    WHERE NEW.source_kind = 'BRANCH_EFFECT'
      AND operation.operation_id = NEW.source_operation_id
      AND operation.kind IN (
          'MECHANICAL_REBASE', 'VALIDATE', 'FORCE_WITH_LEASE_PUSH')
      AND operation.status = 'SUCCEEDED'
      AND step.status = 'SUCCEEDED'
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND operation.stage_generation = NEW.stage_generation
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND operation.result_head_sha = NEW.head_sha
      AND operation.target_base_sha = NEW.base_sha
    UNION ALL
    SELECT 1
    FROM branch_sync_dispatch_operation operation
    JOIN branch_sync_effect_step step
      ON step.id = operation.branch_sync_effect_step_id
    WHERE NEW.source_kind = 'BRANCH_STAGE_TURN'
      AND operation.operation_id = NEW.source_operation_id
      AND operation.kind = 'CONFLICT_REPAIR'
      AND operation.status = 'SUCCEEDED'
      AND step.status = 'SUCCEEDED'
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND operation.stage_generation = NEW.stage_generation
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND operation.result_head_sha = NEW.head_sha
      AND operation.target_base_sha = NEW.base_sha
    UNION ALL
    SELECT 1
    FROM v2_user_remote_action_v270 action
    WHERE NEW.source_kind = 'USER_CI_TRIGGER'
      AND action.operation_id = NEW.source_operation_id
      AND action.semantic_action = 'TRIGGER_CI_EMPTY_COMMIT'
      AND action.status = 'SUCCEEDED'
      AND action.task_id = NEW.task_id
      AND action.task_epoch = NEW.task_epoch
      AND action.remote_stage_id = NEW.remote_development_stage_id
      AND action.stage_generation = NEW.stage_generation
      AND action.expected_code_fingerprint = NEW.code_fingerprint
      AND action.expected_base_sha = NEW.base_sha
      AND action.expected_head_sha <> NEW.head_sha
      AND action.external_effect_id =
          'ci-trigger-empty-commit:' || NEW.head_sha)
BEGIN SELECT RAISE(ABORT,
    'Worktree subject lacks exact successful repair or CI-trigger evidence'); END;
CREATE TRIGGER remote_worktree_subject_revision_insert
BEFORE INSERT ON remote_worktree_subject
WHEN NEW.revision <> COALESCE((
    SELECT MAX(previous.revision) + 1
    FROM remote_worktree_subject previous
    WHERE previous.task_id = NEW.task_id
      AND previous.task_epoch = NEW.task_epoch), 1)
BEGIN SELECT RAISE(ABORT,
    'Worktree subject revision is not the next exact revision'); END;
CREATE TRIGGER response_round_fence_immutable
BEFORE UPDATE OF workflow_version, task_epoch, stage_id, stage_generation,
        operation_id, semantic_attempt, code_fingerprint,
        expected_head_sha, expected_base_sha ON response_round
WHEN NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR (OLD.workflow_version = 'V2'
    AND NEW.code_fingerprint IS NOT OLD.code_fingerprint)
BEGIN SELECT RAISE(ABORT, 'response round fence is immutable'); END;
CREATE TRIGGER response_round_route_insert
BEFORE INSERT ON response_round
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = NEW.workflow_version)
    THEN RAISE(ABORT, 'response round workflow version does not match Task') END;
    SELECT CASE WHEN NEW.workflow_version = 'V2' AND (
        NEW.task_epoch IS NULL OR NEW.stage_id IS NULL
        OR NEW.stage_generation IS NULL OR NEW.operation_id IS NULL
        OR NEW.semantic_attempt IS NULL OR NEW.semantic_attempt <= 0
        OR NEW.code_fingerprint IS NULL
        OR NEW.expected_head_sha IS NULL OR NEW.expected_base_sha IS NULL
        OR NOT EXISTS (
            SELECT 1 FROM stage s JOIN tasks t ON t.id = s.task_id
            WHERE s.id = NEW.stage_id
              AND s.generation = NEW.stage_generation
              AND t.id = NEW.task_id
              AND t.epoch = NEW.task_epoch))
    THEN RAISE(ABORT, 'V2 response round requires its complete fence') END;
END;
CREATE TRIGGER review_assignment_question_answer_transition
BEFORE UPDATE OF state, answer, answer_revision, answered_at_ms,
        answer_option_id, answer_free_form, answer_actor
ON review_assignment_question
WHEN NEW.state IS NOT OLD.state
BEGIN
    SELECT CASE WHEN OLD.state <> 'OPEN'
        OR NEW.state NOT IN ('ANSWERED', 'CANCELED')
        OR NEW.answer_revision <> OLD.answer_revision + 1
        OR NEW.answer_actor IS NULL OR length(trim(NEW.answer_actor)) = 0
        OR NEW.answer IS NULL OR length(trim(NEW.answer)) = 0
        OR NEW.answered_at_ms IS NULL OR NEW.answered_at_ms < OLD.created_at_ms
        OR NEW.state = 'ANSWERED'
            AND NEW.answer_option_id IS NULL AND NEW.answer_free_form IS NULL
        OR NEW.state = 'CANCELED' AND NEW.continuation_state <> 'CANCELED'
    THEN RAISE(ABORT, 'review question answer transition is invalid') END;
END;
CREATE TRIGGER review_assignment_question_continuation_transition
BEFORE UPDATE OF continuation_state, successor_turn_id, continuation_error
ON review_assignment_question
BEGIN
    SELECT CASE WHEN OLD.continuation_state = 'WAITING'
            AND NEW.continuation_state NOT IN ('WAITING', 'READY', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state = 'READY'
            AND NEW.continuation_state NOT IN ('READY', 'DISPATCHED', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state IN ('DISPATCHED', 'CANCELED', 'SUPERSEDED')
            AND (NEW.continuation_state IS NOT OLD.continuation_state
                OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
                OR NEW.continuation_error IS NOT OLD.continuation_error)
        OR NEW.continuation_state = 'DISPATCHED' AND NEW.successor_turn_id IS NULL
    THEN RAISE(ABORT, 'review question continuation is invalid') END;
END;
CREATE TRIGGER review_assignment_question_terminal_immutable
BEFORE UPDATE ON review_assignment_question
WHEN OLD.state <> 'OPEN'
  AND (NEW.state IS NOT OLD.state OR NEW.answer IS NOT OLD.answer
    OR NEW.answer_revision IS NOT OLD.answer_revision
    OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
    OR NEW.answer_option_id IS NOT OLD.answer_option_id
    OR NEW.answer_free_form IS NOT OLD.answer_free_form
    OR NEW.answer_actor IS NOT OLD.answer_actor)
BEGIN SELECT RAISE(ABORT, 'terminal review question is immutable'); END;
CREATE TRIGGER review_assignment_turn_budget_reservation_insert_v278
BEFORE INSERT ON review_assignment_turn
BEGIN
    SELECT CASE
        WHEN NEW.cost_cap_usd_milli IS NULL OR NEW.cost_cap_usd_milli < 1
            THEN RAISE(ABORT, 'review assignment Turn requires a positive frozen cost cap')
        WHEN COALESCE((
            SELECT CAST(COALESCE(
                        json_extract(round.budget_json, '$.cost_cap_cents'),
                        json_extract(round.budget_json, '$.costCapCents')) AS INTEGER)
            FROM review_assignment assignment
            JOIN review_round round ON round.id = assignment.round_id
            WHERE assignment.id = NEW.assignment_id), 0) < 1
            THEN RAISE(ABORT, 'review round requires a positive cost cap')
        WHEN NEW.cost_cap_usd_milli > (
            SELECT CAST(COALESCE(
                        json_extract(round.budget_json, '$.cost_cap_cents'),
                        json_extract(round.budget_json, '$.costCapCents')) AS INTEGER) * 10
                   - COALESCE((
                        SELECT SUM(receipt.cost_usd_milli)
                        FROM review_assignment_turn_result_receipt receipt
                        WHERE receipt.round_id = round.id), 0)
                   - COALESCE((
                        SELECT SUM(existing.cost_cap_usd_milli)
                        FROM review_assignment_turn existing
                        JOIN review_assignment existing_assignment
                          ON existing_assignment.id = existing.assignment_id
                        WHERE existing_assignment.round_id = round.id
                          AND existing.status IN (
                              'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')), 0)
            FROM review_assignment assignment
            JOIN review_round round ON round.id = assignment.round_id
            WHERE assignment.id = NEW.assignment_id)
            THEN RAISE(ABORT, 'review assignment Turn exceeds the round cost cap')
    END;
END;
CREATE TRIGGER review_assignment_turn_global_identity_insert
BEFORE INSERT ON review_assignment_turn
WHEN EXISTS (SELECT 1 FROM thread_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM task_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM stage_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
BEGIN SELECT RAISE(ABORT, 'typed Turn id and operation id must be globally exact'); END;
CREATE TRIGGER review_assignment_turn_identity_immutable
BEFORE UPDATE OF assignment_id, purpose, subject_key, verifier_run_id,
        operation_id, attempt, start_commit, delivery_lane, launch_input,
        cost_cap_usd_milli
        ON review_assignment_turn
WHEN NEW.assignment_id IS NOT OLD.assignment_id
  OR NEW.purpose IS NOT OLD.purpose
  OR NEW.subject_key IS NOT OLD.subject_key
  OR NEW.verifier_run_id IS NOT OLD.verifier_run_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.attempt IS NOT OLD.attempt
  OR NEW.start_commit IS NOT OLD.start_commit
  OR NEW.delivery_lane IS NOT OLD.delivery_lane
  OR NEW.launch_input IS NOT OLD.launch_input
  OR NEW.cost_cap_usd_milli IS NOT OLD.cost_cap_usd_milli
BEGIN SELECT RAISE(ABORT, 'review assignment Turn launch identity is immutable'); END;
CREATE TRIGGER review_assignment_turn_request_receipt_exact
BEFORE INSERT ON review_assignment_turn_request_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM review_assignment_turn turn
        JOIN review_assignment assignment ON assignment.id = turn.assignment_id
        JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
        WHERE turn.id = NEW.turn_id
          AND turn.assignment_id = NEW.assignment_id
          AND assignment.round_id = NEW.round_id
          AND turn.operation_id = NEW.operation_id
          AND turn.attempt = NEW.attempt
          AND turn.start_commit = NEW.start_commit
          AND ticket.operation_id = NEW.operation_id
          AND ticket.owner_kind = 'REVIEW_ASSIGNMENT_TURN'
          AND ticket.owner_id = NEW.turn_id)
    THEN RAISE(ABORT, 'review Turn request receipt is not exact') END;
END;
CREATE TRIGGER review_assignment_turn_request_receipt_immutable
BEFORE UPDATE ON review_assignment_turn_request_receipt
BEGIN SELECT RAISE(ABORT, 'review Turn request receipt is immutable'); END;
CREATE TRIGGER review_assignment_turn_result_receipt_exact
BEFORE INSERT ON review_assignment_turn_result_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM review_assignment_turn turn
        JOIN review_assignment assignment ON assignment.id = turn.assignment_id
        JOIN review_round round ON round.id = assignment.round_id
        WHERE turn.id = NEW.turn_id
          AND turn.assignment_id = NEW.assignment_id
          AND assignment.round_id = NEW.round_id
          AND round.session_id = NEW.review_id
          AND turn.operation_id = NEW.operation_id
          AND turn.attempt = NEW.attempt
          AND turn.start_commit = NEW.start_commit
          AND turn.status = NEW.terminal_status
          AND turn.finished_at_ms IS NOT NULL)
    THEN RAISE(ABORT, 'review Turn result receipt is not exact') END;
END;
CREATE TRIGGER review_assignment_turn_result_receipt_immutable
BEFORE UPDATE ON review_assignment_turn_result_receipt
BEGIN SELECT RAISE(ABORT, 'review Turn result receipt is immutable'); END;
CREATE TRIGGER review_assignment_turn_start_insert
BEFORE INSERT ON review_assignment_turn
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM review_assignment a
        JOIN review_round r ON r.id = a.round_id
        WHERE a.id = NEW.assignment_id
          AND r.start_commit = NEW.start_commit)
    THEN RAISE(ABORT, 'review assignment Turn must freeze round start commit') END;
END;
