      AND pass.head_sha = NEW.expected_head_sha
      AND trunk.workspace_id = NEW.workspace_id
      AND trunk.flow = 'review'
      AND trunk.turn_version = 'V2'
      AND trunk.lifecycle_state IN ('ACTIVE', 'IDLE')
      AND NOT EXISTS (
          SELECT 1 FROM tasks task WHERE task.thread_id = trunk.id))
BEGIN SELECT RAISE(ABORT,
    'review pass publication lacks its exact standalone subject'); END;
CREATE TRIGGER review_pass_publication_item_delete_v288
BEFORE DELETE ON review_pass_publication_item_v288
WHEN NOT EXISTS (
    SELECT 1
    FROM review_pass_publication_v288 publication
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = publication.thread_id
    WHERE publication.id = OLD.publication_id)
BEGIN SELECT RAISE(ABORT,
    'review pass publication item cannot be deleted'); END;
CREATE TRIGGER review_pass_publication_item_insert_v288
BEFORE INSERT ON review_pass_publication_item_v288
WHEN NOT EXISTS (
    SELECT 1
    FROM review_pass_publication_v288 publication
    JOIN review_findings finding ON finding.id = NEW.finding_id
    WHERE publication.id = NEW.publication_id
      AND finding.review_pass_id = publication.review_pass_id
      AND finding.revision = NEW.finding_revision
      AND finding.status IN ('agreed', 'resolved', 'arbitrated')
      AND finding.path IS NEW.path
      AND finding.line IS NEW.line
      AND finding.severity = NEW.severity
      AND finding.body = NEW.body)
BEGIN SELECT RAISE(ABORT,
    'review pass publication item differs from its frozen finding'); END;
CREATE TRIGGER review_pass_publication_item_update_v288
BEFORE UPDATE ON review_pass_publication_item_v288
BEGIN SELECT RAISE(ABORT,
    'review pass publication item is immutable'); END;
CREATE TRIGGER review_pass_publication_observation_v288
BEFORE UPDATE OF observation_started_at_ms, observation_deadline_ms
        ON review_pass_publication_v288
WHEN OLD.observation_started_at_ms IS NOT NULL
  OR OLD.observation_deadline_ms IS NOT NULL
  OR NEW.observation_started_at_ms IS NULL
  OR NEW.observation_deadline_ms <= NEW.observation_started_at_ms
  OR OLD.status <> 'CLAIMED'
BEGIN SELECT RAISE(ABORT,
    'review pass publication observation window is immutable'); END;
CREATE TRIGGER review_pass_publication_pass_freeze_v288
BEFORE UPDATE OF thread_id, repo_full_name, pr_number, head_sha, phase,
        verdict, host_kind, host_id, base_repository_id,
        head_repository_id, head_ref ON review_passes
WHEN EXISTS (
    SELECT 1 FROM review_pass_publication_v288 publication
    WHERE publication.review_pass_id = OLD.id
      AND publication.finalized_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT,
    'an authorized standalone review pass is frozen'); END;
CREATE TRIGGER review_pass_publication_transition_v288
BEFORE UPDATE OF status ON review_pass_publication_v288
WHEN NOT (
    (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status IN ('CLAIMED', 'CANCELED', 'ABANDONED'))
    OR (OLD.status = 'CLAIMED' AND NEW.status IN (
        'SUCCEEDED', 'FAILED', 'INDETERMINATE', 'CANCELED', 'ABANDONED'))
    OR OLD.status = NEW.status)
BEGIN SELECT RAISE(ABORT,
    'review pass publication transition is invalid'); END;
CREATE TRIGGER review_pass_published_requires_v288
BEFORE UPDATE OF phase ON review_passes
WHEN NEW.phase = 'published' AND OLD.phase <> 'published'
  AND NEW.host_kind = 'THREAD'
  AND NOT EXISTS (
      SELECT 1 FROM review_pass_publication_v288 publication
      WHERE publication.review_pass_id = OLD.id
        AND publication.status = 'SUCCEEDED'
        AND publication.finalized_at_ms IS NOT NULL)
BEGIN SELECT RAISE(ABORT,
    'standalone review publication requires accepted durable evidence'); END;
CREATE TRIGGER review_question_continuation_scope
BEFORE UPDATE OF continuation_state, successor_turn_id
ON review_assignment_question
WHEN NEW.continuation_state = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1
    FROM review_assignment_turn source
    JOIN review_assignment_turn successor
      ON successor.id = NEW.successor_turn_id
    WHERE source.id = OLD.turn_id
      AND successor.id <> source.id
      AND successor.assignment_id = source.assignment_id
      AND successor.start_commit = source.start_commit)
BEGIN SELECT RAISE(ABORT, 'review question successor fence is stale'); END;
CREATE TRIGGER review_question_identity_immutable
BEFORE UPDATE ON review_assignment_question
WHEN NEW.id IS NOT OLD.id OR NEW.turn_id IS NOT OLD.turn_id
  OR NEW.call_id IS NOT OLD.call_id OR NEW.prompt IS NOT OLD.prompt
  OR NEW.context IS NOT OLD.context
  OR NEW.options_json IS NOT OLD.options_json
  OR NEW.allow_free_form IS NOT OLD.allow_free_form
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'review question identity is immutable'); END;
CREATE TRIGGER review_question_open_invariant
BEFORE UPDATE ON review_assignment_question
WHEN OLD.state = 'OPEN' AND NEW.state = 'OPEN'
 AND (NEW.answer IS NOT OLD.answer
   OR NEW.answer_revision IS NOT OLD.answer_revision
   OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
   OR NEW.answer_option_id IS NOT OLD.answer_option_id
   OR NEW.answer_free_form IS NOT OLD.answer_free_form
   OR NEW.answer_actor IS NOT OLD.answer_actor
   OR NEW.continuation_state IS NOT OLD.continuation_state
   OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
   OR NEW.continuation_error IS NOT OLD.continuation_error)
BEGIN SELECT RAISE(ABORT, 'open review question is immutable'); END;
CREATE TRIGGER review_round_budget_reservation_update_v278
BEFORE UPDATE OF budget_json ON review_round
WHEN COALESCE(
        json_extract(NEW.budget_json, '$.cost_cap_cents'),
        json_extract(NEW.budget_json, '$.costCapCents')) IS NULL
  OR CAST(COALESCE(
        json_extract(NEW.budget_json, '$.cost_cap_cents'),
        json_extract(NEW.budget_json, '$.costCapCents')) AS INTEGER) < 1
  OR CAST(COALESCE(
        json_extract(NEW.budget_json, '$.cost_cap_cents'),
        json_extract(NEW.budget_json, '$.costCapCents')) AS INTEGER) * 10 <
        COALESCE((
            SELECT SUM(receipt.cost_usd_milli)
            FROM review_assignment_turn_result_receipt receipt
            WHERE receipt.round_id = NEW.id), 0)
        + COALESCE((
            SELECT SUM(turn.cost_cap_usd_milli)
            FROM review_assignment_turn turn
            JOIN review_assignment assignment ON assignment.id = turn.assignment_id
            WHERE assignment.round_id = NEW.id
              AND turn.status IN (
                  'REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')), 0)
BEGIN SELECT RAISE(ABORT, 'review round budget is below durable spend and reservations'); END;
CREATE TRIGGER review_round_followup_binding_update_v262
BEFORE UPDATE OF verifier_assignment_id, verifier_run_id
        ON review_round_followup_v262
WHEN OLD.verifier_assignment_id IS NULL
  AND NEW.verifier_assignment_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1
      FROM review_assignment assignment
      JOIN agent_run run ON run.id = NEW.verifier_run_id
      WHERE assignment.id = NEW.verifier_assignment_id
        AND assignment.round_id = NEW.round_id
        AND run.review_round_id = NEW.round_id)
BEGIN SELECT RAISE(ABORT, 'review follow-up verifier ownership is not exact'); END;
CREATE TRIGGER review_round_followup_exact_insert_v262
BEFORE INSERT ON review_round_followup_v262
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM review_round round
            WHERE round.id = NEW.round_id
              AND round.start_commit = NEW.start_commit)
            THEN RAISE(ABORT, 'review follow-up must freeze the round start commit')
        WHEN NEW.verifier_assignment_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM review_assignment assignment
            JOIN agent_run run ON run.id = NEW.verifier_run_id
            WHERE assignment.id = NEW.verifier_assignment_id
              AND assignment.round_id = NEW.round_id
              AND run.review_round_id = NEW.round_id)
            THEN RAISE(ABORT, 'review follow-up verifier ownership is not exact')
    END;
END;
CREATE TRIGGER review_round_followup_identity_update_v262
BEFORE UPDATE OF round_id, start_commit, verifier_assignment_id, verifier_run_id
        ON review_round_followup_v262
WHEN NEW.round_id IS NOT OLD.round_id
  OR NEW.start_commit IS NOT OLD.start_commit
  OR (OLD.verifier_assignment_id IS NOT NULL
      AND NEW.verifier_assignment_id IS NOT OLD.verifier_assignment_id)
  OR (OLD.verifier_run_id IS NOT NULL
      AND NEW.verifier_run_id IS NOT OLD.verifier_run_id)
BEGIN SELECT RAISE(ABORT, 'review follow-up identity is immutable'); END;
CREATE TRIGGER review_round_snapshot_immutable_v291
BEFORE UPDATE ON review_round_snapshot_v291
BEGIN
    SELECT RAISE(ABORT, 'Review round snapshot is immutable');
END;
CREATE TRIGGER review_round_snapshot_subject_v291
BEFORE INSERT ON review_round_snapshot_v291
WHEN NOT EXISTS (
    SELECT 1
    FROM review_round round
    JOIN review_session review ON review.id = round.session_id
    JOIN pr ON pr.id = review.pr_id
    WHERE round.id = NEW.round_id
      AND round.start_commit = NEW.head_commit
      AND review.base_commit = NEW.base_commit
      AND pr.repo IS NEW.repository
      AND pr.remote_pr_number IS NEW.remote_pr_number
      AND pr.base_branch = NEW.base_branch
      AND pr.title = NEW.pr_title
      AND pr.description = NEW.pr_description)
BEGIN
    SELECT RAISE(ABORT,
        'Review round snapshot differs from its exact ReviewSession subject');
END;
CREATE TRIGGER review_turn_user_wait_continuation_exact_v265
BEFORE INSERT ON review_turn_user_wait_continuation_v265
WHEN NOT EXISTS (
    SELECT 1
    FROM review_assignment_turn predecessor
    JOIN review_assignment_turn successor
      ON successor.id = NEW.successor_turn_id
    JOIN typed_user_wait_result result
      ON result.operation_id = predecessor.operation_id
    WHERE predecessor.id = NEW.predecessor_turn_id
      AND predecessor.operation_id = NEW.predecessor_operation_id
      AND predecessor.status = 'SUCCEEDED'
      AND successor.operation_id = NEW.successor_operation_id
      AND successor.id <> predecessor.id
      AND successor.assignment_id = predecessor.assignment_id
      AND successor.purpose = predecessor.purpose
      AND successor.subject_key = predecessor.subject_key
      AND successor.verifier_run_id IS predecessor.verifier_run_id
      AND successor.attempt = predecessor.attempt + 1
      AND successor.start_commit = predecessor.start_commit
      AND successor.status = 'REQUESTED'
      AND result.owner_kind = 'REVIEW_ASSIGNMENT_TURN'
      AND result.turn_id = predecessor.id
      AND result.wait_kind = NEW.wait_kind AND result.wait_id = NEW.wait_id
      AND ((NEW.wait_kind = 'QUESTION' AND EXISTS (
            SELECT 1 FROM review_assignment_question question
            WHERE question.id = NEW.wait_id
              AND question.turn_id = predecessor.id
              AND question.state = 'ANSWERED'
              AND question.continuation_state = 'READY'))
        OR (NEW.wait_kind = 'PERMISSION' AND EXISTS (
            SELECT 1 FROM permission_request permission
            WHERE permission.id = NEW.wait_id
              AND permission.turn_kind = 'REVIEW_ASSIGNMENT'
              AND permission.turn_id = predecessor.id
              AND permission.operation_id = predecessor.operation_id
              AND permission.state <> 'OPEN'
              AND permission.continuation_state = 'READY'))))
BEGIN SELECT RAISE(ABORT, 'Review user-wait continuation is not exact'); END;
CREATE TRIGGER review_turn_user_wait_continuation_immutable_v265
BEFORE UPDATE ON review_turn_user_wait_continuation_v265
BEGIN SELECT RAISE(ABORT, 'Review user-wait continuation is immutable'); END;
CREATE TRIGGER round_gate_authorization_fence_immutable
BEFORE UPDATE OF workflow_version, task_epoch, stage_id, stage_generation,
        operation_id, semantic_attempt, code_fingerprint,
        expected_head_sha, expected_base_sha ON round_gate_authorization
WHEN NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
BEGIN SELECT RAISE(ABORT, 'round gate authorization fence is immutable'); END;
CREATE TRIGGER round_gate_authorization_route_insert
BEFORE INSERT ON round_gate_authorization
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = NEW.workflow_version)
    THEN RAISE(ABORT, 'round gate workflow version does not match Task') END;
    SELECT CASE WHEN NEW.workflow_version = 'V2' AND (
        NEW.task_epoch IS NULL OR NEW.stage_id IS NULL
        OR NEW.stage_generation IS NULL OR NEW.operation_id IS NULL
        OR NEW.semantic_attempt IS NULL OR NEW.semantic_attempt <= 0
        OR NEW.code_fingerprint IS NULL
        OR NEW.expected_head_sha IS NULL OR NEW.expected_base_sha IS NULL
        OR NOT EXISTS (
            SELECT 1
            FROM response_round r
            JOIN stage s ON s.id = r.stage_id
            JOIN tasks t ON t.id = r.task_id
            WHERE r.id = NEW.round_id
              AND r.workflow_version = NEW.workflow_version
              AND r.task_id = NEW.task_id
              AND r.task_epoch = NEW.task_epoch
              AND r.stage_id = NEW.stage_id
              AND r.stage_generation = NEW.stage_generation
              AND r.operation_id = NEW.operation_id
              AND r.semantic_attempt = NEW.semantic_attempt
              AND r.code_fingerprint IS NEW.code_fingerprint
              AND r.expected_head_sha IS NEW.expected_head_sha
              AND r.expected_base_sha IS NEW.expected_base_sha
              AND s.generation = NEW.stage_generation
              AND t.epoch = NEW.task_epoch))
    THEN RAISE(ABORT, 'V2 round gate authorization requires its complete fence') END;
END;
CREATE TRIGGER stage_command_receipt_immutable
BEFORE UPDATE ON stage_command_receipt
BEGIN SELECT RAISE(ABORT, 'Stage command receipt is immutable'); END;
CREATE TRIGGER stage_command_receipt_insert
BEFORE INSERT ON stage_command_receipt
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM stage stage
            JOIN tasks task ON task.id = stage.task_id
            WHERE stage.id = NEW.stage_id
              AND stage.task_id = NEW.task_id
              AND stage.kind = NEW.returned_kind
              AND stage.generation = NEW.returned_generation
              AND task.workflow_version = 'V2')
            THEN RAISE(ABORT, 'Stage command receipt requires its exact V2 owner')
        WHEN NEW.disposition = 'APPLIED' AND NOT EXISTS (
            SELECT 1 FROM stage_transition transition
            WHERE transition.stage_id = NEW.stage_id
              AND transition.command_id = NEW.command_id
              AND transition.generation = NEW.returned_generation
              AND transition.to_checkpoint = NEW.returned_checkpoint
              AND transition.stage_version = NEW.returned_version
              AND transition.cause = NEW.cause AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'applied Stage receipt lacks its exact transition')
        WHEN NEW.cause = 'SEAL_FOR_TASK_CANCELLATION' AND NOT EXISTS (
            SELECT 1 FROM task_quiescence_barrier barrier
            WHERE barrier.id = NEW.proof_id
              AND barrier.task_id = NEW.task_id
              AND barrier.task_epoch = NEW.expected_task_epoch
              AND barrier.reason = 'CANCEL'
              AND barrier.status = 'SATISFIED'
              AND NEW.expected_stage_generation = NEW.returned_generation
              AND NEW.returned_end_reason = 'TASK_CANCELED'
              AND NEW.source_checkpoint IS NULL)
            THEN RAISE(ABORT, 'Stage cancellation seal proof is invalid')
        WHEN NEW.cause = 'OPEN_CANCELED_CLEANUP' AND NOT EXISTS (
            SELECT 1
            FROM task_quiescence_barrier barrier
            JOIN task_command_receipt task_receipt
              ON task_receipt.task_id = barrier.task_id
            WHERE barrier.id = NEW.proof_id
              AND barrier.task_id = NEW.task_id
              AND barrier.reason = 'CANCEL'
              AND barrier.status = 'SATISFIED'
              AND task_receipt.command_id = NEW.command_id
              AND task_receipt.cause = 'OPEN_CANCELED_CLEANUP'
              AND task_receipt.actor = NEW.actor
              AND task_receipt.disposition = 'APPLIED'
              AND task_receipt.expected_task_epoch = barrier.task_epoch
              AND task_receipt.proof_id = barrier.id
              AND task_receipt.next_stage_id = NEW.stage_id
              AND task_receipt.next_stage_kind = 'CLEANUP'
              AND task_receipt.next_stage_generation = NEW.returned_generation
              AND task_receipt.returned_current_stage_id = NEW.stage_id
              AND task_receipt.returned_lifecycle = 'CLEANING'
              AND task_receipt.returned_terminal_intent = 'CANCELED'
              AND NEW.returned_kind = 'CLEANUP'
              AND NEW.returned_version = 0
              AND NEW.returned_checkpoint = 'WAITING_QUIESCENCE')
            THEN RAISE(ABORT, 'canceled Cleanup must open waiting on its exact barrier')
        WHEN NEW.cause = 'ACCEPT_CLEANUP_QUIESCENCE' AND NOT EXISTS (
            SELECT 1 FROM task_quiescence_barrier barrier
            WHERE barrier.id = NEW.proof_id
              AND barrier.task_id = NEW.task_id
              AND barrier.task_epoch = NEW.expected_task_epoch
              AND barrier.reason IN ('CANCEL', 'CLEANUP')
              AND barrier.status = 'SATISFIED'
              AND NEW.expected_stage_generation = NEW.returned_generation
              AND NEW.source_checkpoint = 'WAITING_QUIESCENCE'
              AND NEW.returned_kind = 'CLEANUP'
              AND NEW.returned_version = NEW.expected_stage_version + 1
              AND NEW.returned_checkpoint = 'CLEANING'
              AND (barrier.reason <> 'CANCEL' OR EXISTS (
                  SELECT 1 FROM stage_command_receipt opening
                  WHERE opening.stage_id = NEW.stage_id
                    AND opening.task_id = NEW.task_id
                    AND opening.cause = 'OPEN_CANCELED_CLEANUP'
                    AND opening.proof_id = barrier.id
                    AND opening.returned_generation = NEW.returned_generation
                    AND opening.returned_version = 0
                    AND opening.returned_checkpoint = 'WAITING_QUIESCENCE')))
            THEN RAISE(ABORT, 'Cleanup quiescence receipt lacks its exact barrier')
        WHEN NEW.cause = 'OPEN_INITIAL_PLAN' AND NOT EXISTS (
            SELECT 1 FROM provision_task_operation operation
            WHERE operation.task_id = NEW.task_id
              AND operation.operation_id = NEW.proof_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.semantic_attempt = NEW.subject_attempt
              AND operation.result_code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND operation.result_head_sha IS NEW.subject_expected_head_sha
              AND operation.result_base_sha IS NEW.subject_expected_base_sha
              AND operation.status = 'ACCEPTED'
              AND NEW.returned_kind = 'PLAN'
              AND NEW.returned_checkpoint = 'DRAFTING')
            THEN RAISE(ABORT, 'Stage receipt initial Plan proof is invalid')
        WHEN NEW.cause = 'OPEN_REPLAN_PLAN' AND NOT EXISTS (
            SELECT 1 FROM task_replan_request request
            JOIN task_quiescence_barrier barrier
              ON barrier.id = request.quiescence_barrier_id
            WHERE request.id = NEW.proof_id
              AND request.task_id = NEW.task_id
              AND barrier.status = 'SATISFIED'
              AND NEW.returned_kind = 'PLAN'
              AND NEW.returned_checkpoint = 'DRAFTING')
            THEN RAISE(ABORT, 'Stage receipt replan proof is invalid')
        WHEN NEW.cause = 'OPEN_LOCAL_DEVELOPMENT' AND NOT EXISTS (
            SELECT 1 FROM plan_approval approval
            JOIN plan_revision revision ON revision.id = approval.plan_revision_id
            JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
            WHERE approval.id = NEW.proof_id
              AND plan.task_id = NEW.task_id
              AND NEW.returned_kind = 'LOCAL_DEVELOPMENT'
              AND NEW.returned_checkpoint = 'IMPLEMENTING')
            THEN RAISE(ABORT, 'Stage receipt Local opening proof is invalid')
        WHEN NEW.cause = 'REVISE_BEFORE_APPROVAL' AND NOT EXISTS (
            SELECT 1 FROM plan_revision revision
            JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
            WHERE revision.id = NEW.proof_id
              AND plan.task_id = NEW.task_id
              AND plan.stage_id = NEW.stage_id
              AND plan.generation = NEW.returned_generation)
            THEN RAISE(ABORT, 'Stage receipt Plan revision proof is invalid')
        WHEN NEW.cause = 'APPROVE_PLAN' AND NOT EXISTS (
            SELECT 1 FROM plan_approval approval
            JOIN plan_revision revision ON revision.id = approval.plan_revision_id
            JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
            WHERE approval.id = NEW.proof_id
              AND plan.task_id = NEW.task_id
              AND plan.stage_id = NEW.stage_id
              AND plan.generation = NEW.returned_generation)
            THEN RAISE(ABORT, 'Stage receipt Plan approval proof is invalid')
        WHEN NEW.cause = 'ACCEPT_IMPLEMENTATION' AND NOT EXISTS (
            SELECT 1 FROM dev_report report
            JOIN stage_turn turn ON turn.id = report.stage_turn_id
            WHERE report.workflow_version = 'V2'
              AND report.task_id = NEW.task_id
              AND report.local_development_stage_id = NEW.stage_id
              AND report.task_epoch = NEW.subject_task_epoch
              AND report.stage_generation = NEW.subject_stage_generation
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.attempt = NEW.subject_attempt
              AND report.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND report.head_sha IS NEW.subject_expected_head_sha
              AND report.base_sha IS NEW.subject_expected_base_sha
              AND NOT EXISTS (
                  SELECT 1 FROM dev_report newer
                  WHERE newer.workflow_version = 'V2'
                    AND newer.local_development_stage_id = report.local_development_stage_id
                    AND newer.revision > report.revision))
            THEN RAISE(ABORT, 'Stage receipt implementation proof is invalid')
        WHEN NEW.cause = 'ACCEPT_VALIDATION' AND NOT EXISTS (
            SELECT 1 FROM validation_evidence evidence
            JOIN validation_operation operation
              ON operation.id = evidence.validation_operation_id
            WHERE evidence.task_id = NEW.task_id
              AND evidence.task_epoch = NEW.subject_task_epoch
              AND evidence.stage_id = NEW.stage_id
              AND evidence.stage_generation = NEW.subject_stage_generation
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.semantic_attempt = NEW.subject_attempt
              AND evidence.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND evidence.head_sha IS NEW.subject_expected_head_sha
              AND evidence.base_sha IS NEW.subject_expected_base_sha
              AND evidence.passed = 1
              AND operation.status = 'COMPLETED')
            THEN RAISE(ABORT, 'Stage receipt validation proof is invalid')
        WHEN NEW.cause IN ('ACCEPT_BRAIN_APPROVAL', 'ACCEPT_BRAIN_FINDINGS')
          AND NOT EXISTS (
            SELECT 1 FROM brain_review_episode brain
            JOIN task_turn turn ON turn.id = brain.task_turn_id
            WHERE brain.task_id = NEW.task_id
              AND brain.task_epoch = NEW.subject_task_epoch
              AND brain.local_development_stage_id = NEW.stage_id
              AND brain.stage_generation = NEW.subject_stage_generation
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.attempt = NEW.subject_attempt
              AND brain.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND brain.expected_head_sha IS NEW.subject_expected_head_sha
              AND brain.expected_base_sha IS NEW.subject_expected_base_sha
              AND brain.status = 'SUCCEEDED'
              AND ((NEW.cause = 'ACCEPT_BRAIN_APPROVAL'
                    AND brain.verdict = 'APPROVED')
                OR (NEW.cause = 'ACCEPT_BRAIN_FINDINGS'
                    AND brain.verdict = 'CHANGES_REQUESTED')))
            THEN RAISE(ABORT, 'Stage receipt Brain proof is invalid')
        WHEN NEW.cause IN ('ACCEPT_BRAIN_FIXES', 'ACCEPT_LOCAL_FEEDBACK_FIXES')
          AND NOT EXISTS (
            SELECT 1 FROM stage_turn turn
            WHERE turn.stage_id = NEW.stage_id
              AND turn.stage_generation = NEW.subject_stage_generation
              AND turn.task_epoch = NEW.subject_task_epoch
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.attempt = NEW.subject_attempt
              AND turn.expected_code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND turn.expected_head_sha IS NEW.subject_expected_head_sha
              AND turn.expected_base_sha IS NEW.subject_expected_base_sha
              AND turn.status = 'SUCCEEDED')
            THEN RAISE(ABORT, 'Stage receipt fix result proof is invalid')
        WHEN NEW.cause = 'SUBMIT_LOCAL_FEEDBACK' AND NOT EXISTS (
            SELECT 1 FROM local_feedback_batch batch
            WHERE batch.id = NEW.proof_id
              AND batch.task_id = NEW.task_id
              AND batch.local_development_stage_id = NEW.stage_id
              AND batch.stage_generation = NEW.returned_generation
              AND batch.status IN ('FROZEN', 'DISPATCHED', 'ADDRESSED'))
            THEN RAISE(ABORT, 'Stage receipt feedback proof is invalid')
        WHEN NEW.cause = 'AUTHORIZE_PUBLISH' AND NOT EXISTS (
            SELECT 1 FROM publish_authorization authorization
            WHERE authorization.id = NEW.proof_id
              AND authorization.task_id = NEW.task_id
              AND authorization.task_epoch = NEW.subject_task_epoch
              AND authorization.local_development_stage_id = NEW.stage_id
              AND authorization.stage_generation = NEW.subject_stage_generation
              AND authorization.authorized_operation_id = NEW.subject_operation_id
              AND authorization.authorized_attempt = NEW.subject_attempt
              AND authorization.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND authorization.head_sha IS NEW.subject_expected_head_sha
              AND authorization.base_sha IS NEW.subject_expected_base_sha
              AND authorization.revoked_at_ms IS NULL
              AND authorization.consumed_at_ms IS NULL
              AND NEW.returned_pending_task_epoch IS NEW.subject_task_epoch
              AND NEW.returned_pending_stage_id IS NEW.subject_stage_id
              AND NEW.returned_pending_stage_generation
                    IS NEW.subject_stage_generation
              AND NEW.returned_pending_operation_id IS NEW.subject_operation_id
              AND NEW.returned_pending_attempt IS NEW.subject_attempt
              AND NEW.returned_pending_code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND NEW.returned_pending_head_sha IS NEW.subject_expected_head_sha
              AND NEW.returned_pending_base_sha IS NEW.subject_expected_base_sha)
            THEN RAISE(ABORT, 'Stage receipt publish authorization proof is invalid')
        WHEN NEW.cause = 'OPEN_REMOTE_DEVELOPMENT' AND NOT EXISTS (
            SELECT 1 FROM remote_pr_binding binding
            JOIN publish_operation operation
              ON operation.id = binding.publish_operation_id
            WHERE binding.task_id = NEW.task_id
              AND operation.local_development_stage_id = NEW.subject_stage_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.stage_generation = NEW.subject_stage_generation
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.semantic_attempt = NEW.subject_attempt
              AND operation.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND operation.expected_head_sha IS NEW.subject_expected_head_sha
              AND operation.expected_base_sha IS NEW.subject_expected_base_sha
              AND operation.status = 'SUCCEEDED'
              AND NEW.returned_kind = 'REMOTE_DEVELOPMENT'
              AND NEW.returned_checkpoint = 'WAITING_CI')
            THEN RAISE(ABORT, 'Stage receipt remote opening proof is invalid')
        WHEN NEW.cause = 'ACCEPT_PUBLISHED' AND NOT EXISTS (
            SELECT 1 FROM remote_pr_binding binding
            JOIN publish_operation operation
              ON operation.id = binding.publish_operation_id
            WHERE binding.task_id = NEW.task_id
              AND operation.local_development_stage_id = NEW.stage_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.stage_generation = NEW.subject_stage_generation
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.semantic_attempt = NEW.subject_attempt
              AND operation.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND operation.expected_head_sha IS NEW.subject_expected_head_sha
              AND operation.expected_base_sha IS NEW.subject_expected_base_sha
              AND operation.status = 'SUCCEEDED')
            THEN RAISE(ABORT, 'Stage receipt remote binding proof is invalid')
        WHEN NEW.returned_checkpoint = 'PUBLISHING'
              AND NEW.cause <> 'AUTHORIZE_PUBLISH'
            THEN RAISE(ABORT, 'LOCAL_REVIEW to PUBLISHING requires PublishAuthorization')
    END;
END;
CREATE TRIGGER stage_command_receipt_local_id_collision
BEFORE INSERT ON stage_command_receipt
WHEN EXISTS (SELECT 1 FROM local_stage_command_receipt local
             WHERE local.stage_id = NEW.stage_id
               AND local.command_id = NEW.command_id)
BEGIN SELECT RAISE(ABORT, 'Stage command id is already used by Local Development'); END;
CREATE TRIGGER stage_command_receipt_v230_feedback_proof
BEFORE INSERT ON stage_command_receipt
WHEN NEW.cause = 'SUBMIT_LOCAL_FEEDBACK'
  AND NOT EXISTS (
      SELECT 1 FROM local_feedback_batch batch
      JOIN local_feedback_batch_digest_v230 digest ON digest.batch_id = batch.id
      WHERE batch.id = NEW.proof_id AND batch.task_id = NEW.task_id
        AND batch.task_epoch = NEW.expected_task_epoch
        AND batch.local_development_stage_id = NEW.stage_id
        AND batch.stage_generation = NEW.expected_stage_generation
        AND batch.stage_generation = NEW.returned_generation
        AND batch.source_submission_id IS NOT NULL
        AND batch.content_digest = digest.content_digest
        AND batch.status IN ('FROZEN', 'QUEUED', 'DISPATCHED')
        AND NEW.source_checkpoint = 'LOCAL_REVIEW'
        AND NEW.returned_kind = 'LOCAL_DEVELOPMENT'
        AND NEW.returned_checkpoint = 'ADDRESSING_LOCAL_FEEDBACK')
BEGIN SELECT RAISE(ABORT, 'Stage receipt LocalFeedbackBatch digest is not exact'); END;
CREATE TRIGGER stage_initial_result_request_delete_guard
BEFORE DELETE ON stage_initial_result_request
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'initial Stage result request cannot be deleted'); END;
CREATE TRIGGER stage_initial_result_request_immutable
BEFORE UPDATE ON stage_initial_result_request
BEGIN SELECT RAISE(ABORT, 'initial Stage result request is immutable'); END;
CREATE TRIGGER stage_initial_result_request_insert
BEFORE INSERT ON stage_initial_result_request
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM stage s
            JOIN tasks task ON task.id = s.task_id
            JOIN task_current_stage current ON current.task_id = task.id
            WHERE s.id = NEW.stage_id
              AND s.task_id = NEW.task_id
              AND s.kind = NEW.stage_kind
              AND s.generation = NEW.expected_stage_generation
              AND s.version = NEW.returned_stage_version
              AND s.checkpoint = NEW.checkpoint
              AND s.completed_at_ms IS NULL
              AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.expected_task_epoch
              AND current.stage_id = s.id
              AND current.stage_generation = s.generation)
            THEN RAISE(ABORT, 'initial result request lacks its exact Stage owner')
        WHEN NEW.pending_task_epoch <> NEW.expected_task_epoch
            THEN RAISE(ABORT, 'initial result request has a stale Task epoch')
        WHEN NEW.turn_owner_kind = 'TASK_TURN' AND NOT EXISTS (
            SELECT 1 FROM task_turn turn
            WHERE turn.id = NEW.turn_id
              AND turn.task_id = NEW.task_id
              AND turn.task_epoch = NEW.pending_task_epoch
              AND turn.trigger_stage_id = NEW.stage_id
              AND turn.trigger_stage_generation = NEW.pending_stage_generation
              AND turn.operation_id = NEW.pending_operation_id
              AND turn.attempt = NEW.pending_attempt
              AND turn.expected_code_fingerprint IS NEW.pending_code_fingerprint
              AND turn.expected_head_sha IS NEW.pending_head_sha
              AND turn.expected_base_sha IS NEW.pending_base_sha
              AND turn.status = 'REQUESTED'
              AND ((NEW.cause = 'REQUEST_PLAN_DRAFT'
                    AND turn.purpose = 'PLAN_DRAFT')))
            THEN RAISE(ABORT, 'initial result request lacks its exact TaskTurn')
        WHEN NEW.turn_owner_kind = 'STAGE_TURN' AND NOT EXISTS (
            SELECT 1 FROM stage_turn turn
            WHERE turn.id = NEW.turn_id
              AND turn.stage_id = NEW.stage_id
              AND turn.stage_generation = NEW.pending_stage_generation
              AND turn.task_epoch = NEW.pending_task_epoch
              AND turn.operation_id = NEW.pending_operation_id
              AND turn.attempt = NEW.pending_attempt
              AND turn.expected_code_fingerprint IS NEW.pending_code_fingerprint
              AND turn.expected_head_sha IS NEW.pending_head_sha
              AND turn.expected_base_sha IS NEW.pending_base_sha
              AND turn.status = 'QUEUED'
              AND NEW.cause = 'REQUEST_LOCAL_RESULT'
              AND turn.purpose = 'IMPLEMENT_LOCAL_PLAN')
            THEN RAISE(ABORT, 'initial result request lacks its exact StageTurn')
        WHEN NOT EXISTS (
            SELECT 1 FROM dispatch_ticket ticket
            WHERE ticket.operation_id = NEW.pending_operation_id
              AND ticket.owner_kind = NEW.turn_owner_kind
              AND ticket.owner_id = NEW.turn_id
              AND ticket.task_id = NEW.task_id
              AND ticket.task_epoch = NEW.pending_task_epoch
              AND ticket.stage_id = NEW.stage_id
              AND ticket.stage_generation = NEW.pending_stage_generation
              AND ticket.attempt = NEW.pending_attempt
              AND ticket.expected_code_fingerprint IS NEW.pending_code_fingerprint
              AND ticket.expected_head_sha IS NEW.pending_head_sha
              AND ticket.expected_base_sha IS NEW.pending_base_sha
              AND ticket.status = 'REQUESTED'
              AND ((NEW.turn_owner_kind = 'TASK_TURN'
                    AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
                    AND ticket.async_family = 'AGENT_TURN'
                    AND ticket.callback_route = 'TASK_TURN_RESULT')
                OR (NEW.turn_owner_kind = 'STAGE_TURN'
                    AND ticket.operation_kind = 'EXECUTE_STAGE_TURN'
                    AND ticket.async_family = 'AGENT_TURN'
                    AND ticket.callback_route = 'STAGE_TURN_RESULT')))
            THEN RAISE(ABORT, 'initial result request lacks its exact DispatchTicket')
    END;
END;
CREATE TRIGGER stage_plan_edit_review_request_immutable
BEFORE UPDATE ON stage_plan_edit_review_request
BEGIN SELECT RAISE(ABORT, 'edited Plan review request is immutable'); END;
CREATE TRIGGER stage_plan_edit_review_request_insert
BEFORE INSERT ON stage_plan_edit_review_request
WHEN NOT EXISTS (
    SELECT 1
    FROM stage s
    JOIN tasks task ON task.id = s.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN plan_revision revision ON revision.id = NEW.revision_id
    JOIN task_turn turn ON turn.operation_id = NEW.pending_operation_id
    JOIN dispatch_ticket ticket ON ticket.operation_id = turn.operation_id
    JOIN stage_transition transition
      ON transition.stage_id = s.id
     AND transition.command_id = NEW.command_id
    WHERE s.id = NEW.stage_id AND s.task_id = NEW.task_id
      AND s.kind = 'PLAN' AND s.generation = NEW.expected_stage_generation
      AND s.version = NEW.returned_stage_version
      AND s.checkpoint = 'SELF_REVIEW' AND s.completed_at_ms IS NULL
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.expected_task_epoch
      AND current.stage_id = s.id
      AND current.stage_generation = s.generation
      AND revision.plan_stage_id = s.id
      AND NOT EXISTS (
          SELECT 1 FROM plan_revision newer
          WHERE newer.plan_stage_id = revision.plan_stage_id
            AND newer.revision > revision.revision)
      AND turn.task_id = task.id AND turn.task_epoch = task.epoch
      AND turn.trigger_stage_id = s.id
      AND turn.trigger_stage_generation = s.generation
      AND turn.purpose = 'PLAN_SELF_REVIEW' AND turn.status = 'REQUESTED'
      AND turn.expected_code_fingerprint = NEW.pending_code_fingerprint
      AND turn.expected_head_sha = NEW.pending_head_sha
      AND turn.expected_base_sha = NEW.pending_base_sha
      AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.status = 'REQUESTED'
      AND transition.generation = s.generation
      AND transition.from_checkpoint = 'DRAFTING'
      AND transition.to_checkpoint = 'SELF_REVIEW'
      AND transition.stage_version = s.version
      AND transition.cause = 'REQUEST_EDITED_PLAN_SELF_REVIEW'
      AND transition.actor = NEW.actor)
BEGIN SELECT RAISE(ABORT, 'edited Plan review request lacks its exact owner'); END;
CREATE TRIGGER stage_plan_review_retry_request_immutable
BEFORE UPDATE ON stage_plan_review_retry_request
BEGIN SELECT RAISE(ABORT, 'Plan self-review retry request is immutable'); END;
CREATE TRIGGER stage_plan_review_retry_request_insert
BEFORE INSERT ON stage_plan_review_retry_request
WHEN NOT EXISTS (
    SELECT 1
    FROM stage s
    JOIN tasks task ON task.id = s.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN plan_self_review review ON review.id = NEW.self_review_id
    JOIN plan_revision revision ON revision.id = review.plan_revision_id
    JOIN task_turn failed ON failed.id = NEW.predecessor_turn_id
    JOIN plan_self_review_attempt retry
      ON retry.self_review_id = review.id AND retry.attempt = 2
    JOIN task_turn replacement ON replacement.id = NEW.replacement_turn_id
    JOIN dispatch_ticket ticket ON ticket.operation_id = replacement.operation_id
    JOIN stage_transition transition
      ON transition.stage_id = s.id AND transition.command_id = NEW.command_id
    WHERE s.id = NEW.stage_id AND s.task_id = NEW.task_id
      AND s.kind = 'PLAN' AND s.checkpoint = 'SELF_REVIEW'
      AND s.version = NEW.returned_stage_version
      AND s.completed_at_ms IS NULL
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.subject_task_epoch
      AND current.stage_id = s.id AND current.stage_generation = s.generation
      AND revision.plan_stage_id = s.id AND review.status = 'REQUESTED'
      AND failed.id = retry.predecessor_turn_id
      AND failed.operation_id = NEW.subject_operation_id
      AND failed.status = 'FAILED'
      AND failed.trigger_stage_id = s.id
      AND failed.trigger_stage_generation = NEW.subject_stage_generation
      AND failed.trigger_stage_generation = s.generation
      AND failed.expected_code_fingerprint = NEW.subject_code_fingerprint
      AND failed.expected_head_sha = NEW.subject_head_sha
      AND failed.expected_base_sha = NEW.subject_base_sha
      AND replacement.id = retry.task_turn_id
      AND replacement.operation_id = NEW.pending_operation_id
      AND replacement.status = 'REQUESTED'
      AND replacement.trigger_stage_id = s.id
      AND replacement.trigger_stage_generation = s.generation
      AND replacement.expected_code_fingerprint = NEW.pending_code_fingerprint
      AND replacement.expected_head_sha = NEW.pending_head_sha
      AND replacement.expected_base_sha = NEW.pending_base_sha
      AND ticket.owner_kind = 'TASK_TURN'
      AND ticket.owner_id = replacement.id
      AND ticket.status = 'REQUESTED'
      AND transition.generation = s.generation
      AND transition.from_checkpoint = 'SELF_REVIEW'
      AND transition.to_checkpoint = 'SELF_REVIEW'
      AND transition.stage_version = s.version
      AND transition.cause = 'RETRY_PLAN_SELF_REVIEW'
      AND transition.actor = NEW.actor)
BEGIN SELECT RAISE(ABORT, 'Plan self-review retry request is not exact'); END;
CREATE TRIGGER stage_plan_terminal_result_immutable
BEFORE UPDATE ON stage_plan_terminal_result
BEGIN SELECT RAISE(ABORT, 'Plan terminal result is immutable'); END;
CREATE TRIGGER stage_plan_terminal_result_insert
BEFORE INSERT ON stage_plan_terminal_result
WHEN NOT EXISTS (
    SELECT 1
    FROM stage s
    JOIN tasks task ON task.id = s.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN task_turn turn ON turn.operation_id = NEW.subject_operation_id
    JOIN stage_transition transition
      ON transition.stage_id = s.id AND transition.command_id = NEW.command_id
    WHERE s.id = NEW.stage_id AND s.task_id = NEW.task_id
      AND s.kind = 'PLAN' AND s.checkpoint = NEW.checkpoint
      AND s.version = NEW.returned_stage_version
      AND s.completed_at_ms IS NULL
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.subject_task_epoch
      AND current.stage_id = s.id AND current.stage_generation = s.generation
      AND turn.task_id = task.id AND turn.task_epoch = task.epoch
      AND turn.trigger_stage_id = s.id
      AND turn.trigger_stage_generation = NEW.subject_stage_generation
      AND turn.trigger_stage_generation = s.generation
      AND turn.expected_code_fingerprint = NEW.subject_code_fingerprint
      AND turn.expected_head_sha = NEW.subject_head_sha
      AND turn.expected_base_sha = NEW.subject_base_sha
      AND turn.status IN ('SUCCEEDED', 'FAILED', 'CANCELED')
      AND ((NEW.cause = 'PLAN_DRAFT_FAILED' AND turn.purpose = 'PLAN_DRAFT')
        OR (NEW.cause <> 'PLAN_DRAFT_FAILED'
            AND turn.purpose = 'PLAN_SELF_REVIEW'))
      AND transition.generation = s.generation
      AND transition.from_checkpoint = NEW.checkpoint
      AND transition.to_checkpoint = NEW.checkpoint
      AND transition.stage_version = s.version
      AND transition.cause = NEW.cause
      AND transition.actor = NEW.actor)
BEGIN SELECT RAISE(ABORT, 'Plan terminal result is not exact'); END;
CREATE TRIGGER stage_question_answer_transition
BEFORE UPDATE OF state, answer, answer_revision, answered_at_ms,
        answer_option_id, answer_free_form, answer_actor
ON stage_question
WHEN NEW.state IS NOT OLD.state
BEGIN
    SELECT CASE WHEN OLD.state <> 'OPEN'
        OR NEW.state NOT IN ('ANSWERED', 'CANCELED')
        OR NEW.answer_revision <> OLD.answer_revision + 1
        OR NEW.answer_actor IS NULL OR length(trim(NEW.answer_actor)) = 0
        OR NEW.answer IS NULL OR length(trim(NEW.answer)) = 0
        OR NEW.answered_at_ms IS NULL OR NEW.answered_at_ms < OLD.created_at_ms
        OR NEW.state = 'ANSWERED'
            AND NEW.answer_option_id IS NULL AND NEW.answer_free_form IS NULL
        OR NEW.state = 'CANCELED' AND NEW.continuation_state <> 'CANCELED'
    THEN RAISE(ABORT, 'stage question answer transition is invalid') END;
END;
CREATE TRIGGER stage_question_continuation_scope
BEFORE UPDATE OF continuation_state, successor_turn_id ON stage_question
WHEN NEW.continuation_state = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1
    FROM stage_turn source
    JOIN stage_turn successor ON successor.id = NEW.successor_turn_id
    WHERE source.id = OLD.turn_id
      AND successor.id <> source.id
      AND successor.stage_id = source.stage_id
      AND successor.stage_generation = source.stage_generation
      AND successor.task_epoch = source.task_epoch
      AND successor.expected_code_fingerprint IS source.expected_code_fingerprint
      AND successor.expected_head_sha IS source.expected_head_sha
      AND successor.expected_base_sha IS source.expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'stage question successor fence is stale'); END;
CREATE TRIGGER stage_question_continuation_transition
BEFORE UPDATE OF continuation_state, successor_turn_id, continuation_error
ON stage_question
BEGIN
    SELECT CASE WHEN OLD.continuation_state = 'WAITING'
            AND NEW.continuation_state NOT IN ('WAITING', 'READY', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state = 'READY'
            AND NEW.continuation_state NOT IN ('READY', 'DISPATCHED', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state IN ('DISPATCHED', 'CANCELED', 'SUPERSEDED')
            AND (NEW.continuation_state IS NOT OLD.continuation_state
                OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
                OR NEW.continuation_error IS NOT OLD.continuation_error)
        OR NEW.continuation_state = 'DISPATCHED' AND NEW.successor_turn_id IS NULL
    THEN RAISE(ABORT, 'stage question continuation is invalid') END;
END;
CREATE TRIGGER stage_question_identity_immutable
BEFORE UPDATE ON stage_question
WHEN NEW.id IS NOT OLD.id OR NEW.turn_id IS NOT OLD.turn_id
  OR NEW.call_id IS NOT OLD.call_id OR NEW.prompt IS NOT OLD.prompt
  OR NEW.context IS NOT OLD.context
  OR NEW.options_json IS NOT OLD.options_json
  OR NEW.allow_free_form IS NOT OLD.allow_free_form
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'stage question identity is immutable'); END;
CREATE TRIGGER stage_question_open_invariant
BEFORE UPDATE ON stage_question
WHEN OLD.state = 'OPEN' AND NEW.state = 'OPEN'
 AND (NEW.answer IS NOT OLD.answer
   OR NEW.answer_revision IS NOT OLD.answer_revision
   OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
   OR NEW.answer_option_id IS NOT OLD.answer_option_id
   OR NEW.answer_free_form IS NOT OLD.answer_free_form
   OR NEW.answer_actor IS NOT OLD.answer_actor
   OR NEW.continuation_state IS NOT OLD.continuation_state
   OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
   OR NEW.continuation_error IS NOT OLD.continuation_error)
BEGIN SELECT RAISE(ABORT, 'open stage question is immutable'); END;
CREATE TRIGGER stage_question_terminal_immutable
BEFORE UPDATE ON stage_question
WHEN OLD.state <> 'OPEN'
  AND (NEW.state IS NOT OLD.state OR NEW.answer IS NOT OLD.answer
    OR NEW.answer_revision IS NOT OLD.answer_revision
    OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
    OR NEW.answer_option_id IS NOT OLD.answer_option_id
    OR NEW.answer_free_form IS NOT OLD.answer_free_form
    OR NEW.answer_actor IS NOT OLD.answer_actor)
BEGIN SELECT RAISE(ABORT, 'terminal stage question is immutable'); END;
CREATE TRIGGER stage_resume_async_successor_identity_v272
BEFORE UPDATE OF handoff_id, command_id, owner_kind, owner_id, operation_id,
        dispatch_ticket_id, dispatch_attempt, domain_attempt, created_at_ms
ON stage_resume_async_successor_v272
BEGIN SELECT RAISE(ABORT, 'Async resume successor identity is immutable'); END;
CREATE TRIGGER stage_resume_async_successor_insert_v272
BEFORE INSERT ON stage_resume_async_successor_v272
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_resume_rearm_intent_v257 intent
    JOIN task_resume_handoff_v256 handoff ON handoff.id = intent.handoff_id
    JOIN tasks task ON task.id = intent.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE intent.handoff_id = NEW.handoff_id
      AND intent.status = 'PENDING' AND handoff.status = 'ACCEPTED'
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = intent.task_epoch
      AND current.stage_id = intent.stage_id
      AND current.stage_generation = intent.stage_generation
      AND owner.kind = intent.stage_kind
      AND owner.generation = intent.stage_generation
      AND owner.version = intent.stage_version
      AND owner.checkpoint = intent.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND code.code_fingerprint = intent.code_fingerprint
      AND code.head_sha = intent.head_sha AND code.base_sha = intent.base_sha
      AND ((NEW.owner_kind = 'PLAN_SELF_REVIEW'
              AND intent.stage_kind = 'PLAN'
              AND intent.restore_checkpoint = 'SELF_REVIEW')
        OR (NEW.owner_kind = 'LOCAL_VALIDATION'
              AND intent.stage_kind = 'LOCAL_DEVELOPMENT'
              AND intent.restore_checkpoint = 'VALIDATING')
        OR (NEW.owner_kind = 'DEVELOPMENT_BRAIN_REVIEW'
              AND intent.stage_kind = 'LOCAL_DEVELOPMENT'
              AND intent.restore_checkpoint = 'BRAIN_REVIEW')
        OR (NEW.owner_kind = 'PUBLISH_RECOVERY'
              AND intent.stage_kind = 'LOCAL_DEVELOPMENT'
              AND intent.restore_checkpoint = 'PUBLISHING')
        OR (NEW.owner_kind = 'MERGE_RECOVERY'
              AND intent.stage_kind = 'REMOTE_DEVELOPMENT'
              AND intent.restore_checkpoint = 'MERGING')))
BEGIN SELECT RAISE(ABORT, 'Async resume successor owner fence is stale'); END;
CREATE TRIGGER stage_resume_async_successor_terminal_v272
BEFORE UPDATE ON stage_resume_async_successor_v272
WHEN OLD.status = 'ARMED'
BEGIN SELECT RAISE(ABORT, 'armed async resume successor is immutable'); END;
CREATE TRIGGER stage_resume_async_successor_transition_v272
BEFORE UPDATE OF status ON stage_resume_async_successor_v272
WHEN OLD.status <> 'PREPARED' OR NEW.status <> 'ARMED'
  OR NEW.armed_at_ms IS NULL
BEGIN SELECT RAISE(ABORT, 'illegal async resume successor transition'); END;
CREATE TRIGGER stage_resume_budget_lineage_immutable_v272
BEFORE UPDATE ON stage_resume_budget_lineage_v272
BEGIN SELECT RAISE(ABORT, 'Async resume budget lineage is immutable'); END;
CREATE TRIGGER stage_resume_budget_lineage_insert_v272
BEFORE INSERT ON stage_resume_budget_lineage_v272
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_resume_async_successor_v272 successor
    JOIN stage_resume_rearm_intent_v257 intent
      ON intent.handoff_id = successor.handoff_id
    WHERE successor.handoff_id = NEW.handoff_id
      AND successor.status = 'PREPARED'
      AND successor.owner_kind = NEW.owner_kind
      AND successor.owner_id = NEW.successor_owner_id
      AND successor.domain_attempt = NEW.execution_attempt
      AND intent.status = 'PENDING'
      AND NEW.execution_attempt > NEW.budget_attempt
      AND ((NEW.owner_kind = 'LOCAL_VALIDATION' AND EXISTS (
            SELECT 1
            FROM validation_operation predecessor
            JOIN validation_operation replacement
              ON replacement.id = NEW.successor_owner_id
            WHERE predecessor.id = NEW.predecessor_owner_id
              AND predecessor.status = 'CANCELED'
              AND replacement.task_id = predecessor.task_id
              AND replacement.task_epoch = predecessor.task_epoch
              AND replacement.local_development_stage_id =
                    predecessor.local_development_stage_id
              AND replacement.stage_generation = predecessor.stage_generation
              AND replacement.dev_report_id = predecessor.dev_report_id
              AND replacement.code_fingerprint = predecessor.code_fingerprint
              AND replacement.expected_head_sha = predecessor.expected_head_sha
              AND replacement.expected_base_sha = predecessor.expected_base_sha
              AND replacement.semantic_attempt = predecessor.semantic_attempt + 1
              AND NEW.execution_attempt = replacement.semantic_attempt
              AND NEW.budget_attempt = COALESCE((
                    SELECT prior.budget_attempt
                    FROM stage_resume_budget_lineage_v272 prior
                    WHERE prior.owner_kind = 'LOCAL_VALIDATION'
                      AND prior.successor_owner_id = predecessor.id),
                    predecessor.semantic_attempt)))
        OR (NEW.owner_kind = 'DEVELOPMENT_BRAIN_REVIEW' AND EXISTS (
            SELECT 1
            FROM brain_review_episode predecessor
            JOIN brain_review_episode replacement
              ON replacement.id = NEW.successor_owner_id
            WHERE predecessor.id = NEW.predecessor_owner_id
              AND predecessor.status IN ('CANCELED', 'SUPERSEDED')
              AND replacement.task_brain_id = predecessor.task_brain_id
              AND replacement.task_id = predecessor.task_id
              AND replacement.task_epoch = predecessor.task_epoch
              AND replacement.local_development_stage_id =
                    predecessor.local_development_stage_id
              AND replacement.stage_generation = predecessor.stage_generation
              AND replacement.dev_report_id = predecessor.dev_report_id
              AND replacement.validation_evidence_id =
                    predecessor.validation_evidence_id
              AND replacement.code_fingerprint = predecessor.code_fingerprint
              AND replacement.expected_head_sha = predecessor.expected_head_sha
              AND replacement.expected_base_sha = predecessor.expected_base_sha
              AND replacement.semantic_attempt = predecessor.semantic_attempt + 1
              AND NEW.execution_attempt = replacement.semantic_attempt
              AND NEW.budget_attempt = COALESCE((
                    SELECT prior.budget_attempt
                    FROM stage_resume_budget_lineage_v272 prior
                    WHERE prior.owner_kind = 'DEVELOPMENT_BRAIN_REVIEW'
                      AND prior.successor_owner_id = predecessor.id),
                    predecessor.semantic_attempt)))))
BEGIN SELECT RAISE(ABORT, 'Async resume budget lineage is not exact'); END;
CREATE TRIGGER stage_resume_passive_wait_immutable_v263
BEFORE UPDATE ON stage_resume_passive_wait_v263
BEGIN SELECT RAISE(ABORT, 'passive resume wait is immutable'); END;
CREATE TRIGGER stage_resume_passive_wait_insert_v263
BEFORE INSERT ON stage_resume_passive_wait_v263
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_resume_rearm_intent_v257 intent
    JOIN task_resume_handoff_v256 handoff ON handoff.id = intent.handoff_id
    JOIN tasks task ON task.id = intent.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    WHERE intent.handoff_id = NEW.handoff_id
      AND intent.status = 'PENDING' AND handoff.status = 'ACCEPTED'
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = intent.task_epoch
      AND current.stage_id = intent.stage_id
      AND current.stage_generation = intent.stage_generation
      AND owner.id = NEW.stage_id
      AND owner.generation = NEW.stage_generation
      AND owner.checkpoint = NEW.checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND ((NEW.wait_kind = 'PLAN_APPROVAL'
            AND owner.kind = 'PLAN'
            AND NEW.checkpoint = 'AWAITING_APPROVAL')
        OR (NEW.wait_kind = 'LOCAL_REVIEW'
            AND owner.kind = 'LOCAL_DEVELOPMENT'
            AND NEW.checkpoint = 'LOCAL_REVIEW')))
BEGIN SELECT RAISE(ABORT, 'passive resume wait owner is stale'); END;
CREATE TRIGGER stage_resume_rearm_identity_immutable_v257
BEFORE UPDATE OF handoff_id, owner_proof_id, accepted_by, task_id, task_epoch,
        task_version, stage_id, stage_kind, stage_generation, stage_version,
        restore_checkpoint, reconciliation_id, code_fingerprint, head_sha,
        base_sha, accepted_at_ms
ON stage_resume_rearm_intent_v257
BEGIN SELECT RAISE(ABORT, 'Resume rearm intent identity is immutable'); END;
CREATE TRIGGER stage_resume_rearm_intent_insert_v257
BEFORE INSERT ON stage_resume_rearm_intent_v257
WHEN NEW.status <> 'PENDING' OR NOT EXISTS (
    SELECT 1
    FROM task_resume_handoff_v256 handoff
    JOIN tasks task ON task.id = handoff.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE handoff.id = NEW.handoff_id AND handoff.status = 'PENDING'
      AND handoff.task_id = NEW.task_id
      AND handoff.task_epoch = NEW.task_epoch
      AND handoff.task_version = NEW.task_version
      AND handoff.reconciliation_id = NEW.reconciliation_id
      AND handoff.stage_id = NEW.stage_id
      AND handoff.stage_kind = NEW.stage_kind
      AND handoff.stage_generation = NEW.stage_generation
      AND handoff.stage_version = NEW.stage_version
      AND handoff.restore_checkpoint = NEW.restore_checkpoint
      AND handoff.code_fingerprint = NEW.code_fingerprint
      AND handoff.head_sha = NEW.head_sha AND handoff.base_sha = NEW.base_sha
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'RESUMING'
      AND task.epoch = NEW.task_epoch
      AND task.aggregate_version = NEW.task_version
      AND current.stage_id = NEW.stage_id
      AND current.stage_generation = NEW.stage_generation
      AND owner.kind = NEW.stage_kind
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.stage_version
      AND owner.checkpoint = NEW.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND code.code_fingerprint = NEW.code_fingerprint
      AND code.head_sha = NEW.head_sha AND code.base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Resume rearm intent fence is stale'); END;
CREATE TRIGGER stage_resume_rearm_materialize_v257
BEFORE UPDATE OF status ON stage_resume_rearm_intent_v257
WHEN NEW.status = 'MATERIALIZED'
 AND NOT EXISTS (
    SELECT 1
    FROM stage_resume_passive_wait_v263 passive
    JOIN tasks task ON task.id = OLD.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    WHERE passive.handoff_id = OLD.handoff_id
      AND passive.stage_id = OLD.stage_id
      AND passive.stage_generation = OLD.stage_generation
      AND passive.checkpoint = OLD.restore_checkpoint
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = OLD.task_epoch
      AND current.stage_id = OLD.stage_id
      AND current.stage_generation = OLD.stage_generation
      AND owner.kind = OLD.stage_kind
      AND owner.generation = OLD.stage_generation
      AND owner.checkpoint = OLD.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND ((passive.wait_kind = 'PLAN_APPROVAL'
            AND OLD.stage_kind = 'PLAN'
            AND OLD.restore_checkpoint = 'AWAITING_APPROVAL')
        OR (passive.wait_kind = 'LOCAL_REVIEW'
            AND OLD.stage_kind = 'LOCAL_DEVELOPMENT'
            AND OLD.restore_checkpoint = 'LOCAL_REVIEW')))
 AND NOT EXISTS (
    SELECT 1
    FROM stage_resume_rearm_successor_v257 successor
    JOIN tasks task ON task.id = OLD.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    WHERE successor.handoff_id = OLD.handoff_id
      AND successor.status = 'ARMED'
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = OLD.task_epoch
      AND current.stage_id = OLD.stage_id
      AND current.stage_generation = OLD.stage_generation
      AND owner.kind = OLD.stage_kind
      AND owner.generation = OLD.stage_generation
      AND owner.checkpoint = OLD.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND ((successor.owner_kind = 'REMOTE_OBSERVATION'
            AND OLD.stage_kind = 'REMOTE_DEVELOPMENT'
            AND OLD.restore_checkpoint IN (
                'WAITING_CI', 'AWAITING_READY', 'WAITING_REMOTE_REVIEW',
                'READY_TO_MERGE')
            AND successor.purpose = 'REMOTE_OBSERVATION'
            AND successor.returned_stage_version IS NULL
            AND EXISTS (
                SELECT 1 FROM remote_observation_operation operation
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE operation.id = successor.owner_id
                  AND operation.operation_id = successor.operation_id
                  AND operation.semantic_attempt = successor.semantic_attempt
                  AND operation.task_id = OLD.task_id
                  AND operation.task_epoch = OLD.task_epoch
                  AND operation.remote_development_stage_id = OLD.stage_id
                  AND operation.stage_generation = OLD.stage_generation
                  AND operation.expected_head_sha = OLD.head_sha
                  AND operation.expected_base_sha = OLD.base_sha
                  AND operation.status = 'DISPATCHED'
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.async_family = 'REMOTE_OBSERVATION'
                  AND ticket.owner_kind = 'STAGE'
                  AND ticket.owner_id = OLD.stage_id
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.semantic_attempt
                  AND ticket.expected_code_fingerprint IS NULL
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))
        OR (successor.owner_kind = 'TASK_TURN'
            AND OLD.stage_kind = 'PLAN'
            AND OLD.restore_checkpoint = 'DRAFTING'
            AND successor.purpose = 'PLAN_DRAFT'
            AND successor.returned_stage_version = owner.version
            AND EXISTS (
                SELECT 1 FROM task_turn turn
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE turn.id = successor.owner_id
                  AND turn.operation_id = successor.operation_id
                  AND turn.attempt = successor.semantic_attempt
                  AND turn.task_id = OLD.task_id
                  AND turn.task_epoch = OLD.task_epoch
                  AND turn.trigger_stage_id = OLD.stage_id
                  AND turn.trigger_stage_generation = OLD.stage_generation
                  AND turn.purpose = successor.purpose
                  AND turn.expected_code_fingerprint = OLD.code_fingerprint
                  AND turn.expected_head_sha = OLD.head_sha
                  AND turn.expected_base_sha = OLD.base_sha
                  AND turn.status = 'REQUESTED'
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.async_family = 'AGENT_TURN'
                  AND ticket.owner_kind = 'TASK_TURN'
                  AND ticket.owner_id = successor.owner_id
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.semantic_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))
        OR (successor.owner_kind = 'STAGE_TURN'
            AND ((OLD.stage_kind = 'LOCAL_DEVELOPMENT'
                  AND (OLD.restore_checkpoint = 'IMPLEMENTING'
                       AND successor.purpose = 'IMPLEMENT_LOCAL_PLAN'
                    OR OLD.restore_checkpoint = 'ADDRESSING_BRAIN_FINDINGS'
                       AND successor.purpose = 'ADDRESS_BRAIN_FINDINGS'
                    OR OLD.restore_checkpoint = 'ADDRESSING_LOCAL_FEEDBACK'
                       AND successor.purpose = 'ADDRESS_LOCAL_FEEDBACK')
                  AND successor.returned_stage_version = owner.version)
              OR (OLD.stage_kind = 'REMOTE_DEVELOPMENT'
                  AND OLD.restore_checkpoint = 'ADDRESSING_REMOTE_FEEDBACK'
                  AND successor.purpose = 'ADDRESS_REMOTE_FEEDBACK'
                  AND successor.returned_stage_version IS NULL))
            AND EXISTS (
                SELECT 1 FROM stage_turn turn
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE turn.id = successor.owner_id
                  AND turn.operation_id = successor.operation_id
                  AND turn.attempt = successor.semantic_attempt
                  AND turn.stage_id = OLD.stage_id
                  AND turn.stage_generation = OLD.stage_generation
                  AND turn.task_epoch = OLD.task_epoch
                  AND turn.purpose = successor.purpose
                  AND turn.expected_code_fingerprint = OLD.code_fingerprint
                  AND turn.expected_head_sha = OLD.head_sha
                  AND turn.expected_base_sha = OLD.base_sha
                  AND turn.status = 'QUEUED'
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.async_family = 'AGENT_TURN'
                  AND ticket.owner_kind = 'STAGE_TURN'
                  AND ticket.owner_id = successor.owner_id
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.semantic_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))))
 AND NOT EXISTS (
    SELECT 1
    FROM stage_resume_async_successor_v272 successor
    JOIN tasks task ON task.id = OLD.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    WHERE successor.handoff_id = OLD.handoff_id
      AND successor.status = 'ARMED'
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = OLD.task_epoch
      AND current.stage_id = OLD.stage_id
      AND current.stage_generation = OLD.stage_generation
      AND owner.kind = OLD.stage_kind
      AND owner.generation = OLD.stage_generation
      AND owner.checkpoint = OLD.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND ((successor.owner_kind = 'PLAN_SELF_REVIEW'
            AND OLD.stage_kind = 'PLAN'
            AND OLD.restore_checkpoint = 'SELF_REVIEW'
            AND successor.returned_stage_version = owner.version
            AND EXISTS (
                SELECT 1
                FROM plan_self_review_resume_attempt_v272 attempt
                JOIN task_turn turn ON turn.id = attempt.task_turn_id
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE attempt.handoff_id = successor.handoff_id
                  AND turn.id = successor.owner_id
                  AND turn.operation_id = successor.operation_id
                  AND turn.attempt = successor.dispatch_attempt
                  AND attempt.semantic_attempt = successor.domain_attempt
                  AND turn.task_id = OLD.task_id
                  AND turn.task_epoch = OLD.task_epoch
                  AND turn.trigger_stage_id = OLD.stage_id
                  AND turn.trigger_stage_generation = OLD.stage_generation
                  AND turn.purpose = 'PLAN_SELF_REVIEW'
                  AND turn.status = 'REQUESTED'
                  AND turn.expected_code_fingerprint = OLD.code_fingerprint
                  AND turn.expected_head_sha = OLD.head_sha
                  AND turn.expected_base_sha = OLD.base_sha
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
                  AND ticket.async_family = 'AGENT_TURN'
                  AND ticket.owner_kind = 'TASK_TURN'
                  AND ticket.owner_id = turn.id
                  AND ticket.callback_route = 'TASK_TURN_RESULT'
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.dispatch_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))
        OR (successor.owner_kind = 'LOCAL_VALIDATION'
            AND OLD.stage_kind = 'LOCAL_DEVELOPMENT'
            AND OLD.restore_checkpoint = 'VALIDATING'
            AND successor.returned_stage_version = owner.version
            AND EXISTS (
                SELECT 1 FROM validation_operation operation
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE operation.id = successor.owner_id
                  AND operation.operation_id = successor.operation_id
                  AND operation.semantic_attempt = successor.domain_attempt
                  AND operation.task_id = OLD.task_id
                  AND operation.task_epoch = OLD.task_epoch
                  AND operation.local_development_stage_id = OLD.stage_id
                  AND operation.stage_generation = OLD.stage_generation
                  AND operation.code_fingerprint = OLD.code_fingerprint
                  AND operation.expected_head_sha = OLD.head_sha
                  AND operation.expected_base_sha = OLD.base_sha
                  AND operation.status = 'DISPATCHED'
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.operation_kind = 'VALIDATE_LOCAL_DEVELOPMENT'
                  AND ticket.async_family = 'VALIDATION'
                  AND ticket.owner_kind = 'STAGE'
                  AND ticket.owner_id = OLD.stage_id
                  AND ticket.callback_route = 'STAGE_VALIDATION_RESULT'
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.dispatch_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'
                  AND EXISTS (
                      SELECT 1
                      FROM stage_resume_budget_lineage_v272 lineage
                      WHERE lineage.handoff_id = successor.handoff_id
                        AND lineage.owner_kind = successor.owner_kind
                        AND lineage.successor_owner_id = operation.id
                        AND lineage.execution_attempt =
                            operation.semantic_attempt
                        AND lineage.consumes_budget = 0)))
        OR (successor.owner_kind = 'DEVELOPMENT_BRAIN_REVIEW'
            AND OLD.stage_kind = 'LOCAL_DEVELOPMENT'
            AND OLD.restore_checkpoint = 'BRAIN_REVIEW'
            AND successor.returned_stage_version IS NULL
            AND EXISTS (
                SELECT 1 FROM brain_review_episode episode
                JOIN task_turn turn ON turn.id = episode.task_turn_id
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                JOIN task_brain_request_receipt receipt
                  ON receipt.command_id = successor.command_id
                WHERE episode.id = successor.owner_id
                  AND episode.semantic_attempt = successor.domain_attempt
                  AND episode.status = 'REQUESTED'
                  AND turn.operation_id = successor.operation_id
                  AND turn.attempt = successor.dispatch_attempt
                  AND turn.status = 'QUEUED'
                  AND turn.task_id = OLD.task_id
                  AND turn.task_epoch = OLD.task_epoch
                  AND turn.trigger_stage_id = OLD.stage_id
                  AND turn.trigger_stage_generation = OLD.stage_generation
                  AND turn.expected_code_fingerprint = OLD.code_fingerprint
                  AND turn.expected_head_sha = OLD.head_sha
                  AND turn.expected_base_sha = OLD.base_sha
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
                  AND ticket.async_family = 'AGENT_TURN'
                  AND ticket.owner_kind = 'TASK_TURN'
                  AND ticket.owner_id = turn.id
                  AND ticket.callback_route = 'TASK_TURN_RESULT'
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.dispatch_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'
                  AND receipt.task_id = OLD.task_id
                  AND receipt.cause = 'REQUEST_BRAIN_REVIEW'
                  AND receipt.disposition = 'APPLIED'
                  AND receipt.proof_id = episode.id
                  AND receipt.returned_pending_operation_id = successor.operation_id
                  AND receipt.returned_pending_attempt = successor.dispatch_attempt
                  AND EXISTS (
                      SELECT 1
                      FROM stage_resume_budget_lineage_v272 lineage
                      WHERE lineage.handoff_id = successor.handoff_id
                        AND lineage.owner_kind = successor.owner_kind
                        AND lineage.successor_owner_id = episode.id
                        AND lineage.execution_attempt = episode.semantic_attempt
                        AND lineage.consumes_budget = 0)))
        OR (successor.owner_kind = 'PUBLISH_RECOVERY'
            AND OLD.stage_kind = 'LOCAL_DEVELOPMENT'
            AND OLD.restore_checkpoint = 'PUBLISHING'
            AND successor.returned_stage_version = owner.version
            AND EXISTS (
                SELECT 1 FROM publish_operation operation
                JOIN publish_authorization authorization
                  ON authorization.id = operation.publish_authorization_id
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE operation.id = successor.owner_id
                  AND operation.operation_id = successor.operation_id
                  AND operation.semantic_attempt = successor.domain_attempt
                  AND operation.task_id = OLD.task_id
                  AND operation.task_epoch = OLD.task_epoch
                  AND operation.local_development_stage_id = OLD.stage_id
                  AND operation.stage_generation = OLD.stage_generation
                  AND operation.code_fingerprint = OLD.code_fingerprint
                  AND operation.expected_head_sha = OLD.head_sha
                  AND operation.expected_base_sha = OLD.base_sha
                  AND operation.status = 'DISPATCHED'
                  AND authorization.revoked_at_ms IS NULL
                  AND authorization.consumed_at_ms IS NULL
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.operation_kind = 'PUBLISH_LOCAL_DEVELOPMENT'
                  AND ticket.async_family = 'GITHUB_EFFECT'
                  AND ticket.owner_kind = 'STAGE'
                  AND ticket.owner_id = OLD.stage_id
                  AND ticket.callback_route = 'STAGE_PUBLISH_RESULT'
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.dispatch_attempt
                  AND ticket.expected_code_fingerprint = OLD.code_fingerprint
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))
        OR (successor.owner_kind = 'MERGE_RECOVERY'
            AND OLD.stage_kind = 'REMOTE_DEVELOPMENT'
            AND OLD.restore_checkpoint = 'MERGING'
            AND successor.returned_stage_version = owner.version
            AND EXISTS (
                SELECT 1 FROM remote_merge_operation operation
                JOIN remote_merge_authorization authorization
                  ON authorization.id = operation.merge_authorization_id
                JOIN dispatch_ticket ticket
                  ON ticket.id = successor.dispatch_ticket_id
                WHERE operation.id = successor.owner_id
                  AND operation.operation_id = successor.operation_id
                  AND operation.semantic_attempt = successor.domain_attempt
                  AND operation.task_id = OLD.task_id
                  AND operation.task_epoch = OLD.task_epoch
                  AND operation.remote_development_stage_id = OLD.stage_id
                  AND operation.stage_generation = OLD.stage_generation
                  AND operation.head_sha = OLD.head_sha
                  AND operation.base_sha = OLD.base_sha
                  AND operation.status IN ('REQUESTED', 'AWAITING_OBSERVATION')
                  AND authorization.status = 'CONSUMED'
                  AND ticket.operation_id = successor.operation_id
                  AND ticket.operation_kind = 'MERGE_REMOTE_PULL_REQUEST'
                  AND ticket.async_family = 'MERGE'
                  AND ticket.owner_kind = 'STAGE'
                  AND ticket.owner_id = OLD.stage_id
                  AND ticket.callback_route = 'REMOTE_MERGE_RESULT'
                  AND ticket.task_id = OLD.task_id
                  AND ticket.task_epoch = OLD.task_epoch
                  AND ticket.stage_id = OLD.stage_id
                  AND ticket.stage_generation = OLD.stage_generation
                  AND ticket.attempt = successor.dispatch_attempt
                  AND ticket.expected_code_fingerprint IS NULL
                  AND ticket.expected_head_sha = OLD.head_sha
                  AND ticket.expected_base_sha = OLD.base_sha
                  AND ticket.status = 'REQUESTED'))))
BEGIN SELECT RAISE(ABORT,
    'Resume materialization lacks its exact successor or passive wait'); END;
CREATE TRIGGER stage_resume_rearm_successor_identity_v257
BEFORE UPDATE OF handoff_id, command_id, owner_kind, owner_id, operation_id,
        dispatch_ticket_id, purpose, semantic_attempt, created_at_ms
ON stage_resume_rearm_successor_v257
BEGIN SELECT RAISE(ABORT, 'Resume successor identity is immutable'); END;
CREATE TRIGGER stage_resume_rearm_successor_insert_v257
BEFORE INSERT ON stage_resume_rearm_successor_v257
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_resume_rearm_intent_v257 intent
    JOIN task_resume_handoff_v256 handoff ON handoff.id = intent.handoff_id
    JOIN tasks task ON task.id = intent.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE intent.handoff_id = NEW.handoff_id AND intent.status = 'PENDING'
      AND handoff.status = 'ACCEPTED'
      AND task.workflow_version = 'V2' AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = intent.task_epoch
      AND current.stage_id = intent.stage_id
      AND current.stage_generation = intent.stage_generation
      AND owner.kind = intent.stage_kind
      AND owner.generation = intent.stage_generation
      AND owner.version = intent.stage_version
      AND owner.checkpoint = intent.restore_checkpoint
      AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
      AND code.code_fingerprint = intent.code_fingerprint
      AND code.head_sha = intent.head_sha AND code.base_sha = intent.base_sha)
BEGIN SELECT RAISE(ABORT, 'Resume successor owner fence is stale'); END;
CREATE TRIGGER stage_resume_rearm_successor_terminal_v257
BEFORE UPDATE ON stage_resume_rearm_successor_v257
WHEN OLD.status = 'ARMED'
BEGIN SELECT RAISE(ABORT, 'armed resume successor is immutable'); END;
CREATE TRIGGER stage_resume_rearm_successor_transition_v257
BEFORE UPDATE OF status ON stage_resume_rearm_successor_v257
WHEN OLD.status <> 'PREPARED' OR NEW.status <> 'ARMED'
  OR NEW.armed_at_ms IS NULL
BEGIN SELECT RAISE(ABORT, 'illegal resume successor transition'); END;
CREATE TRIGGER stage_resume_rearm_terminal_immutable_v257
BEFORE UPDATE ON stage_resume_rearm_intent_v257
WHEN OLD.status = 'MATERIALIZED'
BEGIN SELECT RAISE(ABORT, 'materialized resume rearm intent is immutable'); END;
CREATE TRIGGER stage_resume_rearm_transition_v257
BEFORE UPDATE OF status ON stage_resume_rearm_intent_v257
WHEN OLD.status <> 'PENDING' OR NEW.status <> 'MATERIALIZED'
  OR NEW.materialized_at_ms IS NULL
BEGIN SELECT RAISE(ABORT, 'illegal resume rearm transition'); END;
CREATE TRIGGER stage_steering_attachment_immutable_v257
BEFORE UPDATE ON stage_steering_attachment_v257
BEGIN SELECT RAISE(ABORT, 'Stage steering attachment is immutable'); END;
CREATE TRIGGER stage_steering_identity_immutable_v257
BEFORE UPDATE OF id, command_id, task_id, task_epoch, stage_id, stage_kind,
        stage_generation, accepted_stage_version, accepted_checkpoint, mode,
        body, content_digest, predecessor_owner_kind, predecessor_owner_id,
        predecessor_operation_id, predecessor_ticket_id, predecessor_attempt,
        predecessor_purpose,
        predecessor_code_fingerprint, predecessor_head_sha,
        predecessor_base_sha, cancel_intent_at_ms, requested_by,
        requested_at_ms
ON stage_steering_request_v257
BEGIN SELECT RAISE(ABORT, 'Stage steering identity is immutable'); END;
CREATE TRIGGER stage_steering_request_insert_v257
BEFORE INSERT ON stage_steering_request_v257
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'PENDING'
            THEN RAISE(ABORT, 'Stage steering must start pending')
        WHEN NOT EXISTS (
            SELECT 1 FROM stage owner
            JOIN tasks task ON task.id = owner.task_id
            JOIN task_current_stage current ON current.task_id = task.id
            WHERE owner.id = NEW.stage_id AND owner.task_id = NEW.task_id
              AND owner.kind = NEW.stage_kind
              AND owner.generation = NEW.stage_generation
              AND owner.version = NEW.accepted_stage_version
              AND owner.checkpoint = NEW.accepted_checkpoint
              AND owner.completed_at_ms IS NULL AND owner.end_reason IS NULL
              AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.task_epoch
              AND current.stage_id = owner.id
              AND current.stage_generation = owner.generation)
            THEN RAISE(ABORT, 'Stage steering owner fence is stale')
        WHEN NEW.predecessor_operation_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dispatch_ticket ticket
            WHERE ticket.id = NEW.predecessor_ticket_id
              AND ticket.operation_id = NEW.predecessor_operation_id
              AND ticket.owner_kind = NEW.predecessor_owner_kind
              AND ticket.owner_id = NEW.predecessor_owner_id
              AND ticket.task_id = NEW.task_id
              AND ticket.task_epoch = NEW.task_epoch
              AND ticket.stage_id = NEW.stage_id
              AND ticket.stage_generation = NEW.stage_generation
              AND ticket.attempt = NEW.predecessor_attempt
              AND ticket.expected_code_fingerprint IS NEW.predecessor_code_fingerprint
              AND ticket.expected_head_sha IS NEW.predecessor_head_sha
              AND ticket.expected_base_sha IS NEW.predecessor_base_sha
              AND (ticket.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED')
                OR (ticket.status = 'SUCCEEDED' AND EXISTS (
                    SELECT 1 FROM typed_user_wait_result result
                    WHERE result.operation_id = ticket.operation_id
                      AND result.owner_kind = 'STAGE_TURN'
                      AND result.turn_id = ticket.owner_id)))
              AND ticket.owner_kind = 'STAGE_TURN'
              AND EXISTS (SELECT 1 FROM stage_turn turn
                  WHERE turn.id = ticket.owner_id
                    AND turn.operation_id = ticket.operation_id
                    AND turn.purpose = NEW.predecessor_purpose))
            THEN RAISE(ABORT, 'Stage steering predecessor fence is stale')
    END;
END;
CREATE TRIGGER stage_steering_terminal_immutable_v257
BEFORE UPDATE ON stage_steering_request_v257
WHEN OLD.status IN ('ADMITTED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal Stage steering is immutable'); END;
CREATE TRIGGER stage_steering_transition_receipt_immutable_v257
BEFORE UPDATE ON stage_steering_transition_receipt_v257
BEGIN SELECT RAISE(ABORT, 'Stage steering transition receipt is immutable'); END;
CREATE TRIGGER stage_steering_transition_receipt_insert_v257
BEFORE INSERT ON stage_steering_transition_receipt_v257
WHEN NEW.disposition = 'APPLIED' AND NOT EXISTS (
    SELECT 1
    FROM stage_transition transition
    JOIN local_stage_turn_request request ON request.id = NEW.proof_id
    JOIN stage_turn turn ON turn.id = request.stage_turn_id
    JOIN dispatch_ticket ticket ON ticket.operation_id = turn.operation_id
    WHERE transition.stage_id = NEW.stage_id
      AND transition.command_id = NEW.command_id
      AND transition.generation = NEW.returned_generation
      AND transition.from_checkpoint = 'LOCAL_REVIEW'
      AND transition.to_checkpoint = 'ADDRESSING_LOCAL_FEEDBACK'
      AND transition.stage_version = NEW.returned_version
      AND transition.cause = NEW.cause
      AND transition.actor = NEW.actor
      AND request.task_id = NEW.task_id
      AND request.local_development_stage_id = NEW.stage_id
      AND request.task_epoch = NEW.expected_task_epoch
      AND request.stage_generation = NEW.returned_generation
      AND request.kind = 'STEERING'
      AND request.queue_mode = 'IMMEDIATE'
      AND turn.operation_id = NEW.subject_operation_id
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'Local steering transition lacks exact durable work'); END;
CREATE TRIGGER stage_steering_transition_v257
BEFORE UPDATE OF status ON stage_steering_request_v257
WHEN OLD.status <> 'PENDING' OR NEW.status NOT IN ('ADMITTED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'illegal Stage steering transition'); END;
CREATE TRIGGER stage_transition_immutable
BEFORE UPDATE ON stage_transition
BEGIN SELECT RAISE(ABORT, 'stage transition is immutable'); END;
CREATE TRIGGER stage_turn_global_identity_insert
BEFORE INSERT ON stage_turn
WHEN EXISTS (SELECT 1 FROM thread_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM task_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM review_assignment_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
BEGIN SELECT RAISE(ABORT, 'typed Turn id and operation id must be globally exact'); END;
CREATE TRIGGER stage_turn_identity_immutable
BEFORE UPDATE OF stage_id, stage_generation, purpose, operation_id, attempt,
        task_epoch, expected_code_fingerprint, expected_head_sha,
        expected_base_sha, delivery_lane, launch_input ON stage_turn
WHEN NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.purpose IS NOT OLD.purpose
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.attempt IS NOT OLD.attempt
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.expected_code_fingerprint IS NOT OLD.expected_code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.delivery_lane IS NOT OLD.delivery_lane
  OR NEW.launch_input IS NOT OLD.launch_input
BEGIN SELECT RAISE(ABORT, 'stage Turn launch identity is immutable'); END;
CREATE TRIGGER stage_turn_owner_fence_insert
BEFORE INSERT ON stage_turn
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM stage s
        JOIN tasks t ON t.id = s.task_id
        WHERE s.id = NEW.stage_id
          AND s.generation = NEW.stage_generation
          AND t.workflow_version = 'V2'
          AND t.epoch = NEW.task_epoch)
    THEN RAISE(ABORT, 'stage Turn fence does not match V2 Stage') END;
END;
CREATE TRIGGER stage_turn_user_wait_continuation_identity_v265
BEFORE UPDATE OF request_id, wait_kind, wait_id, predecessor_turn_id,
        predecessor_operation_id ON stage_turn_user_wait_continuation_v265
BEGIN SELECT RAISE(ABORT, 'Stage user-wait continuation identity is immutable'); END;
CREATE TRIGGER stage_turn_user_wait_continuation_insert_v265
BEFORE INSERT ON stage_turn_user_wait_continuation_v265
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_steering_request_v257 request
    JOIN stage_turn predecessor ON predecessor.id = NEW.predecessor_turn_id
    JOIN typed_user_wait_result result
      ON result.operation_id = predecessor.operation_id
    WHERE request.id = NEW.request_id AND request.status = 'PENDING'
      AND request.mode = 'CANCEL_AND_REPLACE'
      AND request.predecessor_owner_kind = 'STAGE_TURN'
      AND request.predecessor_owner_id = predecessor.id
      AND request.predecessor_operation_id = predecessor.operation_id
      AND predecessor.operation_id = NEW.predecessor_operation_id
      AND predecessor.status = 'SUCCEEDED'
      AND result.owner_kind = 'STAGE_TURN'
      AND result.turn_id = predecessor.id
      AND result.wait_kind = NEW.wait_kind AND result.wait_id = NEW.wait_id
      AND ((NEW.wait_kind = 'QUESTION' AND EXISTS (
            SELECT 1 FROM stage_question question
            WHERE question.id = NEW.wait_id
              AND question.turn_id = predecessor.id
              AND question.state = 'ANSWERED'
              AND question.continuation_state = 'READY'))
        OR (NEW.wait_kind = 'PERMISSION' AND EXISTS (
            SELECT 1 FROM permission_request permission
            WHERE permission.id = NEW.wait_id
              AND permission.turn_kind = 'STAGE'
              AND permission.turn_id = predecessor.id
              AND permission.operation_id = predecessor.operation_id
              AND permission.state <> 'OPEN'
              AND permission.continuation_state = 'READY'))))
BEGIN SELECT RAISE(ABORT, 'Stage user-wait continuation is not exact'); END;
CREATE TRIGGER stage_turn_user_wait_continuation_update_v265
BEFORE UPDATE OF successor_turn_id, successor_operation_id, admitted_at_ms
ON stage_turn_user_wait_continuation_v265
WHEN OLD.successor_turn_id IS NOT NULL OR NOT EXISTS (
    SELECT 1
    FROM stage_turn predecessor
    JOIN stage_turn successor ON successor.id = NEW.successor_turn_id
    WHERE predecessor.id = OLD.predecessor_turn_id
      AND successor.operation_id = NEW.successor_operation_id
      AND successor.id <> predecessor.id
      AND successor.stage_id = predecessor.stage_id
      AND successor.stage_generation = predecessor.stage_generation
      AND successor.task_epoch = predecessor.task_epoch
      AND successor.purpose = predecessor.purpose
      AND successor.status = 'QUEUED'
      AND successor.attempt = predecessor.attempt + 1
      AND successor.expected_code_fingerprint IS predecessor.expected_code_fingerprint
      AND successor.expected_head_sha IS predecessor.expected_head_sha
      AND successor.expected_base_sha IS predecessor.expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'Stage user-wait successor is not exact'); END;
CREATE TRIGGER task_archive_liveness_immutable
BEFORE UPDATE ON task_archive_liveness
BEGIN SELECT RAISE(ABORT, 'ArchiveEvidence is immutable'); END;
CREATE TRIGGER task_archive_liveness_insert
BEFORE INSERT ON task_archive_liveness
WHEN NEW.recorded_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
  OR NEW.liveness_digest <> (
       'archive:v1:' || lower(hex(NEW.task_id)) || ':' || NEW.task_epoch || ':'
       || lower(hex(NEW.id)) || ':' || lower(hex(NEW.stage_id)) || ':'
       || NEW.stage_generation || ':' || NEW.active_task_turn_count || ':'
       || NEW.active_stage_turn_count || ':' || NEW.active_review_turn_count || ':'
       || NEW.active_plan_review_count || ':' || NEW.active_validation_count || ':'
       || NEW.active_brain_episode_count || ':' || NEW.active_provision_operation_count || ':'
       || NEW.active_dispatch_count || ':' || NEW.active_agent_execution_count || ':'
       || NEW.unreconciled_execution_count || ':' || NEW.live_capacity_lease_count || ':'
       || NEW.live_worktree_lease_count || ':' || NEW.active_quiescence_count || ':'
       || NEW.active_replan_count || ':' || NEW.active_feedback_batch_count || ':'
       || NEW.active_publish_operation_count || ':'
       || NEW.unreconciled_publish_operation_count || ':'
       || NEW.active_publish_effect_count || ':'
       || NEW.active_publish_authorization_count || ':' || NEW.open_permission_count || ':'
       || NEW.accepted_terminal_intent_count || ':' || NEW.open_cleanup_stage_count || ':'
       || NEW.recorded_at_ms)
  OR NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_live_work_counts_v230 live ON live.task_id = task.id
    WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ARCHIVING' AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.stage_id
      AND current.stage_generation = NEW.stage_generation
      AND owner.task_id = NEW.task_id AND owner.generation = NEW.stage_generation
      AND owner.completed_at_ms IS NULL AND live.task_epoch = NEW.task_epoch
      AND live.active_task_turn_count = NEW.active_task_turn_count
      AND live.active_stage_turn_count = NEW.active_stage_turn_count
      AND live.active_review_turn_count = NEW.active_review_turn_count
      AND live.active_plan_review_count = NEW.active_plan_review_count
      AND live.active_validation_count = NEW.active_validation_count
      AND live.active_brain_episode_count = NEW.active_brain_episode_count
      AND live.active_provision_operation_count = NEW.active_provision_operation_count
      AND live.active_dispatch_count = NEW.active_dispatch_count
      AND live.active_agent_execution_count = NEW.active_agent_execution_count
      AND live.unreconciled_execution_count = NEW.unreconciled_execution_count
      AND live.active_quiescence_count = NEW.active_quiescence_count
      AND live.active_replan_count = NEW.active_replan_count
      AND live.active_feedback_batch_count = NEW.active_feedback_batch_count
      AND live.active_publish_operation_count = NEW.active_publish_operation_count
      AND live.unreconciled_publish_operation_count
            = NEW.unreconciled_publish_operation_count
      AND live.active_publish_effect_count = NEW.active_publish_effect_count
      AND live.active_publish_authorization_count
            = NEW.active_publish_authorization_count
      AND live.open_permission_count = NEW.open_permission_count
      AND live.accepted_terminal_intent_count = NEW.accepted_terminal_intent_count
      AND live.open_cleanup_stage_count = NEW.open_cleanup_stage_count
      AND (SELECT COUNT(*) FROM capacity_lease lease
           WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
             AND lease.task_epoch = NEW.task_epoch AND lease.released_at_ms IS NULL
             AND lease.expires_at_ms > NEW.recorded_at_ms)
            = NEW.live_capacity_lease_count
      AND (SELECT COUNT(*) FROM worktree_leases lease
           WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
             AND lease.task_epoch = NEW.task_epoch
             AND lease.expires_at_ms > NEW.recorded_at_ms)
            = NEW.live_worktree_lease_count)
BEGIN SELECT RAISE(ABORT, 'ArchiveEvidence requires its exact zero-live-work facts'); END;
CREATE TRIGGER task_archive_liveness_v256_all_epoch_fence
BEFORE INSERT ON task_archive_liveness
WHEN EXISTS (
    SELECT 1 FROM task_control_live_work_v256 live
    WHERE live.task_id = NEW.task_id
      AND (live.active_task_turn_count <> 0
        OR live.active_stage_turn_count <> 0
        OR live.active_review_turn_count <> 0
        OR live.active_dispatch_count <> 0
        OR live.active_agent_execution_count <> 0))
  OR EXISTS (
      SELECT 1 FROM capacity_lease lease
      WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
        AND lease.released_at_ms IS NULL
        AND lease.expires_at_ms > NEW.recorded_at_ms)
  OR EXISTS (
      SELECT 1 FROM worktree_leases lease
      WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
        AND lease.expires_at_ms > NEW.recorded_at_ms)
BEGIN SELECT RAISE(ABORT, 'ArchiveEvidence requires all Task work across epochs to stop'); END;
CREATE TRIGGER task_assignment_immutable
BEFORE UPDATE ON task_assignment
BEGIN SELECT RAISE(ABORT, 'TaskAssignment is immutable'); END;
CREATE TRIGGER task_assignment_review_finding_delete_guard
BEFORE DELETE ON task_assignment_review_finding
WHEN NOT EXISTS (
    SELECT 1
    FROM task_assignment assignment
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = assignment.trunk_id
    WHERE assignment.id = OLD.assignment_id)
BEGIN SELECT RAISE(ABORT, 'TaskAssignment review finding cannot be deleted'); END;
CREATE TRIGGER task_assignment_review_finding_immutable
BEFORE UPDATE ON task_assignment_review_finding
BEGIN SELECT RAISE(ABORT, 'TaskAssignment review finding is immutable'); END;
CREATE TRIGGER task_assignment_review_finding_insert
BEFORE INSERT ON task_assignment_review_finding
WHEN NEW.position <> COALESCE((
        SELECT MAX(f.position) + 1
        FROM task_assignment_review_finding f
        WHERE f.assignment_id = NEW.assignment_id), 1)
  OR NOT EXISTS (
      SELECT 1 FROM task_assignment assignment
      WHERE assignment.id = NEW.assignment_id
        AND assignment.kind = 'REVIEW_FINDINGS'
        AND assignment.source_id = NEW.source_review_id
        AND assignment.selected_findings_json = '[]')
BEGIN SELECT RAISE(ABORT, 'typed review finding does not match its assignment'); END;
CREATE TRIGGER task_assignment_v2_exact_insert
BEFORE INSERT ON task_assignment
BEGIN
    SELECT CASE
        WHEN length(trim(NEW.id)) = 0 OR length(trim(NEW.trunk_id)) = 0
          OR length(trim(NEW.created_by)) = 0
          OR NEW.creation_authorization_id IS NULL
          OR length(trim(NEW.creation_authorization_id)) = 0
            THEN RAISE(ABORT, 'TaskAssignment identity must be exact')
        WHEN NOT EXISTS (
            SELECT 1 FROM threads trunk
            JOIN workspace_repos repository
              ON repository.workspace_id = trunk.workspace_id
            WHERE trunk.id = NEW.trunk_id AND trunk.turn_version = 'V2'
              AND trunk.lifecycle_state IN ('ACTIVE', 'IDLE'))
            THEN RAISE(ABORT, 'TaskAssignment requires a live V2 Trunk Workspace')
        WHEN NEW.kind = 'NEW_FROM_TRUNK' AND NOT (
            (NEW.planning_base_sha IS NULL OR length(trim(NEW.planning_base_sha)) > 0)
            AND NEW.plan_seed IS NOT NULL AND length(trim(NEW.plan_seed)) > 0
            AND NEW.prompt IS NOT NULL AND length(trim(NEW.prompt)) > 0
            AND NEW.source_id IS NULL AND NEW.repository_id IS NULL
            AND NEW.pr_number IS NULL AND NEW.remote_head_sha IS NULL
            AND NEW.producer IS NULL AND NEW.reason IS NULL
            AND NEW.selected_findings_json IS NULL
            AND NEW.base_repository_id IS NULL AND NEW.head_repository_id IS NULL
            AND NEW.base_ref IS NULL AND NEW.head_ref IS NULL
            AND NEW.remote_base_sha IS NULL AND NEW.repository_route IS NULL)
            THEN RAISE(ABORT, 'NewFromTrunk assignment shape is not exact')
        WHEN NEW.kind IN ('EXISTING_OWN_PR', 'REVIEW_FINDINGS') AND NOT (
            NEW.repository_id IS NOT NULL
            AND NEW.repository_id = NEW.head_repository_id
            AND NEW.pr_number > 0
            AND length(trim(NEW.base_repository_id)) > 0
            AND length(trim(NEW.head_repository_id)) > 0
            AND ((NEW.repository_route = 'DIRECT'
                    AND NEW.base_repository_id = NEW.head_repository_id)
                OR (NEW.repository_route = 'FORK'
                    AND NEW.base_repository_id <> NEW.head_repository_id))
            AND ((NEW.base_ref IS NULL AND NEW.head_ref IS NULL
                    AND NEW.remote_base_sha IS NULL AND NEW.remote_head_sha IS NULL)
                OR (length(trim(NEW.base_ref)) > 0
                    AND length(trim(NEW.head_ref)) > 0
                    AND length(trim(NEW.remote_base_sha)) > 0
                    AND length(trim(NEW.remote_head_sha)) > 0))
            AND NEW.planning_base_sha IS NULL AND NEW.plan_seed IS NULL
            AND NEW.prompt IS NULL AND NEW.producer IS NULL AND NEW.reason IS NULL
            AND ((NEW.kind = 'EXISTING_OWN_PR' AND NEW.source_id IS NULL
                    AND NEW.selected_findings_json IS NULL)
                OR (NEW.kind = 'REVIEW_FINDINGS'
                    AND length(trim(NEW.source_id)) > 0
                    AND NEW.selected_findings_json = '[]')))
            THEN RAISE(ABORT, 'Existing PR assignment shape is not exact')
        WHEN NEW.kind = 'ISSUE' AND NOT (
            length(trim(NEW.source_id)) > 0 AND NEW.repository_id IS NULL
            AND NEW.pr_number IS NULL AND NEW.remote_head_sha IS NULL
            AND NEW.planning_base_sha IS NULL AND NEW.plan_seed IS NULL
            AND NEW.prompt IS NULL AND NEW.producer IS NULL AND NEW.reason IS NULL
            AND NEW.selected_findings_json IS NULL
            AND NEW.base_repository_id IS NULL AND NEW.head_repository_id IS NULL
            AND NEW.base_ref IS NULL AND NEW.head_ref IS NULL
            AND NEW.remote_base_sha IS NULL AND NEW.repository_route IS NULL)
            THEN RAISE(ABORT, 'Issue assignment shape is not exact')
        WHEN NEW.kind = 'AUTOMATION' AND NOT (
            length(trim(NEW.producer)) > 0 AND length(trim(NEW.reason)) > 0
            AND NEW.source_id IS NULL AND NEW.repository_id IS NULL
            AND NEW.pr_number IS NULL AND NEW.remote_head_sha IS NULL
            AND NEW.planning_base_sha IS NULL AND NEW.plan_seed IS NULL
            AND NEW.prompt IS NULL AND NEW.selected_findings_json IS NULL
            AND NEW.base_repository_id IS NULL AND NEW.head_repository_id IS NULL
            AND NEW.base_ref IS NULL AND NEW.head_ref IS NULL
            AND NEW.remote_base_sha IS NULL AND NEW.repository_route IS NULL)
            THEN RAISE(ABORT, 'Automation assignment shape is not exact')
        WHEN NEW.kind = 'QUALITY_SCAN' AND NOT (
            length(trim(NEW.source_id)) > 0 AND NEW.repository_id IS NULL
            AND NEW.pr_number IS NULL AND NEW.remote_head_sha IS NULL
            AND NEW.planning_base_sha IS NULL AND NEW.plan_seed IS NULL
            AND NEW.prompt IS NULL AND NEW.producer IS NULL AND NEW.reason IS NULL
            AND NEW.selected_findings_json IS NULL
            AND NEW.base_repository_id IS NULL AND NEW.head_repository_id IS NULL
            AND NEW.base_ref IS NULL AND NEW.head_ref IS NULL
            AND NEW.remote_base_sha IS NULL AND NEW.repository_route IS NULL)
            THEN RAISE(ABORT, 'QualityScan assignment shape is not exact')
    END;
END;
CREATE TRIGGER task_automation_eligibility_evidence_immutable
BEFORE UPDATE ON task_automation_eligibility_evidence
BEGIN SELECT RAISE(ABORT, 'Task automation eligibility evidence is immutable'); END;
CREATE TRIGGER task_automation_eligibility_evidence_insert
BEFORE INSERT ON task_automation_eligibility_evidence
WHEN NOT EXISTS (
    SELECT 1 FROM plan_revision revision
    JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
    JOIN tasks task ON task.id = plan.task_id
    WHERE revision.id = NEW.plan_revision_id
      AND plan.task_id = NEW.task_id
      AND plan.opened_for_epoch = NEW.task_epoch
      AND task.epoch = NEW.task_epoch
      AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'Automation eligibility lacks exact Task Plan evidence'); END;
CREATE TRIGGER task_automation_policy_immutable
BEFORE UPDATE ON task_automation_policy
BEGIN SELECT RAISE(ABORT, 'Task automation policy is immutable'); END;
CREATE TRIGGER task_automation_policy_insert
BEFORE INSERT ON task_automation_policy
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            WHERE task.id = NEW.task_id AND task.workflow_version = 'V2')
            THEN RAISE(ABORT, 'Automation policy requires V2 Task')
        WHEN NEW.revision <> COALESCE((
            SELECT MAX(policy.revision) + 1
            FROM task_automation_policy policy
            WHERE policy.task_id = NEW.task_id), 1)
            THEN RAISE(ABORT, 'Automation policy revision must be next')
    END;
END;
CREATE TRIGGER task_blocker_owner_insert
BEFORE INSERT ON task_blocker
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            WHERE task.id = NEW.task_id AND task.workflow_version = 'V2')
            THEN RAISE(ABORT, 'Task blocker requires a V2 Task')
        WHEN NEW.owner_kind = 'TASK'
                AND (NEW.owner_id <> NEW.task_id OR NEW.stage_id IS NOT NULL)
            THEN RAISE(ABORT, 'Task blocker Task owner is invalid')
        WHEN NEW.owner_kind = 'STAGE'
                AND (NEW.stage_id IS NULL OR NEW.owner_id <> NEW.stage_id
                    OR NOT EXISTS (
                        SELECT 1 FROM stage owner
                        WHERE owner.id = NEW.stage_id
                          AND owner.task_id = NEW.task_id))
            THEN RAISE(ABORT, 'Task blocker Stage owner is invalid')
        WHEN NEW.owner_kind = 'EPISODE'
                AND (NEW.stage_id IS NULL OR NOT EXISTS (
                    SELECT 1 FROM ci_repair_episode episode
                    WHERE episode.id = NEW.owner_id
                      AND episode.task_id = NEW.task_id
                      AND episode.remote_development_stage_id = NEW.stage_id
                    UNION ALL
                    SELECT 1 FROM branch_sync_episode episode
                    WHERE episode.id = NEW.owner_id
                      AND episode.task_id = NEW.task_id
                      AND episode.remote_development_stage_id = NEW.stage_id
                    UNION ALL
                    SELECT 1 FROM remote_feedback_batch episode
                    WHERE episode.id = NEW.owner_id
                      AND episode.task_id = NEW.task_id
                      AND episode.remote_development_stage_id = NEW.stage_id))
            THEN RAISE(ABORT, 'Task blocker Episode owner is invalid')
        WHEN NEW.owner_kind = 'OPERATION'
                AND (NEW.stage_id IS NULL OR NOT EXISTS (
                    SELECT 1 FROM remote_merge_operation operation
                    WHERE operation.id = NEW.owner_id
                      AND operation.task_id = NEW.task_id
                      AND operation.remote_development_stage_id = NEW.stage_id
                    UNION ALL
                    SELECT 1 FROM remote_mark_ready_operation operation
                    WHERE operation.id = NEW.owner_id
                      AND operation.task_id = NEW.task_id
                      AND operation.remote_development_stage_id = NEW.stage_id
                    UNION ALL
                    SELECT 1 FROM cleanup_operation operation
                    WHERE operation.id = NEW.owner_id
                      AND operation.task_id = NEW.task_id
                      AND operation.cleanup_stage_id = NEW.stage_id))
            THEN RAISE(ABORT, 'Task blocker Operation owner is invalid')
    END;
END;
CREATE TRIGGER task_brain_budget_receipt_immutable
BEFORE UPDATE ON task_brain_budget_receipt
BEGIN SELECT RAISE(ABORT, 'Brain budget receipt is immutable'); END;
CREATE TRIGGER task_brain_budget_receipt_insert
BEFORE INSERT ON task_brain_budget_receipt
BEGIN
    SELECT CASE
        WHEN NEW.disposition = 'APPLIED' AND NOT EXISTS (
            SELECT 1 FROM task_transition transition
            WHERE transition.task_id = NEW.task_id
              AND transition.command_id = NEW.command_id
              AND transition.cause = NEW.cause
              AND transition.aggregate_version = NEW.returned_version)
            THEN RAISE(ABORT, 'Brain budget receipt lacks its Task transition')
        WHEN NOT EXISTS (
            SELECT 1
            FROM task_blocker blocker
            JOIN brain_review_episode episode
              ON episode.task_id = blocker.task_id
            JOIN task_turn turn ON turn.id = episode.task_turn_id
            WHERE blocker.id = NEW.proof_id
              AND blocker.task_id = NEW.task_id
              AND blocker.stage_id = NEW.subject_stage_id
              AND blocker.blocker_type = 'BRAIN_BUDGET_EXHAUSTED'
              AND blocker.status = 'OPEN'
              AND episode.status = 'BUDGET_EXHAUSTED'
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.task_epoch = NEW.subject_task_epoch
              AND turn.trigger_stage_id = NEW.subject_stage_id
              AND turn.trigger_stage_generation = NEW.subject_stage_generation
              AND turn.expected_code_fingerprint
                    = NEW.subject_expected_code_fingerprint
              AND turn.expected_head_sha = NEW.subject_expected_head_sha
              AND turn.expected_base_sha = NEW.subject_expected_base_sha
              AND turn.status = 'FAILED')
            THEN RAISE(ABORT, 'Brain budget receipt lacks exact terminal evidence')
    END;
END;
CREATE TRIGGER task_brain_conversation_result_immutable_v266
BEFORE UPDATE ON task_brain_conversation_result_v266
BEGIN SELECT RAISE(ABORT, 'Task Brain conversation result is immutable'); END;
CREATE TRIGGER task_brain_conversation_result_insert_v266
BEFORE INSERT ON task_brain_conversation_result_v266
WHEN NOT EXISTS (
    SELECT 1 FROM task_turn turn
    WHERE turn.id = NEW.task_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.purpose = 'TASK_BRAIN_CONVERSATION'
      AND turn.status = NEW.terminal_status
      AND (NEW.assistant_message_id IS NULL OR EXISTS (
          SELECT 1 FROM task_message message
          WHERE message.id = NEW.assistant_message_id
            AND message.turn_id = turn.id
            AND message.role = 'ASSISTANT'
            AND length(trim(message.body)) > 0)))
BEGIN SELECT RAISE(ABORT, 'Task Brain conversation result is not exact'); END;
CREATE TRIGGER task_brain_conversation_ticket_insert_v266
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind = 'EXECUTE_TASK_TURN'
  AND EXISTS (
      SELECT 1 FROM task_turn turn
      WHERE turn.id = NEW.owner_id
        AND turn.purpose = 'TASK_BRAIN_CONVERSATION')
  AND NOT EXISTS (
    SELECT 1 FROM task_turn turn
    JOIN tasks task ON task.id = turn.task_id
    WHERE turn.id = NEW.owner_id
      AND turn.operation_id = NEW.operation_id
      AND turn.task_id = NEW.task_id
      AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id IS NEW.stage_id
      AND turn.trigger_stage_generation IS NEW.stage_generation
      AND turn.attempt = NEW.attempt
      AND turn.expected_code_fingerprint IS
          NEW.expected_code_fingerprint
      AND turn.expected_head_sha IS NEW.expected_head_sha
      AND turn.expected_base_sha IS NEW.expected_base_sha
      AND NEW.async_family = 'AGENT_TURN'
      AND NEW.owner_kind = 'TASK_TURN'
      AND NEW.callback_route = 'TASK_TURN_RESULT'
      AND NEW.lane_mask = (CASE
          json_extract(turn.launch_input, '$.transport')
          WHEN 'CLI' THEN 1 ELSE 2 END) + CASE
              WHEN task.lifecycle_state = 'ACTIVE' THEN 0 ELSE 8 END
      AND NEW.trunk_control = 0
      AND NEW.writer_required = 0
      AND NEW.status = 'REQUESTED'
      AND ((task.lifecycle_state = 'ACTIVE'
            AND NEW.exclusive_task = 1
            AND NEW.stage_id IS NOT NULL)
        OR (task.lifecycle_state IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
            AND NEW.exclusive_task = 0
            AND NEW.stage_id IS NULL)))
BEGIN SELECT RAISE(ABORT, 'Task Brain conversation ticket is not exact'); END;
CREATE TRIGGER task_brain_conversation_turn_insert_v266
BEFORE INSERT ON task_turn
WHEN NEW.purpose = 'TASK_BRAIN_CONVERSATION'
  AND NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_brain brain ON brain.task_id = task.id
    JOIN task_creation_context creation ON creation.task_id = task.id
    LEFT JOIN task_current_stage current ON current.task_id = task.id
    LEFT JOIN stage owner ON owner.id = current.stage_id
    LEFT JOIN task_current_code_subject_v230 code
      ON code.task_id = task.id
    LEFT JOIN task_outcome outcome ON outcome.task_id = task.id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.epoch = NEW.task_epoch
      AND NEW.status = 'REQUESTED'
      AND json_valid(NEW.launch_input)
      AND json_extract(NEW.launch_input, '$.schemaVersion') = 1
      AND json_extract(NEW.launch_input, '$.provider') = brain.provider
      AND json_extract(NEW.launch_input, '$.model') = brain.model
      AND json_extract(NEW.launch_input, '$.provider') =
          json_extract(creation.work_model_snapshot, '$.agentOrProvider')
      AND (json_extract(creation.work_model_snapshot, '$.model') IS NULL
        OR json_extract(creation.work_model_snapshot, '$.model') = brain.model)
      AND json_extract(NEW.launch_input, '$.transport') =
          json_extract(creation.work_model_snapshot, '$.kind')
      AND length(json_extract(NEW.launch_input, '$.workingDirectory')) > 0
      AND length(json_extract(NEW.launch_input, '$.prompt')) > 0
      AND json_extract(NEW.launch_input, '$.toolEndpoint.ownerKind') =
          'TASK_TURN'
      AND json_extract(NEW.launch_input, '$.toolEndpoint.ownerId') = NEW.id
      AND json_extract(NEW.launch_input, '$.toolEndpoint.operationId') =
          NEW.operation_id
      AND json_extract(NEW.launch_input, '$.toolEndpoint.profile') =
          'TASK_BRAIN_READ_ONLY'
      AND ((task.lifecycle_state = 'ACTIVE'
            AND current.stage_id = NEW.trigger_stage_id
            AND current.stage_generation = NEW.trigger_stage_generation
            AND owner.completed_at_ms IS NULL
            AND NEW.expected_code_fingerprint IS code.code_fingerprint
            AND NEW.expected_head_sha IS code.head_sha
            AND NEW.expected_base_sha IS code.base_sha)
        OR (task.lifecycle_state IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
            AND outcome.task_epoch = NEW.task_epoch
            AND NEW.trigger_stage_id IS NULL
            AND NEW.trigger_stage_generation IS NULL
            AND NEW.expected_code_fingerprint IS code.code_fingerprint
            AND NEW.expected_head_sha IS code.head_sha
            AND NEW.expected_base_sha IS code.base_sha)))
BEGIN SELECT RAISE(ABORT, 'Task Brain conversation Turn is not exact'); END;
CREATE TRIGGER task_brain_immutable
BEFORE UPDATE ON task_brain
BEGIN SELECT RAISE(ABORT, 'Task Brain identity is immutable'); END;
CREATE TRIGGER task_brain_owner_insert
BEFORE INSERT ON task_brain
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks t
    JOIN task_creation_context c ON c.task_id = t.id
    WHERE t.id = NEW.task_id
      AND t.workflow_version = 'V2'
      AND c.engine_snapshot = NEW.engine_snapshot)
BEGIN SELECT RAISE(ABORT, 'Task Brain requires a V2 Task'); END;
CREATE TRIGGER task_brain_request_receipt_immutable
BEFORE UPDATE ON task_brain_request_receipt
BEGIN SELECT RAISE(ABORT, 'Task Brain request receipt is immutable'); END;
CREATE TRIGGER task_brain_request_receipt_insert
BEFORE INSERT ON task_brain_request_receipt
BEGIN
    SELECT CASE WHEN
        NEW.cause <> 'REQUEST_BRAIN_REVIEW'
        OR NEW.disposition <> 'APPLIED'
        OR NEW.expected_task_epoch IS NULL
        OR NEW.expected_task_version IS NULL
        OR NEW.subject_operation_id IS NULL
        OR NEW.subject_task_epoch <> NEW.expected_task_epoch
        OR NEW.subject_stage_id IS NULL
        OR NEW.subject_stage_generation IS NULL
        OR NEW.proof_id IS NULL
        OR NEW.brain_verdict IS NOT NULL
        OR NEW.next_stage_id IS NOT NULL
        OR NEW.returned_lifecycle <> 'ACTIVE'
        OR NEW.returned_epoch <> NEW.expected_task_epoch
        OR NEW.returned_version <> NEW.expected_task_version + 1
        OR NEW.returned_current_stage_id <> NEW.subject_stage_id
        OR NEW.returned_pending_task_epoch <> NEW.subject_task_epoch
        OR NEW.returned_pending_stage_id <> NEW.subject_stage_id
        OR NEW.returned_pending_stage_generation
            <> NEW.subject_stage_generation
        OR NEW.returned_pending_operation_id <> NEW.subject_operation_id
        OR NEW.returned_pending_attempt <> NEW.subject_attempt
        OR NEW.returned_pending_code_fingerprint
            IS NOT NEW.subject_expected_code_fingerprint
        OR NEW.returned_pending_head_sha IS NOT NEW.subject_expected_head_sha
        OR NEW.returned_pending_base_sha IS NOT NEW.subject_expected_base_sha
        OR EXISTS (SELECT 1 FROM task_command_receipt shared
                   WHERE shared.task_id = NEW.task_id
                     AND shared.command_id = NEW.command_id)
        OR NOT EXISTS (
            SELECT 1
            FROM brain_review_episode episode
            JOIN task_turn turn ON turn.id = episode.task_turn_id
            JOIN dispatch_ticket ticket ON ticket.operation_id = turn.operation_id
            JOIN tasks task ON task.id = episode.task_id
            JOIN task_current_stage current ON current.task_id = task.id
            WHERE episode.id = NEW.proof_id
              AND episode.task_id = NEW.task_id
              AND episode.task_epoch = NEW.subject_task_epoch
              AND episode.local_development_stage_id = NEW.subject_stage_id
              AND episode.stage_generation = NEW.subject_stage_generation
              AND episode.status = 'REQUESTED'
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.attempt = NEW.subject_attempt
              AND turn.expected_code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND turn.expected_head_sha IS NEW.subject_expected_head_sha
              AND turn.expected_base_sha IS NEW.subject_expected_base_sha
              AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
              AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
              AND ticket.async_family = 'AGENT_TURN'
              AND ticket.callback_route = 'TASK_TURN_RESULT'
              AND ticket.status = 'REQUESTED'
              AND task.workflow_version = 'V2'
              AND task.lifecycle_state = 'ACTIVE'
              AND task.epoch = NEW.subject_task_epoch
              AND current.stage_id = NEW.subject_stage_id
              AND current.stage_generation = NEW.subject_stage_generation)
        OR NOT EXISTS (
            SELECT 1 FROM task_transition transition
            WHERE transition.task_id = NEW.task_id
              AND transition.command_id = NEW.command_id
              AND transition.epoch = NEW.returned_epoch
              AND transition.to_state = 'ACTIVE'
              AND transition.aggregate_version = NEW.returned_version
              AND transition.cause = 'REQUEST_BRAIN_REVIEW'
              AND transition.actor = NEW.actor)
    THEN RAISE(ABORT, 'Task Brain request receipt is not exact') END;
END;
CREATE TRIGGER task_branch_sync_policy_revision_immutable
BEFORE UPDATE ON task_branch_sync_policy_revision
BEGIN SELECT RAISE(ABORT, 'Branch sync policy revision is immutable'); END;
CREATE TRIGGER task_branch_sync_policy_revision_insert
BEFORE INSERT ON task_branch_sync_policy_revision
WHEN NOT EXISTS (
    SELECT 1 FROM tasks task
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state NOT IN (
          'CLEANING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
      AND NEW.revision = COALESCE((
          SELECT MAX(policy.revision) + 1
          FROM task_branch_sync_policy_revision policy
          WHERE policy.task_id = task.id), 1))
BEGIN SELECT RAISE(ABORT, 'Branch sync policy does not match the current V2 Task'); END;
CREATE TRIGGER task_cleanup_completion_receipt_insert
BEFORE INSERT ON task_command_receipt
WHEN NEW.cause = 'ACCEPT_CLEANUP_COMPLETION'
  AND NOT EXISTS (
      SELECT 1 FROM task_outcome outcome
      JOIN cleanup_operation cleanup ON cleanup.id = outcome.cleanup_operation_id
      JOIN cleanup_stage cleanup_owner ON cleanup_owner.stage_id = outcome.cleanup_stage_id
      JOIN stage owner ON owner.id = cleanup_owner.stage_id
      WHERE outcome.task_id = NEW.task_id
        AND outcome.task_epoch = NEW.subject_task_epoch
        AND outcome.terminal_reason = NEW.returned_lifecycle
        AND cleanup.operation_id = NEW.subject_operation_id
        AND cleanup.semantic_attempt = NEW.subject_attempt
        AND cleanup.status = 'COMPLETED'
        AND owner.id = NEW.subject_stage_id
        AND owner.generation = NEW.subject_stage_generation
        AND owner.checkpoint = 'COMPLETED'
        AND NEW.disposition = 'APPLIED'
        AND NEW.expected_task_epoch = outcome.task_epoch
        AND NEW.expected_task_version = NEW.returned_version - 1
        AND NEW.returned_epoch = outcome.task_epoch
        AND NEW.returned_current_stage_id IS NULL
        AND NEW.returned_terminal_intent = outcome.terminal_reason)
BEGIN SELECT RAISE(ABORT, 'Task cleanup completion receipt lacks exact outcome'); END;
CREATE TRIGGER task_code_identity_immutable
BEFORE UPDATE ON task_code_identity
BEGIN SELECT RAISE(ABORT, 'initial Task code identity is immutable'); END;
CREATE TRIGGER task_code_identity_insert_fence
BEFORE INSERT ON task_code_identity
WHEN NOT EXISTS (
    SELECT 1
    FROM provision_task_operation o
    JOIN task_creation_context c ON c.task_id = o.task_id
    WHERE o.id = NEW.provision_operation_id
      AND o.task_id = NEW.task_id
      AND o.status = 'ACCEPTED'
      AND o.repository_id = NEW.repository_id
      AND c.repository_id = NEW.repository_id
      AND c.upstream_repository_id IS NEW.upstream_repository_id
      AND c.publish_repository_id = NEW.publish_repository_id
      AND o.requested_branch_name = NEW.branch_name
      AND o.requested_worktree_path = NEW.worktree_path
      AND o.result_base_sha = NEW.base_sha
      AND o.result_head_sha = NEW.local_head_sha
      AND o.result_code_fingerprint = NEW.code_fingerprint)
BEGIN SELECT RAISE(ABORT, 'Task code identity requires exact accepted provisioning evidence'); END;
CREATE TRIGGER task_code_identity_v229_insert_fence
BEFORE INSERT ON task_code_identity
WHEN NOT EXISTS (
    SELECT 1
    FROM provision_task_operation operation
    JOIN dispatch_ticket ticket ON ticket.operation_id = operation.operation_id
    WHERE operation.id = NEW.provision_operation_id
      AND operation.task_id = NEW.task_id
      AND operation.status = 'ACCEPTED'
      AND operation.result_evidence IS NOT NULL
      AND operation.result_base_sha = NEW.base_sha
      AND operation.result_head_sha = NEW.local_head_sha
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = 'SUCCEEDED'
      AND ticket.pending_result_evidence = operation.result_evidence)
BEGIN SELECT RAISE(ABORT, 'TaskCodeIdentity lacks exact discovered provisioning evidence'); END;
CREATE TRIGGER task_command_receipt_brain_request_id_collision
BEFORE INSERT ON task_command_receipt
WHEN EXISTS (SELECT 1 FROM task_brain_request_receipt brain
             WHERE brain.task_id = NEW.task_id
               AND brain.command_id = NEW.command_id)
BEGIN SELECT RAISE(ABORT, 'Task command id is already used by a Brain request'); END;
CREATE TRIGGER task_command_receipt_immutable
BEFORE UPDATE ON task_command_receipt
BEGIN SELECT RAISE(ABORT, 'Task command receipt is immutable'); END;
CREATE TRIGGER task_command_receipt_insert
BEFORE INSERT ON task_command_receipt
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            WHERE task.id = NEW.task_id
              AND task.thread_id = NEW.returned_trunk_id
              AND task.workflow_version = 'V2')
            THEN RAISE(ABORT, 'Task command receipt requires a V2 Task')
        WHEN NEW.subject_stage_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM stage subject
            WHERE subject.id = NEW.subject_stage_id
              AND subject.task_id = NEW.task_id
              AND subject.generation = NEW.subject_stage_generation)
            THEN RAISE(ABORT, 'Task receipt subject Stage is invalid')
        WHEN NEW.disposition = 'APPLIED' AND NOT EXISTS (
            SELECT 1 FROM task_transition transition
            WHERE transition.task_id = NEW.task_id
              AND transition.command_id = NEW.command_id
              AND transition.epoch = NEW.returned_epoch
              AND transition.to_state = NEW.returned_lifecycle
              AND transition.aggregate_version = NEW.returned_version
              AND transition.cause = NEW.cause AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'applied Task receipt lacks its exact transition')
        WHEN NEW.cause = 'ACCEPT_PROVISIONING' AND NOT EXISTS (
            SELECT 1 FROM provision_task_operation operation
            WHERE operation.task_id = NEW.task_id
              AND operation.operation_id = NEW.proof_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.semantic_attempt = NEW.subject_attempt
              AND operation.result_code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND operation.result_head_sha IS NEW.subject_expected_head_sha
              AND operation.result_base_sha IS NEW.subject_expected_base_sha
              AND operation.status = 'ACCEPTED'
              AND NEW.subject_stage_id IS NULL
              AND NEW.subject_stage_generation = 0
              AND NEW.next_stage_kind = 'PLAN')
            THEN RAISE(ABORT, 'Task receipt provisioning proof is invalid')
        WHEN NEW.cause = 'OPEN_REPLAN_PLAN' AND NOT EXISTS (
            SELECT 1
            FROM task_replan_request request
            JOIN task_quiescence_barrier barrier
              ON barrier.id = request.quiescence_barrier_id
            WHERE request.id = NEW.proof_id
              AND request.task_id = NEW.task_id
              AND request.status IN ('QUIESCING', 'APPLIED')
              AND barrier.task_id = NEW.task_id
              AND barrier.status = 'SATISFIED'
              AND NEW.next_stage_kind = 'PLAN'
              AND (request.new_plan_stage_id IS NULL
                OR (NEW.next_stage_id = request.new_plan_stage_id
                    AND NEW.next_stage_generation = request.new_plan_generation)))
            THEN RAISE(ABORT, 'Task receipt replan proof is invalid')
        WHEN NEW.cause IN ('COMPLETE_PAUSE', 'OPEN_CANCELED_CLEANUP')
          AND NOT EXISTS (
            SELECT 1 FROM task_quiescence_barrier barrier
            WHERE barrier.id = NEW.proof_id
              AND barrier.task_id = NEW.task_id
              AND barrier.status = 'SATISFIED'
              AND ((NEW.cause = 'COMPLETE_PAUSE' AND barrier.reason = 'PAUSE')
                OR (NEW.cause = 'OPEN_CANCELED_CLEANUP'
                    AND barrier.reason = 'CANCEL'
                    AND NEW.next_stage_kind = 'CLEANUP')))
            THEN RAISE(ABORT, 'Task receipt quiescence proof is invalid')
        WHEN NEW.cause = 'OPEN_LOCAL_DEVELOPMENT' AND NOT EXISTS (
            SELECT 1
            FROM plan_approval approval
            JOIN plan_revision revision ON revision.id = approval.plan_revision_id
            JOIN plan_stage plan ON plan.stage_id = revision.plan_stage_id
            WHERE approval.id = NEW.proof_id
              AND plan.task_id = NEW.task_id
              AND NEW.next_stage_kind = 'LOCAL_DEVELOPMENT')
            THEN RAISE(ABORT, 'Task receipt Plan approval proof is invalid')
        WHEN NEW.cause = 'OPEN_REMOTE_DEVELOPMENT' AND NOT EXISTS (
            SELECT 1
            FROM publish_operation operation
            JOIN remote_pr_binding binding
              ON binding.publish_operation_id = operation.id
            WHERE operation.task_id = NEW.task_id
              AND operation.local_development_stage_id = NEW.subject_stage_id
              AND operation.operation_id = NEW.subject_operation_id
              AND operation.task_epoch = NEW.subject_task_epoch
              AND operation.stage_generation = NEW.subject_stage_generation
              AND operation.semantic_attempt = NEW.subject_attempt
              AND operation.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND operation.expected_head_sha IS NEW.subject_expected_head_sha
              AND operation.expected_base_sha IS NEW.subject_expected_base_sha
              AND operation.status = 'SUCCEEDED'
              AND binding.task_id = NEW.task_id
              AND NEW.next_stage_kind = 'REMOTE_DEVELOPMENT')
            THEN RAISE(ABORT, 'Task receipt publish-result proof is invalid')
        WHEN NEW.cause = 'ACCEPT_BRAIN_VERDICT' AND NOT EXISTS (
            SELECT 1 FROM brain_review_episode brain
            JOIN task_turn turn ON turn.id = brain.task_turn_id
            WHERE brain.task_id = NEW.task_id
              AND brain.task_epoch = NEW.subject_task_epoch
              AND brain.local_development_stage_id IS NEW.subject_stage_id
              AND brain.stage_generation = NEW.subject_stage_generation
              AND turn.operation_id = NEW.subject_operation_id
              AND turn.attempt = NEW.subject_attempt
              AND brain.code_fingerprint
                    IS NEW.subject_expected_code_fingerprint
              AND brain.expected_head_sha IS NEW.subject_expected_head_sha
              AND brain.expected_base_sha IS NEW.subject_expected_base_sha
              AND brain.verdict = NEW.brain_verdict
              AND brain.status = 'SUCCEEDED')
            THEN RAISE(ABORT, 'Task receipt Brain proof is invalid')
    END;
END;
CREATE TRIGGER task_command_receipt_remote_brain_id_collision
BEFORE INSERT ON task_command_receipt
WHEN EXISTS (SELECT 1 FROM remote_task_brain_receipt remote
             WHERE remote.task_id = NEW.task_id
               AND remote.command_id = NEW.command_id)
BEGIN SELECT RAISE(ABORT, 'Task command id is already used by Remote Brain'); END;
CREATE TRIGGER task_command_receipt_v256_control_proof
BEFORE INSERT ON task_command_receipt
WHEN NEW.cause IN ('COMPLETE_PAUSE', 'COMPLETE_RESUME', 'COMPLETE_ARCHIVE')
BEGIN
    SELECT CASE
        WHEN NEW.cause = 'COMPLETE_PAUSE' AND NOT EXISTS (
            SELECT 1 FROM task_pause_evidence evidence
            JOIN task_pause_evidence_digest_v230 digest
              ON digest.barrier_id = evidence.barrier_id
            JOIN task_current_stage current ON current.task_id = evidence.task_id
            JOIN task_control_live_work_v256 live ON live.task_id = evidence.task_id
            WHERE evidence.barrier_id = NEW.proof_id
              AND evidence.task_id = NEW.task_id
              AND evidence.task_epoch = NEW.expected_task_epoch
              AND evidence.task_epoch = NEW.returned_epoch
              AND evidence.stage_id = NEW.returned_current_stage_id
              AND current.stage_id = evidence.stage_id
              AND current.stage_generation = evidence.stage_generation
              AND evidence.stop_evidence_digest = digest.content_digest
              AND evidence.status = 'SATISFIED'
              AND live.active_task_turn_count = 0
              AND live.active_stage_turn_count = 0
              AND live.active_review_turn_count = 0
              AND live.active_dispatch_count = 0
              AND live.active_agent_execution_count = 0
              AND NEW.returned_lifecycle = 'PAUSED')
            THEN RAISE(ABORT, 'Task receipt PauseEvidence is not exact')
        WHEN NEW.cause = 'COMPLETE_RESUME' AND NOT (
            (EXISTS (
                SELECT 1 FROM task_resume_reconciliation_v256 evidence
                JOIN task_resume_evidence_digest_v256 digest ON digest.id = evidence.id
                JOIN task_current_stage current ON current.task_id = evidence.task_id
                JOIN task_control_live_work_v256 live ON live.task_id = evidence.task_id
                WHERE evidence.id = NEW.proof_id
                  AND evidence.task_id = NEW.task_id
                  AND evidence.task_epoch = NEW.expected_task_epoch
                  AND evidence.task_epoch = NEW.returned_epoch
                  AND evidence.stage_id = NEW.returned_current_stage_id
                  AND current.stage_id = evidence.stage_id
                  AND current.stage_generation = evidence.stage_generation
                  AND evidence.reconciliation_digest = digest.content_digest
                  AND evidence.status = 'SATISFIED'
                  AND live.active_task_turn_count = 0
                  AND live.active_stage_turn_count = 0
                  AND live.active_review_turn_count = 0
                  AND live.active_dispatch_count = 0
                  AND live.active_agent_execution_count = 0
                  AND NEW.returned_lifecycle = 'ACTIVE')
            OR EXISTS (
                SELECT 1 FROM task_resume_reconciliation evidence
                JOIN task_resume_evidence_digest_v230 digest ON digest.id = evidence.id
                JOIN task_current_stage current ON current.task_id = evidence.task_id
                JOIN task_control_live_work_v256 live ON live.task_id = evidence.task_id
                WHERE evidence.id = NEW.proof_id
                  AND evidence.task_id = NEW.task_id
                  AND evidence.task_epoch = NEW.expected_task_epoch
                  AND evidence.task_epoch = NEW.returned_epoch
                  AND evidence.stage_id = NEW.returned_current_stage_id
                  AND current.stage_id = evidence.stage_id
                  AND current.stage_generation = evidence.stage_generation
                  AND evidence.reconciliation_digest = digest.content_digest
                  AND evidence.status = 'SATISFIED'
                  AND live.active_task_turn_count = 0
                  AND live.active_stage_turn_count = 0
                  AND live.active_review_turn_count = 0
                  AND live.active_dispatch_count = 0
                  AND live.active_agent_execution_count = 0
                  AND NEW.returned_lifecycle = 'ACTIVE'))
            AND EXISTS (
                SELECT 1 FROM task_resume_handoff_v256 handoff
                JOIN task_resume_handoff_digest_v256 digest ON digest.id = handoff.id
                JOIN task_current_stage current ON current.task_id = handoff.task_id
                JOIN stage owner ON owner.id = current.stage_id
                JOIN task_current_code_subject_v230 code
                  ON code.task_id = handoff.task_id
                WHERE handoff.reconciliation_id = NEW.proof_id
                  AND handoff.task_id = NEW.task_id
                  AND handoff.task_epoch = NEW.expected_task_epoch
                  AND handoff.task_epoch = NEW.returned_epoch
                  AND handoff.task_version = NEW.expected_task_version
                  AND handoff.stage_id = NEW.returned_current_stage_id
                  AND current.stage_id = handoff.stage_id
                  AND current.stage_generation = handoff.stage_generation
                  AND owner.kind = handoff.stage_kind
                  AND owner.generation = handoff.stage_generation
                  AND owner.version = handoff.stage_version
                  AND owner.checkpoint = handoff.restore_checkpoint
                  AND owner.completed_at_ms IS NULL
                  AND code.code_fingerprint = handoff.code_fingerprint
                  AND code.head_sha = handoff.head_sha
                  AND code.base_sha = handoff.base_sha
                  AND handoff.request_digest = digest.content_digest
                  AND handoff.status = 'ACCEPTED'))
            THEN RAISE(ABORT, 'Task receipt ResumeEvidence is not exact')
        WHEN NEW.cause = 'COMPLETE_ARCHIVE' AND NOT EXISTS (
            SELECT 1 FROM task_archive_liveness evidence
            JOIN task_archive_evidence_digest_v230 digest ON digest.id = evidence.id
            JOIN task_current_stage current ON current.task_id = evidence.task_id
            JOIN task_control_live_work_v256 live ON live.task_id = evidence.task_id
            WHERE evidence.id = NEW.proof_id
              AND evidence.task_id = NEW.task_id
              AND evidence.task_epoch = NEW.expected_task_epoch
              AND evidence.task_epoch = NEW.returned_epoch
              AND evidence.stage_id = NEW.returned_current_stage_id
              AND current.stage_id = evidence.stage_id
              AND current.stage_generation = evidence.stage_generation
              AND evidence.liveness_digest = digest.content_digest
              AND evidence.status = 'SATISFIED'
              AND live.active_task_turn_count = 0
              AND live.active_stage_turn_count = 0
              AND live.active_review_turn_count = 0
              AND live.active_dispatch_count = 0
              AND live.active_agent_execution_count = 0
              AND NEW.returned_lifecycle = 'ARCHIVED')
            THEN RAISE(ABORT, 'Task receipt ArchiveEvidence is not exact')
    END;
END;
CREATE TRIGGER task_creation_context_immutable
BEFORE UPDATE ON task_creation_context
BEGIN SELECT RAISE(ABORT, 'Task creation context is immutable'); END;
CREATE TRIGGER task_creation_context_owner_insert
BEFORE INSERT ON task_creation_context
WHEN NEW.authorization_id IS NULL
  OR NOT EXISTS (
      SELECT 1 FROM tasks task
      JOIN trunk_task_creation_authorization authorization
        ON authorization.id = NEW.authorization_id
      WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
        AND task.thread_id = authorization.trunk_id
        AND task.assignment_id = NEW.assignment_id
        AND task.policy_revision_id = NEW.policy_revision_id
        AND authorization.assignment_id = NEW.assignment_id
        AND authorization.policy_revision_id = NEW.policy_revision_id
        AND authorization.provenance = NEW.provenance
        AND authorization.repository_id = NEW.repository_id
        AND authorization.upstream_repository_id IS NEW.upstream_repository_id
        AND authorization.publish_repository_id = NEW.publish_repository_id
        AND authorization.base_source = NEW.base_source
        AND authorization.base_repository_id = NEW.base_repository_id
        AND authorization.base_ref IS NEW.base_ref
        AND authorization.planning_base_sha IS NEW.planning_base_sha
        AND authorization.assignment_base_sha IS NEW.assignment_base_sha
        AND authorization.assignment_head_sha IS NEW.assignment_head_sha
        AND authorization.engine_snapshot = NEW.engine_snapshot
        AND authorization.work_model_snapshot = NEW.work_model_snapshot)
BEGIN SELECT RAISE(ABORT, 'Task creation context does not consume exact Trunk authorization'); END;
CREATE TRIGGER task_creation_receipt_dispatch_wake_insert
BEFORE INSERT ON task_creation_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM outbox wake
    JOIN dispatch_ticket ticket ON ticket.id = wake.aggregate_id
    WHERE ticket.id = NEW.dispatch_ticket_id
      AND ticket.operation_id = NEW.operation_id
      AND ticket.status = 'REQUESTED'
      AND wake.id = 'V2_DISPATCH_TICKET_REQUESTED:' || ticket.id
      AND wake.dedup_key = wake.id
      AND wake.aggregate_kind = 'DISPATCH_TICKET'
      AND wake.aggregate_id = ticket.id
      AND wake.topic = 'V2_DISPATCH_TICKET_REQUESTED'
      AND wake.payload = ticket.id
      AND wake.status = 'PENDING'
      AND wake.attempts = 0
      AND wake.available_at_ms = ticket.created_at_ms
      AND wake.created_at_ms = ticket.created_at_ms
      AND wake.claim_owner IS NULL
      AND wake.lease_until_ms IS NULL
      AND wake.delivered_at_ms IS NULL
      AND wake.last_error IS NULL)
BEGIN
    SELECT RAISE(ABORT, 'Task creation receipt lacks exact DispatchTicket wake');
END;
CREATE TRIGGER task_creation_receipt_immutable
BEFORE UPDATE ON task_creation_receipt
BEGIN SELECT RAISE(ABORT, 'Task creation receipt is immutable'); END;
CREATE TRIGGER task_creation_receipt_insert
BEFORE INSERT ON task_creation_receipt
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks task
            JOIN threads trunk ON trunk.id = task.thread_id
            JOIN trunk_task_creation_authorization authorization
              ON authorization.id = NEW.authorization_id
            JOIN task_assignment assignment ON assignment.id = task.assignment_id
            JOIN task_policy_revision policy ON policy.id = task.policy_revision_id
            JOIN task_creation_context context ON context.task_id = task.id
            JOIN task_brain brain ON brain.task_id = task.id
            JOIN task_provision_target target ON target.task_id = task.id
            WHERE task.id = NEW.task_id AND task.thread_id = NEW.trunk_id
              AND trunk.workspace_id = NEW.workspace_id
              AND trunk.turn_version = 'V2' AND task.workflow_version = 'V2'
              AND task.creation_receipt_id = NEW.id
              AND task.seq = NEW.task_seq AND task.epoch = NEW.task_epoch
              AND task.aggregate_version = NEW.task_version
              AND task.lifecycle_state = NEW.returned_lifecycle
              AND task.assignment_id = NEW.assignment_id
              AND task.policy_revision_id = NEW.policy_revision_id
              AND authorization.trunk_id = NEW.trunk_id
              AND authorization.workspace_id = NEW.workspace_id
              AND authorization.command_id = NEW.command_id
              AND authorization.actor = NEW.actor
              AND authorization.assignment_id = NEW.assignment_id
              AND authorization.policy_revision_id = NEW.policy_revision_id
              AND assignment.creation_authorization_id = authorization.id
              AND context.authorization_id = authorization.id
              AND brain.id = NEW.task_brain_id
              AND target.repository_id = context.repository_id
              AND target.publish_repository_id = context.publish_repository_id
              AND target.branch_name = NEW.requested_branch_name
              AND target.worktree_path = NEW.requested_worktree_path)
            THEN RAISE(ABORT, 'Task creation receipt owner/authorization graph is not exact')
        WHEN NOT EXISTS (
            SELECT 1 FROM provision_task_operation operation
            JOIN task_creation_context context ON context.task_id = operation.task_id
            JOIN task_provision_target target ON target.task_id = operation.task_id
            WHERE operation.id = NEW.provision_operation_id
              AND operation.task_id = NEW.task_id
              AND operation.task_epoch = NEW.task_epoch
              AND operation.assignment_id = NEW.assignment_id
              AND operation.operation_id = NEW.operation_id
              AND operation.semantic_attempt = NEW.semantic_attempt
              AND operation.repository_id = target.repository_id
              AND operation.base_source = context.base_source
              AND operation.base_repository_id = context.base_repository_id
              AND operation.base_ref IS context.base_ref
              AND operation.expected_base_sha IS CASE context.base_source
                    WHEN 'PLANNING_SNAPSHOT' THEN context.planning_base_sha
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_base_sha
                    ELSE NULL END
              AND operation.expected_remote_head_sha IS CASE context.base_source
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_head_sha
                    ELSE NULL END
              AND operation.requested_branch_name = target.branch_name
              AND operation.requested_worktree_path = target.worktree_path
              AND operation.status = 'REQUESTED'
              AND (SELECT COUNT(*) FROM provision_task_operation sibling
                   WHERE sibling.task_id = NEW.task_id) = 1)
            THEN RAISE(ABORT, 'Task creation receipt provisioning operation is not exact')
        WHEN NOT EXISTS (
            SELECT 1 FROM dispatch_ticket ticket
            JOIN task_creation_context context ON context.task_id = ticket.task_id
            WHERE ticket.id = NEW.dispatch_ticket_id
              AND ticket.operation_id = NEW.operation_id
              AND ticket.operation_kind = 'PROVISION_TASK'
              AND ticket.async_family = 'LOCAL_GIT'
              AND ticket.owner_kind = 'TASK' AND ticket.owner_id = NEW.task_id
              AND ticket.callback_route = 'TASK_PROVISION_RESULT'
              AND ticket.workspace_id = NEW.workspace_id
              AND ticket.trunk_id = NEW.trunk_id
              AND ticket.task_id = NEW.task_id
              AND ticket.task_epoch = NEW.task_epoch
              AND ticket.stage_id IS NULL AND ticket.stage_generation IS NULL
              AND ticket.attempt = NEW.semantic_attempt
              AND ticket.expected_code_fingerprint IS NULL
              AND ticket.expected_base_sha IS CASE context.base_source
                    WHEN 'PLANNING_SNAPSHOT' THEN context.planning_base_sha
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_base_sha
                    ELSE NULL END
              AND ticket.expected_head_sha IS CASE context.base_source
                    WHEN 'EXISTING_PR_HEAD' THEN context.assignment_head_sha
                    ELSE NULL END
              AND ticket.exclusive_task = 1 AND ticket.writer_required = 1
              AND ticket.lane_mask = CASE
                    WHEN context.base_source = 'EXISTING_PR_HEAD'
                      AND context.assignment_base_sha IS NULL
                      AND context.assignment_head_sha IS NULL THEN 48
                    ELSE 16 END
              AND ticket.status = 'REQUESTED'
              AND (SELECT COUNT(*) FROM dispatch_ticket sibling
                   WHERE sibling.operation_id = NEW.operation_id) = 1)
            THEN RAISE(ABORT, 'Task creation receipt DispatchTicket is not exact')
        WHEN NOT EXISTS (
            SELECT 1 FROM task_transition transition
            WHERE transition.task_id = NEW.task_id
              AND transition.command_id = NEW.command_id
              AND transition.epoch = NEW.task_epoch
              AND transition.from_state IS NULL
              AND transition.to_state = 'PROVISIONING'
              AND transition.aggregate_version = NEW.task_version
              AND transition.cause = 'CREATE_TASK'
              AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'Task creation receipt lacks exact Task transition')
        WHEN EXISTS (
            SELECT 1 FROM task_current_stage current
            WHERE current.task_id = NEW.task_id)
          OR EXISTS (
            SELECT 1 FROM task_code_identity code
            WHERE code.task_id = NEW.task_id)
            THEN RAISE(ABORT, 'new PROVISIONING Task cannot already own code or Stage')
    END;
END;
CREATE TRIGGER task_origin_immutable
BEFORE UPDATE OF origin ON tasks
WHEN NEW.origin <> OLD.origin
BEGIN
    SELECT RAISE(ABORT, 'task origin is immutable');
END;
CREATE TRIGGER task_outcome_create_trunk_inbox
AFTER INSERT ON task_outcome
BEGIN
    INSERT INTO trunk_outcome_inbox(
        id, trunk_id, task_id, task_outcome_id, delivery_key,
        fallback_summary_marker, fallback_summary_text, status,
        created_at_ms, delivered_at_ms, delivery_evidence,
        returned_trunk_version)
    SELECT 'TRUNK_OUTCOME:' || NEW.id, NEW.trunk_id, NEW.task_id, NEW.id,
        'TRUNK_OUTCOME:' || NEW.id,
        'FALLBACK:' || NEW.cleanup_summary_digest,
        CASE NEW.terminal_reason
          WHEN 'CANCELED' THEN CASE
            WHEN binding.remote_pr_number IS NULL
              THEN 'Canceled ' || COALESCE(
                NULLIF(trim(task.name), ''),
                NULLIF(trim(task.branch_name), ''),
                'Task ' || task.seq)
                || ' before opening a pull request.'
            ELSE 'Canceled ' || COALESCE(
                NULLIF(trim(task.name), ''),
                NULLIF(trim(task.branch_name), ''),
                'Task ' || task.seq)
                || ' (PR #' || binding.remote_pr_number
                || ' remains open).'
            END
          WHEN 'REMOTE_CLOSED' THEN
            'Shipped ' || COALESCE(
              NULLIF(trim(task.name), ''),
              NULLIF(trim(task.branch_name), ''),
              'Task ' || task.seq)
              || CASE WHEN binding.remote_pr_number IS NULL
                THEN ' — closed without merging.'
                ELSE ' (PR #' || binding.remote_pr_number
                  || ') — closed without merging.' END
          ELSE 'Shipped ' || COALESCE(
              NULLIF(trim(task.name), ''),
              NULLIF(trim(task.branch_name), ''),
              'Task ' || task.seq)
              || CASE WHEN binding.remote_pr_number IS NULL
                THEN ' — completed with no pull request opened.'
                ELSE ' (PR #' || binding.remote_pr_number
                  || ') — merged.' END
          END,
        'PENDING', NEW.recorded_at_ms, NULL, NULL, NULL
    FROM tasks task
    LEFT JOIN remote_pr_binding binding
      ON binding.id = NEW.remote_pr_binding_id
    WHERE task.id = NEW.task_id;
END;
CREATE TRIGGER task_outcome_delete_immutable
BEFORE DELETE ON task_outcome
WHEN NOT EXISTS (
    SELECT 1 FROM v2_trunk_purge_authorization_v269 authorization
    WHERE authorization.trunk_id = OLD.trunk_id)
BEGIN SELECT RAISE(ABORT, 'TaskOutcome cannot be deleted'); END;
CREATE TRIGGER task_outcome_identity_immutable
BEFORE UPDATE OF task_id, trunk_id, task_epoch, terminal_acceptance_id,
        cleanup_operation_id, cleanup_stage_id, terminal_reason, pr_id,
        remote_pr_binding_id, remote_terminal_observation_id,
        observed_head_sha, cleanup_summary_digest, recorded_at_ms
        ON task_outcome
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.trunk_id IS NOT OLD.trunk_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.terminal_acceptance_id IS NOT OLD.terminal_acceptance_id
  OR NEW.cleanup_operation_id IS NOT OLD.cleanup_operation_id
  OR NEW.cleanup_stage_id IS NOT OLD.cleanup_stage_id
  OR NEW.terminal_reason IS NOT OLD.terminal_reason
  OR NEW.pr_id IS NOT OLD.pr_id
  OR NEW.remote_pr_binding_id IS NOT OLD.remote_pr_binding_id
  OR NEW.remote_terminal_observation_id IS NOT OLD.remote_terminal_observation_id
  OR NEW.observed_head_sha IS NOT OLD.observed_head_sha
  OR NEW.cleanup_summary_digest IS NOT OLD.cleanup_summary_digest
  OR NEW.recorded_at_ms IS NOT OLD.recorded_at_ms
BEGIN SELECT RAISE(ABORT, 'TaskOutcome identity is immutable'); END;
CREATE TRIGGER task_outcome_insert
BEFORE INSERT ON task_outcome
WHEN NEW.summary_state <> 'FALLBACK'
  OR NOT EXISTS (
    SELECT 1 FROM tasks task
    JOIN threads trunk ON trunk.id = task.thread_id
    JOIN task_terminal_acceptance acceptance
      ON acceptance.id = NEW.terminal_acceptance_id
    JOIN cleanup_operation cleanup ON cleanup.id = NEW.cleanup_operation_id
    JOIN cleanup_stage cleanup_owner ON cleanup_owner.stage_id = NEW.cleanup_stage_id
    JOIN stage owner ON owner.id = cleanup_owner.stage_id
    JOIN task_current_stage current ON current.stage_id = owner.id
    JOIN dispatch_ticket ticket ON ticket.id = cleanup.dispatch_ticket_id
    WHERE task.id = NEW.task_id
      AND task.thread_id = NEW.trunk_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'CLEANING'
      AND task.epoch = NEW.task_epoch
      AND trunk.turn_version = 'V2'
      AND acceptance.task_id = NEW.task_id
      AND acceptance.task_epoch = NEW.task_epoch
      AND acceptance.kind = NEW.terminal_reason
      AND acceptance.remote_terminal_observation_id
            IS NEW.remote_terminal_observation_id
      AND acceptance.observed_head_sha IS NEW.observed_head_sha
      AND cleanup.cleanup_stage_id = NEW.cleanup_stage_id
      AND cleanup.task_id = NEW.task_id
      AND cleanup.task_epoch = NEW.task_epoch
      AND cleanup.terminal_acceptance_id = acceptance.id
      AND cleanup.status = 'COMPLETED'
      AND cleanup.summary_digest = NEW.cleanup_summary_digest
      AND cleanup_owner.task_id = NEW.task_id
      AND cleanup_owner.task_epoch = NEW.task_epoch
      AND cleanup_owner.terminal_reason = NEW.terminal_reason
      AND owner.checkpoint = 'COMPLETED'
      AND owner.completed_at_ms IS NOT NULL
      AND current.task_id = NEW.task_id
      AND current.stage_generation = owner.generation
      AND ticket.status = 'SUCCEEDED'
      AND ticket.delivery_acceptance = 'ACCEPTED'
      AND ticket.delivery_evidence IS NOT NULL
      AND ((NEW.remote_pr_binding_id IS NULL
            AND NEW.pr_id IS NULL)
        OR EXISTS (
            SELECT 1 FROM remote_pr_binding binding
            WHERE binding.id = NEW.remote_pr_binding_id
              AND binding.task_id = NEW.task_id
              AND binding.pr_id = NEW.pr_id))
      AND (NEW.remote_terminal_observation_id IS NULL OR EXISTS (
            SELECT 1 FROM remote_terminal_observation remote
            WHERE remote.id = NEW.remote_terminal_observation_id
              AND remote.task_id = NEW.task_id
              AND remote.task_epoch = NEW.task_epoch
              AND remote.remote_pr_binding_id = NEW.remote_pr_binding_id
              AND remote.head_sha = NEW.observed_head_sha)))
BEGIN SELECT RAISE(ABORT, 'TaskOutcome lacks exact accepted Cleanup proof'); END;
CREATE TRIGGER task_outcome_summary_operation_delete_immutable
BEFORE DELETE ON task_outcome_summary_operation
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'Task outcome summary operation cannot be deleted'); END;
CREATE TRIGGER task_outcome_summary_operation_identity_immutable
BEFORE UPDATE OF task_outcome_id, task_id, task_epoch, task_turn_id,
        dispatch_ticket_id, operation_id, semantic_attempt, requested_at_ms
        ON task_outcome_summary_operation
WHEN NEW.task_outcome_id IS NOT OLD.task_outcome_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.task_turn_id IS NOT OLD.task_turn_id
  OR NEW.dispatch_ticket_id IS NOT OLD.dispatch_ticket_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'Task outcome summary identity is immutable'); END;
CREATE TRIGGER task_outcome_summary_operation_insert
BEFORE INSERT ON task_outcome_summary_operation
WHEN NEW.status <> 'REQUESTED'
  OR NEW.semantic_attempt <> COALESCE((
      SELECT MAX(previous.semantic_attempt) + 1
      FROM task_outcome_summary_operation previous
      WHERE previous.task_outcome_id = NEW.task_outcome_id), 1)
  OR NOT EXISTS (
      SELECT 1 FROM task_outcome outcome
      JOIN tasks task ON task.id = outcome.task_id
      JOIN task_turn turn ON turn.id = NEW.task_turn_id
      JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
      JOIN outbox wake ON wake.aggregate_id = ticket.id
      WHERE outcome.id = NEW.task_outcome_id
        AND outcome.task_id = NEW.task_id
        AND outcome.task_epoch = NEW.task_epoch
        AND outcome.summary_state = 'FALLBACK'
        AND task.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
        AND task.epoch = NEW.task_epoch
        AND turn.task_id = NEW.task_id
        AND turn.task_epoch = NEW.task_epoch
        AND turn.purpose = 'TASK_COMPLETION_SUMMARY'
        AND turn.status = 'REQUESTED'
        AND turn.operation_id = NEW.operation_id
        AND turn.attempt = NEW.semantic_attempt
        AND turn.trigger_stage_id IS NULL
        AND ticket.operation_id = NEW.operation_id
        AND ticket.operation_kind = 'GENERATE_TASK_OUTCOME_SUMMARY'
        AND ticket.async_family = 'AGENT_TURN'
        AND ticket.owner_kind = 'TASK_TURN'
        AND ticket.owner_id = turn.id
        AND ticket.callback_route = 'TASK_OUTCOME_SUMMARY_RESULT'
        AND ticket.lane_mask IN (9, 10)
        AND ticket.trunk_control = 0
        AND ticket.exclusive_task = 0
        AND ticket.writer_required = 0
        AND ticket.task_id = NEW.task_id
        AND ticket.task_epoch = NEW.task_epoch
        AND ticket.stage_id IS NULL
        AND ticket.stage_generation IS NULL
        AND ticket.attempt = NEW.semantic_attempt
        AND ticket.status = 'REQUESTED'
        AND wake.id = 'V2_DISPATCH_TICKET_REQUESTED:' || ticket.id
        AND wake.dedup_key = wake.id
        AND wake.aggregate_kind = 'DISPATCH_TICKET'
        AND wake.topic = 'V2_DISPATCH_TICKET_REQUESTED'
        AND wake.payload = ticket.id
        AND wake.status = 'PENDING'
        AND wake.attempts = 0
        AND wake.available_at_ms = ticket.created_at_ms
        AND wake.created_at_ms = ticket.created_at_ms
        AND wake.claim_owner IS NULL AND wake.lease_until_ms IS NULL
        AND wake.delivered_at_ms IS NULL AND wake.last_error IS NULL)
BEGIN SELECT RAISE(ABORT, 'Task outcome summary lacks exact async dispatch'); END;
CREATE TRIGGER task_outcome_summary_operation_non_success
BEFORE UPDATE OF status ON task_outcome_summary_operation
WHEN NEW.status IN ('FAILED', 'CANCELED')
  AND (NEW.completed_at_ms IS NULL
    OR NEW.summary_text IS NOT NULL OR NEW.summary_digest IS NOT NULL
    OR (NEW.status = 'FAILED' AND NEW.error_message IS NULL)
    OR NOT EXISTS (
        SELECT 1 FROM task_turn turn
        JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
        WHERE turn.id = NEW.task_turn_id
          AND turn.operation_id = NEW.operation_id
          AND turn.status = NEW.status
          AND turn.finished_at_ms IS NOT NULL
          AND ticket.operation_id = NEW.operation_id
          AND ticket.status = 'RESULT_PENDING'
          AND ((NEW.status = 'FAILED'
                AND ticket.pending_result_outcome IN (
                    'FAILED', 'INDETERMINATE'))
            OR (NEW.status = 'CANCELED'
                AND ticket.pending_result_outcome = 'CANCELED'))
          AND ticket.pending_result_evidence IS NOT NULL
          AND ticket.pending_result_task_epoch = NEW.task_epoch
          AND ticket.pending_result_stage_id IS NULL
          AND ticket.pending_result_stage_generation IS NULL
          AND ticket.pending_result_operation_id = NEW.operation_id
          AND ticket.pending_result_attempt = NEW.semantic_attempt))
BEGIN SELECT RAISE(ABORT, 'Task outcome summary failure lacks exact result'); END;
CREATE TRIGGER task_outcome_summary_operation_result_fields
BEFORE UPDATE OF summary_text, summary_digest, error_message, completed_at_ms
        ON task_outcome_summary_operation
WHEN NEW.status IS OLD.status
  AND (NEW.summary_text IS NOT OLD.summary_text
    OR NEW.summary_digest IS NOT OLD.summary_digest
    OR NEW.error_message IS NOT OLD.error_message
    OR NEW.completed_at_ms IS NOT OLD.completed_at_ms)
BEGIN SELECT RAISE(ABORT, 'Task outcome summary result changes only with status'); END;
CREATE TRIGGER task_outcome_summary_operation_success
BEFORE UPDATE OF status ON task_outcome_summary_operation
WHEN NEW.status = 'SUCCEEDED'
  AND (NEW.completed_at_ms IS NULL OR NEW.summary_text IS NULL
    OR NEW.summary_digest IS NULL OR length(NEW.summary_digest) <> 64
    OR NEW.error_message IS NOT NULL
    OR NOT EXISTS (
        SELECT 1 FROM task_turn turn
        JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
        WHERE turn.id = NEW.task_turn_id
          AND turn.operation_id = NEW.operation_id
          AND turn.status = 'SUCCEEDED'
          AND turn.finished_at_ms IS NOT NULL
          AND ticket.operation_id = NEW.operation_id
          AND ticket.status = 'RESULT_PENDING'
          AND ticket.pending_result_outcome = 'SUCCEEDED'
          AND ticket.pending_result_payload IS NOT NULL
          AND ticket.pending_result_evidence IS NOT NULL
          AND ticket.pending_result_task_epoch = NEW.task_epoch
          AND ticket.pending_result_stage_id IS NULL
          AND ticket.pending_result_stage_generation IS NULL
          AND ticket.pending_result_operation_id = NEW.operation_id
          AND ticket.pending_result_attempt = NEW.semantic_attempt))
BEGIN SELECT RAISE(ABORT, 'Task outcome summary success lacks exact result'); END;
CREATE TRIGGER task_outcome_summary_operation_terminal_immutable
BEFORE UPDATE ON task_outcome_summary_operation
WHEN OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED')
BEGIN SELECT RAISE(ABORT, 'Terminal Task outcome summary is immutable'); END;
CREATE TRIGGER task_outcome_summary_operation_transition
BEFORE UPDATE OF status ON task_outcome_summary_operation
WHEN NEW.status IS NOT OLD.status
  AND NOT (OLD.status = 'REQUESTED'
      AND NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED'))
BEGIN SELECT RAISE(ABORT, 'Task outcome summary transition is invalid'); END;
CREATE TRIGGER task_outcome_summary_update
BEFORE UPDATE ON task_outcome
WHEN NOT (OLD.summary_state = 'FALLBACK'
      AND NEW.summary_state = 'BRAIN_GENERATED'
      AND NEW.summary_text IS NOT OLD.summary_text
      AND NEW.summary_digest IS NOT OLD.summary_digest
      AND NEW.summary_operation_id IS NOT NULL
      AND NEW.summary_updated_at_ms IS NOT NULL
      AND NEW.follow_up_proposals_json IS NOT NULL
      AND json_valid(NEW.follow_up_proposals_json)
      AND NEW.backlog_items_json IS NOT NULL
      AND json_valid(NEW.backlog_items_json)
      AND EXISTS (
          SELECT 1 FROM task_outcome_summary_operation operation
          JOIN dispatch_ticket ticket ON ticket.id = operation.dispatch_ticket_id
          WHERE operation.id = NEW.summary_operation_id
            AND operation.task_outcome_id = OLD.id
            AND operation.task_id = OLD.task_id
            AND operation.task_epoch = OLD.task_epoch
            AND operation.status = 'SUCCEEDED'
            AND operation.summary_text = NEW.summary_text
            AND operation.summary_digest = NEW.summary_digest
            AND ticket.status = 'SUCCEEDED'
            AND ticket.delivery_acceptance = 'ACCEPTED'))
BEGIN SELECT RAISE(ABORT, 'TaskOutcome summary update lacks exact Brain result'); END;
CREATE TRIGGER task_pause_evidence_immutable
BEFORE UPDATE ON task_pause_evidence
BEGIN SELECT RAISE(ABORT, 'PauseEvidence is immutable'); END;
CREATE TRIGGER task_pause_evidence_insert
BEFORE INSERT ON task_pause_evidence
WHEN NEW.recorded_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
  OR NEW.stop_evidence_digest <> (
       'pause:v1:' || lower(hex(NEW.task_id)) || ':' || NEW.task_epoch || ':'
       || lower(hex(NEW.barrier_id)) || ':' || lower(hex(NEW.stage_id)) || ':'
       || NEW.stage_generation || ':' || lower(hex(NEW.restore_checkpoint)) || ':'
       || lower(hex(NEW.code_fingerprint)) || ':' || lower(hex(NEW.head_sha)) || ':'
       || lower(hex(NEW.base_sha)) || ':' || NEW.barrier_completed_at_ms || ':'
       || NEW.recorded_at_ms)
  OR NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_quiescence_barrier barrier ON barrier.task_id = task.id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    JOIN task_live_work_counts_v230 live ON live.task_id = task.id
    WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'PAUSING' AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.stage_id
      AND current.stage_generation = NEW.stage_generation
      AND owner.task_id = NEW.task_id AND owner.generation = NEW.stage_generation
      AND owner.checkpoint = NEW.restore_checkpoint AND owner.completed_at_ms IS NULL
      AND code.code_fingerprint = NEW.code_fingerprint
      AND code.head_sha = NEW.head_sha AND code.base_sha = NEW.base_sha
      AND barrier.id = NEW.barrier_id AND barrier.task_epoch = NEW.task_epoch
      AND barrier.reason = 'PAUSE' AND barrier.status = NEW.status
      AND barrier.completed_at_ms = NEW.barrier_completed_at_ms
      AND live.task_epoch = NEW.task_epoch
      AND live.active_task_turn_count = 0
      AND live.active_stage_turn_count = 0
      AND live.active_review_turn_count = 0
      AND live.active_plan_review_count = 0
      AND live.active_validation_count = 0
      AND live.active_brain_episode_count = 0
      AND live.active_provision_operation_count = 0
      AND live.active_dispatch_count = 0
      AND live.active_agent_execution_count = 0
      AND live.unreconciled_execution_count = 0
      AND live.active_quiescence_count = 0
      AND live.active_replan_count = 0
      AND live.active_publish_operation_count = 0
      AND live.unreconciled_publish_operation_count = 0
      AND live.active_publish_effect_count = 0
      AND NOT EXISTS (
          SELECT 1 FROM capacity_lease lease
          WHERE lease.workflow_source = 'V2'
            AND lease.task_id = NEW.task_id AND lease.task_epoch = NEW.task_epoch
            AND lease.released_at_ms IS NULL
            AND lease.expires_at_ms > NEW.recorded_at_ms)
      AND NOT EXISTS (
          SELECT 1 FROM worktree_leases lease
          WHERE lease.workflow_version = 'V2'
            AND lease.task_id = NEW.task_id AND lease.task_epoch = NEW.task_epoch
            AND lease.expires_at_ms > NEW.recorded_at_ms))
BEGIN SELECT RAISE(ABORT, 'PauseEvidence requires its exact satisfied stopped owner'); END;
CREATE TRIGGER task_pause_evidence_v256_all_epoch_fence
BEFORE INSERT ON task_pause_evidence
WHEN EXISTS (
    SELECT 1 FROM task_control_live_work_v256 live
    WHERE live.task_id = NEW.task_id
      AND (live.active_task_turn_count <> 0
        OR live.active_stage_turn_count <> 0
        OR live.active_review_turn_count <> 0
        OR live.active_dispatch_count <> 0
        OR live.active_agent_execution_count <> 0))
  OR EXISTS (
      SELECT 1 FROM capacity_lease lease
      WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
        AND lease.released_at_ms IS NULL
        AND lease.expires_at_ms > NEW.recorded_at_ms)
  OR EXISTS (
      SELECT 1 FROM worktree_leases lease
      WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
        AND lease.expires_at_ms > NEW.recorded_at_ms)
BEGIN SELECT RAISE(ABORT, 'PauseEvidence requires all Task work across epochs to stop'); END;
CREATE TRIGGER task_policy_command_intent_immutable
BEFORE UPDATE ON task_policy_command_intent
BEGIN SELECT RAISE(ABORT, 'Task policy command intent is immutable'); END;
CREATE TRIGGER task_policy_command_intent_insert
BEFORE INSERT ON task_policy_command_intent
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_policy_revision previous
      ON previous.id = NEW.previous_policy_revision_id
    JOIN task_policy_revision selected
      ON selected.id = NEW.selected_policy_revision_id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state NOT IN (
          'CLEANING', 'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
      AND task.epoch = NEW.expected_task_epoch
      AND task.aggregate_version = NEW.expected_task_version
      AND task.policy_revision_id = previous.id
      AND previous.trunk_id = task.thread_id
      AND selected.trunk_id = task.thread_id
      AND selected.revision > previous.revision
      AND selected.revision = (
          SELECT MAX(policy.revision)
          FROM task_policy_revision policy
          WHERE policy.trunk_id = task.thread_id)
      AND selected.source = 'TASK_POLICY_COMMAND'
      AND selected.created_by = NEW.actor)
BEGIN
    SELECT RAISE(ABORT, 'Task policy intent does not match the exact aggregate');
END;
CREATE TRIGGER task_policy_command_receipt_immutable
BEFORE UPDATE ON task_policy_command_receipt
BEGIN SELECT RAISE(ABORT, 'Task policy command receipt is immutable'); END;
CREATE TRIGGER task_policy_command_receipt_insert
BEFORE INSERT ON task_policy_command_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_policy_revision previous
      ON previous.id = NEW.previous_policy_revision_id
    JOIN task_policy_revision selected
      ON selected.id = NEW.selected_policy_revision_id
    JOIN task_policy_command_intent intent
      ON intent.id = NEW.intent_id
    JOIN task_transition transition
      ON transition.task_id = task.id
     AND transition.command_id = NEW.command_id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.epoch = NEW.expected_task_epoch
      AND task.aggregate_version = NEW.returned_task_version
      AND task.policy_revision_id = selected.id
      AND intent.task_id = NEW.task_id
      AND intent.command_id = NEW.command_id
      AND intent.actor = NEW.actor
      AND intent.expected_task_epoch = NEW.expected_task_epoch
      AND intent.expected_task_version = NEW.expected_task_version
      AND intent.previous_policy_revision_id = previous.id
      AND intent.selected_policy_revision_id = selected.id
      AND previous.trunk_id = task.thread_id
      AND selected.trunk_id = task.thread_id
      AND selected.revision > previous.revision
      AND transition.epoch = task.epoch
      AND transition.from_state = task.lifecycle_state
      AND transition.to_state = task.lifecycle_state
      AND transition.aggregate_version = NEW.returned_task_version
      AND transition.cause = 'REVISE_POLICY'
      AND transition.actor = NEW.actor)
BEGIN
    SELECT RAISE(ABORT, 'Task policy receipt lacks its exact aggregate revision');
END;
CREATE TRIGGER task_policy_revision_immutable
BEFORE UPDATE ON task_policy_revision
BEGIN SELECT RAISE(ABORT, 'task policy revision is immutable'); END;
CREATE TRIGGER task_policy_revision_sequence_insert
BEFORE INSERT ON task_policy_revision
WHEN length(trim(NEW.id)) = 0 OR length(trim(NEW.source)) = 0
  OR length(trim(NEW.created_by)) = 0
  OR NEW.revision <> COALESCE((
      SELECT MAX(policy.revision) + 1
      FROM task_policy_revision policy
      WHERE policy.trunk_id = NEW.trunk_id), 1)
  OR NOT EXISTS (
      SELECT 1 FROM threads trunk
      WHERE trunk.id = NEW.trunk_id AND trunk.turn_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'Task policy revision is not the next exact V2 revision'); END;
CREATE TRIGGER task_provision_failure_receipt_immutable
BEFORE UPDATE ON task_provision_failure_receipt
BEGIN SELECT RAISE(ABORT, 'provision failure receipt is immutable'); END;
CREATE TRIGGER task_provision_failure_receipt_insert
BEFORE INSERT ON task_provision_failure_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM provision_task_operation operation
    JOIN tasks task ON task.id = operation.task_id
    JOIN task_blocker blocker ON blocker.id = NEW.blocker_id
    WHERE operation.operation_id = NEW.operation_id
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.status = CASE NEW.raw_outcome
          WHEN 'CANCELED' THEN 'CANCELED' ELSE 'FAILED' END
      AND operation.completed_at_ms IS NOT NULL
      AND operation.error_message = NEW.error_message
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'PROVISIONING'
      AND task.epoch = NEW.task_epoch
      AND blocker.task_id = task.id
      AND blocker.stage_id IS NULL
      AND blocker.owner_kind = 'TASK'
      AND blocker.owner_id = task.id
      AND blocker.blocker_type = 'PROVISIONING_FAILED'
      AND blocker.status = 'OPEN')
BEGIN SELECT RAISE(ABORT, 'provision failure receipt is not exact'); END;
CREATE TRIGGER task_provision_plan_receipt_immutable
BEFORE UPDATE ON task_provision_plan_receipt
BEGIN SELECT RAISE(ABORT, 'provision-to-Plan receipt is immutable'); END;
CREATE TRIGGER task_provision_plan_receipt_insert
BEFORE INSERT ON task_provision_plan_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM provision_task_operation provision
    JOIN tasks task ON task.id = provision.task_id
    JOIN task_code_identity code
      ON code.task_id = task.id AND code.provision_operation_id = provision.id
    JOIN task_command_receipt task_receipt ON task_receipt.task_id = task.id
    JOIN stage s ON s.id = NEW.plan_stage_id
    JOIN plan_stage plan ON plan.stage_id = s.id
    JOIN stage_initial_result_request request ON request.stage_id = s.id
    JOIN task_turn turn ON turn.id = NEW.draft_turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.draft_ticket_id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = provision.task_epoch
      AND provision.operation_id = NEW.provision_operation_id
      AND provision.status = 'ACCEPTED'
      AND provision.result_evidence IS NOT NULL
      AND task_receipt.cause = 'ACCEPT_PROVISIONING'
      AND task_receipt.disposition = 'APPLIED'
      AND task_receipt.expected_task_epoch = provision.task_epoch
      AND task_receipt.subject_operation_id = provision.operation_id
      AND task_receipt.proof_id = provision.operation_id
      AND task_receipt.next_stage_id = s.id
      AND task_receipt.next_stage_kind = 'PLAN'
      AND task_receipt.next_stage_generation = NEW.plan_stage_generation
      AND task_receipt.returned_current_stage_id = s.id
      AND s.task_id = task.id AND s.kind = 'PLAN'
      AND s.generation = NEW.plan_stage_generation
      AND s.version = 1 AND s.checkpoint = 'DRAFTING'
      AND plan.task_id = task.id
      AND plan.generation = s.generation
      AND plan.opened_for_epoch = task.epoch
      AND request.cause = 'REQUEST_PLAN_DRAFT'
      AND request.turn_owner_kind = 'TASK_TURN'
      AND request.turn_id = NEW.draft_turn_id
      AND request.pending_operation_id = NEW.draft_operation_id
      AND turn.operation_id = NEW.draft_operation_id
      AND turn.purpose = 'PLAN_DRAFT'
      AND turn.status = 'REQUESTED'
      AND ticket.operation_id = NEW.draft_operation_id
      AND ticket.owner_kind = 'TASK_TURN'
      AND ticket.owner_id = turn.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'provision-to-Plan receipt is not exact'); END;
CREATE TRIGGER task_provision_target_immutable
BEFORE UPDATE ON task_provision_target
BEGIN SELECT RAISE(ABORT, 'Task provision target is immutable'); END;
CREATE TRIGGER task_provision_target_insert
BEFORE INSERT ON task_provision_target
WHEN NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_creation_context context ON context.task_id = task.id
    WHERE task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'PROVISIONING'
      AND task.epoch = 1
      AND context.repository_id = NEW.repository_id
      AND context.publish_repository_id = NEW.publish_repository_id)
BEGIN SELECT RAISE(ABORT, 'Task provision target lacks exact creation context'); END;
CREATE TRIGGER task_push_authorization_fence_immutable
BEFORE UPDATE OF workflow_version, task_epoch, stage_id, stage_generation,
        operation_id, semantic_attempt, expected_base_sha,
        head_sha, code_fingerprint ON task_push_authorization
WHEN NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.head_sha IS NOT OLD.head_sha
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
BEGIN SELECT RAISE(ABORT, 'push authorization fence is immutable'); END;
CREATE TRIGGER task_push_authorization_route_insert
BEFORE INSERT ON task_push_authorization
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = NEW.workflow_version)
    THEN RAISE(ABORT, 'push authorization workflow version does not match Task') END;
    SELECT CASE WHEN NEW.workflow_version = 'V2' AND (
        NEW.task_epoch IS NULL OR NEW.stage_id IS NULL
        OR NEW.stage_generation IS NULL OR NEW.operation_id IS NULL
        OR NEW.semantic_attempt IS NULL OR NEW.semantic_attempt <= 0
        OR NEW.expected_base_sha IS NULL
        OR NEW.head_sha IS NULL OR NEW.code_fingerprint IS NULL
        OR NOT EXISTS (
            SELECT 1 FROM stage s JOIN tasks t ON t.id = s.task_id
            WHERE s.id = NEW.stage_id
              AND s.generation = NEW.stage_generation
              AND t.id = NEW.task_id
              AND t.epoch = NEW.task_epoch))
    THEN RAISE(ABORT, 'V2 push authorization requires its complete fence') END;
END;
CREATE TRIGGER task_question_answer_transition
BEFORE UPDATE OF state, answer, answer_revision, answered_at_ms,
        answer_option_id, answer_free_form, answer_actor
ON task_question
WHEN NEW.state IS NOT OLD.state
BEGIN
    SELECT CASE WHEN OLD.state <> 'OPEN'
        OR NEW.state NOT IN ('ANSWERED', 'CANCELED')
        OR NEW.answer_revision <> OLD.answer_revision + 1
        OR NEW.answer_actor IS NULL OR length(trim(NEW.answer_actor)) = 0
        OR NEW.answer IS NULL OR length(trim(NEW.answer)) = 0
        OR NEW.answered_at_ms IS NULL OR NEW.answered_at_ms < OLD.created_at_ms
        OR NEW.state = 'ANSWERED'
            AND NEW.answer_option_id IS NULL AND NEW.answer_free_form IS NULL
        OR NEW.state = 'CANCELED' AND NEW.continuation_state <> 'CANCELED'
    THEN RAISE(ABORT, 'task question answer transition is invalid') END;
END;
CREATE TRIGGER task_question_continuation_scope
BEFORE UPDATE OF continuation_state, successor_turn_id ON task_question
WHEN NEW.continuation_state = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1
    FROM task_turn source
    JOIN task_turn successor ON successor.id = NEW.successor_turn_id
    WHERE source.id = OLD.turn_id
      AND successor.id <> source.id
      AND successor.task_id = source.task_id
      AND successor.task_epoch = source.task_epoch
      AND successor.trigger_stage_id IS source.trigger_stage_id
      AND successor.trigger_stage_generation IS source.trigger_stage_generation
      AND successor.expected_code_fingerprint IS source.expected_code_fingerprint
      AND successor.expected_head_sha IS source.expected_head_sha
      AND successor.expected_base_sha IS source.expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'task question successor fence is stale'); END;
CREATE TRIGGER task_question_continuation_transition
BEFORE UPDATE OF continuation_state, successor_turn_id, continuation_error
ON task_question
BEGIN
    SELECT CASE WHEN OLD.continuation_state = 'WAITING'
            AND NEW.continuation_state NOT IN ('WAITING', 'READY', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state = 'READY'
            AND NEW.continuation_state NOT IN ('READY', 'DISPATCHED', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state IN ('DISPATCHED', 'CANCELED', 'SUPERSEDED')
            AND (NEW.continuation_state IS NOT OLD.continuation_state
                OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
                OR NEW.continuation_error IS NOT OLD.continuation_error)
        OR NEW.continuation_state = 'DISPATCHED' AND NEW.successor_turn_id IS NULL
    THEN RAISE(ABORT, 'task question continuation is invalid') END;
END;
CREATE TRIGGER task_question_identity_immutable
BEFORE UPDATE ON task_question
WHEN NEW.id IS NOT OLD.id OR NEW.turn_id IS NOT OLD.turn_id
  OR NEW.call_id IS NOT OLD.call_id OR NEW.prompt IS NOT OLD.prompt
  OR NEW.context IS NOT OLD.context
  OR NEW.options_json IS NOT OLD.options_json
  OR NEW.allow_free_form IS NOT OLD.allow_free_form
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'task question identity is immutable'); END;
CREATE TRIGGER task_question_open_invariant
BEFORE UPDATE ON task_question
WHEN OLD.state = 'OPEN' AND NEW.state = 'OPEN'
 AND (NEW.answer IS NOT OLD.answer
   OR NEW.answer_revision IS NOT OLD.answer_revision
   OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
   OR NEW.answer_option_id IS NOT OLD.answer_option_id
   OR NEW.answer_free_form IS NOT OLD.answer_free_form
   OR NEW.answer_actor IS NOT OLD.answer_actor
   OR NEW.continuation_state IS NOT OLD.continuation_state
   OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
   OR NEW.continuation_error IS NOT OLD.continuation_error)
BEGIN SELECT RAISE(ABORT, 'open task question is immutable'); END;
CREATE TRIGGER task_question_terminal_immutable
BEFORE UPDATE ON task_question
WHEN OLD.state <> 'OPEN'
  AND (NEW.state IS NOT OLD.state OR NEW.answer IS NOT OLD.answer
    OR NEW.answer_revision IS NOT OLD.answer_revision
    OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
    OR NEW.answer_option_id IS NOT OLD.answer_option_id
    OR NEW.answer_free_form IS NOT OLD.answer_free_form
    OR NEW.answer_actor IS NOT OLD.answer_actor)
BEGIN SELECT RAISE(ABORT, 'terminal task question is immutable'); END;
CREATE TRIGGER task_quiescence_identity_immutable
BEFORE UPDATE OF task_id, task_epoch, reason, requested_at_ms
ON task_quiescence_barrier
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.reason IS NOT OLD.reason
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'quiescence barrier identity is immutable'); END;
CREATE TRIGGER task_quiescence_owner_insert
BEFORE INSERT ON task_quiescence_barrier
WHEN NEW.status <> 'REQUESTED'
  OR NOT EXISTS (
      SELECT 1 FROM tasks t
      WHERE t.id = NEW.task_id
        AND t.workflow_version = 'V2'
        AND t.epoch = NEW.task_epoch
        AND t.lifecycle_state IN ('ACTIVE', 'PAUSING', 'CANCELING', 'CLEANING'))
BEGIN SELECT RAISE(ABORT, 'quiescence barrier must start on its exact current V2 Task'); END;
CREATE TRIGGER task_quiescence_satisfied_fence
BEFORE UPDATE OF status ON task_quiescence_barrier
WHEN NEW.status = 'SATISFIED'
  AND (NEW.completed_at_ms IS NULL
    OR NEW.completed_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
    OR EXISTS (
        SELECT 1 FROM task_control_live_work_v256 live
        WHERE live.task_id = NEW.task_id
          AND (live.active_task_turn_count <> 0
            OR live.active_stage_turn_count <> 0
            OR live.active_review_turn_count <> 0
            OR live.active_dispatch_count <> 0
            OR live.active_agent_execution_count <> 0))
    OR EXISTS (
        SELECT 1 FROM capacity_lease lease
        WHERE lease.workflow_source = 'V2'
          AND lease.task_id = NEW.task_id
          AND lease.released_at_ms IS NULL
          AND lease.expires_at_ms > NEW.completed_at_ms)
    OR EXISTS (
        SELECT 1 FROM worktree_leases lease
        WHERE lease.workflow_version = 'V2'
          AND lease.task_id = NEW.task_id
          AND lease.expires_at_ms > NEW.completed_at_ms))
BEGIN SELECT RAISE(ABORT, 'quiescence requires all Task work across epochs to stop'); END;
CREATE TRIGGER task_quiescence_terminal_immutable
BEFORE UPDATE ON task_quiescence_barrier
WHEN OLD.status IN ('SATISFIED', 'FAILED', 'CANCELED')
BEGIN SELECT RAISE(ABORT, 'terminal quiescence barrier is immutable'); END;
CREATE TRIGGER task_quiescence_transition
BEFORE UPDATE OF status ON task_quiescence_barrier
WHEN OLD.status <> 'REQUESTED'
  OR NEW.status NOT IN ('SATISFIED', 'FAILED', 'CANCELED')
BEGIN SELECT RAISE(ABORT, 'illegal quiescence barrier transition'); END;
CREATE TRIGGER task_replan_applied_fence
BEFORE UPDATE ON task_replan_request
WHEN NEW.status = 'APPLIED'
  AND (NOT EXISTS (
      SELECT 1
      FROM tasks t
      JOIN plan_stage p ON p.task_id = t.id
      JOIN stage target ON target.id = p.stage_id
      JOIN stage source ON source.id = NEW.source_stage_id
      WHERE t.id = NEW.task_id
        AND t.workflow_version = 'V2'
        AND t.lifecycle_state = 'ACTIVE'
        AND t.epoch = NEW.target_task_epoch
        AND p.stage_id = NEW.new_plan_stage_id
        AND p.generation = NEW.new_plan_generation
        AND p.opened_for_epoch = NEW.target_task_epoch
        AND target.task_id = t.id
        AND target.kind = 'PLAN'
        AND target.generation = NEW.new_plan_generation
        AND target.checkpoint = 'DRAFTING'
        AND target.completed_at_ms IS NULL
        AND source.task_id = t.id
        AND source.id = NEW.source_stage_id
        AND source.generation = NEW.source_generation
        AND source.completed_at_ms IS NOT NULL
        AND source.end_reason = 'SUPERSEDED_BY_REPLAN'
        AND EXISTS (
            SELECT 1 FROM task_current_stage c
            WHERE c.task_id = t.id
              AND c.stage_id = p.stage_id
              AND c.stage_generation = p.generation))
    OR NOT EXISTS (
        SELECT 1 FROM task_quiescence_barrier q
        WHERE q.id = NEW.quiescence_barrier_id
          AND q.task_id = NEW.task_id
          AND q.task_epoch = NEW.source_task_epoch
          AND q.reason = 'REPLAN'
          AND q.status = 'SATISFIED'))
BEGIN SELECT RAISE(ABORT, 'applied replan requires its exact new Plan Stage and epoch'); END;
CREATE TRIGGER task_replan_plan_receipt_immutable
BEFORE UPDATE ON task_replan_plan_receipt
BEGIN SELECT RAISE(ABORT, 'replan-to-Plan receipt is immutable'); END;
CREATE TRIGGER task_replan_plan_receipt_insert
BEFORE INSERT ON task_replan_plan_receipt
WHEN NOT EXISTS (
    SELECT 1
    FROM task_replan_request replan
    JOIN tasks task ON task.id = replan.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage stage ON stage.id = current.stage_id
    JOIN plan_stage plan ON plan.stage_id = stage.id
    JOIN stage_initial_result_request request
      ON request.stage_id = stage.id
    JOIN task_turn turn ON turn.id = request.turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.draft_ticket_id
    WHERE replan.id = NEW.replan_request_id
      AND replan.task_id = NEW.task_id
      AND replan.status = 'APPLIED'
      AND replan.target_task_epoch = NEW.task_epoch
      AND replan.new_plan_stage_id = NEW.plan_stage_id
      AND replan.new_plan_generation = NEW.plan_stage_generation
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.plan_stage_id
      AND current.stage_generation = NEW.plan_stage_generation
      AND stage.kind = 'PLAN' AND stage.checkpoint = 'DRAFTING'
      AND stage.version = 1 AND stage.completed_at_ms IS NULL
      AND plan.generation = NEW.plan_stage_generation
      AND plan.opened_for_epoch = NEW.task_epoch
      AND request.cause = 'REQUEST_PLAN_DRAFT'
      AND request.turn_owner_kind = 'TASK_TURN'
      AND request.turn_id = NEW.draft_turn_id
      AND request.pending_operation_id = NEW.draft_operation_id
      AND turn.task_id = NEW.task_id AND turn.task_epoch = NEW.task_epoch
      AND turn.trigger_stage_id = NEW.plan_stage_id
      AND turn.trigger_stage_generation = NEW.plan_stage_generation
      AND turn.purpose = 'PLAN_DRAFT' AND turn.status = 'REQUESTED'
      AND turn.operation_id = NEW.draft_operation_id
      AND ticket.operation_id = NEW.draft_operation_id
      AND ticket.owner_kind = 'TASK_TURN' AND ticket.owner_id = turn.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'replan-to-Plan receipt is not exact'); END;
CREATE TRIGGER task_replan_request_identity_immutable
BEFORE UPDATE OF task_id, source_stage_id, source_generation,
        source_task_epoch, target_task_epoch, quiescence_barrier_id, command_id, reason,
        requested_by, requested_at_ms ON task_replan_request
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.source_stage_id IS NOT OLD.source_stage_id
  OR NEW.source_generation IS NOT OLD.source_generation
  OR NEW.source_task_epoch IS NOT OLD.source_task_epoch
  OR NEW.target_task_epoch IS NOT OLD.target_task_epoch
  OR NEW.quiescence_barrier_id IS NOT OLD.quiescence_barrier_id
  OR NEW.command_id IS NOT OLD.command_id
  OR NEW.reason IS NOT OLD.reason
  OR NEW.requested_by IS NOT OLD.requested_by
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'replan request fence is immutable'); END;
CREATE TRIGGER task_replan_request_owner_insert
BEFORE INSERT ON task_replan_request
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'replan request must start REQUESTED')
        WHEN NOT EXISTS (
            SELECT 1
            FROM tasks t
            JOIN stage s ON s.task_id = t.id
            JOIN task_quiescence_barrier q ON q.task_id = t.id
            WHERE t.id = NEW.task_id
              AND t.workflow_version = 'V2'
              AND t.epoch = NEW.source_task_epoch
              AND s.id = NEW.source_stage_id
              AND s.generation = NEW.source_generation
              AND s.completed_at_ms IS NULL
              AND q.id = NEW.quiescence_barrier_id
              AND q.task_epoch = NEW.source_task_epoch
              AND q.reason = 'REPLAN'
              AND q.status = 'REQUESTED'
              AND EXISTS (
                  SELECT 1 FROM task_current_stage c
                  WHERE c.task_id = t.id
                    AND c.stage_id = s.id
                    AND c.stage_generation = s.generation))
            THEN RAISE(ABORT, 'replan request must fence the current V2 Stage, epoch and barrier')
    END;
END;
CREATE TRIGGER task_replan_terminal_immutable
BEFORE UPDATE ON task_replan_request
WHEN OLD.status IN ('APPLIED', 'FAILED', 'CANCELED')
BEGIN SELECT RAISE(ABORT, 'terminal replan request is immutable'); END;
CREATE TRIGGER task_replan_transition
BEFORE UPDATE OF status ON task_replan_request
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN ('QUIESCING', 'CANCELED'))
    OR (OLD.status = 'QUIESCING' AND NEW.status IN ('APPLIED', 'FAILED', 'CANCELED')))
BEGIN SELECT RAISE(ABORT, 'illegal replan request transition'); END;
CREATE TRIGGER task_resume_handoff_v256_accept
BEFORE UPDATE ON task_resume_handoff_v256
WHEN NOT (
    OLD.status = 'PENDING' AND NEW.status = 'ACCEPTED'
    AND NEW.id IS OLD.id AND NEW.task_id IS OLD.task_id
    AND NEW.task_epoch IS OLD.task_epoch AND NEW.task_version IS OLD.task_version
    AND NEW.reconciliation_id IS OLD.reconciliation_id
    AND NEW.stage_id IS OLD.stage_id AND NEW.stage_kind IS OLD.stage_kind
    AND NEW.stage_generation IS OLD.stage_generation
    AND NEW.stage_version IS OLD.stage_version
    AND NEW.restore_checkpoint IS OLD.restore_checkpoint
    AND NEW.code_fingerprint IS OLD.code_fingerprint
    AND NEW.head_sha IS OLD.head_sha AND NEW.base_sha IS OLD.base_sha
    AND NEW.request_digest IS OLD.request_digest
    AND NEW.created_at_ms IS OLD.created_at_ms
    AND NEW.owner_proof_id IS NOT NULL AND length(trim(NEW.owner_proof_id)) > 0
    AND NEW.accepted_by IS NOT NULL AND length(trim(NEW.accepted_by)) > 0
    AND NEW.accepted_at_ms IS NOT NULL
    AND NEW.accepted_at_ms >= OLD.created_at_ms
    AND NEW.accepted_at_ms <= CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
    AND EXISTS (
        SELECT 1 FROM tasks task
        JOIN task_current_stage current ON current.task_id = task.id
        JOIN stage owner ON owner.id = current.stage_id
        JOIN task_current_code_subject_v230 code ON code.task_id = task.id
        JOIN task_resume_handoff_digest_v256 digest ON digest.id = OLD.id
        WHERE task.id = OLD.task_id AND task.workflow_version = 'V2'
          AND task.lifecycle_state = 'RESUMING'
          AND task.epoch = OLD.task_epoch
          AND task.aggregate_version = OLD.task_version
          AND current.stage_id = OLD.stage_id
          AND current.stage_generation = OLD.stage_generation
          AND owner.kind = OLD.stage_kind
          AND owner.generation = OLD.stage_generation
          AND owner.version = OLD.stage_version
          AND owner.checkpoint = OLD.restore_checkpoint
          AND owner.completed_at_ms IS NULL
          AND code.code_fingerprint = OLD.code_fingerprint
          AND code.head_sha = OLD.head_sha AND code.base_sha = OLD.base_sha
          AND OLD.request_digest = digest.content_digest))
BEGIN SELECT RAISE(ABORT, 'Resume handoff acceptance is not exact'); END;
CREATE TRIGGER task_resume_handoff_v256_insert
BEFORE INSERT ON task_resume_handoff_v256
WHEN NEW.status <> 'PENDING'
  OR NEW.created_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
  OR NEW.request_digest <> (
       'resume-handoff:v1:' || lower(hex(NEW.id)) || ':'
       || lower(hex(NEW.task_id)) || ':' || NEW.task_epoch || ':'
       || NEW.task_version || ':' || lower(hex(NEW.reconciliation_id)) || ':'
       || lower(hex(NEW.stage_id)) || ':' || lower(hex(NEW.stage_kind)) || ':'
       || NEW.stage_generation || ':' || NEW.stage_version || ':'
       || lower(hex(NEW.restore_checkpoint)) || ':'
       || lower(hex(NEW.code_fingerprint)) || ':'
       || lower(hex(NEW.head_sha)) || ':' || lower(hex(NEW.base_sha)) || ':'
       || NEW.created_at_ms)
  OR NOT EXISTS (
      SELECT 1
      FROM tasks task
      JOIN task_current_stage current ON current.task_id = task.id
      JOIN stage owner ON owner.id = current.stage_id
      JOIN task_current_code_subject_v230 code ON code.task_id = task.id
      JOIN task_control_live_work_v256 live ON live.task_id = task.id
      WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
        AND task.lifecycle_state = 'RESUMING'
        AND task.epoch = NEW.task_epoch
        AND task.aggregate_version = NEW.task_version
        AND current.stage_id = NEW.stage_id
        AND current.stage_generation = NEW.stage_generation
        AND owner.kind = NEW.stage_kind
        AND owner.generation = NEW.stage_generation
        AND owner.version = NEW.stage_version
        AND owner.checkpoint = NEW.restore_checkpoint
        AND owner.completed_at_ms IS NULL
        AND code.code_fingerprint = NEW.code_fingerprint
        AND code.head_sha = NEW.head_sha AND code.base_sha = NEW.base_sha
        AND live.active_task_turn_count = 0
        AND live.active_stage_turn_count = 0
        AND live.active_review_turn_count = 0
        AND live.active_dispatch_count = 0
        AND live.active_agent_execution_count = 0
        AND NOT EXISTS (
            SELECT 1 FROM capacity_lease lease
            WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
              AND lease.released_at_ms IS NULL
              AND lease.expires_at_ms > NEW.created_at_ms)
        AND NOT EXISTS (
            SELECT 1 FROM worktree_leases lease
            WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
              AND lease.expires_at_ms > NEW.created_at_ms)
        AND (EXISTS (
              SELECT 1 FROM task_resume_reconciliation_v256 evidence
              JOIN task_resume_evidence_digest_v256 digest ON digest.id = evidence.id
              WHERE evidence.id = NEW.reconciliation_id
                AND evidence.task_id = NEW.task_id
                AND evidence.task_epoch = NEW.task_epoch
                AND evidence.stage_id = NEW.stage_id
                AND evidence.stage_generation = NEW.stage_generation
                AND evidence.restore_checkpoint = NEW.restore_checkpoint
                AND evidence.code_fingerprint = NEW.code_fingerprint
                AND evidence.head_sha = NEW.head_sha
                AND evidence.base_sha = NEW.base_sha
                AND evidence.reconciliation_digest = digest.content_digest
                AND evidence.status = 'SATISFIED')
          OR EXISTS (
              SELECT 1 FROM task_resume_reconciliation evidence
              JOIN task_resume_evidence_digest_v230 digest ON digest.id = evidence.id
              WHERE evidence.id = NEW.reconciliation_id
                AND evidence.task_id = NEW.task_id
                AND evidence.task_epoch = NEW.task_epoch
                AND evidence.stage_id = NEW.stage_id
                AND evidence.stage_generation = NEW.stage_generation
                AND evidence.restore_checkpoint = NEW.restore_checkpoint
                AND evidence.paused_code_fingerprint = NEW.code_fingerprint
                AND evidence.paused_head_sha = NEW.head_sha
                AND evidence.paused_base_sha = NEW.base_sha
                AND evidence.reconciliation_digest = digest.content_digest
                AND evidence.status = 'SATISFIED')))
BEGIN SELECT RAISE(ABORT, 'Resume handoff lacks exact current Stage ownership'); END;
CREATE TRIGGER task_resume_reconciliation_immutable
BEFORE UPDATE ON task_resume_reconciliation
BEGIN SELECT RAISE(ABORT, 'ResumeEvidence is immutable'); END;
CREATE TRIGGER task_resume_reconciliation_insert
BEFORE INSERT ON task_resume_reconciliation
WHEN NEW.recorded_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
  OR NEW.reconciliation_digest <> (
       'resume:v1:' || lower(hex(NEW.task_id)) || ':' || NEW.task_epoch || ':'
       || lower(hex(NEW.id)) || ':' || lower(hex(NEW.pause_barrier_id)) || ':'
       || lower(hex(NEW.stage_id)) || ':' || NEW.stage_generation || ':'
       || lower(hex(NEW.restore_checkpoint)) || ':'
       || lower(hex(NEW.paused_code_fingerprint)) || ':'
       || lower(hex(NEW.paused_head_sha)) || ':' || lower(hex(NEW.paused_base_sha)) || ':'
       || NEW.active_task_turn_count || ':' || NEW.active_stage_turn_count || ':'
       || NEW.active_plan_review_count || ':' || NEW.active_validation_count || ':'
       || NEW.active_brain_episode_count || ':' || NEW.active_provision_operation_count || ':'
       || NEW.active_writer_dispatch_count || ':' || NEW.active_agent_execution_count || ':'
       || NEW.unreconciled_execution_count || ':' || NEW.live_writer_capacity_count || ':'
       || NEW.live_worktree_lease_count || ':' || NEW.active_publish_operation_count || ':'
       || NEW.unreconciled_publish_operation_count || ':'
       || NEW.active_publish_effect_count || ':' || NEW.recorded_at_ms)
  OR NOT EXISTS (
    SELECT 1
    FROM tasks task
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_pause_evidence paused ON paused.barrier_id = NEW.pause_barrier_id
    JOIN task_pause_evidence_digest_v230 pause_digest
      ON pause_digest.barrier_id = paused.barrier_id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    JOIN task_live_work_counts_v230 live ON live.task_id = task.id
    WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'RESUMING' AND task.epoch = NEW.task_epoch
      AND current.stage_id = NEW.stage_id
      AND current.stage_generation = NEW.stage_generation
      AND owner.task_id = NEW.task_id AND owner.generation = NEW.stage_generation
      AND owner.checkpoint = NEW.restore_checkpoint AND owner.completed_at_ms IS NULL
      AND paused.task_id = NEW.task_id AND paused.task_epoch = NEW.task_epoch
      AND paused.stage_id = NEW.stage_id
      AND paused.stage_generation = NEW.stage_generation
      AND paused.restore_checkpoint = NEW.restore_checkpoint
      AND paused.code_fingerprint = NEW.paused_code_fingerprint
      AND paused.head_sha = NEW.paused_head_sha AND paused.base_sha = NEW.paused_base_sha
      AND paused.stop_evidence_digest = pause_digest.content_digest
      AND code.code_fingerprint = NEW.paused_code_fingerprint
      AND code.head_sha = NEW.paused_head_sha AND code.base_sha = NEW.paused_base_sha
      AND paused.status = 'SATISFIED' AND paused.recorded_at_ms <= NEW.recorded_at_ms
      AND live.task_epoch = NEW.task_epoch
      AND live.active_task_turn_count = NEW.active_task_turn_count
      AND live.active_stage_turn_count = NEW.active_stage_turn_count
      AND live.active_plan_review_count = NEW.active_plan_review_count
      AND live.active_validation_count = NEW.active_validation_count
      AND live.active_brain_episode_count = NEW.active_brain_episode_count
      AND live.active_provision_operation_count = NEW.active_provision_operation_count
      AND live.active_writer_dispatch_count = NEW.active_writer_dispatch_count
      AND live.active_agent_execution_count = NEW.active_agent_execution_count
      AND live.unreconciled_execution_count = NEW.unreconciled_execution_count
      AND live.active_publish_operation_count = NEW.active_publish_operation_count
      AND live.unreconciled_publish_operation_count
            = NEW.unreconciled_publish_operation_count
      AND live.active_publish_effect_count = NEW.active_publish_effect_count
      AND (SELECT COUNT(*) FROM capacity_lease lease
           WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
             AND lease.task_epoch = NEW.task_epoch AND lease.writer_required = 1
             AND lease.released_at_ms IS NULL
             AND lease.expires_at_ms > NEW.recorded_at_ms)
            = NEW.live_writer_capacity_count
      AND (SELECT COUNT(*) FROM worktree_leases lease
           WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
             AND lease.task_epoch = NEW.task_epoch
             AND lease.expires_at_ms > NEW.recorded_at_ms)
            = NEW.live_worktree_lease_count)
BEGIN SELECT RAISE(ABORT, 'ResumeEvidence lacks exact paused reconciliation'); END;
CREATE TRIGGER task_resume_reconciliation_v256_immutable
BEFORE UPDATE ON task_resume_reconciliation_v256
BEGIN SELECT RAISE(ABORT, 'ResumeEvidence is immutable'); END;
CREATE TRIGGER task_resume_reconciliation_v256_insert
BEFORE INSERT ON task_resume_reconciliation_v256
WHEN NEW.recorded_at_ms > CAST(
        (julianday('now') - 2440587.5) * 86400000 AS INTEGER) + 1000
  OR NEW.reconciliation_digest <> (
       'resume:v2:' || lower(hex(NEW.task_id)) || ':' || NEW.task_epoch || ':'
       || lower(hex(NEW.id)) || ':' || lower(hex(NEW.source_kind)) || ':'
       || lower(hex(NEW.source_id)) || ':' || lower(hex(NEW.stage_id)) || ':'
       || NEW.stage_generation || ':' || lower(hex(NEW.restore_checkpoint)) || ':'
       || lower(hex(NEW.code_fingerprint)) || ':' || lower(hex(NEW.head_sha)) || ':'
       || lower(hex(NEW.base_sha)) || ':' || NEW.recorded_at_ms)
  OR NOT EXISTS (
      SELECT 1
      FROM tasks task
      JOIN task_current_stage current ON current.task_id = task.id
      JOIN stage owner ON owner.id = current.stage_id
      JOIN task_current_code_subject_v230 code ON code.task_id = task.id
      JOIN task_transition transition ON transition.task_id = task.id
      JOIN task_control_live_work_v256 live ON live.task_id = task.id
      WHERE task.id = NEW.task_id AND task.workflow_version = 'V2'
        AND task.lifecycle_state = 'RESUMING' AND task.epoch = NEW.task_epoch
        AND current.stage_id = NEW.stage_id
        AND current.stage_generation = NEW.stage_generation
        AND owner.generation = NEW.stage_generation
        AND owner.checkpoint = NEW.restore_checkpoint
        AND owner.completed_at_ms IS NULL
        AND code.code_fingerprint = NEW.code_fingerprint
        AND code.head_sha = NEW.head_sha AND code.base_sha = NEW.base_sha
        AND transition.aggregate_version = task.aggregate_version
        AND transition.to_state = 'RESUMING'
        AND transition.from_state = CASE NEW.source_kind
            WHEN 'PAUSE' THEN 'PAUSED' ELSE 'ARCHIVED' END
        AND live.active_task_turn_count = 0
        AND live.active_stage_turn_count = 0
        AND live.active_review_turn_count = 0
        AND live.active_dispatch_count = 0
        AND live.active_agent_execution_count = 0
        AND ((NEW.source_kind = 'PAUSE' AND EXISTS (
              SELECT 1 FROM task_pause_evidence evidence
              WHERE evidence.barrier_id = NEW.source_id
                AND evidence.task_id = NEW.task_id
                AND evidence.task_epoch = NEW.task_epoch
                AND evidence.stage_id = NEW.stage_id
                AND evidence.stage_generation = NEW.stage_generation
                AND evidence.restore_checkpoint = NEW.restore_checkpoint
                AND evidence.status = 'SATISFIED'))
          OR (NEW.source_kind = 'ARCHIVE' AND EXISTS (
              SELECT 1 FROM task_archive_liveness evidence
              WHERE evidence.id = NEW.source_id
                AND evidence.task_id = NEW.task_id
                AND evidence.task_epoch = NEW.task_epoch
                AND evidence.stage_id = NEW.stage_id
                AND evidence.stage_generation = NEW.stage_generation
                AND evidence.status = 'SATISFIED')))
        AND NOT EXISTS (
            SELECT 1 FROM capacity_lease lease
            WHERE lease.workflow_source = 'V2' AND lease.task_id = NEW.task_id
              AND lease.writer_required = 1 AND lease.released_at_ms IS NULL
              AND lease.expires_at_ms > NEW.recorded_at_ms)
        AND NOT EXISTS (
            SELECT 1 FROM worktree_leases lease
            WHERE lease.workflow_version = 'V2' AND lease.task_id = NEW.task_id
              AND lease.expires_at_ms > NEW.recorded_at_ms))
BEGIN SELECT RAISE(ABORT, 'ResumeEvidence lacks exact stopped predecessor proof'); END;
CREATE TRIGGER task_review_snapshot_identity_immutable_v286
BEFORE UPDATE OF id, review_id, pr_id, repository, remote_pr_number,
    base_branch, pr_title, pr_description, task_id, task_epoch, worktree_path,
    code_fingerprint, expected_head_sha, expected_base_sha,
    start_options_json, requested_at_ms
ON task_review_snapshot_operation_v286
BEGIN
    SELECT RAISE(ABORT, 'Task review snapshot identity is immutable');
END;
CREATE TRIGGER task_review_snapshot_operation_insert_v286
BEFORE INSERT ON task_review_snapshot_operation_v286
WHEN NOT EXISTS (
    SELECT 1
    FROM review_session review
    JOIN pr ON pr.id = review.pr_id
    JOIN tasks task ON task.id = pr.task_id
    JOIN threads trunk ON trunk.id = task.thread_id
    JOIN task_code_identity identity ON identity.task_id = task.id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE review.id = NEW.review_id
      AND review.pr_id = NEW.pr_id
      AND pr.repo IS NEW.repository
      AND pr.remote_pr_number IS NEW.remote_pr_number
      AND pr.base_branch = NEW.base_branch
      AND pr.title = NEW.pr_title
      AND pr.description = NEW.pr_description
      AND review.owner_task_id = NEW.task_id
      AND review.owner_thread_id = task.thread_id
      AND review.workspace_id = trunk.workspace_id
      AND review.status = 'ACTIVE'
      AND task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND identity.worktree_path = NEW.worktree_path
      AND code.code_fingerprint = NEW.code_fingerprint
      AND code.head_sha = NEW.expected_head_sha
      AND code.base_sha = NEW.expected_base_sha
      AND NEW.status = 'REQUESTED')
BEGIN
    SELECT RAISE(ABORT,
        'Task review snapshot requires an exact active V2 Task subject');
END;
CREATE TRIGGER task_review_snapshot_terminal_immutable_v286
BEFORE UPDATE ON task_review_snapshot_operation_v286
WHEN OLD.status <> 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT, 'Terminal Task review snapshot is immutable');
END;
CREATE TRIGGER task_review_snapshot_transition_v286
BEFORE UPDATE OF status ON task_review_snapshot_operation_v286
WHEN OLD.status <> 'REQUESTED' OR NEW.status = 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT, 'Task review snapshot has one terminal transition');
END;
CREATE TRIGGER task_terminal_acceptance_immutable
BEFORE UPDATE ON task_terminal_acceptance
BEGIN SELECT RAISE(ABORT, 'Task terminal acceptance is immutable'); END;
CREATE TRIGGER task_terminal_acceptance_insert
BEFORE INSERT ON task_terminal_acceptance
WHEN NOT EXISTS (
    SELECT 1 FROM task_terminal_intent intent
    JOIN tasks task ON task.id = intent.task_id
    WHERE intent.id = NEW.task_terminal_intent_id
      AND intent.task_id = NEW.task_id
      AND intent.accepted = 1
      AND intent.kind = NEW.kind
      AND intent.source = NEW.source_kind
      AND intent.source_id = NEW.source_id
      AND intent.observed_head_sha IS NEW.observed_head_sha
      AND task.workflow_version = 'V2'
      AND task.epoch = NEW.task_epoch
      AND ((NEW.source_kind = 'REMOTE_OBSERVATION'
            AND EXISTS (
                SELECT 1 FROM remote_terminal_observation remote
                WHERE remote.id = NEW.remote_terminal_observation_id
                  AND remote.task_terminal_intent_id = intent.id
                  AND remote.task_id = NEW.task_id
                  AND remote.task_epoch = NEW.task_epoch
                  AND remote.head_sha = NEW.observed_head_sha
                  AND remote.kind = CASE NEW.kind
                      WHEN 'COMPLETED' THEN 'MERGED' ELSE 'CLOSED' END))
        OR (NEW.source_kind = 'USER_CANCEL'
            AND task.lifecycle_state = 'CANCELING'
            AND EXISTS (
                SELECT 1 FROM task_transition transition
                WHERE transition.task_id = NEW.task_id
                  AND transition.command_id = NEW.source_id
                  AND transition.epoch = NEW.task_epoch
                  AND transition.to_state = 'CANCELING'))
        OR (NEW.source_kind = 'LOCAL_COMPLETION'
            AND task.lifecycle_state IN ('ACTIVE', 'PAUSED', 'ARCHIVED'))))
BEGIN SELECT RAISE(ABORT, 'Terminal acceptance lacks exact Task-owned intent proof'); END;
CREATE TRIGGER task_terminal_completion_marker
BEFORE UPDATE OF lifecycle_state ON tasks
WHEN OLD.workflow_version = 'V2'
  AND OLD.lifecycle_state = 'CLEANING'
  AND NEW.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
  AND NOT EXISTS (
      SELECT 1
      FROM task_outcome outcome
      JOIN trunk_outcome_inbox inbox ON inbox.task_outcome_id = outcome.id
      WHERE outcome.task_id = OLD.id
        AND outcome.task_epoch = OLD.epoch
        AND outcome.terminal_reason = NEW.lifecycle_state
        AND inbox.task_id = OLD.id
        AND inbox.trunk_id = outcome.trunk_id
        AND inbox.fallback_summary_text IS NOT NULL
        AND length(trim(inbox.fallback_summary_text)) > 0)
BEGIN SELECT RAISE(ABORT, 'Terminal Task lacks its completion marker'); END;
CREATE TRIGGER task_terminal_intent_immutable
BEFORE UPDATE ON task_terminal_intent
BEGIN SELECT RAISE(ABORT, 'task terminal intent is immutable'); END;
CREATE TRIGGER task_terminal_intent_owner_insert
BEFORE INSERT ON task_terminal_intent
WHEN NOT EXISTS (
    SELECT 1 FROM tasks t
    WHERE t.id = NEW.task_id AND t.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'terminal intent requires V2 Task'); END;
CREATE TRIGGER task_terminal_intent_remote_observation_insert
AFTER INSERT ON task_terminal_intent
WHEN NEW.source = 'REMOTE_OBSERVATION'
BEGIN
    INSERT INTO remote_terminal_observation(
        id, remote_development_stage_id, task_id, task_epoch,
        stage_generation, remote_pr_binding_id, remote_pr_snapshot_id,
        task_terminal_intent_id, kind, head_sha, base_sha,
        observed_at_ms, evidence)
    SELECT 'remote-terminal-observation:' || NEW.id,
        snapshot.remote_development_stage_id, snapshot.task_id,
        snapshot.task_epoch, snapshot.stage_generation,
        snapshot.remote_pr_binding_id, snapshot.id, NEW.id,
        CASE NEW.kind WHEN 'COMPLETED' THEN 'MERGED' ELSE 'CLOSED' END,
        snapshot.head_sha, snapshot.base_sha, snapshot.observed_at_ms,
        COALESCE(NEW.evidence_json, snapshot.raw_evidence,
            'accepted remote terminal observation')
    FROM remote_pr_snapshot snapshot
    JOIN remote_development_stage remote
      ON remote.stage_id = snapshot.remote_development_stage_id
    WHERE snapshot.id = NEW.source_id
      AND snapshot.task_id = NEW.task_id
      AND NEW.accepted = 1
      AND NEW.kind IN ('COMPLETED', 'REMOTE_CLOSED')
      AND NEW.observed_head_sha = snapshot.head_sha
      AND snapshot.pr_state = CASE NEW.kind
          WHEN 'COMPLETED' THEN 'MERGED' ELSE 'CLOSED' END
      AND remote.accepted_snapshot_id = snapshot.id
      AND remote.current_head_sha = snapshot.head_sha
      AND remote.current_base_sha = snapshot.base_sha;

    SELECT CASE WHEN changes() <> 1
        THEN RAISE(ABORT, 'Remote Task terminal intent lacks accepted exact-head truth') END;
END;
CREATE TRIGGER task_terminal_state_immutable
BEFORE UPDATE OF lifecycle_state ON tasks
WHEN OLD.workflow_version = 'V2'
  AND OLD.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
  AND NEW.lifecycle_state IS NOT OLD.lifecycle_state
BEGIN SELECT RAISE(ABORT, 'Terminal Task lifecycle is immutable'); END;
CREATE TRIGGER task_terminalize_after_cleanup
BEFORE UPDATE OF lifecycle_state ON tasks
WHEN OLD.workflow_version = 'V2'
  AND NEW.lifecycle_state IS NOT OLD.lifecycle_state
  AND (OLD.lifecycle_state = 'CLEANING'
        OR NEW.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
  AND NOT (OLD.lifecycle_state = 'CLEANING'
      AND NEW.lifecycle_state IN ('COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
      AND NEW.epoch = OLD.epoch
      AND EXISTS (
          SELECT 1 FROM task_outcome outcome
          JOIN trunk_outcome_inbox inbox
            ON inbox.task_outcome_id = outcome.id
          JOIN task_transition transition
            ON transition.task_id = outcome.task_id
          JOIN task_command_receipt receipt
            ON receipt.task_id = outcome.task_id
          WHERE outcome.task_id = OLD.id
            AND outcome.task_epoch = OLD.epoch
            AND outcome.terminal_reason = NEW.lifecycle_state
            AND inbox.trunk_id = outcome.trunk_id
            AND inbox.task_id = outcome.task_id
            AND inbox.delivery_key = 'TRUNK_OUTCOME:' || outcome.id
            AND inbox.fallback_summary_marker =
                'FALLBACK:' || outcome.cleanup_summary_digest
            AND inbox.status IN ('PENDING', 'DELIVERED')
            AND transition.command_id = receipt.command_id
            AND transition.epoch = OLD.epoch
            AND transition.from_state = 'CLEANING'
            AND transition.to_state = NEW.lifecycle_state
            AND transition.aggregate_version = NEW.aggregate_version
            AND transition.cause = 'ACCEPT_CLEANUP_COMPLETION'
            AND receipt.cause = transition.cause
            AND receipt.disposition = 'APPLIED'
            AND receipt.expected_task_epoch = OLD.epoch
            AND receipt.expected_task_version = OLD.aggregate_version
            AND receipt.returned_lifecycle = NEW.lifecycle_state
            AND receipt.returned_epoch = OLD.epoch
            AND receipt.returned_version = NEW.aggregate_version
            AND receipt.returned_current_stage_id IS NULL))
BEGIN SELECT RAISE(ABORT, 'Task terminal state lacks exact Cleanup outcome receipt'); END;
CREATE TRIGGER task_transition_immutable
BEFORE UPDATE ON task_transition
BEGIN SELECT RAISE(ABORT, 'task transition is immutable'); END;
CREATE TRIGGER task_turn_global_identity_insert
BEFORE INSERT ON task_turn
WHEN EXISTS (SELECT 1 FROM thread_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM stage_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM review_assignment_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
BEGIN SELECT RAISE(ABORT, 'typed Turn id and operation id must be globally exact'); END;
CREATE TRIGGER task_turn_identity_immutable
BEFORE UPDATE OF task_id, purpose, operation_id, attempt, task_epoch,
        trigger_stage_id, trigger_stage_generation, expected_code_fingerprint,
        expected_head_sha, expected_base_sha, delivery_lane, launch_input ON task_turn
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.purpose IS NOT OLD.purpose
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.attempt IS NOT OLD.attempt
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.trigger_stage_id IS NOT OLD.trigger_stage_id
  OR NEW.trigger_stage_generation IS NOT OLD.trigger_stage_generation
  OR NEW.expected_code_fingerprint IS NOT OLD.expected_code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.delivery_lane IS NOT OLD.delivery_lane
  OR NEW.launch_input IS NOT OLD.launch_input
BEGIN SELECT RAISE(ABORT, 'task Turn launch identity is immutable'); END;
CREATE TRIGGER task_turn_owner_fence_insert
BEFORE INSERT ON task_turn
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM tasks t
            WHERE t.id = NEW.task_id
              AND t.workflow_version = 'V2'
              AND t.epoch = NEW.task_epoch)
            THEN RAISE(ABORT, 'task Turn fence does not match V2 Task')
        WHEN NEW.trigger_stage_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM stage s
            WHERE s.id = NEW.trigger_stage_id
              AND s.task_id = NEW.task_id
              AND s.generation = NEW.trigger_stage_generation)
            THEN RAISE(ABORT, 'task Turn trigger Stage does not match Task')
    END;
END;
CREATE TRIGGER task_turn_user_wait_continuation_exact_v266
BEFORE INSERT ON task_turn_user_wait_continuation_v266
WHEN NOT EXISTS (
    SELECT 1
    FROM task_turn source
    JOIN typed_user_wait_result result
      ON result.operation_id = source.operation_id
    JOIN task_turn logical ON logical.id = NEW.logical_turn_id
    JOIN task_turn successor ON successor.id = NEW.successor_turn_id
    JOIN tasks task ON task.id = source.task_id
    LEFT JOIN task_turn_user_wait_continuation_v266 prior
      ON prior.successor_turn_id = source.id
    WHERE source.id = NEW.source_turn_id
      AND source.operation_id = NEW.source_operation_id
      AND source.status = 'SUCCEEDED'
      AND source.purpose = NEW.purpose
      AND result.owner_kind = 'TASK_TURN'
      AND result.turn_id = source.id
      AND result.wait_kind = NEW.wait_kind
      AND result.wait_id = NEW.wait_id
      AND logical.id = COALESCE(prior.logical_turn_id, source.id)
      AND logical.operation_id = NEW.logical_operation_id
      AND logical.purpose = source.purpose
      AND successor.id <> source.id
      AND successor.operation_id = NEW.successor_operation_id
      AND successor.status = 'REQUESTED'
      AND successor.purpose = source.purpose
      AND successor.task_id = source.task_id
      AND successor.task_epoch = source.task_epoch
      AND successor.attempt = source.attempt + 1
      AND successor.trigger_stage_id IS source.trigger_stage_id
      AND successor.trigger_stage_generation IS
          source.trigger_stage_generation
      AND successor.expected_code_fingerprint IS
          source.expected_code_fingerprint
      AND successor.expected_head_sha IS source.expected_head_sha
      AND successor.expected_base_sha IS source.expected_base_sha
      AND NEW.task_id = source.task_id
      AND NEW.task_epoch = source.task_epoch
      AND NEW.trigger_stage_id IS source.trigger_stage_id
      AND NEW.trigger_stage_generation IS source.trigger_stage_generation
      AND NEW.expected_code_fingerprint IS
          source.expected_code_fingerprint
      AND NEW.expected_head_sha IS source.expected_head_sha
      AND NEW.expected_base_sha IS source.expected_base_sha
      AND task.workflow_version = 'V2'
      AND task.epoch = source.task_epoch
      AND ((source.purpose = 'TASK_BRAIN_CONVERSATION'
            AND source.trigger_stage_id IS NULL
            AND task.lifecycle_state IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
        OR (source.trigger_stage_id IS NOT NULL
            AND task.lifecycle_state = 'ACTIVE'
            AND EXISTS (
                SELECT 1 FROM task_current_stage current
                JOIN stage owner ON owner.id = current.stage_id
                JOIN task_current_code_subject_v230 code
                  ON code.task_id = task.id
                WHERE current.task_id = task.id
                  AND current.stage_id = source.trigger_stage_id
                  AND current.stage_generation =
                      source.trigger_stage_generation
                  AND owner.completed_at_ms IS NULL
                  AND code.code_fingerprint IS
                      source.expected_code_fingerprint
                  AND code.head_sha IS source.expected_head_sha
                  AND code.base_sha IS source.expected_base_sha)))
      AND ((NEW.wait_kind = 'QUESTION' AND EXISTS (
            SELECT 1 FROM task_question question
            WHERE question.id = NEW.wait_id
              AND question.turn_id = source.id
              AND question.state = 'ANSWERED'
              AND question.continuation_state = 'READY'))
        OR (NEW.wait_kind = 'PERMISSION' AND EXISTS (
            SELECT 1 FROM permission_request permission
            WHERE permission.id = NEW.wait_id
              AND permission.turn_kind = 'TASK'
              AND permission.turn_id = source.id
              AND permission.operation_id = source.operation_id
              AND permission.state <> 'OPEN'
              AND permission.continuation_state = 'READY'))))
BEGIN SELECT RAISE(ABORT, 'Task Brain user-wait continuation is not exact'); END;
CREATE TRIGGER task_turn_user_wait_continuation_immutable_v266
BEFORE UPDATE ON task_turn_user_wait_continuation_v266
BEGIN SELECT RAISE(ABORT, 'Task Brain user-wait continuation is immutable'); END;
CREATE TRIGGER task_workflow_version_immutable
BEFORE UPDATE OF workflow_version ON tasks
WHEN NEW.workflow_version IS NOT OLD.workflow_version
BEGIN
    SELECT RAISE(ABORT, 'task workflow version is immutable');
END;
CREATE TRIGGER thread_question_answer_transition
BEFORE UPDATE OF state, answer, answer_revision, answered_at_ms,
        answer_option_id, answer_free_form, answer_actor
ON thread_question
WHEN NEW.state IS NOT OLD.state
BEGIN
    SELECT CASE WHEN OLD.state <> 'OPEN'
        OR NEW.state NOT IN ('ANSWERED', 'CANCELED')
        OR NEW.answer_revision <> OLD.answer_revision + 1
        OR NEW.answer_actor IS NULL OR length(trim(NEW.answer_actor)) = 0
        OR NEW.answer IS NULL OR length(trim(NEW.answer)) = 0
        OR NEW.answered_at_ms IS NULL OR NEW.answered_at_ms < OLD.created_at_ms
        OR NEW.state = 'ANSWERED'
            AND NEW.answer_option_id IS NULL AND NEW.answer_free_form IS NULL
        OR NEW.state = 'CANCELED' AND NEW.continuation_state <> 'CANCELED'
    THEN RAISE(ABORT, 'thread question answer transition is invalid') END;
END;
CREATE TRIGGER thread_question_continuation_scope
BEFORE UPDATE OF continuation_state, successor_turn_id ON thread_question
WHEN NEW.continuation_state = 'DISPATCHED' AND NOT EXISTS (
    SELECT 1
    FROM thread_turn source
    JOIN thread_turn successor ON successor.id = NEW.successor_turn_id
    WHERE source.id = OLD.turn_id
      AND successor.id <> source.id
      AND successor.trunk_id = source.trunk_id)
BEGIN SELECT RAISE(ABORT, 'thread question successor scope is stale'); END;
CREATE TRIGGER thread_question_continuation_transition
BEFORE UPDATE OF continuation_state, successor_turn_id, continuation_error
ON thread_question
BEGIN
    SELECT CASE WHEN OLD.continuation_state = 'WAITING'
            AND NEW.continuation_state NOT IN ('WAITING', 'READY', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state = 'READY'
            AND NEW.continuation_state NOT IN ('READY', 'DISPATCHED', 'CANCELED', 'SUPERSEDED')
        OR OLD.continuation_state IN ('DISPATCHED', 'CANCELED', 'SUPERSEDED')
            AND (NEW.continuation_state IS NOT OLD.continuation_state
                OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
                OR NEW.continuation_error IS NOT OLD.continuation_error)
        OR NEW.continuation_state = 'DISPATCHED' AND NEW.successor_turn_id IS NULL
    THEN RAISE(ABORT, 'thread question continuation is invalid') END;
END;
CREATE TRIGGER thread_question_identity_immutable
BEFORE UPDATE ON thread_question
WHEN NEW.id IS NOT OLD.id OR NEW.turn_id IS NOT OLD.turn_id
  OR NEW.call_id IS NOT OLD.call_id OR NEW.prompt IS NOT OLD.prompt
  OR NEW.context IS NOT OLD.context
  OR NEW.options_json IS NOT OLD.options_json
  OR NEW.allow_free_form IS NOT OLD.allow_free_form
  OR NEW.created_at_ms IS NOT OLD.created_at_ms
BEGIN SELECT RAISE(ABORT, 'thread question identity is immutable'); END;
CREATE TRIGGER thread_question_open_invariant
BEFORE UPDATE ON thread_question
WHEN OLD.state = 'OPEN' AND NEW.state = 'OPEN'
 AND (NEW.answer IS NOT OLD.answer
   OR NEW.answer_revision IS NOT OLD.answer_revision
   OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
   OR NEW.answer_option_id IS NOT OLD.answer_option_id
   OR NEW.answer_free_form IS NOT OLD.answer_free_form
   OR NEW.answer_actor IS NOT OLD.answer_actor
   OR NEW.continuation_state IS NOT OLD.continuation_state
   OR NEW.successor_turn_id IS NOT OLD.successor_turn_id
   OR NEW.continuation_error IS NOT OLD.continuation_error)
BEGIN SELECT RAISE(ABORT, 'open thread question is immutable'); END;
CREATE TRIGGER thread_question_terminal_immutable
BEFORE UPDATE ON thread_question
WHEN OLD.state <> 'OPEN'
  AND (NEW.state IS NOT OLD.state OR NEW.answer IS NOT OLD.answer
    OR NEW.answer_revision IS NOT OLD.answer_revision
    OR NEW.answered_at_ms IS NOT OLD.answered_at_ms
    OR NEW.answer_option_id IS NOT OLD.answer_option_id
    OR NEW.answer_free_form IS NOT OLD.answer_free_form
    OR NEW.answer_actor IS NOT OLD.answer_actor)
BEGIN SELECT RAISE(ABORT, 'terminal thread question is immutable'); END;
CREATE TRIGGER thread_settings_capacity_insert_v275
BEFORE INSERT ON thread_settings
WHEN NEW.max_running_tasks IS NOT NULL
 AND NEW.max_running_tasks < 1
BEGIN SELECT RAISE(ABORT,
    'thread_settings.max_running_tasks must be positive'); END;
CREATE TRIGGER thread_settings_capacity_update_v275
BEFORE UPDATE OF max_running_tasks ON thread_settings
WHEN NEW.max_running_tasks IS NOT NULL
 AND NEW.max_running_tasks < 1
BEGIN SELECT RAISE(ABORT,
    'thread_settings.max_running_tasks must be positive'); END;
CREATE TRIGGER thread_turn_global_identity_insert
BEFORE INSERT ON thread_turn
WHEN EXISTS (SELECT 1 FROM task_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM stage_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
  OR EXISTS (SELECT 1 FROM review_assignment_turn WHERE id = NEW.id OR operation_id = NEW.operation_id)
BEGIN SELECT RAISE(ABORT, 'typed Turn id and operation id must be globally exact'); END;
CREATE TRIGGER thread_turn_identity_immutable
BEFORE UPDATE OF trunk_id, purpose, operation_id, attempt, delivery_lane,
        launch_input, planning_operation_id, expected_base_sha ON thread_turn
WHEN NEW.trunk_id IS NOT OLD.trunk_id
  OR NEW.purpose IS NOT OLD.purpose
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.attempt IS NOT OLD.attempt
  OR NEW.delivery_lane IS NOT OLD.delivery_lane
  OR NEW.launch_input IS NOT OLD.launch_input
  OR NEW.planning_operation_id IS NOT OLD.planning_operation_id
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
BEGIN SELECT RAISE(ABORT, 'thread Turn launch identity is immutable'); END;
CREATE TRIGGER thread_turn_owner_insert
BEFORE INSERT ON thread_turn
WHEN NOT EXISTS (
    SELECT 1 FROM threads t
    WHERE t.id = NEW.trunk_id AND t.turn_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'thread Turn requires a V2 Trunk'); END;
CREATE TRIGGER thread_turn_planning_fence_insert
BEFORE INSERT ON thread_turn
WHEN (NEW.purpose = 'TRUNK_CONVERSATION')
     <> (NEW.planning_operation_id IS NOT NULL AND NEW.expected_base_sha IS NOT NULL)
  OR (NEW.planning_operation_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM planning_base_refresh_operation planning
      JOIN dispatch_ticket ticket ON ticket.id = planning.dispatch_ticket_id
      WHERE planning.id = NEW.planning_operation_id
        AND planning.trunk_id = NEW.trunk_id
        AND planning.reserved_thread_turn_id = NEW.id
        AND planning.status = 'SUCCEEDED'
        AND planning.result_base_sha = NEW.expected_base_sha
        AND planning.result_worktree_path = json_extract(
            NEW.launch_input, '$.workingDirectory')
        AND ticket.status = 'SUCCEEDED'
        AND ticket.delivery_acceptance = 'ACCEPTED'))
BEGIN SELECT RAISE(ABORT, 'ThreadTurn lacks its exact planning snapshot'); END;
CREATE TRIGGER trunk_command_receipt_immutable
BEFORE UPDATE ON trunk_command_receipt
BEGIN SELECT RAISE(ABORT, 'Trunk command receipt is immutable'); END;
CREATE TRIGGER trunk_command_receipt_insert
BEFORE INSERT ON trunk_command_receipt
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM threads trunk
            WHERE trunk.id = NEW.trunk_id AND trunk.turn_version = 'V2')
            THEN RAISE(ABORT, 'Trunk command receipt requires a V2 Trunk')
        WHEN NOT EXISTS (
            SELECT 1 FROM trunk_transition transition
            WHERE transition.trunk_id = NEW.trunk_id
              AND transition.command_id = NEW.command_id
              AND transition.to_state = NEW.returned_lifecycle
              AND transition.aggregate_version = NEW.returned_version
              AND transition.cause = NEW.cause AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'applied Trunk receipt lacks its exact transition')
    END;
END;
CREATE TRIGGER trunk_outcome_inbox_delete_immutable
BEFORE DELETE ON trunk_outcome_inbox
WHEN NOT EXISTS (
    SELECT 1 FROM v2_trunk_purge_authorization_v269 authorization
    WHERE authorization.trunk_id = OLD.trunk_id)
BEGIN SELECT RAISE(ABORT, 'Trunk outcome inbox evidence cannot be deleted'); END;
CREATE TRIGGER trunk_outcome_inbox_insert
BEFORE INSERT ON trunk_outcome_inbox
WHEN NEW.id <> 'TRUNK_OUTCOME:' || NEW.task_outcome_id
  OR NEW.delivery_key <> NEW.id
  OR NEW.status <> 'PENDING'
  OR NEW.delivered_at_ms IS NOT NULL OR NEW.delivery_evidence IS NOT NULL
  OR NEW.returned_trunk_version IS NOT NULL
  OR NEW.legacy_delivery_evidence IS NOT NULL
  OR NEW.legacy_delivered_at_ms IS NOT NULL
  OR NEW.fallback_summary_text IS NULL
  OR NOT EXISTS (
      SELECT 1
      FROM task_outcome outcome
      JOIN tasks task ON task.id = outcome.task_id
      LEFT JOIN remote_pr_binding binding
        ON binding.id = outcome.remote_pr_binding_id
      WHERE outcome.id = NEW.task_outcome_id
        AND outcome.task_id = NEW.task_id
        AND outcome.trunk_id = NEW.trunk_id
        AND NEW.fallback_summary_marker =
            'FALLBACK:' || outcome.cleanup_summary_digest
        AND NEW.fallback_summary_text = CASE outcome.terminal_reason
          WHEN 'CANCELED' THEN CASE
            WHEN binding.remote_pr_number IS NULL
              THEN 'Canceled ' || COALESCE(
                NULLIF(trim(task.name), ''),
                NULLIF(trim(task.branch_name), ''),
                'Task ' || task.seq)
                || ' before opening a pull request.'
            ELSE 'Canceled ' || COALESCE(
                NULLIF(trim(task.name), ''),
                NULLIF(trim(task.branch_name), ''),
                'Task ' || task.seq)
                || ' (PR #' || binding.remote_pr_number
                || ' remains open).'
            END
          WHEN 'REMOTE_CLOSED' THEN
            'Shipped ' || COALESCE(
              NULLIF(trim(task.name), ''),
              NULLIF(trim(task.branch_name), ''),
              'Task ' || task.seq)
              || CASE WHEN binding.remote_pr_number IS NULL
                THEN ' — closed without merging.'
                ELSE ' (PR #' || binding.remote_pr_number
                  || ') — closed without merging.' END
          ELSE 'Shipped ' || COALESCE(
              NULLIF(trim(task.name), ''),
              NULLIF(trim(task.branch_name), ''),
              'Task ' || task.seq)
              || CASE WHEN binding.remote_pr_number IS NULL
                THEN ' — completed with no pull request opened.'
                ELSE ' (PR #' || binding.remote_pr_number
                  || ') — merged.' END
          END)
BEGIN SELECT RAISE(ABORT, 'Trunk outcome inbox marker is not exact'); END;
CREATE TRIGGER trunk_outcome_inbox_transition
BEFORE UPDATE ON trunk_outcome_inbox
WHEN NOT (OLD.status = 'PENDING' AND NEW.status = 'DELIVERED'
      AND NEW.id = OLD.id AND NEW.trunk_id = OLD.trunk_id
      AND NEW.task_id = OLD.task_id
      AND NEW.task_outcome_id = OLD.task_outcome_id
      AND NEW.delivery_key = OLD.delivery_key
      AND NEW.fallback_summary_marker = OLD.fallback_summary_marker
      AND NEW.fallback_summary_text = OLD.fallback_summary_text
      AND NEW.legacy_delivery_evidence IS OLD.legacy_delivery_evidence
      AND NEW.legacy_delivered_at_ms IS OLD.legacy_delivered_at_ms
      AND NEW.created_at_ms = OLD.created_at_ms
      AND NEW.delivered_at_ms >= OLD.created_at_ms
      AND NEW.delivery_evidence IS NOT NULL
      AND NEW.returned_trunk_version > 0
      AND EXISTS (
          SELECT 1
          FROM task_outcome outcome
          JOIN tasks task ON task.id = outcome.task_id
          JOIN threads trunk ON trunk.id = outcome.trunk_id
          JOIN trunk_transition transition
            ON transition.trunk_id = outcome.trunk_id
          WHERE outcome.id = OLD.task_outcome_id
            AND outcome.task_id = OLD.task_id
            AND outcome.trunk_id = OLD.trunk_id
            AND task.lifecycle_state IN (
              'COMPLETED', 'CANCELED', 'REMOTE_CLOSED')
            AND transition.command_id = OLD.delivery_key
            AND transition.cause = 'ACCEPT_TASK_OUTCOME'
            AND transition.from_state = transition.to_state
            AND transition.to_state = trunk.lifecycle_state
            AND transition.aggregate_version = NEW.returned_trunk_version
            AND trunk.aggregate_version = NEW.returned_trunk_version))
BEGIN SELECT RAISE(ABORT, 'Trunk outcome inbox transition is invalid'); END;
CREATE TRIGGER trunk_planning_base_request_exact
BEFORE INSERT ON trunk_planning_base_request_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM planning_base_refresh_operation operation
        JOIN dispatch_ticket ticket ON ticket.id = operation.dispatch_ticket_id
        JOIN outbox wake ON wake.aggregate_id = ticket.id
        JOIN trunk_transition transition
          ON transition.trunk_id = operation.trunk_id
         AND transition.command_id = operation.command_id
        WHERE operation.id = NEW.planning_operation_id
          AND operation.trunk_id = NEW.trunk_id
          AND operation.command_id = NEW.command_id
          AND operation.status = 'REQUESTED'
          AND ticket.operation_id = operation.operation_id
          AND ticket.operation_kind = 'REFRESH_PLANNING_BASE'
          AND ticket.async_family = 'LOCAL_GIT'
          AND ticket.owner_kind = 'TRUNK'
          AND ticket.owner_id = operation.trunk_id
          AND ticket.callback_route = 'PLANNING_BASE_REFRESH_RESULT'
          AND ticket.lane_mask = 16
          AND ticket.trunk_control = 1
          AND ticket.exclusive_task = 0
          AND ticket.writer_required = 0
          AND ticket.workspace_id = operation.workspace_id
          AND ticket.trunk_id = operation.trunk_id
          AND ticket.task_id IS NULL AND ticket.stage_id IS NULL
          AND ticket.expected_base_sha IS operation.previous_base_sha
          AND ticket.status = 'REQUESTED'
          AND wake.id = 'V2_DISPATCH_TICKET_REQUESTED:' || ticket.id
          AND wake.status = 'PENDING'
          AND transition.aggregate_version = NEW.returned_trunk_version
          AND transition.cause = 'REQUEST_PLANNING_BASE_REFRESH')
    THEN RAISE(ABORT, 'Planning-base request receipt is not exact') END;
END;
CREATE TRIGGER trunk_planning_base_request_receipt_immutable
BEFORE UPDATE ON trunk_planning_base_request_receipt
BEGIN SELECT RAISE(ABORT, 'Planning-base request receipt is immutable'); END;
CREATE TRIGGER trunk_planning_base_result_exact
BEFORE INSERT ON trunk_planning_base_result_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM planning_base_refresh_operation operation
        JOIN dispatch_ticket ticket ON ticket.id = operation.dispatch_ticket_id
        JOIN trunk_transition transition
          ON transition.trunk_id = operation.trunk_id
         AND transition.command_id = NEW.command_id
        WHERE operation.id = NEW.planning_operation_id
          AND operation.trunk_id = NEW.trunk_id
          AND operation.operation_id = NEW.operation_id
          AND operation.raw_outcome = NEW.raw_outcome
          AND operation.raw_result_digest = NEW.raw_result_digest
          AND operation.status <> 'REQUESTED'
          AND ticket.status = 'RESULT_PENDING'
          AND ticket.pending_result_outcome = NEW.raw_outcome
          AND ticket.pending_result_operation_id = operation.operation_id
          AND ticket.pending_result_attempt = operation.semantic_attempt
          AND ticket.pending_result_expected_base_sha IS operation.previous_base_sha
          AND transition.aggregate_version = NEW.returned_trunk_version
          AND transition.cause = 'ACCEPT_PLANNING_BASE_REFRESH')
    THEN RAISE(ABORT, 'Planning-base result receipt is not exact') END;
END;
CREATE TRIGGER trunk_planning_base_result_receipt_immutable
BEFORE UPDATE ON trunk_planning_base_result_receipt
BEGIN SELECT RAISE(ABORT, 'Planning-base result receipt is immutable'); END;
CREATE TRIGGER trunk_task_creation_authorization_immutable
BEFORE UPDATE ON trunk_task_creation_authorization
BEGIN SELECT RAISE(ABORT, 'Task creation authorization is immutable'); END;
CREATE TRIGGER trunk_task_creation_authorization_insert
BEFORE INSERT ON trunk_task_creation_authorization
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM threads trunk
            JOIN task_assignment assignment ON assignment.trunk_id = trunk.id
            JOIN task_policy_revision policy ON policy.trunk_id = trunk.id
            JOIN workspace_repos local_repo
              ON local_repo.workspace_id = trunk.workspace_id
            WHERE trunk.id = NEW.trunk_id
              AND trunk.workspace_id = NEW.workspace_id
              AND trunk.turn_version = 'V2'
              AND trunk.lifecycle_state = NEW.returned_lifecycle
              AND trunk.aggregate_version = NEW.returned_trunk_version
              AND assignment.id = NEW.assignment_id
              AND assignment.creation_authorization_id = NEW.id
              AND policy.id = NEW.policy_revision_id
              AND lower(local_repo.repo_full_name) = lower(NEW.repository_id)
              AND NEW.publish_repository_id = NEW.repository_id
              AND NOT EXISTS (
                  SELECT 1 FROM task_policy_revision newer
                  WHERE newer.trunk_id = policy.trunk_id
                    AND newer.revision > policy.revision))
            THEN RAISE(ABORT, 'Task creation authorization owner graph is not exact')
        WHEN NOT EXISTS (
            SELECT 1 FROM trunk_transition transition
            WHERE transition.trunk_id = NEW.trunk_id
              AND transition.command_id = NEW.command_id
              AND transition.from_state = NEW.returned_lifecycle
              AND transition.to_state = NEW.returned_lifecycle
              AND transition.aggregate_version = NEW.returned_trunk_version
              AND transition.cause = 'AUTHORIZE_TASK_CREATION'
              AND transition.actor = NEW.actor)
            THEN RAISE(ABORT, 'Task creation authorization lacks exact Trunk CAS audit')
        WHEN NEW.upstream_repository_id IS NULL AND NOT (
            NEW.base_repository_id = NEW.repository_id
            AND NOT EXISTS (
                SELECT 1 FROM workspace_relation relation
                WHERE relation.workspace_id = NEW.workspace_id))
            THEN RAISE(ABORT, 'direct Task authorization conflicts with Workspace provenance')
        WHEN NEW.upstream_repository_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM workspace_relation relation
            JOIN workspace_repos upstream
              ON upstream.workspace_id = relation.upstream_workspace_id
            WHERE relation.workspace_id = NEW.workspace_id
              AND lower(upstream.repo_full_name) = lower(NEW.upstream_repository_id)
              AND lower(upstream.repo_full_name) = lower(NEW.base_repository_id))
            THEN RAISE(ABORT, 'fork Task authorization lacks exact upstream Workspace')
        WHEN NEW.base_source <> 'EXISTING_PR_HEAD' AND NOT EXISTS (
            SELECT 1 FROM workspace_repos base_repo
            WHERE lower(base_repo.repo_full_name) = lower(NEW.base_repository_id)
              AND base_repo.default_base_branch = NEW.base_ref
              AND base_repo.workspace_id = CASE
                  WHEN NEW.upstream_repository_id IS NULL THEN NEW.workspace_id
                  ELSE (SELECT relation.upstream_workspace_id
                        FROM workspace_relation relation
                        WHERE relation.workspace_id = NEW.workspace_id)
              END)
            THEN RAISE(ABORT, 'fresh/planning Task authorization lacks exact base ref')
        WHEN NOT (
            EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'NEW_FROM_TRUNK'
                  AND NEW.provenance = 'AGENT_HANDOFF'
                  AND NEW.base_source = 'PLANNING_SNAPSHOT'
                  AND assignment.planning_base_sha IS NEW.planning_base_sha)
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'NEW_FROM_TRUNK'
                  AND NEW.provenance = 'DIRECT_USER'
                  AND NEW.base_source = 'FRESH_REMOTE_BASE'
                  AND assignment.planning_base_sha IS NULL)
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'REVIEW_FINDINGS'
                  AND NEW.provenance = 'REVIEW_SESSION'
                  AND NEW.base_source = 'EXISTING_PR_HEAD'
                  AND assignment.repository_id = NEW.repository_id
                  AND assignment.head_repository_id = NEW.publish_repository_id
                  AND assignment.base_repository_id = NEW.base_repository_id
                  AND assignment.base_ref IS NEW.base_ref
                  AND assignment.remote_base_sha IS NEW.assignment_base_sha
                  AND assignment.remote_head_sha IS NEW.assignment_head_sha
                  AND ((assignment.repository_route = 'DIRECT'
                        AND NEW.upstream_repository_id IS NULL)
                    OR (assignment.repository_route = 'FORK'
                        AND assignment.base_repository_id = NEW.upstream_repository_id))
                  AND EXISTS (
                      SELECT 1 FROM task_assignment_review_finding finding
                      WHERE finding.assignment_id = assignment.id))
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'ISSUE'
                  AND NEW.provenance = 'ISSUE_MONITOR'
                  AND NEW.base_source = 'FRESH_REMOTE_BASE')
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'AUTOMATION'
                  AND NEW.provenance = 'AUTOMATION'
                  AND NEW.base_source = 'FRESH_REMOTE_BASE')
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'QUALITY_SCAN'
                  AND NEW.provenance = 'QUALITY_SCAN'
                  AND NEW.base_source = 'FRESH_REMOTE_BASE')
            OR EXISTS (
                SELECT 1 FROM task_assignment assignment
                WHERE assignment.id = NEW.assignment_id
                  AND assignment.kind = 'EXISTING_OWN_PR'
                  AND NEW.provenance = 'DIRECT_USER'
                  AND NEW.base_source = 'EXISTING_PR_HEAD'
                  AND assignment.repository_id = NEW.repository_id
                  AND assignment.head_repository_id = NEW.publish_repository_id
                  AND assignment.base_repository_id = NEW.base_repository_id
                  AND assignment.base_ref IS NEW.base_ref
                  AND assignment.remote_base_sha IS NEW.assignment_base_sha
                  AND assignment.remote_head_sha IS NEW.assignment_head_sha
                  AND ((assignment.repository_route = 'DIRECT'
                        AND NEW.upstream_repository_id IS NULL)
                    OR (assignment.repository_route = 'FORK'
                        AND assignment.base_repository_id = NEW.upstream_repository_id))))
            THEN RAISE(ABORT, 'Task creation authorization source is not exact')
    END;
END;
CREATE TRIGGER trunk_thread_turn_request_receipt_exact
BEFORE INSERT ON trunk_thread_turn_request_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM thread_turn turn
        JOIN thread_message message
          ON message.turn_id = turn.id AND message.seq = 1
        JOIN dispatch_ticket ticket
          ON ticket.id = NEW.dispatch_ticket_id
        WHERE turn.id = NEW.turn_id
          AND turn.trunk_id = NEW.trunk_id
          AND turn.operation_id = NEW.operation_id
          AND turn.purpose = NEW.purpose
          AND turn.delivery_lane = NEW.delivery_lane
          AND message.role = 'user'
          AND ticket.operation_id = NEW.operation_id
          AND ticket.operation_kind = 'EXECUTE_THREAD_TURN'
          AND ticket.async_family = 'AGENT_TURN'
          AND ticket.owner_kind = 'THREAD_TURN'
          AND ticket.owner_id = NEW.turn_id
          AND ticket.callback_route = 'THREAD_TURN_RESULT'
          AND ticket.trunk_control = 1
          AND ticket.exclusive_task = 0
          AND ticket.writer_required = 0
          AND ticket.workspace_id IS NOT NULL
          AND ticket.trunk_id = NEW.trunk_id
          AND ticket.task_id IS NULL
          AND ticket.stage_id IS NULL)
    THEN RAISE(ABORT, 'ThreadTurn request receipt is not exact') END;
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM trunk_transition transition
        WHERE transition.trunk_id = NEW.trunk_id
          AND transition.command_id = NEW.command_id
          AND transition.aggregate_version = NEW.returned_trunk_version
          AND transition.to_state = NEW.returned_lifecycle
          AND transition.cause = 'REQUEST_THREAD_TURN')
    THEN RAISE(ABORT, 'ThreadTurn request lacks its Trunk transition') END;
END;
CREATE TRIGGER trunk_thread_turn_request_receipt_immutable
BEFORE UPDATE ON trunk_thread_turn_request_receipt
BEGIN SELECT RAISE(ABORT, 'ThreadTurn request receipt is immutable'); END;
CREATE TRIGGER trunk_thread_turn_result_receipt_exact
BEFORE INSERT ON trunk_thread_turn_result_receipt
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM thread_turn turn
        WHERE turn.id = NEW.turn_id
          AND turn.trunk_id = NEW.trunk_id
          AND turn.operation_id = NEW.operation_id
          AND turn.attempt = NEW.attempt
          AND turn.status = NEW.terminal_status
          AND turn.finished_at_ms IS NOT NULL)
    THEN RAISE(ABORT, 'ThreadTurn result receipt is not exact') END;
    SELECT CASE WHEN NEW.assistant_message_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM thread_message message
        WHERE message.id = NEW.assistant_message_id
          AND message.turn_id = NEW.turn_id
          AND message.seq = 2
          AND message.role = 'assistant')
    THEN RAISE(ABORT, 'ThreadTurn result message is not exact') END;
    SELECT CASE WHEN NEW.terminal_status <> 'SUCCEEDED'
        AND EXISTS (
            SELECT 1 FROM thread_message message
            WHERE message.turn_id = NEW.turn_id AND message.seq = 2)
    THEN RAISE(ABORT, 'ThreadTurn result message shape is invalid') END;
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM trunk_transition transition
        WHERE transition.trunk_id = NEW.trunk_id
          AND transition.command_id = NEW.command_id
          AND transition.aggregate_version = NEW.returned_trunk_version
          AND transition.to_state = NEW.returned_lifecycle
          AND transition.cause = 'ACCEPT_THREAD_TURN_RESULT')
    THEN RAISE(ABORT, 'ThreadTurn result lacks its Trunk transition') END;
END;
CREATE TRIGGER trunk_thread_turn_result_receipt_immutable
BEFORE UPDATE ON trunk_thread_turn_result_receipt
BEGIN SELECT RAISE(ABORT, 'ThreadTurn result receipt is immutable'); END;
CREATE TRIGGER trunk_transition_immutable
BEFORE UPDATE ON trunk_transition
BEGIN SELECT RAISE(ABORT, 'trunk transition is immutable'); END;
CREATE TRIGGER trunk_turn_version_quiescent
BEFORE UPDATE OF turn_version ON threads
WHEN NEW.turn_version IS NOT OLD.turn_version
  AND (
      EXISTS (
          SELECT 1 FROM thread_turns legacy
          WHERE legacy.thread_id = OLD.id
            AND legacy.task_id IS NULL
            AND (legacy.scope = 'TRUNK' OR legacy.scope IS NULL)
            AND legacy.status IN ('QUEUED', 'RUNNING'))
      OR EXISTS (
          SELECT 1 FROM thread_turn typed
          WHERE typed.trunk_id = OLD.id
            AND typed.status IN ('REQUESTED', 'QUEUED', 'CLAIMED', 'RUNNING')))
BEGIN
    SELECT RAISE(ABORT, 'Trunk Turn version can change only while quiescent');
END;
CREATE TRIGGER typed_user_wait_result_immutable
BEFORE UPDATE ON typed_user_wait_result
BEGIN SELECT RAISE(ABORT, 'user-wait result evidence is immutable'); END;
CREATE TRIGGER typed_user_wait_result_owner_insert
BEFORE INSERT ON typed_user_wait_result
BEGIN
    SELECT CASE WHEN
        (NEW.owner_kind = 'THREAD_TURN' AND NOT EXISTS (
            SELECT 1 FROM thread_turn turn
            WHERE turn.id = NEW.turn_id AND turn.operation_id = NEW.operation_id))
        OR (NEW.owner_kind = 'TASK_TURN' AND NOT EXISTS (
            SELECT 1 FROM task_turn turn
            WHERE turn.id = NEW.turn_id AND turn.operation_id = NEW.operation_id))
        OR (NEW.owner_kind = 'STAGE_TURN' AND NOT EXISTS (
            SELECT 1 FROM stage_turn turn
            WHERE turn.id = NEW.turn_id AND turn.operation_id = NEW.operation_id))
        OR (NEW.owner_kind = 'REVIEW_ASSIGNMENT_TURN' AND NOT EXISTS (
            SELECT 1 FROM review_assignment_turn turn
            WHERE turn.id = NEW.turn_id AND turn.operation_id = NEW.operation_id))
    THEN RAISE(ABORT, 'user-wait result owner is not exact') END;

    SELECT CASE WHEN NEW.wait_kind = 'QUESTION' AND NOT (
        (NEW.owner_kind = 'THREAD_TURN' AND EXISTS (
            SELECT 1 FROM thread_question question
            WHERE question.id = NEW.wait_id AND question.turn_id = NEW.turn_id))
        OR (NEW.owner_kind = 'TASK_TURN' AND EXISTS (
            SELECT 1 FROM task_question question
            WHERE question.id = NEW.wait_id AND question.turn_id = NEW.turn_id))
        OR (NEW.owner_kind = 'STAGE_TURN' AND EXISTS (
            SELECT 1 FROM stage_question question
            WHERE question.id = NEW.wait_id AND question.turn_id = NEW.turn_id))
        OR (NEW.owner_kind = 'REVIEW_ASSIGNMENT_TURN' AND EXISTS (
            SELECT 1 FROM review_assignment_question question
            WHERE question.id = NEW.wait_id AND question.turn_id = NEW.turn_id)))
    THEN RAISE(ABORT, 'question wait does not belong to typed Turn') END;

    SELECT CASE WHEN NEW.wait_kind = 'PERMISSION' AND NOT EXISTS (
        SELECT 1 FROM permission_request permission
        WHERE permission.id = NEW.wait_id
          AND permission.turn_id = NEW.turn_id
          AND permission.operation_id = NEW.operation_id
          AND CASE permission.turn_kind
              WHEN 'THREAD' THEN 'THREAD_TURN'
              WHEN 'TASK' THEN 'TASK_TURN'
              WHEN 'STAGE' THEN 'STAGE_TURN'
              WHEN 'REVIEW_ASSIGNMENT' THEN 'REVIEW_ASSIGNMENT_TURN'
              END = NEW.owner_kind)
    THEN RAISE(ABORT, 'permission wait does not belong to typed Turn') END;
END;
CREATE TRIGGER v2_quality_issue_publish_delete_v285
BEFORE DELETE ON v2_quality_issue_publish_v285
WHEN NOT EXISTS (
    SELECT 1 FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT,
    'quality issue publish evidence cannot be deleted'); END;
CREATE TRIGGER v2_quality_issue_publish_delivery_immutable_v285
BEFORE UPDATE OF result_json, last_error, delivered_at_ms
ON v2_quality_issue_publish_v285
WHEN OLD.delivered_at_ms IS NOT NULL
  AND (NEW.result_json IS NOT OLD.result_json
    OR NEW.last_error IS NOT OLD.last_error
    OR NEW.delivered_at_ms IS NOT OLD.delivered_at_ms)
BEGIN SELECT RAISE(ABORT,
    'quality issue delivery is immutable'); END;
CREATE TRIGGER v2_quality_issue_publish_dispatch_delete_v285
BEFORE DELETE ON v2_quality_issue_publish_dispatch_v285
WHEN NOT EXISTS (
    SELECT 1 FROM v2_quality_issue_publish_v285 publish
    JOIN tasks task ON task.id = publish.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE publish.id = OLD.publish_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT,
    'quality issue publish dispatch cannot be deleted'); END;
CREATE TRIGGER v2_quality_issue_publish_dispatch_insert_v285
BEFORE INSERT ON v2_quality_issue_publish_dispatch_v285
WHEN NOT EXISTS (
    SELECT 1
    FROM v2_quality_issue_publish_v285 publish
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    WHERE publish.id = NEW.publish_id
      AND publish.operation_id = NEW.operation_id
      AND ticket.operation_id = publish.operation_id
      AND ticket.operation_kind = 'PUBLISH_V2_QUALITY_ISSUE'
      AND ticket.callback_route = 'V2_QUALITY_ISSUE_RESULT'
      AND ticket.owner_kind = 'TASK'
      AND ticket.owner_id = publish.task_id
      AND ticket.task_id = publish.task_id
      AND ticket.task_epoch = publish.task_epoch
      AND ticket.stage_id IS NULL
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT,
    'quality issue publish dispatch is invalid'); END;
CREATE TRIGGER v2_quality_issue_publish_dispatch_update_v285
BEFORE UPDATE ON v2_quality_issue_publish_dispatch_v285
BEGIN SELECT RAISE(ABORT,
    'quality issue publish dispatch is immutable'); END;
CREATE TRIGGER v2_quality_issue_publish_identity_v285
BEFORE UPDATE OF id, operation_id, notification_id, task_id, task_epoch,
        workspace_id, trunk_id, repo_owner, repo_name, issue_title,
        issue_body, idempotency_marker, payload_digest, authorized_at_ms
ON v2_quality_issue_publish_v285
BEGIN SELECT RAISE(ABORT,
    'quality issue publish identity is immutable'); END;
CREATE TRIGGER v2_quality_issue_publish_insert_v285
BEFORE INSERT ON v2_quality_issue_publish_v285
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM notifications notification
            JOIN tasks task ON task.id = notification.task_id
            JOIN threads trunk ON trunk.id = task.thread_id
            WHERE notification.id = NEW.notification_id
              AND notification.kind = 'AWAITING_REVIEW'
              AND notification.status = 'RESOLVING'
              AND notification.thread_id = task.thread_id
              AND task.id = NEW.task_id
              AND task.workflow_version = 'V2'
              AND task.epoch = NEW.task_epoch
              AND task.lifecycle_state IN ('CANCELING', 'CLEANING', 'CANCELED')
              AND task.thread_id = NEW.trunk_id
              AND trunk.workspace_id = NEW.workspace_id
              AND json_valid(notification.payload_json)
              AND json_extract(notification.payload_json, '$.action') = 'create_issue'
              AND json_extract(notification.payload_json, '$.source')
                    = 'automation:quality-scan'
              AND json_extract(notification.payload_json, '$.repo.owner')
                    = NEW.repo_owner
              AND json_extract(notification.payload_json, '$.repo.repo')
                    = NEW.repo_name
              AND json_extract(notification.payload_json, '$.title')
                    = NEW.issue_title)
            THEN RAISE(ABORT,
                'quality issue publish lacks its exact canceled V2 Task proposal')
        WHEN NEW.status <> 'REQUESTED'
          OR NEW.idempotency_marker NOT LIKE
                '<!-- bytequay-quality-issue-operation:v1 id=% -->'
          OR instr(NEW.issue_body, NEW.idempotency_marker) = 0
          OR instr(NEW.issue_body, '<!-- bytequay-quality-scan:v1 -->') = 0
            THEN RAISE(ABORT,
                'quality issue publish lacks immutable idempotency evidence')
    END;
END;
CREATE TRIGGER v2_quality_issue_publish_transition_v285
BEFORE UPDATE OF status ON v2_quality_issue_publish_v285
WHEN NEW.status IS NOT OLD.status
  AND NOT (
      (OLD.status = 'REQUESTED'
        AND NEW.status IN ('EXECUTING', 'SUCCEEDED', 'FAILED', 'CANCELED'))
      OR (OLD.status = 'EXECUTING'
        AND NEW.status IN ('SUCCEEDED', 'INDETERMINATE', 'FAILED', 'CANCELED'))
      OR (OLD.status = 'INDETERMINATE'
        AND NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED'))
      OR (OLD.status = 'SUCCEEDED' AND NEW.status = 'DELIVERED'))
BEGIN SELECT RAISE(ABORT,
    'quality issue publish transition is invalid'); END;
CREATE TRIGGER v2_review_assignment_turn_ticket_shape_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.owner_kind = 'REVIEW_ASSIGNMENT_TURN'
BEGIN
    SELECT CASE
        WHEN NEW.operation_kind <> 'EXECUTE_REVIEW_ASSIGNMENT_TURN'
          OR NEW.async_family <> 'AGENT_TURN'
          OR NEW.callback_route <> 'REVIEW_ASSIGNMENT_TURN_RESULT'
          OR NEW.lane_mask NOT IN (9, 10)
          OR NEW.trunk_control <> 0
          OR NEW.exclusive_task <> 0
          OR NEW.writer_required <> 0
          OR NEW.stage_id IS NOT NULL
          OR NEW.stage_generation IS NOT NULL
          OR NEW.expected_code_fingerprint IS NOT NULL
          OR NEW.expected_base_sha IS NOT NULL
          OR NOT EXISTS (
              SELECT 1
              FROM review_assignment_turn turn
              WHERE turn.id = NEW.owner_id
                AND turn.operation_id = NEW.operation_id
                AND turn.attempt = NEW.attempt
                AND turn.start_commit = NEW.expected_head_sha
                AND ((turn.delivery_lane = 'CLI' AND NEW.lane_mask = 9)
                  OR (turn.delivery_lane = 'API' AND NEW.lane_mask = 10))
                AND json_valid(turn.launch_input)
                AND json_extract(turn.launch_input, '$.schemaVersion') = 1
                AND json_extract(turn.launch_input, '$.toolEndpoint.ownerKind')
                    = 'REVIEW_ASSIGNMENT_TURN'
                AND json_extract(turn.launch_input, '$.toolEndpoint.ownerId') = turn.id
                AND json_extract(turn.launch_input, '$.toolEndpoint.operationId')
                    = turn.operation_id
                AND json_extract(turn.launch_input, '$.toolEndpoint.profile')
                    = 'REVIEW_ASSIGNMENT_READ_ONLY')
        THEN RAISE(ABORT, 'review Turn requires exact read-only REVIEW capacity')
    END;
END;
CREATE TRIGGER v2_review_assignment_turn_ticket_shape_update
BEFORE UPDATE OF operation_kind, async_family, owner_kind, callback_route,
        lane_mask, trunk_control, exclusive_task, writer_required,
        workspace_id, trunk_id, task_id, task_epoch, stage_id,
        stage_generation, expected_code_fingerprint, expected_head_sha,
        expected_base_sha ON dispatch_ticket
WHEN NEW.owner_kind = 'REVIEW_ASSIGNMENT_TURN'
BEGIN
    SELECT CASE
        WHEN NEW.operation_kind <> 'EXECUTE_REVIEW_ASSIGNMENT_TURN'
          OR NEW.async_family <> 'AGENT_TURN'
          OR NEW.callback_route <> 'REVIEW_ASSIGNMENT_TURN_RESULT'
          OR NEW.lane_mask NOT IN (9, 10)
          OR NEW.trunk_control <> 0
          OR NEW.exclusive_task <> 0
          OR NEW.writer_required <> 0
          OR NEW.stage_id IS NOT NULL
          OR NEW.stage_generation IS NOT NULL
          OR NEW.expected_code_fingerprint IS NOT NULL
          OR NEW.expected_base_sha IS NOT NULL
          OR NOT EXISTS (
              SELECT 1
              FROM review_assignment_turn turn
              WHERE turn.id = NEW.owner_id
                AND turn.operation_id = NEW.operation_id
                AND turn.attempt = NEW.attempt
                AND turn.start_commit = NEW.expected_head_sha
                AND ((turn.delivery_lane = 'CLI' AND NEW.lane_mask = 9)
                  OR (turn.delivery_lane = 'API' AND NEW.lane_mask = 10)))
        THEN RAISE(ABORT, 'review Turn requires exact read-only REVIEW capacity')
    END;
END;
CREATE TRIGGER v2_stage_completed_immutable
BEFORE UPDATE ON stage
WHEN OLD.completed_at_ms IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'completed stage is immutable');
END;
CREATE TRIGGER v2_stage_identity_immutable
BEFORE UPDATE OF task_id, kind, generation, opened_at_ms ON stage
WHEN NEW.task_id IS NOT OLD.task_id
  OR NEW.kind IS NOT OLD.kind
  OR NEW.generation IS NOT OLD.generation
  OR NEW.opened_at_ms IS NOT OLD.opened_at_ms
BEGIN
    SELECT RAISE(ABORT, 'stage identity is immutable');
END;
CREATE TRIGGER v2_stage_task_route_insert
BEFORE INSERT ON stage
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = 'V2')
    THEN RAISE(ABORT, 'V2 stage requires a V2 task') END;
    SELECT CASE WHEN NEW.generation <> COALESCE((
        SELECT MAX(s.generation) + 1
        FROM stage s
        WHERE s.task_id = NEW.task_id AND s.kind = NEW.kind), 1)
    THEN RAISE(ABORT, 'Stage generation must be the next exact generation') END;
END;
CREATE TRIGGER v2_stage_version_monotonic
BEFORE UPDATE ON stage
WHEN NEW.version <> OLD.version + 1
BEGIN
    SELECT RAISE(ABORT, 'Stage version must advance once');
END;
CREATE TRIGGER v2_task_creation_authority_insert
BEFORE INSERT ON tasks
WHEN NEW.workflow_version = 'V2'
  AND (NEW.creation_receipt_id IS NULL
    OR NEW.epoch <> 1 OR NEW.aggregate_version <> 0
    OR NEW.lifecycle_state <> 'PROVISIONING'
    OR NEW.branch_name IS NOT NULL OR NEW.worktree_path IS NOT NULL
    OR NEW.seq <> COALESCE((
        SELECT MAX(sibling.seq) + 1 FROM tasks sibling
        WHERE sibling.thread_id = NEW.thread_id), 1)
    OR NOT EXISTS (
        SELECT 1
        FROM threads trunk
        JOIN task_assignment assignment ON assignment.trunk_id = trunk.id
        JOIN trunk_task_creation_authorization authorization
          ON authorization.id = assignment.creation_authorization_id
        WHERE trunk.id = NEW.thread_id
          AND trunk.turn_version = 'V2'
          AND trunk.lifecycle_state IN ('ACTIVE', 'IDLE')
          AND assignment.id = NEW.assignment_id
          AND authorization.assignment_id = assignment.id
          AND authorization.policy_revision_id = NEW.policy_revision_id))
BEGIN SELECT RAISE(ABORT, 'V2 Task creation must consume authorization at next sequence'); END;
CREATE TRIGGER v2_task_creation_authorization_presentation_insert
BEFORE INSERT ON trunk_task_creation_authorization
WHEN NEW.task_name IS NULL OR length(trim(NEW.task_name)) = 0
  OR NEW.task_type IS NULL OR length(trim(NEW.task_type)) = 0
  OR NEW.task_origin IS NULL OR length(trim(NEW.task_origin)) = 0
  OR (NEW.linked_issue_number IS NOT NULL AND NEW.linked_issue_number < 1)
  OR (NEW.opening_prompt IS NOT NULL AND length(trim(NEW.opening_prompt)) = 0)
BEGIN SELECT RAISE(ABORT, 'V2 Task presentation must be exact'); END;
CREATE TRIGGER v2_task_creation_context_presentation_immutable
BEFORE UPDATE OF task_name, task_type, linked_issue_number, opening_prompt, task_origin
