CREATE TRIGGER v2_thread_turn_ticket_shape_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.owner_kind = 'THREAD_TURN'
BEGIN
    SELECT CASE
        WHEN NEW.operation_kind <> 'EXECUTE_THREAD_TURN'
          OR NEW.async_family <> 'AGENT_TURN'
          OR NEW.callback_route <> 'THREAD_TURN_RESULT'
          OR NEW.lane_mask NOT IN (1, 2)
          OR NEW.trunk_control <> 1
          OR NEW.exclusive_task <> 0
          OR NEW.writer_required <> 0
          OR NEW.workspace_id IS NULL
          OR NEW.trunk_id IS NULL
          OR NEW.task_id IS NOT NULL
          OR NEW.task_epoch IS NOT NULL
          OR NEW.stage_id IS NOT NULL
          OR NEW.stage_generation IS NOT NULL
          OR NOT EXISTS (
              SELECT 1 FROM thread_turn turn
              WHERE turn.id = NEW.owner_id
                AND ((turn.delivery_lane = 'CLI' AND NEW.lane_mask = 1)
                  OR (turn.delivery_lane = 'API' AND NEW.lane_mask = 2)))
        THEN RAISE(ABORT, 'ThreadTurn requires exact reserved Trunk-control capacity')
    END;
END;
CREATE TRIGGER v2_thread_turn_ticket_shape_update
BEFORE UPDATE OF operation_kind, async_family, owner_kind, callback_route,
        lane_mask, trunk_control, exclusive_task, writer_required,
        workspace_id, trunk_id, task_id, task_epoch, stage_id,
        stage_generation ON dispatch_ticket
WHEN NEW.owner_kind = 'THREAD_TURN'
BEGIN
    SELECT CASE
        WHEN NEW.operation_kind <> 'EXECUTE_THREAD_TURN'
          OR NEW.async_family <> 'AGENT_TURN'
          OR NEW.callback_route <> 'THREAD_TURN_RESULT'
          OR NEW.lane_mask NOT IN (1, 2)
          OR NEW.trunk_control <> 1
          OR NEW.exclusive_task <> 0
          OR NEW.writer_required <> 0
          OR NEW.workspace_id IS NULL
          OR NEW.trunk_id IS NULL
          OR NEW.task_id IS NOT NULL
          OR NEW.task_epoch IS NOT NULL
          OR NEW.stage_id IS NOT NULL
          OR NEW.stage_generation IS NOT NULL
          OR NOT EXISTS (
              SELECT 1 FROM thread_turn turn
              WHERE turn.id = NEW.owner_id
                AND ((turn.delivery_lane = 'CLI' AND NEW.lane_mask = 1)
                  OR (turn.delivery_lane = 'API' AND NEW.lane_mask = 2)))
        THEN RAISE(ABORT, 'ThreadTurn requires exact reserved Trunk-control capacity')
    END;
END;
CREATE TRIGGER v2_trunk_insert_shape
BEFORE INSERT ON threads
WHEN NEW.turn_version = 'V2'
BEGIN
    SELECT CASE WHEN NEW.lifecycle_state IS NULL
            OR NEW.lifecycle_state NOT IN ('ACTIVE', 'IDLE', 'ARCHIVED')
        THEN RAISE(ABORT, 'invalid V2 trunk lifecycle state') END;
END;
CREATE TRIGGER v2_trunk_physical_delete_guard_v269
BEFORE DELETE ON threads
WHEN OLD.turn_version = 'V2'
  AND NOT EXISTS (
      SELECT 1 FROM v2_trunk_purge_authorization_v269 authorization
      WHERE authorization.trunk_id = OLD.id
        AND authorization.archived_version = OLD.aggregate_version)
BEGIN
    SELECT RAISE(ABORT,
        'V2 Trunk physical delete requires exact purge authorization');
END;
CREATE TRIGGER v2_trunk_purge_authorization_insert_v269
BEFORE INSERT ON v2_trunk_purge_authorization_v269
WHEN NOT EXISTS (
    SELECT 1 FROM v2_trunk_purge_state_v269 state
    WHERE state.trunk_id = NEW.trunk_id
      AND state.lifecycle_state = 'ARCHIVED'
      AND state.aggregate_version = NEW.archived_version
      AND state.nonterminal_task_count = 0
      AND state.incomplete_cleanup_count = 0
      AND state.open_wait_count = 0
      AND state.live_turn_count = 0
      AND state.live_ticket_count = 0
      AND state.live_execution_count = 0
      AND state.live_operation_count = 0
      AND state.incomplete_stage_count = 0
      AND state.live_lease_count = 0)
BEGIN
    SELECT RAISE(ABORT,
        'V2 Trunk purge requires exact archived quiescent Cleanup proof');
END;
