BEFORE UPDATE OF turn_version, lifecycle_state ON threads
WHEN NEW.turn_version = 'V2'
BEGIN
    SELECT CASE WHEN NEW.lifecycle_state IS NULL
            OR NEW.lifecycle_state NOT IN ('ACTIVE', 'IDLE', 'ARCHIVED')
        THEN RAISE(ABORT, 'invalid V2 trunk lifecycle state') END;
END;
CREATE TRIGGER v2_trunk_version_monotonic
BEFORE UPDATE OF lifecycle_state, aggregate_version ON threads
WHEN OLD.turn_version = 'V2'
  AND (NEW.lifecycle_state IS NOT OLD.lifecycle_state
       OR NEW.aggregate_version IS NOT OLD.aggregate_version)
  AND NEW.aggregate_version <> OLD.aggregate_version + 1
BEGIN
    SELECT RAISE(ABORT, 'V2 trunk aggregate version must advance once');
END;
CREATE TRIGGER v2_user_remote_action_baseline_v270
BEFORE UPDATE OF recovery_baseline_json ON v2_user_remote_action_v270
WHEN OLD.recovery_baseline_json IS NOT NULL
  OR NEW.recovery_baseline_json IS NULL
  OR OLD.status <> 'CLAIMED'
  OR NEW.status <> OLD.status
BEGIN SELECT RAISE(ABORT,
    'V2 user remote action recovery baseline is immutable'); END;
CREATE TRIGGER v2_user_remote_action_ci_trigger_identity_v283
BEFORE UPDATE OF worktree_path, expected_code_fingerprint
ON v2_user_remote_action_v270
BEGIN SELECT RAISE(ABORT,
    'V2 user remote action worktree identity is immutable'); END;
CREATE TRIGGER v2_user_remote_action_ci_trigger_insert_v283
BEFORE INSERT ON v2_user_remote_action_v270
WHEN (NEW.semantic_action = 'TRIGGER_CI_EMPTY_COMMIT'
      AND NOT EXISTS (
          SELECT 1
          FROM tasks task
          JOIN task_code_identity identity ON identity.task_id = task.id
          JOIN task_current_code_subject_v230 code ON code.task_id = task.id
          JOIN remote_pr_binding binding
            ON binding.id = NEW.remote_pr_binding_id
          JOIN remote_development_stage remote
            ON remote.stage_id = NEW.remote_stage_id
          WHERE task.id = NEW.task_id
            AND task.workflow_version = 'V2'
            AND task.lifecycle_state = 'ACTIVE'
            AND task.epoch = NEW.task_epoch
            AND identity.worktree_path = NEW.worktree_path
            AND identity.publish_repository_id = NEW.head_repository_id
            AND identity.branch_name = NEW.branch_name
            AND code.code_fingerprint = NEW.expected_code_fingerprint
            AND code.head_sha = NEW.expected_head_sha
            AND code.base_sha = NEW.expected_base_sha
            AND remote.task_id = task.id
            AND remote.generation = NEW.stage_generation
            AND remote.current_head_sha = NEW.expected_head_sha
            AND remote.current_base_sha = NEW.expected_base_sha
            AND binding.task_id = task.id
            AND binding.head_repository_id = identity.publish_repository_id))
   OR (NEW.semantic_action <> 'TRIGGER_CI_EMPTY_COMMIT'
       AND (NEW.worktree_path IS NOT NULL
            OR NEW.expected_code_fingerprint IS NOT NULL))
BEGIN SELECT RAISE(ABORT,
    'empty-commit CI trigger lacks its exact Task worktree subject'); END;
CREATE TRIGGER v2_user_remote_action_delete_v270
BEFORE DELETE ON v2_user_remote_action_v270
WHEN NOT EXISTS (
    SELECT 1 FROM tasks task
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE task.id = OLD.task_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'V2 user remote action cannot be deleted'); END;
CREATE TRIGGER v2_user_remote_action_dispatch_delete_v270
BEFORE DELETE ON v2_user_remote_action_dispatch_v270
WHEN NOT EXISTS (
    SELECT 1 FROM v2_user_remote_action_v270 action
    JOIN tasks task ON task.id = action.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE action.id = OLD.action_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'V2 user remote action dispatch cannot be deleted'); END;
CREATE TRIGGER v2_user_remote_action_dispatch_insert_v270
BEFORE INSERT ON v2_user_remote_action_dispatch_v270
WHEN NOT EXISTS (
    SELECT 1
    FROM v2_user_remote_action_v270 action
    JOIN dispatch_ticket ticket ON ticket.id = NEW.dispatch_ticket_id
    WHERE action.id = NEW.action_id
      AND action.operation_id = NEW.operation_id
      AND action.status = 'REQUESTED'
      AND ticket.operation_id = action.operation_id
      AND ticket.operation_kind = 'APPLY_V2_USER_REMOTE_ACTION'
      AND ticket.callback_route = 'V2_USER_REMOTE_ACTION_RESULT'
      AND ticket.owner_kind = 'TASK'
      AND ticket.owner_id = action.task_id
      AND ticket.task_id = action.task_id
      AND ticket.task_epoch = action.task_epoch
      AND ticket.stage_id = action.remote_stage_id
      AND ticket.stage_generation = action.stage_generation
      AND ticket.expected_head_sha = action.expected_head_sha
      AND ticket.expected_base_sha = action.expected_base_sha
      AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'V2 user remote action dispatch is invalid'); END;
CREATE TRIGGER v2_user_remote_action_dispatch_update_v270
BEFORE UPDATE ON v2_user_remote_action_dispatch_v270
BEGIN SELECT RAISE(ABORT, 'V2 user remote action dispatch is immutable'); END;
CREATE TRIGGER v2_user_remote_action_draft_delete_v270
BEFORE DELETE ON v2_user_remote_action_draft_v270
WHEN NOT EXISTS (
    SELECT 1 FROM v2_user_remote_action_v270 action
    JOIN tasks task ON task.id = action.task_id
    JOIN v2_trunk_purge_authorization_v269 authorization
      ON authorization.trunk_id = task.thread_id
    WHERE action.id = OLD.action_id AND task.workflow_version = 'V2')
BEGIN SELECT RAISE(ABORT, 'V2 user remote action draft cannot be deleted'); END;
CREATE TRIGGER v2_user_remote_action_draft_insert_v270
BEFORE INSERT ON v2_user_remote_action_draft_v270
WHEN NOT EXISTS (
    SELECT 1
    FROM v2_user_remote_action_v270 action
    JOIN pr_comment comment ON comment.id = NEW.comment_id
    WHERE action.id = NEW.action_id
      AND action.kind = 'SUBMIT_REVIEW'
      AND comment.pr_id = action.pr_id
      AND comment.origin = 'local'
      AND comment.parent_comment_id IS NULL
      AND comment.published_at_ms IS NULL
      AND comment.stripped_on_push_at_ms IS NULL
      AND comment.resolved_at_ms IS NULL
      AND comment.dismissed_at_ms IS NULL
      AND comment.scope = NEW.scope
      AND comment.file_path IS NEW.file_path
      AND comment.line_number IS NEW.line_number
      AND COALESCE(comment.side,
            CASE WHEN comment.scope = 'file-line' THEN 'RIGHT' END) IS NEW.side
      AND comment.start_line IS NEW.start_line
      AND comment.start_side IS NEW.start_side
      AND comment.body = NEW.body
      AND comment.finding_id IS NEW.finding_id)
  OR EXISTS (
    SELECT 1
    FROM v2_user_remote_action_draft_v270 reserved
    JOIN v2_user_remote_action_v270 action
      ON action.id = reserved.action_id
    WHERE reserved.comment_id = NEW.comment_id
      AND (action.status NOT IN ('SUCCEEDED', 'CANCELED', 'ABANDONED')
        OR action.finalized_at_ms IS NULL))
BEGIN SELECT RAISE(ABORT, 'V2 review draft changed before authorization'); END;
CREATE TRIGGER v2_user_remote_action_draft_update_v270
BEFORE UPDATE ON v2_user_remote_action_draft_v270
BEGIN SELECT RAISE(ABORT, 'V2 user remote action draft is immutable'); END;
CREATE TRIGGER v2_user_remote_action_identity_v270
BEFORE UPDATE OF id, operation_id, task_id, command_id, task_epoch, remote_stage_id,
        stage_generation, remote_pr_binding_id, pr_id, kind,
        remote_repository_id, head_repository_id, remote_pr_number,
        branch_name, expected_head_sha, expected_base_sha, payload_json,
        payload_digest, handled_action, semantic_attempt, attempt_limit,
        authorized_by, authorized_at_ms ON v2_user_remote_action_v270
BEGIN SELECT RAISE(ABORT, 'V2 user remote action identity is immutable'); END;
CREATE TRIGGER v2_user_remote_action_semantic_insert_v282
BEFORE INSERT ON v2_user_remote_action_v270
WHEN NEW.semantic_action IS NULL
  OR NEW.semantic_action NOT IN (
      'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
      'SUBMIT_REVIEW', 'RERUN_FAILED_CHECKS', 'SET_DRAFT_STATE',
      'UPDATE_TITLE', 'UPDATE_BODY', 'CLOSE_PULL_REQUEST',
      'COMMENT_AND_CLOSE',
      'REPLY_REVIEW_THREAD', 'EDIT_ISSUE_COMMENT', 'EDIT_REVIEW_COMMENT',
      'DELETE_ISSUE_COMMENT', 'DELETE_REVIEW_COMMENT', 'ADD_REVIEWER',
      'REMOVE_REVIEWER', 'SET_ASSIGNEE', 'SET_LABEL',
      'CREATE_INLINE_COMMENT', 'REACT_PULL_REQUEST',
      'REACT_REVIEW_COMMENT', 'REACT_ISSUE_COMMENT',
      'SET_THREAD_RESOLUTION', 'TRIGGER_CI_EMPTY_COMMIT')
  OR (NEW.semantic_action IN (
          'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
          'SUBMIT_REVIEW')
      AND NEW.kind <> NEW.semantic_action)
  OR (NEW.semantic_action NOT IN (
          'DEQUEUE', 'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT',
          'SUBMIT_REVIEW')
      AND NEW.kind <> 'DEQUEUE')
BEGIN SELECT RAISE(ABORT,
    'V2 user remote action semantic identity is invalid'); END;
CREATE TRIGGER v2_user_remote_action_semantic_update_v282
BEFORE UPDATE OF semantic_action ON v2_user_remote_action_v270
BEGIN SELECT RAISE(ABORT,
    'V2 user remote action semantic identity is immutable'); END;
CREATE TRIGGER v2_user_remote_action_transition_v270
BEFORE UPDATE OF status ON v2_user_remote_action_v270
WHEN NEW.status IS NOT OLD.status
  AND NOT (
      (OLD.status IN ('REQUESTED', 'FAILED', 'INDETERMINATE')
        AND NEW.status IN ('CLAIMED', 'CANCELED', 'ABANDONED'))
      OR (OLD.status = 'CLAIMED'
        AND NEW.status IN ('SUCCEEDED', 'FAILED', 'INDETERMINATE',
            'CANCELED', 'ABANDONED')))
BEGIN SELECT RAISE(ABORT, 'V2 user remote action transition is invalid'); END;
CREATE TRIGGER validation_evidence_immutable
BEFORE UPDATE ON validation_evidence
BEGIN SELECT RAISE(ABORT, 'ValidationEvidence is immutable'); END;
CREATE TRIGGER validation_evidence_owner_insert
BEFORE INSERT ON validation_evidence
WHEN NOT EXISTS (
    SELECT 1
    FROM validation_operation o
    JOIN validation_pass p ON p.id = NEW.validation_pass_id
    WHERE o.id = NEW.validation_operation_id
      AND o.status = 'DISPATCHED'
      AND o.task_id = NEW.task_id
      AND o.task_epoch = NEW.task_epoch
      AND o.local_development_stage_id = NEW.stage_id
      AND o.stage_generation = NEW.stage_generation
      AND o.code_fingerprint = NEW.code_fingerprint
      AND o.expected_head_sha = NEW.head_sha
      AND o.expected_base_sha = NEW.base_sha
      AND p.task_id = NEW.task_id
      AND p.workflow_version = 'V2'
      AND p.task_epoch = NEW.task_epoch
      AND p.stage_id = NEW.stage_id
      AND p.stage_generation = NEW.stage_generation
      AND p.operation_id = o.operation_id
      AND p.semantic_attempt = o.semantic_attempt
      AND p.code_fingerprint = NEW.code_fingerprint
      AND p.expected_head_sha = NEW.head_sha
      AND p.expected_base_sha = NEW.base_sha
      AND p.ended_at_ms IS NOT NULL
      AND p.passed = NEW.passed)
BEGIN
    SELECT RAISE(ABORT, 'ValidationEvidence does not match its exact completed pass');
END;
CREATE TRIGGER validation_operation_completion_proof
BEFORE UPDATE OF status ON validation_operation
WHEN NEW.status = 'COMPLETED'
  AND NOT EXISTS (
      SELECT 1 FROM validation_evidence e
      WHERE e.validation_operation_id = NEW.id
        AND e.task_id = NEW.task_id
        AND e.task_epoch = NEW.task_epoch
        AND e.stage_id = NEW.local_development_stage_id
        AND e.stage_generation = NEW.stage_generation
        AND e.code_fingerprint = NEW.code_fingerprint
        AND e.head_sha = NEW.expected_head_sha
        AND e.base_sha = NEW.expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'completed validation requires exact immutable evidence'); END;
CREATE TRIGGER validation_operation_dispatch_fence
BEFORE UPDATE OF status ON validation_operation
WHEN NEW.status = 'DISPATCHED'
  AND NOT EXISTS (
      SELECT 1 FROM dispatch_ticket ticket
      WHERE ticket.operation_id = NEW.operation_id
        AND ticket.operation_kind = 'VALIDATE_LOCAL_DEVELOPMENT'
        AND ticket.async_family = 'VALIDATION'
        AND ticket.owner_kind = 'STAGE'
        AND ticket.owner_id = NEW.local_development_stage_id
        AND ticket.task_id = NEW.task_id
        AND ticket.task_epoch = NEW.task_epoch
        AND ticket.stage_id = NEW.local_development_stage_id
        AND ticket.stage_generation = NEW.stage_generation
        AND ticket.attempt = NEW.semantic_attempt
        AND ticket.expected_code_fingerprint = NEW.code_fingerprint
        AND ticket.expected_head_sha = NEW.expected_head_sha
        AND ticket.expected_base_sha = NEW.expected_base_sha
        AND ticket.exclusive_task = 1 AND ticket.writer_required = 0
        AND ticket.lane_mask = 4
        AND ticket.status = 'REQUESTED')
BEGIN SELECT RAISE(ABORT, 'dispatched validation requires exact VALIDATION ticket'); END;
CREATE TRIGGER validation_operation_identity_immutable
BEFORE UPDATE OF local_development_stage_id, task_id, task_epoch,
        stage_generation, dev_report_id, operation_id, semantic_attempt,
        code_fingerprint, expected_head_sha, expected_base_sha, requested_at_ms
ON validation_operation
WHEN NEW.local_development_stage_id IS NOT OLD.local_development_stage_id
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.dev_report_id IS NOT OLD.dev_report_id
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
  OR NEW.requested_at_ms IS NOT OLD.requested_at_ms
BEGIN SELECT RAISE(ABORT, 'ValidationOperation fence is immutable'); END;
CREATE TRIGGER validation_operation_owner_insert
BEFORE INSERT ON validation_operation
BEGIN
    SELECT CASE
        WHEN NEW.status <> 'REQUESTED'
            THEN RAISE(ABORT, 'ValidationOperation must start REQUESTED')
        WHEN NOT EXISTS (
            SELECT 1
            FROM local_development_stage l
            JOIN stage s ON s.id = l.stage_id
            JOIN tasks t ON t.id = l.task_id
            JOIN task_current_stage c ON c.stage_id = l.stage_id
            JOIN dev_report r ON r.id = NEW.dev_report_id
            WHERE l.stage_id = NEW.local_development_stage_id
              AND l.task_id = NEW.task_id
              AND l.generation = NEW.stage_generation
              AND l.opened_for_epoch = NEW.task_epoch
              AND t.epoch = NEW.task_epoch
              AND t.lifecycle_state = 'ACTIVE'
              AND s.completed_at_ms IS NULL
              AND c.task_id = NEW.task_id
              AND c.stage_generation = NEW.stage_generation
              AND r.local_development_stage_id = l.stage_id
              AND r.task_id = NEW.task_id
              AND r.task_epoch = NEW.task_epoch
              AND r.stage_generation = NEW.stage_generation
              AND r.code_fingerprint = NEW.code_fingerprint
              AND r.head_sha = NEW.expected_head_sha
              AND r.base_sha = NEW.expected_base_sha)
            THEN RAISE(ABORT, 'ValidationOperation does not match its DevReport subject')
    END;
END;
CREATE TRIGGER validation_operation_terminal_immutable
BEFORE UPDATE ON validation_operation
WHEN OLD.status IN ('COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')
BEGIN SELECT RAISE(ABORT, 'terminal ValidationOperation is immutable'); END;
CREATE TRIGGER validation_operation_transition
BEFORE UPDATE OF status ON validation_operation
WHEN NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN (
        'DISPATCHED', 'FAILED', 'CANCELED', 'SUPERSEDED'))
    OR (OLD.status = 'DISPATCHED' AND NEW.status IN (
        'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')))
BEGIN SELECT RAISE(ABORT, 'illegal ValidationOperation transition'); END;
CREATE TRIGGER validation_pass_fence_immutable
BEFORE UPDATE OF workflow_version, task_epoch, stage_id, stage_generation,
        operation_id, semantic_attempt, code_fingerprint,
        expected_head_sha, expected_base_sha ON validation_pass
WHEN NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.stage_id IS NOT OLD.stage_id
  OR NEW.stage_generation IS NOT OLD.stage_generation
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.semantic_attempt IS NOT OLD.semantic_attempt
  OR NEW.code_fingerprint IS NOT OLD.code_fingerprint
  OR NEW.expected_head_sha IS NOT OLD.expected_head_sha
  OR NEW.expected_base_sha IS NOT OLD.expected_base_sha
BEGIN SELECT RAISE(ABORT, 'validation fence is immutable'); END;
CREATE TRIGGER validation_pass_route_insert
BEFORE INSERT ON validation_pass
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = NEW.workflow_version)
    THEN RAISE(ABORT, 'validation workflow version does not match Task') END;
    SELECT CASE WHEN NEW.workflow_version = 'V2' AND (
        NEW.task_epoch IS NULL OR NEW.stage_id IS NULL
        OR NEW.stage_generation IS NULL OR NEW.operation_id IS NULL
        OR NEW.semantic_attempt IS NULL OR NEW.semantic_attempt <= 0
        OR NEW.code_fingerprint IS NULL
        OR NOT EXISTS (
            SELECT 1 FROM stage s JOIN tasks t ON t.id = s.task_id
            WHERE s.id = NEW.stage_id
              AND s.generation = NEW.stage_generation
              AND t.id = NEW.task_id
              AND t.epoch = NEW.task_epoch))
    THEN RAISE(ABORT, 'V2 validation requires its exact Task, Stage and operation fence') END;
END;
CREATE TRIGGER worktree_lease_fence_immutable
BEFORE UPDATE OF worktree_path, task_id, agent_kind, acquired_at_ms,
        workflow_version, operation_id, task_epoch,
        fencing_token, lease_owner ON worktree_leases
WHEN NEW.worktree_path IS NOT OLD.worktree_path
  OR NEW.task_id IS NOT OLD.task_id
  OR NEW.agent_kind IS NOT OLD.agent_kind
  OR NEW.acquired_at_ms IS NOT OLD.acquired_at_ms
  OR NEW.workflow_version IS NOT OLD.workflow_version
  OR NEW.operation_id IS NOT OLD.operation_id
  OR NEW.task_epoch IS NOT OLD.task_epoch
  OR NEW.fencing_token IS NOT OLD.fencing_token
  OR NEW.lease_owner IS NOT OLD.lease_owner
BEGIN SELECT RAISE(ABORT, 'worktree lease fence is immutable'); END;
CREATE TRIGGER worktree_lease_route_insert
BEFORE INSERT ON worktree_leases
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM tasks t
        WHERE t.id = NEW.task_id AND t.workflow_version = NEW.workflow_version)
    THEN RAISE(ABORT, 'worktree lease workflow version does not match Task') END;
    SELECT CASE WHEN NEW.workflow_version = 'V2' AND (
        NEW.operation_id IS NULL OR NEW.task_epoch IS NULL
        OR NEW.fencing_token IS NULL OR NEW.fencing_token <= 0
        OR NEW.lease_owner IS NULL OR NEW.expires_at_ms IS NULL
        OR NOT EXISTS (
            SELECT 1
            FROM capacity_lease c
            JOIN tasks t ON t.id = c.task_id
            WHERE c.operation_id = NEW.operation_id
              AND c.workflow_source = 'V2'
              AND c.task_id = NEW.task_id
              AND c.task_epoch = NEW.task_epoch
              AND c.writer_required = 1
              AND c.fencing_token = NEW.fencing_token
              AND c.holder = NEW.lease_owner
              AND c.released_at_ms IS NULL
              AND NEW.expires_at_ms <= c.expires_at_ms
              AND t.epoch = NEW.task_epoch))
    THEN RAISE(ABORT, 'V2 worktree lease requires its exact fence') END;
END;
CREATE TRIGGER worktree_lease_route_update
BEFORE UPDATE ON worktree_leases
WHEN OLD.workflow_version = 'V2'
  AND NOT EXISTS (
      SELECT 1 FROM capacity_lease c
      WHERE c.operation_id = NEW.operation_id
        AND c.workflow_source = 'V2'
        AND c.task_id = NEW.task_id
        AND c.task_epoch = NEW.task_epoch
        AND c.writer_required = 1
        AND c.fencing_token = NEW.fencing_token
        AND c.holder = NEW.lease_owner
        AND c.released_at_ms IS NULL
        AND NEW.expires_at_ms IS NOT NULL
        AND NEW.expires_at_ms <= c.expires_at_ms)
BEGIN SELECT RAISE(ABORT, 'V2 worktree lease update lost its CapacityLease'); END;
CREATE TRIGGER worktree_lease_v2_path_insert
BEFORE INSERT ON worktree_leases
WHEN NEW.workflow_version = 'V2'
  AND NOT (
      EXISTS (
          SELECT 1 FROM provision_task_operation operation
          WHERE operation.task_id = NEW.task_id
            AND operation.task_epoch = NEW.task_epoch
            AND operation.operation_id = NEW.operation_id
            AND operation.requested_worktree_path = NEW.worktree_path
            AND operation.status = 'DISPATCHED')
      OR EXISTS (
          SELECT 1 FROM task_code_identity code
          WHERE code.task_id = NEW.task_id
            AND code.worktree_path = NEW.worktree_path))
BEGIN SELECT RAISE(ABORT, 'V2 WorktreeLease path lacks exact Task authority'); END;
CREATE INDEX idx_dispatch_ticket_agent_turn_task_v267
    ON dispatch_ticket(task_id, created_at_ms DESC, id DESC)
    WHERE async_family = 'AGENT_TURN';
CREATE INDEX idx_dispatch_ticket_agent_turn_trunk_v267
    ON dispatch_ticket(trunk_id, created_at_ms DESC, id DESC)
    WHERE async_family = 'AGENT_TURN';
CREATE INDEX idx_dispatch_ticket_agent_turn_workspace_v267
    ON dispatch_ticket(workspace_id, created_at_ms DESC, id DESC)
    WHERE async_family = 'AGENT_TURN';
CREATE INDEX idx_dispatch_ticket_claim
    ON dispatch_ticket(claim_owner, claim_expires_at_ms) WHERE claim_owner IS NOT NULL;
CREATE INDEX idx_dispatch_ticket_eligible
    ON dispatch_ticket(status, next_attempt_at_ms, created_at_ms);
CREATE TABLE review_session_snapshot_operation_v293 (
    id                 TEXT    NOT NULL PRIMARY KEY,
    dispatch_ticket_id TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) DEFERRABLE INITIALLY DEFERRED,
    review_id          TEXT    NOT NULL
        REFERENCES review_session(id) ON DELETE CASCADE,
    command_id         TEXT    NOT NULL,
    pr_id              TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    repository         TEXT    NOT NULL,
    remote_pr_number   INTEGER NOT NULL CHECK (remote_pr_number > 0),
    base_branch        TEXT    NOT NULL,
    pr_title           TEXT    NOT NULL,
    pr_description     TEXT    NOT NULL,
    workspace_id       TEXT    REFERENCES workspaces(id),
    repository_root    TEXT,
    scope              TEXT    NOT NULL CHECK (scope IN ('quick', 'full')),
    request_json       TEXT    NOT NULL CHECK (json_valid(request_json)),
    expected_base_sha  TEXT    NOT NULL,
    expected_head_sha  TEXT    NOT NULL,
    status             TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    result_json        TEXT,
    error_message      TEXT,
    round_id           TEXT REFERENCES review_round(id),
    requested_at_ms    INTEGER NOT NULL,
    completed_at_ms    INTEGER,
    UNIQUE (review_id, command_id),
    CHECK (length(trim(command_id)) > 0
        AND length(trim(repository)) > 0
        AND length(trim(base_branch)) > 0
        AND length(trim(expected_base_sha)) > 0
        AND length(trim(expected_head_sha)) > 0),
    CHECK ((scope = 'quick') = (workspace_id IS NULL)),
    CHECK ((scope = 'quick') = (repository_root IS NULL)),
    CHECK (repository_root IS NULL OR length(trim(repository_root)) > 0),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK ((status = 'REQUESTED') = (result_json IS NULL)),
    CHECK ((status = 'COMPLETED') = (round_id IS NOT NULL))
);
CREATE UNIQUE INDEX review_session_snapshot_one_requested_v293
    ON review_session_snapshot_operation_v293(review_id)
    WHERE status = 'REQUESTED';
CREATE INDEX review_session_snapshot_latest_v293
    ON review_session_snapshot_operation_v293(review_id, requested_at_ms DESC);
CREATE TRIGGER review_session_snapshot_operation_insert_v293
BEFORE INSERT ON review_session_snapshot_operation_v293
WHEN NOT EXISTS (
    SELECT 1
    FROM review_session review
    JOIN pr ON pr.id = review.pr_id
    WHERE review.id = NEW.review_id
      AND review.pr_id = NEW.pr_id
      AND pr.repo = NEW.repository
      AND pr.remote_pr_number = NEW.remote_pr_number
      AND pr.base_branch = NEW.base_branch
      AND pr.title = NEW.pr_title
      AND pr.description = NEW.pr_description
      AND review.owner_task_id IS NULL
      AND review.owner_thread_id IS NULL
      AND pr.task_id IS NULL
      AND review.status IN ('ACTIVE', 'STALE')
      AND review.workspace_id IS NEW.workspace_id
      AND NEW.status = 'REQUESTED'
      AND ((NEW.scope = 'quick'
              AND NEW.workspace_id IS NULL
              AND NEW.repository_root IS NULL
              AND pr.origin = 'external'
              AND pr.repo IS NOT NULL
              AND pr.remote_pr_number IS NOT NULL)
        OR (NEW.scope = 'full'
              AND NEW.workspace_id IS NOT NULL
              AND NEW.repository_root IS NOT NULL
              AND EXISTS (
                  SELECT 1
                  FROM workspace_repos binding
                  JOIN watched_repos watched
                    ON lower(binding.repo_full_name) =
                       lower(watched.owner || '/' || watched.repo)
                  WHERE binding.workspace_id = NEW.workspace_id
                    AND lower(binding.repo_full_name) = lower(pr.repo)
                    AND watched.local_clone_path = NEW.repository_root)))
      AND NEW.expected_base_sha = COALESCE((
          SELECT commit_row.sha FROM pr_commit commit_row
          WHERE commit_row.pr_id = NEW.pr_id
          ORDER BY commit_row.authored_at_ms, commit_row.id LIMIT 1),
          'unknown-base')
      AND NEW.expected_head_sha = COALESCE((
          SELECT commit_row.sha FROM pr_commit commit_row
          WHERE commit_row.pr_id = NEW.pr_id
          ORDER BY commit_row.authored_at_ms DESC, commit_row.id DESC LIMIT 1),
          'unknown-head'))
BEGIN
    SELECT RAISE(ABORT,
        'ReviewSession snapshot requires an exact standalone review subject');
END;
CREATE TRIGGER review_session_snapshot_identity_immutable_v293
BEFORE UPDATE OF id, dispatch_ticket_id, review_id, command_id, pr_id, repository,
    remote_pr_number, base_branch, pr_title, pr_description, workspace_id,
    repository_root, scope, request_json, expected_base_sha,
    expected_head_sha, requested_at_ms
ON review_session_snapshot_operation_v293
BEGIN
    SELECT RAISE(ABORT, 'ReviewSession snapshot identity is immutable');
END;
CREATE TRIGGER workspace_repository_detach_quiescence_v293
BEFORE UPDATE OF detached_at_ms ON workspaces
WHEN OLD.detached_at_ms IS NULL
  AND NEW.detached_at_ms IS NOT NULL
  AND (EXISTS (
          SELECT 1
          FROM tasks task
          JOIN threads trunk ON trunk.id = task.thread_id
          WHERE trunk.workspace_id = OLD.id
            AND task.workflow_version = 'V2'
            AND task.lifecycle_state NOT IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
    OR EXISTS (
          SELECT 1 FROM dispatch_ticket ticket
          WHERE ticket.workspace_id = OLD.id
            AND ticket.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED')))
BEGIN
    SELECT RAISE(ABORT,
        'Workspace repository detach requires V2 quiescence');
END;
CREATE TRIGGER workspace_repository_reclone_quiescence_v293
BEFORE INSERT ON workspace_creation
WHEN NEW.operation_kind = 'reclone'
  AND NEW.state IN ('queued', 'forking', 'cloning', 'syncing')
  AND NEW.workspace_id IS NOT NULL
  AND (EXISTS (
          SELECT 1
          FROM tasks task
          JOIN threads trunk ON trunk.id = task.thread_id
          WHERE trunk.workspace_id = NEW.workspace_id
            AND task.workflow_version = 'V2'
            AND task.lifecycle_state NOT IN (
                'COMPLETED', 'CANCELED', 'REMOTE_CLOSED'))
    OR EXISTS (
          SELECT 1 FROM dispatch_ticket ticket
          WHERE ticket.workspace_id = NEW.workspace_id
            AND ticket.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED')))
BEGIN
    SELECT RAISE(ABORT,
        'Workspace repository re-clone requires V2 quiescence');
END;
CREATE TRIGGER dispatch_ticket_workspace_repository_available_v293
BEFORE INSERT ON dispatch_ticket
WHEN NEW.workspace_id IS NOT NULL
  AND (EXISTS (
          SELECT 1 FROM workspaces workspace
          WHERE workspace.id = NEW.workspace_id
            AND workspace.detached_at_ms IS NOT NULL)
    OR EXISTS (
          SELECT 1 FROM workspace_creation creation
          WHERE creation.workspace_id = NEW.workspace_id
            AND creation.operation_kind = 'reclone'
            AND creation.state IN ('queued', 'forking', 'cloning', 'syncing')))
BEGIN
    SELECT RAISE(ABORT,
        'DispatchTicket Workspace repository is unavailable');
END;
CREATE TRIGGER review_session_snapshot_delete_ticket_v293
AFTER DELETE ON review_session_snapshot_operation_v293
BEGIN
    DELETE FROM dispatch_ticket
    WHERE id = OLD.dispatch_ticket_id
      AND status IN ('SUCCEEDED', 'FAILED', 'CANCELED');
END;
CREATE TRIGGER review_session_snapshot_transition_v293
BEFORE UPDATE OF status ON review_session_snapshot_operation_v293
WHEN OLD.status <> 'REQUESTED' OR NEW.status = 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT,
        'ReviewSession snapshot has one terminal transition');
END;
CREATE TRIGGER review_session_snapshot_terminal_immutable_v293
BEFORE UPDATE ON review_session_snapshot_operation_v293
WHEN OLD.status <> 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT, 'Terminal ReviewSession snapshot is immutable');
END;
CREATE TRIGGER dispatch_ticket_review_session_owner_v293
BEFORE INSERT ON dispatch_ticket
WHEN NEW.owner_kind = 'REVIEW_SESSION'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM review_session_snapshot_operation_v293 operation
        JOIN review_session review ON review.id = operation.review_id
        WHERE operation.id = NEW.operation_id
          AND operation.dispatch_ticket_id = NEW.id
          AND review.id = NEW.owner_id
          AND review.owner_task_id IS NULL
          AND review.owner_thread_id IS NULL
          AND review.workspace_id IS NEW.workspace_id
          AND NEW.trunk_id IS NULL AND NEW.task_id IS NULL
          AND NEW.task_epoch IS NULL AND NEW.stage_id IS NULL
          AND NEW.stage_generation IS NULL)
    THEN RAISE(ABORT, 'DispatchTicket ReviewSession owner is invalid') END;
END;
CREATE TRIGGER dispatch_ticket_review_session_snapshot_v293
BEFORE INSERT ON dispatch_ticket
WHEN NEW.owner_kind = 'REVIEW_SESSION'
  OR NEW.callback_route = 'REVIEW_SESSION_SNAPSHOT_RESULT'
  OR NEW.operation_kind = 'CAPTURE_REVIEW_SESSION_SNAPSHOT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM review_session_snapshot_operation_v293 operation
        WHERE operation.id = NEW.operation_id
          AND operation.review_id = NEW.owner_id
          AND operation.workspace_id IS NEW.workspace_id
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND operation.status = 'REQUESTED'
          AND NEW.operation_kind = 'CAPTURE_REVIEW_SESSION_SNAPSHOT'
          AND NEW.async_family = CASE operation.scope
              WHEN 'quick' THEN 'REMOTE_OBSERVATION' ELSE 'LOCAL_GIT' END
          AND NEW.callback_route = 'REVIEW_SESSION_SNAPSHOT_RESULT'
          AND NEW.lane_mask = CASE operation.scope
              WHEN 'quick' THEN 64 ELSE 48 END
          AND NEW.trunk_control = 0 AND NEW.exclusive_task = 0
          AND NEW.writer_required = 0 AND NEW.trunk_id IS NULL
          AND NEW.task_id IS NULL AND NEW.task_epoch IS NULL
          AND NEW.stage_id IS NULL AND NEW.stage_generation IS NULL
          AND NEW.attempt = 1
          AND NEW.expected_code_fingerprint IS NULL
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT,
        'ReviewSession snapshot DispatchTicket is not exact') END;
END;
CREATE TABLE task_review_round_snapshot_operation_v293 (
    id                        TEXT    NOT NULL PRIMARY KEY,
    dispatch_ticket_id        TEXT    NOT NULL UNIQUE
        REFERENCES dispatch_ticket(id) DEFERRABLE INITIALLY DEFERRED,
    review_id                 TEXT    NOT NULL
        REFERENCES review_session(id) ON DELETE CASCADE,
    command_id                TEXT    NOT NULL,
    pr_id                     TEXT    NOT NULL REFERENCES pr(id) ON DELETE CASCADE,
    repository                TEXT,
    remote_pr_number          INTEGER,
    base_branch               TEXT    NOT NULL,
    pr_title                  TEXT    NOT NULL,
    pr_description            TEXT    NOT NULL,
    task_id                   TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                INTEGER NOT NULL CHECK (task_epoch > 0),
    worktree_path             TEXT    NOT NULL,
    code_fingerprint          TEXT    NOT NULL,
    expected_head_sha         TEXT    NOT NULL,
    expected_base_sha         TEXT    NOT NULL,
    request_json              TEXT    NOT NULL CHECK (json_valid(request_json)),
    status                    TEXT    NOT NULL CHECK (status IN (
        'REQUESTED', 'COMPLETED', 'FAILED', 'CANCELED', 'SUPERSEDED')),
    result_json               TEXT,
    error_message             TEXT,
    round_id                  TEXT REFERENCES review_round(id),
    requested_at_ms           INTEGER NOT NULL,
    completed_at_ms           INTEGER,
    UNIQUE (review_id, command_id),
    CHECK ((repository IS NULL) = (remote_pr_number IS NULL)),
    CHECK (repository IS NULL OR length(trim(repository)) > 0),
    CHECK (remote_pr_number IS NULL OR remote_pr_number > 0),
    CHECK (length(trim(command_id)) > 0
        AND length(trim(base_branch)) > 0
        AND length(trim(worktree_path)) > 0
        AND length(trim(code_fingerprint)) > 0
        AND length(trim(expected_head_sha)) > 0
        AND length(trim(expected_base_sha)) > 0),
    CHECK ((status = 'REQUESTED') = (completed_at_ms IS NULL)),
    CHECK ((status = 'REQUESTED') = (result_json IS NULL)),
    CHECK ((status = 'COMPLETED') = (round_id IS NOT NULL))
);
CREATE UNIQUE INDEX task_review_round_snapshot_one_requested_v293
    ON task_review_round_snapshot_operation_v293(review_id)
    WHERE status = 'REQUESTED';
CREATE INDEX task_review_round_snapshot_latest_v293
    ON task_review_round_snapshot_operation_v293(review_id, requested_at_ms DESC);
CREATE TRIGGER task_review_round_snapshot_insert_v293
BEFORE INSERT ON task_review_round_snapshot_operation_v293
WHEN NOT EXISTS (
    SELECT 1
    FROM review_session review
    JOIN pr ON pr.id = review.pr_id
    JOIN tasks task ON task.id = pr.task_id
    JOIN threads trunk ON trunk.id = task.thread_id
    JOIN task_code_identity identity ON identity.task_id = task.id
    JOIN task_current_code_subject_v230 code ON code.task_id = task.id
    WHERE review.id = NEW.review_id
      AND review.pr_id = NEW.pr_id
      AND pr.repo IS NEW.repository
      AND pr.remote_pr_number IS NEW.remote_pr_number
      AND pr.base_branch = NEW.base_branch
      AND pr.title = NEW.pr_title
      AND pr.description = NEW.pr_description
      AND review.owner_task_id = NEW.task_id
      AND review.owner_thread_id = task.thread_id
      AND review.workspace_id = trunk.workspace_id
      AND review.status IN ('ACTIVE', 'STALE')
      AND task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.task_epoch
      AND identity.worktree_path = NEW.worktree_path
      AND code.code_fingerprint = NEW.code_fingerprint
      AND code.head_sha = NEW.expected_head_sha
      AND code.base_sha = NEW.expected_base_sha
      AND NEW.status = 'REQUESTED')
BEGIN
    SELECT RAISE(ABORT,
        'Task review round snapshot requires an exact active V2 Task subject');
END;
CREATE TRIGGER task_review_round_snapshot_identity_immutable_v293
BEFORE UPDATE OF id, dispatch_ticket_id, review_id, command_id, pr_id,
    repository, remote_pr_number, base_branch, pr_title, pr_description,
    task_id, task_epoch, worktree_path, code_fingerprint,
    expected_head_sha, expected_base_sha, request_json, requested_at_ms
ON task_review_round_snapshot_operation_v293
BEGIN
    SELECT RAISE(ABORT, 'Task review round snapshot identity is immutable');
END;
