BEFORE UPDATE OF status ON task_review_round_snapshot_operation_v293
WHEN OLD.status <> 'REQUESTED' OR NEW.status = 'REQUESTED'
BEGIN
    SELECT RAISE(ABORT,
        'Task review round snapshot has one terminal transition');
