CREATE TRIGGER task_review_round_snapshot_delete_ticket_v293
AFTER DELETE ON task_review_round_snapshot_operation_v293
BEGIN
    DELETE FROM dispatch_ticket
    WHERE id = OLD.dispatch_ticket_id
      AND status IN ('SUCCEEDED', 'FAILED', 'CANCELED');
END;
CREATE TRIGGER dispatch_ticket_task_review_round_snapshot_v293
BEFORE INSERT ON dispatch_ticket
WHEN NEW.callback_route = 'TASK_REVIEW_ROUND_SNAPSHOT_RESULT'
  OR NEW.operation_kind = 'CAPTURE_TASK_REVIEW_ROUND_SNAPSHOT'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM task_review_round_snapshot_operation_v293 operation
        WHERE operation.id = NEW.operation_id
          AND operation.dispatch_ticket_id = NEW.id
          AND operation.task_id = NEW.owner_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.code_fingerprint = NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND operation.status = 'REQUESTED'
          AND NEW.operation_kind = 'CAPTURE_TASK_REVIEW_ROUND_SNAPSHOT'
          AND NEW.async_family = 'LOCAL_GIT'
          AND NEW.owner_kind = 'TASK'
          AND NEW.callback_route = 'TASK_REVIEW_ROUND_SNAPSHOT_RESULT'
          AND NEW.lane_mask = 16
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = 1
          AND NEW.writer_required = 1
          AND NEW.stage_id IS NULL AND NEW.stage_generation IS NULL
          AND NEW.attempt = 1 AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT,
        'Task review round snapshot DispatchTicket is not exact') END;
END;
CREATE TRIGGER task_review_snapshot_delete_live_guard_v293
BEFORE DELETE ON task_review_snapshot_operation_v286
WHEN EXISTS (
    SELECT 1 FROM dispatch_ticket ticket
    WHERE ticket.operation_id = OLD.id
      AND ticket.operation_kind = 'CAPTURE_TASK_REVIEW_SNAPSHOT'
      AND ticket.callback_route = 'TASK_REVIEW_SNAPSHOT_RESULT'
      AND ticket.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED'))
BEGIN
    SELECT RAISE(ABORT,
        'live initial Task review snapshot must be canceled before purge');
END;
CREATE TRIGGER task_review_snapshot_delete_ticket_v293
AFTER DELETE ON task_review_snapshot_operation_v286
BEGIN
    DELETE FROM dispatch_ticket
    WHERE operation_id = OLD.id
      AND operation_kind = 'CAPTURE_TASK_REVIEW_SNAPSHOT'
      AND callback_route = 'TASK_REVIEW_SNAPSHOT_RESULT'
      AND status IN ('SUCCEEDED', 'FAILED', 'CANCELED');
END;
CREATE TABLE review_session_purge_authorization_v293 (
    review_id         TEXT    NOT NULL PRIMARY KEY
        REFERENCES review_session(id) DEFERRABLE INITIALLY DEFERRED,
    workspace_id      TEXT    NOT NULL
        REFERENCES workspaces(id) DEFERRABLE INITIALLY DEFERRED,
    authorized_at_ms  INTEGER NOT NULL CHECK (authorized_at_ms > 0)
);
CREATE TRIGGER review_session_purge_authorization_insert_v293
BEFORE INSERT ON review_session_purge_authorization_v293
WHEN NOT EXISTS (
        SELECT 1 FROM review_session review
        WHERE review.id = NEW.review_id
          AND review.workspace_id = NEW.workspace_id
          AND review.owner_thread_id IS NULL
          AND review.owner_task_id IS NULL)
   OR EXISTS (
        SELECT 1
        FROM review_session_snapshot_operation_v293 operation
        JOIN dispatch_ticket ticket
          ON ticket.id = operation.dispatch_ticket_id
        WHERE operation.review_id = NEW.review_id
          AND ticket.status NOT IN (
              'SUCCEEDED', 'FAILED', 'CANCELED',
              'RESULT_PENDING', 'DELIVERING')
          AND NOT (ticket.status = 'CLAIMED'
              AND ticket.claim_purpose = 'DELIVER')
          AND ticket.cancel_requested_at_ms IS NULL)
   OR EXISTS (
        SELECT 1
        FROM review_assignment_turn turn
        JOIN review_assignment assignment ON assignment.id = turn.assignment_id
        JOIN review_round round ON round.id = assignment.round_id
        JOIN dispatch_ticket ticket
          ON ticket.owner_kind = 'REVIEW_ASSIGNMENT_TURN'
         AND ticket.owner_id = turn.id
         AND ticket.operation_id = turn.operation_id
         AND ticket.operation_kind = 'EXECUTE_REVIEW_ASSIGNMENT_TURN'
         AND ticket.callback_route = 'REVIEW_ASSIGNMENT_TURN_RESULT'
        WHERE round.session_id = NEW.review_id
          AND ticket.status NOT IN (
              'SUCCEEDED', 'FAILED', 'CANCELED',
              'RESULT_PENDING', 'DELIVERING')
          AND NOT (ticket.status = 'CLAIMED'
              AND ticket.claim_purpose = 'DELIVER')
          AND ticket.cancel_requested_at_ms IS NULL)
BEGIN
    SELECT RAISE(ABORT,
        'standalone ReviewSession purge requires exact canceled work');
END;
CREATE TRIGGER review_session_purge_authorization_update_v293
BEFORE UPDATE ON review_session_purge_authorization_v293
BEGIN
    SELECT RAISE(ABORT, 'ReviewSession purge authorization is immutable');
END;
CREATE TRIGGER review_session_standalone_delete_guard_v293
BEFORE DELETE ON review_session
WHEN OLD.workspace_id IS NOT NULL
  AND OLD.owner_thread_id IS NULL
  AND OLD.owner_task_id IS NULL
  AND (EXISTS (
          SELECT 1 FROM review_session_snapshot_operation_v293 operation
          WHERE operation.review_id = OLD.id)
    OR EXISTS (
          SELECT 1
          FROM review_assignment_turn turn
          JOIN review_assignment assignment ON assignment.id = turn.assignment_id
          JOIN review_round round ON round.id = assignment.round_id
          WHERE round.session_id = OLD.id))
  AND NOT EXISTS (
      SELECT 1 FROM review_session_purge_authorization_v293 authorization
      WHERE authorization.review_id = OLD.id
        AND authorization.workspace_id = OLD.workspace_id)
BEGIN
    SELECT RAISE(ABORT,
        'standalone ReviewSession typed work requires purge authorization');
END;
CREATE TRIGGER review_session_snapshot_delete_live_guard_v293
BEFORE DELETE ON review_session_snapshot_operation_v293
WHEN EXISTS (
    SELECT 1 FROM dispatch_ticket ticket
    WHERE ticket.id = OLD.dispatch_ticket_id
      AND ticket.status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED'))
  AND NOT EXISTS (
    SELECT 1
    FROM review_session_purge_authorization_v293 authorization
    WHERE authorization.review_id = OLD.review_id)
BEGIN
    SELECT RAISE(ABORT,
        'live ReviewSession snapshot must be canceled before purge');
END;
CREATE TABLE agent_execution_process_attempt (
    execution_id   TEXT    NOT NULL
        REFERENCES agent_execution(id) ON DELETE CASCADE,
    process_attempt INTEGER NOT NULL CHECK (process_attempt > 0),
    process_pid    INTEGER NOT NULL CHECK (process_pid > 0),
    log_ref        TEXT,
    PRIMARY KEY (execution_id, process_attempt),
    CHECK (log_ref IS NULL OR length(trim(log_ref)) > 0)
);
CREATE TRIGGER agent_execution_process_attempt_sequence
BEFORE INSERT ON agent_execution_process_attempt
WHEN NEW.process_attempt <> COALESCE((
    SELECT MAX(process_attempt)
    FROM agent_execution_process_attempt
    WHERE execution_id = NEW.execution_id), 0) + 1
BEGIN
    SELECT RAISE(ABORT, 'Agent execution process attempts must be sequential');
END;
CREATE TRIGGER agent_execution_process_attempt_immutable
BEFORE UPDATE ON agent_execution_process_attempt
BEGIN
    SELECT RAISE(ABORT, 'Agent execution process attempt is immutable');
END;
CREATE TABLE stage_plan_draft_retry_request_v297 (
    id                         TEXT    NOT NULL PRIMARY KEY,
    stage_id                   TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    task_id                    TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                 TEXT    NOT NULL,
    actor                      TEXT    NOT NULL,
    reason                     TEXT    NOT NULL,
    blocker_id                 TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    predecessor_turn_id        TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    replacement_turn_id        TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    replacement_ticket_id      TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    expected_task_epoch        INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_stage_generation  INTEGER NOT NULL CHECK (expected_stage_generation > 0),
    expected_stage_version     INTEGER NOT NULL CHECK (expected_stage_version > 0),
    returned_stage_version     INTEGER NOT NULL,
    subject_operation_id       TEXT    NOT NULL UNIQUE,
    subject_attempt            INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_code_fingerprint   TEXT    NOT NULL,
    subject_head_sha           TEXT    NOT NULL,
    subject_base_sha           TEXT    NOT NULL,
    pending_operation_id       TEXT    NOT NULL UNIQUE,
    pending_attempt            INTEGER NOT NULL CHECK (pending_attempt > 0),
    pending_code_fingerprint   TEXT    NOT NULL,
    pending_head_sha           TEXT    NOT NULL,
    pending_base_sha           TEXT    NOT NULL,
    requested_at_ms            INTEGER NOT NULL,
    UNIQUE (stage_id, command_id),
    CHECK (length(trim(command_id)) > 0
        AND length(trim(actor)) > 0
        AND length(trim(reason)) > 0),
    CHECK (returned_stage_version = expected_stage_version + 1)
);
CREATE TRIGGER stage_plan_draft_retry_request_v297_insert
BEFORE INSERT ON stage_plan_draft_retry_request_v297
WHEN NOT EXISTS (
    SELECT 1
    FROM stage plan_stage
    JOIN tasks task ON task.id = plan_stage.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN task_blocker blocker ON blocker.id = NEW.blocker_id
    JOIN task_turn predecessor ON predecessor.id = NEW.predecessor_turn_id
    JOIN stage_plan_terminal_result terminal
      ON terminal.stage_id = plan_stage.id
     AND terminal.proof_id = predecessor.id
     AND terminal.subject_operation_id = predecessor.operation_id
    JOIN task_turn replacement ON replacement.id = NEW.replacement_turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.replacement_ticket_id
    JOIN stage_transition transition
      ON transition.stage_id = plan_stage.id
     AND transition.command_id = NEW.command_id
    WHERE plan_stage.id = NEW.stage_id
      AND plan_stage.task_id = NEW.task_id
      AND plan_stage.kind = 'PLAN'
      AND plan_stage.generation = NEW.expected_stage_generation
      AND plan_stage.version = NEW.returned_stage_version
      AND plan_stage.checkpoint = 'DRAFTING'
      AND plan_stage.completed_at_ms IS NULL
      AND plan_stage.end_reason IS NULL
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.expected_task_epoch
      AND current.stage_id = plan_stage.id
      AND current.stage_generation = plan_stage.generation
      AND blocker.task_id = task.id
      AND blocker.stage_id = plan_stage.id
      AND blocker.owner_kind = 'STAGE'
      AND blocker.owner_id = plan_stage.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND (blocker.subject_revision = predecessor.id
        OR blocker.subject_revision IS NULL)
      AND 1 = (
          SELECT COUNT(*)
          FROM task_blocker open_failure
          WHERE open_failure.task_id = task.id
            AND open_failure.stage_id = plan_stage.id
            AND open_failure.owner_kind = 'STAGE'
            AND open_failure.owner_id = plan_stage.id
            AND open_failure.blocker_type = 'OPERATION_FAILED'
            AND open_failure.status = 'OPEN')
      AND predecessor.task_id = task.id
      AND predecessor.task_epoch = task.epoch
      AND predecessor.trigger_stage_id = plan_stage.id
      AND predecessor.trigger_stage_generation = plan_stage.generation
      AND predecessor.purpose = 'PLAN_DRAFT'
      AND predecessor.status = 'FAILED'
      AND predecessor.operation_id = NEW.subject_operation_id
      AND predecessor.attempt = NEW.subject_attempt
      AND predecessor.expected_code_fingerprint =
          NEW.subject_code_fingerprint
      AND predecessor.expected_head_sha = NEW.subject_head_sha
      AND predecessor.expected_base_sha = NEW.subject_base_sha
      AND terminal.cause = 'PLAN_DRAFT_FAILED'
      AND terminal.checkpoint = 'DRAFTING'
      AND terminal.returned_stage_version = NEW.expected_stage_version
      AND terminal.subject_task_epoch = NEW.expected_task_epoch
      AND terminal.subject_stage_generation =
          NEW.expected_stage_generation
      AND terminal.subject_attempt = NEW.subject_attempt
      AND terminal.subject_code_fingerprint =
          NEW.subject_code_fingerprint
      AND terminal.subject_head_sha = NEW.subject_head_sha
      AND terminal.subject_base_sha = NEW.subject_base_sha
      AND replacement.task_id = task.id
      AND replacement.task_epoch = task.epoch
      AND replacement.trigger_stage_id = plan_stage.id
      AND replacement.trigger_stage_generation = plan_stage.generation
      AND replacement.purpose = 'PLAN_DRAFT'
      AND replacement.status = 'REQUESTED'
      AND replacement.operation_id = NEW.pending_operation_id
      AND replacement.attempt = NEW.pending_attempt
      AND replacement.expected_code_fingerprint =
          NEW.pending_code_fingerprint
      AND replacement.expected_head_sha = NEW.pending_head_sha
      AND replacement.expected_base_sha = NEW.pending_base_sha
      AND json_type(replacement.launch_input, '$.resumeSessionId') IS NULL
      AND json_extract(replacement.launch_input, '$.prompt') =
          COALESCE(
              json_extract(predecessor.launch_input, '$.fallbackPrompt'),
              json_extract(predecessor.launch_input, '$.prompt'))
      AND ticket.operation_id = replacement.operation_id
      AND ticket.owner_kind = 'TASK_TURN'
      AND ticket.owner_id = replacement.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
      AND ticket.async_family = 'AGENT_TURN'
      AND ticket.status = 'REQUESTED'
      AND transition.generation = plan_stage.generation
      AND transition.from_checkpoint = 'DRAFTING'
      AND transition.to_checkpoint = 'DRAFTING'
      AND transition.stage_version = plan_stage.version
      AND transition.cause = 'RETRY_PLAN_DRAFT'
      AND transition.actor = NEW.actor)
BEGIN
    SELECT RAISE(ABORT, 'Plan draft retry request is not exact');
END;
CREATE TRIGGER stage_plan_draft_retry_request_v297_immutable
BEFORE UPDATE ON stage_plan_draft_retry_request_v297
BEGIN
    SELECT RAISE(ABORT, 'Plan draft retry request is immutable');
END;
CREATE TABLE local_stage_turn_failure_v298 (
    id                    TEXT    NOT NULL PRIMARY KEY,
    stage_turn_id         TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    operation_id          TEXT    NOT NULL UNIQUE,
    task_id               TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    stage_id              TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation      INTEGER NOT NULL CHECK (stage_generation > 0),
    blocker_id            TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    error_message         TEXT    NOT NULL CHECK (length(trim(error_message)) > 0),
    payload_json          TEXT    NOT NULL CHECK (json_valid(payload_json)),
    cleared_stage_version INTEGER NOT NULL CHECK (cleared_stage_version > 0),
    recorded_at_ms        INTEGER NOT NULL CHECK (recorded_at_ms >= 0)
);
CREATE TRIGGER local_stage_turn_failure_v298_immutable
BEFORE UPDATE ON local_stage_turn_failure_v298
BEGIN
    SELECT RAISE(ABORT, 'Local StageTurn failure is immutable');
END;
CREATE TABLE local_stage_turn_retry_v298 (
    id                     TEXT    NOT NULL PRIMARY KEY,
    task_id                TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    stage_id               TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation       INTEGER NOT NULL CHECK (stage_generation > 0),
    command_id             TEXT    NOT NULL,
    actor                  TEXT    NOT NULL CHECK (length(trim(actor)) > 0),
    reason                 TEXT    NOT NULL CHECK (length(trim(reason)) > 0),
    blocker_id             TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    failure_id             TEXT    NOT NULL UNIQUE
        REFERENCES local_stage_turn_failure_v298(id),
    predecessor_turn_id    TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    replacement_request_id TEXT    NOT NULL UNIQUE
        REFERENCES local_stage_turn_request(id),
    replacement_turn_id    TEXT    NOT NULL UNIQUE REFERENCES stage_turn(id),
    replacement_ticket_id  TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    expected_stage_version INTEGER NOT NULL CHECK (expected_stage_version > 0),
    returned_stage_version INTEGER NOT NULL,
    recorded_at_ms         INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (stage_id, command_id),
    CHECK (returned_stage_version = expected_stage_version + 1)
);
CREATE TRIGGER local_stage_turn_retry_v298_insert
BEFORE INSERT ON local_stage_turn_retry_v298
WHEN NOT EXISTS (
    SELECT 1
    FROM local_stage_turn_failure_v298 failure
    JOIN task_blocker blocker ON blocker.id = NEW.blocker_id
    JOIN stage_turn previous ON previous.id = NEW.predecessor_turn_id
    JOIN local_stage_turn_request previous_request
      ON previous_request.stage_turn_id = previous.id
    JOIN stage_turn replacement ON replacement.id = NEW.replacement_turn_id
    JOIN local_stage_turn_request replacement_request
      ON replacement_request.id = NEW.replacement_request_id
     AND replacement_request.stage_turn_id = replacement.id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.replacement_ticket_id
    JOIN stage owner ON owner.id = NEW.stage_id
    JOIN tasks task ON task.id = owner.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN local_stage_command_receipt admission
      ON admission.stage_id = owner.id
     AND admission.command_id = NEW.command_id
    WHERE failure.id = NEW.failure_id
      AND failure.task_id = NEW.task_id
      AND failure.stage_id = NEW.stage_id
      AND failure.stage_generation = NEW.stage_generation
      AND failure.stage_turn_id = previous.id
      AND failure.operation_id = previous.operation_id
      AND failure.blocker_id = blocker.id
      AND failure.cleared_stage_version = NEW.expected_stage_version
      AND blocker.task_id = task.id
      AND blocker.stage_id = owner.id
      AND blocker.owner_kind = 'STAGE'
      AND blocker.owner_id = owner.id
      AND blocker.subject_revision = previous.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND previous.status = 'FAILED'
      AND previous.stage_id = owner.id
      AND previous.stage_generation = owner.generation
      AND previous.task_epoch = task.epoch
      AND replacement.stage_id = previous.stage_id
      AND replacement.stage_generation = previous.stage_generation
      AND replacement.task_epoch = previous.task_epoch
      AND replacement.purpose = previous.purpose
      AND replacement.status = 'QUEUED'
      AND replacement.attempt = previous.attempt + 1
      AND replacement.expected_code_fingerprint =
          previous.expected_code_fingerprint
      AND replacement.expected_head_sha = previous.expected_head_sha
      AND replacement.expected_base_sha = previous.expected_base_sha
      AND json_type(replacement.launch_input, '$.resumeSessionId') IS NULL
      AND json_type(replacement.launch_input, '$.fallbackPrompt') IS NULL
      AND json_type(replacement.launch_input,
          '$.priorCumulativeInputTokens') IS NULL
      AND json_type(replacement.launch_input,
          '$.priorCumulativeOutputTokens') IS NULL
      AND instr(json_extract(replacement.launch_input, '$.prompt'),
          COALESCE(json_extract(previous.launch_input, '$.fallbackPrompt'),
                   json_extract(previous.launch_input, '$.prompt'))) = 1
      AND json_extract(replacement.launch_input,
          '$.toolEndpoint.ownerKind') = 'STAGE_TURN'
      AND json_extract(replacement.launch_input,
          '$.toolEndpoint.ownerId') = replacement.id
      AND json_extract(replacement.launch_input,
          '$.toolEndpoint.operationId') = replacement.operation_id
      AND previous_request.task_id = task.id
      AND previous_request.local_development_stage_id = owner.id
      AND replacement_request.task_id = task.id
      AND replacement_request.local_development_stage_id = owner.id
      AND replacement_request.task_epoch = task.epoch
      AND replacement_request.stage_generation = owner.generation
      AND replacement_request.kind = previous_request.kind
      AND replacement_request.queue_mode = 'IMMEDIATE'
      AND replacement_request.predecessor_turn_id IS NULL
      AND replacement_request.brain_review_episode_id
          IS previous_request.brain_review_episode_id
      AND replacement_request.local_feedback_batch_id
          IS previous_request.local_feedback_batch_id
      AND replacement_request.requested_by = NEW.actor
      AND ticket.operation_id = replacement.operation_id
      AND ticket.owner_kind = 'STAGE_TURN'
      AND ticket.owner_id = replacement.id
      AND ticket.callback_route = 'STAGE_TURN_RESULT'
      AND ticket.operation_kind = 'EXECUTE_STAGE_TURN'
      AND ticket.async_family = 'AGENT_TURN'
      AND ticket.task_id = task.id
      AND ticket.task_epoch = task.epoch
      AND ticket.stage_id = owner.id
      AND ticket.stage_generation = owner.generation
      AND ticket.attempt = replacement.attempt
      AND ticket.status = 'REQUESTED'
      AND owner.task_id = NEW.task_id
      AND owner.kind = 'LOCAL_DEVELOPMENT'
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.returned_stage_version
      AND owner.completed_at_ms IS NULL
      AND owner.end_reason IS NULL
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND current.stage_id = owner.id
      AND current.stage_generation = owner.generation
      AND admission.task_id = task.id
      AND admission.cause = 'REQUEST_LOCAL_RESULT'
      AND admission.actor = NEW.actor
      AND admission.disposition = 'APPLIED'
      AND admission.expected_task_epoch = task.epoch
      AND admission.expected_stage_generation = owner.generation
      AND admission.expected_stage_version = NEW.expected_stage_version
      AND admission.returned_version = NEW.returned_stage_version
      AND admission.returned_checkpoint = owner.checkpoint
      AND admission.subject_operation_id = replacement.operation_id
      AND admission.proof_id = replacement_request.id
      AND admission.returned_pending_operation_id = replacement.operation_id)
BEGIN
    SELECT RAISE(ABORT, 'Local StageTurn retry is not exact');
END;
CREATE TRIGGER local_stage_turn_retry_v298_immutable
BEFORE UPDATE ON local_stage_turn_retry_v298
BEGIN
    SELECT RAISE(ABORT, 'Local StageTurn retry is immutable');
END;
CREATE TRIGGER local_stage_turn_failure_v298_insert
BEFORE INSERT ON local_stage_turn_failure_v298
WHEN NOT EXISTS (
    SELECT 1
    FROM stage_turn turn
    JOIN local_stage_turn_request request
      ON request.stage_turn_id = turn.id
    JOIN dispatch_ticket ticket
      ON ticket.operation_id = turn.operation_id
     AND ticket.owner_kind = 'STAGE_TURN'
     AND ticket.owner_id = turn.id
     AND ticket.callback_route = 'STAGE_TURN_RESULT'
    JOIN stage owner ON owner.id = turn.stage_id
    JOIN tasks task ON task.id = owner.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN task_blocker blocker ON blocker.id = NEW.blocker_id
    JOIN local_stage_command_receipt cleared
      ON cleared.stage_id = owner.id
     AND cleared.cause = 'CLEAR_LOCAL_RESULT'
     AND cleared.disposition = 'APPLIED'
     AND cleared.subject_operation_id = turn.operation_id
    WHERE turn.id = NEW.stage_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.status = 'FAILED'
      AND request.task_id = NEW.task_id
      AND request.local_development_stage_id = NEW.stage_id
      AND request.task_epoch = turn.task_epoch
      AND request.stage_generation = NEW.stage_generation
      AND ticket.task_id = task.id
      AND ticket.task_epoch = task.epoch
      AND ticket.stage_id = owner.id
      AND ticket.stage_generation = owner.generation
      AND ticket.attempt = turn.attempt
      AND ((ticket.status = 'RESULT_PENDING'
            AND ticket.pending_result_outcome IN ('FAILED', 'INDETERMINATE'))
        OR (ticket.status = 'FAILED'
            AND ticket.delivery_acceptance = 'ACCEPTED'
            AND EXISTS (
                SELECT 1
                FROM local_stage_turn_delivery_receipt delivery
                WHERE delivery.stage_turn_id = turn.id
                  AND delivery.operation_id = turn.operation_id
                  AND delivery.acceptance = 'ACCEPTED'
                  AND delivery.raw_outcome IN ('FAILED', 'INDETERMINATE'))))
      AND owner.id = NEW.stage_id
      AND owner.kind = 'LOCAL_DEVELOPMENT'
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.cleared_stage_version
      AND owner.completed_at_ms IS NULL
      AND owner.end_reason IS NULL
      AND task.id = NEW.task_id
      AND task.workflow_version = 'V2'
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = turn.task_epoch
      AND current.stage_id = owner.id
      AND current.stage_generation = owner.generation
      AND blocker.task_id = task.id
      AND blocker.stage_id = owner.id
      AND blocker.owner_kind = 'STAGE'
      AND blocker.owner_id = owner.id
      AND blocker.subject_revision = turn.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND cleared.task_id = task.id
      AND cleared.returned_generation = owner.generation
      AND cleared.returned_version = owner.version
      AND cleared.returned_checkpoint = owner.checkpoint
      AND cleared.returned_pending_operation_id IS NULL)
BEGIN
    SELECT RAISE(ABORT, 'Local StageTurn failure is not exact');
END;
CREATE UNIQUE INDEX task_blocker_one_open_stage_operation_failure_v299
    ON task_blocker(task_id, stage_id)
    WHERE owner_kind = 'STAGE'
      AND blocker_type = 'OPERATION_FAILED'
      AND status = 'OPEN';
CREATE TRIGGER local_stage_turn_request_failure_gate_v299
BEFORE INSERT ON local_stage_turn_request
WHEN EXISTS (
    SELECT 1 FROM task_blocker blocker
    WHERE blocker.task_id = NEW.task_id
      AND blocker.stage_id = NEW.local_development_stage_id
      AND blocker.owner_kind = 'STAGE'
      AND blocker.owner_id = NEW.local_development_stage_id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN')
  AND NOT EXISTS (
    SELECT 1
    FROM local_stage_turn_failure_v298 failure
    JOIN task_blocker blocker ON blocker.id = failure.blocker_id
    JOIN stage_turn previous ON previous.id = failure.stage_turn_id
    JOIN local_stage_turn_request previous_request
      ON previous_request.stage_turn_id = previous.id
    JOIN stage_turn replacement ON replacement.id = NEW.stage_turn_id
    WHERE failure.task_id = NEW.task_id
      AND failure.stage_id = NEW.local_development_stage_id
      AND failure.stage_generation = NEW.stage_generation
      AND blocker.task_id = NEW.task_id
      AND blocker.stage_id = NEW.local_development_stage_id
      AND blocker.owner_kind = 'STAGE'
      AND blocker.owner_id = NEW.local_development_stage_id
      AND blocker.subject_revision = previous.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND previous.status = 'FAILED'
      AND replacement.stage_id = previous.stage_id
      AND replacement.stage_generation = previous.stage_generation
      AND replacement.task_epoch = previous.task_epoch
      AND replacement.purpose = previous.purpose
      AND replacement.status = 'QUEUED'
      AND replacement.attempt = previous.attempt + 1
      AND replacement.expected_code_fingerprint
          = previous.expected_code_fingerprint
      AND replacement.expected_head_sha = previous.expected_head_sha
      AND replacement.expected_base_sha = previous.expected_base_sha
      AND NEW.kind = previous_request.kind
      AND NEW.queue_mode = 'IMMEDIATE'
      AND NEW.predecessor_turn_id IS NULL
      AND NEW.brain_review_episode_id
          IS previous_request.brain_review_episode_id
      AND NEW.local_feedback_batch_id
          IS previous_request.local_feedback_batch_id
      AND NOT EXISTS (
          SELECT 1 FROM local_stage_turn_retry_v298 retry
          WHERE retry.failure_id = failure.id
             OR retry.blocker_id = blocker.id
             OR retry.predecessor_turn_id = previous.id))
BEGIN
    SELECT RAISE(ABORT,
        'Local StageTurn admission requires exact failure recovery');
END;
CREATE UNIQUE INDEX task_blocker_one_open_task_operation_failure_v300
    ON task_blocker(task_id)
    WHERE owner_kind = 'TASK'
      AND blocker_type = 'OPERATION_FAILED'
      AND status = 'OPEN';
CREATE TABLE task_brain_protocol_failure_receipt_v300 (
    id                                TEXT    NOT NULL PRIMARY KEY,
    task_id                           TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id                        TEXT    NOT NULL,
    cause                             TEXT    NOT NULL CHECK (cause = 'ACCEPT_BRAIN_PROTOCOL_FAILURE'),
    actor                             TEXT    NOT NULL CHECK (length(trim(actor)) > 0),
    disposition                       TEXT    NOT NULL CHECK (disposition = 'APPLIED'),
    expected_task_epoch               INTEGER,
    expected_task_version             INTEGER,
    subject_task_epoch                INTEGER NOT NULL CHECK (subject_task_epoch > 0),
    subject_stage_id                  TEXT    NOT NULL,
    subject_stage_generation          INTEGER NOT NULL CHECK (subject_stage_generation > 0),
    subject_operation_id              TEXT    NOT NULL CHECK (length(subject_operation_id) > 0),
    subject_attempt                   INTEGER NOT NULL CHECK (subject_attempt > 0),
    subject_expected_code_fingerprint TEXT    NOT NULL,
    subject_expected_head_sha         TEXT    NOT NULL,
    subject_expected_base_sha         TEXT    NOT NULL,
    brain_verdict                     TEXT,
    proof_id                          TEXT    NOT NULL REFERENCES task_blocker(id),
    next_stage_id                     TEXT,
    next_stage_kind                   TEXT,
    next_stage_generation             INTEGER,
    returned_trunk_id                 TEXT    NOT NULL REFERENCES threads(id),
    returned_lifecycle                TEXT    NOT NULL CHECK (returned_lifecycle = 'ACTIVE'),
    returned_epoch                    INTEGER NOT NULL CHECK (returned_epoch > 0),
    returned_version                  INTEGER NOT NULL CHECK (returned_version > 0),
    returned_current_stage_id         TEXT    NOT NULL,
    returned_pending_task_epoch       INTEGER,
    returned_pending_stage_id         TEXT,
    returned_pending_stage_generation INTEGER,
    returned_pending_operation_id     TEXT,
    returned_pending_attempt          INTEGER,
    returned_pending_code_fingerprint TEXT,
    returned_pending_head_sha         TEXT,
    returned_pending_base_sha         TEXT,
    returned_last_brain_verdict       TEXT CHECK (returned_last_brain_verdict IN (
        'APPROVED', 'CHANGES_REQUESTED')),
    returned_last_brain_task_epoch    INTEGER,
    returned_last_brain_stage_id      TEXT,
    returned_last_brain_stage_generation INTEGER,
    returned_last_brain_operation_id  TEXT,
    returned_last_brain_attempt       INTEGER,
    returned_last_brain_code_fingerprint TEXT,
    returned_last_brain_head_sha      TEXT,
    returned_last_brain_base_sha      TEXT,
    returned_terminal_intent          TEXT,
    recorded_at_ms                    INTEGER NOT NULL CHECK (recorded_at_ms >= 0),
    UNIQUE (task_id, command_id),
    CHECK (expected_task_epoch IS NULL AND expected_task_version IS NULL),
    CHECK (brain_verdict IS NULL AND next_stage_id IS NULL
        AND next_stage_kind IS NULL AND next_stage_generation IS NULL),
    CHECK (returned_terminal_intent IS NULL),
    CHECK (returned_epoch = subject_task_epoch),
    CHECK (returned_current_stage_id = subject_stage_id),
    CHECK (returned_pending_operation_id IS NULL
        AND returned_pending_task_epoch IS NULL
        AND returned_pending_stage_id IS NULL
        AND returned_pending_stage_generation IS NULL
        AND returned_pending_attempt IS NULL
        AND returned_pending_code_fingerprint IS NULL
        AND returned_pending_head_sha IS NULL
        AND returned_pending_base_sha IS NULL),
    CHECK ((returned_last_brain_operation_id IS NULL
            AND returned_last_brain_verdict IS NULL
            AND returned_last_brain_task_epoch IS NULL
            AND returned_last_brain_stage_id IS NULL
            AND returned_last_brain_stage_generation IS NULL
            AND returned_last_brain_attempt IS NULL
            AND returned_last_brain_code_fingerprint IS NULL
            AND returned_last_brain_head_sha IS NULL
            AND returned_last_brain_base_sha IS NULL)
        OR (returned_last_brain_operation_id IS NOT NULL
            AND length(returned_last_brain_operation_id) > 0
            AND returned_last_brain_verdict IS NOT NULL
            AND returned_last_brain_task_epoch IS NOT NULL
            AND returned_last_brain_stage_id IS NOT NULL
            AND returned_last_brain_stage_generation > 0
            AND returned_last_brain_attempt > 0))
);
CREATE TRIGGER task_brain_protocol_failure_receipt_insert_v300
BEFORE INSERT ON task_brain_protocol_failure_receipt_v300
WHEN NOT EXISTS (
    SELECT 1
    FROM task_transition transition
    JOIN tasks task ON task.id = NEW.task_id
    JOIN task_current_stage current ON current.task_id = task.id
    JOIN stage owner ON owner.id = current.stage_id
    JOIN task_blocker blocker ON blocker.id = NEW.proof_id
    JOIN task_turn delivered ON delivered.id = blocker.subject_revision
    LEFT JOIN task_turn_user_wait_continuation_v266 continuation
      ON continuation.successor_turn_id = delivered.id
    JOIN task_turn logical ON logical.id = COALESCE(
        continuation.logical_turn_id, delivered.id)
    JOIN brain_review_episode episode
      ON episode.task_id = task.id
     AND episode.task_turn_id = logical.id
    WHERE transition.task_id = task.id
      AND transition.command_id = NEW.command_id
      AND transition.cause = NEW.cause
      AND transition.actor = NEW.actor
      AND transition.aggregate_version = NEW.returned_version
      AND task.workflow_version = 'V2'
      AND task.thread_id = NEW.returned_trunk_id
      AND task.lifecycle_state = 'ACTIVE'
      AND task.epoch = NEW.subject_task_epoch
      AND task.aggregate_version = NEW.returned_version
      AND current.stage_id = NEW.subject_stage_id
      AND current.stage_generation = NEW.subject_stage_generation
      AND owner.kind = 'LOCAL_DEVELOPMENT'
      AND owner.checkpoint = 'BRAIN_REVIEW'
      AND owner.completed_at_ms IS NULL
      AND blocker.task_id = task.id
      AND blocker.stage_id IS NULL
      AND blocker.owner_kind = 'TASK'
      AND blocker.owner_id = task.id
      AND blocker.subject_revision = delivered.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND episode.status = 'FAILED'
      AND episode.local_development_stage_id = owner.id
      AND episode.stage_generation = owner.generation
      AND logical.operation_id = NEW.subject_operation_id
      AND logical.attempt = NEW.subject_attempt
      AND logical.expected_code_fingerprint =
          NEW.subject_expected_code_fingerprint
      AND logical.expected_head_sha = NEW.subject_expected_head_sha
      AND logical.expected_base_sha = NEW.subject_expected_base_sha
      AND delivered.task_id = task.id
      AND delivered.task_epoch = task.epoch
      AND delivered.trigger_stage_id = owner.id
      AND delivered.trigger_stage_generation = owner.generation
      AND delivered.purpose = 'DEVELOPMENT_BRAIN_REVIEW'
      AND delivered.status = 'FAILED'
      AND delivered.expected_code_fingerprint =
          NEW.subject_expected_code_fingerprint
      AND delivered.expected_head_sha = NEW.subject_expected_head_sha
      AND delivered.expected_base_sha = NEW.subject_expected_base_sha)
BEGIN SELECT RAISE(ABORT, 'Brain protocol failure Task receipt is not exact'); END;
CREATE TRIGGER task_brain_protocol_failure_receipt_immutable_v300
BEFORE UPDATE ON task_brain_protocol_failure_receipt_v300
BEGIN SELECT RAISE(ABORT, 'Brain protocol failure Task receipt is immutable'); END;
CREATE TABLE development_brain_protocol_failure_v300 (
    id                       TEXT    NOT NULL PRIMARY KEY,
    task_turn_id             TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    operation_id             TEXT    NOT NULL UNIQUE,
    brain_review_episode_id  TEXT    NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    owner_turn_id            TEXT    NOT NULL REFERENCES task_turn(id),
    owner_operation_id       TEXT    NOT NULL,
    owner_attempt            INTEGER NOT NULL CHECK (owner_attempt > 0),
    task_id                  TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch               INTEGER NOT NULL CHECK (task_epoch > 0),
    stage_id                 TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation         INTEGER NOT NULL CHECK (stage_generation > 0),
    stage_version            INTEGER NOT NULL CHECK (stage_version >= 0),
    code_fingerprint         TEXT    NOT NULL,
    head_sha                 TEXT    NOT NULL,
    base_sha                 TEXT    NOT NULL,
    blocker_id               TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    raw_outcome              TEXT    NOT NULL CHECK (raw_outcome = 'SUCCEEDED'),
    raw_result_digest        TEXT    NOT NULL CHECK (length(raw_result_digest) = 64),
    error_message            TEXT    NOT NULL CHECK (length(trim(error_message)) > 0),
    cleared_task_version     INTEGER NOT NULL CHECK (cleared_task_version > 0),
    recorded_at_ms           INTEGER NOT NULL CHECK (recorded_at_ms >= 0)
);
CREATE TRIGGER development_brain_protocol_failure_insert_v300
BEFORE INSERT ON development_brain_protocol_failure_v300
WHEN NOT EXISTS (
    SELECT 1
    FROM brain_review_episode episode
    JOIN task_turn owner_turn ON owner_turn.id = episode.task_turn_id
    JOIN task_turn turn ON turn.id = NEW.task_turn_id
    LEFT JOIN task_turn_user_wait_continuation_v266 continuation
      ON continuation.successor_turn_id = turn.id
    JOIN dispatch_ticket ticket
      ON ticket.operation_id = turn.operation_id
     AND ticket.owner_kind = 'TASK_TURN'
     AND ticket.owner_id = turn.id
     AND ticket.callback_route = 'TASK_TURN_RESULT'
    JOIN task_blocker blocker ON blocker.id = NEW.blocker_id
    JOIN task_brain_protocol_failure_receipt_v300 receipt
      ON receipt.task_id = episode.task_id
     AND receipt.proof_id = blocker.id
     AND receipt.subject_operation_id = owner_turn.operation_id
    JOIN stage owner ON owner.id = episode.local_development_stage_id
    WHERE episode.id = NEW.brain_review_episode_id
      AND episode.task_id = NEW.task_id
      AND episode.task_epoch = NEW.task_epoch
      AND episode.local_development_stage_id = NEW.stage_id
      AND episode.stage_generation = NEW.stage_generation
      AND episode.status = 'FAILED'
      AND owner_turn.id = NEW.owner_turn_id
      AND owner_turn.id = COALESCE(continuation.logical_turn_id, turn.id)
      AND owner_turn.operation_id = NEW.owner_operation_id
      AND owner_turn.attempt = NEW.owner_attempt
      AND turn.id = NEW.task_turn_id
      AND turn.operation_id = NEW.operation_id
      AND turn.status = 'FAILED'
      AND ticket.status = 'RESULT_PENDING'
      AND ticket.pending_result_outcome = 'SUCCEEDED'
      AND ticket.pending_result_task_epoch = turn.task_epoch
      AND ticket.pending_result_stage_id = turn.trigger_stage_id
      AND ticket.pending_result_stage_generation =
          turn.trigger_stage_generation
      AND ticket.pending_result_operation_id = turn.operation_id
      AND ticket.pending_result_attempt = turn.attempt
      AND ticket.pending_result_expected_code_fingerprint =
          turn.expected_code_fingerprint
      AND ticket.pending_result_expected_head_sha = turn.expected_head_sha
      AND ticket.pending_result_expected_base_sha = turn.expected_base_sha
      AND turn.expected_code_fingerprint = NEW.code_fingerprint
      AND turn.expected_head_sha = NEW.head_sha
      AND turn.expected_base_sha = NEW.base_sha
      AND blocker.task_id = NEW.task_id
      AND blocker.owner_kind = 'TASK'
      AND blocker.owner_id = NEW.task_id
      AND blocker.stage_id IS NULL
      AND blocker.subject_revision = turn.id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND receipt.subject_attempt = NEW.owner_attempt
      AND receipt.returned_version = NEW.cleared_task_version
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.stage_version
      AND owner.checkpoint = 'BRAIN_REVIEW')
BEGIN SELECT RAISE(ABORT, 'Brain protocol failure delivery is not exact'); END;
CREATE TRIGGER development_brain_protocol_failure_immutable_v300
BEFORE UPDATE ON development_brain_protocol_failure_v300
BEGIN SELECT RAISE(ABORT, 'Brain protocol failure delivery is immutable'); END;
CREATE TABLE development_brain_retry_budget_lineage_v300 (
    predecessor_episode_id TEXT    NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    successor_episode_id   TEXT    NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    execution_attempt      INTEGER NOT NULL CHECK (execution_attempt > 1),
    budget_attempt         INTEGER NOT NULL CHECK (budget_attempt > 0),
    consumes_budget        INTEGER NOT NULL CHECK (consumes_budget = 0),
    recorded_at_ms         INTEGER NOT NULL,
    PRIMARY KEY (predecessor_episode_id, successor_episode_id)
);
CREATE TRIGGER development_brain_retry_budget_lineage_insert_v300
BEFORE INSERT ON development_brain_retry_budget_lineage_v300
WHEN NOT EXISTS (
    SELECT 1
    FROM brain_review_episode predecessor
    JOIN brain_review_episode successor
      ON successor.id = NEW.successor_episode_id
    WHERE predecessor.id = NEW.predecessor_episode_id
      AND predecessor.status = 'FAILED'
      AND successor.status = 'REQUESTED'
      AND successor.task_brain_id = predecessor.task_brain_id
      AND successor.task_id = predecessor.task_id
      AND successor.task_epoch = predecessor.task_epoch
      AND successor.local_development_stage_id = predecessor.local_development_stage_id
      AND successor.stage_generation = predecessor.stage_generation
      AND successor.dev_report_id = predecessor.dev_report_id
      AND successor.validation_evidence_id = predecessor.validation_evidence_id
      AND successor.code_fingerprint = predecessor.code_fingerprint
      AND successor.expected_head_sha = predecessor.expected_head_sha
      AND successor.expected_base_sha = predecessor.expected_base_sha
      AND successor.semantic_attempt = predecessor.semantic_attempt + 1
      AND NEW.execution_attempt = successor.semantic_attempt
      AND NEW.budget_attempt = COALESCE((
          SELECT prior.budget_attempt
          FROM development_brain_retry_budget_lineage_v300 prior
          WHERE prior.successor_episode_id = predecessor.id),
          predecessor.semantic_attempt))
BEGIN SELECT RAISE(ABORT, 'Brain protocol retry budget lineage is not exact'); END;
CREATE TRIGGER development_brain_retry_budget_lineage_immutable_v300
BEFORE UPDATE ON development_brain_retry_budget_lineage_v300
BEGIN SELECT RAISE(ABORT, 'Brain protocol retry budget lineage is immutable'); END;
CREATE TABLE development_brain_retry_v300 (
    id                       TEXT    NOT NULL PRIMARY KEY,
    task_id                  TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    command_id               TEXT    NOT NULL,
    task_request_command_id  TEXT    NOT NULL UNIQUE,
    actor                    TEXT    NOT NULL,
    reason                   TEXT    NOT NULL,
    failure_id               TEXT    NOT NULL UNIQUE REFERENCES development_brain_protocol_failure_v300(id),
    blocker_id               TEXT    NOT NULL UNIQUE REFERENCES task_blocker(id),
    predecessor_episode_id   TEXT    NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    predecessor_turn_id      TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    replacement_episode_id   TEXT    NOT NULL UNIQUE REFERENCES brain_review_episode(id),
    replacement_turn_id      TEXT    NOT NULL UNIQUE REFERENCES task_turn(id),
    replacement_operation_id TEXT    NOT NULL UNIQUE,
    replacement_ticket_id    TEXT    NOT NULL UNIQUE REFERENCES dispatch_ticket(id),
    expected_task_epoch      INTEGER NOT NULL CHECK (expected_task_epoch > 0),
    expected_task_version    INTEGER NOT NULL CHECK (expected_task_version >= 0),
    returned_task_version    INTEGER NOT NULL,
    stage_id                 TEXT    NOT NULL REFERENCES stage(id) ON DELETE CASCADE,
    stage_generation         INTEGER NOT NULL CHECK (stage_generation > 0),
    stage_version            INTEGER NOT NULL CHECK (stage_version >= 0),
    code_fingerprint         TEXT    NOT NULL,
    head_sha                 TEXT    NOT NULL,
    base_sha                 TEXT    NOT NULL,
    execution_attempt        INTEGER NOT NULL CHECK (execution_attempt > 1),
    budget_attempt           INTEGER NOT NULL CHECK (budget_attempt > 0),
    recorded_at_ms           INTEGER NOT NULL,
    UNIQUE (task_id, command_id),
    CHECK (length(trim(actor)) > 0 AND length(trim(reason)) > 0),
    CHECK (returned_task_version = expected_task_version + 1)
);
CREATE TRIGGER development_brain_retry_insert_v300
BEFORE INSERT ON development_brain_retry_v300
WHEN NOT EXISTS (
    SELECT 1
    FROM development_brain_protocol_failure_v300 failure
    JOIN task_blocker blocker ON blocker.id = failure.blocker_id
    JOIN brain_review_episode predecessor ON predecessor.id = failure.brain_review_episode_id
    JOIN task_turn failed ON failed.id = failure.task_turn_id
    JOIN dispatch_ticket failed_ticket
      ON failed_ticket.operation_id = failed.operation_id
     AND failed_ticket.owner_kind = 'TASK_TURN'
     AND failed_ticket.owner_id = failed.id
    JOIN brain_review_episode replacement ON replacement.id = NEW.replacement_episode_id
    JOIN task_turn turn ON turn.id = replacement.task_turn_id
    JOIN dispatch_ticket ticket ON ticket.id = NEW.replacement_ticket_id
    JOIN development_brain_retry_budget_lineage_v300 lineage
      ON lineage.predecessor_episode_id = predecessor.id
     AND lineage.successor_episode_id = replacement.id
    JOIN task_brain_request_receipt request
      ON request.task_id = NEW.task_id
     AND request.command_id = NEW.task_request_command_id
    JOIN stage owner ON owner.id = NEW.stage_id
    JOIN tasks task ON task.id = NEW.task_id
    JOIN threads trunk ON trunk.id = task.thread_id
    WHERE failure.id = NEW.failure_id
      AND failure.task_id = NEW.task_id
      AND failure.task_turn_id = NEW.predecessor_turn_id
      AND failure.blocker_id = NEW.blocker_id
      AND blocker.owner_kind = 'TASK'
      AND blocker.owner_id = NEW.task_id
      AND blocker.blocker_type = 'OPERATION_FAILED'
      AND blocker.status = 'OPEN'
      AND predecessor.status = 'FAILED'
      AND replacement.task_id = predecessor.task_id
      AND replacement.task_epoch = NEW.expected_task_epoch
      AND replacement.local_development_stage_id = NEW.stage_id
      AND replacement.stage_generation = NEW.stage_generation
      AND replacement.semantic_attempt = NEW.execution_attempt
      AND turn.id = NEW.replacement_turn_id
      AND turn.operation_id = NEW.replacement_operation_id
      AND turn.attempt = NEW.execution_attempt
      AND turn.status IN ('REQUESTED', 'QUEUED')
      AND turn.task_id = NEW.task_id
      AND turn.task_epoch = NEW.expected_task_epoch
      AND turn.trigger_stage_id = NEW.stage_id
      AND turn.trigger_stage_generation = NEW.stage_generation
      AND turn.expected_code_fingerprint = NEW.code_fingerprint
      AND turn.expected_head_sha = NEW.head_sha
      AND turn.expected_base_sha = NEW.base_sha
      AND turn.delivery_lane = failed.delivery_lane
      AND json_valid(turn.launch_input)
      AND json_type(turn.launch_input, '$.resumeSessionId') IS NULL
      AND json_type(turn.launch_input, '$.fallbackPrompt') IS NULL
      AND json_type(turn.launch_input,
          '$.priorCumulativeInputTokens') IS NULL
      AND json_type(turn.launch_input,
          '$.priorCumulativeOutputTokens') IS NULL
      AND instr(json_extract(turn.launch_input, '$.prompt'),
          COALESCE(json_extract(failed.launch_input, '$.fallbackPrompt'),
                   json_extract(failed.launch_input, '$.prompt'))) = 1
      AND instr(json_extract(turn.launch_input, '$.prompt'),
          'Retry instruction:') > 0
      AND json_extract(turn.launch_input, '$.transport') =
          json_extract(failed.launch_input, '$.transport')
      AND json_extract(turn.launch_input, '$.provider') =
          json_extract(failed.launch_input, '$.provider')
      AND json_extract(turn.launch_input, '$.model') =
          json_extract(failed.launch_input, '$.model')
      AND json_extract(turn.launch_input, '$.workingDirectory') =
          json_extract(failed.launch_input, '$.workingDirectory')
      AND json_extract(turn.launch_input,
          '$.toolEndpoint.ownerKind') = 'TASK_TURN'
      AND json_extract(turn.launch_input,
          '$.toolEndpoint.ownerId') = turn.id
      AND json_extract(turn.launch_input,
          '$.toolEndpoint.operationId') = turn.operation_id
      AND json_extract(turn.launch_input,
          '$.toolEndpoint.profile') = 'TASK_BRAIN_READ_ONLY'
      AND ticket.operation_id = turn.operation_id
      AND ticket.operation_kind = 'EXECUTE_TASK_TURN'
      AND ticket.async_family = 'AGENT_TURN'
      AND ticket.owner_kind = 'TASK_TURN'
      AND ticket.owner_id = turn.id
      AND ticket.callback_route = 'TASK_TURN_RESULT'
      AND ticket.lane_mask = failed_ticket.lane_mask
      AND ticket.trunk_control = 0
      AND ticket.exclusive_task = 1
      AND ticket.writer_required = 0
      AND ticket.workspace_id = trunk.workspace_id
      AND ticket.trunk_id = task.thread_id
      AND ticket.task_id = task.id
      AND ticket.task_epoch = NEW.expected_task_epoch
      AND ticket.stage_id = NEW.stage_id
      AND ticket.stage_generation = NEW.stage_generation
      AND ticket.attempt = NEW.execution_attempt
      AND ticket.expected_code_fingerprint = NEW.code_fingerprint
      AND ticket.expected_head_sha = NEW.head_sha
      AND ticket.expected_base_sha = NEW.base_sha
      AND ticket.status = 'REQUESTED'
      AND request.proof_id = replacement.id
      AND request.subject_operation_id = turn.operation_id
      AND request.returned_version = NEW.returned_task_version
      AND lineage.execution_attempt = NEW.execution_attempt
      AND lineage.budget_attempt = NEW.budget_attempt
      AND lineage.consumes_budget = 0
      AND owner.kind = 'LOCAL_DEVELOPMENT'
      AND owner.generation = NEW.stage_generation
      AND owner.version = NEW.stage_version
      AND owner.checkpoint = 'BRAIN_REVIEW'
      AND owner.completed_at_ms IS NULL)
BEGIN SELECT RAISE(ABORT, 'Brain protocol retry is not exact'); END;
CREATE TRIGGER development_brain_retry_immutable_v300
BEFORE UPDATE ON development_brain_retry_v300
BEGIN SELECT RAISE(ABORT, 'Brain protocol retry is immutable'); END;
CREATE TABLE ci_base_repair_manifest_v303 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    ci_repair_episode_id        TEXT    NOT NULL UNIQUE
        REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    failed_ci_evaluation_id     TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    remote_pr_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    subject_head_sha            TEXT    NOT NULL,
    subject_base_sha            TEXT    NOT NULL,
    subject_manifest_json       TEXT    NOT NULL CHECK (json_valid(subject_manifest_json)),
    manifest_digest             TEXT    NOT NULL CHECK (length(manifest_digest) = 64),
    created_at_ms               INTEGER NOT NULL
);
CREATE TRIGGER ci_base_repair_manifest_immutable_v303
BEFORE UPDATE ON ci_base_repair_manifest_v303
BEGIN SELECT RAISE(ABORT, 'Base repair manifest is immutable'); END;
CREATE TABLE ci_base_repair_authorization_v303 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    ci_repair_episode_id        TEXT    NOT NULL REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    manifest_id                 TEXT    NOT NULL REFERENCES ci_base_repair_manifest_v303(id),
    semantic_attempt            INTEGER NOT NULL CHECK (semantic_attempt > 0),
    authority_kind              TEXT    NOT NULL CHECK (authority_kind IN (
        'AUTO_APPROVE_POLICY', 'MANUAL')),
    automation_policy_id        TEXT    REFERENCES task_automation_policy(id),
    blocker_id                  TEXT    REFERENCES task_blocker(id),
    command_id                  TEXT    NOT NULL UNIQUE,
    actor                       TEXT,
    reason                      TEXT    NOT NULL,
    failed_ci_evaluation_id     TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    remote_pr_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    expected_worktree_head_sha  TEXT    NOT NULL,
    subject_head_sha            TEXT    NOT NULL,
    subject_base_sha            TEXT    NOT NULL,
    manifest_digest             TEXT    NOT NULL CHECK (length(manifest_digest) = 64),
    status                      TEXT    NOT NULL CHECK (status IN (
        'CLAIMED', 'CONSUMED', 'CLOSED')),
    claimed_at_ms               INTEGER NOT NULL,
    terminal_at_ms              INTEGER,
    terminal_evidence           TEXT,
    UNIQUE (ci_repair_episode_id, semantic_attempt),
    CHECK ((status = 'CLAIMED') = (terminal_at_ms IS NULL)),
    CHECK ((authority_kind = 'AUTO_APPROVE_POLICY'
            AND automation_policy_id IS NOT NULL
            AND blocker_id IS NULL AND actor IS NULL)
        OR (authority_kind = 'MANUAL'
            AND automation_policy_id IS NULL
            AND blocker_id IS NOT NULL AND actor IS NOT NULL))
);
CREATE TRIGGER ci_base_repair_authorization_insert_v303
BEFORE INSERT ON ci_base_repair_authorization_v303
WHEN NEW.status <> 'CLAIMED' OR NOT EXISTS (
    SELECT 1
    FROM ci_repair_episode episode
    JOIN ci_base_repair_manifest_v303 manifest
      ON manifest.id = NEW.manifest_id
    WHERE episode.id = NEW.ci_repair_episode_id
      AND episode.classification = 'BASE_DETERMINISTIC'
      AND episode.status = 'OPEN'
      AND episode.fix_attempt_count + 1 = NEW.semantic_attempt
      AND episode.failed_ci_evaluation_id = NEW.failed_ci_evaluation_id
      AND episode.subject_head_sha = NEW.subject_head_sha
      AND episode.subject_base_sha = NEW.subject_base_sha
      AND manifest.ci_repair_episode_id = episode.id
      AND manifest.failed_ci_evaluation_id = NEW.failed_ci_evaluation_id
      AND manifest.remote_pr_snapshot_id = NEW.remote_pr_snapshot_id
      AND manifest.subject_head_sha = NEW.subject_head_sha
      AND manifest.subject_base_sha = NEW.subject_base_sha
      AND manifest.manifest_digest = NEW.manifest_digest
      AND NOT EXISTS (
          SELECT 1 FROM ci_repair_operation operation
          WHERE operation.ci_repair_episode_id = episode.id
            AND operation.status IN ('REQUESTED', 'DISPATCHED'))
      AND ((NEW.authority_kind = 'AUTO_APPROVE_POLICY' AND EXISTS (
              SELECT 1 FROM task_automation_policy policy
              WHERE policy.id = NEW.automation_policy_id
                AND policy.task_id = episode.task_id
                AND policy.auto_approve = 1
                AND policy.stewardship_exception = 0
                AND policy.revision = (
                    SELECT MAX(latest.revision)
                    FROM task_automation_policy latest
                    WHERE latest.task_id = episode.task_id)))
        OR (NEW.authority_kind = 'MANUAL' AND EXISTS (
              SELECT 1 FROM task_blocker blocker
              WHERE blocker.id = NEW.blocker_id
                AND blocker.task_id = episode.task_id
                AND blocker.stage_id = episode.remote_development_stage_id
                AND blocker.owner_kind = 'EPISODE'
                AND blocker.owner_id = episode.id
                AND blocker.blocker_type = 'CI_BASE_REPAIR_REQUIRED'
                AND blocker.status = 'OPEN'))))
BEGIN SELECT RAISE(ABORT, 'Base repair authorization is not exact'); END;
CREATE TRIGGER ci_base_repair_authorization_identity_v303
BEFORE UPDATE OF id, ci_repair_episode_id, manifest_id, semantic_attempt,
        authority_kind, automation_policy_id, blocker_id, command_id, actor,
        reason, failed_ci_evaluation_id, remote_pr_snapshot_id,
        expected_worktree_head_sha, subject_head_sha, subject_base_sha,
        manifest_digest, claimed_at_ms
ON ci_base_repair_authorization_v303
BEGIN SELECT RAISE(ABORT, 'Base repair authorization identity is immutable'); END;
CREATE TRIGGER ci_base_repair_authorization_status_v303
BEFORE UPDATE OF status, terminal_at_ms, terminal_evidence
ON ci_base_repair_authorization_v303
WHEN OLD.status <> 'CLAIMED'
  OR NEW.status NOT IN ('CONSUMED', 'CLOSED')
  OR NEW.terminal_at_ms IS NULL
BEGIN SELECT RAISE(ABORT, 'Illegal base repair authorization transition'); END;
CREATE TRIGGER ci_repair_operation_base_authorization_v303
BEFORE INSERT ON ci_repair_operation
WHEN EXISTS (
        SELECT 1 FROM ci_repair_episode episode
        WHERE episode.id = NEW.ci_repair_episode_id
          AND episode.classification = 'BASE_DETERMINISTIC')
 AND (NEW.kind <> 'RERUN' AND NOT EXISTS (
        SELECT 1
        FROM ci_base_repair_authorization_v303 authorization
        WHERE authorization.id = NEW.base_repair_authorization_id
          AND authorization.ci_repair_episode_id = NEW.ci_repair_episode_id
          AND authorization.semantic_attempt = NEW.semantic_attempt
          AND authorization.status = 'CLAIMED'
          AND authorization.subject_base_sha = NEW.expected_base_sha
          AND (NEW.kind <> 'FIX_STAGE_TURN'
            OR authorization.expected_worktree_head_sha = NEW.expected_head_sha)))
BEGIN SELECT RAISE(ABORT, 'Base repair Operation lacks exact authorization'); END;
CREATE TRIGGER ci_repair_operation_base_identity_v303
BEFORE UPDATE OF base_repair_authorization_id, lease_expected_sha
ON ci_repair_operation
BEGIN SELECT RAISE(ABORT, 'Base repair Operation authority is immutable'); END;
CREATE TABLE ci_base_repair_rewrite_result_v303 (
    authorization_id            TEXT    NOT NULL PRIMARY KEY
        REFERENCES ci_base_repair_authorization_v303(id) ON DELETE CASCADE,
    ci_repair_operation_id      TEXT    NOT NULL UNIQUE REFERENCES ci_repair_operation(id),
    input_head_sha              TEXT    NOT NULL,
    output_head_sha             TEXT    NOT NULL,
    repair_commit_sha           TEXT    NOT NULL,
    original_commits_json       TEXT    NOT NULL CHECK (json_valid(original_commits_json)),
    proof_json                  TEXT    NOT NULL CHECK (json_valid(proof_json)),
    proof_digest                TEXT    NOT NULL CHECK (length(proof_digest) = 64),
    validation_outcome          TEXT    NOT NULL CHECK (validation_outcome IN (
        'PASSED', 'FAILED')),
    recorded_at_ms              INTEGER NOT NULL
);
CREATE TRIGGER ci_base_repair_rewrite_result_insert_v303
BEFORE INSERT ON ci_base_repair_rewrite_result_v303
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_base_repair_authorization_v303 authorization
    JOIN ci_repair_operation operation
      ON operation.id = NEW.ci_repair_operation_id
    WHERE authorization.id = NEW.authorization_id
      AND authorization.status = 'CLAIMED'
      AND operation.base_repair_authorization_id = authorization.id
      AND operation.ci_repair_episode_id = authorization.ci_repair_episode_id
      AND operation.kind = 'VALIDATE'
      AND operation.semantic_attempt = authorization.semantic_attempt
      AND operation.expected_head_sha = NEW.input_head_sha
      AND operation.result_head_sha = NEW.output_head_sha
      AND operation.status IN ('SUCCEEDED', 'FAILED'))
BEGIN SELECT RAISE(ABORT, 'Base repair rewrite result is not exact'); END;
CREATE TRIGGER ci_base_repair_rewrite_result_immutable_v303
BEFORE UPDATE ON ci_base_repair_rewrite_result_v303
BEGIN SELECT RAISE(ABORT, 'Base repair rewrite result is immutable'); END;
CREATE TABLE ci_base_repair_subject_v303 (
    id                          TEXT    NOT NULL PRIMARY KEY,
    task_id                     TEXT    NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    task_epoch                  INTEGER NOT NULL CHECK (task_epoch > 0),
    remote_development_stage_id TEXT    NOT NULL
        REFERENCES remote_development_stage(stage_id) ON DELETE CASCADE,
    stage_generation            INTEGER NOT NULL CHECK (stage_generation > 0),
    authorization_id            TEXT    NOT NULL UNIQUE
        REFERENCES ci_base_repair_authorization_v303(id) ON DELETE CASCADE,
    ci_repair_operation_id      TEXT    NOT NULL UNIQUE REFERENCES ci_repair_operation(id),
    code_fingerprint            TEXT    NOT NULL,
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    recorded_at_ms              INTEGER NOT NULL
);
CREATE TRIGGER ci_base_repair_subject_immutable_v303
BEFORE UPDATE ON ci_base_repair_subject_v303
BEGIN SELECT RAISE(ABORT, 'Base repair subject is immutable'); END;
CREATE TABLE ci_repair_episode_supersession_v303 (
    predecessor_episode_id      TEXT    NOT NULL PRIMARY KEY
        REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    successor_episode_id        TEXT    NOT NULL UNIQUE
        REFERENCES ci_repair_episode(id) ON DELETE CASCADE,
    predecessor_evaluation_id   TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    successor_evaluation_id     TEXT    NOT NULL REFERENCES remote_ci_evaluation(id),
    predecessor_snapshot_id     TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    successor_snapshot_id       TEXT    NOT NULL REFERENCES remote_pr_snapshot(id),
    head_sha                    TEXT    NOT NULL,
    base_sha                    TEXT    NOT NULL,
    provenance_digest           TEXT    NOT NULL CHECK (length(provenance_digest) = 64),
    superseded_at_ms            INTEGER NOT NULL
);
CREATE TRIGGER ci_repair_episode_supersession_insert_v303
BEFORE INSERT ON ci_repair_episode_supersession_v303
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_repair_episode predecessor
    JOIN ci_repair_episode successor
      ON successor.id = NEW.successor_episode_id
    JOIN remote_ci_evaluation predecessor_evaluation
      ON predecessor_evaluation.id = NEW.predecessor_evaluation_id
    JOIN remote_ci_evaluation successor_evaluation
      ON successor_evaluation.id = NEW.successor_evaluation_id
    WHERE predecessor.id = NEW.predecessor_episode_id
      AND predecessor.classification = 'UNKNOWN'
      AND predecessor.status = 'STOPPED'
      AND predecessor.failed_ci_evaluation_id = NEW.predecessor_evaluation_id
      AND successor.classification <> 'UNKNOWN'
      AND successor.status = 'OPEN'
      AND successor.failed_ci_evaluation_id = NEW.successor_evaluation_id
      AND predecessor.remote_development_stage_id =
          successor.remote_development_stage_id
      AND predecessor.task_id = successor.task_id
      AND predecessor.task_epoch = successor.task_epoch
      AND predecessor.stage_generation = successor.stage_generation
      AND predecessor.subject_head_sha = NEW.head_sha
      AND successor.subject_head_sha = NEW.head_sha
      AND predecessor.subject_base_sha = NEW.base_sha
      AND successor.subject_base_sha = NEW.base_sha
      AND predecessor.rerun_count = successor.rerun_count
      AND predecessor.rerun_limit = successor.rerun_limit
      AND predecessor.fix_attempt_count = successor.fix_attempt_count
      AND predecessor.fix_attempt_limit = successor.fix_attempt_limit
      AND predecessor.delivery_retry_count = successor.delivery_retry_count
      AND predecessor.delivery_retry_limit = successor.delivery_retry_limit
      AND predecessor.push_count = successor.push_count
      AND predecessor.push_limit = successor.push_limit
      AND predecessor_evaluation.remote_pr_snapshot_id =
          NEW.predecessor_snapshot_id
      AND successor_evaluation.remote_pr_snapshot_id =
          NEW.successor_snapshot_id
      AND NOT EXISTS (
          SELECT 1 FROM ci_repair_operation operation
          WHERE operation.ci_repair_episode_id = predecessor.id
            AND operation.status IN ('REQUESTED', 'DISPATCHED')))
BEGIN SELECT RAISE(ABORT, 'CI classification supersession is not exact'); END;
CREATE TRIGGER ci_repair_episode_supersession_immutable_v303
BEFORE UPDATE ON ci_repair_episode_supersession_v303
BEGIN SELECT RAISE(ABORT, 'CI classification supersession is immutable'); END;
CREATE VIEW task_current_code_subject_v230 AS
SELECT task.id AS task_id,
       COALESCE(current_local.code_fingerprint, remote.code_fingerprint,
                report.code_fingerprint, code.code_fingerprint) AS code_fingerprint,
       COALESCE(current_local.head_sha, remote.head_sha,
                report.head_sha, code.local_head_sha) AS head_sha,
       COALESCE(current_local.base_sha, remote.base_sha,
                report.base_sha, code.base_sha) AS base_sha
FROM tasks task
JOIN task_code_identity code ON code.task_id = task.id
LEFT JOIN dev_report report ON report.id = (
    SELECT candidate.id FROM dev_report candidate
    WHERE candidate.workflow_version = 'V2' AND candidate.task_id = task.id
    ORDER BY candidate.created_at_ms DESC, candidate.id DESC LIMIT 1)
LEFT JOIN remote_code_subject remote ON remote.id = (
    SELECT candidate.id FROM remote_code_subject candidate
    WHERE candidate.task_id = task.id AND candidate.task_epoch = task.epoch
    ORDER BY candidate.created_at_ms DESC, candidate.id DESC LIMIT 1)
LEFT JOIN (
    SELECT 'WORKTREE:' || id AS selector, task_id, task_epoch,
           code_fingerprint, head_sha, base_sha, recorded_at_ms
    FROM remote_worktree_subject
    UNION ALL
    SELECT 'STEERING:' || request_id, task_id, task_epoch,
           code_fingerprint, head_sha, base_sha, recorded_at_ms
    FROM remote_steering_code_subject_v257
    UNION ALL
    SELECT 'BASE_REPAIR:' || id, task_id, task_epoch,
           code_fingerprint, head_sha, base_sha, recorded_at_ms
    FROM ci_base_repair_subject_v303
) current_local ON current_local.selector = (
    SELECT candidate.selector FROM (
        SELECT 'WORKTREE:' || id AS selector, task_id, task_epoch,
               recorded_at_ms FROM remote_worktree_subject
        UNION ALL
        SELECT 'STEERING:' || request_id, task_id, task_epoch,
               recorded_at_ms FROM remote_steering_code_subject_v257
        UNION ALL
        SELECT 'BASE_REPAIR:' || id, task_id, task_epoch,
               recorded_at_ms FROM ci_base_repair_subject_v303
    ) candidate
    WHERE candidate.task_id = task.id AND candidate.task_epoch = task.epoch
    ORDER BY candidate.recorded_at_ms DESC, candidate.selector DESC LIMIT 1)
WHERE task.workflow_version = 'V2';
CREATE TRIGGER remote_pr_snapshot_ci_provenance_v304
BEFORE INSERT ON remote_pr_snapshot
WHEN NEW.ci_provenance_json IS NOT NULL
 AND (json_valid(NEW.ci_provenance_json) = 0
      OR COALESCE(json_type(
             NEW.ci_provenance_json, '$.schemaVersion'), '') <> 'integer'
      OR COALESCE(json_extract(
             NEW.ci_provenance_json, '$.schemaVersion'), -1) NOT IN (3, 4))
BEGIN SELECT RAISE(ABORT, 'Remote CI provenance is not schema v3 or v4'); END;
CREATE TRIGGER ci_base_repair_manifest_insert_v304
BEFORE INSERT ON ci_base_repair_manifest_v303
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_repair_episode episode
    JOIN remote_ci_evaluation evaluation
      ON evaluation.id = episode.failed_ci_evaluation_id
    JOIN remote_pr_snapshot snapshot
      ON snapshot.id = evaluation.remote_pr_snapshot_id
    WHERE episode.id = NEW.ci_repair_episode_id
      AND episode.classification = 'BASE_DETERMINISTIC'
      AND episode.failed_ci_evaluation_id = NEW.failed_ci_evaluation_id
      AND episode.subject_head_sha = NEW.subject_head_sha
      AND episode.subject_base_sha = NEW.subject_base_sha
      AND evaluation.remote_pr_snapshot_id = NEW.remote_pr_snapshot_id
      AND evaluation.head_sha = NEW.subject_head_sha
      AND evaluation.base_sha = NEW.subject_base_sha
      AND snapshot.head_sha = NEW.subject_head_sha
      AND snapshot.base_sha = NEW.subject_base_sha
      AND snapshot.ci_provenance_json IS NOT NULL
      AND json_valid(snapshot.ci_provenance_json)
      AND json_extract(snapshot.ci_provenance_json, '$.schemaVersion') IN (3, 4)
      AND json_extract(snapshot.ci_provenance_json, '$.complete') = 1)
BEGIN SELECT RAISE(ABORT, 'Base repair requires exact complete typed CI proof'); END;
CREATE TRIGGER ci_base_repair_subject_insert_v305
BEFORE INSERT ON ci_base_repair_subject_v303
WHEN NOT EXISTS (
    SELECT 1
    FROM ci_base_repair_rewrite_result_v303 rewrite
    JOIN ci_repair_operation operation
      ON operation.id = rewrite.ci_repair_operation_id
    WHERE rewrite.authorization_id = NEW.authorization_id
      AND rewrite.ci_repair_operation_id = NEW.ci_repair_operation_id
      AND rewrite.validation_outcome = 'PASSED'
      AND rewrite.output_head_sha = NEW.head_sha
      AND operation.task_id = NEW.task_id
      AND operation.task_epoch = NEW.task_epoch
      AND operation.remote_development_stage_id =
          NEW.remote_development_stage_id
      AND operation.stage_generation = NEW.stage_generation
      AND operation.status = 'SUCCEEDED'
      AND operation.result_code_fingerprint = NEW.code_fingerprint
      AND operation.expected_base_sha = NEW.base_sha)
BEGIN SELECT RAISE(ABORT, 'Base repair subject lacks passed rewrite proof'); END;
CREATE TRIGGER dispatch_ticket_ci_repair_insert
BEFORE INSERT ON dispatch_ticket
WHEN NEW.operation_kind IN (
        'RERUN_REMOTE_CI', 'VALIDATE_REMOTE_CI_REPAIR',
        'REWRITE_VALIDATE_REMOTE_CI_BASE_REPAIR',
        'PUSH_REMOTE_CI_REPAIR')
  OR NEW.callback_route IN (
        'REMOTE_CI_RERUN_RESULT', 'REMOTE_CI_STAGE_TURN_RESULT',
        'REMOTE_CI_VALIDATION_RESULT',
        'REMOTE_CI_BASE_REWRITE_VALIDATION_RESULT',
        'REMOTE_CI_BRAIN_RESULT', 'REMOTE_CI_PUSH_RESULT')
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM ci_repair_operation operation
        WHERE operation.operation_id = NEW.operation_id
          AND operation.task_id = NEW.task_id
          AND operation.task_epoch = NEW.task_epoch
          AND operation.remote_development_stage_id = NEW.stage_id
          AND operation.stage_generation = NEW.stage_generation
          AND operation.semantic_attempt = NEW.attempt
          AND operation.expected_code_fingerprint IS NEW.expected_code_fingerprint
          AND operation.expected_head_sha = NEW.expected_head_sha
          AND operation.expected_base_sha = NEW.expected_base_sha
          AND NEW.callback_route = CASE operation.kind
              WHEN 'RERUN' THEN 'REMOTE_CI_RERUN_RESULT'
              WHEN 'FIX_STAGE_TURN' THEN 'REMOTE_CI_STAGE_TURN_RESULT'
              WHEN 'VALIDATE' THEN CASE
                  WHEN operation.base_repair_authorization_id IS NULL
                      THEN 'REMOTE_CI_VALIDATION_RESULT'
                  ELSE 'REMOTE_CI_BASE_REWRITE_VALIDATION_RESULT' END
              WHEN 'BRAIN_REVIEW' THEN 'REMOTE_CI_BRAIN_RESULT'
              WHEN 'PUSH_HEAD' THEN 'REMOTE_CI_PUSH_RESULT' END
          AND NEW.operation_kind = CASE operation.kind
              WHEN 'RERUN' THEN 'RERUN_REMOTE_CI'
              WHEN 'FIX_STAGE_TURN' THEN 'EXECUTE_STAGE_TURN'
              WHEN 'VALIDATE' THEN CASE
                  WHEN operation.base_repair_authorization_id IS NULL
                      THEN 'VALIDATE_REMOTE_CI_REPAIR'
                  ELSE 'REWRITE_VALIDATE_REMOTE_CI_BASE_REPAIR' END
              WHEN 'BRAIN_REVIEW' THEN 'EXECUTE_TASK_TURN'
              WHEN 'PUSH_HEAD' THEN 'PUSH_REMOTE_CI_REPAIR' END
          AND NEW.async_family = CASE operation.kind
              WHEN 'RERUN' THEN 'GITHUB_EFFECT'
              WHEN 'FIX_STAGE_TURN' THEN 'AGENT_TURN'
              WHEN 'VALIDATE' THEN 'VALIDATION'
              WHEN 'BRAIN_REVIEW' THEN 'AGENT_TURN'
              WHEN 'PUSH_HEAD' THEN 'GITHUB_EFFECT' END
          AND NEW.owner_kind = CASE operation.kind
              WHEN 'FIX_STAGE_TURN' THEN 'STAGE_TURN'
              WHEN 'BRAIN_REVIEW' THEN 'TASK_TURN'
              ELSE 'STAGE' END
          AND NEW.owner_id = COALESCE(
              operation.stage_turn_id, operation.task_turn_id,
              operation.remote_development_stage_id)
          AND NEW.lane_mask = CASE operation.kind
              WHEN 'RERUN' THEN 32
              WHEN 'FIX_STAGE_TURN' THEN NEW.lane_mask
              WHEN 'VALIDATE' THEN 4
              WHEN 'BRAIN_REVIEW' THEN NEW.lane_mask
              WHEN 'PUSH_HEAD' THEN 48
              END
          AND (operation.kind NOT IN ('FIX_STAGE_TURN', 'BRAIN_REVIEW')
              OR NEW.lane_mask IN (1, 2))
          AND NEW.trunk_control = 0
          AND NEW.exclusive_task = CASE operation.kind
              WHEN 'RERUN' THEN 0 ELSE 1 END
          AND NEW.writer_required = CASE operation.kind
              WHEN 'FIX_STAGE_TURN' THEN 1
              WHEN 'VALIDATE' THEN CASE
                  WHEN operation.base_repair_authorization_id IS NULL
                      THEN 0 ELSE 1 END
              WHEN 'PUSH_HEAD' THEN 1
              ELSE 0 END
          AND NEW.status = 'REQUESTED')
    THEN RAISE(ABORT, 'CI repair DispatchTicket is not exact') END;
END;
CREATE TRIGGER remote_readiness_known_queue_capability_v307
BEFORE INSERT ON remote_readiness_evidence
WHEN NEW.ready = 1 AND NEW.merge_queue_capability = 'UNKNOWN'
BEGIN SELECT RAISE(ABORT,
    'Ready evidence requires known merge queue capability'); END;
CREATE TRIGGER remote_stage_runtime_known_queue_capability_v307
BEFORE INSERT ON remote_stage_runtime_receipt
WHEN NEW.cause = 'ACCEPT_REMOTE_READINESS'
  AND NOT EXISTS (
      SELECT 1 FROM remote_readiness_evidence readiness
      WHERE readiness.id = NEW.proof_id
        AND readiness.merge_queue_capability <> 'UNKNOWN')
BEGIN SELECT RAISE(ABORT,
    'Remote readiness transition requires known merge queue capability'); END;
CREATE TRIGGER remote_merge_authorization_known_queue_capability_v307
BEFORE INSERT ON remote_merge_authorization
WHEN NOT EXISTS (
    SELECT 1 FROM remote_readiness_evidence readiness
    WHERE readiness.id = NEW.readiness_evidence_id
      AND readiness.merge_queue_capability <> 'UNKNOWN')
BEGIN SELECT RAISE(ABORT,
    'Merge authorization requires known merge queue capability'); END;
CREATE TRIGGER v2_user_remote_action_insert_v270
BEFORE INSERT ON v2_user_remote_action_v270
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1
            FROM tasks task
            JOIN threads trunk ON trunk.id = task.thread_id
            JOIN remote_pr_binding binding
              ON binding.id = NEW.remote_pr_binding_id
            JOIN pr pull_request ON pull_request.id = NEW.pr_id
            JOIN remote_development_stage remote
              ON remote.stage_id = NEW.remote_stage_id
            JOIN stage owner ON owner.id = remote.stage_id
            JOIN remote_pr_snapshot snapshot
              ON snapshot.id = remote.accepted_snapshot_id
            WHERE task.id = NEW.task_id
              AND task.workflow_version = 'V2'
              AND task.epoch = NEW.task_epoch
              AND trunk.id = task.thread_id
              AND binding.task_id = task.id
              AND binding.pr_id = pull_request.id
              AND binding.remote_repository_id = NEW.remote_repository_id
              AND binding.head_repository_id = NEW.head_repository_id
              AND binding.remote_pr_number = NEW.remote_pr_number
              AND pull_request.task_id = task.id
              AND pull_request.origin = 'task'
              AND pull_request.repo = NEW.remote_repository_id
              AND pull_request.remote_pr_number = NEW.remote_pr_number
              AND pull_request.branch_name = NEW.branch_name
              AND remote.task_id = task.id
              AND remote.generation = NEW.stage_generation
              AND owner.task_id = task.id
              AND owner.kind = 'REMOTE_DEVELOPMENT'
              AND owner.generation = remote.generation
              AND snapshot.task_id = task.id
              AND snapshot.remote_development_stage_id = remote.stage_id
              AND snapshot.stage_generation = remote.generation
              AND snapshot.remote_pr_binding_id = binding.id
              AND snapshot.head_sha = NEW.expected_head_sha
              AND snapshot.base_sha = NEW.expected_base_sha
              AND remote.current_head_sha = NEW.expected_head_sha
              AND remote.current_base_sha = NEW.expected_base_sha)
            THEN RAISE(ABORT,
                'V2 user remote action lacks its exact Task/PR/Stage subject')
        WHEN NEW.kind NOT IN (
                'DELETE_REMOTE_BRANCH', 'POST_TOP_LEVEL_COMMENT')
          AND NOT EXISTS (
            SELECT 1
            FROM tasks task
            JOIN task_current_stage current ON current.task_id = task.id
            JOIN stage owner ON owner.id = current.stage_id
            JOIN remote_development_stage remote ON remote.stage_id = owner.id
            JOIN remote_pr_snapshot snapshot
              ON snapshot.id = remote.accepted_snapshot_id
            WHERE task.id = NEW.task_id
              AND task.lifecycle_state = 'ACTIVE'
              AND current.stage_id = NEW.remote_stage_id
              AND current.stage_generation = NEW.stage_generation
              AND owner.completed_at_ms IS NULL
              AND remote.current_head_sha = NEW.expected_head_sha
              AND remote.current_base_sha = NEW.expected_base_sha
              AND snapshot.pr_state IN ('OPEN', 'DRAFT'))
            THEN RAISE(ABORT,
                'V2 user remote action requires the current open Remote Stage')
        WHEN NEW.kind = 'POST_TOP_LEVEL_COMMENT' AND NOT EXISTS (
            SELECT 1
            FROM tasks task
            JOIN pr pull_request ON pull_request.id = NEW.pr_id
            JOIN remote_development_stage remote
              ON remote.stage_id = NEW.remote_stage_id
            JOIN stage owner ON owner.id = remote.stage_id
            JOIN remote_pr_snapshot snapshot
              ON snapshot.id = remote.accepted_snapshot_id
            LEFT JOIN task_current_stage current ON current.task_id = task.id
            WHERE task.id = NEW.task_id
              AND remote.task_id = task.id
              AND remote.generation = NEW.stage_generation
              AND remote.current_head_sha = NEW.expected_head_sha
              AND remote.current_base_sha = NEW.expected_base_sha
              AND snapshot.head_sha = NEW.expected_head_sha
              AND snapshot.base_sha = NEW.expected_base_sha
              AND (
                  (task.lifecycle_state = 'ACTIVE'
                    AND current.stage_id = NEW.remote_stage_id
                    AND current.stage_generation = NEW.stage_generation
                    AND owner.completed_at_ms IS NULL
                    AND snapshot.pr_state IN ('OPEN', 'DRAFT'))
                  OR
                  (pull_request.status IN ('merged', 'closed')
                    AND snapshot.pr_state = CASE pull_request.status
                        WHEN 'merged' THEN 'MERGED' ELSE 'CLOSED' END
                    AND NOT EXISTS (
                        SELECT 1
                        FROM remote_development_stage newer
                        WHERE newer.task_id = NEW.task_id
                          AND newer.generation > NEW.stage_generation))))
            THEN RAISE(ABORT,
                'V2 comment requires the current open or exact terminal PR')
        WHEN NEW.kind = 'DELETE_REMOTE_BRANCH' AND NOT EXISTS (
            SELECT 1
            FROM pr pull_request
            JOIN remote_development_stage remote
              ON remote.stage_id = NEW.remote_stage_id
            JOIN remote_pr_snapshot snapshot
              ON snapshot.id = remote.accepted_snapshot_id
            WHERE pull_request.id = NEW.pr_id
              AND pull_request.status = 'merged'
              AND snapshot.pr_state = 'MERGED'
              AND snapshot.head_sha = NEW.expected_head_sha
              AND snapshot.base_sha = NEW.expected_base_sha
              AND NOT EXISTS (
                  SELECT 1
                  FROM remote_development_stage newer
                  WHERE newer.task_id = NEW.task_id
                    AND newer.generation > NEW.stage_generation))
            THEN RAISE(ABORT,
                'V2 remote branch deletion requires preserved merged proof')
    END;
END;
